@dataclasses.dataclass(frozen=True)
class NetworkHostPolicy:
    """Allow-list HTTPS destinations and their credentialed redirects."""

    name: str
    allowed_hosts: frozenset[str]
    allowed_host_suffixes: frozenset[str] = frozenset()
    credentialed_redirect_hosts: frozenset[str] = frozenset()

    def validate(self, url: str) -> urllib.parse.SplitResult:
        try:
            parsed = urllib.parse.urlsplit(url)
            port = parsed.port
        except ValueError as exc:
            raise PrivacyError(f"{self.name} destination URL is invalid") from exc
        host = (parsed.hostname or "").lower().rstrip(".")
        if (
            parsed.scheme.lower() != "https"
            or not host
            or parsed.username is not None
            or parsed.password is not None
            or parsed.fragment
            or port not in {None, 443}
            or (
                host not in self.allowed_hosts
                and not any(
                    host == suffix or host.endswith(f".{suffix}")
                    for suffix in self.allowed_host_suffixes
                )
            )
        ):
            raise PrivacyError(f"{self.name} destination is not approved")
        return parsed


