def utc_now() -> str:
    return dt.datetime.now(dt.timezone.utc).isoformat().replace("+00:00", "Z")


def validate_rfc3339(value: Any, label: str) -> str:
    """Validate the bounded, timezone-aware timestamp used by network objects."""

    if not isinstance(value, str) or RFC3339_RE.fullmatch(value) is None:
        raise VerificationError(f"{label} is not an RFC 3339 timestamp")
    try:
        parsed = dt.datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError as exc:
        raise VerificationError(
            f"{label} is not an RFC 3339 timestamp"
        ) from exc
    if parsed.tzinfo is None or parsed.utcoffset() is None:
        raise VerificationError(f"{label} has no timezone")
    return value


def jcs_json_bytes(value: Any) -> bytes:
    """Encode the integer-only RFC 8785 domain used by immutable events."""
    try:
        return _protocol_jcs_json_bytes(value)
    except ProtocolValueError as exc:
        messages = {
            "integer_outside_ieee754_safe_range": (
                "hashed JCS integer is outside the IEEE-754 safe range"
            ),
            "floating_point_forbidden": (
                "floating-point values are forbidden in hashed JCS data"
            ),
            "non_string_object_key": (
                "hashed JCS object keys must be strings"
            ),
        }
        message = messages.get(
            exc.code,
            f"unsupported hashed JCS value: {exc.value_type}",
        )
        raise VerificationError(message) from exc


def sha256_jcs(value: Any) -> str:
    return sha256_bytes(jcs_json_bytes(value))


def pretty_json_bytes(value: Any) -> bytes:
    return (
        json.dumps(
            value,
            ensure_ascii=False,
            sort_keys=True,
            indent=2,
            allow_nan=False,
        )
        + "\n"
    ).encode("utf-8")


def git_blob_sha(value: bytes) -> str:
    header = f"blob {len(value)}\0".encode("ascii")
    return hashlib.sha1(header + value).hexdigest()


def _safe_chmod(path: Path, mode: int) -> None:
    with contextlib.suppress(OSError, NotImplementedError):
        path.chmod(mode)


def ensure_private_dir(path: Path) -> None:
    path.mkdir(parents=True, exist_ok=True)
    _safe_chmod(path, 0o700)


def atomic_write_bytes(path: Path, value: bytes, mode: int = 0o600) -> None:
    ensure_private_dir(path.parent)
    fd, temporary_name = tempfile.mkstemp(
        prefix=f".{path.name}.",
        suffix=".tmp",
        dir=str(path.parent),
    )
    temporary = Path(temporary_name)
    try:
        with os.fdopen(fd, "wb") as stream:
            stream.write(value)
            stream.flush()
            os.fsync(stream.fileno())
        _safe_chmod(temporary, mode)
        os.replace(temporary, path)
        _safe_chmod(path, mode)
        if hasattr(os, "O_DIRECTORY"):
            directory_fd = os.open(path.parent, os.O_RDONLY | os.O_DIRECTORY)
            try:
                os.fsync(directory_fd)
            finally:
                os.close(directory_fd)
    finally:
        with contextlib.suppress(FileNotFoundError):
            temporary.unlink()


def atomic_write_json(path: Path, value: Any) -> None:
    atomic_write_bytes(path, pretty_json_bytes(value))


def load_json(path: Path) -> Any:
    raw = path.read_bytes()
    if raw.startswith(b"\xef\xbb\xbf"):
        raise PrivacyError(f"UTF-8 BOM is forbidden: {path.name}")
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise PrivacyError(f"invalid UTF-8: {path.name}") from exc
    try:
        return strict_json_loads(text)
    except (ValueError, json.JSONDecodeError) as exc:
        raise ConfigurationError(f"invalid JSON in {path.name}: {exc}") from exc


def validate_identifier(value: Any, label: str) -> str:
    if not isinstance(value, str) or not ID_RE.fullmatch(value):
        raise PrivacyError(
            f"{label} must match ^[a-z0-9][a-z0-9_-]{{1,63}}$"
        )
    lowered_base = value.rstrip(" .").split(".", 1)[0].lower()
    if lowered_base in WINDOWS_RESERVED or value.endswith((" ", ".")):
        raise PrivacyError(f"{label} is not portable to Windows")
    if value in {".", ".."}:
        raise PrivacyError(f"{label} contains a relative path segment")
    return value


def validate_sha256(value: Any, label: str) -> str:
    if (
        not isinstance(value, str)
        or not SHA256_RE.fullmatch(value)
        or value == "0" * 64
    ):
        raise PrivacyError(f"{label} is not a SHA-256 value")
    return value


def validate_git_sha(value: Any, label: str) -> str:
    if (
        not isinstance(value, str)
        or not GIT_SHA_RE.fullmatch(value)
        or value in {"0" * 40, "0" * 64}
    ):
        raise PrivacyError(f"{label} is not a Git object ID")
    return value


def validate_repo_path(value: Any, label: str = "repository path") -> str:
    if not isinstance(value, str) or not value or len(value) > 512:
        raise PrivacyError(f"{label} is invalid")
    if value != unicodedata.normalize("NFC", value):
        raise PrivacyError(f"{label} must be Unicode NFC")
    if "\\" in value or value.startswith("/") or re.match(r"^[A-Za-z]:", value):
        raise PrivacyError(f"{label} must be a relative POSIX path")
    path = PurePosixPath(value)
    if any(part in {"", ".", ".."} for part in path.parts):
        raise PrivacyError(f"{label} contains an unsafe segment")
    for part in path.parts:
        if any(character in part for character in '<>:"|?*'):
            raise PrivacyError(f"{label} contains a cross-platform unsafe character")
        if part.endswith((" ", ".")):
            raise PrivacyError(f"{label} is not portable to Windows")
        if part.split(".", 1)[0].lower() in WINDOWS_RESERVED:
            raise PrivacyError(f"{label} uses a Windows reserved name")
    return path.as_posix()


def _is_reparse_point(path: Path) -> bool:
    try:
        result = path.lstat()
    except OSError:
        return True
    attributes = getattr(result, "st_file_attributes", 0)
    reparse_flag = getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0x400)
    return bool(attributes & reparse_flag)


def assert_plain_path(path: Path, *, require_file: bool | None = None) -> None:
    if path.is_symlink() or _is_reparse_point(path):
        raise PrivacyError(f"symbolic links and reparse points are forbidden: {path.name}")
    if require_file is True and not path.is_file():
        raise IdentityError(f"required file is missing: {path.name}")
    if require_file is False and not path.is_dir():
        raise IdentityError(f"required directory is missing: {path.name}")


def assert_plain_directory_chain(root: Path, leaf: Path) -> None:
    """Require every existing component from ``root`` through ``leaf`` plain.

    This is a narrow local-state guard, not a replacement for platform ACL
    policy. It prevents a linked/reparse parent from redirecting bounded reads
    or atomic rewrites outside the configured private data directory.
    """

    root_path = Path(os.path.abspath(os.fspath(root)))
    leaf_path = Path(os.path.abspath(os.fspath(leaf)))
    try:
        relative = leaf_path.relative_to(root_path)
    except ValueError as exc:
        raise PrivacyError("private directory escaped its configured root") from exc
    chain = [root_path]
    current = root_path
    for component in relative.parts:
        current = current / component
        chain.append(current)
    for directory in chain:
        try:
            named = directory.lstat()
        except OSError as exc:
            raise IdentityError(
                f"required private directory is missing: {directory.name}"
            ) from exc
        if (
            not stat.S_ISDIR(named.st_mode)
            or stat.S_ISLNK(named.st_mode)
            or _is_reparse_point(directory)
        ):
            raise PrivacyError(
                f"private directory links are forbidden: {directory.name}"
            )
        flags = (
            os.O_RDONLY
            | getattr(os, "O_DIRECTORY", 0)
            | getattr(os, "O_NOFOLLOW", 0)
            | getattr(os, "O_NOINHERIT", 0)
        )
        try:
            descriptor = os.open(directory, flags)
            opened = os.fstat(descriptor)
            named_after = directory.lstat()
        except OSError as exc:
            raise PrivacyError(
                f"private directory could not be opened safely: {directory.name}"
            ) from exc
        finally:
            if "descriptor" in locals():
                os.close(descriptor)
                del descriptor
        if (
            not stat.S_ISDIR(opened.st_mode)
            or not _stable_file_observations_match(
                named, opened, cross_interface=True
            )
            or not _stable_file_observations_match(
                opened, named_after, cross_interface=True
            )
        ):
            raise PrivacyError(
                f"private directory changed during verification: {directory.name}"
            )


def _mapping_only_yaml(text: str) -> Mapping[str, Any]:
    """Parse the small nested-mapping subset used by portable identity files."""

    if text.lstrip().startswith("{"):
        value = strict_json_loads(text)
        if not isinstance(value, Mapping):
            raise IdentityError("portable identity must be an object")
        return value

    lines: list[tuple[int, str, str]] = []
    for number, raw in enumerate(text.splitlines(), 1):
        if not raw.strip() or raw.lstrip().startswith("#"):
            continue
        if "\t" in raw[: len(raw) - len(raw.lstrip())]:
            raise IdentityError(f"identity line {number} uses a tab")
        indent = len(raw) - len(raw.lstrip(" "))
        content = raw.strip()
        if ":" not in content:
            raise IdentityError(f"identity line {number} is not a mapping")
        key, raw_value = content.split(":", 1)
        key = key.strip()
        if not key or not re.fullmatch(r"[A-Za-z0-9_-]+", key):
            raise IdentityError(f"identity line {number} has an unsafe key")
        lines.append((indent, key, raw_value.strip()))

    root: dict[str, Any] = {}
    stack: list[tuple[int, MutableMapping[str, Any]]] = [(-1, root)]
    for indent, key, raw_value in lines:
        while stack and indent <= stack[-1][0]:
            stack.pop()
        if not stack:
            raise IdentityError("identity indentation is inconsistent")
        parent = stack[-1][1]
        if key in parent:
            raise IdentityError(f"duplicate identity key: {key}")
        if not raw_value:
            child: dict[str, Any] = {}
            parent[key] = child
            stack.append((indent, child))
            continue
        lowered = raw_value.lower()
        if lowered in {"null", "~"}:
            parsed: Any = None
        elif lowered == "true":
            parsed = True
        elif lowered == "false":
            parsed = False
        elif raw_value.startswith(('"', "'")):
            if raw_value[0] == '"':
                parsed = strict_json_loads(raw_value)
            elif raw_value.endswith("'"):
                parsed = raw_value[1:-1].replace("''", "'")
            else:
                raise IdentityError("unterminated identity string")
        elif re.fullmatch(r"-?(?:0|[1-9]\d*)", raw_value):
            parsed = int(raw_value)
        else:
            if any(character in raw_value for character in "[]{}&*!"):
                raise IdentityError("unsupported identity YAML feature")
            parsed = raw_value.split(" #", 1)[0].strip()
        parent[key] = parsed
    return root


@dataclasses.dataclass(frozen=True)
class PortableIdentity:
    path: Path
    workspace_root: Path
    binding_id: str
    task_id: str
    lineage_id: str
    base: Mapping[str, Any]


@dataclasses.dataclass(frozen=True)
class SourceIdentity:
    """Conversation-only identity resolved from an existing vault source.

    This identity never grants access to local files.  It only authorizes
    visible conversation checkpoints through an exact, confirmed
    ``source -> source_for -> primary`` binding.
    """

    binding_id: str
    task_id: str
    source_id: str
    external_source_key_sha256: str


@dataclasses.dataclass(frozen=True)
class SourceRoute:
    """One confirmed primary source route and its audit lineage."""

    path: str
    binding_id: str
    task_id: str
    source_sequence_from: int
    source_sequence_to: int | None
    supersedes_binding_id: str | None
    document: Mapping[str, Any]


TaskIdentity = PortableIdentity | SourceIdentity


def _parse_identity_value(
    value: Mapping[str, Any], path: Path
) -> PortableIdentity:
    expected = {
        "schema_version",
        "vault_id",
        "binding_id",
        "semantic_task_id",
        "workspace_lineage_id",
        "binding_state",
        "base",
    }
    if set(value) != expected:
        raise IdentityError("portable identity fields do not match the v1 schema")
    if value.get("schema_version") != "portable-workspace-identity/v1":
        raise IdentityError("unsupported portable identity schema")
    if value.get("vault_id") != VAULT_ID or value.get("binding_state") != "confirmed":
        raise IdentityError("portable identity is not confirmed for this vault")
    base = value.get("base")
    if not isinstance(base, Mapping) or set(base) != {
        "snapshot_id",
        "manifest_sha256",
        "current_blob_sha",
        "transaction_id",
    }:
        raise IdentityError("portable identity base is incomplete")
    for key in ("snapshot_id", "transaction_id"):
        if base.get(key) is not None:
            validate_identifier(base[key], f"base.{key}")
    if base.get("manifest_sha256") is not None:
        validate_sha256(base["manifest_sha256"], "base.manifest_sha256")
    if base.get("current_blob_sha") is not None:
        validate_git_sha(base["current_blob_sha"], "base.current_blob_sha")
    return PortableIdentity(
        path=path,
        workspace_root=path.parent,
        binding_id=validate_identifier(value.get("binding_id"), "binding_id"),
        task_id=validate_identifier(value.get("semantic_task_id"), "semantic_task_id"),
        lineage_id=validate_identifier(
            value.get("workspace_lineage_id"), "workspace_lineage_id"
        ),
        base=base,
    )


def parse_identity(path: Path) -> PortableIdentity:
    assert_plain_path(path, require_file=True)
    raw = path.read_bytes()
    if raw.startswith(b"\xef\xbb\xbf"):
        raise IdentityError("portable identity must be UTF-8 without BOM")
    try:
        value = _mapping_only_yaml(raw.decode("utf-8"))
    except (UnicodeDecodeError, ValueError) as exc:
        raise IdentityError(
            "portable identity is not valid UTF-8 structured data"
        ) from exc
    return _parse_identity_value(value, path)


def parse_identity_set(
    path: Path, task_id: str | None = None
) -> PortableIdentity:
    assert_plain_path(path, require_file=True)
    raw = path.read_bytes()
    if raw.startswith(b"\xef\xbb\xbf"):
        raise IdentityError("portable identity set must be UTF-8 without BOM")
    try:
        value = strict_json_loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, ValueError) as exc:
        raise IdentityError("portable identity set is not valid UTF-8 JSON") from exc
    if (
        not isinstance(value, Mapping)
        or set(value) != {"schema_version", "vault_id", "identities"}
        or value.get("schema_version") != "portable-workspace-set/v1"
        or value.get("vault_id") != VAULT_ID
    ):
        raise IdentityError("portable identity set fields do not match the v1 schema")
    raw_identities = value.get("identities")
    if not isinstance(raw_identities, list) or not raw_identities:
        raise IdentityError("portable identity set must contain identities")
    identities: list[PortableIdentity] = []
    seen: set[str] = set()
    for raw_identity in raw_identities:
        if not isinstance(raw_identity, Mapping):
            raise IdentityError("portable identity set contains an invalid identity")
        identity = _parse_identity_value(raw_identity, path)
        if identity.task_id in seen:
            raise IdentityError("portable identity set contains a duplicate task")
        seen.add(identity.task_id)
        identities.append(identity)
    if task_id is None:
        if len(identities) != 1:
            raise UnboundIdentityError(
                "multi-task workspace requires an exact confirmed task route"
            )
        return identities[0]
    validated_task = validate_identifier(task_id, "task_id")
    matches = [
        identity for identity in identities if identity.task_id == validated_task
    ]
    if len(matches) != 1:
        raise UnboundIdentityError(
            "multi-task workspace has no identity for the confirmed task route"
        )
    return matches[0]


def _path_is_within(path: Path, root: Path) -> bool:
    try:
        path.relative_to(root)
    except ValueError:
        return False
    return True


def resolve_workspace(
    cwd: Path,
    allowed_roots: Sequence[str],
    *,
    task_id: str | None = None,
) -> PortableIdentity:
    try:
        resolved_cwd = cwd.resolve(strict=True)
    except OSError as exc:
        raise IdentityError("working directory cannot be resolved") from exc
    assert_plain_path(resolved_cwd, require_file=False)

    roots: list[Path] = []
    for raw_root in allowed_roots:
        if not isinstance(raw_root, str) or not os.path.isabs(raw_root):
            raise ConfigurationError("privacy.allowed_roots must be absolute paths")
        root = Path(raw_root).resolve(strict=True)
        assert_plain_path(root, require_file=False)
        roots.append(root)
    matching = [root for root in roots if _path_is_within(resolved_cwd, root)]
    if not matching:
        raise UnboundIdentityError(
            "working directory is not inside an allowed root"
        )
    boundary = max(matching, key=lambda item: len(item.parts))
    cursor = resolved_cwd
    while True:
        marker = cursor / ".vault_identity.yaml"
        marker_set = cursor / ".vault_identities.json"
        if marker.exists() and marker_set.exists():
            raise IdentityError("workspace contains conflicting portable identity files")
        if marker.exists():
            identity = parse_identity(marker)
            if task_id is not None and identity.task_id != task_id:
                raise IdentityError(
                    "workspace identity conflicts with the confirmed task route"
                )
            if not _path_is_within(identity.workspace_root, boundary):
                raise IdentityError("portable identity escapes the allowed root")
            return identity
        if marker_set.exists():
            identity = parse_identity_set(marker_set, task_id=task_id)
            if not _path_is_within(identity.workspace_root, boundary):
                raise IdentityError("portable identity set escapes the allowed root")
            return identity
        if cursor == boundary:
            break
        cursor = cursor.parent
    raise UnboundIdentityError("no confirmed .vault_identity.yaml was found")


def _routing_workspace_identity_fingerprint(
    cwd: Path,
    allowed_roots: Sequence[str],
) -> str | None:
    """Return a stable identity-marker fingerprint for routing races.

    A valid multi-task marker is intentionally accepted here even though it
    cannot resolve one exact workspace identity without a confirmed task
    route. Invalid or conflicting markers are hashed as opaque artifact-policy
    blockers: they cannot grant artifact authority, but their exact state is
    still locked so conversation-only content matching can proceed safely.
    """

    try:
        resolved_cwd = cwd.resolve(strict=True)
    except OSError as exc:
        raise IdentityError("working directory cannot be resolved") from exc
    assert_plain_path(resolved_cwd, require_file=False)
    roots: list[Path] = []
    for raw_root in allowed_roots:
        if not isinstance(raw_root, str) or not os.path.isabs(raw_root):
            raise ConfigurationError("privacy.allowed_roots must be absolute paths")
        try:
            root = Path(raw_root).resolve(strict=True)
        except OSError as exc:
            raise ConfigurationError(
                "privacy.allowed_roots contains an unavailable directory"
            ) from exc
        assert_plain_path(root, require_file=False)
        if _path_is_within(resolved_cwd, root):
            roots.append(root)
    if not roots:
        return None
    boundary = max(roots, key=lambda item: len(item.parts))
    cursor = resolved_cwd

    def stable_marker_digest(
        path: Path,
        *,
        multiple: bool,
    ) -> tuple[str, int, bool]:
        assert_plain_path(path, require_file=True)
        if path.stat().st_size > MAX_CODEX_JSON_BYTES:
            raise IdentityError(
                "portable workspace identity exceeds the safety limit"
            )
        structurally_valid = True
        try:
            if multiple:
                try:
                    parse_identity_set(path)
                except UnboundIdentityError:
                    # The set is structurally valid but needs a confirmed task
                    # route before one member can become workspace authority.
                    pass
            else:
                parse_identity(path)
        except IdentityError:
            structurally_valid = False
        observations: list[tuple[str, int]] = []
        for _attempt in range(2):
            observations.append(_hash_plain_file(path))
        if observations[0] != observations[1]:
            raise BusyError(
                "portable workspace identity changed during task matching"
            )
        return (*observations[1], structurally_valid)

    while True:
        single = cursor / ".vault_identity.yaml"
        multiple = cursor / ".vault_identities.json"
        if single.exists() and multiple.exists():
            single_digest, single_size, _single_valid = (
                stable_marker_digest(single, multiple=False)
            )
            multiple_digest, multiple_size, _multiple_valid = (
                stable_marker_digest(multiple, multiple=True)
            )
            return sha256_bytes(
                canonical_json_bytes(
                    {
                        "kind": "conflicting_artifact_markers",
                        "single": {
                            "path": single.relative_to(boundary).as_posix(),
                            "sha256": single_digest,
                            "size": single_size,
                        },
                        "multiple": {
                            "path": multiple.relative_to(boundary).as_posix(),
                            "sha256": multiple_digest,
                            "size": multiple_size,
                        },
                    }
                )
            )
        if single.exists():
            digest, size, structurally_valid = stable_marker_digest(
                single,
                multiple=False,
            )
            marker_kind = (
                "single" if structurally_valid else "invalid_single"
            )
            marker_path = single
        elif multiple.exists():
            digest, size, structurally_valid = stable_marker_digest(
                multiple,
                multiple=True,
            )
            marker_kind = (
                "multiple" if structurally_valid else "invalid_multiple"
            )
            marker_path = multiple
        else:
            if cursor == boundary:
                return None
            cursor = cursor.parent
            continue
        relative_marker = marker_path.relative_to(boundary).as_posix()
        return sha256_bytes(
            canonical_json_bytes(
                {
                    "kind": marker_kind,
                    "path": relative_marker,
                    "sha256": digest,
                    "size": size,
                }
            )
        )


def _codex_home() -> Path:
    provided = os.environ.get("CODEX_HOME")
    if provided:
        path = Path(provided).expanduser()
        if not path.is_absolute():
            raise ConfigurationError("CODEX_HOME must be an absolute path")
        return path.resolve()
    return (Path.home() / ".codex").resolve()


def _managed_plugin_data_dir() -> Path:
    return (
        _codex_home()
        / "plugins"
        / "data"
        / f"{PLUGIN_NAME}-{MARKETPLACE_NAME}"
    )


def _is_managed_plugin_data_dir(path: Path) -> bool:
    return path.expanduser().resolve() == _managed_plugin_data_dir()


def default_data_dir() -> Path:
    provided = os.environ.get("PLUGIN_DATA")
    if provided:
        return Path(provided).expanduser().resolve()
    return _managed_plugin_data_dir()


def _json_clone(value: Any) -> Any:
    return strict_json_loads(
        json.dumps(value, ensure_ascii=False, allow_nan=False)
    )


def _provider_scope_fingerprint(
    *,
    kind: str,
    driver: str,
    adapter_config: Mapping[str, Any],
) -> str:
    if kind == "control_plane" and driver in {"git-https", "git-local-test"}:
        scope = {
            "repo_url": adapter_config.get("repo_url"),
            "branch": adapter_config.get("branch"),
        }
    elif kind == "object_store" and driver == "google-drive-v3":
        scope = {
            "root_folder_id": adapter_config.get("root_folder_id"),
        }
    elif kind == "object_store" and driver == "filesystem-test":
        scope = {
            "root": adapter_config.get("root"),
        }
    elif kind == "object_store" and driver == RCLONE_OBJECT_STORE_DRIVER:
        # Device-local executable/config paths are deliberately excluded. A
        # transaction is pinned to the credential-free encrypted destination
        # identity and can therefore remain portable across operating systems.
        scope = {
            "remote_name": adapter_config.get("remote_name"),
            "remote_fingerprint": adapter_config.get(
                "remote_fingerprint"
            ),
        }
    else:
        raise ConfigurationError("unsupported provider scope fingerprint driver")
    return sha256_bytes(
        canonical_json_bytes(
            {
                "kind": kind,
                "driver": driver,
                "scope": scope,
            }
        )
    )


def _default_provider_config() -> dict[str, Any]:
    control_adapter = {
        "repo_url": DEPLOYMENT_DEFAULT_REPO_URL,
        "branch": "main",
        "privacy_verifier": DEPLOYMENT_CONTROL_PRIVACY_VERIFIER,
        "expected_repository": EXPECTED_MARKETPLACE_REPOSITORY,
    }
    object_adapter = {
        "root_folder_id": None,
        "oauth_client_id": None,
    }
    return {
        "schema_version": PROVIDER_CONFIG_SCHEMA,
        "active_profile_id": DEFAULT_PROVIDER_PROFILE_ID,
        "profiles": [
            {
                "profile_id": DEFAULT_PROVIDER_PROFILE_ID,
                "status": "active",
                "control_plane": {
                    "driver": "git-https",
                    "adapter_config_ref": DEFAULT_CONTROL_ADAPTER_REF,
                    "credential_ref": DEFAULT_CONTROL_CREDENTIAL_REF,
                    "scope_fingerprint": _provider_scope_fingerprint(
                        kind="control_plane",
                        driver="git-https",
                        adapter_config=control_adapter,
                    ),
                    "access": "read_write",
                },
                "object_stores": [
                    {
                        "store_id": DEFAULT_OBJECT_STORE_ID,
                        "driver": "google-drive-v3",
                        "adapter_config_ref": DEFAULT_OBJECT_ADAPTER_REF,
                        "credential_ref": DEFAULT_OBJECT_CREDENTIAL_REF,
                        "scope_fingerprint": _provider_scope_fingerprint(
                            kind="object_store",
                            driver="google-drive-v3",
                            adapter_config=object_adapter,
                        ),
                        "role": "primary",
                        "access": "read_write",
                    }
                ],
            }
        ],
        "protocol_guards": {
            "object_write_before_control_plane": True,
            "current_compare_and_swap": True,
            "preserve_provider_pins": True,
            "retired_stores_read_only": True,
        },
    }


def default_config() -> dict[str, Any]:
    return {
        "schema_version": CONFIG_SCHEMA,
        "vault_id": VAULT_ID,
        "enabled": True,
        "providers": _default_provider_config(),
        "adapter_configs": {
            DEFAULT_CONTROL_ADAPTER_REF: {
                "repo_url": DEPLOYMENT_DEFAULT_REPO_URL,
                "branch": "main",
                "privacy_verifier": DEPLOYMENT_CONTROL_PRIVACY_VERIFIER,
                "expected_repository": EXPECTED_MARKETPLACE_REPOSITORY,
            },
            DEFAULT_OBJECT_ADAPTER_REF: {
                "root_folder_id": None,
                "oauth_client_id": None,
            },
        },
        "credential_bindings": {
            DEFAULT_CONTROL_CREDENTIAL_REF: {
                "helper_host": DEPLOYMENT_CONTROL_CREDENTIAL_HOST,
            },
            DEFAULT_OBJECT_CREDENTIAL_REF: {
                "helper_host": "google-drive.memory-vault-sync.local",
            },
        },
        "sync": {
            # Memory is always a taskless, append-only network.  There is no
            # product switch back to task ownership or conversation binding.
            "associative_recall_enabled": True,
            "memory_recall_limit": DEFAULT_MEMORY_RECALL_LIMIT,
            "memory_recall_context_bytes": (
                DEFAULT_MEMORY_RECALL_CONTEXT_BYTES
            ),
            "startup_pull": True,
            "pull_artifacts": True,
            "stop_publish": True,
            "conversation_backup": True,
            "artifact_mode": "declared-only",
            "max_auto_pull_bytes": 512 * 1024 * 1024,
            # Keep the Stop hook responsive. Larger immutable artifacts stay
            # safely queued and are uploaded by an explicit `flush` window.
            "max_stop_upload_bytes": DEFAULT_MAX_STOP_UPLOAD_BYTES,
            # Distinct content-addressed objects can transfer concurrently.
            # The hard ceiling protects provider quotas and hook responsiveness.
            "max_parallel_artifact_uploads": (
                DEFAULT_MAX_PARALLEL_ARTIFACT_UPLOADS
            ),
            # Chunking is an explicit, reversible rclone/crypt optimization.
            # Historical chunked objects remain readable when this is false.
            "chunked_artifacts_enabled": False,
            "chunked_artifact_min_bytes": DEFAULT_CHUNK_MINIMUM_BYTES,
            "max_files_per_turn": 128,
            "max_total_bytes_per_turn": 2 * 1024 * 1024 * 1024,
        },
        "updates": {
            "enabled": True,
            "auto_install": True,
            "check_interval_seconds": DEFAULT_UPDATE_INTERVAL_SECONDS,
            "codex_executable": None,
        },
        "privacy": {
            "allowed_roots": [],
            "reject_symlinks": True,
            "parse_transcript_path": False,
            "store_raw_hook_input": False,
        },
    }


def _migrate_config_v1_to_v2(value: Mapping[str, Any]) -> dict[str, Any]:
    legacy = _json_clone(value)
    if not isinstance(legacy, dict):
        raise ConfigurationError("legacy config is invalid")
    vault = legacy.get("vault")
    drive = legacy.get("drive")
    if not isinstance(vault, Mapping) or not isinstance(drive, Mapping):
        raise ConfigurationError("legacy config has no vault or drive section")
    if vault.get("vault_id") != VAULT_ID:
        raise ConfigurationError("legacy config vault_id does not match this plugin")
    migrated = default_config()
    for key in (
        "enabled",
        "sync",
        "projection",
        "matching",
        "updates",
        "privacy",
        "_test_mode",
    ):
        if key in legacy:
            migrated[key] = _json_clone(legacy[key])
    control_driver = (
        "git-local-test"
        if (
            legacy.get("_test_mode") is True
            and not GITHUB_REPO_RE.fullmatch(str(vault.get("repo_url", "")))
        )
        else "git-https"
    )
    object_driver = str(drive.get("backend") or "google-drive-v3")
    control_adapter = {
        "repo_url": vault.get("repo_url"),
        "branch": vault.get("branch"),
        "privacy_verifier": (
            "test-local-v1"
            if control_driver == "git-local-test"
            else "github-private-v1"
        ),
        "expected_repository": vault.get("expected_github_repository"),
    }
    object_adapter = {
        key: drive.get(key)
        for key in ("root_folder_id", "oauth_client_id", "root")
        if key in drive
    }
    migrated["adapter_configs"] = {
        DEFAULT_CONTROL_ADAPTER_REF: control_adapter,
        DEFAULT_OBJECT_ADAPTER_REF: object_adapter,
    }
    migrated["credential_bindings"] = {
        DEFAULT_CONTROL_CREDENTIAL_REF: {
            "helper_host": (
                vault.get("github_privacy_credential_host") or "github.com"
            ),
        },
        DEFAULT_OBJECT_CREDENTIAL_REF: {
            "helper_host": (
                drive.get("credential_host")
                or "google-drive.memory-vault-sync.local"
            ),
        },
    }
    providers = _default_provider_config()
    profile = providers["profiles"][0]
    profile["control_plane"].update(
        {
            "driver": control_driver,
            "scope_fingerprint": _provider_scope_fingerprint(
                kind="control_plane",
                driver=control_driver,
                adapter_config=control_adapter,
            ),
        }
    )
    store = profile["object_stores"][0]
    store.update(
        {
            "driver": object_driver,
            "scope_fingerprint": _provider_scope_fingerprint(
                kind="object_store",
                driver=object_driver,
                adapter_config=object_adapter,
            ),
        }
    )
    migrated["providers"] = providers
    return migrated


def _provider_profile(config: Mapping[str, Any]) -> Mapping[str, Any]:
    providers = config.get("providers")
    if not isinstance(providers, Mapping):
        raise ConfigurationError("config.providers must be an object")
    active = validate_identifier(
        providers.get("active_profile_id"),
        "providers.active_profile_id",
    )
    profiles = providers.get("profiles")
    if not isinstance(profiles, list):
        raise ConfigurationError("providers.profiles must be an array")
    matches = [
        item
        for item in profiles
        if isinstance(item, Mapping) and item.get("profile_id") == active
    ]
    if len(matches) != 1:
        raise ConfigurationError("active provider profile is missing or ambiguous")
    return matches[0]


def _adapter_config(
    config: Mapping[str, Any],
    reference: Any,
) -> Mapping[str, Any]:
    if not isinstance(reference, str) or not re.fullmatch(
        r"adapter-config:[a-z0-9][a-z0-9_-]{1,63}",
        reference,
    ):
        raise ConfigurationError("provider adapter_config_ref is invalid")
    adapters = config.get("adapter_configs")
    if not isinstance(adapters, Mapping):
        raise ConfigurationError("config.adapter_configs must be an object")
    adapter = adapters.get(reference)
    if not isinstance(adapter, Mapping):
        raise ConfigurationError("provider adapter configuration is missing")
    return adapter


def _credential_host(
    config: Mapping[str, Any],
    reference: Any,
) -> str:
    if not isinstance(reference, str) or not re.fullmatch(
        r"credential:[a-z0-9][a-z0-9_-]{1,63}",
        reference,
    ):
        raise ConfigurationError("provider credential_ref is invalid")
    bindings = config.get("credential_bindings")
    if not isinstance(bindings, Mapping):
        raise ConfigurationError("config.credential_bindings must be an object")
    binding = bindings.get(reference)
    if not isinstance(binding, Mapping):
        raise ConfigurationError("provider credential binding is missing")
    host = binding.get("helper_host")
    if not isinstance(host, str) or not host or len(host) > 255:
        raise ConfigurationError("provider credential helper host is invalid")
    return host


def _control_plane_config(config: Mapping[str, Any]) -> dict[str, Any]:
    profile = _provider_profile(config)
    control = profile.get("control_plane")
    if not isinstance(control, Mapping):
        raise ConfigurationError("provider control_plane is invalid")
    adapter = dict(_adapter_config(config, control.get("adapter_config_ref")))
    adapter.update(
        {
            "driver": control.get("driver"),
            "profile_id": profile.get("profile_id"),
            "adapter_config_ref": control.get("adapter_config_ref"),
            "scope_fingerprint": control.get("scope_fingerprint"),
            "credential_ref": control.get("credential_ref"),
            "credential_host": _credential_host(
                config,
                control.get("credential_ref"),
            ),
        }
    )
    return adapter


def _object_store_config(
    config: Mapping[str, Any],
    store_id: str | None = None,
) -> dict[str, Any]:
    profile = _provider_profile(config)
    stores = profile.get("object_stores")
    if not isinstance(stores, list):
        raise ConfigurationError("provider object_stores must be an array")
    selected = (
        validate_identifier(store_id, "store_id")
        if store_id is not None
        else None
    )
    candidates = [
        item
        for item in stores
        if isinstance(item, Mapping)
        and (
            item.get("store_id") == selected
            if selected is not None
            else item.get("role") == "primary"
            and item.get("access") == "read_write"
        )
    ]
    if len(candidates) != 1:
        raise ConfigurationError(
            "provider object store is missing or ambiguous"
        )
    store = candidates[0]
    adapter = dict(_adapter_config(config, store.get("adapter_config_ref")))
    adapter.update(
        {
            "driver": store.get("driver"),
            "profile_id": profile.get("profile_id"),
            "store_id": store.get("store_id"),
            "adapter_config_ref": store.get("adapter_config_ref"),
            "scope_fingerprint": store.get("scope_fingerprint"),
            "credential_ref": store.get("credential_ref"),
            "credential_host": _credential_host(
                config,
                store.get("credential_ref"),
            ),
            "access": store.get("access"),
            "role": store.get("role"),
        }
    )
    return adapter


def _refresh_provider_scope_fingerprints(config: MutableMapping[str, Any]) -> None:
    profile = _provider_profile(config)
    control = profile.get("control_plane")
    if not isinstance(control, MutableMapping):
        raise ConfigurationError("provider control_plane is invalid")
    control_adapter = _adapter_config(
        config,
        control.get("adapter_config_ref"),
    )
    control["scope_fingerprint"] = _provider_scope_fingerprint(
        kind="control_plane",
        driver=str(control.get("driver")),
        adapter_config=control_adapter,
    )
    stores = profile.get("object_stores")
    if not isinstance(stores, list):
        raise ConfigurationError("provider object_stores must be an array")
    for store in stores:
        if not isinstance(store, MutableMapping):
            raise ConfigurationError("provider object store is invalid")
        adapter = _adapter_config(
            config,
            store.get("adapter_config_ref"),
        )
        store["scope_fingerprint"] = _provider_scope_fingerprint(
            kind="object_store",
            driver=str(store.get("driver")),
            adapter_config=adapter,
        )


def _validate_provider_transaction_pins(value: Any) -> dict[str, Any]:
    if not isinstance(value, Mapping):
        raise VerificationError("provider transaction pins are missing")
    raw = _json_clone(value)
    if raw.get("schema_version") != PROVIDER_PINS_SCHEMA:
        raise VerificationError("provider transaction pin schema is invalid")
    if set(raw) != {
        "schema_version",
        "profile_id",
        "control_plane",
        "object_store",
    }:
        raise VerificationError("provider transaction pin fields are invalid")
    validate_identifier(raw.get("profile_id"), "provider pin profile_id")
    specifications = (
        (
            "control_plane",
            {"git-https", "git-local-test"},
            {
                "driver",
                "adapter_config_ref",
                "credential_ref",
                "scope_fingerprint",
            },
        ),
        (
            "object_store",
            {
                "google-drive-v3",
                "filesystem-test",
                RCLONE_OBJECT_STORE_DRIVER,
            },
            {
                "store_id",
                "driver",
                "adapter_config_ref",
                "credential_ref",
                "scope_fingerprint",
            },
        ),
    )
    for label, drivers, expected_fields in specifications:
        item = raw.get(label)
        if not isinstance(item, Mapping) or set(item) != expected_fields:
            raise VerificationError(f"provider {label} pin fields are invalid")
        if item.get("driver") not in drivers:
            raise VerificationError(f"provider {label} pin driver is invalid")
        adapter_ref = item.get("adapter_config_ref")
        if not isinstance(adapter_ref, str) or not re.fullmatch(
            r"adapter-config:[a-z0-9][a-z0-9_-]{1,63}",
            adapter_ref,
        ):
            raise VerificationError(
                f"provider {label} adapter pin is invalid"
            )
        credential_ref = item.get("credential_ref")
        if not isinstance(credential_ref, str) or not re.fullmatch(
            r"credential:[a-z0-9][a-z0-9_-]{1,63}",
            credential_ref,
        ):
            raise VerificationError(
                f"provider {label} credential pin is invalid"
            )
        validate_sha256(
            item.get("scope_fingerprint"),
            f"provider {label} scope fingerprint",
        )
    validate_identifier(
        raw["object_store"].get("store_id"),
        "provider pin store_id",
    )
    return raw


def _provider_transaction_pins(config: Mapping[str, Any]) -> dict[str, Any]:
    control = _control_plane_config(config)
    object_store = _object_store_config(config)
    return _validate_provider_transaction_pins(
        {
            "schema_version": PROVIDER_PINS_SCHEMA,
            "profile_id": control["profile_id"],
            "control_plane": {
                "driver": control["driver"],
                "adapter_config_ref": control["adapter_config_ref"],
                "credential_ref": control["credential_ref"],
                "scope_fingerprint": control["scope_fingerprint"],
            },
            "object_store": {
                "store_id": object_store["store_id"],
                "driver": object_store["driver"],
                "adapter_config_ref": object_store["adapter_config_ref"],
                "credential_ref": object_store["credential_ref"],
                "scope_fingerprint": object_store["scope_fingerprint"],
            },
        }
    )


def _rclone_version_tuple(value: Any, label: str) -> tuple[int, int, int]:
    if not isinstance(value, str):
        raise ConfigurationError(f"{label} must be a semantic version")
    match = re.fullmatch(r"(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)", value)
    if match is None:
        raise ConfigurationError(f"{label} must be a semantic version")
    return tuple(int(item) for item in match.groups())


def _validate_rclone_adapter_config(value: Any) -> dict[str, str]:
    expected = {
        "executable",
        "executable_sha256",
        "config_path",
        "remote_name",
        "remote_fingerprint",
        "minimum_version",
        "verified_version",
    }
    if not isinstance(value, Mapping) or set(value) != expected:
        raise ConfigurationError(
            "rclone adapter configuration fields are invalid"
        )
    adapter = {str(key): item for key, item in value.items()}
    for key in ("executable", "config_path"):
        item = adapter.get(key)
        if (
            not isinstance(item, str)
            or not Path(item).is_absolute()
            or "\x00" in item
            or "\n" in item
            or "\r" in item
        ):
            raise ConfigurationError(f"rclone {key} must be an absolute path")
    validate_sha256(
        adapter.get("executable_sha256"),
        "rclone executable_sha256",
    )
    validate_sha256(
        adapter.get("remote_fingerprint"),
        "rclone remote_fingerprint",
    )
    remote_name = adapter.get("remote_name")
    if not isinstance(remote_name, str) or re.fullmatch(
        r"[A-Za-z0-9][A-Za-z0-9_-]{0,62}", remote_name
    ) is None:
        raise ConfigurationError("rclone remote_name is invalid")
    minimum = adapter.get("minimum_version")
    if minimum != RCLONE_MINIMUM_VERSION:
        raise ConfigurationError("rclone minimum_version is unsupported")
    minimum_tuple = _rclone_version_tuple(minimum, "rclone minimum_version")
    verified_tuple = _rclone_version_tuple(
        adapter.get("verified_version"),
        "rclone verified_version",
    )
    if verified_tuple < minimum_tuple:
        raise ConfigurationError("verified rclone version is too old")
    return {key: str(adapter[key]) for key in sorted(expected)}


def _parse_rclone_redacted_section(
    raw: bytes,
    *,
    expected_name: str,
) -> dict[str, str]:
    if len(raw) > MAX_RCLONE_CONTROL_OUTPUT_BYTES or b"\x00" in raw:
        raise PrivacyError("rclone redacted configuration is out of bounds")
    try:
        text = raw.decode("utf-8", "strict")
        parser = configparser.RawConfigParser(
            interpolation=None,
            strict=True,
            empty_lines_in_values=False,
        )
        parser.read_string(text)
    except (UnicodeDecodeError, configparser.Error) as exc:
        raise PrivacyError("rclone redacted configuration is invalid") from exc
    if parser.sections() != [expected_name]:
        raise PrivacyError("rclone redacted configuration identity is invalid")
    values = {
        str(key).strip().lower(): str(item).strip()
        for key, item in parser.items(expected_name, raw=True)
    }
    if not values or any(
        not key
        or "\x00" in key + item
        or "\n" in key + item
        or "\r" in key + item
        for key, item in values.items()
    ):
        raise PrivacyError("rclone redacted configuration fields are invalid")
    nonsecret_key_paths = {
        "key_file",
        "pubkey_file",
        "known_hosts_file",
        "pass_bad_blocks",
    }
    sensitive_name = re.compile(
        r"(?:pass(?:word)?|secret|token|credential|bearer|cookie|"
        r"access_key|api_key|customer_key|private_key|client_key|key_pem|"
        r"key_file_pass)",
        re.IGNORECASE,
    )
    for key, item in values.items():
        if (
            key not in nonsecret_key_paths
            and sensitive_name.search(key)
            and item not in {"", "XXX"}
        ):
            raise PrivacyError(
                "rclone redaction did not remove a credential field"
            )
    return values


def _rclone_boolean(
    values: Mapping[str, str],
    key: str,
    *,
    default: bool,
) -> bool:
    raw = values.get(key)
    if raw is None or raw == "":
        return default
    normalized = raw.strip().lower()
    if normalized == "true":
        return True
    if normalized == "false":
        return False
    raise PrivacyError(f"rclone {key} must be true or false")


def _validate_rclone_wrapped_path(value: str) -> tuple[str, str]:
    if (
        not isinstance(value, str)
        or len(value.encode("utf-8")) > 1024
        or "\x00" in value
        or "\n" in value
        or "\r" in value
        or "\\" in value
    ):
        raise PrivacyError("rclone crypt wrapped remote is invalid")
    match = re.fullmatch(
        r"([A-Za-z0-9][A-Za-z0-9_-]{0,62}):(.+)", value
    )
    if match is None:
        raise PrivacyError(
            "rclone crypt must wrap a named remote and dedicated path"
        )
    remote_name, path = match.groups()
    if path.startswith("/"):
        path_body = path[1:]
    elif re.match(r"^[A-Za-z]:/", path):
        path_body = path[3:]
    else:
        path_body = path
    pieces = path_body.split("/")
    if any(piece in {"", ".", ".."} for piece in pieces):
        raise PrivacyError("rclone crypt wrapped path is not dedicated")
    return remote_name, path


def _validate_rclone_redacted_sections(
    *,
    remote_name: str,
    crypt_raw: bytes,
    base_raw: bytes,
) -> dict[str, Any]:
    if re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_-]{0,62}", remote_name) is None:
        raise PrivacyError("rclone crypt remote name is invalid")
    crypt = _parse_rclone_redacted_section(
        crypt_raw,
        expected_name=remote_name,
    )
    if crypt.get("type") != "crypt":
        raise PrivacyError("rclone object store must use a crypt remote")
    if crypt.get("password") != "XXX" or crypt.get("password2") != "XXX":
        raise PrivacyError(
            "rclone crypt remote needs a redacted password and custom salt"
        )
    if crypt.get("filename_encryption") != "standard":
        raise PrivacyError("rclone crypt filename encryption must be standard")
    if not _rclone_boolean(
        crypt,
        "directory_name_encryption",
        default=False,
    ):
        raise PrivacyError("rclone crypt directory names must be encrypted")
    if not _rclone_boolean(crypt, "strict_names", default=False):
        raise PrivacyError("rclone crypt strict_names must be enabled")
    if _rclone_boolean(crypt, "pass_bad_blocks", default=False):
        raise PrivacyError("rclone crypt pass_bad_blocks must be disabled")
    wrapped_name, wrapped_path = _validate_rclone_wrapped_path(
        str(crypt.get("remote") or "")
    )
    base = _parse_rclone_redacted_section(
        base_raw,
        expected_name=wrapped_name,
    )
    backend_type = str(base.get("type") or "").lower()
    if backend_type not in RCLONE_SUPPORTED_BACKENDS:
        raise PrivacyError("rclone wrapped backend is unsupported")
    absolute_wrapped_path = wrapped_path.startswith("/") or re.match(
        r"^[A-Za-z]:/",
        wrapped_path,
    ) is not None
    if absolute_wrapped_path and backend_type != "local":
        raise PrivacyError(
            "only the local rclone backend may use an absolute wrapped path"
        )
    for unsafe_boolean in (
        "no_check_certificate",
        "auth_redirect",
        "copy_links",
        "links",
        "use_insecure_cipher",
        "ask_password",
        "env_auth",
        "v2_auth",
    ):
        if _rclone_boolean(base, unsafe_boolean, default=False):
            raise PrivacyError(
                f"rclone backend {unsafe_boolean} must be disabled"
            )
    base_fingerprint = dict(base)
    local_trust_files: dict[str, str] = {}
    if backend_type == "webdav":
        url = base.get("url")
        parsed = urllib.parse.urlparse(str(url or ""))
        if parsed.scheme != "https" or not parsed.hostname:
            raise PrivacyError("rclone WebDAV endpoint must use HTTPS")
        for unsafe_field in (
            "bearer_token_command",
            "headers",
            "unix_socket",
        ):
            if str(base.get(unsafe_field) or "").strip():
                raise PrivacyError(
                    f"rclone WebDAV {unsafe_field} is not supported"
                )
    elif backend_type == "s3":
        for endpoint_field in (
            "endpoint",
            "download_url",
            "sts_endpoint",
            "ibm_iam_endpoint",
        ):
            endpoint = str(base.get(endpoint_field) or "")
            if not endpoint:
                continue
            parsed = urllib.parse.urlparse(endpoint)
            if parsed.scheme != "https" or not parsed.hostname:
                raise PrivacyError(
                    f"rclone S3 {endpoint_field} must use HTTPS"
                )
        for external_credential_field in (
            "profile",
            "shared_credentials_file",
        ):
            if str(base.get(external_credential_field) or "").strip():
                raise PrivacyError(
                    "rclone S3 external credential profiles are not supported"
                )
    elif backend_type == "sftp":
        if not str(base.get("host") or "").strip():
            raise PrivacyError("rclone SFTP host is required")
        for command_field in (
            "ssh",
            "set_env",
            "server_command",
            "md5sum_command",
            "sha1sum_command",
            "sha256sum_command",
            "crc32sum_command",
            "blake3sum_command",
            "xxh3sum_command",
            "xxh128sum_command",
            "ciphers",
            "key_exchange",
            "macs",
            "host_key_algorithms",
        ):
            if str(base.get(command_field) or "").strip():
                raise PrivacyError(
                    "rclone SFTP command or custom cipher settings are not "
                    "supported"
                )
        for field in (
            "known_hosts_file",
            "key_file",
            "pubkey_file",
        ):
            value = str(base.get(field) or "")
            if not value:
                if field == "known_hosts_file":
                    raise PrivacyError(
                        "rclone SFTP known_hosts_file is required"
                    )
                continue
            if not (
                value.startswith("/")
                or re.match(r"^[A-Za-z]:[\\/]", value)
            ):
                raise PrivacyError(
                    f"rclone SFTP {field} must be an absolute path"
                )
            local_trust_files[field] = value
            # Device-local credential and trust-file paths are not portable
            # store identity. Their safety and content are verified below;
            # only the known-host bytes participate in the destination pin.
            base_fingerprint[field] = "<verified-local-file>"
    normalized = {
        "remote_name": remote_name,
        "crypt": {key: crypt[key] for key in sorted(crypt)},
        "wrapped_remote_name": wrapped_name,
        "wrapped_path": wrapped_path,
        "backend": {
            key: base_fingerprint[key]
            for key in sorted(base_fingerprint)
        },
    }
    result = {
        "backend_type": backend_type,
        "remote_fingerprint": sha256_bytes(canonical_json_bytes(normalized)),
        "wrapped_remote_name": wrapped_name,
        "wrapped_path": wrapped_path,
    }
    result.update(local_trust_files)
    return result


def _rclone_environment(config_password: str | None) -> dict[str, str]:
    if config_password is not None and (
        not config_password
        or "\x00" in config_password
        or "\n" in config_password
        or "\r" in config_password
    ):
        raise PrivacyError("rclone configuration password is invalid")
    # Do not inherit arbitrary RCLONE_* variables: any remote option can be
    # expressed through the environment and could otherwise replace the
    # reviewed crypt remote at process launch. Only OS/network plumbing needed
    # by the provider-owned client crosses this boundary.
    allowed = {
        "APPDATA",
        "LOCALAPPDATA",
        "SystemRoot",
        "SYSTEMROOT",
        "TEMP",
        "TMP",
        "TMPDIR",
        "WINDIR",
        "SSL_CERT_FILE",
        "SSL_CERT_DIR",
        "SSH_AUTH_SOCK",
        "HTTP_PROXY",
        "HTTPS_PROXY",
        "NO_PROXY",
        "http_proxy",
        "https_proxy",
        "no_proxy",
    }
    environment = {
        key: value
        for key, value in os.environ.items()
        if key in allowed and isinstance(value, str) and "\x00" not in value
    }
    if config_password is not None:
        environment["RCLONE_CONFIG_PASS"] = config_password
    return environment


def _hash_rclone_boundary_file(path: Path, label: str) -> tuple[str, int]:
    """Hash a provider-owned trust/credential file without exposing it.

    Unlike artifact hashing, this intentionally accepts conventional private
    key filenames. The bytes never enter a log, manifest, or remote document.
    """

    assert_plain_path(path, require_file=True)
    before = path.stat()
    if not stat.S_ISREG(before.st_mode):
        raise PrivacyError(f"{label} is not a regular file")
    digest = hashlib.sha256()
    total = 0
    with path.open("rb", buffering=0) as stream:
        while True:
            chunk = stream.read(1024 * 1024)
            if not chunk:
                break
            digest.update(chunk)
            total += len(chunk)
    after = path.stat()
    stable_fields = (
        "st_dev",
        "st_ino",
        "st_size",
        "st_mtime_ns",
        "st_ctime_ns",
    )
    if any(
        getattr(before, field, None) != getattr(after, field, None)
        for field in stable_fields
    ) or total != before.st_size:
        raise VerificationError(f"{label} changed while it was hashed")
    return digest.hexdigest(), total


def _run_rclone_control(
    arguments: Sequence[str],
    *,
    environment: Mapping[str, str],
    timeout: float,
) -> subprocess.CompletedProcess[bytes]:
    if (
        not arguments
        or any(
            not isinstance(item, str) or "\x00" in item
            for item in arguments
        )
    ):
        raise PrivacyError("rclone command arguments are invalid")
    output = bytearray()
    errors = bytearray()
    exceeded = threading.Event()
    try:
        process = subprocess.Popen(
            list(arguments),
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            shell=False,
            env=dict(environment),
            creationflags=(
                getattr(subprocess, "CREATE_NO_WINDOW", 0)
                if os.name == "nt"
                else 0
            ),
        )
    except OSError as exc:
        raise ConfigurationError("verified rclone executable is unavailable") from exc

    def read_bounded(stream: Any, target: bytearray) -> None:
        try:
            while True:
                chunk = stream.read(8192)
                if not chunk:
                    return
                remaining = MAX_RCLONE_CONTROL_OUTPUT_BYTES - len(target)
                if len(chunk) > remaining:
                    if remaining > 0:
                        target.extend(chunk[:remaining])
                    exceeded.set()
                    with contextlib.suppress(OSError):
                        process.kill()
                    return
                target.extend(chunk)
        finally:
            with contextlib.suppress(Exception):
                stream.close()

    assert process.stdout is not None and process.stderr is not None
    readers = (
        threading.Thread(
            target=read_bounded,
            args=(process.stdout, output),
            daemon=True,
        ),
        threading.Thread(
            target=read_bounded,
            args=(process.stderr, errors),
            daemon=True,
        ),
    )
    for reader in readers:
        reader.start()
    try:
        return_code = process.wait(timeout=timeout)
    except subprocess.TimeoutExpired as exc:
        with contextlib.suppress(OSError):
            process.kill()
        process.wait()
        for reader in readers:
            reader.join(timeout=2)
        raise OfflineError("rclone command timed out") from exc
    for reader in readers:
        reader.join(timeout=2)
    if any(reader.is_alive() for reader in readers):
        with contextlib.suppress(OSError):
            process.kill()
        raise VerificationError("rclone command output did not terminate")
    if exceeded.is_set():
        raise VerificationError("rclone command output exceeded its fixed bound")
    return subprocess.CompletedProcess(
        list(arguments),
        return_code,
        bytes(output),
        bytes(errors),
    )


def _rclone_config_command(
    executable: Path,
    config_path: Path,
    *arguments: str,
) -> list[str]:
    return [
        str(executable),
        "--config",
        str(config_path),
        "--ask-password=false",
        "--color=NEVER",
        *arguments,
    ]


def _probe_rclone_boundary(
    *,
    executable: Path,
    expected_executable_sha256: str,
    config_path: Path,
    remote_name: str,
    config_password: str,
) -> dict[str, Any]:
    executable = executable.expanduser().resolve(strict=True)
    config_path = config_path.expanduser().resolve(strict=True)
    assert_plain_path(executable, require_file=True)
    assert_plain_path(config_path, require_file=True)
    executable_mode = executable.stat().st_mode
    config_mode = config_path.stat().st_mode
    if not stat.S_ISREG(executable_mode) or not stat.S_ISREG(config_mode):
        raise ConfigurationError("rclone executable or config is not a plain file")
    if os.name != "nt":
        if not os.access(executable, os.X_OK):
            raise ConfigurationError("rclone executable is not executable")
        if executable_mode & (stat.S_IWGRP | stat.S_IWOTH):
            raise PrivacyError("rclone executable is writable by another account")
        if config_mode & (stat.S_IRWXG | stat.S_IRWXO):
            raise PrivacyError("rclone config permissions are not owner-only")
        getuid = getattr(os, "getuid", None)
        if callable(getuid) and config_path.stat().st_uid != getuid():
            raise PrivacyError("rclone config is owned by another account")
    expected_sha = validate_sha256(
        expected_executable_sha256,
        "rclone executable sha256",
    )
    executable_sha, _ = stable_hash_file(executable, inspect_text=False)
    if executable_sha != expected_sha:
        raise VerificationError("rclone executable hash does not match its pin")
    config_sha_before, config_size_before = stable_hash_file(
        config_path,
        inspect_text=False,
    )
    no_secret_environment = _rclone_environment(None)
    version = _run_rclone_control(
        _rclone_config_command(
            executable,
            Path(os.devnull),
            "version",
        ),
        environment=no_secret_environment,
        timeout=10,
    )
    if version.returncode != 0:
        raise ConfigurationError("rclone version probe failed")
    try:
        first_line = version.stdout.decode("utf-8", "strict").splitlines()[0]
    except (UnicodeDecodeError, IndexError) as exc:
        raise VerificationError("rclone version output is invalid") from exc
    match = re.fullmatch(r"rclone v([0-9]+\.[0-9]+\.[0-9]+)", first_line.strip())
    if match is None:
        raise VerificationError("rclone version output is unsupported")
    verified_version = match.group(1)
    if _rclone_version_tuple(
        verified_version,
        "rclone verified version",
    ) < _rclone_version_tuple(
        RCLONE_MINIMUM_VERSION,
        "rclone minimum version",
    ):
        raise ConfigurationError("rclone version is below the supported floor")
    environment = _rclone_environment(config_password)
    encryption = _run_rclone_control(
        _rclone_config_command(
            executable,
            config_path,
            "config",
            "encryption",
            "check",
        ),
        environment=environment,
        timeout=15,
    )
    if encryption.returncode != 0:
        raise AuthenticationError(
            "rclone config is not encrypted or could not be decrypted"
        )
    crypt_result = _run_rclone_control(
        _rclone_config_command(
            executable,
            config_path,
            "config",
            "redacted",
            remote_name,
        ),
        environment=environment,
        timeout=15,
    )
    if crypt_result.returncode != 0:
        raise AuthenticationError("rclone crypt remote could not be inspected")
    crypt = _parse_rclone_redacted_section(
        crypt_result.stdout,
        expected_name=remote_name,
    )
    wrapped_name, _ = _validate_rclone_wrapped_path(
        str(crypt.get("remote") or "")
    )
    base_result = _run_rclone_control(
        _rclone_config_command(
            executable,
            config_path,
            "config",
            "redacted",
            wrapped_name,
        ),
        environment=environment,
        timeout=15,
    )
    if base_result.returncode != 0:
        raise AuthenticationError("rclone wrapped remote could not be inspected")
    boundary = _validate_rclone_redacted_sections(
        remote_name=remote_name,
        crypt_raw=crypt_result.stdout,
        base_raw=base_result.stdout,
    )
    local_trust_files: dict[str, tuple[Path, str]] = {}
    remote_fingerprint = boundary["remote_fingerprint"]
    if boundary["backend_type"] == "sftp":
        for field in (
            "known_hosts_file",
            "key_file",
            "pubkey_file",
        ):
            raw_path = boundary.get(field)
            if not isinstance(raw_path, str):
                continue
            trust_path = Path(raw_path).expanduser().resolve(strict=True)
            assert_plain_path(trust_path, require_file=True)
            trust_stat = trust_path.stat()
            trust_mode = trust_stat.st_mode
            forbidden_mode = stat.S_IWGRP | stat.S_IWOTH
            if field == "key_file":
                forbidden_mode |= stat.S_IRGRP | stat.S_IROTH
            if (
                not stat.S_ISREG(trust_mode)
                or (os.name != "nt" and trust_mode & forbidden_mode)
            ):
                raise PrivacyError(
                    f"rclone SFTP {field} is not owner-controlled"
                )
            getuid = getattr(os, "getuid", None)
            if callable(getuid) and trust_stat.st_uid != getuid():
                raise PrivacyError(
                    f"rclone SFTP {field} is owned by another account"
                )
            trust_sha, _ = _hash_rclone_boundary_file(
                trust_path,
                f"rclone SFTP {field}",
            )
            local_trust_files[field] = (trust_path, trust_sha)
        known_hosts_sha_before = local_trust_files["known_hosts_file"][1]
        remote_fingerprint = sha256_bytes(
            canonical_json_bytes(
                {
                    "redacted_remote_fingerprint": remote_fingerprint,
                    "known_hosts_sha256": known_hosts_sha_before,
                }
            )
        )
    executable_sha_after, _ = stable_hash_file(
        executable,
        inspect_text=False,
    )
    config_sha_after, config_size_after = stable_hash_file(
        config_path,
        inspect_text=False,
    )
    if executable_sha_after != expected_sha:
        raise VerificationError("rclone executable changed during verification")
    if (
        config_sha_after != config_sha_before
        or config_size_after != config_size_before
    ):
        raise VerificationError("rclone config changed during verification")
    for field, (trust_path, trust_sha_before) in local_trust_files.items():
        trust_sha_after, _ = _hash_rclone_boundary_file(
            trust_path,
            f"rclone SFTP {field}",
        )
        if trust_sha_after != trust_sha_before:
            raise VerificationError(
                f"rclone SFTP {field} changed during verification"
            )
    return {
        "executable_sha256": expected_sha,
        "config_sha256": config_sha_before,
        "verified_version": verified_version,
        "minimum_version": RCLONE_MINIMUM_VERSION,
        "remote_fingerprint": remote_fingerprint,
        "backend_type": boundary["backend_type"],
        "wrapped_remote_name": boundary["wrapped_remote_name"],
        "wrapped_path": boundary.get("wrapped_path", ""),
        "local_trust_file_sha256": {
            str(path): digest
            for path, digest in local_trust_files.values()
        },
    }


def _stream_rclone_stdout(
    arguments: Sequence[str],
    *,
    environment: Mapping[str, str],
    timeout: float,
    maximum_bytes: int,
    output_stream: Any | None = None,
) -> tuple[str, int]:
    if maximum_bytes < 0:
        raise VerificationError("rclone stream byte bound is invalid")
    if not arguments or any(
        not isinstance(item, str) or "\x00" in item for item in arguments
    ):
        raise PrivacyError("rclone stream arguments are invalid")
    try:
        process = subprocess.Popen(
            list(arguments),
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            shell=False,
            env=dict(environment),
            creationflags=(
                getattr(subprocess, "CREATE_NO_WINDOW", 0)
                if os.name == "nt"
                else 0
            ),
        )
    except OSError as exc:
        raise ConfigurationError("verified rclone executable is unavailable") from exc
    assert process.stdout is not None and process.stderr is not None
    timed_out = threading.Event()
    stderr_exceeded = threading.Event()

    def terminate_on_timeout() -> None:
        timed_out.set()
        with contextlib.suppress(OSError):
            process.kill()

    def discard_stderr() -> None:
        total = 0
        try:
            while True:
                chunk = process.stderr.read(8192)
                if not chunk:
                    return
                total += len(chunk)
                if total > MAX_RCLONE_CONTROL_OUTPUT_BYTES:
                    stderr_exceeded.set()
                    with contextlib.suppress(OSError):
                        process.kill()
                    return
        finally:
            with contextlib.suppress(Exception):
                process.stderr.close()

    error_reader = threading.Thread(target=discard_stderr, daemon=True)
    error_reader.start()
    timer = threading.Timer(timeout, terminate_on_timeout)
    timer.daemon = True
    timer.start()
    digest = hashlib.sha256()
    total = 0
    try:
        while True:
            chunk = process.stdout.read(1024 * 1024)
            if not chunk:
                break
            total += len(chunk)
            if total > maximum_bytes:
                with contextlib.suppress(OSError):
                    process.kill()
                raise VerificationError(
                    "rclone stream exceeded its declared byte bound"
                )
            digest.update(chunk)
            if output_stream is not None:
                output_stream.write(chunk)
        return_code = process.wait()
    finally:
        timer.cancel()
        with contextlib.suppress(Exception):
            process.stdout.close()
        if process.poll() is None:
            with contextlib.suppress(OSError):
                process.kill()
            process.wait()
        error_reader.join(timeout=2)
    if timed_out.is_set():
        raise OfflineError("rclone stream timed out")
    if stderr_exceeded.is_set() or error_reader.is_alive():
        raise VerificationError("rclone stream diagnostics exceeded their bound")
    if return_code != 0:
        raise OfflineError("rclone encrypted object transfer failed")
    return digest.hexdigest(), total


def validate_config(value: Any) -> dict[str, Any]:
    if not isinstance(value, Mapping):
        raise ConfigurationError("config must be an object")
    raw = _json_clone(value)
    if raw.get("schema_version") == LEGACY_CONFIG_SCHEMA:
        raw = _migrate_config_v1_to_v2(raw)
    if raw.get("schema_version") != CONFIG_SCHEMA:
        raise ConfigurationError(f"config must use {CONFIG_SCHEMA}")
    if raw.get("vault_id") != VAULT_ID:
        raise ConfigurationError("vault_id does not match this plugin")
    legacy_test_mode = (
        raw.get("_test_mode") is True
        and os.environ.get("MEMORY_VAULT_SYNC_TESTING") == "1"
    )
    if not isinstance(raw.get("enabled"), bool):
        raise ConfigurationError("config.enabled must be boolean")
    for section in (
        "providers",
        "adapter_configs",
        "credential_bindings",
        "sync",
        "privacy",
    ):
        if not isinstance(raw.get(section), dict):
            raise ConfigurationError(f"config.{section} must be an object")
    if legacy_test_mode:
        if "projection" not in raw:
            raw["projection"] = {
                "enabled": False,
                "root": None,
                "materialize_missing": True,
            }
        if not isinstance(raw.get("projection"), dict):
            raise ConfigurationError("config.projection must be an object")
        if "matching" not in raw:
            raw["matching"] = {
                "enabled": True,
                "auto_provisional": False,
                "auto_promote_after_consistency_check": False,
                "prompt_on_ambiguity": True,
                "policy_version": MATCHING_POLICY_VERSION,
            }
        if not isinstance(raw.get("matching"), dict):
            raise ConfigurationError("config.matching must be an object")
    else:
        # These fields used to make a conversation or local workspace own a
        # memory.  Production now has one taskless associative network, so an
        # old config is migrated by deleting the obsolete product surface.
        raw.pop("projection", None)
        raw.pop("matching", None)
    if "updates" not in raw:
        raw["updates"] = {
            "enabled": True,
            "auto_install": True,
            "check_interval_seconds": DEFAULT_UPDATE_INTERVAL_SECONDS,
            "codex_executable": None,
        }
    if not isinstance(raw.get("updates"), dict):
        raise ConfigurationError("config.updates must be an object")
    providers = raw["providers"]
    if providers.get("schema_version") != PROVIDER_CONFIG_SCHEMA:
        raise ConfigurationError(
            f"config.providers must use {PROVIDER_CONFIG_SCHEMA}"
        )
    guards = providers.get("protocol_guards")
    expected_guards = {
        "object_write_before_control_plane": True,
        "current_compare_and_swap": True,
        "preserve_provider_pins": True,
        "retired_stores_read_only": True,
    }
    if guards != expected_guards:
        raise ConfigurationError("provider protocol guards cannot be disabled")
    profile = _provider_profile(raw)
    if profile.get("status") != "active":
        raise ConfigurationError("active provider profile must be active")
    control = profile.get("control_plane")
    if not isinstance(control, Mapping):
        raise ConfigurationError("provider control_plane must be an object")
    control_driver = control.get("driver")
    if control_driver not in {"git-https", "git-local-test"}:
        raise ConfigurationError("unsupported control-plane driver")
    if control.get("access") != "read_write":
        raise ConfigurationError("active control plane must be read-write")
    control_adapter = _adapter_config(
        raw,
        control.get("adapter_config_ref"),
    )
    validate_identifier(control_adapter.get("branch"), "control_plane.branch")
    repo_url = control_adapter.get("repo_url")
    if not isinstance(repo_url, str) or not repo_url:
        raise ConfigurationError("control-plane repo_url is required")
    if (
        control_driver == "git-local-test"
        and not (
            raw.get("_test_mode") is True
            and os.environ.get("MEMORY_VAULT_SYNC_TESTING") == "1"
        )
    ):
        raise ConfigurationError("local Git control plane is test-only")
    if control_driver == "git-https":
        privacy_verifier = control_adapter.get("privacy_verifier")
        if privacy_verifier not in {
            "github-private-v1",
            "gitlab-private-v1",
        }:
            raise ConfigurationError(
                "Git HTTPS control plane needs a supported privacy verifier"
            )
        repo_url_text = str(repo_url)
        if (
            privacy_verifier == "github-private-v1"
            and (
                GITHUB_REPO_RE.fullmatch(repo_url_text) is None
                or not repo_url_text.startswith("https://github.com/")
            )
        ):
            raise ConfigurationError(
                "GitHub privacy verification requires a GitHub HTTPS remote"
            )
        if (
            privacy_verifier == "gitlab-private-v1"
            and GITLAB_HTTPS_REPO_RE.fullmatch(repo_url_text) is None
        ):
            raise ConfigurationError(
                "GitLab privacy verification requires a GitLab.com HTTPS remote"
            )
        expected_repository = control_adapter.get("expected_repository")
        if not isinstance(expected_repository, str) or not expected_repository:
            raise ConfigurationError(
                "control-plane expected repository is required"
            )
    expected_control_scope = _provider_scope_fingerprint(
        kind="control_plane",
        driver=str(control_driver),
        adapter_config=control_adapter,
    )
    if control.get("scope_fingerprint") != expected_control_scope:
        raise ConfigurationError("control-plane scope fingerprint is stale")
    _credential_host(raw, control.get("credential_ref"))
    stores = profile.get("object_stores")
    if not isinstance(stores, list) or not stores:
        raise ConfigurationError("provider profile needs object stores")
    store_ids: set[str] = set()
    writable_primary = 0
    for store in stores:
        if not isinstance(store, Mapping):
            raise ConfigurationError("provider object store is invalid")
        store_id = validate_identifier(store.get("store_id"), "store_id")
        if store_id in store_ids:
            raise ConfigurationError("provider store_id is duplicated")
        store_ids.add(store_id)
        driver = store.get("driver")
        if driver not in {
            "google-drive-v3",
            "filesystem-test",
            RCLONE_OBJECT_STORE_DRIVER,
        }:
            raise ConfigurationError("unsupported object-store driver")
        access = store.get("access")
        if access not in {"read_write", "read_only"}:
            raise ConfigurationError("object-store access is invalid")
        if store.get("role") not in {"primary", "replica", "archive"}:
            raise ConfigurationError("object-store role is invalid")
        if access == "read_write" and store.get("role") == "primary":
            writable_primary += 1
        adapter = _adapter_config(raw, store.get("adapter_config_ref"))
        if driver == RCLONE_OBJECT_STORE_DRIVER:
            _validate_rclone_adapter_config(adapter)
        if (
            driver == "filesystem-test"
            and not (
                raw.get("_test_mode") is True
                and os.environ.get("MEMORY_VAULT_SYNC_TESTING") == "1"
            )
        ):
            raise ConfigurationError("filesystem object store is test-only")
        expected_scope = _provider_scope_fingerprint(
            kind="object_store",
            driver=str(driver),
            adapter_config=adapter,
        )
        if store.get("scope_fingerprint") != expected_scope:
            raise ConfigurationError("object-store scope fingerprint is stale")
        _credential_host(raw, store.get("credential_ref"))
    if writable_primary != 1:
        raise ConfigurationError(
            "provider profile needs exactly one writable primary object store"
        )
    privacy = raw["privacy"]
    if privacy.get("parse_transcript_path") is not False:
        raise ConfigurationError("parse_transcript_path must remain false")
    if privacy.get("store_raw_hook_input") is not False:
        raise ConfigurationError("store_raw_hook_input must remain false")
    if not isinstance(privacy.get("allowed_roots"), list):
        raise ConfigurationError("privacy.allowed_roots must be a list")
    allowed_roots: list[Path] = []
    for raw_root in privacy["allowed_roots"]:
        if not isinstance(raw_root, str) or not Path(raw_root).is_absolute():
            raise ConfigurationError(
                "privacy.allowed_roots must contain absolute paths"
            )
        allowed_roots.append(Path(raw_root).resolve())
    sync = raw["sync"]
    network_defaults = {
        "memory_network_enabled": True,
        "legacy_task_handoff_enabled": False,
        "associative_recall_enabled": True,
        "memory_recall_limit": DEFAULT_MEMORY_RECALL_LIMIT,
        "memory_recall_context_bytes": DEFAULT_MEMORY_RECALL_CONTEXT_BYTES,
    }
    for key, default in network_defaults.items():
        if key not in sync:
            sync[key] = default
    for key in (
        "memory_network_enabled",
        "legacy_task_handoff_enabled",
        "associative_recall_enabled",
    ):
        if not isinstance(sync.get(key), bool):
            raise ConfigurationError(f"sync.{key} must be boolean")
    if sync["memory_network_enabled"] and sync["legacy_task_handoff_enabled"]:
        raise ConfigurationError(
            "taskless memory network and legacy task handoff cannot both own hooks"
        )
    if not legacy_test_mode and (
        sync["memory_network_enabled"] is not True
        or sync["legacy_task_handoff_enabled"] is not False
    ):
        raise ConfigurationError(
            "task binding is retired; the associative memory network is the only runtime"
        )
    recall_limit = sync.get("memory_recall_limit")
    if (
        not isinstance(recall_limit, int)
        or isinstance(recall_limit, bool)
        or not 1 <= recall_limit <= memory_network.MAX_RECALL_LIMIT
    ):
        raise ConfigurationError(
            "sync.memory_recall_limit is outside the supported range"
        )
    recall_bytes = sync.get("memory_recall_context_bytes")
    if (
        not isinstance(recall_bytes, int)
        or isinstance(recall_bytes, bool)
        or not 512 <= recall_bytes <= 64 * 1024
    ):
        raise ConfigurationError(
            "sync.memory_recall_context_bytes is outside the supported range"
        )
    if sync.get("artifact_mode") not in {"declared-only", "none"}:
        raise ConfigurationError("artifact_mode must be declared-only or none")
    for key in (
        "max_auto_pull_bytes",
        "max_files_per_turn",
        "max_total_bytes_per_turn",
    ):
        if not isinstance(sync.get(key), int) or int(sync[key]) < 1:
            raise ConfigurationError(f"sync.{key} must be a positive integer")
    max_stop_upload = sync.get(
        "max_stop_upload_bytes",
        DEFAULT_MAX_STOP_UPLOAD_BYTES,
    )
    if (
        not isinstance(max_stop_upload, int)
        or isinstance(max_stop_upload, bool)
        or int(max_stop_upload) < 0
    ):
        raise ConfigurationError(
            "sync.max_stop_upload_bytes must be a non-negative integer"
        )
    sync["max_stop_upload_bytes"] = int(max_stop_upload)
    max_parallel_uploads = sync.get(
        "max_parallel_artifact_uploads",
        DEFAULT_MAX_PARALLEL_ARTIFACT_UPLOADS,
    )
    if (
        not isinstance(max_parallel_uploads, int)
        or isinstance(max_parallel_uploads, bool)
        or not 1 <= int(max_parallel_uploads) <= MAX_PARALLEL_ARTIFACT_UPLOADS
    ):
        raise ConfigurationError(
            "sync.max_parallel_artifact_uploads must be between 1 and "
            f"{MAX_PARALLEL_ARTIFACT_UPLOADS}"
        )
    sync["max_parallel_artifact_uploads"] = int(max_parallel_uploads)
    chunking_enabled = sync.get("chunked_artifacts_enabled", False)
    if not isinstance(chunking_enabled, bool):
        raise ConfigurationError(
            "sync.chunked_artifacts_enabled must be boolean"
        )
    if (
        chunking_enabled
        and _object_store_config(raw).get("driver")
        != RCLONE_OBJECT_STORE_DRIVER
    ):
        raise ConfigurationError(
            "sync.chunked_artifacts_enabled requires rclone crypt primary"
        )
    sync["chunked_artifacts_enabled"] = chunking_enabled
    chunk_minimum = sync.get(
        "chunked_artifact_min_bytes",
        DEFAULT_CHUNK_MINIMUM_BYTES,
    )
    if (
        not isinstance(chunk_minimum, int)
        or isinstance(chunk_minimum, bool)
        or not (
            CHUNK_SIZE_BYTES
            <= int(chunk_minimum)
            <= CHUNK_SIZE_BYTES * MAX_CHUNK_COUNT
        )
    ):
        raise ConfigurationError(
            "sync.chunked_artifact_min_bytes must be between one chunk and "
            "the maximum chunked artifact size"
        )
    sync["chunked_artifact_min_bytes"] = int(chunk_minimum)
    if legacy_test_mode:
        projection = raw["projection"]
        for key in ("enabled", "materialize_missing"):
            if not isinstance(projection.get(key), bool):
                raise ConfigurationError(f"projection.{key} must be boolean")
        projection_root = projection.get("root")
        if projection_root is not None:
            if (
                not isinstance(projection_root, str)
                or not Path(projection_root).is_absolute()
            ):
                raise ConfigurationError(
                    "projection.root must be an absolute path"
                )
            resolved_projection = Path(projection_root).resolve()
            if not any(
                _path_is_within(resolved_projection, allowed)
                for allowed in allowed_roots
            ):
                raise ConfigurationError(
                    "projection.root must be inside a configured allowed root"
                )
        if projection.get("enabled") and projection_root is None:
            raise ConfigurationError(
                "projection.root is required when task projection is enabled"
            )
        matching = raw["matching"]
        for key in (
            "enabled",
            "auto_provisional",
            "auto_promote_after_consistency_check",
            "prompt_on_ambiguity",
        ):
            if not isinstance(matching.get(key), bool):
                raise ConfigurationError(f"matching.{key} must be boolean")
        if matching.get("policy_version") != MATCHING_POLICY_VERSION:
            raise ConfigurationError("matching.policy_version is unsupported")
    updates = raw["updates"]
    for key in ("enabled", "auto_install"):
        if not isinstance(updates.get(key), bool):
            raise ConfigurationError(f"updates.{key} must be boolean")
    update_interval = updates.get("check_interval_seconds")
    if (
        not isinstance(update_interval, int)
        or isinstance(update_interval, bool)
        or not (
            MIN_UPDATE_INTERVAL_SECONDS
            <= update_interval
            <= MAX_UPDATE_INTERVAL_SECONDS
        )
    ):
        raise ConfigurationError(
            "updates.check_interval_seconds must be between 1 hour and 7 days"
        )
    codex_executable = updates.get("codex_executable")
    if codex_executable is not None and (
        not isinstance(codex_executable, str)
        or not Path(codex_executable).is_absolute()
    ):
        raise ConfigurationError(
            "updates.codex_executable must be an absolute path or null"
        )
    if not legacy_test_mode:
        # There is deliberately no production switch back to task ownership.
        sync.pop("memory_network_enabled", None)
        sync.pop("legacy_task_handoff_enabled", None)
    return raw


def _retire_legacy_automatic_matching_config(config_path: Path) -> bool:
    """Persistently disarm v0.12 auto-binding for old cached hook runtimes."""

    assert_plain_path(config_path, require_file=True)
    value = load_json(config_path)
    schema_version = value.get("schema_version") if isinstance(value, dict) else None
    legacy_vault = value.get("vault") if isinstance(value, dict) else None
    if (
        not isinstance(value, dict)
        or schema_version not in {CONFIG_SCHEMA, LEGACY_CONFIG_SCHEMA}
        or not isinstance(value.get("matching"), dict)
    ):
        return False
    if schema_version == LEGACY_CONFIG_SCHEMA and (
        not isinstance(legacy_vault, Mapping)
        or legacy_vault.get("vault_id") != VAULT_ID
    ):
        return False
    matching = value["matching"]
    keys = (
        "auto_provisional",
        "auto_promote_after_consistency_check",
    )
    if any(not isinstance(matching.get(key), bool) for key in keys):
        return False
    previous = {
        **{key: bool(matching[key]) for key in keys},
        "policy_version": matching.get("policy_version"),
    }
    if (
        not any(bool(matching[key]) for key in keys)
        and matching.get("policy_version") == MATCHING_POLICY_VERSION
    ):
        return False

    matching["auto_provisional"] = False
    matching["auto_promote_after_consistency_check"] = False
    matching["policy_version"] = MATCHING_POLICY_VERSION
    atomic_write_json(config_path, value)
    persisted = load_json(config_path)
    persisted_matching = (
        persisted.get("matching") if isinstance(persisted, Mapping) else None
    )
    if (
        not isinstance(persisted_matching, Mapping)
        or persisted_matching.get("auto_provisional") is not False
        or persisted_matching.get("auto_promote_after_consistency_check")
        is not False
        or persisted_matching.get("policy_version")
        != MATCHING_POLICY_VERSION
    ):
        raise VerificationError(
            "legacy automatic matching retirement could not be verified"
        )

    audit_path = (
        config_path.parent
        / "state"
        / "config-migrations"
        / "legacy-auto-matching-retired-v1.json"
    )
    if not audit_path.exists():
        atomic_write_json(
            audit_path,
            {
                "schema_version": LEGACY_AUTO_MATCHING_RETIREMENT_SCHEMA,
                "state": "completed",
                "reason": (
                    "v0.12 automatic matching did not prove full conversation "
                    "and artifact evidence"
                ),
                "previous": previous,
                "current": {
                    "auto_provisional": False,
                    "auto_promote_after_consistency_check": False,
                    "policy_version": MATCHING_POLICY_VERSION,
                },
                "retired_by_version": VERSION,
                "completed_at": utc_now(),
            },
        )
    return True


def _retire_known_legacy_automatic_matching_configs(data_dir: Path) -> None:
    paths = [data_dir / "config.json"]
    if _is_managed_plugin_data_dir(data_dir):
        paths.extend(path / "config.json" for path in _legacy_plugin_data_dirs())
    seen: set[str] = set()
    for path in paths:
        resolved = path.expanduser().resolve()
        key = os.path.normcase(str(resolved))
        if key in seen or not resolved.exists():
            continue
        seen.add(key)
        _retire_legacy_automatic_matching_config(resolved)


def _config_v2_migration_receipt_path(data_dir: Path) -> Path:
    return data_dir / "migration" / "config-v2.json"


def load_config(data_dir: Path) -> dict[str, Any] | None:
    path = data_dir / "config.json"
    if not path.exists():
        return None
    _retire_known_legacy_automatic_matching_configs(data_dir)
    assert_plain_path(path, require_file=True)
    original = load_json(path)
    normalized = validate_config(original)
    if (
        isinstance(original, Mapping)
        and original.get("schema_version") == LEGACY_CONFIG_SCHEMA
    ):
        lock_path = data_dir / "locks" / "config-v2-migration.lock"
        with FileLock(lock_path):
            current = load_json(path)
            if (
                isinstance(current, Mapping)
                and current.get("schema_version") == LEGACY_CONFIG_SCHEMA
            ):
                normalized = validate_config(current)
                atomic_write_json(
                    _config_v2_migration_receipt_path(data_dir),
                    {
                        "schema_version": CONFIG_MIGRATION_SCHEMA,
                        "from_schema": LEGACY_CONFIG_SCHEMA,
                        "to_schema": CONFIG_SCHEMA,
                        "provider_profile_id": DEFAULT_PROVIDER_PROFILE_ID,
                        "provider_pins": _provider_transaction_pins(
                            normalized
                        ),
                        "source_sha256": sha256_bytes(
                            canonical_json_bytes(current)
                        ),
                        "completed_at": utc_now(),
                    },
                )
                atomic_write_json(path, normalized)
            else:
                normalized = validate_config(current)
    elif isinstance(original, Mapping) and original != normalized:
        # Persist the taskless configuration shape so deleted binding fields do
        # not silently return on the next client.  Keep a private, bounded
        # rollback record; it never enters the remote memory repository.
        lock_path = data_dir / "locks" / "taskless-config-migration.lock"
        with FileLock(lock_path):
            current = load_json(path)
            current_normalized = validate_config(current)
            if current != current_normalized:
                receipt_path = (
                    data_dir / "migration" / "taskless-config-v1.json"
                )
                if not receipt_path.exists():
                    atomic_write_json(
                        receipt_path,
                        {
                            "schema_version": (
                                "memory-vault-taskless-config-migration/v1"
                            ),
                            "source_sha256": sha256_bytes(
                                canonical_json_bytes(current)
                            ),
                            "removed_sections": [
                                key
                                for key in ("matching", "projection")
                                if key in current
                            ],
                            "removed_sync_switches": [
                                key
                                for key in (
                                    "memory_network_enabled",
                                    "legacy_task_handoff_enabled",
                                )
                                if isinstance(current.get("sync"), Mapping)
                                and key in current["sync"]
                            ],
                            "completed_at": utc_now(),
                        },
                    )
                atomic_write_json(path, current_normalized)
                normalized = current_normalized
    return normalized


def _legacy_plugin_data_dirs() -> list[Path]:
    candidates = [
        _codex_home() / "plugin-data" / PLUGIN_NAME,
        Path.home() / ".codex" / "plugin-data" / PLUGIN_NAME,
    ]
    local_app_data = os.environ.get("LOCALAPPDATA")
    if local_app_data:
        candidates.append(
            Path(local_app_data)
            / "OpenAI"
            / "Codex"
            / "plugin-data"
            / PLUGIN_NAME
        )
    unique: list[Path] = []
    seen: set[str] = set()
    for candidate in candidates:
        resolved = candidate.expanduser().resolve()
        key = os.path.normcase(str(resolved))
        if key not in seen:
            seen.add(key)
            unique.append(resolved)
    return unique


def _migration_marker_path(data_dir: Path) -> Path:
    return data_dir / "migration" / "legacy-data-v1.json"


def _hash_plain_file(path: Path) -> tuple[str, int]:
    assert_plain_path(path, require_file=True)
    before = path.stat()
    if not stat.S_ISREG(before.st_mode):
        raise PrivacyError("legacy plugin data contains a non-regular file")
    digest = hashlib.sha256()
    size = 0
    with path.open("rb") as stream:
        while True:
            chunk = stream.read(1024 * 1024)
            if not chunk:
                break
            digest.update(chunk)
            size += len(chunk)
    after = path.stat()
    stable_fields = (
        "st_dev",
        "st_ino",
        "st_size",
        "st_mtime_ns",
        "st_ctime_ns",
    )
    if any(
        getattr(before, field, None) != getattr(after, field, None)
        for field in stable_fields
    ):
        raise BusyError("legacy plugin data changed during migration")
    if size != before.st_size:
        raise BusyError("legacy plugin data size changed during migration")
    return digest.hexdigest(), size


def _collect_migration_files(source: Path) -> list[tuple[Path, Path, str, int]]:
    allowed_roots = ("g", "outbox", "spool", "state")
    collected: list[tuple[Path, Path, str, int]] = []
    total_bytes = 0

    def visit(root: Path, relative_root: Path) -> None:
        nonlocal total_bytes
        assert_plain_path(root, require_file=False)
        for entry in sorted(root.iterdir(), key=lambda item: item.name):
            relative = relative_root / entry.name
            if entry.is_symlink() or _is_reparse_point(entry):
                raise PrivacyError(
                    "legacy plugin data contains a symbolic link or reparse point"
                )
            entry_stat = entry.stat()
            if stat.S_ISDIR(entry_stat.st_mode):
                visit(entry, relative)
                continue
            if not stat.S_ISREG(entry_stat.st_mode):
                raise PrivacyError("legacy plugin data contains a special file")
            if (
                relative.parts
                and relative.parts[0] == "g"
                and entry.name.endswith(".lock")
            ):
                # Git lock files are transient crash/concurrency state, never
                # part of a reusable verified cache.
                continue
            digest, size = _hash_plain_file(entry)
            collected.append((entry, relative, digest, size))
            total_bytes += size
            if len(collected) > MAX_LOCAL_MIGRATION_FILES:
                raise BusyError("legacy plugin data exceeds the migration file limit")
            if total_bytes > MAX_LOCAL_MIGRATION_BYTES:
                raise BusyError("legacy plugin data exceeds the migration size limit")

    for name in allowed_roots:
        root = source / name
        if root.exists():
            visit(root, Path(name))
    return collected


def _migration_file_signature(
    files: Sequence[tuple[Path, Path, str, int]],
) -> list[tuple[str, str, int]]:
    return [
        (relative.as_posix(), digest, size)
        for _path, relative, digest, size in files
    ]


def _copy_migration_file(
    source: Path,
    destination: Path,
    expected_sha256: str,
    expected_size: int,
) -> None:
    if destination.exists():
        actual_sha256, actual_size = _hash_plain_file(destination)
        if (
            actual_sha256 != expected_sha256
            or actual_size != expected_size
        ):
            raise ConflictError(
                "the new plugin data directory contains conflicting local state"
            )
        return
    ensure_private_dir(destination.parent)
    fd, temporary_name = tempfile.mkstemp(
        prefix=f".{destination.name}.",
        suffix=".migration",
        dir=str(destination.parent),
    )
    temporary = Path(temporary_name)
    digest = hashlib.sha256()
    size = 0
    try:
        with source.open("rb") as source_stream, os.fdopen(
            fd, "wb"
        ) as destination_stream:
            while True:
                chunk = source_stream.read(1024 * 1024)
                if not chunk:
                    break
                destination_stream.write(chunk)
                digest.update(chunk)
                size += len(chunk)
            destination_stream.flush()
            os.fsync(destination_stream.fileno())
        if digest.hexdigest() != expected_sha256 or size != expected_size:
            raise BusyError("legacy plugin data changed while it was copied")
        source_sha256, source_size = _hash_plain_file(source)
        if source_sha256 != expected_sha256 or source_size != expected_size:
            raise BusyError("legacy plugin data changed while it was copied")
        _safe_chmod(temporary, 0o600)
        os.replace(temporary, destination)
        _safe_chmod(destination, 0o600)
        if hasattr(os, "O_DIRECTORY"):
            directory_fd = os.open(
                destination.parent,
                os.O_RDONLY | os.O_DIRECTORY,
            )
            try:
                os.fsync(directory_fd)
            finally:
                os.close(directory_fd)
    finally:
        with contextlib.suppress(FileNotFoundError):
            temporary.unlink()


def _migrate_legacy_source(
    source: Path,
    target: Path,
    raw_config: bytes,
) -> Mapping[str, Any]:
    target_config = target / "config.json"
    marker_path = _migration_marker_path(target)
    with FileLock(source / "locks" / "sync.lock"):
        config_path = source / "config.json"
        assert_plain_path(config_path, require_file=True)
        current_config = config_path.read_bytes()
        if current_config != raw_config:
            raise BusyError("legacy plugin configuration changed during migration")
        validate_config(load_json(config_path))

        files = _collect_migration_files(source)
        initial_signature = _migration_file_signature(files)
        source_by_relative = {
            relative: (digest, size)
            for relative, digest, size in initial_signature
        }
        for relative, digest, size in _migration_file_signature(
            _collect_migration_files(target)
        ):
            if source_by_relative.get(relative) != (digest, size):
                raise ConflictError(
                    "the new plugin data directory contains unrelated local state"
                )
        manifest_digest = hashlib.sha256()
        total_bytes = 0
        created_targets: list[tuple[Path, str, int]] = []
        try:
            for source_file, relative, digest, size in files:
                relative_text = relative.as_posix()
                manifest_digest.update(relative_text.encode("utf-8"))
                manifest_digest.update(b"\0")
                manifest_digest.update(digest.encode("ascii"))
                manifest_digest.update(b"\0")
                manifest_digest.update(str(size).encode("ascii"))
                manifest_digest.update(b"\0")
                total_bytes += size
                destination = target / relative
                destination_existed = destination.exists()
                _copy_migration_file(
                    source_file,
                    destination,
                    digest,
                    size,
                )
                if not destination_existed:
                    created_targets.append((destination, digest, size))

            final_files = _collect_migration_files(source)
            final_signature = _migration_file_signature(final_files)
            if final_signature != initial_signature:
                raise BusyError("legacy plugin data changed during migration")
            target_signature = _migration_file_signature(
                _collect_migration_files(target)
            )
            if target_signature != initial_signature:
                raise ConflictError(
                    "migrated local plugin state contains unexpected files"
                )
            for _source_file, relative, digest, size in files:
                target_digest, target_size = _hash_plain_file(target / relative)
                if target_digest != digest or target_size != size:
                    raise ConflictError(
                        "migrated local plugin state failed final verification"
                    )
            post_verify_signature = _migration_file_signature(
                _collect_migration_files(source)
            )
            if post_verify_signature != initial_signature:
                raise BusyError(
                    "legacy plugin data changed during final verification"
                )
        except Exception:
            for destination, digest, size in reversed(created_targets):
                with contextlib.suppress(OSError, VaultSyncError):
                    actual_digest, actual_size = _hash_plain_file(destination)
                    if actual_digest == digest and actual_size == size:
                        destination.unlink()
            raise

        marker = {
            "schema_version": LOCAL_DATA_MIGRATION_SCHEMA,
            "state": "completed",
            "source_kind": "pre-plugin-data-root",
            "file_count": len(files),
            "total_bytes": total_bytes,
            "manifest_sha256": manifest_digest.hexdigest(),
            "completed_at": utc_now(),
        }
        config_digest = sha256_bytes(raw_config)
        _copy_migration_file(
            config_path,
            target_config,
            config_digest,
            len(raw_config),
        )
        atomic_write_json(marker_path, marker)
        return marker


def _migrate_legacy_plugin_data_locked(
    target: Path,
) -> Mapping[str, Any] | None:
    marker_path = _migration_marker_path(target)
    if marker_path.exists():
        marker = load_json(marker_path)
        if (
            not isinstance(marker, Mapping)
            or marker.get("schema_version") != LOCAL_DATA_MIGRATION_SCHEMA
            or marker.get("state") != "completed"
        ):
            raise ConfigurationError("local plugin data migration marker is invalid")
        target_config = target / "config.json"
        if not target_config.exists():
            raise ConfigurationError(
                "completed local plugin data migration has no configuration"
            )
        validate_config(load_json(target_config))
        return marker

    target_config = target / "config.json"
    if target_config.exists():
        assert_plain_path(target_config, require_file=True)
        validate_config(load_json(target_config))
        # A configured target is already an independent local authority.  Even
        # an identical config is not permission to merge device/session state.
        return None

    legacy_sources: list[tuple[Path, bytes]] = []
    for source in _legacy_plugin_data_dirs():
        if source == target or not source.exists():
            continue
        assert_plain_path(source, require_file=False)
        config_path = source / "config.json"
        if not config_path.exists():
            continue
        assert_plain_path(config_path, require_file=True)
        raw_config = config_path.read_bytes()
        validate_config(load_json(config_path))
        legacy_sources.append((source, raw_config))
    if len(legacy_sources) > 1:
        raise ConflictError("more than one legacy plugin data directory is configured")
    if not legacy_sources:
        return None

    source, raw_config = legacy_sources[0]
    return _migrate_legacy_source(source, target, raw_config)


def migrate_legacy_plugin_data(data_dir: Path) -> Mapping[str, Any] | None:
    """Import the pre-plugin data root once into Codex-owned PLUGIN_DATA."""

    target = data_dir.expanduser().resolve()
    if not _is_managed_plugin_data_dir(target):
        return None
    ensure_private_dir(target)
    target_config = target / "config.json"
    if target_config.exists():
        assert_plain_path(target_config, require_file=True)
        return None

    lock_path = target / "locks" / "legacy-data-migration.lock"
    deadline = time.monotonic() + LOCAL_MIGRATION_LOCK_WAIT_SECONDS
    while True:
        migration_lock = FileLock(lock_path)
        try:
            migration_lock.__enter__()
        except BusyError:
            if target_config.exists():
                assert_plain_path(target_config, require_file=True)
                return None
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                raise
            time.sleep(min(0.1, remaining))
            continue
        try:
            # Another process may have completed migration while this process
            # waited for the one-time lock.
            if target_config.exists():
                assert_plain_path(target_config, require_file=True)
                return None
            return _migrate_legacy_plugin_data_locked(target)
        finally:
            migration_lock.__exit__(None, None, None)


def _read_bounded_plain_runtime_file(
    path: Path,
    *,
    maximum_bytes: int,
    label: str,
) -> bytes:
    """Read one stable, unlinked regular runtime file."""

    assert_plain_path(path, require_file=True)
    before = path.stat()
    if (
        not stat.S_ISREG(before.st_mode)
        or int(getattr(before, "st_nlink", 1)) != 1
        or before.st_size < 1
        or before.st_size > maximum_bytes
    ):
        raise PrivacyError(f"{label} is not a bounded private regular file")
    with path.open("rb", buffering=0) as stream:
        opened = os.fstat(stream.fileno())
        opened_links = int(getattr(opened, "st_nlink", 0) or 0)
        if (
            not stat.S_ISREG(opened.st_mode)
            or opened_links not in {0, 1}
            or not _stable_file_observations_match(
                before,
                opened,
                cross_interface=True,
            )
        ):
            raise PrivacyError(f"{label} changed before it was opened")
        raw = stream.read(maximum_bytes + 1)
        opened_after = os.fstat(stream.fileno())
    assert_plain_path(path, require_file=True)
    named_after = path.stat()
    if (
        len(raw) > maximum_bytes
        or len(raw) != before.st_size
        or not _stable_file_observations_match(opened, opened_after)
        or not _stable_file_observations_match(before, named_after)
    ):
        raise BusyError(f"{label} changed while it was verified")
    return raw


def _runtime_version_from_bytes(raw: bytes, label: str) -> str:
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise VerificationError(f"{label} is not UTF-8") from exc
    normalized = text.replace("\r\n", "\n")
    if "\r" in normalized:
        raise VerificationError(f"{label} contains an unsupported line ending")
    versions = re.findall(
        r'^VERSION = "([^"]+)"$',
        normalized,
        flags=re.MULTILINE,
    )
    if len(versions) != 1:
        raise VerificationError(f"{label} has no unique VERSION")
    _parse_semver(versions[0])
    return versions[0]


def _assert_plugin_cache_root(cache_root: Path) -> Path:
    if not cache_root.is_absolute():
        raise PrivacyError("plugin cache root must be absolute")
    lexical = Path(os.path.abspath(cache_root))
    if (
        lexical.name != PLUGIN_NAME
        or lexical.parent.name != MARKETPLACE_NAME
        or lexical.parent.parent.name != "cache"
        or lexical.parent.parent.parent.name != "plugins"
    ):
        raise PrivacyError("runtime retirement is outside the plugin cache")
    assert_plain_path(lexical, require_file=False)
    resolved = lexical.resolve(strict=True)
    if os.path.normcase(str(resolved)) != os.path.normcase(str(lexical)):
        raise PrivacyError(
            "plugin cache root contains a symbolic link or reparse point"
        )
    return resolved


def _verified_cached_runtime(
    version_root: Path,
    cache_root: Path,
) -> tuple[str, Path, Path, bytes] | None:
    """Return one verified cached runtime and whether it is already retired."""

    if version_root.is_symlink() or _is_reparse_point(version_root):
        raise PrivacyError(
            "cached plugin version is a symbolic link or reparse point"
        )
    if not version_root.is_dir():
        return None
    resolved_version = version_root.resolve(strict=True)
    if (
        resolved_version.parent != cache_root
        or not _path_is_within(resolved_version, cache_root)
    ):
        raise PrivacyError("cached plugin version escapes its plugin cache")
    version = version_root.name
    try:
        _parse_semver(version)
    except VerificationError:
        return None

    manifest_dir = version_root / ".codex-plugin"
    scripts_dir = version_root / "scripts"
    for directory in (manifest_dir, scripts_dir):
        if directory.is_symlink():
            raise PrivacyError(
                "cached plugin metadata contains a symbolic link or reparse point"
            )
        if not directory.exists():
            return None
        if _is_reparse_point(directory):
            raise PrivacyError(
                "cached plugin metadata contains a symbolic link or reparse point"
            )
        assert_plain_path(directory, require_file=False)
        resolved = directory.resolve(strict=True)
        if (
            resolved.parent != resolved_version
            or not _path_is_within(resolved, resolved_version)
        ):
            raise PrivacyError("cached plugin directory escapes its version")

    manifest_path = manifest_dir / "plugin.json"
    if manifest_path.is_symlink():
        raise PrivacyError(
            "cached plugin manifest is a symbolic link or reparse point"
        )
    if not manifest_path.exists():
        return None
    manifest_raw = _read_bounded_plain_runtime_file(
        manifest_path,
        maximum_bytes=64 * 1024,
        label="cached plugin manifest",
    )
    try:
        manifest = strict_json_loads(manifest_raw.decode("utf-8"))
    except (UnicodeDecodeError, ValueError, json.JSONDecodeError):
        return None
    if (
        not isinstance(manifest, Mapping)
        or manifest.get("name") != PLUGIN_NAME
        or manifest.get("version") != version
        or not isinstance(manifest.get("author"), Mapping)
        or manifest["author"].get("name") != PLUGIN_AUTHOR
    ):
        return None

    active_script = scripts_dir / "vault_sync.py"
    backup_script = scripts_dir / "vault_sync.py.retired.bak"
    for script_path in (active_script, backup_script):
        if script_path.is_symlink():
            raise PrivacyError(
                "cached plugin runtime is a symbolic link or reparse point"
            )
        if script_path.exists() and _is_reparse_point(script_path):
            raise PrivacyError(
                "cached plugin runtime is a symbolic link or reparse point"
            )
    active_exists = active_script.exists()
    backup_exists = backup_script.exists()
    if active_exists and backup_exists:
        raise ConflictError(
            "cached runtime has both active and retired script copies"
        )
    if not active_exists and not backup_exists:
        return None
    selected = active_script if active_exists else backup_script
    raw = _read_bounded_plain_runtime_file(
        selected,
        maximum_bytes=4 * 1024 * 1024,
        label="cached plugin runtime",
    )
    try:
        runtime_version = _runtime_version_from_bytes(
            raw,
            "cached plugin runtime",
        )
    except VerificationError:
        return None
    if runtime_version != version:
        return None
    return version, active_script, backup_script, raw


def _retire_older_cached_runtimes(
    cache_root: Path,
    activated_version: str,
) -> Mapping[str, Any]:
    """Atomically preserve and deactivate verified older cached hook scripts."""

    _parse_semver(activated_version)
    result: dict[str, Any] = {
        "schema_version": RUNTIME_RETIREMENT_SCHEMA,
        "activated_version": activated_version,
        "retired_versions": [],
        "already_retired_versions": [],
        "unverified_older_version_count": 0,
    }
    if cache_root.is_symlink():
        raise PrivacyError(
            "plugin cache root is a symbolic link or reparse point"
        )
    if not cache_root.exists():
        return result
    root = _assert_plugin_cache_root(cache_root)
    for entry in sorted(root.iterdir(), key=lambda item: item.name):
        if entry.is_symlink() or _is_reparse_point(entry):
            raise PrivacyError(
                "plugin cache contains a symbolic link or reparse point"
            )
        if not entry.is_dir():
            continue
        try:
            comparison = compare_semver(entry.name, activated_version)
        except VerificationError:
            continue
        if comparison >= 0:
            continue
        verified = _verified_cached_runtime(entry, root)
        if verified is None:
            result["unverified_older_version_count"] += 1
            continue
        version, active_script, backup_script, raw = verified
        if not active_script.exists():
            result["already_retired_versions"].append(version)
            continue
        if backup_script.exists():
            raise ConflictError(
                "cached runtime retirement would overwrite a backup"
            )
        try:
            os.rename(active_script, backup_script)
        except FileNotFoundError:
            # A concurrent verified activation may have completed the same
            # deterministic retirement. Re-verify it before treating it as
            # idempotent.
            repeated = _verified_cached_runtime(entry, root)
            if repeated is None or repeated[1].exists():
                raise BusyError("cached runtime changed during retirement")
            if repeated[3] != raw:
                raise BusyError("retired cached runtime content changed")
            result["already_retired_versions"].append(version)
            continue
        retired_raw = _read_bounded_plain_runtime_file(
            backup_script,
            maximum_bytes=4 * 1024 * 1024,
            label="retired cached plugin runtime",
        )
        if active_script.exists() or retired_raw != raw:
            raise VerificationError(
                "cached runtime retirement failed content verification"
            )
        with contextlib.suppress(OSError):
            directory_fd = os.open(backup_script.parent, os.O_RDONLY)
            try:
                os.fsync(directory_fd)
            finally:
                os.close(directory_fd)
        result["retired_versions"].append(version)
    return result


def _retire_managed_cached_runtimes(
    data_dir: Path,
    activated_version: str,
) -> Mapping[str, Any]:
    empty = {
        "schema_version": RUNTIME_RETIREMENT_SCHEMA,
        "activated_version": activated_version,
        "retired_versions": [],
        "already_retired_versions": [],
        "unverified_older_version_count": 0,
    }
    if not _is_managed_plugin_data_dir(data_dir):
        return empty
    cache_root = (
        _codex_home()
        / "plugins"
        / "cache"
        / MARKETPLACE_NAME
        / PLUGIN_NAME
    )
    if cache_root.is_symlink():
        raise PrivacyError(
            "plugin cache root is a symbolic link or reparse point"
        )
    if not cache_root.exists():
        return empty
    try:
        with FileLock(
            data_dir / "locks" / "runtime-cache-retirement.lock"
        ):
            return _retire_older_cached_runtimes(
                cache_root,
                activated_version,
            )
    except BusyError:
        # Another hook is already performing the same deterministic operation.
        # The next lifecycle event retries it.
        return {
            **empty,
            "retry_pending": True,
        }


def _read_runtime_bundle(root: Path, *, source: bool) -> dict[str, bytes]:
    files: dict[str, bytes] = {}
    location = "source" if source else "activated"
    for spec in RUNTIME_FILE_SPECS:
        files[spec.path] = _read_bounded_plain_runtime_file(
            root / PurePosixPath(spec.path),
            maximum_bytes=spec.maximum_bytes,
            label=f"{location} {spec.label}",
        )
    return files


def _runtime_bundle_versions(
    files: Mapping[str, bytes],
) -> tuple[str, str]:
    return (
        _runtime_version_from_bytes(
            files["scripts/vault_sync.py"],
            "stable runtime entrypoint",
        ),
        _runtime_version_from_bytes(
            files["scripts/memory_vault_runtime/core.py"],
            "stable runtime core",
        ),
    )


def _verify_stable_runtime_copy(
    stable_root: Path,
    expected_version: str,
    source_files: Mapping[str, bytes],
    *,
    bundle_sha256: str | None = None,
    marketplace_commit_sha: str | None = None,
) -> None:
    verified_files = _read_runtime_bundle(stable_root, source=False)
    script_bytes = source_files["scripts/vault_sync.py"]
    launcher_bytes = source_files["scripts/windows_launcher.ps1"]
    metadata_raw = _read_bounded_plain_runtime_file(
        stable_root / "runtime.json",
        maximum_bytes=64 * 1024,
        label="stable runtime metadata",
    )
    try:
        metadata = strict_json_loads(metadata_raw.decode("utf-8"))
    except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
        raise VerificationError("stable runtime metadata is invalid") from exc
    if (
        not isinstance(metadata, Mapping)
        or metadata.get("schema_version") != RUNTIME_CACHE_SCHEMA
        or metadata.get("plugin_version") != expected_version
        or metadata.get("script_sha256") != sha256_bytes(script_bytes)
        or metadata.get("script_size") != len(script_bytes)
        or metadata.get("launcher_sha256") != sha256_bytes(launcher_bytes)
        or metadata.get("launcher_size") != len(launcher_bytes)
        or not _runtime_inventory_matches(metadata.get("files"), source_files)
        or metadata.get("bundle_sha256") != bundle_sha256
        or metadata.get("marketplace_commit_sha") != marketplace_commit_sha
        or verified_files != dict(source_files)
        or _runtime_bundle_versions(verified_files)
        != (expected_version, expected_version)
    ):
        raise VerificationError("stable runtime activation failed verification")


def _load_verified_stable_runtime_identity(
    data_dir: Path,
) -> Mapping[str, str] | None:
    """Return the exact identity of the active runtime, or fail closed."""

    stable_root = data_dir / "runtime" / "active"
    metadata_path = stable_root / "runtime.json"
    try:
        metadata_raw = _read_bounded_plain_runtime_file(
            metadata_path,
            maximum_bytes=64 * 1024,
            label="stable runtime metadata",
        )
        metadata = strict_json_loads(metadata_raw.decode("utf-8"))
        files = _read_runtime_bundle(stable_root, source=False)
    except (
        UnicodeDecodeError,
        ValueError,
        json.JSONDecodeError,
        OSError,
        VaultSyncError,
    ):
        return None
    if not isinstance(metadata, Mapping):
        return None
    plugin_version = metadata.get("plugin_version")
    bundle_sha256 = metadata.get("bundle_sha256")
    marketplace_commit_sha = metadata.get("marketplace_commit_sha")
    script_bytes = files["scripts/vault_sync.py"]
    launcher_bytes = files["scripts/windows_launcher.ps1"]
    if (
        metadata.get("schema_version") != RUNTIME_CACHE_SCHEMA
        or not isinstance(plugin_version, str)
        or not isinstance(bundle_sha256, str)
        or not SHA256_RE.fullmatch(bundle_sha256)
        or bundle_sha256 == "0" * 64
        or not isinstance(marketplace_commit_sha, str)
        or not GIT_SHA_RE.fullmatch(marketplace_commit_sha)
        or marketplace_commit_sha in {"0" * 40, "0" * 64}
        or metadata.get("script_sha256") != sha256_bytes(script_bytes)
        or metadata.get("script_size") != len(script_bytes)
        or metadata.get("launcher_sha256") != sha256_bytes(launcher_bytes)
        or metadata.get("launcher_size") != len(launcher_bytes)
        or not _runtime_inventory_matches(metadata.get("files"), files)
    ):
        return None
    try:
        runtime_versions = _runtime_bundle_versions(files)
    except VaultSyncError:
        return None
    if runtime_versions != (plugin_version, plugin_version):
        return None
    return {
        "plugin_version": plugin_version,
        "bundle_sha256": bundle_sha256,
        "marketplace_commit_sha": marketplace_commit_sha,
    }


def _refresh_stable_runtime_from_plugin(
    data_dir: Path,
    plugin_root: Path,
    expected_version: str,
    *,
    bundle_sha256: str | None = None,
    marketplace_commit_sha: str | None = None,
) -> Mapping[str, Any]:
    """Activate a verified plugin runtime outside the version-pruned cache."""

    if bundle_sha256 is not None:
        bundle_sha256 = validate_sha256(
            bundle_sha256,
            "stable runtime bundle identity",
        )
    if marketplace_commit_sha is not None:
        marketplace_commit_sha = validate_git_sha(
            marketplace_commit_sha,
            "stable runtime marketplace identity",
        )

    source_root = plugin_root.resolve(strict=True)
    source_files = _read_runtime_bundle(source_root, source=True)
    script_bytes = source_files["scripts/vault_sync.py"]
    launcher_bytes = source_files["scripts/windows_launcher.ps1"]
    if _runtime_bundle_versions(source_files) != (
        expected_version,
        expected_version,
    ):
        raise VerificationError(
            "stable runtime source does not match the expected plugin version"
        )
    stable_root = data_dir / "runtime" / "active"
    metadata_path = stable_root / "runtime.json"

    if (
        metadata_path.exists()
        and not metadata_path.is_symlink()
        and not _is_reparse_point(metadata_path)
    ):
        with contextlib.suppress(VaultSyncError, OSError, ValueError):
            _verify_stable_runtime_copy(
                stable_root,
                expected_version,
                source_files,
                bundle_sha256=bundle_sha256,
                marketplace_commit_sha=marketplace_commit_sha,
            )
            retirement = _retire_managed_cached_runtimes(
                data_dir,
                expected_version,
            )
            return {
                "schema_version": RUNTIME_CACHE_SCHEMA,
                "plugin_version": expected_version,
                "bundle_sha256": bundle_sha256,
                "marketplace_commit_sha": marketplace_commit_sha,
                "updated": False,
                "runtime_retirement": retirement,
            }

    for spec in RUNTIME_FILE_SPECS:
        source = source_root / PurePosixPath(spec.path)
        target = stable_root / PurePosixPath(spec.path)
        if source != target.resolve(strict=False):
            atomic_write_bytes(
                target,
                source_files[spec.path],
                mode=spec.mode,
            )
    metadata = {
        "schema_version": RUNTIME_CACHE_SCHEMA,
        "plugin_version": expected_version,
        "script_sha256": sha256_bytes(script_bytes),
        "script_size": len(script_bytes),
        "launcher_sha256": sha256_bytes(launcher_bytes),
        "launcher_size": len(launcher_bytes),
        "files": _runtime_inventory_for(source_files),
        "bundle_sha256": bundle_sha256,
        "marketplace_commit_sha": marketplace_commit_sha,
        "refreshed_at": utc_now(),
    }
    atomic_write_json(metadata_path, metadata)
    _verify_stable_runtime_copy(
        stable_root,
        expected_version,
        source_files,
        bundle_sha256=bundle_sha256,
        marketplace_commit_sha=marketplace_commit_sha,
    )
    retirement = _retire_managed_cached_runtimes(
        data_dir,
        expected_version,
    )
    return {
        "schema_version": RUNTIME_CACHE_SCHEMA,
        "plugin_version": expected_version,
        "bundle_sha256": bundle_sha256,
        "marketplace_commit_sha": marketplace_commit_sha,
        "updated": True,
        "runtime_retirement": retirement,
    }


def _refresh_stable_runtime(data_dir: Path) -> Mapping[str, Any]:
    """Keep one private runtime copy outside the version-pruned plugin cache."""
    source_root = Path(__file__).resolve().parents[2]
    active_identity = _load_verified_stable_runtime_identity(data_dir)
    if (
        active_identity is not None
        and active_identity["plugin_version"] == VERSION
    ):
        source_files = _read_runtime_bundle(source_root, source=True)
        _verify_stable_runtime_copy(
            data_dir / "runtime" / "active",
            VERSION,
            source_files,
            bundle_sha256=active_identity["bundle_sha256"],
            marketplace_commit_sha=active_identity[
                "marketplace_commit_sha"
            ],
        )
        retirement = _retire_managed_cached_runtimes(data_dir, VERSION)
        return {
            "schema_version": RUNTIME_CACHE_SCHEMA,
            "plugin_version": VERSION,
            "bundle_sha256": active_identity["bundle_sha256"],
            "marketplace_commit_sha": active_identity[
                "marketplace_commit_sha"
            ],
            "updated": False,
            "runtime_retirement": retirement,
        }
    return _refresh_stable_runtime_from_plugin(
        data_dir,
        source_root,
        VERSION,
    )


def _subprocess_environment() -> dict[str, str]:
    environment = {
        key: value
        for key, value in os.environ.items()
        if not key.upper().startswith("GIT_")
    }
    environment["GIT_TERMINAL_PROMPT"] = "0"
    environment["GIT_CONFIG_NOSYSTEM"] = "1"
    environment["GIT_CONFIG_GLOBAL"] = os.devnull
    environment["GCM_INTERACTIVE"] = "Never"
    environment["GCM_GUI_PROMPT"] = "false"
    environment.pop("SSH_ASKPASS", None)
    return environment


def run_process(
    arguments: Sequence[str],
    *,
    cwd: Path | None = None,
    input_bytes: bytes | None = None,
    timeout: float = 60,
    sensitive_output: bool = False,
    extra_environment: Mapping[str, str] | None = None,
    inherit_git_environment: bool = False,
) -> subprocess.CompletedProcess[bytes]:
    environment = (
        dict(os.environ)
        if inherit_git_environment
        else _subprocess_environment()
    )
    if extra_environment:
        for key, value in extra_environment.items():
            if (
                not isinstance(key, str)
                or not isinstance(value, str)
                or "\x00" in key + value
                or "=" in key
            ):
                raise PrivacyError("subprocess environment override is invalid")
            environment[key] = value
    try:
        result = subprocess.run(
            list(arguments),
            cwd=str(cwd) if cwd else None,
            input=input_bytes,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            timeout=timeout,
            check=False,
            shell=False,
            env=environment,
        )
    except (OSError, subprocess.TimeoutExpired) as exc:
        raise OfflineError(f"command unavailable: {arguments[0]}") from exc
    if result.returncode:
        if sensitive_output:
            detail = "credential or network command failed"
        else:
            detail = result.stderr.decode("utf-8", "replace").strip()[-500:]
        lowered = detail.lower()
        if any(
            marker in lowered
            for marker in (
                "could not resolve",
                "connection",
                "timed out",
                "network",
                "ssl_error",
                "unable to access",
                "failed to connect",
            )
        ):
            raise OfflineError(detail or "network operation failed")
        raise VaultSyncError(detail or f"{arguments[0]} exited {result.returncode}")
    return result


def _https_context() -> ssl.SSLContext:
    """Return a verified TLS context, including the macOS system trust store."""

    global _HTTPS_CONTEXT
    if _HTTPS_CONTEXT is not None:
        return _HTTPS_CONTEXT
    with _HTTPS_CONTEXT_LOCK:
        if _HTTPS_CONTEXT is not None:
            return _HTTPS_CONTEXT
        context = ssl.create_default_context()
        if sys.platform == "darwin":
            pem_parts: list[str] = []
            for keychain in _MACOS_TRUST_KEYCHAINS:
                try:
                    result = run_process(
                        [
                            "/usr/bin/security",
                            "find-certificate",
                            "-a",
                            "-p",
                            keychain,
                        ],
                        timeout=10,
                    )
                except (VerificationError, PrivacyError, IdentityError):
                    continue
                pem = result.stdout.decode("ascii", "strict")
                if "-----BEGIN CERTIFICATE-----" in pem:
                    pem_parts.append(pem)
            if pem_parts:
                context.load_verify_locations(cadata="\n".join(pem_parts))
            if context.cert_store_stats().get("x509_ca", 0) < 1:
                raise ConfigurationError(
                    "macOS system trust store is unavailable; HTTPS verification "
                    "cannot continue"
                )
        _HTTPS_CONTEXT = context
        return context


class _PolicyRedirectHandler(urllib.request.HTTPRedirectHandler):
    def __init__(self, policy: NetworkHostPolicy):
        super().__init__()
        self.policy = policy

    def redirect_request(
        self,
        req: urllib.request.Request,
        fp: Any,
        code: int,
        msg: str,
        newurl: str,
    ) -> urllib.request.Request:
        source = self.policy.validate(req.full_url)
        target_url = urllib.parse.urljoin(req.full_url, newurl)
        target = self.policy.validate(target_url)
        redirect_dict = getattr(req, "redirect_dict", {})
        if target_url in redirect_dict or len(redirect_dict) >= 10:
            raise VerificationError(f"{self.policy.name} redirect loop detected")
        headers = dict(req.header_items())
        if (
            source.hostname != target.hostname
            and target.hostname not in self.policy.credentialed_redirect_hosts
        ):
            headers = {
                key: value
                for key, value in headers.items()
                if key.lower() not in _SENSITIVE_REDIRECT_HEADERS
            }
        method = req.get_method()
        data = req.data
        if code in {301, 302, 303} and method not in {"GET", "HEAD"}:
            method = "GET"
            data = None
            headers = {
                key: value
                for key, value in headers.items()
                if key.lower() not in {"content-length", "content-type"}
            }
        return urllib.request.Request(
            target_url,
            data=data,
            headers=headers,
            origin_req_host=req.origin_req_host,
            unverifiable=True,
            method=method,
        )


def open_verified_url(
    request: urllib.request.Request,
    *,
    timeout: float,
    policy: NetworkHostPolicy | None = None,
) -> Any:
    if policy is None:
        return urllib.request.urlopen(
            request,
            timeout=timeout,
            context=_https_context(),
        )
    policy.validate(request.full_url)
    opener = urllib.request.build_opener(
        _PolicyRedirectHandler(policy),
        urllib.request.HTTPSHandler(context=_https_context()),
    )
    return opener.open(request, timeout=timeout)


def _credential_helper() -> str:
    override = os.environ.get("MEMORY_VAULT_CREDENTIAL_HELPER")
    if override:
        return override
    if sys.platform == "darwin":
        return "osxkeychain"
    if os.name == "nt":
        return "manager"
    return "libsecret"


def credential_get(host: str, username: str | None = None) -> dict[str, str]:
    request = [f"protocol=https", f"host={host}"]
    if username:
        request.append(f"username={username}")
    payload = ("\n".join(request) + "\n\n").encode("utf-8")
    result = run_process(
        [
            "git",
            "-c",
            f"credential.helper={_credential_helper()}",
            "credential",
            "fill",
        ],
        input_bytes=payload,
        timeout=10,
        sensitive_output=True,
    )
    fields: dict[str, str] = {}
    for raw_line in result.stdout.decode("utf-8", "strict").splitlines():
        if "=" in raw_line:
            key, field_value = raw_line.split("=", 1)
            fields[key] = field_value
    if not fields.get("password"):
        raise AuthenticationError(f"no credential is stored for {host}")
    return fields


def credential_store(host: str, username: str, password: str) -> None:
    if "\n" in host + username + password or "\x00" in host + username + password:
        raise PrivacyError("credential fields contain forbidden characters")
    payload = (
        f"protocol=https\nhost={host}\nusername={username}\npassword={password}\n\n"
    ).encode("utf-8")
    run_process(
        [
            "git",
            "-c",
            f"credential.helper={_credential_helper()}",
            "credential",
            "approve",
        ],
        input_bytes=payload,
        timeout=10,
        sensitive_output=True,
    )


def credential_erase(host: str, username: str) -> None:
    if "\n" in host + username or "\x00" in host + username:
        raise PrivacyError("credential fields contain forbidden characters")
    payload = (
        f"protocol=https\nhost={host}\nusername={username}\n\n"
    ).encode("utf-8")
    run_process(
        [
            "git",
            "-c",
            f"credential.helper={_credential_helper()}",
            "credential",
            "reject",
        ],
        input_bytes=payload,
        timeout=10,
        sensitive_output=True,
    )


class FileLock:
    """Cross-platform non-blocking advisory file lock."""

    def __init__(self, path: Path):
        self.path = path
        self.stream: Any = None

    def __enter__(self) -> "FileLock":
        ensure_private_dir(self.path.parent)
        if self.path.exists():
            assert_plain_path(self.path, require_file=True)
        flags = (
            os.O_RDWR
            | os.O_CREAT
            | getattr(os, "O_BINARY", 0)
            | getattr(os, "O_NOFOLLOW", 0)
            | getattr(os, "O_NOINHERIT", 0)
        )
        try:
            descriptor = os.open(self.path, flags, 0o600)
        except OSError as exc:
            raise PrivacyError("lock file could not be opened safely") from exc
        self.stream = os.fdopen(descriptor, "r+b")
        try:
            opened = os.fstat(self.stream.fileno())
            named = self.path.lstat()
        except OSError as exc:
            self.stream.close()
            self.stream = None
            raise PrivacyError("lock file changed while it was opened") from exc
        if (
            not stat.S_ISREG(opened.st_mode)
            or int(getattr(opened, "st_nlink", 1)) != 1
            or self.path.is_symlink()
            or _is_reparse_point(self.path)
            or (
                getattr(opened, "st_ino", 0)
                and getattr(named, "st_ino", 0)
                and opened.st_ino != named.st_ino
            )
        ):
            self.stream.close()
            self.stream = None
            raise PrivacyError("lock file is not a stable regular file")
        try:
            if hasattr(os, "fchmod"):
                os.fchmod(self.stream.fileno(), 0o600)
            else:
                _safe_chmod(self.path, 0o600)
            opened_again = os.fstat(self.stream.fileno())
            named_again = self.path.lstat()
        except OSError as exc:
            self.stream.close()
            self.stream = None
            raise PrivacyError("lock file changed before initialization") from exc
        if (
            not stat.S_ISREG(opened_again.st_mode)
            or int(getattr(opened_again, "st_nlink", 1)) != 1
            or self.path.is_symlink()
            or _is_reparse_point(self.path)
            or (
                getattr(opened_again, "st_ino", 0)
                and getattr(named_again, "st_ino", 0)
                and opened_again.st_ino != named_again.st_ino
            )
        ):
            self.stream.close()
            self.stream = None
            raise PrivacyError("lock file changed before initialization")
        try:
            if os.fstat(self.stream.fileno()).st_size == 0:
                self.stream.write(b"\0")
                self.stream.flush()
                os.fsync(self.stream.fileno())
            self.stream.seek(0)
            if os.name == "nt":
                import msvcrt

                msvcrt.locking(self.stream.fileno(), msvcrt.LK_NBLCK, 1)
            else:
                import fcntl

                fcntl.flock(self.stream.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
        except (OSError, BlockingIOError) as exc:
            self.stream.close()
            self.stream = None
            raise BusyError("another Memory Vault hook is already running") from exc
        return self

    def __exit__(self, exc_type: Any, exc: Any, traceback: Any) -> None:
        if self.stream is None:
            return
        with contextlib.suppress(OSError):
            if os.name == "nt":
                import msvcrt

                self.stream.seek(0)
                msvcrt.locking(self.stream.fileno(), msvcrt.LK_UNLCK, 1)
            else:
                import fcntl

                fcntl.flock(self.stream.fileno(), fcntl.LOCK_UN)
        self.stream.close()
        self.stream = None


def _parse_semver(
    value: Any,
) -> tuple[tuple[int, int, int], tuple[tuple[int, int | str], ...] | None]:
    if not isinstance(value, str) or len(value) > 128:
        raise VerificationError("plugin version is not valid semantic versioning")
    match = SEMVER_RE.fullmatch(value)
    if match is None:
        raise VerificationError("plugin version is not valid semantic versioning")
    prerelease_text = match.group("prerelease")
    prerelease: tuple[tuple[int, int | str], ...] | None = None
    if prerelease_text is not None:
        tokens: list[tuple[int, int | str]] = []
        for token in prerelease_text.split("."):
            if token.isdigit():
                if len(token) > 1 and token.startswith("0"):
                    raise VerificationError(
                        "numeric prerelease identifiers cannot have leading zeroes"
                    )
                tokens.append((0, int(token)))
            else:
                tokens.append((1, token))
        prerelease = tuple(tokens)
    return (
        (
            int(match.group("major")),
            int(match.group("minor")),
            int(match.group("patch")),
        ),
        prerelease,
    )


def compare_semver(left: Any, right: Any) -> int:
    left_base, left_pre = _parse_semver(left)
    right_base, right_pre = _parse_semver(right)
    if left_base != right_base:
        return 1 if left_base > right_base else -1
    if left_pre is None and right_pre is None:
        return 0
    if left_pre is None:
        return 1
    if right_pre is None:
        return -1
    for left_item, right_item in zip(left_pre, right_pre):
        if left_item == right_item:
            continue
        if left_item[0] != right_item[0]:
            return -1 if left_item[0] == 0 else 1
        return 1 if left_item[1] > right_item[1] else -1
    if len(left_pre) == len(right_pre):
        return 0
    return 1 if len(left_pre) > len(right_pre) else -1


def _deployment_marketplace_identity() -> str:
    github = GITHUB_REPO_RE.fullmatch(DEPLOYMENT_DEFAULT_REPO_URL)
    if github is not None:
        return (
            "github.com/"
            f"{github.group('owner')}/{github.group('repo')}"
        ).lower()
    gitlab = GITLAB_HTTPS_REPO_RE.fullmatch(DEPLOYMENT_DEFAULT_REPO_URL)
    if gitlab is not None:
        return (
            "gitlab.com/"
            f"{gitlab.group('namespace')}/{gitlab.group('repo')}"
        ).lower()
    raise VerificationError("deployment marketplace URL is unsupported")


def _marketplace_repository_identity(value: Any) -> str:
    if not isinstance(value, str) or not value.strip():
        raise VerificationError("plugin marketplace source is missing")
    text = value.strip()
    matched = GITHUB_REPO_RE.fullmatch(text)
    if matched is not None:
        return (
            "github.com/"
            f"{matched.group('owner')}/{matched.group('repo')}"
        ).lower()
    gitlab = GITLAB_HTTPS_REPO_RE.fullmatch(text)
    if gitlab is not None:
        return (
            "gitlab.com/"
            f"{gitlab.group('namespace')}/{gitlab.group('repo')}"
        ).lower()
    simple = re.fullmatch(
        r"(?P<path>[A-Za-z0-9_.-]+(?:/[A-Za-z0-9_.-]+)+)"
        r"(?:@[^/@\s]+)?",
        text,
    )
    if simple is None:
        raise VerificationError("plugin marketplace source is unsupported")
    deployment_host = _deployment_marketplace_identity().split("/", 1)[0]
    path = simple.group("path")
    if path.lower().endswith(".git"):
        path = path[:-4]
    return f"{deployment_host}/{path}".lower()


def _github_repository_identity(value: Any) -> str:
    """Compatibility helper retained for existing diagnostics and tests."""

    identity = _marketplace_repository_identity(value)
    if not identity.startswith("github.com/"):
        raise VerificationError("plugin marketplace is not a GitHub source")
    return identity.removeprefix("github.com/")


def _load_update_state(data_dir: Path) -> Mapping[str, Any] | None:
    path = data_dir / "updates" / "state.json"
    if not path.exists():
        return None
    assert_plain_path(path, require_file=True)
    value = load_json(path)
    if (
        not isinstance(value, Mapping)
        or value.get("schema_version") != UPDATE_STATE_SCHEMA
    ):
        raise ConfigurationError("local plugin update state is invalid")
    return value


def _signed_update_trust_path(data_dir: Path) -> Path:
    return data_dir / "updates" / SIGNED_UPDATE_TRUST_FILENAME


def _load_signed_update_trust_store(
    data_dir: Path,
) -> Mapping[str, Any] | None:
    path = _signed_update_trust_path(data_dir)
    try:
        path.lstat()
    except FileNotFoundError:
        return None
    except OSError as exc:
        raise VerificationError(
            "signed update trust store identity is unavailable"
        ) from exc
    try:
        raw = read_trust_store_file(path)
        value = strict_json_loads(raw.decode("utf-8"))
        return validate_signed_update_trust_store(value)
    except (
        SignedUpdateError,
        UnicodeDecodeError,
        ValueError,
        json.JSONDecodeError,
    ) as exc:
        raise VerificationError(
            "signed update trust store is invalid"
        ) from exc


def _persist_signed_update_trust_store(
    data_dir: Path,
    value: Mapping[str, Any],
) -> Mapping[str, Any]:
    try:
        validated = validate_signed_update_trust_store(value)
        raw = pretty_json_bytes(validated)
    except (SignedUpdateError, TypeError, ValueError) as exc:
        raise VerificationError(
            "signed update trust state could not be persisted"
        ) from exc
    if len(raw) > MAX_TRUST_STORE_BYTES:
        raise VerificationError("signed update trust state is too large")
    atomic_write_bytes(_signed_update_trust_path(data_dir), raw)
    reloaded = _load_signed_update_trust_store(data_dir)
    if reloaded is None or dict(reloaded) != validated:
        raise VerificationError(
            "signed update trust state failed atomic verification"
        )
    return reloaded


def update_trust_status_command(data_dir: Path) -> Mapping[str, Any]:
    return signed_update_trust_summary(
        _load_signed_update_trust_store(data_dir),
        now_epoch=int(time.time()),
    )


def _signed_update_trust_report(data_dir: Path) -> Mapping[str, Any]:
    try:
        return update_trust_status_command(data_dir)
    except (VaultSyncError, OSError, ValueError):
        return {
            "schema_version": "memory-vault-update-trust-summary/v1",
            "required": True,
            "profile": None,
            "mode": "signed-metadata-invalid-fail-closed",
            "valid": False,
            "root_version": None,
            "root_sha256": None,
            "root_expires": None,
            "root_expired": None,
            "metadata_versions": None,
            "last_target": None,
            "last_verified_at": None,
            "private_keys_imported": False,
        }


def configure_update_trust_command(
    args: argparse.Namespace,
    data_dir: Path,
) -> Mapping[str, Any]:
    try:
        # Keep the lexical final component so the stable reader can reject a
        # symlink instead of silently following it through ``resolve``.
        source = Path(os.path.abspath(args.root_file.expanduser()))
        raw = read_signed_metadata_file(source)
        trust_store = import_trusted_root(
            raw,
            now_epoch=int(time.time()),
        )
    except (SignedUpdateError, OSError) as exc:
        raise VerificationError(
            "initial signed update root is invalid or expired"
        ) from exc
    path = _signed_update_trust_path(data_dir)
    with FileLock(data_dir / "locks" / "plugin-update.lock"):
        try:
            path.lstat()
        except FileNotFoundError:
            pass
        except OSError as exc:
            raise VerificationError(
                "signed update trust store identity is unavailable"
            ) from exc
        else:
            raise ConflictError(
                "signed update trust is already configured and cannot be overwritten"
            )
        verified = _persist_signed_update_trust_store(
            data_dir,
            trust_store,
        )
    result = dict(
        signed_update_trust_summary(
            verified,
            now_epoch=int(time.time()),
        )
    )
    result["status"] = "trusted_root_imported"
    return result


def _trusted_codex_executable(
    config: Mapping[str, Any],
    data_dir: Path,
) -> Path:
    updates = config["updates"]
    configured = updates.get("codex_executable")
    candidates: list[Path] = []
    if isinstance(configured, str):
        candidates.append(Path(configured))
    if sys.platform == "darwin":
        candidates.append(
            Path("/Applications/ChatGPT.app/Contents/Resources/codex")
        )
    for name in ("codex.exe", "codex"):
        discovered = shutil.which(name)
        if discovered:
            candidates.append(Path(discovered))

    forbidden_roots = [data_dir.resolve()]
    for raw_root in config["privacy"].get("allowed_roots", []):
        if isinstance(raw_root, str) and Path(raw_root).is_absolute():
            forbidden_roots.append(Path(raw_root).resolve())
    with contextlib.suppress(OSError):
        forbidden_roots.append(Path(tempfile.gettempdir()).resolve())

    tested: set[str] = set()
    for candidate in candidates:
        try:
            resolved = candidate.expanduser().resolve(strict=True)
        except OSError:
            continue
        normalized = os.path.normcase(str(resolved))
        if normalized in tested:
            continue
        tested.add(normalized)
        try:
            assert_plain_path(resolved, require_file=True)
        except VaultSyncError:
            continue
        if any(_path_is_within(resolved, root) for root in forbidden_roots):
            continue
        file_mode = resolved.stat().st_mode
        if not stat.S_ISREG(file_mode):
            continue
        if os.name != "nt" and (
            not os.access(resolved, os.X_OK)
            or file_mode & (stat.S_IWGRP | stat.S_IWOTH)
        ):
            continue
        if os.environ.get("MEMORY_VAULT_SYNC_TESTING") == "1":
            return resolved
        try:
            if sys.platform == "darwin":
                run_process(
                    [
                        "/usr/bin/codesign",
                        "--verify",
                        "--strict",
                        str(resolved),
                    ],
                    timeout=10,
                    sensitive_output=True,
                )
                details = run_process(
                    [
                        "/usr/bin/codesign",
                        "-dv",
                        "--verbose=4",
                        str(resolved),
                    ],
                    timeout=10,
                    sensitive_output=True,
                ).stderr.decode("utf-8", "replace")
                if (
                    "Identifier=codex" not in details
                    or "TeamIdentifier=2DC432GLL2" not in details
                ):
                    continue
            elif os.name == "nt":
                if resolved.suffix.lower() != ".exe":
                    continue
                system_root = os.environ.get("SystemRoot")
                host = os.environ.get("MEMORY_VAULT_POWERSHELL_HOST")
                if not host and system_root:
                    host = str(
                        Path(system_root)
                        / "System32"
                        / "WindowsPowerShell"
                        / "v1.0"
                        / "powershell.exe"
                    )
                if not host:
                    continue
                host_path = Path(host).resolve(strict=True)
                assert_plain_path(host_path, require_file=True)
                verification_script = (
                    "$signature=Microsoft.PowerShell.Security\\"
                    "Get-AuthenticodeSignature -LiteralPath "
                    "$env:MEMORY_VAULT_CODEX_EXE_TO_VERIFY;"
                    "if ($signature.Status -ne 'Valid') { exit 31 };"
                    "if ($signature.SignerCertificate.Subject -notmatch "
                    "'OpenAI') { exit 32 }"
                )
                run_process(
                    [
                        str(host_path),
                        "-NoProfile",
                        "-NonInteractive",
                        "-Command",
                        verification_script,
                    ],
                    timeout=15,
                    sensitive_output=True,
                    extra_environment={
                        "MEMORY_VAULT_CODEX_EXE_TO_VERIFY": str(resolved)
                    },
                )
        except (OSError, VaultSyncError):
            continue
        return resolved
    raise ConfigurationError(
        "a trusted Codex executable is unavailable for automatic updates"
    )


class PluginUpdater:
    """Bounded, downgrade-safe updater for the private Git marketplace."""

    def __init__(self, config: Mapping[str, Any], data_dir: Path):
        self.config = validate_config(dict(config))
        self.update_config = self.config["updates"]
        self.data_dir = data_dir.resolve()
        self.state_path = self.data_dir / "updates" / "state.json"
        self.lock_path = self.data_dir / "locks" / "plugin-update.lock"

    def _codex_json(
        self,
        executable: Path,
        arguments: Sequence[str],
        *,
        timeout: float = 30,
    ) -> Mapping[str, Any]:
        result = run_process(
            [str(executable), *arguments],
            timeout=timeout,
            sensitive_output=True,
            inherit_git_environment=True,
        )
        if len(result.stdout) > MAX_CODEX_JSON_BYTES:
            raise VerificationError("Codex plugin output exceeds the fixed limit")
        try:
            decoded = result.stdout.decode("utf-8")
            value = strict_json_loads(decoded)
        except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
            raise VerificationError(
                "Codex plugin command returned invalid JSON"
            ) from exc
        if not isinstance(value, Mapping):
            raise VerificationError("Codex plugin command returned no object")
        return value

    def _marketplace(
        self,
        executable: Path,
    ) -> tuple[Path, str]:
        value = self._codex_json(
            executable,
            ["plugin", "marketplace", "list", "--json"],
        )
        items = value.get("marketplaces")
        if not isinstance(items, list):
            raise VerificationError("Codex marketplace list is invalid")
        matches = [
            item
            for item in items
            if isinstance(item, Mapping)
            and item.get("name") == MARKETPLACE_NAME
        ]
        if len(matches) != 1:
            raise VerificationError(
                "the private Memory Vault marketplace is not uniquely configured"
            )
        item = matches[0]
        raw_root = item.get("root")
        source = item.get("marketplaceSource")
        if (
            not isinstance(raw_root, str)
            or not Path(raw_root).is_absolute()
            or not isinstance(source, Mapping)
        ):
            raise VerificationError("the private marketplace metadata is incomplete")
        root = Path(raw_root).resolve(strict=True)
        assert_plain_path(root, require_file=False)
        source_type = source.get("sourceType")
        expected_identity = _deployment_marketplace_identity()
        if source_type == "git":
            identity = _marketplace_repository_identity(source.get("source"))
            if identity != expected_identity:
                raise VerificationError(
                    "automatic updates refused an unexpected Git marketplace"
                )
        elif source_type == "local":
            remote = run_process(
                ["git", "-C", str(root), "remote", "get-url", "origin"],
                timeout=10,
                sensitive_output=True,
            ).stdout.decode("utf-8", "strict").strip()
            if _marketplace_repository_identity(remote) != expected_identity:
                raise VerificationError(
                    "automatic updates refused an unexpected local marketplace"
                )
        else:
            raise VerificationError(
                "automatic updates require a Git or verified local marketplace"
            )
        dirty = run_process(
            [
                "git",
                "-C",
                str(root),
                "status",
                "--porcelain",
                "--untracked-files=all",
                "--",
                ".agents/plugins/marketplace.json",
                f"plugins/{PLUGIN_NAME}",
            ],
            timeout=10,
            sensitive_output=True,
        ).stdout
        if dirty:
            raise ConflictError(
                "automatic updates refuse a modified plugin marketplace"
            )
        return root, str(source_type)

    def _candidate(
        self,
        root: Path,
    ) -> Mapping[str, Any]:
        lexical_plugin_root = root / "plugins" / PLUGIN_NAME
        assert_plain_path(lexical_plugin_root, require_file=False)
        plugin_root = lexical_plugin_root.resolve(strict=True)
        if not _path_is_within(plugin_root, root):
            raise PrivacyError("plugin update package escapes the marketplace")
        commit_before = run_process(
            ["git", "-C", str(root), "rev-parse", "HEAD"],
            timeout=10,
            sensitive_output=True,
        ).stdout.decode("ascii", "strict").strip()
        validate_git_sha(commit_before, "marketplace commit")
        manifest_path = plugin_root / ".codex-plugin" / "plugin.json"
        assert_plain_path(manifest_path, require_file=True)
        resolved_manifest = manifest_path.resolve(strict=True)
        if (
            not _path_is_within(resolved_manifest, root)
            or os.path.normcase(str(resolved_manifest))
            != os.path.normcase(str(Path(os.path.abspath(manifest_path))))
        ):
            raise PrivacyError("plugin update manifest escapes the marketplace")
        manifest_bytes = _read_bounded_plain_runtime_file(
            resolved_manifest,
            maximum_bytes=64 * 1024,
            label="plugin update manifest",
        )
        try:
            manifest = strict_json_loads(manifest_bytes.decode("utf-8"))
        except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
            raise VerificationError("plugin update manifest is invalid") from exc
        if (
            not isinstance(manifest, Mapping)
            or manifest.get("name") != PLUGIN_NAME
            or not isinstance(manifest.get("author"), Mapping)
            or manifest["author"].get("name") != PLUGIN_AUTHOR
        ):
            raise VerificationError("plugin update manifest identity is invalid")
        version = manifest.get("version")
        _parse_semver(version)
        required = (
            "hooks/hooks.json",
            *(spec.path for spec in RUNTIME_FILE_SPECS),
            "skills/sync-memory-vault/SKILL.md",
        )
        digest = hashlib.sha256()
        digest.update(manifest_bytes)
        bundle_length = len(manifest_bytes)
        runtime_limits = {
            spec.path: spec.maximum_bytes for spec in RUNTIME_FILE_SPECS
        }
        candidate_runtime_files: dict[str, bytes] = {}
        for relative in required:
            path = plugin_root / PurePosixPath(relative)
            assert_plain_path(path, require_file=True)
            resolved = path.resolve(strict=True)
            if (
                not _path_is_within(resolved, plugin_root)
                or os.path.normcase(str(resolved))
                != os.path.normcase(str(Path(os.path.abspath(path))))
            ):
                raise PrivacyError("plugin update file escapes the package")
            content = _read_bounded_plain_runtime_file(
                resolved,
                maximum_bytes=runtime_limits.get(
                    relative,
                    4 * 1024 * 1024,
                ),
                label="plugin update file",
            )
            relative_bytes = relative.encode("utf-8")
            digest.update(relative_bytes)
            digest.update(b"\0")
            digest.update(content)
            bundle_length += len(relative_bytes) + 1 + len(content)
            if relative.startswith("scripts/"):
                candidate_runtime_files[relative] = content
        if _runtime_bundle_versions(candidate_runtime_files) != (
            version,
            version,
        ):
            raise VerificationError(
                "candidate manifest and runtime versions do not match"
            )
        commit = run_process(
            ["git", "-C", str(root), "rev-parse", "HEAD"],
            timeout=10,
            sensitive_output=True,
        ).stdout.decode("ascii", "strict").strip()
        validate_git_sha(commit, "marketplace commit")
        if commit != commit_before:
            raise ConflictError(
                "plugin marketplace changed while the candidate was verified"
            )
        dirty = run_process(
            [
                "git",
                "-C",
                str(root),
                "status",
                "--porcelain",
                "--untracked-files=all",
                "--",
                ".agents/plugins/marketplace.json",
                f"plugins/{PLUGIN_NAME}",
            ],
            timeout=10,
            sensitive_output=True,
        ).stdout
        if dirty:
            raise ConflictError(
                "plugin marketplace changed while the candidate was verified"
            )
        return {
            "version": version,
            "bundle_sha256": digest.hexdigest(),
            "bundle_length": bundle_length,
            "commit_sha": commit,
            "plugin_root": str(plugin_root),
        }

    def _verify_signed_release_commit(
        self,
        root: Path,
        *,
        signed_commit: str,
        observed_commit: str,
    ) -> None:
        signed_commit = validate_git_sha(
            signed_commit,
            "signed marketplace release commit",
        )
        observed_commit = validate_git_sha(
            observed_commit,
            "observed marketplace commit",
        )
        try:
            run_process(
                [
                    "git",
                    "-C",
                    str(root),
                    "cat-file",
                    "-e",
                    f"{signed_commit}^{{commit}}",
                ],
                timeout=10,
                sensitive_output=True,
            )
            run_process(
                [
                    "git",
                    "-C",
                    str(root),
                    "merge-base",
                    "--is-ancestor",
                    signed_commit,
                    observed_commit,
                ],
                timeout=10,
                sensitive_output=True,
            )
            run_process(
                [
                    "git",
                    "-C",
                    str(root),
                    "diff",
                    "--quiet",
                    signed_commit,
                    observed_commit,
                    "--",
                    ".agents/plugins/marketplace.json",
                    f"plugins/{PLUGIN_NAME}",
                ],
                timeout=10,
                sensitive_output=True,
            )
        except VaultSyncError as exc:
            raise VerificationError(
                "signed release commit does not identify the observed plugin tree"
            ) from exc

    def _verify_release_commit_still_identifies_candidate(
        self,
        root: Path,
        *,
        release_commit: str,
        observed_commit: str,
    ) -> bool:
        """Allow data-only descendants while pinning the released plugin tree."""

        release_commit = validate_git_sha(
            release_commit,
            "stable runtime release commit",
        )
        observed_commit = validate_git_sha(
            observed_commit,
            "observed marketplace commit",
        )
        if release_commit == observed_commit:
            return True
        try:
            run_process(
                [
                    "git",
                    "-C",
                    str(root),
                    "cat-file",
                    "-e",
                    f"{release_commit}^{{commit}}",
                ],
                timeout=10,
                sensitive_output=True,
            )
            run_process(
                [
                    "git",
                    "-C",
                    str(root),
                    "merge-base",
                    "--is-ancestor",
                    release_commit,
                    observed_commit,
                ],
                timeout=10,
                sensitive_output=True,
            )
            run_process(
                [
                    "git",
                    "-C",
                    str(root),
                    "diff",
                    "--quiet",
                    release_commit,
                    observed_commit,
                    "--",
                    ".agents/plugins/marketplace.json",
                    f"plugins/{PLUGIN_NAME}",
                ],
                timeout=10,
                sensitive_output=True,
            )
        except VaultSyncError:
            return False
        return True

    def _verify_signed_candidate(
        self,
        root: Path,
        candidate: Mapping[str, Any],
        *,
        now: int,
    ) -> Mapping[str, Any]:
        trust_store = _load_signed_update_trust_store(self.data_dir)
        if trust_store is None:
            return {
                "required": False,
                "identity_commit_sha": str(candidate["commit_sha"]),
                "target": None,
            }
        try:
            result = verify_update_chain(
                root / SIGNED_UPDATE_METADATA_DIRECTORY,
                trust_store,
                candidate,
                plugin_name=PLUGIN_NAME,
                now_epoch=now,
            )
        except SignedUpdateError as exc:
            raise VerificationError(
                "signed update metadata verification failed"
            ) from exc
        target = result["target"]
        if not isinstance(target, Mapping):
            raise VerificationError("signed update target is missing")
        previous_target = trust_store.get("last_target")
        if isinstance(previous_target, Mapping):
            version_comparison = compare_semver(
                candidate["version"],
                previous_target.get("plugin_version"),
            )
            if version_comparison < 0:
                raise VerificationError(
                    "signed plugin target version rollback was refused"
                )
            if version_comparison == 0 and any(
                target.get(key) != previous_target.get(key)
                for key in (
                    "bundle_sha256",
                    "bundle_length",
                    "marketplace_commit_sha",
                )
            ):
                raise VerificationError(
                    "signed same-version plugin identity changed"
                )
        signed_commit = str(target["marketplace_commit_sha"])
        self._verify_signed_release_commit(
            root,
            signed_commit=signed_commit,
            observed_commit=str(candidate["commit_sha"]),
        )
        persisted = _persist_signed_update_trust_store(
            self.data_dir,
            result["trust_store"],
        )
        return {
            "required": True,
            "identity_commit_sha": signed_commit,
            "target": target,
            "trust_store": persisted,
            "root_rotations": int(result["root_rotations"]),
        }

    def _assert_candidate_unchanged(
        self,
        root: Path,
        candidate: Mapping[str, Any],
    ) -> None:
        repeated = self._candidate(root)
        identity_fields = (
            "version",
            "bundle_sha256",
            "bundle_length",
            "commit_sha",
            "plugin_root",
        )
        if any(
            repeated.get(key) != candidate.get(key)
            for key in identity_fields
        ):
            raise ConflictError(
                "plugin update candidate changed after verification"
            )

    def _installed(
        self,
        executable: Path,
    ) -> Mapping[str, Any] | None:
        value = self._codex_json(
            executable,
            ["plugin", "list", "--json"],
        )
        items = value.get("installed")
        if not isinstance(items, list):
            raise VerificationError("Codex installed plugin list is invalid")
        matches = [
            item
            for item in items
            if isinstance(item, Mapping)
            and item.get("pluginId") == f"{PLUGIN_NAME}@{MARKETPLACE_NAME}"
        ]
        if len(matches) > 1:
            raise VerificationError("installed Memory Vault plugin is ambiguous")
        return matches[0] if matches else None

    def _store(
        self,
        *,
        status: str,
        now: int,
        available_version: str | None = None,
        installed_version: str | None = None,
        bundle_sha256: str | None = None,
        commit_sha: str | None = None,
        activated_runtime_version: str | None = None,
        error_code: str | None = None,
        identity_issue: str | None = None,
        retry_seconds: int | None = None,
    ) -> Mapping[str, Any]:
        interval = (
            retry_seconds
            if retry_seconds is not None
            else int(self.update_config["check_interval_seconds"])
        )
        state = {
            "schema_version": UPDATE_STATE_SCHEMA,
            "status": status,
            "running_version": VERSION,
            "available_version": available_version,
            "installed_version": installed_version,
            "bundle_sha256": bundle_sha256,
            "marketplace_commit_sha": commit_sha,
            "activated_runtime_version": activated_runtime_version,
            "last_error_code": error_code,
            "identity_issue": identity_issue,
            "checked_at": utc_now(),
            "checked_at_epoch": now,
            "next_check_after_epoch": now + interval,
        }
        atomic_write_json(self.state_path, state)
        return state

    def _check_locked(
        self,
        *,
        force: bool,
        check_only: bool,
    ) -> Mapping[str, Any]:
        now = int(time.time())
        previous: Mapping[str, Any] | None = None
        with contextlib.suppress(VaultSyncError, OSError, ValueError):
            previous = _load_update_state(self.data_dir)
        if not force and previous is not None:
            next_check = previous.get("next_check_after_epoch")
            if (
                isinstance(next_check, int)
                and now < next_check
                and next_check - now <= MAX_UPDATE_INTERVAL_SECONDS
            ):
                return {
                    "schema_version": UPDATE_STATE_SCHEMA,
                    "status": "not_due",
                    "running_version": VERSION,
                    "available_version": previous.get("available_version"),
                    "installed_version": previous.get("installed_version"),
                    "next_check_after_epoch": next_check,
                }

        executable = _trusted_codex_executable(self.config, self.data_dir)
        root, source_type = self._marketplace(executable)
        if source_type == "git":
            run_process(
                [
                    str(executable),
                    "plugin",
                    "marketplace",
                    "upgrade",
                    MARKETPLACE_NAME,
                    "--json",
                ],
                timeout=60,
                sensitive_output=True,
                inherit_git_environment=True,
            )
            root, verified_type = self._marketplace(executable)
            if verified_type != "git":
                raise VerificationError(
                    "the marketplace source changed during update"
                )
        candidate = self._candidate(root)
        signed_identity = self._verify_signed_candidate(
            root,
            candidate,
            now=now,
        )
        identity_commit = str(signed_identity["identity_commit_sha"])
        available_version = str(candidate["version"])
        comparison = compare_semver(available_version, VERSION)
        installed = self._installed(executable)
        installed_version = (
            str(installed.get("version"))
            if isinstance(installed, Mapping)
            and isinstance(installed.get("version"), str)
            else None
        )
        if comparison < 0:
            return self._store(
                status="remote_older_refused",
                now=now,
                available_version=available_version,
                installed_version=installed_version,
                bundle_sha256=str(candidate["bundle_sha256"]),
                commit_sha=identity_commit,
            )
        if comparison == 0:
            candidate_bundle = str(candidate["bundle_sha256"])
            candidate_commit = identity_commit
            active_identity = _load_verified_stable_runtime_identity(
                self.data_dir
            )
            if active_identity is None:
                installed_source = (
                    installed.get("source")
                    if isinstance(installed, Mapping)
                    else None
                )
                installed_path_value = (
                    installed.get("installPath")
                    if isinstance(installed, Mapping)
                    else None
                )
                if (
                    not isinstance(installed_path_value, str)
                    and isinstance(installed_source, Mapping)
                    and installed_source.get("source") == "local"
                ):
                    installed_path_value = installed_source.get("path")
                installed_path: Path | None = None
                if (
                    isinstance(installed_path_value, str)
                    and Path(installed_path_value).is_absolute()
                ):
                    installed_lexical_path = Path(installed_path_value)
                    if (
                        not installed_lexical_path.is_symlink()
                        and not _is_reparse_point(installed_lexical_path)
                    ):
                        with contextlib.suppress(OSError):
                            installed_path = installed_lexical_path.resolve(
                                strict=True
                            )
                candidate_lexical_path = Path(
                    str(candidate["plugin_root"])
                )
                try:
                    candidate_path = candidate_lexical_path.resolve(
                        strict=True
                    )
                except OSError:
                    return self._store(
                        status="identity_unverified",
                        now=now,
                        available_version=available_version,
                        installed_version=installed_version,
                        bundle_sha256=candidate_bundle,
                        commit_sha=candidate_commit,
                        error_code="same_version_identity_unverified",
                        identity_issue=(
                            "active_runtime_identity_missing_or_invalid"
                        ),
                    )
                candidate_path_is_plain = (
                    not candidate_lexical_path.is_symlink()
                    and not _is_reparse_point(candidate_lexical_path)
                )
                installed_identity_matches = (
                    isinstance(installed, Mapping)
                    and installed.get("version") == available_version
                    and installed.get("enabled") is True
                    and installed_path == candidate_path
                    and candidate_path_is_plain
                )
                if not installed_identity_matches:
                    return self._store(
                        status="identity_unverified",
                        now=now,
                        available_version=available_version,
                        installed_version=installed_version,
                        bundle_sha256=candidate_bundle,
                        commit_sha=candidate_commit,
                        error_code="same_version_identity_unverified",
                        identity_issue=(
                            "active_runtime_identity_missing_or_invalid"
                        ),
                    )
                self._assert_candidate_unchanged(root, candidate)
                activated = _refresh_stable_runtime_from_plugin(
                    self.data_dir,
                    candidate_path,
                    available_version,
                    bundle_sha256=candidate_bundle,
                    marketplace_commit_sha=candidate_commit,
                )
                return self._store(
                    status="identity_bootstrapped",
                    now=now,
                    available_version=available_version,
                    installed_version=installed_version,
                    bundle_sha256=candidate_bundle,
                    commit_sha=candidate_commit,
                    activated_runtime_version=str(
                        activated["plugin_version"]
                    ),
                )
            if active_identity["plugin_version"] != available_version:
                if (
                    compare_semver(
                        active_identity["plugin_version"],
                        available_version,
                    )
                    >= 0
                ):
                    return self._store(
                        status="identity_mismatch",
                        now=now,
                        available_version=available_version,
                        installed_version=installed_version,
                        bundle_sha256=candidate_bundle,
                        commit_sha=candidate_commit,
                        error_code="stable_runtime_version_mismatch",
                        identity_issue="active_runtime_version_not_older",
                    )
                installed_source = (
                    installed.get("source")
                    if isinstance(installed, Mapping)
                    else None
                )
                installed_path_value = (
                    installed_source.get("path")
                    if isinstance(installed_source, Mapping)
                    and installed_source.get("source") == "local"
                    else installed.get("installPath")
                    if isinstance(installed, Mapping)
                    else None
                )
                candidate_lexical_path = Path(
                    str(candidate["plugin_root"])
                )
                try:
                    installed_path = Path(
                        str(installed_path_value)
                    ).resolve(strict=True)
                    candidate_path = candidate_lexical_path.resolve(
                        strict=True
                    )
                except OSError:
                    installed_path = None
                    candidate_path = candidate_lexical_path.resolve()
                if (
                    not isinstance(installed, Mapping)
                    or installed.get("version") != available_version
                    or installed.get("enabled") is not True
                    or installed_path != candidate_path
                    or candidate_lexical_path.is_symlink()
                    or _is_reparse_point(candidate_lexical_path)
                ):
                    return self._store(
                        status="identity_unverified",
                        now=now,
                        available_version=available_version,
                        installed_version=installed_version,
                        bundle_sha256=candidate_bundle,
                        commit_sha=candidate_commit,
                        error_code="upgrade_identity_unverified",
                        identity_issue="installed_candidate_mismatch",
                    )
                self._assert_candidate_unchanged(root, candidate)
                activated = _refresh_stable_runtime_from_plugin(
                    self.data_dir,
                    candidate_path,
                    available_version,
                    bundle_sha256=candidate_bundle,
                    marketplace_commit_sha=candidate_commit,
                )
                return self._store(
                    status="new_version_already_installed",
                    now=now,
                    available_version=available_version,
                    installed_version=installed_version,
                    bundle_sha256=candidate_bundle,
                    commit_sha=candidate_commit,
                    activated_runtime_version=str(
                        activated["plugin_version"]
                    ),
                )
            if active_identity["bundle_sha256"] != candidate_bundle:
                return self._store(
                    status="identity_mismatch",
                    now=now,
                    available_version=available_version,
                    installed_version=installed_version,
                    bundle_sha256=candidate_bundle,
                    commit_sha=candidate_commit,
                    error_code="same_version_bundle_mismatch",
                    identity_issue="bundle_sha256_changed",
                )
            if active_identity["marketplace_commit_sha"] != candidate_commit:
                if bool(signed_identity.get("required")):
                    # The legacy identity records the observed repository HEAD.
                    # A signed channel may intentionally name an earlier
                    # release commit followed only by metadata/docs. The exact
                    # bundle match plus the signed ancestry/tree proof above
                    # makes this one-time identity re-anchor safe.
                    self._assert_candidate_unchanged(root, candidate)
                    activated = _refresh_stable_runtime_from_plugin(
                        self.data_dir,
                        Path(str(candidate["plugin_root"])),
                        available_version,
                        bundle_sha256=candidate_bundle,
                        marketplace_commit_sha=candidate_commit,
                    )
                    return self._store(
                        status="up_to_date",
                        now=now,
                        available_version=available_version,
                        installed_version=installed_version,
                        bundle_sha256=candidate_bundle,
                        commit_sha=candidate_commit,
                        activated_runtime_version=str(
                            activated["plugin_version"]
                        ),
                    )
                if self._verify_release_commit_still_identifies_candidate(
                    root,
                    release_commit=active_identity[
                        "marketplace_commit_sha"
                    ],
                    observed_commit=candidate_commit,
                ):
                    return self._store(
                        status="up_to_date",
                        now=now,
                        available_version=available_version,
                        installed_version=installed_version,
                        bundle_sha256=candidate_bundle,
                        commit_sha=active_identity[
                            "marketplace_commit_sha"
                        ],
                    )
                return self._store(
                    status="identity_mismatch",
                    now=now,
                    available_version=available_version,
                    installed_version=installed_version,
                    bundle_sha256=candidate_bundle,
                    commit_sha=candidate_commit,
                    error_code="same_version_commit_mismatch",
                    identity_issue="marketplace_commit_sha_changed",
                )
            return self._store(
                status="up_to_date",
                now=now,
                available_version=available_version,
                installed_version=installed_version,
                bundle_sha256=candidate_bundle,
                commit_sha=candidate_commit,
            )
        if installed_version == available_version and bool(
            installed and installed.get("enabled")
        ):
            self._assert_candidate_unchanged(root, candidate)
            activated = _refresh_stable_runtime_from_plugin(
                self.data_dir,
                Path(str(candidate["plugin_root"])),
                available_version,
                bundle_sha256=str(candidate["bundle_sha256"]),
                marketplace_commit_sha=identity_commit,
            )
            return self._store(
                status="new_version_already_installed",
                now=now,
                available_version=available_version,
                installed_version=installed_version,
                bundle_sha256=str(candidate["bundle_sha256"]),
                commit_sha=identity_commit,
                activated_runtime_version=str(activated["plugin_version"]),
            )
        if check_only or not self.update_config.get("auto_install"):
            return self._store(
                status="update_available",
                now=now,
                available_version=available_version,
                installed_version=installed_version,
                bundle_sha256=str(candidate["bundle_sha256"]),
                commit_sha=identity_commit,
            )

        _refresh_stable_runtime(self.data_dir)
        self._assert_candidate_unchanged(root, candidate)
        self._codex_json(
            executable,
            [
                "plugin",
                "add",
                f"{PLUGIN_NAME}@{MARKETPLACE_NAME}",
                "--json",
            ],
            timeout=60,
        )
        confirmed = self._installed(executable)
        if (
            not isinstance(confirmed, Mapping)
            or confirmed.get("version") != available_version
            or confirmed.get("enabled") is not True
        ):
            raise VerificationError(
                "Codex did not confirm the requested plugin version"
            )
        self._assert_candidate_unchanged(root, candidate)
        activated = _refresh_stable_runtime_from_plugin(
            self.data_dir,
            Path(str(candidate["plugin_root"])),
            available_version,
            bundle_sha256=str(candidate["bundle_sha256"]),
            marketplace_commit_sha=identity_commit,
        )
        return self._store(
            status="updated",
            now=now,
            available_version=available_version,
            installed_version=available_version,
            bundle_sha256=str(candidate["bundle_sha256"]),
            commit_sha=identity_commit,
            activated_runtime_version=str(activated["plugin_version"]),
        )

    def check(
        self,
        *,
        force: bool = False,
        check_only: bool = False,
    ) -> Mapping[str, Any]:
        if not self.update_config.get("enabled"):
            return {
                "schema_version": UPDATE_STATE_SCHEMA,
                "status": "disabled",
                "running_version": VERSION,
            }
        try:
            with FileLock(self.lock_path):
                try:
                    return self._check_locked(
                        force=force,
                        check_only=check_only,
                    )
                except VaultSyncError as exc:
                    return self._store(
                        status="check_failed",
                        now=int(time.time()),
                        error_code=exc.code,
                        retry_seconds=FAILED_UPDATE_RETRY_SECONDS,
                    )
                except (OSError, ValueError):
                    return self._store(
                        status="check_failed",
                        now=int(time.time()),
                        error_code="internal",
                        retry_seconds=FAILED_UPDATE_RETRY_SECONDS,
                    )
        except BusyError:
            return {
                "schema_version": UPDATE_STATE_SCHEMA,
                "status": "busy",
                "running_version": VERSION,
            }


def _decorate_update_result(
    output: dict[str, Any],
    result: Mapping[str, Any] | None,
) -> dict[str, Any]:
    if result is None:
        return output
    status = result.get("status")
    if status not in {
        "updated",
        "new_version_already_installed",
        "identity_bootstrapped",
    }:
        return output
    available = result.get("available_version")
    if not isinstance(available, str):
        return output
    if status == "updated":
        notice = (
            f"Private Memory Vault automatically installed version {available}. "
            "This task remains on its verified runtime; a new task will use the "
            "updated plugin."
        )
    elif status == "new_version_already_installed":
        notice = (
            f"Private Memory Vault version {available} is already installed. "
            "A new task will use the updated plugin."
        )
    else:
        notice = (
            f"Private Memory Vault verified installed version {available} and "
            "anchored its stable runtime to the exact release identity."
        )
    existing = output.get("systemMessage")
    output["systemMessage"] = (
        f"{existing} {notice}"[:500]
        if isinstance(existing, str) and existing
        else notice[:500]
    )
    return output


@dataclasses.dataclass
class Worktree:
    git: "GitVault"
    path: Path

    def close(self) -> None:
        self.git._run_bare(["worktree", "remove", "--force", str(self.path)], timeout=30)
        self.git._run_bare(["worktree", "prune"], timeout=10)

    def __enter__(self) -> Path:
        return self.path

    def __exit__(self, exc_type: Any, exc: Any, traceback: Any) -> None:
        with contextlib.suppress(VaultSyncError):
            self.close()


class GitVault:
    def __init__(self, config: Mapping[str, Any], data_dir: Path):
        control = _control_plane_config(config)
        self.driver = str(control["driver"])
        self.profile_id = validate_identifier(
            control.get("profile_id"),
            "control-plane profile_id",
        )
        self.scope_fingerprint = validate_sha256(
            control.get("scope_fingerprint"),
            "control-plane scope fingerprint",
        )
        self.repo_url = str(control["repo_url"])
        self.branch = validate_identifier(
            control["branch"],
            "control-plane branch",
        )
        self.expected_repo = control.get("expected_repository")
        self.privacy_verifier = control.get("privacy_verifier")
        self.privacy_credential_host = str(control["credential_host"])
        self.data_dir = data_dir
        self.remote_identity = self._canonical_remote(self.repo_url)
        cache_key = sha256_bytes(self.remote_identity.encode("utf-8"))[:24]
        self.git_dir = data_dir / "g" / cache_key
        self.worktree_root = data_dir / "w"
        self.disabled_hooks = data_dir / "h"
        ensure_private_dir(self.disabled_hooks)

    @staticmethod
    def _canonical_remote(value: str) -> str:
        parsed = GITHUB_REPO_RE.fullmatch(value)
        if parsed is not None:
            if not value.startswith("https://github.com/"):
                raise PrivacyError("production vault remote must use GitHub HTTPS")
            return (
                "https://github.com/"
                f"{parsed.group('owner').lower()}/{parsed.group('repo').lower()}.git"
            )
        gitlab = GITLAB_HTTPS_REPO_RE.fullmatch(value)
        if gitlab is not None:
            return (
                "https://gitlab.com/"
                f"{gitlab.group('namespace').lower()}/"
                f"{gitlab.group('repo').lower()}.git"
            )
        if os.environ.get("MEMORY_VAULT_SYNC_TESTING") == "1":
            return str(Path(value).expanduser().resolve())
        raise PrivacyError(
            "production vault remote must be an approved HTTPS Git repository"
        )

    def _assert_cached_remote(self) -> None:
        if not self.git_dir.exists():
            return
        assert_plain_path(self.git_dir, require_file=False)
        result = self._run_bare(["config", "--get", "remote.origin.url"])
        actual = result.stdout.decode("utf-8", "strict").strip()
        if self._canonical_remote(actual) != self.remote_identity:
            raise PrivacyError("cached Git remote does not match the configured vault")

    @property
    def remote_ref(self) -> str:
        return f"refs/remotes/origin/{self.branch}"

    def _git_prefix(self) -> list[str]:
        return [
            "git",
            "-c",
            f"core.hooksPath={self.disabled_hooks}",
            "-c",
            "core.longpaths=true",
            "-c",
            "credential.helper=",
            "-c",
            f"credential.helper={_credential_helper()}",
            "-c",
            "http.followRedirects=false",
            "-c",
            "commit.gpgsign=false",
        ]

    def _run_bare(
        self,
        arguments: Sequence[str],
        *,
        input_bytes: bytes | None = None,
        timeout: float = 60,
    ) -> subprocess.CompletedProcess[bytes]:
        return run_process(
            [*self._git_prefix(), f"--git-dir={self.git_dir}", *arguments],
            input_bytes=input_bytes,
            timeout=timeout,
        )

    def _run_worktree(
        self,
        path: Path,
        arguments: Sequence[str],
        *,
        timeout: float = 60,
    ) -> subprocess.CompletedProcess[bytes]:
        return run_process(
            [*self._git_prefix(), "-C", str(path), *arguments],
            timeout=timeout,
        )

    def _test_local_allowed(self) -> bool:
        return (
            os.environ.get("MEMORY_VAULT_SYNC_TESTING") == "1"
            and bool(self.config_test_mode)
        )

    @property
    def config_test_mode(self) -> bool:
        config_path = self.data_dir / "config.json"
        if not config_path.exists():
            return False
        with contextlib.suppress(Exception):
            return bool(load_json(config_path).get("_test_mode"))
        return False

    def assert_remote_private(self) -> None:
        github = GITHUB_REPO_RE.fullmatch(self.repo_url)
        gitlab = GITLAB_HTTPS_REPO_RE.fullmatch(self.repo_url)
        if github is None and gitlab is None:
            if self._test_local_allowed():
                return
            raise PrivacyError(
                "production vault remote must be an approved HTTPS Git repository"
            )
        if github is not None:
            if (
                self.privacy_verifier != "github-private-v1"
                or not self.repo_url.startswith("https://github.com/")
            ):
                raise PrivacyError(
                    "GitHub remote privacy verifier does not match its host"
                )
            full_name = f"{github.group('owner')}/{github.group('repo')}"
            api_url = (
                "https://api.github.com/repos/"
                f"{urllib.parse.quote(github.group('owner'))}/"
                f"{urllib.parse.quote(github.group('repo'))}"
            )
            policy = GITHUB_API_POLICY
            headers: dict[str, str] = {
                "Accept": "application/vnd.github+json",
                "User-Agent": f"memory-vault-sync/{VERSION}",
                "X-GitHub-Api-Version": "2022-11-28",
            }
            service = "GitHub"
        else:
            assert gitlab is not None
            if self.privacy_verifier != "gitlab-private-v1":
                raise PrivacyError(
                    "GitLab remote privacy verifier does not match its host"
                )
            full_name = (
                f"{gitlab.group('namespace')}/{gitlab.group('repo')}"
            )
            api_url = (
                "https://gitlab.com/api/v4/projects/"
                + urllib.parse.quote(full_name, safe="")
            )
            policy = GITLAB_API_POLICY
            headers = {
                "Accept": "application/json",
                "User-Agent": f"memory-vault-sync/{VERSION}",
            }
            service = "GitLab"
        if (
            self.expected_repo
            and str(self.expected_repo).lower() != full_name.lower()
        ):
            raise PrivacyError(
                f"{service} remote does not match the configured private vault"
            )
        credential = credential_get(self.privacy_credential_host)
        headers["Authorization"] = f"Bearer {credential['password']}"
        request = urllib.request.Request(api_url, headers=headers)
        try:
            with open_verified_url(
                request,
                timeout=15,
                policy=policy,
            ) as response:
                body = response.read(1024 * 1024)
        except urllib.error.HTTPError as exc:
            if exc.code in {401, 403, 404}:
                raise AuthenticationError(
                    f"{service} privacy check failed; refresh the scoped credential"
                ) from exc
            raise OfflineError(f"{service} privacy check failed") from exc
        except (urllib.error.URLError, TimeoutError, socket.timeout) as exc:
            raise OfflineError(f"{service} privacy check is offline") from exc
        metadata = strict_json_loads(body.decode("utf-8"))
        if not isinstance(metadata, Mapping):
            raise VerificationError(
                f"{service} privacy response is invalid"
            )
        if github is not None:
            private = metadata.get("private") is True
            returned_name = metadata.get("full_name")
        else:
            private = metadata.get("visibility") == "private"
            returned_name = metadata.get("path_with_namespace")
        if not private:
            raise PrivacyError(
                f"{service} repository is not private; publication refused"
            )
        if str(returned_name or "").lower() != full_name.lower():
            raise PrivacyError(
                f"{service} API returned a different repository"
            )

    def ensure(self, *, fetch_remote: bool = True) -> None:
        self.assert_remote_private()
        ensure_private_dir(self.git_dir.parent)
        cloned = False
        if not self.git_dir.exists():
            run_process(
                [
                    *self._git_prefix(),
                    "clone",
                    "--bare",
                    "--no-local",
                    "--single-branch",
                    "--branch",
                    self.branch,
                    self.repo_url,
                    str(self.git_dir),
                ],
                timeout=120,
            )
            self._run_bare(
                [
                    "config",
                    "remote.origin.fetch",
                    "+refs/heads/*:refs/remotes/origin/*",
                ]
            )
            initial = validate_git_sha(
                self._run_bare(
                    ["rev-parse", f"refs/heads/{self.branch}"]
                ).stdout.decode("ascii").strip(),
                "initial remote commit",
            )
            self._run_bare(["update-ref", self.remote_ref, initial])
            cloned = True
        self._assert_cached_remote()
        assert_plain_path(self.git_dir, require_file=False)
        if fetch_remote and not cloned:
            # The destination was proved private immediately above. Avoid a
            # duplicate provider-API round trip inside the same operation.
            self._fetch_after_privacy_proof()

    def fetch(self) -> None:
        self.assert_remote_private()
        self._fetch_after_privacy_proof()

    def _fetch_after_privacy_proof(self) -> None:
        """Fetch only after this call stack has just proved privacy."""

        self._assert_cached_remote()
        self._run_bare(
            [
                "fetch",
                "--no-tags",
                self.repo_url,
                f"refs/heads/{self.branch}",
            ],
            timeout=90,
        )
        incoming = validate_git_sha(
            self._run_bare(["rev-parse", "FETCH_HEAD"])
            .stdout.decode("ascii")
            .strip(),
            "fetched remote commit",
        )
        previous: str | None = None
        try:
            previous = validate_git_sha(
                self._run_bare(["rev-parse", "--verify", self.remote_ref])
                .stdout.decode("ascii")
                .strip(),
                "cached remote commit",
            )
        except VaultSyncError:
            previous = None
        if previous is not None and previous != incoming:
            try:
                self._run_bare(
                    ["merge-base", "--is-ancestor", previous, incoming],
                    timeout=20,
                )
            except VaultSyncError as exc:
                raise ConflictError(
                    "remote branch history moved backwards or was rewritten; "
                    "explicit rollback review is required"
                ) from exc
        update_arguments = ["update-ref", self.remote_ref, incoming]
        if previous is not None:
            update_arguments.append(previous)
        try:
            self._run_bare(update_arguments, timeout=20)
        except VaultSyncError as exc:
            raise ConflictError(
                "cached remote reference changed during fetch"
            ) from exc

    def has_cache(self) -> bool:
        return (self.git_dir / "HEAD").is_file()

    def head_sha(self) -> str:
        result = self._run_bare(["rev-parse", self.remote_ref])
        return validate_git_sha(result.stdout.decode("ascii").strip(), "remote commit")

    def blob_sha(self, repo_path: str) -> str:
        safe_path = validate_repo_path(repo_path)
        result = self._run_bare(["rev-parse", f"{self.remote_ref}:{safe_path}"])
        return validate_git_sha(result.stdout.decode("ascii").strip(), "remote blob")

    def blob_size(self, repo_path: str) -> int:
        object_id = self.blob_sha(repo_path)
        raw = self._run_bare(["cat-file", "-s", object_id]).stdout
        try:
            size = int(raw.decode("ascii", "strict").strip())
        except (UnicodeDecodeError, ValueError) as exc:
            raise VerificationError("remote Git blob size is invalid") from exc
        if size < 0:
            raise VerificationError("remote Git blob size is invalid")
        return size

    def show_bytes(self, repo_path: str) -> bytes:
        safe_path = validate_repo_path(repo_path)
        result = self._run_bare(["show", f"{self.remote_ref}:{safe_path}"])
        return result.stdout

    def show_blob_bytes(self, object_id: str) -> bytes:
        blob_id = validate_git_sha(object_id, "Git blob")
        return self._run_bare(["cat-file", "blob", blob_id]).stdout

    def show_blob_bytes_many(
        self,
        object_ids: Sequence[str],
    ) -> dict[str, bytes]:
        """Read bounded memory blobs through a few Git batch processes.

        Initial receive can contain thousands of small immutable objects. One
        `cat-file` process per object dominates indexing time, so sizes are
        checked once and content is streamed in bounded 32-MiB process batches.
        """

        requested = [
            validate_git_sha(item, "Git blob") for item in object_ids
        ]
        unique = list(dict.fromkeys(requested))
        if len(unique) > MAX_MEMORY_NETWORK_BUNDLE_ENTRIES:
            raise VerificationError("memory blob batch exceeds its count limit")
        if not unique:
            return {}
        query = "".join(f"{item}\n" for item in unique).encode("ascii")
        checked = self._run_bare(
            [
                "cat-file",
                "--batch-check=%(objectname) %(objecttype) %(objectsize)",
            ],
            input_bytes=query,
            timeout=120,
        ).stdout.splitlines()
        if len(checked) != len(unique):
            raise VerificationError("Git memory blob size batch is incomplete")
        sizes: dict[str, int] = {}
        total = 0
        for expected, line in zip(unique, checked, strict=True):
            parts = line.split(b" ")
            if len(parts) != 3:
                raise VerificationError("Git memory blob size record is invalid")
            try:
                observed = parts[0].decode("ascii", "strict")
                object_type = parts[1].decode("ascii", "strict")
                size = int(parts[2].decode("ascii", "strict"))
            except (UnicodeDecodeError, ValueError) as exc:
                raise VerificationError(
                    "Git memory blob size record is invalid"
                ) from exc
            if (
                observed != expected
                or object_type != "blob"
                or size < 1
                or size > MAX_MEMORY_NETWORK_BUNDLE_MEMBER_BYTES
            ):
                raise VerificationError("Git memory blob is invalid or too large")
            sizes[expected] = size
            total += size
            if total > MAX_MEMORY_NETWORK_BUNDLE_TOTAL_BYTES:
                raise VerificationError("Git memory blob batch is too large")

        groups: list[list[str]] = []
        current: list[str] = []
        current_bytes = 0
        for object_id in unique:
            size = sizes[object_id]
            if current and (
                len(current) >= 2048
                or current_bytes + size > 32 * 1024 * 1024
            ):
                groups.append(current)
                current = []
                current_bytes = 0
            current.append(object_id)
            current_bytes += size
        if current:
            groups.append(current)

        result: dict[str, bytes] = {}
        for group in groups:
            output = self._run_bare(
                ["cat-file", "--batch"],
                input_bytes="".join(
                    f"{item}\n" for item in group
                ).encode("ascii"),
                timeout=120,
            ).stdout
            cursor = 0
            for expected in group:
                newline = output.find(b"\n", cursor)
                if newline < 0:
                    raise VerificationError(
                        "Git memory blob batch header is incomplete"
                    )
                header = output[cursor:newline].split(b" ")
                if len(header) != 3:
                    raise VerificationError(
                        "Git memory blob batch header is invalid"
                    )
                try:
                    observed = header[0].decode("ascii", "strict")
                    object_type = header[1].decode("ascii", "strict")
                    size = int(header[2].decode("ascii", "strict"))
                except (UnicodeDecodeError, ValueError) as exc:
                    raise VerificationError(
                        "Git memory blob batch header is invalid"
                    ) from exc
                if (
                    observed != expected
                    or object_type != "blob"
                    or size != sizes[expected]
                ):
                    raise VerificationError(
                        "Git memory blob batch identity is invalid"
                    )
                start = newline + 1
                end = start + size
                if end >= len(output) or output[end : end + 1] != b"\n":
                    raise VerificationError(
                        "Git memory blob batch content is incomplete"
                    )
                raw = output[start:end]
                object_header = f"blob {len(raw)}\0".encode("ascii")
                algorithm = "sha1" if len(expected) == 40 else "sha256"
                observed_hash = hashlib.new(
                    algorithm, object_header + raw
                ).hexdigest()
                if observed_hash != expected:
                    raise VerificationError(
                        "Git memory blob content hash is invalid"
                    )
                result[expected] = raw
                cursor = end + 1
            if cursor != len(output):
                raise VerificationError(
                    "Git memory blob batch has trailing output"
                )
        if set(result) != set(unique):
            raise VerificationError("Git memory blob batch is incomplete")
        return result

    def show_bytes_at(self, commit: str, repo_path: str) -> bytes:
        commit_id = validate_git_sha(commit, "Git commit")
        safe_path = validate_repo_path(repo_path)
        return self._run_bare(["show", f"{commit_id}:{safe_path}"]).stdout

    def path_commits(self, repo_path: str, *, maximum: int = 512) -> list[str]:
        safe_path = validate_repo_path(repo_path)
        if (
            isinstance(maximum, bool)
            or not isinstance(maximum, int)
            or maximum < 1
            or maximum > 10000
        ):
            raise VerificationError("path history bound is invalid")
        result = self._run_bare(
            [
                "rev-list",
                f"--max-count={maximum}",
                self.remote_ref,
                "--",
                safe_path,
            ],
            timeout=30,
        )
        commits = [
            validate_git_sha(line, "path history commit")
            for line in result.stdout.decode("ascii", "strict").splitlines()
            if line
        ]
        return commits

    def commit_changed_paths(self, commit: str) -> set[str]:
        commit_id = validate_git_sha(commit, "Git commit")
        result = self._run_bare(
            [
                "diff-tree",
                "--root",
                "--no-commit-id",
                "--name-only",
                "-r",
                "-z",
                commit_id,
            ],
            timeout=30,
        )
        paths = {
            validate_repo_path(item.decode("utf-8"))
            for item in result.stdout.split(b"\0")
            if item
        }
        if len(paths) > 1000:
            raise VerificationError(
                "transaction commit changed too many paths"
            )
        return paths

    def assert_immutable_path(self, repo_path: str, expected: bytes) -> None:
        safe_path = validate_repo_path(repo_path)
        if self.show_bytes(safe_path) != expected:
            raise VerificationError("immutable remote file changed while loading")
        commits = self.path_commits(safe_path, maximum=2)
        if len(commits) != 1:
            raise VerificationError(
                f"immutable remote file has non-append-only history: {safe_path}"
            )

    def assert_commit_is_ancestor(self, commit: str) -> None:
        commit_id = validate_git_sha(commit, "Git ancestor commit")
        try:
            self._run_bare(
                ["merge-base", "--is-ancestor", commit_id, self.remote_ref],
                timeout=20,
            )
        except VaultSyncError as exc:
            raise VerificationError(
                "declared version parent commit is outside verified remote ancestry"
            ) from exc

    def show_json(self, repo_path: str) -> Mapping[str, Any]:
        try:
            value = strict_json_loads(self.show_bytes(repo_path).decode("utf-8"))
        except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
            raise VerificationError(f"remote JSON is invalid: {repo_path}") from exc
        if not isinstance(value, Mapping):
            raise VerificationError(f"remote JSON is not an object: {repo_path}")
        return value

    def list_paths(self, prefix: str) -> list[str]:
        safe_prefix = validate_repo_path(prefix, "repository prefix")
        result = self._run_bare(
            [
                "ls-tree",
                "-r",
                "--name-only",
                "-z",
                self.remote_ref,
                "--",
                safe_prefix,
            ]
        )
        paths = [
            item.decode("utf-8")
            for item in result.stdout.split(b"\0")
            if item
        ]
        if len(paths) > 10000:
            raise VerificationError("remote path listing exceeds the safety limit")
        return [validate_repo_path(item) for item in paths]

    def list_blob_paths(
        self,
        prefixes: Sequence[str],
        *,
        maximum: int = 250_000,
    ) -> dict[str, str]:
        """List path -> blob in one Git call for a scalable initial receive."""

        if (
            not isinstance(maximum, int)
            or isinstance(maximum, bool)
            or not 1 <= maximum <= 1_000_000
        ):
            raise VerificationError("remote blob listing bound is invalid")
        safe_prefixes = [
            validate_repo_path(item, "repository prefix") for item in prefixes
        ]
        if not safe_prefixes:
            raise VerificationError("remote blob listing has no prefixes")
        result = self._run_bare(
            [
                "ls-tree",
                "-r",
                "-z",
                self.remote_ref,
                "--",
                *safe_prefixes,
            ],
            timeout=60,
        )
        items: dict[str, str] = {}
        for raw in result.stdout.split(b"\0"):
            if not raw:
                continue
            try:
                metadata, raw_path = raw.split(b"\t", 1)
                _mode, object_type, object_id = metadata.decode(
                    "ascii", "strict"
                ).split(" ", 2)
                path = validate_repo_path(raw_path.decode("utf-8", "strict"))
            except (ValueError, UnicodeDecodeError) as exc:
                raise VerificationError("remote Git tree entry is invalid") from exc
            if object_type != "blob":
                raise VerificationError("remote memory tree contains a non-blob")
            if path in items:
                raise VerificationError("remote Git tree contains a duplicate path")
            items[path] = validate_git_sha(object_id, "remote blob")
            if len(items) > maximum:
                raise VerificationError(
                    "remote memory tree exceeds the safety limit"
                )
        return items

    def assert_ancestor(self, ancestor: str, descendant: str) -> None:
        base = validate_git_sha(ancestor, "memory receive cursor")
        head = validate_git_sha(descendant, "memory receive head")
        try:
            self._run_bare(
                ["merge-base", "--is-ancestor", base, head],
                timeout=20,
            )
        except VaultSyncError as exc:
            raise ConflictError(
                "memory receive cursor is outside verified remote ancestry"
            ) from exc

    def accept_pushed_commit(self, previous: str, commit: str) -> None:
        """Advance the local remote-tracking ref after a successful push.

        A successful Git push already proves that the remote accepted this
        exact commit.  Updating the private cache with compare-and-swap avoids
        a second network fetch on the ordinary memory path.  The next receive
        still fetches and verifies ancestry, so a later concurrent advance is
        discovered normally.
        """

        old = validate_git_sha(previous, "pre-push memory head")
        new = validate_git_sha(commit, "pushed memory commit")
        self.assert_ancestor(old, new)
        if self.head_sha() != old:
            raise ConflictError(
                "cached memory head changed while accepting the pushed commit"
            )
        try:
            self._run_bare(
                ["update-ref", self.remote_ref, new, old],
                timeout=20,
            )
        except VaultSyncError as exc:
            raise ConflictError(
                "cached memory head changed after the successful push"
            ) from exc

    def changed_paths_between(
        self,
        ancestor: str,
        descendant: str,
        prefixes: Sequence[str],
        *,
        maximum: int = 20_000,
    ) -> dict[str, str]:
        """Return status by path without rescanning the remote memory tree."""

        base = validate_git_sha(ancestor, "memory receive cursor")
        head = validate_git_sha(descendant, "memory receive head")
        self.assert_ancestor(base, head)
        safe_prefixes = [
            validate_repo_path(item, "repository prefix") for item in prefixes
        ]
        if not safe_prefixes:
            raise VerificationError("memory receive diff has no prefixes")
        result = self._run_bare(
            [
                "diff",
                "--name-status",
                "-z",
                "--no-renames",
                base,
                head,
                "--",
                *safe_prefixes,
            ],
            timeout=60,
        )
        parts = [item for item in result.stdout.split(b"\0") if item]
        if len(parts) % 2:
            raise VerificationError("remote memory diff is malformed")
        changes: dict[str, str] = {}
        for index in range(0, len(parts), 2):
            try:
                status = parts[index].decode("ascii", "strict")
                path = validate_repo_path(
                    parts[index + 1].decode("utf-8", "strict")
                )
            except UnicodeDecodeError as exc:
                raise VerificationError("remote memory diff is invalid") from exc
            if status not in {"A", "M", "D", "T", "U", "X", "B"}:
                raise VerificationError("remote memory diff status is unsupported")
            if path in changes:
                raise VerificationError("remote memory diff repeats a path")
            changes[path] = status
            if len(changes) > maximum:
                raise VerificationError(
                    "remote memory diff exceeds the safety limit"
                )
        return changes

    def file_exists(self, repo_path: str) -> bool:
        try:
            self.blob_sha(repo_path)
        except VaultSyncError:
            return False
        return True

    def create_worktree(self) -> Worktree:
        ensure_private_dir(self.worktree_root)
        path = self.worktree_root / f"wt-{uuid.uuid4().hex}"
        self._run_bare(["worktree", "add", "--detach", str(path), self.remote_ref], timeout=60)
        self._run_worktree(path, ["config", "user.name", "Memory Vault Sync"])
        self._run_worktree(
            path, ["config", "user.email", "memory-vault-sync@localhost"]
        )
        return Worktree(self, path)

    def write_generated_files(
        self,
        worktree: Path,
        files: Mapping[str, bytes],
    ) -> list[str]:
        written: list[str] = []
        for repo_path, content in sorted(files.items()):
            safe_path = validate_repo_path(repo_path)
            destination = worktree / PurePosixPath(safe_path)
            resolved_parent = destination.parent.resolve()
            if not _path_is_within(resolved_parent, worktree.resolve()):
                raise PrivacyError("generated file escapes the Git worktree")
            cursor = worktree.resolve()
            for component in PurePosixPath(safe_path).parts[:-1]:
                cursor = cursor / component
                if cursor.exists() and (
                    cursor.is_symlink() or _is_reparse_point(cursor)
                ):
                    raise PrivacyError(
                        "generated file traverses a symlink or reparse point"
                    )
            ensure_private_dir(destination.parent)
            if destination.exists():
                assert_plain_path(destination, require_file=True)
            atomic_write_bytes(destination, content, mode=0o644)
            written.append(safe_path)
        return written

    def commit_and_push(
        self,
        worktree: Path,
        generated_files: Mapping[str, bytes],
        task_id: str,
        transaction_id: str,
    ) -> str:
        self._assert_cached_remote()
        task = validate_identifier(task_id, "task_id")
        transaction = validate_identifier(transaction_id, "transaction_id")
        paths = [validate_repo_path(item) for item in generated_files]
        if not paths:
            raise VerificationError("transaction has no generated files")
        self._run_worktree(worktree, ["add", "--", *paths])
        staged = self._run_worktree(
            worktree, ["diff", "--cached", "--name-only", "-z"]
        ).stdout.split(b"\0")
        actual = {
            item.decode("utf-8")
            for item in staged
            if item
        }
        if actual != set(paths):
            raise PrivacyError("Git staged files do not match the transaction")
        for path in paths:
            staged_bytes = self._run_worktree(
                worktree, ["show", f":{path}"], timeout=30
            ).stdout
            if staged_bytes != generated_files[path]:
                raise PrivacyError("staged Git content changed after validation")
        self._run_worktree(
            worktree,
            [
                "commit",
                "--no-verify",
                "-m",
                f"sync({task}): private checkpoint [tx:{transaction}]",
            ],
            timeout=30,
        )
        commit = validate_git_sha(
            self._run_worktree(worktree, ["rev-parse", "HEAD"])
            .stdout.decode("ascii")
            .strip(),
            "new commit",
        )
        self._run_worktree(
            worktree,
            ["push", self.repo_url, f"HEAD:refs/heads/{self.branch}"],
            timeout=90,
        )
        return commit


def read_hook_input() -> Mapping[str, Any]:
    raw = sys.stdin.buffer.read(MAX_HOOK_INPUT_BYTES + 1)
    if len(raw) > MAX_HOOK_INPUT_BYTES:
        raise PrivacyError("hook input exceeds the fixed limit")
    try:
        value = strict_json_loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
        raise PrivacyError("hook input is not valid JSON") from exc
    if not isinstance(value, Mapping):
        raise PrivacyError("hook input must be an object")
    return value


def read_private_routing_review_input() -> Mapping[str, Any]:
    raw = sys.stdin.buffer.read(MAX_LOCAL_ROUTING_REVIEW_BYTES + 1)
    if len(raw) > MAX_LOCAL_ROUTING_REVIEW_BYTES:
        raise PrivacyError("local routing review exceeds the fixed limit")
    try:
        value = strict_json_loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
        raise PrivacyError("local routing review is not valid JSON") from exc
    if not isinstance(value, Mapping):
        raise PrivacyError("local routing review must be an object")
    return value


def read_private_local_artifact_input() -> Mapping[str, Any]:
    raw = sys.stdin.buffer.read(64 * 1024 + 1)
    if len(raw) > 64 * 1024:
        raise PrivacyError("local artifact evidence input exceeds the fixed limit")
    try:
        value = strict_json_loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
        raise PrivacyError("local artifact evidence input is not valid JSON") from exc
    if not isinstance(value, Mapping):
        raise PrivacyError("local artifact evidence input must be an object")
    return value


def read_private_routing_token() -> str:
    raw = sys.stdin.buffer.read(128)
    if len(raw) >= 128:
        raise PrivacyError("routing decision token input is invalid")
    try:
        value = raw.decode("ascii").strip()
    except UnicodeDecodeError as exc:
        raise PrivacyError("routing decision token input is invalid") from exc
    if ROUTING_DECISION_TOKEN_RE.fullmatch(value) is None:
        raise PrivacyError("routing decision token input is invalid")
    return value


def read_private_memory_query() -> str:
    raw = sys.stdin.buffer.read(memory_network.MAX_QUERY_BYTES + 1)
    if len(raw) > memory_network.MAX_QUERY_BYTES:
        raise PrivacyError("associative memory query exceeds the fixed limit")
    try:
        value = raw.decode("utf-8").strip()
    except UnicodeDecodeError as exc:
        raise PrivacyError("associative memory query is not UTF-8") from exc
    if not value:
        raise PrivacyError("associative memory query is empty")
    return scan_visible_text(value, "associative memory query")


def read_private_memory_proposal() -> Mapping[str, Any]:
    raw = sys.stdin.buffer.read(256 * 1024 + 1)
    if len(raw) > 256 * 1024:
        raise PrivacyError("semantic memory proposal exceeds the fixed limit")
    try:
        value = strict_json_loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
        raise PrivacyError("semantic memory proposal is not valid JSON") from exc
    if not isinstance(value, Mapping):
        raise PrivacyError("semantic memory proposal must be an object")
    return value


def read_private_share_selector() -> Mapping[str, Any]:
    raw = sys.stdin.buffer.read(sharing.MAX_SELECTOR_BYTES + 1)
    if len(raw) > sharing.MAX_SELECTOR_BYTES:
        raise PrivacyError("memory share selector exceeds the fixed limit")
    try:
        value = strict_json_loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
        raise PrivacyError("memory share selector is not valid JSON") from exc
    if not isinstance(value, Mapping):
        raise PrivacyError("memory share selector must be an object")
    return value


def hook_json(
    event: str,
    *,
    context: str | None = None,
    warning: str | None = None,
) -> dict[str, Any]:
    output: dict[str, Any] = {"continue": True}
    if context is not None:
        if len(context.encode("utf-8")) > CONTINUATION_CONTEXT_MAX_BYTES:
            raise VerificationError(
                "hook continuation context exceeds the fixed UTF-8 byte limit"
            )
        output["hookSpecificOutput"] = {
            "hookEventName": event,
            "additionalContext": context,
        }
    if warning:
        output["systemMessage"] = warning[:500]
    return output


@dataclasses.dataclass(frozen=True)
class VerifiedDriveObject:
    file_id: str
    parent_id: str
    sha256: str
    size: int
    mime_type: str
    verification_level: str
    # Defaults preserve the constructor used by pre-0.13.7 diagnostics.
    store_id: str = DEFAULT_OBJECT_STORE_ID
    driver: str = "google-drive-v3"
    storage_mode: str = "full"


@dataclasses.dataclass(frozen=True)
class ChunkSourceSnapshot:
    device: int | None
    inode: int | None
    mode: int | None
    size: int
    mtime_ns: int | None
    ctime_ns: int | None


def _validate_artifact_storage_ref(value: Any) -> dict[str, str]:
    if not isinstance(value, Mapping) or set(value) != {
        "schema_version",
        "store_id",
        "driver",
        "object_id",
        "container_id",
        "verification_level",
    }:
        raise VerificationError("artifact storage reference is invalid")
    if value.get("schema_version") != ARTIFACT_STORAGE_REF_SCHEMA:
        raise VerificationError("artifact storage reference schema is invalid")
    store_id = validate_identifier(
        value.get("store_id"),
        "artifact.storage_ref.store_id",
    )
    driver = validate_identifier(
        value.get("driver"),
        "artifact.storage_ref.driver",
    )
    result = {
        "schema_version": ARTIFACT_STORAGE_REF_SCHEMA,
        "store_id": store_id,
        "driver": driver,
    }
    for key in ("object_id", "container_id"):
        item = value.get(key)
        if not isinstance(item, str) or not re.fullmatch(
            r"[A-Za-z0-9_-][A-Za-z0-9._~-]{1,511}", item
        ):
            raise VerificationError(f"artifact storage {key} is invalid")
        result[key] = item
    result["verification_level"] = validate_identifier(
        value.get("verification_level"),
        "artifact.storage_ref.verification_level",
    )
    return result


def _artifact_storage_ref(
    artifact: Mapping[str, Any],
    *,
    legacy_store_id: str = DEFAULT_OBJECT_STORE_ID,
    legacy_driver: str = "google-drive-v3",
) -> dict[str, str]:
    """Normalize generic v1 and legacy Google Drive artifact references."""

    storage_ref = artifact.get("storage_ref")
    if storage_ref is not None:
        return _validate_artifact_storage_ref(storage_ref)
    file_id = artifact.get("drive_file_id")
    parent_id = artifact.get("drive_parent_id")
    if not isinstance(file_id, str) or not isinstance(parent_id, str):
        raise VerificationError("artifact has no verified storage reference")
    return _validate_artifact_storage_ref(
        {
            "schema_version": ARTIFACT_STORAGE_REF_SCHEMA,
            "store_id": legacy_store_id,
            "driver": legacy_driver,
            "object_id": file_id,
            "container_id": parent_id,
            "verification_level": "legacy-drive-reference",
        }
    )


def _storage_ref_from_verified(
    verified: VerifiedDriveObject,
) -> dict[str, str]:
    return _validate_artifact_storage_ref(
        {
            "schema_version": ARTIFACT_STORAGE_REF_SCHEMA,
            "store_id": verified.store_id,
            "driver": verified.driver,
            "object_id": verified.file_id,
            "container_id": verified.parent_id,
            "verification_level": verified.verification_level,
        }
    )


class DriveAdapter:
    store_id: str
    driver: str

    def assert_private(self) -> None:
        raise NotImplementedError

    def should_chunk(self, size: int) -> bool:
        return False

    def find_verified(
        self, sha256: str, size: int, mime_type: str
    ) -> VerifiedDriveObject | None:
        raise NotImplementedError

    def upload_and_verify(
        self,
        path: Path,
        sha256: str,
        size: int,
        mime_type: str,
    ) -> VerifiedDriveObject:
        raise NotImplementedError

    def download_and_verify(
        self, artifact: Mapping[str, Any], destination: Path
    ) -> None:
        raise NotImplementedError


class FilesystemDriveAdapter(DriveAdapter):
    """Content-addressed test adapter.

    This adapter is intentionally unavailable in normal production mode. It is
    used for deterministic fault tests without touching the user's real Drive.
    """

    def __init__(
        self,
        config: Mapping[str, Any],
        *,
        store_id: str | None = None,
    ):
        if not (
            os.environ.get("MEMORY_VAULT_SYNC_TESTING") == "1"
            and config.get("_test_mode") is True
        ):
            raise ConfigurationError("filesystem Drive is test-only")
        store = _object_store_config(config, store_id)
        self.store_id = validate_identifier(
            store.get("store_id"),
            "object-store store_id",
        )
        self.driver = "filesystem-test"
        root = store.get("root")
        if not isinstance(root, str) or not os.path.isabs(root):
            raise ConfigurationError("test Drive root must be absolute")
        self.root = Path(root).resolve()
        self.objects = self.root / "objects" / "sha256"

    def assert_private(self) -> None:
        assert_plain_path(self.root, require_file=False)
        marker = self.root / ".memory-vault-private.json"
        assert_plain_path(marker, require_file=True)
        value = load_json(marker)
        if value != {
            "vault_id": VAULT_ID,
            "owner_only": True,
            "shared": False,
        }:
            raise PrivacyError("test Drive privacy marker is not owner-only")

    def _object_path(self, sha256: str) -> Path:
        validate_sha256(sha256, "artifact sha256")
        return self.objects / sha256[:2] / sha256

    def _verified(
        self, path: Path, sha256: str, size: int, mime_type: str
    ) -> VerifiedDriveObject:
        actual_sha, actual_size = stable_hash_file(path, inspect_text=False)
        if actual_sha != sha256 or actual_size != size:
            raise VerificationError("test Drive object failed SHA-256 verification")
        root_id = f"fs-root-{sha256_bytes(str(self.root).encode())[:24]}"
        return VerifiedDriveObject(
            store_id=self.store_id,
            driver=self.driver,
            file_id=f"fs-{sha256}",
            parent_id=root_id,
            sha256=sha256,
            size=size,
            mime_type=mime_type,
            verification_level="remote-content-sha256-verified",
        )

    def find_verified(
        self, sha256: str, size: int, mime_type: str
    ) -> VerifiedDriveObject | None:
        self.assert_private()
        path = self._object_path(sha256)
        if not path.exists():
            return None
        assert_plain_path(path, require_file=True)
        return self._verified(path, sha256, size, mime_type)

    def upload_and_verify(
        self,
        path: Path,
        sha256: str,
        size: int,
        mime_type: str,
    ) -> VerifiedDriveObject:
        self.assert_private()
        existing = self.find_verified(sha256, size, mime_type)
        if existing is not None:
            return existing
        destination = self._object_path(sha256)
        ensure_private_dir(destination.parent)
        fd, temporary_name = tempfile.mkstemp(
            prefix=f".{sha256}.", suffix=".upload", dir=str(destination.parent)
        )
        temporary = Path(temporary_name)
        try:
            with path.open("rb") as source, os.fdopen(fd, "wb") as target:
                while True:
                    chunk = source.read(1024 * 1024)
                    if not chunk:
                        break
                    target.write(chunk)
                target.flush()
                os.fsync(target.fileno())
            os.replace(temporary, destination)
            _safe_chmod(destination, 0o600)
        finally:
            with contextlib.suppress(FileNotFoundError):
                temporary.unlink()
        return self._verified(destination, sha256, size, mime_type)

    def download_and_verify(
        self, artifact: Mapping[str, Any], destination: Path
    ) -> None:
        self.assert_private()
        storage_ref = _artifact_storage_ref(
            artifact,
            legacy_store_id=self.store_id,
            legacy_driver=self.driver,
        )
        if (
            storage_ref["driver"] != self.driver
            or storage_ref["store_id"] != self.store_id
        ):
            raise VerificationError(
                "artifact belongs to a different object-store adapter"
            )
        sha256 = validate_sha256(artifact.get("sha256"), "artifact.sha256")
        size = int(artifact.get("size"))
        mime_type = str(artifact.get("mime_type"))
        verified = self.find_verified(sha256, size, mime_type)
        if (
            verified is None
            or storage_ref["object_id"] != verified.file_id
            or storage_ref["container_id"] != verified.parent_id
        ):
            raise VerificationError("test Drive artifact reference is invalid")
        _copy_verified_file(self._object_path(sha256), destination, sha256, size)


class RcloneCryptAdapter(DriveAdapter):
    """Encrypted provider-neutral object storage through a pinned rclone.

    The adapter accepts only a reviewed ``crypt`` remote wrapping S3, WebDAV,
    SFTP, or local storage. It never reads an arbitrary extension, never puts a
    credential on the command line, and independently re-hashes decrypted
    bytes before returning a storage reference.
    """

    def __init__(
        self,
        config: Mapping[str, Any],
        *,
        store_id: str | None = None,
        config_password_override: str | None = None,
        data_dir: Path | None = None,
    ):
        self.config = config
        store = _object_store_config(config, store_id)
        if store.get("driver") != RCLONE_OBJECT_STORE_DRIVER:
            raise ConfigurationError("selected object store is not rclone crypt")
        self.store_id = validate_identifier(
            store.get("store_id"),
            "object-store store_id",
        )
        self.driver = RCLONE_OBJECT_STORE_DRIVER
        adapter = _validate_rclone_adapter_config(
            _adapter_config(config, store.get("adapter_config_ref"))
        )
        self.executable = Path(adapter["executable"]).resolve()
        self.executable_sha256 = adapter["executable_sha256"]
        self.config_path = Path(adapter["config_path"]).resolve()
        self.remote_name = adapter["remote_name"]
        self.remote_fingerprint = adapter["remote_fingerprint"]
        self.minimum_version = adapter["minimum_version"]
        self.verified_version = adapter["verified_version"]
        self.credential_host = str(store["credential_host"])
        self._config_password_override = config_password_override
        self.container_id = f"rclone-{self.remote_fingerprint[:32]}"
        self.data_dir = (
            data_dir.resolve()
            if data_dir is not None
            else default_data_dir().resolve()
        )
        self._boundary_lock = threading.RLock()
        self._lookup_cache_lock = threading.RLock()
        self._private_root_verified = False
        self._verified_lookup_cache: dict[
            tuple[str, int, str], VerifiedDriveObject
        ] = {}
        self._chunk_policy_cache: dict[str, Any] | None = None

    def should_chunk(self, size: int) -> bool:
        minimum = int(
            self.config["sync"].get(
                "chunked_artifact_min_bytes",
                DEFAULT_CHUNK_MINIMUM_BYTES,
            )
        )
        return bool(
            self.config["sync"].get("chunked_artifacts_enabled", False)
            and minimum <= size <= CHUNK_SIZE_BYTES * MAX_CHUNK_COUNT
        )

    def _config_password(self) -> str:
        if self._config_password_override is not None:
            password = self._config_password_override
            if not password or any(
                item in password for item in ("\x00", "\r", "\n")
            ):
                raise AuthenticationError(
                    "rclone configuration password override is invalid"
                )
            return password
        credential = credential_get(self.credential_host, self.store_id)
        password = credential.get("password")
        if not isinstance(password, str) or not password:
            raise AuthenticationError(
                "rclone configuration password is unavailable"
            )
        return password

    def _probe_current(self) -> None:
        password = self._config_password()
        try:
            probe = _probe_rclone_boundary(
                executable=self.executable,
                expected_executable_sha256=self.executable_sha256,
                config_path=self.config_path,
                remote_name=self.remote_name,
                config_password=password,
            )
        finally:
            del password
        if (
            probe["verified_version"] != self.verified_version
            or probe["minimum_version"] != self.minimum_version
            or probe["remote_fingerprint"] != self.remote_fingerprint
        ):
            raise PrivacyError("rclone executable or encrypted remote changed")
        self._wrapped_remote_name = probe["wrapped_remote_name"]
        self._wrapped_path = probe["wrapped_path"]
        self._config_sha256 = validate_sha256(
            probe.get("config_sha256"),
            "rclone verified config sha256",
        )
        local_trust = probe.get("local_trust_file_sha256")
        if not isinstance(local_trust, Mapping):
            raise VerificationError(
                "rclone local trust-file proof is invalid"
            )
        self._local_trust_file_sha256 = {
            str(Path(path).resolve()): validate_sha256(
                digest,
                "rclone local trust-file sha256",
            )
            for path, digest in local_trust.items()
        }

    def _assert_local_boundary_unchanged(self) -> None:
        expected_config_sha = getattr(self, "_config_sha256", None)
        if not isinstance(expected_config_sha, str):
            raise VerificationError("rclone boundary was not verified")
        config_sha, _ = stable_hash_file(
            self.config_path,
            inspect_text=False,
        )
        if config_sha != expected_config_sha:
            raise VerificationError(
                "rclone encrypted config changed during this operation"
            )
        local_trust = getattr(self, "_local_trust_file_sha256", None)
        if not isinstance(local_trust, Mapping):
            raise VerificationError(
                "rclone local trust-file proof is unavailable"
            )
        for path_text, expected_sha in local_trust.items():
            current_sha, _ = _hash_rclone_boundary_file(
                Path(path_text),
                "rclone local trust file",
            )
            if current_sha != expected_sha:
                raise VerificationError(
                    "rclone local trust file changed during this operation"
                )

    def _transfer_command(self, *arguments: str) -> list[str]:
        return [
            str(self.executable),
            "--config",
            str(self.config_path),
            "--ask-password=false",
            "--color=NEVER",
            "--log-level=ERROR",
            "--stats=0",
            "--retries=1",
            "--low-level-retries=1",
            "--contimeout=15s",
            "--timeout=2m",
            "--max-connections=4",
            "--checkers=1",
            "--transfers=1",
            "--buffer-size=4Mi",
            "--max-buffer-memory=16Mi",
            f"--user-agent=memory-vault-sync/{VERSION}",
            "--no-check-certificate=false",
            "--webdav-auth-redirect=false",
            "--crypt-filename-encryption=standard",
            "--crypt-directory-name-encryption=true",
            "--crypt-strict-names=true",
            "--crypt-pass-bad-blocks=false",
            *arguments,
        ]

    def _run_command(
        self,
        *arguments: str,
        timeout: float = 180,
    ) -> subprocess.CompletedProcess[bytes]:
        self._assert_local_boundary_unchanged()
        password = self._config_password()
        try:
            result = _run_rclone_control(
                self._transfer_command(*arguments),
                environment=_rclone_environment(password),
                timeout=timeout,
            )
        finally:
            del password
            self._assert_local_boundary_unchanged()
        return result

    def _remote_path(self, relative_path: str) -> str:
        if relative_path:
            validate_repo_path(relative_path, "rclone object path")
        return f"{self.remote_name}:{relative_path}"

    def _base_ciphertext_entry_count(self) -> int:
        wrapped_name = getattr(self, "_wrapped_remote_name", None)
        wrapped_path = getattr(self, "_wrapped_path", None)
        if not isinstance(wrapped_name, str) or not isinstance(
            wrapped_path,
            str,
        ):
            raise VerificationError("rclone wrapped remote was not verified")
        result = self._run_command(
            "lsf",
            f"{wrapped_name}:{wrapped_path}",
            "--max-depth=1",
            "--format=p",
            timeout=60,
        )
        if result.returncode == 3:
            return 0
        if result.returncode != 0:
            raise OfflineError(
                "rclone ciphertext root listing failed "
                f"(exit {result.returncode})"
            )
        try:
            lines = result.stdout.decode("utf-8", "strict").splitlines()
        except UnicodeDecodeError as exc:
            raise VerificationError(
                "rclone ciphertext listing is not UTF-8"
            ) from exc
        entries = [line for line in lines if line.strip()]
        if len(entries) > 10000:
            raise VerificationError(
                "rclone ciphertext listing exceeds the safety limit"
            )
        return len(entries)

    def _object_relative_path(self, sha256: str) -> str:
        digest = validate_sha256(sha256, "artifact sha256")
        return f"{RCLONE_OBJECT_PREFIX}/{digest[:2]}/{digest}"

    @staticmethod
    def _encrypted_transfer_limit(plaintext_size: int) -> int:
        if (
            not isinstance(plaintext_size, int)
            or isinstance(plaintext_size, bool)
            or plaintext_size < 1
        ):
            raise VerificationError("rclone plaintext size is invalid")
        chunks = (
            plaintext_size + RCLONE_CRYPT_BLOCK_BYTES - 1
        ) // RCLONE_CRYPT_BLOCK_BYTES
        # rclone crypt writes a 32-byte header and a 16-byte Poly1305
        # authenticator for every 64-KiB plaintext chunk. --max-transfer is
        # evaluated after this encryption overhead is added.
        encrypted_size = plaintext_size + 32 + (16 * chunks)
        # rclone's transfer counter is deliberately approximate and may cross
        # the exact ciphertext size before the final accounting update. One
        # crypt block of headroom avoids rejecting the verified source while
        # retaining a strict per-object transfer ceiling.
        return encrypted_size + RCLONE_CRYPT_BLOCK_BYTES

    def _list_names(self, parent: str) -> list[str]:
        if parent:
            validate_repo_path(parent, "rclone list path")
        result = self._run_command(
            "lsf",
            self._remote_path(parent),
            "--max-depth=1",
            "--format=p",
            timeout=60,
        )
        if result.returncode == 3 and parent:
            # rclone's documented exit code 3 is "directory not found". A
            # content-address prefix does not exist before its first object;
            # the encrypted root itself is never allowed to use this fallback.
            return []
        if result.returncode != 0:
            raise OfflineError(
                "rclone encrypted root listing failed "
                f"(exit {result.returncode})"
            )
        try:
            text = result.stdout.decode("utf-8", "strict")
        except UnicodeDecodeError as exc:
            raise VerificationError("rclone listing is not UTF-8") from exc
        names = []
        for raw in text.splitlines():
            name = unicodedata.normalize("NFC", raw.strip())
            if (
                not name
                or len(name.encode("utf-8")) > 512
                or name.startswith(("/", "\\"))
                or "\\" in name
                or name in {".", ".."}
                or "/../" in f"/{name}/"
            ):
                raise VerificationError("rclone listing contains an unsafe name")
            names.append(name)
        if len(names) != len(set(names)):
            raise VerificationError("rclone listing contains duplicate names")
        return names

    def _stream_remote(
        self,
        relative_path: str,
        *,
        expected_size: int,
        output_stream: Any | None = None,
    ) -> tuple[str, int]:
        validate_repo_path(relative_path, "rclone object path")
        self._assert_local_boundary_unchanged()
        password = self._config_password()
        try:
            result = _stream_rclone_stdout(
                self._transfer_command(
                    "cat",
                    self._remote_path(relative_path),
                    f"--count={expected_size + 1}",
                ),
                environment=_rclone_environment(password),
                timeout=600,
                maximum_bytes=expected_size,
                output_stream=output_stream,
            )
        finally:
            del password
            self._assert_local_boundary_unchanged()
        return result

    def _copyto(self, source: Path, relative_path: str, size: int) -> None:
        assert_plain_path(source, require_file=True)
        validate_repo_path(relative_path, "rclone object path")
        result = self._run_command(
            "copyto",
            str(source),
            self._remote_path(relative_path),
            "--immutable",
            "--no-traverse",
            "--no-update-modtime",
            f"--max-transfer={self._encrypted_transfer_limit(size)}B",
            timeout=900,
        )
        if result.returncode != 0:
            lowered = result.stderr.lower()
            if b"immutable file modified" in lowered or b"do not match" in lowered:
                raise VerificationError(
                    "rclone immutable object already contains different bytes"
                )
            raise OfflineError(
                "rclone encrypted upload failed "
                f"(exit {result.returncode})"
            )

    def _marker_bytes(self) -> bytes:
        return canonical_json_bytes(
            {
                "schema_version": RCLONE_ROOT_MARKER_SCHEMA,
                "vault_id": VAULT_ID,
                "store_id": self.store_id,
                "remote_fingerprint": self.remote_fingerprint,
            }
        )

    @staticmethod
    def _allowed_root_names() -> set[str]:
        return {
            RCLONE_ROOT_MARKER_PATH,
            "objects/",
            CHUNK_POLICY_PATH,
            f"{CHUNK_ROOT.split('/', 1)[0]}/",
            f"{CHUNK_MANIFEST_ROOT.split('/', 1)[0]}/",
        }

    @staticmethod
    def _require_chunk_policy_for_chunk_roots(names: set[str]) -> None:
        chunk_roots = {
            f"{CHUNK_ROOT.split('/', 1)[0]}/",
            f"{CHUNK_MANIFEST_ROOT.split('/', 1)[0]}/",
        }
        if names.intersection(chunk_roots) and CHUNK_POLICY_PATH not in names:
            raise PrivacyError(
                "rclone encrypted chunk roots have no key policy marker"
            )

    def _verify_marker(self) -> None:
        names = set(self._list_names(""))
        if any(name not in self._allowed_root_names() for name in names):
            raise PrivacyError(
                "rclone crypt root contains unexpected plaintext entries"
            )
        self._require_chunk_policy_for_chunk_roots(names)
        if RCLONE_ROOT_MARKER_PATH not in names:
            raise PrivacyError("rclone encrypted root marker is missing")
        expected = self._marker_bytes()
        try:
            digest, size = self._stream_remote(
                RCLONE_ROOT_MARKER_PATH,
                expected_size=len(expected),
            )
        except VerificationError as exc:
            raise PrivacyError(
                "rclone encrypted root marker does not match"
            ) from exc
        if digest != sha256_bytes(expected) or size != len(expected):
            raise PrivacyError("rclone encrypted root marker does not match")

    def initialize_private_root(self, data_dir: Path) -> dict[str, Any]:
        with self._boundary_lock:
            self._probe_current()
            names = set(self._list_names(""))
            if any(name not in self._allowed_root_names() for name in names):
                raise PrivacyError(
                    "rclone crypt root is not empty or Memory Vault owned"
                )
            self._require_chunk_policy_for_chunk_roots(names)
            created = False
            if RCLONE_ROOT_MARKER_PATH not in names:
                if self._base_ciphertext_entry_count() != 0:
                    raise PrivacyError(
                        "rclone ciphertext root is not empty; the crypt key "
                        "or destination may have changed"
                    )
                root = data_dir.expanduser().resolve()
                ensure_private_dir(root)
                fd, temporary_name = tempfile.mkstemp(
                    prefix=".rclone-root-",
                    suffix=".json",
                    dir=str(root),
                )
                temporary = Path(temporary_name)
                marker = self._marker_bytes()
                try:
                    with os.fdopen(fd, "wb") as stream:
                        stream.write(marker)
                        stream.flush()
                        os.fsync(stream.fileno())
                    _safe_chmod(temporary, 0o600)
                    self._copyto(
                        temporary,
                        RCLONE_ROOT_MARKER_PATH,
                        len(marker),
                    )
                    if self._base_ciphertext_entry_count() != 1:
                        raise PrivacyError(
                            "rclone encrypted root changed during initialization"
                        )
                    created = True
                finally:
                    with contextlib.suppress(FileNotFoundError):
                        temporary.unlink()
            self._verify_marker()
            self._private_root_verified = True
            return {
                "schema_version": RCLONE_ROOT_MARKER_SCHEMA,
                "store_id": self.store_id,
                "driver": self.driver,
                "marker_created": created,
                "encrypted_root_verified": True,
            }

    def inspect_initialization_state(self) -> dict[str, Any]:
        """Read-only proof for --no-initialize-root configuration."""

        with self._boundary_lock:
            self._probe_current()
            names = set(self._list_names(""))
            if any(name not in self._allowed_root_names() for name in names):
                raise PrivacyError(
                    "rclone crypt root contains unexpected plaintext entries"
                )
            self._require_chunk_policy_for_chunk_roots(names)
            if RCLONE_ROOT_MARKER_PATH in names:
                self._verify_marker()
                self._private_root_verified = True
                return {
                    "marker_created": False,
                    "encrypted_root_verified": True,
                }
            if self._base_ciphertext_entry_count() != 0:
                raise PrivacyError(
                    "rclone ciphertext root is not empty; the crypt key or "
                    "destination may have changed"
                )
            return {
                "marker_created": False,
                "encrypted_root_verified": False,
            }

    def assert_private(self) -> None:
        with self._boundary_lock:
            if self._private_root_verified:
                return
            self._probe_current()
            self._verify_marker()
            self._private_root_verified = True

    def _validate_chunk_policy_value(self, value: Any) -> dict[str, Any]:
        try:
            return validate_chunk_policy(
                value,
                vault_id=VAULT_ID,
                store_id=self.store_id,
                container_id=self.container_id,
                remote_fingerprint=self.remote_fingerprint,
            )
        except ChunkProtocolError as exc:
            raise VerificationError(str(exc)) from exc

    def _read_chunk_policy(self) -> dict[str, Any]:
        output = io.BytesIO()
        digest, size = self._stream_remote(
            CHUNK_POLICY_PATH,
            expected_size=64 * 1024,
            output_stream=output,
        )
        raw = output.getvalue()
        if size != len(raw) or digest != sha256_bytes(raw):
            raise VerificationError(
                "rclone chunk policy failed plaintext verification"
            )
        try:
            value = strict_json_loads(raw.decode("utf-8"))
        except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
            raise VerificationError("rclone chunk policy is invalid") from exc
        policy = self._validate_chunk_policy_value(value)
        if raw != canonical_json_bytes(policy):
            raise VerificationError("rclone chunk policy is not canonical")
        return policy

    def _chunk_policy(self, *, initialize: bool = False) -> dict[str, Any]:
        with self._boundary_lock:
            self.assert_private()
            if self._chunk_policy_cache is not None:
                return dict(self._chunk_policy_cache)
            names = set(self._list_names(""))
            if CHUNK_POLICY_PATH not in names:
                if not initialize:
                    raise ConfigurationError(
                        "encrypted chunk storage is not initialized; run "
                        "configure-chunking --enable"
                    )
                policy = chunk_policy_document(
                    vault_id=VAULT_ID,
                    store_id=self.store_id,
                    container_id=self.container_id,
                    remote_fingerprint=self.remote_fingerprint,
                    key_epoch=secrets.token_hex(32),
                )
                raw = canonical_json_bytes(policy)
                temporary_root = self.data_dir / "tmp"
                ensure_private_dir(temporary_root)
                fd, temporary_name = tempfile.mkstemp(
                    prefix=".chunk-policy-",
                    suffix=".json",
                    dir=str(temporary_root),
                )
                temporary = Path(temporary_name)
                transfer_failure: VaultSyncError | None = None
                try:
                    with os.fdopen(fd, "wb") as stream:
                        fd = -1
                        stream.write(raw)
                        stream.flush()
                        os.fsync(stream.fileno())
                    _safe_chmod(temporary, 0o600)
                    try:
                        self._copyto(
                            temporary,
                            CHUNK_POLICY_PATH,
                            len(raw),
                        )
                    except VaultSyncError as exc:
                        transfer_failure = exc
                finally:
                    if fd >= 0:
                        with contextlib.suppress(OSError):
                            os.close(fd)
                    with contextlib.suppress(FileNotFoundError):
                        temporary.unlink()
                try:
                    remote_policy = self._read_chunk_policy()
                except VaultSyncError:
                    if transfer_failure is not None:
                        raise transfer_failure
                    raise
                policy = remote_policy
            else:
                policy = self._read_chunk_policy()
            self._chunk_policy_cache = dict(policy)
            return dict(policy)

    def initialize_chunk_policy(self) -> dict[str, Any]:
        policy = self._chunk_policy(initialize=True)
        return {
            "schema_version": "memory-vault-chunk-storage/v1",
            "enabled": True,
            "store_id": self.store_id,
            "driver": self.driver,
            "reader_protocol": policy["reader_protocol"],
            "algorithm": policy["algorithm"],
            "encryption_policy": policy["encryption_policy"],
            "key_epoch": policy["key_epoch"],
            "chunk_size": policy["chunk_size"],
            "maximum_chunks": policy["maximum_chunks"],
            "remote_deletion_performed": False,
        }

    @staticmethod
    def _chunk_batches(values: Sequence[str]) -> Iterator[list[str]]:
        # Keep command lines below the Windows process-creation limit while
        # still reducing a 1-GiB artifact to one provider call per direction.
        for offset in range(0, len(values), 128):
            yield list(values[offset : offset + 128])

    def _list_remote_chunk_ids(
        self,
        policy: Mapping[str, Any],
        content_ids: set[str],
    ) -> set[str]:
        ordered = sorted(
            validate_sha256(item, "chunk content_id")
            for item in content_ids
        )
        if len(ordered) > MAX_CHUNK_COUNT:
            raise VerificationError("chunk lookup exceeds the fixed bound")
        if not ordered:
            return set()
        epoch = validate_sha256(policy.get("key_epoch"), "chunk key epoch")
        parent = f"{CHUNK_ROOT}/{epoch}"
        found: set[str] = set()
        for batch in self._chunk_batches(ordered):
            arguments = [
                "lsf",
                self._remote_path(parent),
                "--recursive",
                "--files-only",
                "--format=p",
            ]
            for content_id in batch:
                arguments.extend(
                    ["--include", f"/{content_id[:2]}/{content_id}"]
                )
            result = self._run_command(*arguments, timeout=120)
            if result.returncode == 3:
                continue
            if result.returncode != 0:
                raise OfflineError(
                    "rclone encrypted chunk lookup failed "
                    f"(exit {result.returncode})"
                )
            try:
                lines = result.stdout.decode("utf-8", "strict").splitlines()
            except UnicodeDecodeError as exc:
                raise VerificationError(
                    "rclone chunk listing is not UTF-8"
                ) from exc
            batch_set = set(batch)
            for raw in lines:
                relative = unicodedata.normalize("NFC", raw.strip())
                match = re.fullmatch(r"([0-9a-f]{2})/([0-9a-f]{64})", relative)
                if (
                    match is None
                    or match.group(1) != match.group(2)[:2]
                    or match.group(2) not in batch_set
                    or match.group(2) in found
                ):
                    raise VerificationError(
                        "rclone chunk lookup returned an unexpected path"
                    )
                found.add(match.group(2))
        return found

    @staticmethod
    def _chunk_transfer_limit(sizes: Mapping[str, int]) -> int:
        if not sizes:
            raise VerificationError("chunk transfer set is empty")
        return sum(
            RcloneCryptAdapter._encrypted_transfer_limit(int(size))
            for size in sizes.values()
        )

    def _copy_chunk_files(
        self,
        staging_root: Path,
        policy: Mapping[str, Any],
        sizes: Mapping[str, int],
    ) -> None:
        assert_plain_path(staging_root, require_file=False)
        expected = {
            PurePosixPath(content_id[:2], content_id).as_posix(): int(size)
            for content_id, size in sizes.items()
        }
        actual: dict[str, int] = {}
        for path in staging_root.rglob("*"):
            if path.is_symlink():
                raise PrivacyError("chunk staging contains a symbolic link")
            if path.is_dir():
                assert_plain_path(path, require_file=False)
                continue
            assert_plain_path(path, require_file=True)
            relative = path.relative_to(staging_root).as_posix()
            actual[relative] = path.stat().st_size
        if actual != expected:
            raise VerificationError("chunk staging inventory is invalid")
        epoch = validate_sha256(policy.get("key_epoch"), "chunk key epoch")
        result = self._run_command(
            "copy",
            str(staging_root),
            self._remote_path(f"{CHUNK_ROOT}/{epoch}"),
            "--immutable",
            "--no-traverse",
            "--no-update-modtime",
            f"--max-transfer={self._chunk_transfer_limit(sizes)}B",
            timeout=1800,
        )
        if result.returncode != 0:
            lowered = result.stderr.lower()
            if b"immutable file modified" in lowered or b"do not match" in lowered:
                raise VerificationError(
                    "rclone immutable chunk already contains different bytes"
                )
            raise OfflineError(
                "rclone encrypted chunk upload failed "
                f"(exit {result.returncode})"
            )

    def _fetch_chunk_files(
        self,
        policy: Mapping[str, Any],
        sizes: Mapping[str, int],
        destination: Path,
    ) -> None:
        ensure_private_dir(destination)
        if any(destination.iterdir()):
            raise VerificationError("chunk download staging is not empty")
        ordered = sorted(sizes)
        epoch = validate_sha256(policy.get("key_epoch"), "chunk key epoch")
        parent = f"{CHUNK_ROOT}/{epoch}"
        for batch in self._chunk_batches(ordered):
            batch_sizes = {item: int(sizes[item]) for item in batch}
            arguments = [
                "copy",
                self._remote_path(parent),
                str(destination),
                "--immutable",
                "--no-traverse",
                "--no-update-modtime",
                f"--max-transfer={self._chunk_transfer_limit(batch_sizes)}B",
            ]
            for content_id in batch:
                arguments.extend(
                    ["--include", f"/{content_id[:2]}/{content_id}"]
                )
            result = self._run_command(*arguments, timeout=1800)
            if result.returncode != 0:
                raise OfflineError(
                    "rclone encrypted chunk download failed "
                    f"(exit {result.returncode})"
                )

    @staticmethod
    def _stable_chunk_content_id(path: Path, expected_size: int) -> str:
        assert_plain_path(path, require_file=True)
        before = path.stat()
        if before.st_size != expected_size:
            raise VerificationError("chunk file size is invalid")
        digest = new_chunk_hasher()
        total = 0
        with path.open("rb", buffering=0) as stream:
            while True:
                block = stream.read(1024 * 1024)
                if not block:
                    break
                digest.update(block)
                total += len(block)
        after = path.stat()
        stable_fields = (
            "st_dev",
            "st_ino",
            "st_size",
            "st_mtime_ns",
            "st_ctime_ns",
        )
        if (
            total != expected_size
            or any(
                getattr(before, field, None) != getattr(after, field, None)
                for field in stable_fields
            )
        ):
            raise VerificationError("chunk file changed during verification")
        return digest.hexdigest()

    def _verify_chunk_files(
        self,
        root: Path,
        sizes: Mapping[str, int],
    ) -> None:
        expected_paths = {
            PurePosixPath(content_id[:2], content_id).as_posix()
            for content_id in sizes
        }
        actual_paths: set[str] = set()
        for path in root.rglob("*"):
            if path.is_symlink():
                raise PrivacyError("chunk download contains a symbolic link")
            if path.is_dir():
                assert_plain_path(path, require_file=False)
                continue
            assert_plain_path(path, require_file=True)
            actual_paths.add(path.relative_to(root).as_posix())
        if actual_paths != expected_paths:
            raise VerificationError("chunk download inventory is incomplete")
        for content_id, size in sizes.items():
            path = root / content_id[:2] / content_id
            if self._stable_chunk_content_id(path, int(size)) != content_id:
                raise VerificationError(
                    "downloaded chunk failed plaintext identity verification"
                )

    def _cryptcheck_chunk_files(
        self,
        root: Path,
        policy: Mapping[str, Any],
        sizes: Mapping[str, int],
    ) -> bool:
        """Verify encrypted remote bytes without downloading full chunks.

        rclone cryptcheck reads each encrypted object's nonce, encrypts the
        already verified local plaintext with that nonce, and compares the
        resulting ciphertext checksum with the wrapped provider checksum. A
        backend without a usable checksum returns false here and the caller
        falls back to a bounded plaintext download.
        """

        self._verify_chunk_files(root, sizes)
        ordered = sorted(sizes)
        if not ordered:
            raise VerificationError("chunk cryptcheck set is empty")
        epoch = validate_sha256(policy.get("key_epoch"), "chunk key epoch")
        parent = f"{CHUNK_ROOT}/{epoch}"
        for batch in self._chunk_batches(ordered):
            arguments = [
                "cryptcheck",
                str(root),
                self._remote_path(parent),
                "--one-way",
                "--max-backlog=128",
                "--combined=-",
            ]
            for content_id in batch:
                arguments.extend(
                    ["--include", f"/{content_id[:2]}/{content_id}"]
                )
            result = self._run_command(*arguments, timeout=1800)
            if result.returncode != 0:
                return False
            try:
                lines = result.stdout.decode("utf-8", "strict").splitlines()
            except UnicodeDecodeError:
                return False
            expected = {
                f"{content_id[:2]}/{content_id}" for content_id in batch
            }
            observed: set[str] = set()
            for line in lines:
                match = re.fullmatch(
                    r"= ([0-9a-f]{2}/[0-9a-f]{64})",
                    unicodedata.normalize("NFC", line.strip()),
                )
                if match is None or match.group(1) in observed:
                    return False
                observed.add(match.group(1))
            if observed != expected:
                return False
        return True

    def _chunk_receipt_path(
        self,
        policy: Mapping[str, Any],
        content_id: str,
    ) -> Path:
        epoch = validate_sha256(policy.get("key_epoch"), "chunk key epoch")
        digest = validate_sha256(content_id, "chunk content_id")
        return (
            self.data_dir
            / "state"
            / "chunks"
            / self.store_id
            / epoch
            / digest[:2]
            / f"{digest}.json"
        )

    def _chunk_receipt_valid(
        self,
        policy: Mapping[str, Any],
        content_id: str,
        size: int,
    ) -> bool:
        path = self._chunk_receipt_path(policy, content_id)
        if (
            not path.exists()
            or path.is_symlink()
            or not path.is_file()
            or path.stat().st_size > 4096
        ):
            return False
        try:
            assert_plain_path(path, require_file=True)
            value = load_json(path)
        except (VaultSyncError, OSError, ValueError):
            return False
        expected = {
            "schema_version": CHUNK_RECEIPT_SCHEMA,
            "store_id": self.store_id,
            "container_id": self.container_id,
            "remote_fingerprint": self.remote_fingerprint,
            "key_epoch": policy.get("key_epoch"),
            "algorithm": CHUNK_ALGORITHM,
            "encryption_policy": CHUNK_ENCRYPTION_POLICY,
            "content_id": content_id,
            "size": int(size),
            "plaintext_verification": "domain-sha256-and-size-v1",
        }
        return bool(
            isinstance(value, Mapping)
            and set(value)
            == set(expected) | {"remote_verification", "verified_at"}
            and all(value.get(key) == item for key, item in expected.items())
            and value.get("remote_verification")
            in {"rclone-cryptcheck", "rclone-plaintext-download"}
            and isinstance(value.get("verified_at"), str)
        )

    def _record_chunk_receipt(
        self,
        policy: Mapping[str, Any],
        content_id: str,
        size: int,
        remote_verification: str,
    ) -> None:
        if remote_verification not in {
            "rclone-cryptcheck",
            "rclone-plaintext-download",
        }:
            raise VerificationError(
                "chunk remote verification method is invalid"
            )
        atomic_write_json(
            self._chunk_receipt_path(policy, content_id),
            {
                "schema_version": CHUNK_RECEIPT_SCHEMA,
                "store_id": self.store_id,
                "container_id": self.container_id,
                "remote_fingerprint": self.remote_fingerprint,
                "key_epoch": policy.get("key_epoch"),
                "algorithm": CHUNK_ALGORITHM,
                "encryption_policy": CHUNK_ENCRYPTION_POLICY,
                "content_id": validate_sha256(
                    content_id,
                    "chunk content_id",
                ),
                "size": int(size),
                "plaintext_verification": "domain-sha256-and-size-v1",
                "remote_verification": remote_verification,
                "verified_at": utc_now(),
            },
        )

    def _verify_remote_chunks_from_local(
        self,
        policy: Mapping[str, Any],
        sizes: Mapping[str, int],
        local_root: Path,
        temporary_root: Path,
    ) -> str:
        """Prove remote encrypted chunks and persist scoped local receipts."""

        if not sizes:
            raise VerificationError("chunk verification set is empty")
        if self._cryptcheck_chunk_files(local_root, policy, sizes):
            method = "rclone-cryptcheck"
        else:
            with tempfile.TemporaryDirectory(
                prefix="chunk-download-verify-",
                dir=str(temporary_root),
            ) as temporary:
                download_root = Path(temporary)
                self._fetch_chunk_files(
                    policy,
                    sizes,
                    download_root,
                )
                self._verify_chunk_files(download_root, sizes)
            method = "rclone-plaintext-download"
        for content_id in sorted(sizes):
            self._record_chunk_receipt(
                policy,
                content_id,
                int(sizes[content_id]),
                method,
            )
        return method

    @staticmethod
    def _chunk_source_snapshot(
        path: Path,
        expected_size: int,
    ) -> ChunkSourceSnapshot:
        assert_plain_path(path, require_file=True)
        stat = path.stat()
        if stat.st_size != expected_size:
            raise VerificationError("artifact size changed during chunking")
        return ChunkSourceSnapshot(
            device=getattr(stat, "st_dev", None),
            inode=getattr(stat, "st_ino", None),
            mode=getattr(stat, "st_mode", None),
            size=int(stat.st_size),
            mtime_ns=getattr(stat, "st_mtime_ns", None),
            ctime_ns=getattr(stat, "st_ctime_ns", None),
        )

    @staticmethod
    def _scan_local_chunks(
        path: Path,
        expected_sha256: str,
        expected_size: int,
    ) -> tuple[list[dict[str, Any]], ChunkSourceSnapshot]:
        assert_plain_path(path, require_file=True)
        expected_digest = validate_sha256(
            expected_sha256,
            "artifact sha256",
        )
        if (
            not isinstance(expected_size, int)
            or isinstance(expected_size, bool)
            or not 1 <= expected_size <= CHUNK_SIZE_BYTES * MAX_CHUNK_COUNT
        ):
            raise VerificationError("artifact is outside chunk protocol bounds")
        before = RcloneCryptAdapter._chunk_source_snapshot(
            path,
            expected_size,
        )
        full_digest = hashlib.sha256()
        descriptors: list[dict[str, Any]] = []
        total = 0
        with path.open("rb", buffering=0) as stream:
            while total < expected_size:
                chunk_offset = total
                chunk_limit = min(CHUNK_SIZE_BYTES, expected_size - total)
                chunk_digest = new_chunk_hasher()
                chunk_total = 0
                while chunk_total < chunk_limit:
                    block = stream.read(
                        min(1024 * 1024, chunk_limit - chunk_total)
                    )
                    if not block:
                        raise VerificationError(
                            "artifact ended before its declared size"
                        )
                    full_digest.update(block)
                    chunk_digest.update(block)
                    chunk_total += len(block)
                    total += len(block)
                descriptors.append(
                    {
                        "index": len(descriptors),
                        "offset": chunk_offset,
                        "size": chunk_total,
                        "content_id": chunk_digest.hexdigest(),
                    }
                )
            if stream.read(1):
                raise VerificationError("artifact exceeds its declared size")
        after = RcloneCryptAdapter._chunk_source_snapshot(
            path,
            expected_size,
        )
        if before != after:
            raise VerificationError("artifact changed during chunk scan")
        if (
            total != expected_size
            or full_digest.hexdigest() != expected_digest
            or not 1 <= len(descriptors) <= MAX_CHUNK_COUNT
        ):
            raise VerificationError("artifact failed chunk scan verification")
        return descriptors, after

    @staticmethod
    def _stage_missing_chunks(
        path: Path,
        descriptors: Sequence[Mapping[str, Any]],
        missing: set[str],
        staging_root: Path,
        expected_snapshot: ChunkSourceSnapshot,
    ) -> dict[str, int]:
        ensure_private_dir(staging_root)
        if RcloneCryptAdapter._chunk_source_snapshot(
            path,
            expected_snapshot.size,
        ) != expected_snapshot:
            raise VerificationError(
                "artifact changed before selective chunk staging"
            )
        staged: dict[str, int] = {}
        selected: dict[str, tuple[int, int]] = {}
        for descriptor in descriptors:
            content_id = validate_sha256(
                descriptor.get("content_id"),
                "chunk content_id",
            )
            if content_id not in missing or content_id in selected:
                continue
            offset = descriptor.get("offset")
            size = descriptor.get("size")
            if (
                not isinstance(offset, int)
                or isinstance(offset, bool)
                or offset < 0
                or not isinstance(size, int)
                or isinstance(size, bool)
                or not 1 <= size <= CHUNK_SIZE_BYTES
                or offset + size > expected_snapshot.size
            ):
                raise VerificationError("chunk staging descriptor is invalid")
            selected[content_id] = (offset, size)
        if set(selected) != missing:
            raise VerificationError("chunk staging did not cover every upload")
        with path.open("rb", buffering=0) as source:
            for content_id, (offset, size) in sorted(
                selected.items(),
                key=lambda item: item[1][0],
            ):
                if source.seek(offset) != offset:
                    raise VerificationError("chunk staging seek failed")
                target_path = staging_root / content_id[:2] / content_id
                ensure_private_dir(target_path.parent)
                target = target_path.open("xb", buffering=0)
                _safe_chmod(target_path, 0o600)
                digest = new_chunk_hasher()
                remaining = size
                try:
                    while remaining:
                        block = source.read(min(1024 * 1024, remaining))
                        if not block:
                            raise VerificationError(
                                "artifact ended during chunk staging"
                            )
                        digest.update(block)
                        target.write(block)
                        remaining -= len(block)
                    target.flush()
                    os.fsync(target.fileno())
                finally:
                    target.close()
                if digest.hexdigest() != content_id:
                    raise VerificationError(
                        "artifact changed between chunk scan and staging"
                    )
                staged[content_id] = size
        if set(staged) != missing:
            raise VerificationError("chunk staging did not cover every upload")
        if RcloneCryptAdapter._chunk_source_snapshot(
            path,
            expected_snapshot.size,
        ) != expected_snapshot:
            raise VerificationError(
                "artifact changed during selective chunk staging"
            )
        return staged

    def _read_chunk_manifest(
        self,
        policy: Mapping[str, Any],
        manifest_id: str,
        *,
        artifact_sha256: str,
        artifact_size: int,
        mime_type: str,
    ) -> dict[str, Any]:
        digest_id = validate_sha256(manifest_id, "chunk manifest_id")
        output = io.BytesIO()
        digest, size = self._stream_remote(
            chunk_manifest_relative_path(policy, digest_id),
            expected_size=MAX_CHUNK_MANIFEST_BYTES,
            output_stream=output,
        )
        raw = output.getvalue()
        if size != len(raw) or digest != sha256_bytes(raw):
            raise VerificationError(
                "encrypted chunk manifest failed plaintext verification"
            )
        try:
            value = strict_json_loads(raw.decode("utf-8"))
            manifest = validate_chunk_manifest(
                value,
                policy=policy,
                artifact_sha256=artifact_sha256,
                artifact_size=artifact_size,
                mime_type=mime_type,
            )
            expected_raw = chunk_manifest_bytes(manifest)
            observed_id = chunk_manifest_id(manifest)
        except (
            ChunkProtocolError,
            UnicodeDecodeError,
            ValueError,
            json.JSONDecodeError,
        ) as exc:
            raise VerificationError("encrypted chunk manifest is invalid") from exc
        if raw != expected_raw or observed_id != digest_id:
            raise VerificationError(
                "encrypted chunk manifest identity does not match"
            )
        return manifest

    def _upload_chunked(
        self,
        path: Path,
        sha256: str,
        size: int,
        mime_type: str,
    ) -> VerifiedDriveObject:
        policy = self._chunk_policy()
        descriptors, source_snapshot = self._scan_local_chunks(
            path,
            sha256,
            size,
        )
        try:
            manifest = chunk_manifest_document(
                policy=policy,
                artifact_sha256=sha256,
                artifact_size=size,
                mime_type=mime_type,
                chunks=descriptors,
            )
            manifest_id = chunk_manifest_id(manifest)
            manifest_raw = chunk_manifest_bytes(manifest)
        except ChunkProtocolError as exc:
            raise VerificationError(str(exc)) from exc
        sizes: dict[str, int] = {}
        for descriptor in descriptors:
            content_id = str(descriptor["content_id"])
            chunk_size = int(descriptor["size"])
            previous = sizes.setdefault(content_id, chunk_size)
            if previous != chunk_size:
                raise VerificationError(
                    "one chunk identity has conflicting sizes"
                )
        desired = set(sizes)
        present = self._list_remote_chunk_ids(policy, desired)
        missing = desired - present
        unverified_present = {
            content_id
            for content_id in present
            if not self._chunk_receipt_valid(
                policy,
                content_id,
                sizes[content_id],
            )
        }
        transfer_failure: VaultSyncError | None = None
        temporary_root = self.data_dir / "tmp"
        ensure_private_dir(temporary_root)
        with tempfile.TemporaryDirectory(
            prefix="chunk-operation-",
            dir=str(temporary_root),
        ) as temporary:
            operation_root = Path(temporary)
            missing_root = operation_root / "upload"
            existing_root = operation_root / "existing"
            staged_missing: dict[str, int] = {}
            if missing:
                staged_missing = self._stage_missing_chunks(
                    path,
                    descriptors,
                    missing,
                    missing_root,
                    source_snapshot,
                )
                try:
                    self._copy_chunk_files(
                        missing_root,
                        policy,
                        staged_missing,
                    )
                except VaultSyncError as exc:
                    # The batch may have completed remotely before the process
                    # reported failure, or a peer may have won the same
                    # immutable paths. Exact plaintext verification below is
                    # the only convergence authority.
                    transfer_failure = exc
            present_after = self._list_remote_chunk_ids(policy, desired)
            if present_after != desired:
                if transfer_failure is not None:
                    raise transfer_failure
                raise VerificationError(
                    "encrypted chunk upload did not materialize every object"
                )
            if staged_missing:
                self._verify_remote_chunks_from_local(
                    policy,
                    staged_missing,
                    missing_root,
                    temporary_root,
                )
            if unverified_present:
                staged_existing = self._stage_missing_chunks(
                    path,
                    descriptors,
                    unverified_present,
                    existing_root,
                    source_snapshot,
                )
                self._verify_remote_chunks_from_local(
                    policy,
                    staged_existing,
                    existing_root,
                    temporary_root,
                )
        if self._chunk_source_snapshot(path, size) != source_snapshot:
            raise VerificationError(
                "local artifact changed during encrypted chunk upload"
            )
        fd, manifest_name = tempfile.mkstemp(
            prefix=f".{manifest_id}.",
            suffix=".manifest",
            dir=str(temporary_root),
        )
        manifest_path = Path(manifest_name)
        manifest_failure: VaultSyncError | None = None
        try:
            with os.fdopen(fd, "wb") as stream:
                fd = -1
                stream.write(manifest_raw)
                stream.flush()
                os.fsync(stream.fileno())
            _safe_chmod(manifest_path, 0o600)
            try:
                self._copyto(
                    manifest_path,
                    chunk_manifest_relative_path(policy, manifest_id),
                    len(manifest_raw),
                )
            except VaultSyncError as exc:
                manifest_failure = exc
            try:
                self._read_chunk_manifest(
                    policy,
                    manifest_id,
                    artifact_sha256=sha256,
                    artifact_size=size,
                    mime_type=mime_type,
                )
            except VerificationError:
                raise
            except VaultSyncError:
                if manifest_failure is not None:
                    raise manifest_failure
                raise
            if self._chunk_source_snapshot(path, size) != source_snapshot:
                raise VerificationError(
                    "local artifact changed before chunk manifest publication"
                )
        finally:
            if fd >= 0:
                with contextlib.suppress(OSError):
                    os.close(fd)
            with contextlib.suppress(FileNotFoundError):
                manifest_path.unlink()
        return VerifiedDriveObject(
            store_id=self.store_id,
            driver=self.driver,
            file_id=f"chunk-manifest-{manifest_id}",
            parent_id=self.container_id,
            sha256=sha256,
            size=size,
            mime_type=mime_type,
            verification_level="rclone-crypt-chunk-manifest-sha256",
            storage_mode="chunked-v1",
        )

    def _download_chunked(
        self,
        artifact: Mapping[str, Any],
        destination: Path,
    ) -> None:
        storage_ref = _artifact_storage_ref(artifact)
        if (
            storage_ref["driver"] != self.driver
            or storage_ref["store_id"] != self.store_id
            or storage_ref["container_id"] != self.container_id
            or storage_ref["verification_level"]
            != "rclone-crypt-chunk-manifest-sha256"
        ):
            raise VerificationError(
                "chunked artifact belongs to a different encrypted store"
            )
        match = re.fullmatch(
            r"chunk-manifest-([0-9a-f]{64})",
            storage_ref["object_id"],
        )
        if match is None:
            raise VerificationError("chunk manifest object identity is invalid")
        sha256 = validate_sha256(artifact.get("sha256"), "artifact.sha256")
        raw_size = artifact.get("size")
        if (
            not isinstance(raw_size, int)
            or isinstance(raw_size, bool)
            or not 1 <= raw_size <= CHUNK_SIZE_BYTES * MAX_CHUNK_COUNT
        ):
            raise VerificationError("chunked artifact size is invalid")
        size = raw_size
        raw_mime_type = artifact.get("mime_type")
        if not isinstance(raw_mime_type, str) or re.fullmatch(
            r"[a-z0-9.+-]+/[a-z0-9.+-]+",
            raw_mime_type,
        ) is None:
            raise VerificationError("chunked artifact MIME type is invalid")
        mime_type = raw_mime_type
        if destination.exists():
            existing_sha, existing_size = stable_hash_file(
                destination,
                inspect_text=False,
            )
            if existing_sha == sha256 and existing_size == size:
                return
            raise VerificationError(
                "versioned download target exists with different content"
            )
        policy = self._chunk_policy()
        manifest = self._read_chunk_manifest(
            policy,
            match.group(1),
            artifact_sha256=sha256,
            artifact_size=size,
            mime_type=mime_type,
        )
        chunk_sizes: dict[str, int] = {}
        for descriptor in manifest["chunks"]:
            content_id = str(descriptor["content_id"])
            chunk_size = int(descriptor["size"])
            previous = chunk_sizes.setdefault(content_id, chunk_size)
            if previous != chunk_size:
                raise VerificationError(
                    "chunk manifest reuses one identity with another size"
                )
        ensure_private_dir(destination.parent)
        temporary_root = self.data_dir / "tmp"
        ensure_private_dir(temporary_root)
        fd, output_name = tempfile.mkstemp(
            prefix=f".{sha256}.",
            suffix=".chunked-download",
            dir=str(destination.parent),
        )
        output_path = Path(output_name)
        try:
            with tempfile.TemporaryDirectory(
                prefix="chunk-restore-",
                dir=str(temporary_root),
            ) as temporary:
                chunk_root = Path(temporary)
                self._fetch_chunk_files(
                    policy,
                    chunk_sizes,
                    chunk_root,
                )
                self._verify_chunk_files(chunk_root, chunk_sizes)
                full_digest = hashlib.sha256()
                total = 0
                with os.fdopen(fd, "wb", buffering=0) as output:
                    fd = -1
                    for descriptor in manifest["chunks"]:
                        content_id = str(descriptor["content_id"])
                        remaining = int(descriptor["size"])
                        chunk_path = chunk_root / content_id[:2] / content_id
                        with chunk_path.open("rb", buffering=0) as source:
                            while remaining:
                                block = source.read(
                                    min(1024 * 1024, remaining)
                                )
                                if not block:
                                    raise VerificationError(
                                        "verified chunk ended during restore"
                                    )
                                output.write(block)
                                full_digest.update(block)
                                total += len(block)
                                remaining -= len(block)
                            if source.read(1):
                                raise VerificationError(
                                    "verified chunk exceeds its manifest size"
                                )
                    output.flush()
                    os.fsync(output.fileno())
            if full_digest.hexdigest() != sha256 or total != size:
                raise VerificationError(
                    "restored chunked artifact failed final SHA-256"
                )
            for content_id, chunk_size in chunk_sizes.items():
                self._record_chunk_receipt(
                    policy,
                    content_id,
                    chunk_size,
                    "rclone-plaintext-download",
                )
            _publish_temp_exclusive(output_path, destination, sha256, size)
        finally:
            if fd >= 0:
                with contextlib.suppress(OSError):
                    os.close(fd)
            with contextlib.suppress(FileNotFoundError):
                output_path.unlink()

    def _verified_remote_object(
        self,
        sha256: str,
        size: int,
        mime_type: str,
    ) -> VerifiedDriveObject:
        relative = self._object_relative_path(sha256)
        digest, downloaded_size = self._stream_remote(
            relative,
            expected_size=size,
        )
        if digest != sha256 or downloaded_size != size:
            raise VerificationError(
                "rclone decrypted object failed exact SHA-256 verification"
            )
        return VerifiedDriveObject(
            store_id=self.store_id,
            driver=self.driver,
            file_id=f"sha256-{sha256}",
            parent_id=self.container_id,
            sha256=sha256,
            size=size,
            mime_type=mime_type,
            verification_level="rclone-crypt-download-sha256",
        )

    def find_verified(
        self,
        sha256: str,
        size: int,
        mime_type: str,
    ) -> VerifiedDriveObject | None:
        key = (
            validate_sha256(sha256, "artifact sha256"),
            int(size),
            str(mime_type),
        )
        if key[1] < 1:
            raise VerificationError("artifact size is invalid")
        with self._lookup_cache_lock:
            cached = self._verified_lookup_cache.get(key)
            if cached is not None:
                return cached
        self.assert_private()
        parent = f"{RCLONE_OBJECT_PREFIX}/{key[0][:2]}"
        names = self._list_names(parent)
        for name in names:
            if re.fullmatch(r"[0-9a-f]{64}", name) is None:
                raise PrivacyError(
                    "rclone content-address directory contains an unexpected object"
                )
        if key[0] not in names:
            return None
        verified = self._verified_remote_object(*key)
        with self._lookup_cache_lock:
            self._verified_lookup_cache[key] = verified
        return verified

    def upload_and_verify(
        self,
        path: Path,
        sha256: str,
        size: int,
        mime_type: str,
    ) -> VerifiedDriveObject:
        self.assert_private()
        if self.should_chunk(size):
            return self._upload_chunked(
                path,
                validate_sha256(sha256, "artifact sha256"),
                int(size),
                str(mime_type),
            )
        actual_sha, actual_size = stable_hash_file(path, inspect_text=False)
        if actual_sha != sha256 or actual_size != size:
            raise VerificationError("local artifact changed before rclone upload")
        existing = self.find_verified(sha256, size, mime_type)
        if existing is not None:
            return existing
        transfer_failure: VaultSyncError | None = None
        try:
            self._copyto(path, self._object_relative_path(sha256), size)
        except VaultSyncError as exc:
            # A second device may win the same content-addressed immutable
            # object between our listing and copy. Never trust the copy error
            # alone: exact decrypted bytes can still prove that the desired
            # object exists and make the operation idempotent.
            transfer_failure = exc
        post_sha, post_size = stable_hash_file(path, inspect_text=False)
        if post_sha != sha256 or post_size != size:
            raise VerificationError("local artifact changed during rclone upload")
        try:
            verified = self._verified_remote_object(sha256, size, mime_type)
        except VerificationError:
            raise
        except VaultSyncError:
            if transfer_failure is not None:
                raise transfer_failure
            raise
        with self._lookup_cache_lock:
            self._verified_lookup_cache[(sha256, size, mime_type)] = verified
        return verified

    def download_and_verify(
        self,
        artifact: Mapping[str, Any],
        destination: Path,
    ) -> None:
        self.assert_private()
        storage_mode = artifact.get("storage_mode", "full")
        if storage_mode == "chunked-v1":
            self._download_chunked(artifact, destination)
            return
        if storage_mode != "full":
            raise VerificationError("rclone artifact storage mode is invalid")
        storage_ref = _artifact_storage_ref(artifact)
        if (
            storage_ref["driver"] != self.driver
            or storage_ref["store_id"] != self.store_id
            or storage_ref["container_id"] != self.container_id
        ):
            raise VerificationError(
                "artifact belongs to a different rclone object store"
            )
        sha256 = validate_sha256(artifact.get("sha256"), "artifact.sha256")
        size = int(artifact.get("size"))
        if storage_ref["object_id"] != f"sha256-{sha256}":
            raise VerificationError("rclone artifact object identity is invalid")
        if destination.exists():
            existing_sha, existing_size = stable_hash_file(
                destination,
                inspect_text=False,
            )
            if existing_sha == sha256 and existing_size == size:
                return
            raise VerificationError(
                "versioned download target exists with different content"
            )
        ensure_private_dir(destination.parent)
        fd, temporary_name = tempfile.mkstemp(
            prefix=f".{sha256}.",
            suffix=".download",
            dir=str(destination.parent),
        )
        temporary = Path(temporary_name)
        try:
            with os.fdopen(fd, "wb", buffering=0) as output_stream:
                fd = -1
                digest, downloaded_size = self._stream_remote(
                    self._object_relative_path(sha256),
                    expected_size=size,
                    output_stream=output_stream,
                )
                output_stream.flush()
                os.fsync(output_stream.fileno())
            if digest != sha256 or downloaded_size != size:
                raise VerificationError(
                    "downloaded rclone artifact failed exact SHA-256"
                )
            _publish_temp_exclusive(temporary, destination, sha256, size)
        finally:
            if fd >= 0:
                with contextlib.suppress(OSError):
                    os.close(fd)
            with contextlib.suppress(FileNotFoundError):
                temporary.unlink()


class GoogleDriveAdapter(DriveAdapter):
    API_ROOT = "https://www.googleapis.com/drive/v3"
    UPLOAD_ROOT = "https://www.googleapis.com/upload/drive/v3"
    TOKEN_URL = "https://oauth2.googleapis.com/token"

    def __init__(
        self,
        config: Mapping[str, Any],
        *,
        store_id: str | None = None,
    ):
        self.config = config
        store = _object_store_config(config, store_id)
        self.store_id = validate_identifier(
            store.get("store_id"),
            "object-store store_id",
        )
        self.driver = "google-drive-v3"
        root = store.get("root_folder_id")
        if not isinstance(root, str) or not re.fullmatch(r"[A-Za-z0-9_-]{2,256}", root):
            raise ConfigurationError("Drive root_folder_id is not configured")
        client_id = store.get("oauth_client_id")
        if not isinstance(client_id, str) or not client_id:
            raise ConfigurationError("Drive oauth_client_id is not configured")
        self.root_id = root
        self.client_id = client_id
        self.credential_host = str(
            store.get("credential_host")
            or "google-drive.memory-vault-sync.local"
        )
        self._token: str | None = None
        self._token_expiry = 0.0
        self._token_lock = threading.RLock()
        self._privacy_lock = threading.RLock()
        self._lookup_cache_lock = threading.RLock()
        # These caches are deliberately scoped to one adapter instance. They
        # remove duplicate checks inside one bounded flush without carrying a
        # trust decision across lifecycle invocations.
        self._private_root_verified = False
        self._verified_private_folders: set[str] = {self.root_id}
        self._verified_private_files: set[str] = set()
        self._verified_lookup_cache: dict[
            tuple[str, int, str], VerifiedDriveObject | None
        ] = {}

    def _credential(self) -> Mapping[str, Any]:
        fields = credential_get(self.credential_host, username="oauth")
        try:
            value = strict_json_loads(fields["password"])
        except (ValueError, json.JSONDecodeError) as exc:
            raise AuthenticationError("stored Drive credential is invalid") from exc
        if not isinstance(value, Mapping):
            raise AuthenticationError("stored Drive credential is invalid")
        refresh = value.get("refresh_token")
        secret = value.get("client_secret")
        if not isinstance(refresh, str) or not refresh:
            raise AuthenticationError("Drive refresh token is missing")
        if secret is not None and not isinstance(secret, str):
            raise AuthenticationError("Drive client secret is invalid")
        return value

    def _access_token(self) -> str:
        with self._token_lock:
            return self._access_token_unlocked()

    def _access_token_unlocked(self) -> str:
        if self._token and time.monotonic() < self._token_expiry - 60:
            return self._token
        credential = self._credential()
        form = {
            "client_id": self.client_id,
            "refresh_token": credential["refresh_token"],
            "grant_type": "refresh_token",
        }
        if credential.get("client_secret"):
            form["client_secret"] = credential["client_secret"]
        request = urllib.request.Request(
            self.TOKEN_URL,
            data=urllib.parse.urlencode(form).encode("ascii"),
            headers={"Content-Type": "application/x-www-form-urlencoded"},
            method="POST",
        )
        try:
            with open_verified_url(
                request,
                timeout=20,
                policy=GOOGLE_OAUTH_POLICY,
            ) as response:
                value = strict_json_loads(response.read(1024 * 1024).decode("utf-8"))
        except urllib.error.HTTPError as exc:
            if exc.code in {400, 401, 403}:
                raise AuthenticationError("Drive OAuth refresh failed") from exc
            raise OfflineError("Drive OAuth service is unavailable") from exc
        except (urllib.error.URLError, TimeoutError, socket.timeout) as exc:
            raise OfflineError("Drive OAuth service is offline") from exc
        token = value.get("access_token") if isinstance(value, Mapping) else None
        if not isinstance(token, str) or not token:
            raise AuthenticationError("Drive OAuth response has no access token")
        expires = value.get("expires_in", 3600)
        self._token = token
        self._token_expiry = time.monotonic() + int(expires)
        return token

    def _request(
        self,
        url: str,
        *,
        method: str = "GET",
        body: bytes | None = None,
        headers: Mapping[str, str] | None = None,
        maximum: int = 8 * 1024 * 1024,
        timeout: float = 30,
    ) -> tuple[int, Mapping[str, str], bytes]:
        request_headers = {
            "Authorization": f"Bearer {self._access_token()}",
            "User-Agent": f"memory-vault-sync/{VERSION}",
        }
        if headers:
            request_headers.update(headers)
        request = urllib.request.Request(
            url,
            data=body,
            headers=request_headers,
            method=method,
        )
        try:
            with open_verified_url(
                request,
                timeout=timeout,
                policy=GOOGLE_DRIVE_API_POLICY,
            ) as response:
                data = response.read(maximum + 1)
                if len(data) > maximum:
                    raise VerificationError("Drive response exceeded the fixed limit")
                return response.status, dict(response.headers.items()), data
        except urllib.error.HTTPError as exc:
            if exc.code in {401, 403}:
                with self._token_lock:
                    self._token = None
                with self._privacy_lock:
                    self._private_root_verified = False
                raise AuthenticationError("Drive authorization or permission failed") from exc
            if exc.code in {408, 429, 500, 502, 503, 504}:
                raise OfflineError("Drive request is temporarily unavailable") from exc
            raise VerificationError(f"Drive request failed with HTTP {exc.code}") from exc
        except (urllib.error.URLError, TimeoutError, socket.timeout) as exc:
            raise OfflineError("Drive request is offline") from exc

    def _json_request(
        self,
        url: str,
        *,
        method: str = "GET",
        value: Any | None = None,
    ) -> Mapping[str, Any]:
        body = None
        headers: dict[str, str] = {}
        if value is not None:
            body = canonical_json_bytes(value)
            headers["Content-Type"] = "application/json; charset=utf-8"
        _, _, raw = self._request(url, method=method, body=body, headers=headers)
        try:
            parsed = strict_json_loads(raw.decode("utf-8"))
        except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
            raise VerificationError("Drive returned invalid JSON") from exc
        if not isinstance(parsed, Mapping):
            raise VerificationError("Drive returned a non-object JSON value")
        return parsed

    def assert_private(self) -> None:
        with self._privacy_lock:
            self._assert_private_unlocked()

    def _assert_private_unlocked(self) -> None:
        if self._private_root_verified:
            return
        fields = "id,name,mimeType,trashed,owners(emailAddress,permissionId)"
        metadata = self._json_request(
            f"{self.API_ROOT}/files/{urllib.parse.quote(self.root_id)}?"
            + urllib.parse.urlencode({"fields": fields, "supportsAllDrives": "true"})
        )
        if metadata.get("id") != self.root_id or metadata.get("trashed") is True:
            raise PrivacyError("Drive root folder is missing or trashed")
        if metadata.get("mimeType") != "application/vnd.google-apps.folder":
            raise PrivacyError("Drive root is not a folder")
        permissions = self._json_request(
            f"{self.API_ROOT}/files/{urllib.parse.quote(self.root_id)}/permissions?"
            + urllib.parse.urlencode(
                {
                    "fields": "permissions(id,type,role,deleted,allowFileDiscovery)",
                    "supportsAllDrives": "true",
                }
            )
        )
        items = permissions.get("permissions")
        if not isinstance(items, list) or not items:
            raise PrivacyError("Drive permissions could not be verified")
        active = [
            item
            for item in items
            if isinstance(item, Mapping) and item.get("deleted") is not True
        ]
        if len(active) != 1:
            raise PrivacyError("Drive root is shared; publication refused")
        permission = active[0]
        if permission.get("type") != "user" or permission.get("role") != "owner":
            raise PrivacyError("Drive root is not owner-only; publication refused")
        self._private_root_verified = True

    def _assert_file_owner_only(self, file_id: str) -> None:
        with self._lookup_cache_lock:
            if file_id in self._verified_private_files:
                return
        permissions = self._json_request(
            f"{self.API_ROOT}/files/{urllib.parse.quote(file_id)}/permissions?"
            + urllib.parse.urlencode(
                {
                    "fields": "permissions(id,type,role,deleted,allowFileDiscovery)",
                    "supportsAllDrives": "true",
                }
            )
        )
        items = permissions.get("permissions")
        if not isinstance(items, list) or not items:
            raise PrivacyError("Drive object permissions could not be verified")
        active = [
            item
            for item in items
            if isinstance(item, Mapping) and item.get("deleted") is not True
        ]
        if len(active) != 1:
            raise PrivacyError("Drive object is shared; publication refused")
        permission = active[0]
        if permission.get("type") != "user" or permission.get("role") != "owner":
            raise PrivacyError("Drive object is not owner-only; publication refused")
        with self._lookup_cache_lock:
            self._verified_private_files.add(file_id)

    def _assert_descendant_folder(self, folder_id: str) -> None:
        with self._lookup_cache_lock:
            if folder_id in self._verified_private_folders:
                return
        current = folder_id
        visited: list[str] = []
        for _ in range(16):
            with self._lookup_cache_lock:
                if current in self._verified_private_folders:
                    self._verified_private_folders.update(visited)
                    return
            if current in visited:
                raise PrivacyError("Drive folder ancestry contains a cycle")
            visited.append(current)
            fields = "id,mimeType,parents,trashed"
            metadata = self._json_request(
                f"{self.API_ROOT}/files/{urllib.parse.quote(current)}?"
                + urllib.parse.urlencode(
                    {"fields": fields, "supportsAllDrives": "true"}
                )
            )
            if (
                metadata.get("id") != current
                or metadata.get("trashed") is True
                or metadata.get("mimeType")
                != "application/vnd.google-apps.folder"
            ):
                raise PrivacyError("Drive artifact parent is not a valid folder")
            self._assert_file_owner_only(current)
            parents = metadata.get("parents")
            if not isinstance(parents, list) or len(parents) != 1:
                raise PrivacyError(
                    "Drive artifact parent is outside the private root"
                )
            parent = parents[0]
            if not isinstance(parent, str):
                raise PrivacyError(
                    "Drive artifact parent is outside the private root"
                )
            current = parent
        raise PrivacyError("Drive artifact folder ancestry is too deep")

    @staticmethod
    def _query_escape(value: str) -> str:
        return value.replace("\\", "\\\\").replace("'", "\\'")

    def _lookup(self, sha256: str) -> list[Mapping[str, Any]]:
        query = (
            f"'{self._query_escape(self.root_id)}' in parents and "
            f"name = '{self._query_escape(sha256)}' and trashed = false"
        )
        fields = (
            "files(id,name,size,mimeType,parents,appProperties,"
            "sha256Checksum,md5Checksum,trashed)"
        )
        response = self._json_request(
            f"{self.API_ROOT}/files?"
            + urllib.parse.urlencode(
                {
                    "q": query,
                    "spaces": "drive",
                    "fields": fields,
                    "pageSize": "10",
                }
            )
        )
        files = response.get("files")
        if not isinstance(files, list):
            raise VerificationError("Drive file lookup is malformed")
        return [item for item in files if isinstance(item, Mapping)]

    def _download_sha256(
        self,
        file_id: str,
        *,
        maximum_size: int,
    ) -> tuple[str, int]:
        url = (
            f"{self.API_ROOT}/files/{urllib.parse.quote(file_id)}?"
            + urllib.parse.urlencode({"alt": "media"})
        )
        request = urllib.request.Request(
            url,
            headers={
                "Authorization": f"Bearer {self._access_token()}",
                "User-Agent": f"memory-vault-sync/{VERSION}",
            },
        )
        digest = hashlib.sha256()
        total = 0
        try:
            with open_verified_url(
                request,
                timeout=60,
                policy=GOOGLE_DRIVE_MEDIA_POLICY,
            ) as response:
                while True:
                    chunk = response.read(1024 * 1024)
                    if not chunk:
                        break
                    digest.update(chunk)
                    total += len(chunk)
                    if total > maximum_size:
                        raise VerificationError(
                            "Drive verification download exceeded declared size"
                        )
        except urllib.error.HTTPError as exc:
            if exc.code in {401, 403}:
                raise AuthenticationError("Drive verification download is forbidden") from exc
            raise VerificationError("Drive verification download failed") from exc
        except (urllib.error.URLError, TimeoutError, socket.timeout) as exc:
            raise OfflineError("Drive verification download is offline") from exc
        return digest.hexdigest(), total

    def _verify_metadata(
        self,
        metadata: Mapping[str, Any],
        sha256: str,
        size: int,
        mime_type: str,
    ) -> VerifiedDriveObject:
        file_id = metadata.get("id")
        parents = metadata.get("parents")
        app_properties = metadata.get("appProperties")
        if not isinstance(file_id, str) or not re.fullmatch(
            r"[A-Za-z0-9_-]{2,256}", file_id
        ):
            raise VerificationError("Drive file ID is invalid")
        if metadata.get("trashed") is True:
            raise VerificationError("Drive object is trashed")
        self._assert_file_owner_only(file_id)
        if parents != [self.root_id]:
            raise VerificationError("Drive object is outside the private root")
        try:
            remote_size = int(metadata.get("size"))
        except (TypeError, ValueError) as exc:
            raise VerificationError("Drive object size is missing") from exc
        if remote_size != size:
            raise VerificationError("Drive object size does not match")
        if metadata.get("mimeType") != mime_type:
            raise VerificationError("Drive object media type does not match")
        if not isinstance(app_properties, Mapping):
            raise VerificationError("Drive object has no content-address metadata")
        if app_properties.get("sha256") != sha256 or str(
            app_properties.get("size")
        ) != str(size):
            raise VerificationError("Drive object content address does not match")
        remote_sha = metadata.get("sha256Checksum")
        verification = "drive-native-sha256"
        if remote_sha != sha256:
            remote_sha, downloaded_size = self._download_sha256(
                file_id,
                maximum_size=size,
            )
            if remote_sha != sha256 or downloaded_size != size:
                raise VerificationError("Drive content SHA-256 verification failed")
            verification = "remote-download-sha256-verified"
        return VerifiedDriveObject(
            store_id=self.store_id,
            driver=self.driver,
            file_id=file_id,
            parent_id=self.root_id,
            sha256=sha256,
            size=size,
            mime_type=mime_type,
            verification_level=verification,
        )

    def _verify_exact_reference(
        self,
        metadata: Mapping[str, Any],
        *,
        expected_file_id: str,
        expected_parent_id: str,
        sha256: str,
        size: int,
        mime_type: str,
    ) -> VerifiedDriveObject:
        file_id = metadata.get("id")
        if file_id != expected_file_id:
            raise VerificationError("Drive returned a different artifact")
        if not isinstance(file_id, str) or not re.fullmatch(
            r"[A-Za-z0-9_-]{2,256}", file_id
        ):
            raise VerificationError("Drive file ID is invalid")
        if not re.fullmatch(r"[A-Za-z0-9_-]{2,256}", expected_parent_id):
            raise VerificationError("Drive parent ID is invalid")
        if metadata.get("trashed") is True:
            raise VerificationError("Drive artifact is trashed")
        self._assert_file_owner_only(file_id)
        self._assert_descendant_folder(expected_parent_id)
        if metadata.get("parents") != [expected_parent_id]:
            raise VerificationError("Drive object parent does not match")
        try:
            remote_size = int(metadata.get("size"))
        except (TypeError, ValueError) as exc:
            raise VerificationError("Drive object size is missing") from exc
        if remote_size != size:
            raise VerificationError("Drive object size does not match")
        if metadata.get("mimeType") != mime_type:
            raise VerificationError("Drive object media type does not match")
        remote_sha = metadata.get("sha256Checksum")
        verification = "drive-native-sha256"
        if remote_sha != sha256:
            remote_sha, downloaded_size = self._download_sha256(
                file_id,
                maximum_size=size,
            )
            if remote_sha != sha256 or downloaded_size != size:
                raise VerificationError("Drive content SHA-256 verification failed")
            verification = "remote-download-sha256-verified"
        return VerifiedDriveObject(
            store_id=self.store_id,
            driver=self.driver,
            file_id=file_id,
            parent_id=expected_parent_id,
            sha256=sha256,
            size=size,
            mime_type=mime_type,
            verification_level=verification,
        )

    def find_verified(
        self, sha256: str, size: int, mime_type: str
    ) -> VerifiedDriveObject | None:
        key = (
            validate_sha256(sha256, "artifact sha256"),
            int(size),
            str(mime_type),
        )
        with self._lookup_cache_lock:
            if key in self._verified_lookup_cache:
                return self._verified_lookup_cache[key]
        self.assert_private()
        verified: VerifiedDriveObject | None = None
        for metadata in self._lookup(key[0]):
            try:
                verified = self._verify_metadata(
                    metadata,
                    key[0],
                    key[1],
                    key[2],
                )
                break
            except VerificationError:
                continue
        with self._lookup_cache_lock:
            self._verified_lookup_cache[key] = verified
        return verified

    def upload_and_verify(
        self,
        path: Path,
        sha256: str,
        size: int,
        mime_type: str,
    ) -> VerifiedDriveObject:
        self.assert_private()
        existing = self.find_verified(sha256, size, mime_type)
        if existing is not None:
            return existing
        metadata = {
            "name": sha256,
            "parents": [self.root_id],
            "appProperties": {
                "sha256": sha256,
                "size": str(size),
                "vault_id": VAULT_ID,
            },
        }
        _, response_headers, _ = self._request(
            f"{self.UPLOAD_ROOT}/files?uploadType=resumable&"
            + urllib.parse.urlencode(
                {
                    "fields": (
                        "id,name,size,mimeType,parents,appProperties,"
                        "sha256Checksum,md5Checksum,trashed"
                    )
                }
            ),
            method="POST",
            body=canonical_json_bytes(metadata),
            headers={
                "Content-Type": "application/json; charset=utf-8",
                "X-Upload-Content-Type": mime_type,
                "X-Upload-Content-Length": str(size),
            },
        )
        session_url = response_headers.get("Location") or response_headers.get(
            "location"
        )
        if not isinstance(session_url, str):
            raise VerificationError("Drive did not return a resumable upload URL")
        try:
            GOOGLE_DRIVE_UPLOAD_POLICY.validate(session_url)
        except (PrivacyError, VerificationError) as exc:
            raise VerificationError(
                "Drive resumable upload URL is not approved"
            ) from exc

        chunk_size = 8 * 1024 * 1024
        offset = 0
        final_metadata: Mapping[str, Any] | None = None
        with path.open("rb") as stream:
            while offset < size:
                chunk = stream.read(min(chunk_size, size - offset))
                if not chunk:
                    raise VerificationError("local file ended during Drive upload")
                end = offset + len(chunk) - 1
                request = urllib.request.Request(
                    session_url,
                    data=chunk,
                    method="PUT",
                    headers={
                        "Authorization": f"Bearer {self._access_token()}",
                        "Content-Type": mime_type,
                        "Content-Length": str(len(chunk)),
                        "Content-Range": f"bytes {offset}-{end}/{size}",
                        "User-Agent": f"memory-vault-sync/{VERSION}",
                    },
                )
                try:
                    with open_verified_url(
                        request,
                        timeout=120,
                        policy=GOOGLE_DRIVE_UPLOAD_POLICY,
                    ) as response:
                        raw = response.read(1024 * 1024)
                        if response.status in {200, 201}:
                            parsed = strict_json_loads(raw.decode("utf-8"))
                            if not isinstance(parsed, Mapping):
                                raise VerificationError(
                                    "Drive upload completion is malformed"
                                )
                            final_metadata = parsed
                        elif response.status != 308:
                            raise VerificationError(
                                f"unexpected Drive upload status {response.status}"
                            )
                except urllib.error.HTTPError as exc:
                    if exc.code == 308:
                        raw = exc.read(1024 * 1024)
                    elif exc.code in {401, 403}:
                        raise AuthenticationError("Drive upload authorization failed") from exc
                    elif exc.code in {408, 429, 500, 502, 503, 504}:
                        raise OfflineError("Drive upload was interrupted") from exc
                    else:
                        raise VerificationError(
                            f"Drive upload failed with HTTP {exc.code}"
                        ) from exc
                except (urllib.error.URLError, TimeoutError, socket.timeout) as exc:
                    raise OfflineError("Drive upload was interrupted") from exc
                offset += len(chunk)

        if final_metadata is None:
            matches = self._lookup(sha256)
            if not matches:
                raise VerificationError("Drive upload completed without a file record")
            final_metadata = matches[0]
        verified = self._verify_metadata(final_metadata, sha256, size, mime_type)
        with self._lookup_cache_lock:
            self._verified_lookup_cache[(sha256, size, mime_type)] = verified
        return verified

    def download_and_verify(
        self, artifact: Mapping[str, Any], destination: Path
    ) -> None:
        self.assert_private()
        storage_ref = _artifact_storage_ref(
            artifact,
            legacy_store_id=self.store_id,
            legacy_driver=self.driver,
        )
        if (
            storage_ref["driver"] != self.driver
            or storage_ref["store_id"] != self.store_id
        ):
            raise VerificationError(
                "artifact belongs to a different object-store adapter"
            )
        file_id = storage_ref["object_id"]
        if not isinstance(file_id, str) or not re.fullmatch(
            r"[A-Za-z0-9_-]{2,256}", file_id
        ):
            raise VerificationError("Drive artifact file ID is invalid")
        sha256 = validate_sha256(artifact.get("sha256"), "artifact.sha256")
        size = int(artifact.get("size"))
        mime_type = str(artifact.get("mime_type"))
        fields = (
            "id,name,size,mimeType,parents,appProperties,"
            "sha256Checksum,md5Checksum,trashed"
        )
        metadata = self._json_request(
            f"{self.API_ROOT}/files/{urllib.parse.quote(file_id)}?"
            + urllib.parse.urlencode({"fields": fields, "supportsAllDrives": "true"})
        )
        parent_id = storage_ref["container_id"]
        if not isinstance(parent_id, str):
            raise VerificationError("Drive artifact parent ID is invalid")
        verified = self._verify_exact_reference(
            metadata,
            expected_file_id=file_id,
            expected_parent_id=parent_id,
            sha256=sha256,
            size=size,
            mime_type=mime_type,
        )
        if (
            storage_ref["container_id"] != verified.parent_id
            or verified.file_id != file_id
        ):
            raise VerificationError("Drive artifact reference does not match metadata")
        if destination.exists():
            existing_sha, existing_size = stable_hash_file(
                destination, inspect_text=False
            )
            if existing_sha == sha256 and existing_size == size:
                return
            raise VerificationError(
                "versioned download target exists with different content"
            )
        ensure_private_dir(destination.parent)
        fd, temporary_name = tempfile.mkstemp(
            prefix=f".{sha256}.", suffix=".download", dir=str(destination.parent)
        )
        temporary = Path(temporary_name)
        digest = hashlib.sha256()
        total = 0
        try:
            url = (
                f"{self.API_ROOT}/files/{urllib.parse.quote(file_id)}?"
                + urllib.parse.urlencode({"alt": "media"})
            )
            request = urllib.request.Request(
                url,
                headers={
                    "Authorization": f"Bearer {self._access_token()}",
                    "User-Agent": f"memory-vault-sync/{VERSION}",
                },
            )
            try:
                with open_verified_url(
                    request,
                    timeout=120,
                    policy=GOOGLE_DRIVE_MEDIA_POLICY,
                ) as response, os.fdopen(
                    fd, "wb", buffering=0
                ) as output_stream:
                    fd = -1
                    while True:
                        chunk = response.read(1024 * 1024)
                        if not chunk:
                            break
                        output_stream.write(chunk)
                        digest.update(chunk)
                        total += len(chunk)
                        if total > size:
                            raise VerificationError(
                                "Drive artifact exceeded its declared size"
                            )
                    output_stream.flush()
                    os.fsync(output_stream.fileno())
            except urllib.error.HTTPError as exc:
                if exc.code in {401, 403}:
                    raise AuthenticationError(
                        "Drive artifact download is forbidden"
                    ) from exc
                if exc.code in {408, 429, 500, 502, 503, 504}:
                    raise OfflineError("Drive artifact download was interrupted") from exc
                raise VerificationError("Drive artifact download failed") from exc
            except (urllib.error.URLError, TimeoutError, socket.timeout) as exc:
                raise OfflineError("Drive artifact download is offline") from exc
            if digest.hexdigest() != sha256 or total != size:
                raise VerificationError("downloaded Drive artifact failed SHA-256")
            _publish_temp_exclusive(temporary, destination, sha256, size)
        finally:
            if fd >= 0:
                with contextlib.suppress(OSError):
                    os.close(fd)
            with contextlib.suppress(FileNotFoundError):
                temporary.unlink()


def make_drive_adapter(
    config: Mapping[str, Any],
    store_id: str | None = None,
    *,
    data_dir: Path | None = None,
) -> DriveAdapter:
    backend = _object_store_config(config, store_id).get("driver")
    if backend == "filesystem-test":
        return FilesystemDriveAdapter(config, store_id=store_id)
    if backend == "google-drive-v3":
        return GoogleDriveAdapter(config, store_id=store_id)
    if backend == RCLONE_OBJECT_STORE_DRIVER:
        return RcloneCryptAdapter(
            config,
            store_id=store_id,
            data_dir=data_dir,
        )
    raise ConfigurationError(f"unsupported object-store backend: {backend}")


def _detect_utf16_encoding(sample: bytes) -> str | None:
    if sample.startswith((b"\xff\xfe", b"\xfe\xff")):
        return "utf-16"
    probe = sample[:4096]
    if len(probe) < 8:
        return None
    even = probe[0::2]
    odd = probe[1::2]
    even_nuls = even.count(0) / max(len(even), 1)
    odd_nuls = odd.count(0) / max(len(odd), 1)
    if odd_nuls >= 0.30 and even_nuls <= 0.10:
        return "utf-16-le"
    if even_nuls >= 0.30 and odd_nuls <= 0.10:
        return "utf-16-be"
    return None


class _PrivacyStreamScanner:
    """Scan one byte stream without assuming a single text encoding."""

    def __init__(
        self,
        label: str,
        *,
        known_text: bool,
        reject_absolute_paths: bool,
    ):
        self.label = label
        self.known_text = known_text
        self.reject_absolute_paths = reject_absolute_paths
        self.first_chunk = True
        self.primary_active = True
        self.primary_encoding = "utf-8"
        self.primary_decoder: codecs.IncrementalDecoder | None = None
        self.primary_tail = ""
        self.raw_tail = b""
        self.utf16_decoders = {
            "utf-16-le": codecs.getincrementaldecoder("utf-16-le")("ignore"),
            "utf-16-be": codecs.getincrementaldecoder("utf-16-be")("ignore"),
        }
        self.utf16_tails = {"utf-16-le": "", "utf-16-be": ""}

    def _scan_decoded(self, decoded: str, *, encoding: str) -> None:
        tail = self.utf16_tails[encoding]
        probe = tail + decoded
        _scan_text_content(
            probe,
            f"{self.label} {encoding}",
            reject_absolute_paths=self.reject_absolute_paths,
        )
        self.utf16_tails[encoding] = probe[-8192:]

    def feed(self, chunk: bytes) -> None:
        raw_probe = self.raw_tail + chunk
        _scan_text_content(
            raw_probe.decode("latin-1"),
            f"{self.label} binary-safe scan",
            reject_absolute_paths=self.reject_absolute_paths,
        )
        self.raw_tail = raw_probe[-8192:]

        for encoding, decoder in self.utf16_decoders.items():
            self._scan_decoded(decoder.decode(chunk), encoding=encoding)

        if self.primary_active:
            if self.first_chunk:
                detected = _detect_utf16_encoding(chunk)
                if detected is not None:
                    self.primary_encoding = detected
                    self.known_text = True
                self.primary_decoder = codecs.getincrementaldecoder(
                    self.primary_encoding
                )("strict")
            if self.primary_encoding == "utf-8" and b"\x00" in chunk:
                if self.known_text:
                    raise PrivacyError(f"{self.label} contains NUL")
                self.primary_active = False
            else:
                try:
                    if self.primary_decoder is None:
                        self.primary_decoder = codecs.getincrementaldecoder(
                            self.primary_encoding
                        )("strict")
                    decoded = self.primary_decoder.decode(chunk)
                except UnicodeDecodeError as exc:
                    if self.known_text:
                        raise PrivacyError(
                            f"{self.label} is not valid "
                            f"{self.primary_encoding.upper()}"
                        ) from exc
                    self.primary_active = False
                else:
                    probe = self.primary_tail + decoded
                    _scan_text_content(
                        probe,
                        self.label,
                        reject_absolute_paths=self.reject_absolute_paths,
                    )
                    self.primary_tail = probe[-8192:]
        self.first_chunk = False

    def finish(self) -> None:
        for encoding, decoder in self.utf16_decoders.items():
            self._scan_decoded(decoder.decode(b"", final=True), encoding=encoding)
        if self.primary_active and self.primary_decoder is not None:
            try:
                decoded = self.primary_decoder.decode(b"", final=True)
            except UnicodeDecodeError as exc:
                if self.known_text:
                    raise PrivacyError(
                        f"{self.label} is not valid "
                        f"{self.primary_encoding.upper()}"
                    ) from exc
            else:
                if decoded:
                    _scan_text_content(
                        self.primary_tail + decoded,
                        self.label,
                        reject_absolute_paths=self.reject_absolute_paths,
                    )


def _scan_zip_container(path: Path) -> None:
    if path.suffix.lower() not in ARCHIVE_SUFFIXES:
        return
    try:
        archive = zipfile.ZipFile(path)
    except (OSError, zipfile.BadZipFile, zipfile.LargeZipFile) as exc:
        raise PrivacyError("declared archive cannot be inspected safely") from exc
    scanned_bytes = 0
    maximum_uncompressed = 2 * 1024 * 1024 * 1024
    with archive:
        members = archive.infolist()
        if len(members) > 10_000:
            raise PrivacyError("declared archive has too many members")
        declared_total = sum(max(int(member.file_size), 0) for member in members)
        if declared_total > maximum_uncompressed:
            raise PrivacyError(
                "archive content exceeds the complete privacy-scan limit"
            )
        for member in members:
            normalized = unicodedata.normalize("NFC", member.filename)
            member_path = PurePosixPath(normalized)
            if (
                not normalized
                or normalized.startswith("/")
                or "\\" in normalized
                or any(part in {"", ".", ".."} for part in member_path.parts)
            ):
                raise PrivacyError("declared archive contains an unsafe member path")
            unix_mode = (member.external_attr >> 16) & 0xFFFF
            if stat.S_ISLNK(unix_mode):
                raise PrivacyError("declared archive contains a symbolic link")
            if member.flag_bits & 0x1:
                raise PrivacyError("encrypted archive members cannot be privacy-scanned")
            if member.is_dir():
                continue
            lowered = member_path.name.lower().rstrip(" .")
            if lowered in {
                ".env",
                "credentials",
                "credentials.json",
                "cookies",
                "cookies.txt",
                "id_rsa",
                "id_ed25519",
                "secrets",
                "secrets.json",
            } or any(
                marker in lowered
                for marker in ("private-key", "refresh-token", "access-token")
            ):
                raise PrivacyError("declared archive contains a credential-like file")
            suffix = member_path.suffix.lower()
            if suffix in ARCHIVE_SUFFIXES:
                raise PrivacyError(
                    "nested archives must be reviewed and published separately"
                )
            known_text = (
                suffix in KNOWN_TEXT_SUFFIXES
                or suffix in {".rels", ".vml"}
                or lowered == "[content_types].xml"
            )
            scanner = _PrivacyStreamScanner(
                f"archive member {member_path.as_posix()}",
                known_text=known_text,
                reject_absolute_paths=False,
            )
            member_total = 0
            try:
                with archive.open(member, "r") as stream:
                    while True:
                        chunk = stream.read(1024 * 1024)
                        if not chunk:
                            break
                        member_total += len(chunk)
                        scanned_bytes += len(chunk)
                        if (
                            member_total > member.file_size
                            or scanned_bytes > maximum_uncompressed
                        ):
                            raise PrivacyError(
                                "archive expanded beyond its verified scan budget"
                            )
                        scanner.feed(chunk)
            except PrivacyError:
                raise
            except (OSError, RuntimeError, zipfile.BadZipFile, EOFError) as exc:
                raise PrivacyError("archive member cannot be inspected") from exc
            if member_total != member.file_size:
                raise PrivacyError("archive member size is inconsistent")
            scanner.finish()


def stable_hash_file(path: Path, *, inspect_text: bool = True) -> tuple[str, int]:
    assert_plain_path(path, require_file=True)
    before = path.stat()
    if not stat.S_ISREG(before.st_mode):
        raise PrivacyError("artifact is not a regular file")
    lowered = path.name.lower().rstrip(" .")
    sensitive_names = {
        ".env",
        "credentials",
        "credentials.json",
        "cookies",
        "cookies.txt",
        "id_rsa",
        "id_ed25519",
        "secrets",
        "secrets.json",
    }
    if lowered in sensitive_names or any(
        marker in lowered for marker in ("private-key", "refresh-token", "access-token")
    ):
        raise PrivacyError("artifact filename indicates credentials")

    digest = hashlib.sha256()
    total = 0
    known_text = inspect_text and (
        path.suffix.lower() in KNOWN_TEXT_SUFFIXES
        or (mimetypes.guess_type(path.name)[0] or "").startswith("text/")
    )
    scanner = (
        _PrivacyStreamScanner(
            "artifact text",
            known_text=known_text,
            reject_absolute_paths=known_text,
        )
        if inspect_text
        else None
    )
    with path.open("rb", buffering=0) as stream:
        while True:
            chunk = stream.read(1024 * 1024)
            if not chunk:
                break
            digest.update(chunk)
            total += len(chunk)
            if scanner is not None:
                scanner.feed(chunk)
    if scanner is not None:
        scanner.finish()
    if inspect_text:
        _scan_zip_container(path)
    after = path.stat()
    stable_fields = (
        "st_dev",
        "st_ino",
        "st_size",
        "st_mtime_ns",
        "st_ctime_ns",
    )
    if any(getattr(before, key, None) != getattr(after, key, None) for key in stable_fields):
        raise VerificationError("artifact changed while it was being hashed")
    if total != before.st_size:
        raise VerificationError("artifact size changed while it was being hashed")
    return digest.hexdigest(), total


def _copy_verified_file(
    source: Path, destination: Path, sha256: str, size: int
) -> None:
    validate_sha256(sha256, "artifact.sha256")
    if destination.exists():
        existing_sha, existing_size = stable_hash_file(
            destination, inspect_text=False
        )
        if existing_sha == sha256 and existing_size == size:
            return
        raise VerificationError(
            "versioned download target exists with different content"
        )
    assert_plain_path(source, require_file=True)
    ensure_private_dir(destination.parent)
    fd, temporary_name = tempfile.mkstemp(
        prefix=f".{sha256}.", suffix=".copy", dir=str(destination.parent)
    )
    temporary = Path(temporary_name)
    digest = hashlib.sha256()
    total = 0
    try:
        with source.open("rb", buffering=0) as input_stream, os.fdopen(
            fd, "wb", buffering=0
        ) as output_stream:
            while True:
                chunk = input_stream.read(1024 * 1024)
                if not chunk:
                    break
                output_stream.write(chunk)
                digest.update(chunk)
                total += len(chunk)
            output_stream.flush()
            os.fsync(output_stream.fileno())
        if digest.hexdigest() != sha256 or total != size:
            raise VerificationError("downloaded artifact failed SHA-256")
        _publish_temp_exclusive(temporary, destination, sha256, size)
    finally:
        with contextlib.suppress(FileNotFoundError):
            temporary.unlink()


def _publish_temp_exclusive(
    temporary: Path, destination: Path, sha256: str, size: int
) -> None:
    try:
        if os.name == "nt":
            os.rename(temporary, destination)
        else:
            os.link(temporary, destination)
    except FileExistsError:
        actual_sha, actual_size = stable_hash_file(
            destination, inspect_text=False
        )
        if actual_sha != sha256 or actual_size != size:
            raise VerificationError(
                "versioned destination appeared with different content"
            )
        return
    except OSError as exc:
        raise VerificationError(
            "filesystem cannot atomically publish a no-overwrite version"
        ) from exc
    _safe_chmod(destination, 0o600)
    with contextlib.suppress(OSError):
        directory_fd = os.open(destination.parent, os.O_RDONLY)
        try:
            os.fsync(directory_fd)
        finally:
            os.close(directory_fd)


def _publish_manifest_snapshot(
    identity: PortableIdentity,
    *,
    parse: bool,
) -> tuple[str | None, Any | None]:
    path = identity.workspace_root / ".vault_publish.json"
    if not path.exists():
        return None, None
    assert_plain_path(path, require_file=True)
    with path.open("rb", buffering=0) as stream:
        before = os.fstat(stream.fileno())
        if before.st_size > MAX_CODEX_JSON_BYTES:
            raise PrivacyError(".vault_publish.json exceeds the local safety limit")
        raw = stream.read(MAX_CODEX_JSON_BYTES + 1)
        after = os.fstat(stream.fileno())
    if (
        len(raw) > MAX_CODEX_JSON_BYTES
        or len(raw) != before.st_size
        or before.st_size != after.st_size
        or before.st_mtime_ns != after.st_mtime_ns
        or getattr(before, "st_ino", 0) != getattr(after, "st_ino", 0)
    ):
        raise VerificationError(".vault_publish.json changed during inspection")
    fingerprint = sha256_bytes(raw)
    if not parse:
        return fingerprint, None
    if raw.startswith(b"\xef\xbb\xbf"):
        raise PrivacyError("UTF-8 BOM is forbidden: .vault_publish.json")
    try:
        value = strict_json_loads(raw.decode("utf-8"))
    except UnicodeDecodeError as exc:
        raise PrivacyError(".vault_publish.json is not valid UTF-8") from exc
    except (ValueError, json.JSONDecodeError) as exc:
        raise ConfigurationError(
            f"invalid JSON in .vault_publish.json: {exc}"
        ) from exc
    return fingerprint, value


def _artifact_declarations_from_value(
    identity: PortableIdentity,
    value: Any,
) -> list[str]:
    if not isinstance(value, Mapping):
        raise PrivacyError(".vault_publish.json has an unsupported schema")
    if value.get("schema_version") == "vault-publish/v1":
        if identity.path.name == ".vault_identities.json":
            raise PrivacyError(
                "shared workspaces require a task-scoped vault-publish/v2 manifest"
            )
        if set(value) != {"schema_version", "artifacts"}:
            raise PrivacyError(".vault_publish.json contains unsupported fields")
        artifacts = value.get("artifacts")
    elif value.get("schema_version") == "vault-publish/v2":
        if set(value) != {"schema_version", "tasks"}:
            raise PrivacyError(".vault_publish.json contains unsupported fields")
        tasks = value.get("tasks")
        if not isinstance(tasks, list):
            raise PrivacyError(".vault_publish.json tasks must be a list")
        matches: list[Mapping[str, Any]] = []
        seen: set[str] = set()
        for task in tasks:
            if not isinstance(task, Mapping) or set(task) != {
                "semantic_task_id",
                "artifacts",
            }:
                raise PrivacyError(".vault_publish.json contains an invalid task")
            declared_task = validate_identifier(
                task.get("semantic_task_id"), "semantic_task_id"
            )
            if declared_task in seen:
                raise PrivacyError(".vault_publish.json contains a duplicate task")
            seen.add(declared_task)
            if declared_task == identity.task_id:
                matches.append(task)
        if len(matches) != 1:
            return []
        artifacts = matches[0].get("artifacts")
    else:
        raise PrivacyError(".vault_publish.json has an unsupported schema")
    if not isinstance(artifacts, list) or not all(
        isinstance(item, str) for item in artifacts
    ):
        raise PrivacyError(".vault_publish.json artifacts must be a string list")
    result: list[str] = []
    for item in artifacts:
        safe = validate_repo_path(item, "declared artifact path")
        if safe in {
            ".vault_identity.yaml",
            ".vault_identities.json",
            ".vault_adoptions.json",
            ".vault_publish.json",
        }:
            raise PrivacyError("control files cannot be published as artifacts")
        if safe not in result:
            result.append(safe)
    return result


def _artifact_declarations(identity: PortableIdentity) -> list[str]:
    _fingerprint, value = _publish_manifest_snapshot(identity, parse=True)
    if value is None:
        return []
    return _artifact_declarations_from_value(identity, value)


def _publish_manifest_fingerprint(identity: PortableIdentity) -> str | None:
    """Fingerprint the local publish declaration without granting it authority."""

    fingerprint, _value = _publish_manifest_snapshot(identity, parse=False)
    return fingerprint


def artifact_snapshot(
    identity: PortableIdentity,
    remote_manifest: Mapping[str, Any] | None = None,
) -> dict[str, list[Any]]:
    remote_hashes: set[str] = set()
    if isinstance(remote_manifest, Mapping):
        artifacts = remote_manifest.get("artifacts")
        if not isinstance(artifacts, list):
            raise VerificationError("remote manifest artifacts are invalid")
        for artifact in artifacts:
            if not isinstance(artifact, Mapping):
                raise VerificationError("remote manifest artifact is invalid")
            remote_hashes.add(
                validate_sha256(artifact.get("sha256"), "remote artifact.sha256")
            )
    snapshot: dict[str, list[Any]] = {}
    root = identity.workspace_root.resolve()
    for relative in _artifact_declarations(identity):
        path = root / PurePosixPath(relative)
        if not _path_is_within(path.resolve(strict=False), root):
            raise PrivacyError("declared artifact escapes the workspace")
        if not path.exists():
            snapshot[relative] = [-1, -1, -1, -1, None]
            continue
        assert_plain_path(path, require_file=True)
        sha256, size = stable_hash_file(path)
        metadata = path.stat()
        observed = [
            int(metadata.st_size),
            int(metadata.st_mtime_ns),
            int(getattr(metadata, "st_ino", 0)),
            int(getattr(metadata, "st_ctime_ns", 0)),
            sha256,
        ]
        if size != observed[0]:
            raise VerificationError("artifact changed during startup inventory")
        snapshot[relative] = (
            observed if sha256 in remote_hashes else [-1, -1, -1, -1, None]
        )
    return snapshot


def _requires_content_hash_recheck() -> bool:
    # Windows st_ctime_ns is commonly creation time, not a content-change clock.
    return os.name == "nt"


def changed_artifacts(
    identity: PortableIdentity,
    previous: Mapping[str, Any],
    config: Mapping[str, Any],
    *,
    declarations_override: Sequence[str] | None = None,
) -> list[dict[str, Any]]:
    if config["sync"].get("artifact_mode") == "none":
        return []
    declarations = (
        list(declarations_override)
        if declarations_override is not None
        else _artifact_declarations(identity)
    )
    limit = int(config["sync"].get("max_files_per_turn", 128))
    byte_limit = int(
        config["sync"].get("max_total_bytes_per_turn", 2 * 1024 * 1024 * 1024)
    )
    if len(declarations) > limit:
        raise PrivacyError("too many declared artifacts for one turn")
    root = identity.workspace_root.resolve()
    results: list[dict[str, Any]] = []
    total = 0
    for relative in declarations:
        path = root / PurePosixPath(relative)
        try:
            resolved = path.resolve(strict=True)
        except OSError as exc:
            raise VerificationError(f"declared artifact is missing: {relative}") from exc
        if not _path_is_within(resolved, root):
            raise PrivacyError("declared artifact escapes the workspace")
        assert_plain_path(path, require_file=True)
        metadata = path.stat()
        observed = [
            int(metadata.st_size),
            int(metadata.st_mtime_ns),
            int(getattr(metadata, "st_ino", 0)),
            int(getattr(metadata, "st_ctime_ns", 0)),
        ]
        prior = previous.get(relative)
        same_metadata = (
            isinstance(prior, list)
            and len(prior) >= 4
            and prior[:4] == observed
        )
        sha256: str | None = None
        size: int | None = None
        if same_metadata:
            if not _requires_content_hash_recheck():
                continue
            sha256, size = stable_hash_file(path)
            if (
                len(prior) >= 5
                and isinstance(prior[4], str)
                and prior[4] == sha256
                and size == observed[0]
            ):
                continue
        if sha256 is None or size is None:
            sha256, size = stable_hash_file(path)
        if size < 1:
            raise PrivacyError("zero-byte artifacts are not publishable")
        total += size
        if total > byte_limit:
            raise PrivacyError("changed artifacts exceed the per-turn byte limit")
        suffix = path.suffix.lower()
        safe_suffix = suffix if re.fullmatch(r"\.[a-z0-9]{1,12}", suffix) else ""
        mime_type = mimetypes.guess_type(path.name)[0] or "application/octet-stream"
        if not re.fullmatch(r"[a-z0-9.+-]+/[a-z0-9.+-]+", mime_type):
            mime_type = "application/octet-stream"
        display_name = unicodedata.normalize("NFC", path.name)
        if not display_name or len(display_name) > 255 or any(
            character in display_name for character in "/\\\r\n"
        ):
            raise PrivacyError("artifact filename is not portable")
        _scan_text_content(display_name, "artifact filename")
        results.append(
            {
                "local_path": str(path),
                "relative_path": relative,
                "display_name": display_name,
                "logical_path": f"workspace/{sha256}{safe_suffix}",
                "sha256": sha256,
                "size": size,
                "mime_type": mime_type,
                "stat": [*observed, sha256],
                "drive": None,
            }
        )
    return results


def _device_state(data_dir: Path) -> dict[str, Any]:
    path = data_dir / "state" / "device.json"
    if path.exists():
        value = load_json(path)
        if (
            isinstance(value, dict)
            and value.get("schema_version") == DEVICE_SCHEMA
            and isinstance(value.get("device_secret"), str)
            and isinstance(value.get("installation_id"), str)
        ):
            return value
        raise ConfigurationError("local device state is invalid")
    value = {
        "schema_version": DEVICE_SCHEMA,
        "installation_id": f"install-{uuid.uuid4().hex}",
        "device_secret": base64.urlsafe_b64encode(secrets.token_bytes(32))
        .decode("ascii")
        .rstrip("="),
        "created_at": utc_now(),
    }
    atomic_write_json(path, value)
    return value


def _opaque_key(secret: str, *parts: str, length: int = 32) -> str:
    digest = hashlib.sha256()
    digest.update(secret.encode("ascii"))
    for part in parts:
        digest.update(b"\0")
        digest.update(part.encode("utf-8"))
    return digest.hexdigest()[:length]


def _session_key(device: Mapping[str, Any], session_id: str) -> str:
    return _opaque_key(str(device["device_secret"]), "session", session_id, length=32)


def _turn_key(device: Mapping[str, Any], session_id: str, turn_id: str) -> str:
    return _opaque_key(
        str(device["device_secret"]), "turn", session_id, turn_id, length=32
    )


def _transaction_id(device: Mapping[str, Any], session_id: str, turn_id: str) -> str:
    return "tx-" + _opaque_key(
        str(device["device_secret"]), "transaction", session_id, turn_id, length=32
    )


def _workspace_instance(
    data_dir: Path, device: Mapping[str, Any], workspace_root: Path
) -> str:
    path = data_dir / "state" / "workspaces.json"
    value: dict[str, Any]
    if path.exists():
        loaded = load_json(path)
        if not isinstance(loaded, dict):
            raise ConfigurationError("local workspace state is invalid")
        value = loaded
    else:
        value = {"schema_version": "memory-vault-sync-workspaces/v1", "items": {}}
    if value.get("schema_version") != "memory-vault-sync-workspaces/v1":
        raise ConfigurationError("local workspace state has an unsupported schema")
    items = value.get("items")
    if not isinstance(items, dict):
        raise ConfigurationError("local workspace state has invalid items")
    local_key = _opaque_key(
        str(device["device_secret"]),
        "workspace",
        str(workspace_root.resolve()),
        length=40,
    )
    item = items.get(local_key)
    if not isinstance(item, dict):
        item = {
            "workspace_instance_id": f"wsi-{uuid.uuid4().hex}",
            "local_path": str(workspace_root.resolve()),
            "created_at": utc_now(),
        }
        items[local_key] = item
        atomic_write_json(path, value)
    instance = item.get("workspace_instance_id")
    return validate_identifier(instance, "workspace_instance_id")


def _session_path(data_dir: Path, session_key: str) -> Path:
    if not re.fullmatch(r"[0-9a-f]{32}", session_key):
        raise PrivacyError("local session key is invalid")
    return data_dir / "state" / "sessions" / f"{session_key}.json"


def _reconciliation_ticket_path(
    data_dir: Path,
    token_sha256: str,
) -> Path:
    validate_sha256(token_sha256, "reconciliation ticket hash")
    return (
        data_dir
        / "state"
        / "reconciliation-tickets"
        / f"{token_sha256}.json"
    )


def _invalidate_session_reconciliation_ticket(
    data_dir: Path,
    session: MutableMapping[str, Any],
) -> None:
    token_sha256 = session.pop(
        "active_reconciliation_token_sha256",
        None,
    )
    if not isinstance(token_sha256, str):
        return
    path = _reconciliation_ticket_path(data_dir, token_sha256)
    if not path.exists():
        return
    value = load_json(path)
    if (
        isinstance(value, dict)
        and value.get("schema_version")
        == "memory-vault-reconciliation-ticket/v1"
        and value.get("state") == "issued"
    ):
        value["state"] = "invalidated"
        value["invalidated_at"] = utc_now()
        atomic_write_json(path, value)


def _prompt_path(data_dir: Path, session_key: str, turn_key: str) -> Path:
    if not re.fullmatch(r"[0-9a-f]{32}", session_key) or not re.fullmatch(
        r"[0-9a-f]{32}", turn_key
    ):
        raise PrivacyError("local prompt key is invalid")
    return data_dir / "state" / "prompts" / session_key / f"{turn_key}.json"


def _memory_network_index_path(data_dir: Path) -> Path:
    return data_dir / "index" / "memory-network-v1.sqlite3"


def _memory_network_session_path(data_dir: Path, session_key: str) -> Path:
    if not re.fullmatch(r"[0-9a-f]{32}", session_key):
        raise PrivacyError("memory network session key is invalid")
    return data_dir / "state" / "memory-network" / "sessions" / f"{session_key}.json"


def _memory_network_prompt_path(
    data_dir: Path,
    session_key: str,
    turn_key: str,
) -> Path:
    if not re.fullmatch(r"[0-9a-f]{32}", session_key) or not re.fullmatch(
        r"[0-9a-f]{32}", turn_key
    ):
        raise PrivacyError("memory network prompt key is invalid")
    return (
        data_dir
        / "state"
        / "memory-network"
        / "prompts"
        / session_key
        / f"{turn_key}.json"
    )


def _memory_network_outbox_path(
    data_dir: Path,
    state: str,
    transaction_id: str,
) -> Path:
    transaction = validate_identifier(transaction_id, "transaction_id")
    if state not in {"pending", "done", "quarantine", "recovery-v1"}:
        raise PrivacyError("memory network outbox state is invalid")
    return (
        data_dir
        / "memory-network"
        / "outbox"
        / state
        / f"{transaction}.json"
    )


def _memory_network_device_trust_path(data_dir: Path) -> Path:
    """Return the private, taskless device-trust state location."""

    return data_dir / "memory-network" / "device-trust.json"


def _find_memory_network_outbox_state(
    data_dir: Path,
    transaction_id: str,
) -> str | None:
    with _MemoryNetworkOutbox(data_dir) as outbox:
        return outbox.find_state(transaction_id)


class _MemoryNetworkOutbox:
    """Operate on private outbox files without following directory links.

    POSIX keeps every directory descriptor open and performs enumeration,
    reads, writes, replacement and unlink relative to those descriptors.
    Windows lacks equivalent Python ``dir_fd`` coverage; there every directory
    component is rejected if it is a reparse point and its identity is checked
    immediately before and after each path-based operation.
    """

    _STATES = ("pending", "done", "quarantine", "recovery-v1")
    _RAW_NAME_RE = re.compile(r"tx-[0-9a-f]{32}\.json")
    _RECEIPT_NAME_RE = re.compile(r"tx-[0-9a-f]{32}\.receipt\.json")

    def __init__(self, data_dir: Path):
        self.data_dir = Path(os.path.abspath(os.fspath(data_dir)))
        self.root = self.data_dir / "memory-network" / "outbox"
        self._posix = os.name != "nt" and all(
            function in os.supports_dir_fd
            for function in (
                os.open,
                os.mkdir,
                os.stat,
                os.link,
                os.rename,
                os.unlink,
            )
        )
        self._directories: list[tuple[Path, int, int | None, str | None]] = []
        self._state_fds: dict[str, int] = {}

    @staticmethod
    def _directory_flags() -> int:
        return (
            os.O_RDONLY
            | getattr(os, "O_DIRECTORY", 0)
            | getattr(os, "O_NOFOLLOW", 0)
            | getattr(os, "O_NOINHERIT", 0)
        )

    @staticmethod
    def _file_flags() -> int:
        return (
            os.O_RDONLY
            | getattr(os, "O_BINARY", 0)
            | getattr(os, "O_NOFOLLOW", 0)
            | getattr(os, "O_NOINHERIT", 0)
        )

    @classmethod
    def _validate_name(cls, name: str, *, receipt: bool = False) -> str:
        pattern = cls._RECEIPT_NAME_RE if receipt else cls._RAW_NAME_RE
        if not isinstance(name, str) or pattern.fullmatch(name) is None:
            raise PrivacyError("memory network outbox filename is invalid")
        return name

    @staticmethod
    def _same_directory(
        named: os.stat_result,
        opened: os.stat_result,
    ) -> bool:
        return stat.S_ISDIR(named.st_mode) and stat.S_ISDIR(opened.st_mode) and (
            _stable_file_observations_match(
                named,
                opened,
                cross_interface=True,
            )
        )

    def _open_posix_directory(
        self,
        path: Path,
        *,
        parent_fd: int | None,
        name: str | None,
        create: bool,
    ) -> int:
        if parent_fd is None:
            if create:
                path.mkdir(parents=True, exist_ok=True)
            named = path.lstat()
            if stat.S_ISLNK(named.st_mode) or _is_reparse_point(path):
                raise PrivacyError("private outbox root is linked")
            descriptor = os.open(path, self._directory_flags())
            named_after = path.lstat()
        else:
            assert name is not None
            if create:
                try:
                    os.mkdir(name, mode=0o700, dir_fd=parent_fd)
                except FileExistsError:
                    pass
            try:
                named = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
                descriptor = os.open(
                    name,
                    self._directory_flags(),
                    dir_fd=parent_fd,
                )
                named_after = os.stat(
                    name,
                    dir_fd=parent_fd,
                    follow_symlinks=False,
                )
            except OSError as exc:
                raise PrivacyError(
                    "private outbox directory could not be opened safely"
                ) from exc
        opened = os.fstat(descriptor)
        if (
            not self._same_directory(named, opened)
            or not self._same_directory(opened, named_after)
        ):
            os.close(descriptor)
            raise PrivacyError("private outbox directory changed while opened")
        with contextlib.suppress(OSError, NotImplementedError):
            os.fchmod(descriptor, 0o700)
        self._directories.append((path, descriptor, parent_fd, name))
        return descriptor

    def _open_posix(self) -> None:
        root_fd = self._open_posix_directory(
            self.data_dir,
            parent_fd=None,
            name=None,
            create=True,
        )
        memory_path = self.data_dir / "memory-network"
        memory_fd = self._open_posix_directory(
            memory_path,
            parent_fd=root_fd,
            name="memory-network",
            create=True,
        )
        outbox_fd = self._open_posix_directory(
            self.root,
            parent_fd=memory_fd,
            name="outbox",
            create=True,
        )
        for state in self._STATES:
            self._state_fds[state] = self._open_posix_directory(
                self.root / state,
                parent_fd=outbox_fd,
                name=state,
                create=True,
            )
        self._verify_directories()

    def _open_windows(self) -> None:
        # Python on Windows does not provide complete dir_fd support for this
        # operation set. Refuse every reparse component, then repeat the same
        # identity proof after each individual path-based file operation.
        current = self.data_dir
        ensure_private_dir(current)
        assert_plain_directory_chain(self.data_dir, current)
        for component in ("memory-network", "outbox"):
            current = current / component
            if not current.exists():
                current.mkdir(mode=0o700)
            assert_plain_directory_chain(self.data_dir, current)
        for state in self._STATES:
            directory = self.root / state
            if not directory.exists():
                directory.mkdir(mode=0o700)
            assert_plain_directory_chain(self.data_dir, directory)

    def __enter__(self) -> "_MemoryNetworkOutbox":
        try:
            if self._posix:
                self._open_posix()
            else:
                self._open_windows()
        except Exception:
            self.__exit__(None, None, None)
            raise
        return self

    def __exit__(self, exc_type: Any, exc: Any, traceback: Any) -> None:
        verification_error: Exception | None = None
        if self._directories:
            try:
                self._verify_directories()
            except Exception as observed:
                verification_error = observed
        for _path, descriptor, _parent, _name in reversed(self._directories):
            with contextlib.suppress(OSError):
                os.close(descriptor)
        self._directories.clear()
        self._state_fds.clear()
        if verification_error is not None and exc_type is None:
            raise verification_error

    def _verify_directories(self) -> None:
        if not self._posix:
            for state in self._STATES:
                assert_plain_directory_chain(
                    self.data_dir,
                    self.root / state,
                )
            return
        for path, descriptor, parent_fd, name in self._directories:
            opened = os.fstat(descriptor)
            if parent_fd is None:
                named = path.lstat()
            else:
                assert name is not None
                named = os.stat(
                    name,
                    dir_fd=parent_fd,
                    follow_symlinks=False,
                )
            if not self._same_directory(named, opened):
                raise PrivacyError("private outbox directory identity changed")

    def path(self, state: str, name: str) -> Path:
        if state not in self._STATES:
            raise PrivacyError("memory network outbox state is invalid")
        self._validate_name(name)
        return self.root / state / name

    def _state_path(self, state: str) -> Path:
        if state not in self._STATES:
            raise PrivacyError("memory network outbox state is invalid")
        return self.root / state

    def list_raw_names(self, state: str) -> list[str]:
        directory = self._state_path(state)
        self._verify_directories()
        names = (
            os.listdir(self._state_fds[state])
            if self._posix
            else os.listdir(directory)
        )
        result: list[str] = []
        for name in names:
            if not name.endswith(".json") or name.endswith(".receipt.json"):
                continue
            self._validate_name(name)
            result.append(name)
        self._verify_directories()
        return sorted(result)

    def _named_stat(self, state: str, name: str) -> os.stat_result:
        if self._posix:
            return os.stat(
                name,
                dir_fd=self._state_fds[state],
                follow_symlinks=False,
            )
        return (self._state_path(state) / name).lstat()

    def exists(self, state: str, name: str, *, receipt: bool = False) -> bool:
        self._validate_name(name, receipt=receipt)
        self._verify_directories()
        try:
            observed = self._named_stat(state, name)
        except FileNotFoundError:
            return False
        if not stat.S_ISREG(observed.st_mode) or int(
            getattr(observed, "st_nlink", 1)
        ) != 1:
            raise PrivacyError("memory network outbox entry is not a plain file")
        return True

    def _read_posix(
        self,
        state: str,
        name: str,
        maximum_bytes: int,
    ) -> bytes:
        directory_fd = self._state_fds[state]
        before = self._named_stat(state, name)
        if (
            not stat.S_ISREG(before.st_mode)
            or int(getattr(before, "st_nlink", 1)) != 1
            or before.st_size < 1
            or before.st_size > maximum_bytes
        ):
            raise PrivacyError("memory network outbox entry is not a bounded file")
        try:
            descriptor = os.open(name, self._file_flags(), dir_fd=directory_fd)
        except OSError as exc:
            raise PrivacyError("memory network outbox entry opened unsafely") from exc
        try:
            opened = os.fstat(descriptor)
            if not _stable_file_observations_match(before, opened):
                raise PrivacyError("memory network outbox entry changed before open")
            chunks: list[bytes] = []
            remaining = maximum_bytes + 1
            while remaining:
                chunk = os.read(descriptor, min(1024 * 1024, remaining))
                if not chunk:
                    break
                chunks.append(chunk)
                remaining -= len(chunk)
            raw = b"".join(chunks)
            opened_after = os.fstat(descriptor)
        finally:
            os.close(descriptor)
        named_after = self._named_stat(state, name)
        if (
            len(raw) > maximum_bytes
            or len(raw) != before.st_size
            or not _stable_file_observations_match(opened, opened_after)
            or not _stable_file_observations_match(before, named_after)
        ):
            raise BusyError("memory network outbox entry changed during read")
        return raw

    def read(
        self,
        state: str,
        name: str,
        *,
        maximum_bytes: int = MAX_CODEX_JSON_BYTES,
        receipt: bool = False,
    ) -> bytes:
        self._validate_name(name, receipt=receipt)
        self._verify_directories()
        if self._posix:
            raw = self._read_posix(state, name, maximum_bytes)
        else:
            raw = _read_bounded_plain_runtime_file(
                self._state_path(state) / name,
                maximum_bytes=maximum_bytes,
                label="memory network outbox entry",
            )
        self._verify_directories()
        return raw

    def _write_temporary_posix(self, state: str, raw: bytes) -> str:
        directory_fd = self._state_fds[state]
        for _attempt in range(32):
            temporary = f".memory-outbox-{secrets.token_hex(16)}.tmp"
            flags = (
                os.O_WRONLY
                | os.O_CREAT
                | os.O_EXCL
                | getattr(os, "O_BINARY", 0)
                | getattr(os, "O_NOFOLLOW", 0)
                | getattr(os, "O_NOINHERIT", 0)
            )
            try:
                descriptor = os.open(
                    temporary,
                    flags,
                    0o600,
                    dir_fd=directory_fd,
                )
                break
            except FileExistsError:
                continue
        else:
            raise BusyError("memory network outbox temporary name is busy")
        try:
            view = memoryview(raw)
            while view:
                written = os.write(descriptor, view)
                if written <= 0:
                    raise OSError("short outbox write")
                view = view[written:]
            os.fsync(descriptor)
            with contextlib.suppress(OSError, NotImplementedError):
                os.fchmod(descriptor, 0o600)
        finally:
            os.close(descriptor)
        return temporary

    def write_new(
        self,
        state: str,
        name: str,
        raw: bytes,
        *,
        receipt: bool = False,
        allow_existing_equal: bool = False,
    ) -> None:
        self._validate_name(name, receipt=receipt)
        if not raw or len(raw) > MAX_CODEX_JSON_BYTES:
            raise PrivacyError("memory network outbox write size is invalid")
        self._verify_directories()
        if self._posix:
            temporary = self._write_temporary_posix(state, raw)
            directory_fd = self._state_fds[state]
            try:
                os.link(
                    temporary,
                    name,
                    src_dir_fd=directory_fd,
                    dst_dir_fd=directory_fd,
                    follow_symlinks=False,
                )
                os.fsync(directory_fd)
            except FileExistsError:
                if not allow_existing_equal or self.read(
                    state,
                    name,
                    receipt=receipt,
                ) != raw:
                    raise ConflictError("memory network outbox entry already exists")
            finally:
                with contextlib.suppress(FileNotFoundError):
                    os.unlink(temporary, dir_fd=directory_fd)
        else:
            destination = self._state_path(state) / name
            if destination.exists():
                if not allow_existing_equal or self.read(
                    state,
                    name,
                    receipt=receipt,
                ) != raw:
                    raise ConflictError("memory network outbox entry already exists")
                return
            fd, temporary_name = tempfile.mkstemp(
                prefix=f".{name}.", suffix=".tmp", dir=str(destination.parent)
            )
            temporary = Path(temporary_name)
            try:
                with os.fdopen(fd, "wb") as stream:
                    stream.write(raw)
                    stream.flush()
                    os.fsync(stream.fileno())
                _safe_chmod(temporary, 0o600)
                os.rename(temporary, destination)
            finally:
                with contextlib.suppress(FileNotFoundError):
                    temporary.unlink()
        self._verify_directories()

    def replace(
        self,
        state: str,
        name: str,
        *,
        expected_raw: bytes,
        replacement_raw: bytes,
    ) -> None:
        self._validate_name(name)
        if self.read(state, name) != expected_raw:
            raise BusyError("memory network outbox entry changed before update")
        self._verify_directories()
        if self._posix:
            temporary = self._write_temporary_posix(state, replacement_raw)
            directory_fd = self._state_fds[state]
            try:
                if self.read(state, name) != expected_raw:
                    raise BusyError(
                        "memory network outbox entry changed before replacement"
                    )
                os.rename(
                    temporary,
                    name,
                    src_dir_fd=directory_fd,
                    dst_dir_fd=directory_fd,
                )
                os.fsync(directory_fd)
            finally:
                with contextlib.suppress(FileNotFoundError):
                    os.unlink(temporary, dir_fd=directory_fd)
        else:
            destination = self._state_path(state) / name
            fd, temporary_name = tempfile.mkstemp(
                prefix=f".{name}.", suffix=".tmp", dir=str(destination.parent)
            )
            temporary = Path(temporary_name)
            try:
                with os.fdopen(fd, "wb") as stream:
                    stream.write(replacement_raw)
                    stream.flush()
                    os.fsync(stream.fileno())
                if self.read(state, name) != expected_raw:
                    raise BusyError(
                        "memory network outbox entry changed before replacement"
                    )
                os.replace(temporary, destination)
            finally:
                with contextlib.suppress(FileNotFoundError):
                    temporary.unlink()
        self._verify_directories()

    def unlink(self, state: str, name: str, *, expected_raw: bytes) -> None:
        self._validate_name(name)
        if self.read(state, name) != expected_raw:
            raise BusyError("memory network outbox entry changed before removal")
        if self._posix:
            os.unlink(name, dir_fd=self._state_fds[state])
            os.fsync(self._state_fds[state])
        else:
            (self._state_path(state) / name).unlink()
        self._verify_directories()

    def _move_posix_noreplace(
        self,
        source_state: str,
        destination_state: str,
        name: str,
        *,
        expected_raw: bytes,
    ) -> None:
        source_fd = self._state_fds[source_state]
        destination_fd = self._state_fds[destination_state]
        if self.read(source_state, name) != expected_raw:
            raise BusyError("legacy outbox changed before recovery move")
        try:
            os.link(
                name,
                name,
                src_dir_fd=source_fd,
                dst_dir_fd=destination_fd,
                follow_symlinks=False,
            )
        except FileExistsError:
            if self.read(destination_state, name) != expected_raw:
                raise ConflictError("legacy recovery entry has different bytes")
        else:
            # The link is a no-overwrite publication of the exact inode. Drop
            # the pending name immediately; after that the recovered file is
            # again a single-link regular file and can pass normal reads.
            current = os.stat(name, dir_fd=source_fd, follow_symlinks=False)
            recovered = os.stat(
                name,
                dir_fd=destination_fd,
                follow_symlinks=False,
            )
            if (
                not stat.S_ISREG(current.st_mode)
                or int(getattr(current, "st_nlink", 0)) != 2
                or not _stable_file_observations_match(current, recovered)
            ):
                with contextlib.suppress(FileNotFoundError):
                    os.unlink(name, dir_fd=destination_fd)
                raise PrivacyError("legacy recovery link could not be verified")
        os.unlink(name, dir_fd=source_fd)
        os.fsync(source_fd)
        os.fsync(destination_fd)

    def move_to_recovery(self, name: str, *, expected_raw: bytes) -> None:
        self._validate_name(name)
        if self.read("pending", name) != expected_raw:
            raise BusyError("legacy outbox changed before recovery")
        if self.exists("recovery-v1", name):
            if self.read("recovery-v1", name) != expected_raw:
                raise ConflictError("legacy recovery entry has different bytes")
            self.unlink("pending", name, expected_raw=expected_raw)
            return
        if self._posix:
            self._move_posix_noreplace(
                "pending",
                "recovery-v1",
                name,
                expected_raw=expected_raw,
            )
        else:
            source = self._state_path("pending") / name
            destination = self._state_path("recovery-v1") / name
            if self.read("pending", name) != expected_raw:
                raise BusyError("legacy outbox changed before recovery move")
            os.rename(source, destination)
        if self.read("recovery-v1", name) != expected_raw:
            raise VerificationError("legacy outbox recovery bytes changed")
        self._verify_directories()

    def find_state(self, transaction_id: str) -> str | None:
        transaction = validate_identifier(transaction_id, "transaction_id")
        name = f"{transaction}.json"
        self._validate_name(name)
        for state in ("done", "quarantine", "recovery-v1", "pending"):
            if self.exists(state, name):
                return state
        return None


def _workspace_identity_fingerprint(workspace: Path) -> str:
    records: list[dict[str, Any]] = []
    for name in (".vault_identity.yaml", ".vault_identities.json"):
        path = workspace / name
        if not path.exists():
            continue
        assert_plain_path(path, require_file=True)
        size = path.stat().st_size
        if size > MAX_CODEX_JSON_BYTES:
            raise IdentityError("portable workspace identity exceeds the safety limit")
        sha256, verified_size = stable_hash_file(path, inspect_text=False)
        if verified_size != size:
            raise VerificationError("portable workspace identity changed during inspection")
        records.append({"name": name, "sha256": sha256, "size": size})
    return sha256_bytes(canonical_json_bytes(records))


def _adoption_guard_path(
    data_dir: Path,
    device: Mapping[str, Any],
    workspace: Path,
    task_id: str,
) -> Path:
    task_id = validate_identifier(task_id, "task_id")
    key = _opaque_key(
        str(device["device_secret"]),
        "existing-adoption",
        str(workspace.resolve()),
        task_id,
        length=40,
    )
    return data_dir / "state" / "existing-adoptions" / f"{key}.json"


def _validate_adoption_guard(
    value: Any,
    *,
    workspace: Path,
    task_id: str,
) -> dict[str, Any]:
    required = {
        "schema_version",
        "task_id",
        "binding_id",
        "workspace_lineage_id",
        "workspace_root",
        "expected_source_key_sha256",
        "cloud_snapshot_id",
        "cloud_current_blob_sha",
        "preexisting_publish_manifest_sha256",
        "approved_publish_manifest_sha256",
        "artifact_publication_blocked",
        "state",
        "created_at",
        "updated_at",
    }
    if (
        not isinstance(value, dict)
        or set(value) != required
        or value.get("schema_version") != ADOPTION_GUARD_SCHEMA
    ):
        raise ConfigurationError("local existing-task adoption state is invalid")
    if value.get("task_id") != validate_identifier(task_id, "task_id"):
        raise IdentityError("local existing-task adoption targets another task")
    if value.get("workspace_root") != str(workspace.resolve()):
        raise IdentityError("local existing-task adoption targets another workspace")
    validate_identifier(value.get("binding_id"), "adoption.binding_id")
    validate_identifier(
        value.get("workspace_lineage_id"),
        "adoption.workspace_lineage_id",
    )
    validate_identifier(
        value.get("cloud_snapshot_id"),
        "adoption.cloud_snapshot_id",
    )
    validate_git_sha(
        value.get("cloud_current_blob_sha"),
        "adoption.cloud_current_blob_sha",
    )
    validate_sha256(
        value.get("expected_source_key_sha256"),
        "adoption.expected_source_key_sha256",
    )
    for field in (
        "preexisting_publish_manifest_sha256",
        "approved_publish_manifest_sha256",
    ):
        if value.get(field) is not None:
            validate_sha256(value[field], f"adoption.{field}")
    if not isinstance(value.get("artifact_publication_blocked"), bool):
        raise ConfigurationError("local existing-task adoption gate is invalid")
    if value.get("state") not in {
        "binding_committed",
        "cloud_current_loaded",
        "artifacts_reconciled",
    }:
        raise ConfigurationError("local existing-task adoption phase is invalid")
    return value


def _load_adoption_guard(
    data_dir: Path,
    device: Mapping[str, Any],
    workspace: Path,
    task_id: str,
) -> tuple[Path, dict[str, Any]] | None:
    path = _adoption_guard_path(data_dir, device, workspace, task_id)
    if not path.exists():
        return None
    return path, _validate_adoption_guard(
        load_json(path),
        workspace=workspace,
        task_id=task_id,
    )


def _portable_adoptions_path(workspace: Path) -> Path:
    return workspace / ".vault_adoptions.json"


def _load_portable_adoptions(workspace: Path) -> dict[str, dict[str, Any]]:
    path = _portable_adoptions_path(workspace)
    if not path.exists():
        return {}
    assert_plain_path(path, require_file=True)
    value = load_json(path)
    if (
        not isinstance(value, Mapping)
        or set(value) != {"schema_version", "vault_id", "adoptions"}
        or value.get("schema_version") != PORTABLE_ADOPTION_SCHEMA
        or value.get("vault_id") != VAULT_ID
        or not isinstance(value.get("adoptions"), list)
    ):
        raise IdentityError("portable existing-task adoption state is invalid")
    result: dict[str, dict[str, Any]] = {}
    required = {
        "task_id",
        "binding_id",
        "workspace_lineage_id",
        "cloud_snapshot_id",
        "cloud_current_blob_sha",
        "preexisting_publish_manifest_sha256",
        "approved_publish_manifest_sha256",
        "artifact_publication_blocked",
        "state",
        "created_at",
        "updated_at",
    }
    for raw in value["adoptions"]:
        if not isinstance(raw, dict) or set(raw) != required:
            raise IdentityError("portable existing-task adoption entry is invalid")
        task_id = validate_identifier(raw.get("task_id"), "adoption.task_id")
        if task_id in result:
            raise IdentityError("portable existing-task adoption has duplicate tasks")
        validate_identifier(raw.get("binding_id"), "adoption.binding_id")
        validate_identifier(
            raw.get("workspace_lineage_id"),
            "adoption.workspace_lineage_id",
        )
        validate_identifier(
            raw.get("cloud_snapshot_id"),
            "adoption.cloud_snapshot_id",
        )
        validate_git_sha(
            raw.get("cloud_current_blob_sha"),
            "adoption.cloud_current_blob_sha",
        )
        for field in (
            "preexisting_publish_manifest_sha256",
            "approved_publish_manifest_sha256",
        ):
            if raw.get(field) is not None:
                validate_sha256(raw[field], f"adoption.{field}")
        if not isinstance(raw.get("artifact_publication_blocked"), bool):
            raise IdentityError("portable existing-task adoption gate is invalid")
        if raw.get("state") not in {
            "binding_committed",
            "cloud_current_loaded",
            "artifacts_reconciled",
        }:
            raise IdentityError("portable existing-task adoption phase is invalid")
        result[task_id] = dict(raw)
    return result


def _write_portable_adoption(
    workspace: Path,
    entry: Mapping[str, Any],
) -> None:
    task_id = validate_identifier(entry.get("task_id"), "adoption.task_id")
    entries = _load_portable_adoptions(workspace)
    entries[task_id] = dict(entry)
    atomic_write_json(
        _portable_adoptions_path(workspace),
        {
            "schema_version": PORTABLE_ADOPTION_SCHEMA,
            "vault_id": VAULT_ID,
            "adoptions": [entries[key] for key in sorted(entries)],
        },
    )


def _portable_adoption_for(
    identity: PortableIdentity,
) -> Mapping[str, Any] | None:
    return _load_portable_adoptions(identity.workspace_root).get(identity.task_id)


def _with_adoption_context(context: str, *, blocked: bool) -> str:
    lines = [
        line
        for line in context.splitlines()
        if not line.startswith(ADOPTION_CONTEXT_PREFIX)
    ]
    status = (
        "artifact publication is blocked until exact manifest inspection and "
        "device-local approval."
        if blocked
        else (
            "the inspected artifact manifest is approved on this device; "
            "changing it revokes approval."
        )
    )
    adoption_line = (
        f"{ADOPTION_CONTEXT_PREFIX} verified cloud CURRENT is active; earlier "
        f"local conversation and working files remain reference-only evidence; "
        f"{status}"
    )
    insertion = next(
        (
            index + 1
            for index, line in enumerate(lines)
            if line.startswith(
                (
                    "Five-layer handoff integrity and memory-use contract:",
                    "Memory-use rule:",
                )
            )
        ),
        min(2, len(lines)),
    )
    lines.insert(insertion, adoption_line)
    # Both legacy and projected capsules are intentionally rendered below the
    # final hook budget.  Do not prune their protected tail to make adoption
    # fit: adoption itself is mandatory, while overflow means a composer bug.
    rendered = "\n".join(lines)
    if len(rendered.encode("utf-8")) > CONTINUATION_CONTEXT_MAX_BYTES:
        raise VerificationError(
            "mandatory adopted continuation context exceeds its limit"
        )
    return rendered


def _native_handoff_path(data_dir: Path, token: str) -> Path:
    if not re.fullmatch(r"[A-Za-z0-9_-]{43}", token):
        raise PrivacyError("native handoff token is invalid")
    digest = sha256_bytes(token.encode("ascii"))
    return data_dir / "state" / "native-handoffs" / f"{digest}.json"


def _extract_native_handoff_prompt(value: Any) -> tuple[str | None, str]:
    if not isinstance(value, str):
        raise PrivacyError("user prompt is not text")
    matches = list(NATIVE_HANDOFF_MARKER_RE.finditer(value))
    if not matches:
        return None, scan_visible_text(value, "user prompt")
    if len(matches) != 1:
        raise PrivacyError("user prompt contains multiple native handoff markers")
    match = matches[0]
    prompt = (value[: match.start()] + value[match.end() :]).strip()
    if not prompt:
        prompt = "请从已验证的云端继续点开始这个任务。"
    return match.group(1), scan_visible_text(prompt, "user prompt")


def _load_native_handoff(
    data_dir: Path,
    token: str,
) -> tuple[Path, dict[str, Any]]:
    path = _native_handoff_path(data_dir, token)
    if not path.exists():
        raise IdentityError("native task handoff is missing, expired, or already used")
    value = load_json(path)
    required = {
        "schema_version",
        "mode",
        "token_sha256",
        "task_id",
        "binding_id",
        "workspace_lineage_id",
        "workspace_root",
        "expected_source_key_sha256",
        "expected_source_id",
        "expected_source_binding_id",
        "identity_documents",
        "workspace_identity_fingerprint",
        "created_at",
        "expires_at_epoch",
    }
    if (
        not isinstance(value, dict)
        or set(value) != required
        or value.get("schema_version") != NATIVE_HANDOFF_SCHEMA
        or value.get("token_sha256")
        != sha256_bytes(token.encode("ascii"))
    ):
        raise IdentityError("native task handoff state is invalid")
    mode = value.get("mode")
    if mode not in NATIVE_HANDOFF_MODES:
        raise IdentityError("native task handoff mode is invalid")
    validate_identifier(value.get("task_id"), "handoff.task_id")
    validate_identifier(value.get("binding_id"), "handoff.binding_id")
    validate_identifier(
        value.get("workspace_lineage_id"),
        "handoff.workspace_lineage_id",
    )
    workspace_root = value.get("workspace_root")
    if not isinstance(workspace_root, str) or not os.path.isabs(workspace_root):
        raise IdentityError("native task handoff workspace is invalid")
    expected_source_key = value.get("expected_source_key_sha256")
    if mode == "existing_adoption":
        validate_sha256(
            expected_source_key,
            "handoff.expected_source_key_sha256",
        )
        validate_identifier(
            value.get("expected_source_id"),
            "handoff.expected_source_id",
        )
        validate_identifier(
            value.get("expected_source_binding_id"),
            "handoff.expected_source_binding_id",
        )
        documents = value.get("identity_documents")
        fingerprint = value.get("workspace_identity_fingerprint")
        if not isinstance(documents, list) or not documents:
            raise IdentityError("existing native task adoption has no identities")
        if not isinstance(fingerprint, str):
            raise IdentityError("existing native task adoption has no workspace guard")
        validate_sha256(fingerprint, "handoff.workspace_identity_fingerprint")
        task_ids: set[str] = set()
        for document in documents:
            if not isinstance(document, Mapping):
                raise IdentityError("existing native task adoption identity is invalid")
            parsed = _parse_identity_value(document, Path(".vault_identities.json"))
            if parsed.task_id in task_ids:
                raise IdentityError(
                    "existing native task adoption has duplicate identities"
                )
            task_ids.add(parsed.task_id)
        if value.get("task_id") not in task_ids:
            raise IdentityError("existing native task adoption omits its target identity")
    elif (
        expected_source_key is not None
        or value.get("expected_source_id") is not None
        or value.get("expected_source_binding_id") is not None
    ):
        raise IdentityError(
            "new native task handoff cannot target an existing source route"
        )
    elif (
        value.get("identity_documents") is not None
        or value.get("workspace_identity_fingerprint") is not None
    ):
        raise IdentityError("new native task handoff contains adoption-only state")
    expires = value.get("expires_at_epoch")
    if not isinstance(expires, int) or isinstance(expires, bool):
        raise IdentityError("native task handoff expiry is invalid")
    if expires < int(time.time()):
        with contextlib.suppress(OSError):
            path.unlink()
        raise IdentityError("native task handoff has expired")
    return path, value


def _consume_native_handoff(path: Path) -> None:
    used = path.parent / "used" / path.name
    ensure_private_dir(used.parent)
    os.replace(path, used)
    with contextlib.suppress(OSError):
        used.unlink()


def _outbox_recovery_default(
    *,
    status: str = "ready",
    attempt_count: int = 0,
    last_error_code: str | None = None,
    next_attempt_at: str | None = None,
) -> dict[str, Any]:
    if status not in {"ready", "in_flight", "retryable", "blocked"}:
        raise VerificationError("outbox recovery status is invalid")
    return {
        "schema_version": OUTBOX_RECOVERY_SCHEMA,
        "status": status,
        "attempt_count": int(attempt_count),
        "last_error_code": last_error_code,
        "last_error_at": None,
        "next_attempt_at": next_attempt_at,
        "updated_at": utc_now(),
    }


def _outbox_recovery_value(intent: Mapping[str, Any]) -> dict[str, Any]:
    """Return a safe recovery view, accepting pre-0.13.5 intents."""

    raw = intent.get("recovery")
    attempts = intent.get("attempts")
    attempt_count = (
        int(attempts.get("count", 0))
        if isinstance(attempts, Mapping)
        and isinstance(attempts.get("count", 0), int)
        and not isinstance(attempts.get("count", 0), bool)
        else 0
    )
    if not isinstance(raw, Mapping):
        return _outbox_recovery_default(attempt_count=attempt_count)
    status = raw.get("status")
    if status not in {"ready", "in_flight", "retryable", "blocked"}:
        status = "ready"
    raw_count = raw.get("attempt_count", attempt_count)
    if not isinstance(raw_count, int) or isinstance(raw_count, bool) or raw_count < 0:
        raw_count = attempt_count
    last_error_code = raw.get("last_error_code")
    if last_error_code is not None and not isinstance(last_error_code, str):
        last_error_code = None
    next_attempt_at = raw.get("next_attempt_at")
    if next_attempt_at is not None and not isinstance(next_attempt_at, str):
        next_attempt_at = None
    return {
        "schema_version": OUTBOX_RECOVERY_SCHEMA,
        "status": status,
        "attempt_count": raw_count,
        "last_error_code": last_error_code,
        "last_error_at": (
            raw.get("last_error_at")
            if isinstance(raw.get("last_error_at"), str)
            else None
        ),
        "next_attempt_at": next_attempt_at,
        "updated_at": (
            raw.get("updated_at")
            if isinstance(raw.get("updated_at"), str)
            else utc_now()
        ),
    }


def _outbox_recovery_due(value: Mapping[str, Any], *, force: bool = False) -> bool:
    recovery = _outbox_recovery_value(value)
    if force or recovery["status"] in {"ready", "in_flight"}:
        return True
    if recovery["status"] == "blocked":
        return False
    next_attempt_at = recovery.get("next_attempt_at")
    if not isinstance(next_attempt_at, str):
        return True
    try:
        due = dt.datetime.fromisoformat(next_attempt_at.replace("Z", "+00:00"))
    except ValueError:
        return True
    return due <= dt.datetime.now(dt.timezone.utc)


def _outbox_retry_delay_seconds(attempt_count: int) -> int:
    if attempt_count <= 1:
        return 0
    return min(
        OUTBOX_RETRY_MAX_SECONDS,
        OUTBOX_RETRY_BASE_SECONDS * (2 ** min(attempt_count - 2, 12)),
    )


def _local_artifact_storage(
    artifact: Mapping[str, Any],
) -> Mapping[str, Any] | None:
    """Read generic v0.13.7 or legacy v0.13.6 local object metadata."""

    storage = artifact.get("storage")
    if isinstance(storage, Mapping):
        return storage
    drive = artifact.get("drive")
    return drive if isinstance(drive, Mapping) else None


def _outbox_path(data_dir: Path, state: str, transaction_id: str) -> Path:
    transaction = validate_identifier(transaction_id, "transaction_id")
    if state not in {"pending", "blocked", "done", "candidate", "quarantine"}:
        raise PrivacyError("outbox state is invalid")
    return data_dir / "outbox" / state / f"{transaction}.json"


def _find_outbox_state(data_dir: Path, transaction_id: str) -> str | None:
    for state in ("done", "candidate", "quarantine", "blocked", "pending"):
        if _outbox_path(data_dir, state, transaction_id).exists():
            return state
    return None


def _load_session(
    data_dir: Path, device: Mapping[str, Any], session_id: str
) -> tuple[str, dict[str, Any]] | None:
    key = _session_key(device, session_id)
    path = _session_path(data_dir, key)
    if not path.exists():
        return None
    value = load_json(path)
    if not isinstance(value, dict) or value.get("schema_version") != SESSION_SCHEMA:
        raise ConfigurationError("local session state is invalid")
    return key, value


def _save_session(data_dir: Path, session_key: str, value: Mapping[str, Any]) -> None:
    atomic_write_json(_session_path(data_dir, session_key), value)


def _contract_recovery_path(data_dir: Path, session_key: str) -> Path:
    if not re.fullmatch(r"[0-9a-f]{32}", session_key):
        raise IdentityError("session key is invalid")
    return data_dir / "state" / "contract-recovery" / f"{session_key}.json"


def _contract_recovery_due(data_dir: Path, session_key: str) -> bool:
    path = _contract_recovery_path(data_dir, session_key)
    if not path.exists():
        return True
    value = load_json(path)
    if (
        not isinstance(value, Mapping)
        or value.get("schema_version") != "memory-vault-contract-recovery/v1"
        or not isinstance(value.get("failed_at_epoch"), int)
        or isinstance(value.get("failed_at_epoch"), bool)
    ):
        raise ConfigurationError("contract recovery cooldown is invalid")
    return (
        int(time.time()) - int(value["failed_at_epoch"])
        >= CONTRACT_RECOVERY_RETRY_SECONDS
    )


def _record_contract_recovery_failure(
    data_dir: Path, session_key: str
) -> None:
    atomic_write_json(
        _contract_recovery_path(data_dir, session_key),
        {
            "schema_version": "memory-vault-contract-recovery/v1",
            "failed_at_epoch": int(time.time()),
            "required_contract": CONTINUATION_CONTEXT_CONTRACT,
        },
    )


def _clear_contract_recovery_failure(
    data_dir: Path, session_key: str
) -> None:
    with contextlib.suppress(FileNotFoundError):
        _contract_recovery_path(data_dir, session_key).unlink()


def _routing_request_id(
    device: Mapping[str, Any],
    session_id: str,
) -> str:
    return validate_identifier(
        "route-"
        + _opaque_key(
            str(device["device_secret"]),
            "routing-request",
            session_id,
            length=32,
        ),
        "routing_request_id",
    )


def _routing_request_path(data_dir: Path, request_id: str) -> Path:
    request = validate_identifier(request_id, "routing_request_id")
    return data_dir / "state" / "routing-requests" / f"{request}.json"


def _routing_choice_path(data_dir: Path, request_id: str) -> Path:
    request = validate_identifier(request_id, "routing_request_id")
    return data_dir / "state" / "routing-choices" / f"{request}.json"


def _routing_evidence_receipt_path(
    data_dir: Path,
    request_id: str,
    task_id: str,
) -> Path:
    request = validate_identifier(request_id, "routing_request_id")
    task = validate_identifier(task_id, "task_id")
    return (
        data_dir
        / "state"
        / "routing-evidence"
        / request
        / f"{task}.json"
    )


def _artifact_extraction_receipt_path(
    data_dir: Path,
    request_id: str,
    receipt_id: str,
) -> Path:
    request = validate_identifier(request_id, "routing_request_id")
    receipt = validate_identifier(receipt_id, "artifact_receipt_id")
    return (
        data_dir
        / "state"
        / "routing-artifact-evidence"
        / request
        / f"{receipt}.json"
    )


def _local_routing_review_receipt_path(
    data_dir: Path,
    request_id: str,
) -> Path:
    request = validate_identifier(request_id, "routing_request_id")
    return (
        data_dir
        / "state"
        / "routing-local-evidence"
        / f"{request}.json"
    )


def _load_routing_choice(
    data_dir: Path,
    request_id: str,
    *,
    required: bool = True,
) -> tuple[Path, dict[str, Any]] | None:
    path = _routing_choice_path(data_dir, request_id)
    if not path.exists():
        if required:
            raise IdentityError(
                "routing candidates have not been presented for user choice"
            )
        return None
    value = load_json(path)
    fields = {
        "schema_version",
        "request_id",
        "state",
        "shortlist_task_ids",
        "selection_codes",
        "remote_commit_sha",
        "candidate_set_sha256",
        "workspace_identity_fingerprint",
        "evidence_receipt_sha256",
        "local_evidence_receipt_sha256",
        "operation",
        "previous_binding_id",
        "previous_task_id",
        "workspace_mode",
        "created_at",
        "completed_at",
        "expires_at_epoch",
    }
    if not isinstance(value, dict):
        raise IdentityError("routing choice state is invalid")
    _require_keys(
        value,
        required=fields,
        allowed=fields,
        label="routing choice",
    )
    if (
        value.get("schema_version") != ROUTING_CHOICE_SCHEMA
        or value.get("request_id") != request_id
        or value.get("state")
        not in {"awaiting_user_reply", "consumed"}
    ):
        raise IdentityError("routing choice state is invalid")
    shortlist = value.get("shortlist_task_ids")
    if (
        not isinstance(shortlist, list)
        or not shortlist
        or len(shortlist) > 8
        or len(set(shortlist)) != len(shortlist)
    ):
        raise IdentityError("routing choice shortlist is invalid")
    for task_id in shortlist:
        validate_identifier(task_id, "routing choice task_id")
    selection_codes = value.get("selection_codes")
    expected_codes = {
        str(index + 1): task_id
        for index, task_id in enumerate(shortlist)
    }
    if selection_codes != expected_codes:
        raise IdentityError("routing choice selection codes are invalid")
    validate_git_sha(
        value.get("remote_commit_sha"),
        "routing choice remote commit",
    )
    validate_sha256(
        value.get("candidate_set_sha256"),
        "routing choice candidate set",
    )
    fingerprint = value.get("workspace_identity_fingerprint")
    if fingerprint is not None:
        validate_sha256(
            fingerprint,
            "routing choice workspace fingerprint",
        )
    receipts = value.get("evidence_receipt_sha256")
    if not isinstance(receipts, dict) or set(receipts) != set(shortlist):
        raise IdentityError("routing choice evidence receipts are invalid")
    for digest in receipts.values():
        validate_sha256(digest, "routing evidence receipt")
    validate_sha256(
        value.get("local_evidence_receipt_sha256"),
        "local routing evidence receipt",
    )
    operation = value.get("operation")
    previous_binding_id = value.get("previous_binding_id")
    previous_task_id = value.get("previous_task_id")
    workspace_mode = value.get("workspace_mode")
    if operation == "initial_binding":
        if (
            previous_binding_id is not None
            or previous_task_id is not None
            or workspace_mode is not None
        ):
            raise IdentityError("initial routing choice scope is invalid")
    elif operation == "route_switch":
        validate_identifier(
            previous_binding_id,
            "routing choice previous_binding_id",
        )
        validate_identifier(
            previous_task_id,
            "routing choice previous_task_id",
        )
        if workspace_mode not in {"session-only", "shared", "replace"}:
            raise IdentityError("route switch choice mode is invalid")
    else:
        raise IdentityError("routing choice operation is invalid")
    expires = value.get("expires_at_epoch")
    if not isinstance(expires, int) or isinstance(expires, bool):
        raise IdentityError("routing choice expiry is invalid")
    if value.get("state") != "consumed" and expires < int(time.time()):
        raise IdentityError("routing choice has expired")
    return path, value


def _routing_choice_has_current_content_review(
    data_dir: Path,
    request: Mapping[str, Any],
    *,
    previous_binding_id: str,
) -> bool:
    """Keep an awaiting legacy-route choice only when v4 evidence is intact."""

    try:
        choice_record = _load_routing_choice(
            data_dir,
            str(request["request_id"]),
        )
        assert choice_record is not None
        _choice_path, choice = choice_record
        _local_review, local_review_sha = (
            _load_local_routing_review_receipt(
                data_dir,
                request,
            )
        )
    except (VaultSyncError, OSError, ValueError):
        return False
    if (
        choice.get("state") != "awaiting_user_reply"
        or choice.get("remote_commit_sha")
        != request.get("remote_commit_sha")
        or choice.get("candidate_set_sha256")
        != _routing_candidate_set_sha256(request)
        or choice.get("workspace_identity_fingerprint")
        != request.get("workspace_identity_fingerprint")
        or choice.get("local_evidence_receipt_sha256")
        != local_review_sha
    ):
        return False
    operation = choice.get("operation")
    if operation == "initial_binding":
        return (
            choice.get("previous_binding_id") is None
            and choice.get("previous_task_id") is None
        )
    return bool(
        operation == "route_switch"
        and choice.get("previous_binding_id") == previous_binding_id
    )


def _routing_decision_path(data_dir: Path, token: str) -> Path:
    if ROUTING_DECISION_TOKEN_RE.fullmatch(token) is None:
        raise PrivacyError("routing decision token is invalid")
    digest = sha256_bytes(token.encode("ascii"))
    return data_dir / "state" / "routing-decisions" / f"{digest}.json"


def _routing_candidate_set_sha256(request: Mapping[str, Any]) -> str:
    return sha256_bytes(
        canonical_json_bytes(
            {
                "review_nonce": request.get("review_nonce"),
                "remote_commit_sha": request.get("remote_commit_sha"),
                "candidate_task_ids": sorted(
                    str(item)
                    for item in request.get("candidate_task_ids", [])
                ),
            }
        )
    )


def _issue_routing_decision_token(
    data_dir: Path,
    request: Mapping[str, Any],
) -> str | None:
    choice_record = _load_routing_choice(
        data_dir,
        str(request.get("request_id")),
        required=False,
    )
    if choice_record is None:
        return None
    _choice_path, choice = choice_record
    if choice.get("state") != "awaiting_user_reply":
        return None
    if (
        choice.get("remote_commit_sha")
        != request.get("remote_commit_sha")
        or choice.get("candidate_set_sha256")
        != _routing_candidate_set_sha256(request)
        or choice.get("workspace_identity_fingerprint")
        != request.get("workspace_identity_fingerprint")
    ):
        return None
    turn_id = request.get("pending_turn_id")
    prompt = request.get("pending_prompt")
    if (
        not isinstance(turn_id, str)
        or not turn_id
        or not isinstance(prompt, str)
        or not prompt
    ):
        raise IdentityError(
            "routing confirmation requires a visible user turn"
        )
    selection = unicodedata.normalize("NFKC", prompt).strip()
    selection_codes = choice.get("selection_codes")
    if not isinstance(selection_codes, Mapping):
        raise IdentityError("routing choice selection codes are invalid")
    if selection == "0":
        decision_kind = "reject"
        selected_task_id = None
    elif selection in selection_codes:
        decision_kind = "select"
        selected_task_id = validate_identifier(
            selection_codes[selection],
            "selected_task_id",
        )
    else:
        return None
    token = "mvrd_" + base64.urlsafe_b64encode(
        secrets.token_bytes(32)
    ).decode("ascii").rstrip("=")
    record = {
        "schema_version": ROUTING_DECISION_SCHEMA,
        "token_sha256": sha256_bytes(token.encode("ascii")),
        "state": "issued",
        "request_id": validate_identifier(
            request.get("request_id"),
            "routing_request_id",
        ),
        "session_key": str(request["session_key"]),
        "pending_turn_id": turn_id,
        "pending_prompt_sha256": sha256_bytes(prompt.encode("utf-8")),
        "remote_commit_sha": validate_git_sha(
            request.get("remote_commit_sha"),
            "routing remote commit",
        ),
        "candidate_set_sha256": _routing_candidate_set_sha256(request),
        "choice_sha256": sha256_bytes(canonical_json_bytes(choice)),
        "shortlist_task_ids": list(choice["shortlist_task_ids"]),
        "operation": choice["operation"],
        "previous_binding_id": choice["previous_binding_id"],
        "previous_task_id": choice["previous_task_id"],
        "workspace_mode": choice["workspace_mode"],
        "decision_kind": decision_kind,
        "selected_task_id": selected_task_id,
        "created_at": utc_now(),
        "completed_at": None,
        "expires_at_epoch": (
            int(time.time()) + ROUTING_DECISION_TTL_SECONDS
        ),
    }
    atomic_write_json(_routing_decision_path(data_dir, token), record)
    return token


def _load_routing_decision(
    data_dir: Path,
    token: str,
) -> tuple[Path, dict[str, Any]]:
    path = _routing_decision_path(data_dir, token)
    if not path.exists():
        raise IdentityError(
            "routing decision token is missing, expired, or already used"
        )
    value = load_json(path)
    required = {
        "schema_version",
        "token_sha256",
        "state",
        "request_id",
        "session_key",
        "pending_turn_id",
        "pending_prompt_sha256",
        "remote_commit_sha",
        "candidate_set_sha256",
        "choice_sha256",
        "shortlist_task_ids",
        "operation",
        "previous_binding_id",
        "previous_task_id",
        "workspace_mode",
        "decision_kind",
        "selected_task_id",
        "created_at",
        "completed_at",
        "expires_at_epoch",
    }
    if (
        not isinstance(value, dict)
        or set(value) != required
        or value.get("schema_version") != ROUTING_DECISION_SCHEMA
        or value.get("token_sha256")
        != sha256_bytes(token.encode("ascii"))
        or value.get("state")
        not in {"issued", "consuming", "consumed"}
    ):
        raise IdentityError("routing decision state is invalid")
    validate_identifier(value.get("request_id"), "routing_request_id")
    if not re.fullmatch(r"[0-9a-f]{32}", str(value.get("session_key"))):
        raise IdentityError("routing decision session is invalid")
    if (
        not isinstance(value.get("pending_turn_id"), str)
        or not value["pending_turn_id"]
    ):
        raise IdentityError("routing decision turn is invalid")
    validate_sha256(
        value.get("pending_prompt_sha256"),
        "routing prompt digest",
    )
    validate_git_sha(
        value.get("remote_commit_sha"),
        "routing remote commit",
    )
    validate_sha256(
        value.get("candidate_set_sha256"),
        "routing candidate set digest",
    )
    validate_sha256(
        value.get("choice_sha256"),
        "routing choice digest",
    )
    shortlist = value.get("shortlist_task_ids")
    if (
        not isinstance(shortlist, list)
        or not shortlist
        or len(shortlist) > 8
        or len(set(shortlist)) != len(shortlist)
    ):
        raise IdentityError("routing decision shortlist is invalid")
    for task_id in shortlist:
        validate_identifier(task_id, "routing decision task_id")
    operation = value.get("operation")
    if operation == "initial_binding":
        if (
            value.get("previous_binding_id") is not None
            or value.get("previous_task_id") is not None
            or value.get("workspace_mode") is not None
        ):
            raise IdentityError("initial routing decision scope is invalid")
    elif operation == "route_switch":
        validate_identifier(
            value.get("previous_binding_id"),
            "routing decision previous_binding_id",
        )
        validate_identifier(
            value.get("previous_task_id"),
            "routing decision previous_task_id",
        )
        if value.get("workspace_mode") not in {
            "session-only",
            "shared",
            "replace",
        }:
            raise IdentityError("route switch decision mode is invalid")
    else:
        raise IdentityError("routing decision operation is invalid")
    selected = value.get("selected_task_id")
    decision_kind = value.get("decision_kind")
    if decision_kind == "select":
        validate_identifier(selected, "selected_task_id")
        if selected not in shortlist:
            raise IdentityError(
                "routing decision selected an unpresented task"
            )
    elif decision_kind == "reject":
        if selected is not None:
            raise IdentityError("routing rejection selected a task")
    else:
        raise IdentityError("routing decision kind is invalid")
    expires = value.get("expires_at_epoch")
    if not isinstance(expires, int) or isinstance(expires, bool):
        raise IdentityError("routing decision expiry is invalid")
    if value.get("state") != "consumed" and expires < int(time.time()):
        raise IdentityError("routing decision token has expired")
    return path, value


def _assert_routing_decision_matches(
    data_dir: Path,
    decision: Mapping[str, Any],
    request: Mapping[str, Any],
) -> Mapping[str, Any]:
    prompt = request.get("pending_prompt")
    if (
        decision.get("request_id") != request.get("request_id")
        or decision.get("session_key") != request.get("session_key")
        or decision.get("pending_turn_id")
        != request.get("pending_turn_id")
        or not isinstance(prompt, str)
        or decision.get("pending_prompt_sha256")
        != sha256_bytes(prompt.encode("utf-8"))
        or decision.get("remote_commit_sha")
        != request.get("remote_commit_sha")
        or decision.get("candidate_set_sha256")
        != _routing_candidate_set_sha256(request)
    ):
        raise IdentityError(
            "routing decision no longer matches the visible turn or candidates"
        )
    choice_record = _load_routing_choice(
        data_dir,
        str(request["request_id"]),
    )
    assert choice_record is not None
    _choice_path, choice = choice_record
    if (
        choice.get("state") != "awaiting_user_reply"
        or decision.get("choice_sha256")
        != sha256_bytes(canonical_json_bytes(choice))
        or decision.get("shortlist_task_ids")
        != choice.get("shortlist_task_ids")
        or decision.get("operation") != choice.get("operation")
        or decision.get("previous_binding_id")
        != choice.get("previous_binding_id")
        or decision.get("previous_task_id")
        != choice.get("previous_task_id")
        or decision.get("workspace_mode")
        != choice.get("workspace_mode")
    ):
        raise IdentityError(
            "routing decision no longer matches the presented choices"
        )
    prompt_selection = unicodedata.normalize("NFKC", prompt).strip()
    expected_selection = (
        "0"
        if decision.get("decision_kind") == "reject"
        else next(
            (
                code
                for code, task_id in choice["selection_codes"].items()
                if task_id == decision.get("selected_task_id")
            ),
            None,
        )
    )
    if prompt_selection != expected_selection:
        raise IdentityError(
            "routing decision is not the exact choice made in the visible turn"
        )
    return choice


def _assert_frozen_routing_evidence(
    engine: "SyncEngine",
    request: Mapping[str, Any],
    choice: Mapping[str, Any],
    catalog: Mapping[str, "RemoteTaskState"],
    *,
    remote_artifact_task_id: str | None,
) -> None:
    """Recheck the exact local and remote evidence frozen for this choice."""

    data_dir = engine.data_dir
    local_review, local_review_sha = _load_local_routing_review_receipt(
        data_dir,
        request,
    )
    if local_review_sha != choice.get("local_evidence_receipt_sha256"):
        raise IdentityError(
            "the local content review changed after choices were presented"
        )
    reviews = {
        str(review["task_id"]): review
        for review in local_review["candidate_reviews"]
        if isinstance(review, Mapping)
    }
    expected_receipts = choice.get("evidence_receipt_sha256")
    if not isinstance(expected_receipts, Mapping):
        raise IdentityError("routing choice evidence scope is invalid")
    for task_id in choice["shortlist_task_ids"]:
        review = reviews.get(str(task_id))
        remote = catalog.get(str(task_id))
        if (
            review is None
            or remote is None
            or review.get("verdict") != "consistent"
        ):
            raise IdentityError(
                "a frozen routing candidate is missing or no longer fully "
                "consistent"
            )
        _receipt, remote_receipt_sha = _load_routing_evidence_receipt(
            data_dir,
            request,
            remote,
        )
        if (
            remote_receipt_sha != expected_receipts.get(task_id)
            or remote_receipt_sha
            != review.get("remote_evidence_receipt_sha256")
        ):
            raise IdentityError(
                "verified candidate evidence changed after choices were "
                "presented"
            )
        _routing_choice_artifact_disclosures(remote, review)
    if remote_artifact_task_id is not None:
        _reverify_frozen_remote_artifacts(
            engine,
            request,
            reviews,
            catalog,
            remote_artifact_task_id,
        )


def _build_source_route_content_attestation(
    data_dir: Path,
    request: Mapping[str, Any],
    choice: Mapping[str, Any],
    decision: Mapping[str, Any],
    *,
    source_id: str,
    task_id: str,
) -> dict[str, Any]:
    """Derive a route proof only from the frozen review and visible choice."""

    selected_task_id = validate_identifier(
        task_id,
        "attested selected_task_id",
    )
    if (
        decision.get("decision_kind") != "select"
        or decision.get("selected_task_id") != selected_task_id
        or decision.get("request_id") != request.get("request_id")
        or decision.get("remote_commit_sha")
        != request.get("remote_commit_sha")
        or decision.get("candidate_set_sha256")
        != _routing_candidate_set_sha256(request)
    ):
        raise IdentityError(
            "source route attestation does not match the frozen user choice"
        )
    local_review, local_review_sha = _load_local_routing_review_receipt(
        data_dir,
        request,
    )
    if (
        local_review.get("transcript_coverage") != "full_visible_task"
        or local_review_sha
        != choice.get("local_evidence_receipt_sha256")
    ):
        raise IdentityError(
            "source route attestation requires the complete frozen local review"
        )
    remote_receipts = choice.get("evidence_receipt_sha256")
    if (
        not isinstance(remote_receipts, Mapping)
        or selected_task_id not in remote_receipts
    ):
        raise IdentityError(
            "source route attestation lacks selected remote evidence"
        )
    proof = local_review.get("session_log_proof")
    reviewed_anchors = local_review.get("reviewed_turn_anchor_sha256")
    if (
        not isinstance(proof, Mapping)
        or not isinstance(reviewed_anchors, list)
        or not reviewed_anchors
    ):
        raise IdentityError(
            "source route attestation lacks exact local conversation anchors"
        )
    attestation = {
        "schema_version": SOURCE_ROUTE_CONTENT_ATTESTATION_SCHEMA,
        "authority_epoch": SOURCE_ROUTE_AUTHORITY_EPOCH,
        "matching_policy_version": MATCHING_POLICY_VERSION,
        "source_id": validate_identifier(
            source_id,
            "attested source_id",
        ),
        "request_id": validate_identifier(
            request.get("request_id"),
            "attested routing request_id",
        ),
        "review_nonce": str(request["review_nonce"]),
        "reviewed_remote_commit_sha": validate_git_sha(
            request.get("remote_commit_sha"),
            "attested routing remote commit",
        ),
        "candidate_set_sha256": validate_sha256(
            decision.get("candidate_set_sha256"),
            "attested routing candidate set",
        ),
        "selected_task_id": selected_task_id,
        "remote_evidence_receipt_sha256": validate_sha256(
            remote_receipts[selected_task_id],
            "attested remote evidence receipt",
        ),
        "local_evidence_receipt_sha256": validate_sha256(
            local_review_sha,
            "attested local evidence receipt",
        ),
        "choice_sha256": validate_sha256(
            decision.get("choice_sha256"),
            "attested routing choice",
        ),
        "decision_prompt_sha256": validate_sha256(
            decision.get("pending_prompt_sha256"),
            "attested visible user choice",
        ),
        "local_transcript_sha256": validate_sha256(
            proof.get("transcript_sha256"),
            "attested local transcript",
        ),
        "reviewed_turn_anchor_set_sha256": sha256_bytes(
            canonical_json_bytes(reviewed_anchors)
        ),
        "conversation_coverage": "full_visible_task",
        "confirmation_mode": "next_visible_numeric_choice",
    }
    return _validate_source_route_content_attestation(
        attestation,
        source_id=source_id,
        task_id=selected_task_id,
    )


def _reverify_frozen_remote_artifacts(
    engine: "SyncEngine",
    request: Mapping[str, Any],
    reviews: Mapping[str, Mapping[str, Any]],
    catalog: Mapping[str, "RemoteTaskState"],
    selected_task_id: str,
) -> None:
    """Re-download the selected task's compared objects before route writing."""

    task_id = validate_identifier(
        selected_task_id,
        "selected routing artifact task_id",
    )
    if task_id not in reviews or task_id not in catalog:
        raise IdentityError(
            "selected routing artifact task is outside the frozen shortlist"
        )
    verified_references: set[tuple[str, str, str, int]] = set()
    with tempfile.TemporaryDirectory(
        prefix="memory-vault-routing-confirm-"
    ) as temporary:
        temporary_root = Path(temporary)
        object_index = 0
        review = reviews[task_id]
        remote = catalog[task_id]
        manifest_artifacts = remote.manifest.get("artifacts")
        if not isinstance(manifest_artifacts, list):
            raise VerificationError(
                "candidate artifact manifest is invalid"
            )
        artifact_by_id: dict[str, Mapping[str, Any]] = {}
        for artifact in manifest_artifacts:
            if not isinstance(artifact, Mapping):
                raise VerificationError(
                    "candidate artifact entry is invalid"
                )
            _validate_artifact(artifact)
            artifact_id = str(artifact["artifact_id"])
            if artifact_id in artifact_by_id:
                raise VerificationError(
                    "candidate artifact identity is duplicated"
                )
            artifact_by_id[artifact_id] = artifact
        for pair in review["artifact_pairs"]:
            artifact_id = str(pair["remote_artifact_id"])
            artifact = artifact_by_id.get(artifact_id)
            if artifact is None:
                raise IdentityError(
                    "frozen artifact pair left the candidate manifest"
                )
            bundle, bundle_sha = _load_artifact_extraction_bundle(
                engine.data_dir,
                request,
                str(pair["remote_receipt_id"]),
                expected_source_kind="remote",
                expected_task_id=task_id,
            )
            if (
                bundle_sha != pair["remote_bundle_sha256"]
                or bundle.get("artifact_id") != artifact_id
                or bundle.get("object_sha256") != artifact.get("sha256")
                or bundle.get("object_size") != artifact.get("size")
            ):
                raise IdentityError(
                    "frozen remote artifact receipt no longer matches "
                    "the verified manifest"
                )
            storage_ref = _artifact_storage_ref(artifact)
            reference = (
                storage_ref["store_id"],
                storage_ref["object_id"],
                str(artifact["sha256"]),
                int(artifact["size"]),
            )
            if reference in verified_references:
                continue
            verified_references.add(reference)
            object_index += 1
            destination = (
                temporary_root / f"object-{object_index:04d}.bin"
            )
            engine._artifact_store(artifact).download_and_verify(
                artifact,
                destination,
            )
            actual_sha, actual_size = stable_hash_file(
                destination,
                inspect_text=False,
            )
            if (
                actual_sha != artifact["sha256"]
                or actual_size != artifact["size"]
            ):
                raise VerificationError(
                    "remote artifact changed after the routing choice"
                )
    _latest_path, latest_request, _latest_catalog = (
        engine._verified_routing_request(str(request["request_id"]))
    )
    if (
        latest_request.get("review_nonce") != request.get("review_nonce")
        or latest_request.get("remote_commit_sha")
        != request.get("remote_commit_sha")
    ):
        raise ConflictError(
            "remote task evidence advanced during artifact re-verification"
        )


def _provisional_claim_path(data_dir: Path, session_key: str) -> Path:
    if not isinstance(session_key, str) or not re.fullmatch(
        r"[0-9a-f]{32}", session_key
    ):
        raise IdentityError("provisional claim session key is invalid")
    return data_dir / "state" / "provisional-claims" / f"{session_key}.json"


def _load_routing_request(
    data_dir: Path,
    request_id: str,
) -> tuple[Path, dict[str, Any]]:
    path = _routing_request_path(data_dir, request_id)
    if not path.exists():
        raise IdentityError("task matching request is missing or expired")
    value = load_json(path)
    required = {
        "schema_version",
        "request_id",
        "state",
        "session_key",
        "session_id",
        "source_external_key_sha256",
        "workspace_root",
        "workspace_identity_fingerprint",
        "review_nonce",
        "remote_commit_sha",
        "candidate_task_ids",
        "pending_turn_id",
        "pending_prompt",
        "created_at",
        "updated_at",
        "expires_at_epoch",
    }
    if not isinstance(value, dict) or value.get("request_id") != request_id:
        raise IdentityError("task matching request is invalid")
    schema = value.get("schema_version")
    if schema in LEGACY_ROUTING_REQUEST_SCHEMAS:
        legacy_required = required - {"review_nonce"}
        if schema == "memory-vault-routing-request/v1":
            legacy_required -= {"workspace_identity_fingerprint"}
        if set(value) != legacy_required:
            raise IdentityError("legacy task matching request is invalid")
        value = dict(value)
        value["schema_version"] = ROUTING_REQUEST_SCHEMA
        if schema == "memory-vault-routing-request/v1":
            value["workspace_identity_fingerprint"] = None
        value["review_nonce"] = sha256_bytes(
            canonical_json_bytes(
                {
                    "request_id": value.get("request_id"),
                    "session_key": value.get("session_key"),
                    "source_external_key_sha256": value.get(
                        "source_external_key_sha256"
                    ),
                    "legacy_schema": schema,
                }
            )
        )[:32]
    elif schema == ROUTING_REQUEST_SCHEMA:
        if set(value) != required:
            raise IdentityError("task matching request is invalid")
    else:
        raise IdentityError("task matching request schema is unsupported")
    if value.get("state") not in {
        "pending",
        "awaiting_user_reply",
        "provisional",
        "promoted",
        "confirmed_by_user",
        "rejected",
    }:
        raise IdentityError("task matching request state is invalid")
    session_key = value.get("session_key")
    if not isinstance(session_key, str) or not re.fullmatch(
        r"[0-9a-f]{32}", session_key
    ):
        raise IdentityError("task matching request session key is invalid")
    session_id = value.get("session_id")
    if not isinstance(session_id, str) or not session_id:
        raise IdentityError("task matching request session identity is invalid")
    if _codex_source_key(session_id) != value.get(
        "source_external_key_sha256"
    ):
        raise IdentityError("task matching request source identity changed")
    workspace_root = value.get("workspace_root")
    if not isinstance(workspace_root, str) or not os.path.isabs(workspace_root):
        raise IdentityError("task matching request workspace is invalid")
    workspace_fingerprint = value.get("workspace_identity_fingerprint")
    if workspace_fingerprint is not None:
        validate_sha256(
            workspace_fingerprint,
            "routing workspace identity fingerprint",
        )
    review_nonce = value.get("review_nonce")
    if not isinstance(review_nonce, str) or not re.fullmatch(
        r"[0-9a-f]{32}", review_nonce
    ):
        raise IdentityError("task matching review nonce is invalid")
    validate_git_sha(value.get("remote_commit_sha"), "routing remote commit")
    task_ids = value.get("candidate_task_ids")
    if (
        not isinstance(task_ids, list)
        or len(task_ids) > 1000
        or len(set(task_ids)) != len(task_ids)
    ):
        raise IdentityError("task matching request candidates are invalid")
    for task_id in task_ids:
        validate_identifier(task_id, "routing candidate task_id")
    turn_id = value.get("pending_turn_id")
    prompt = value.get("pending_prompt")
    if (turn_id is None) != (prompt is None):
        raise IdentityError("task matching request pending turn is incomplete")
    if turn_id is not None and (
        not isinstance(turn_id, str)
        or not turn_id
        or not isinstance(prompt, str)
        or not prompt
    ):
        raise IdentityError("task matching request pending turn is invalid")
    expires = value.get("expires_at_epoch")
    if not isinstance(expires, int) or isinstance(expires, bool):
        raise IdentityError("task matching request expiry is invalid")
    if expires < int(time.time()):
        with contextlib.suppress(OSError):
            path.unlink()
        raise IdentityError("task matching request has expired")
    return path, value


def _load_routing_request_for_session(
    data_dir: Path,
    device: Mapping[str, Any],
    session_id: str,
) -> tuple[Path, dict[str, Any]] | None:
    request_id = _routing_request_id(device, session_id)
    path = _routing_request_path(data_dir, request_id)
    if not path.exists():
        return None
    return _load_routing_request(data_dir, request_id)


def _assert_routing_request_matches_workspace(
    request: Mapping[str, Any],
    cwd: str,
    allowed_roots: Sequence[str],
) -> None:
    if not isinstance(cwd, str) or not os.path.isabs(cwd):
        raise IdentityError("task matching workspace is invalid")
    try:
        workspace = Path(cwd).resolve(strict=True)
    except OSError as exc:
        raise IdentityError("task matching workspace cannot be resolved") from exc
    if str(workspace) != request.get("workspace_root"):
        raise IdentityError("task matching workspace changed")
    fingerprint = _routing_workspace_identity_fingerprint(
        workspace,
        allowed_roots,
    )
    if fingerprint != request.get("workspace_identity_fingerprint"):
        raise IdentityError("task matching workspace identity changed")


def _load_provisional_claim(
    data_dir: Path,
    session_key: str,
) -> tuple[Path, dict[str, Any]] | None:
    path = _provisional_claim_path(data_dir, session_key)
    if not path.exists():
        return None
    value = load_json(path)
    required = {
        "schema_version",
        "claim_id",
        "state",
        "request_id",
        "session_key",
        "expected_source_key_sha256",
        "source_id",
        "task_id",
        "proposal_binding_id",
        "proposal_binding_path",
        "proposal_binding_blob_sha",
        "task_current_blob_sha",
        "snapshot_id",
        "policy_version",
        "initial_evidence_digest_sha256",
        "goal_score_basis_points",
        "distinctive_score_basis_points",
        "runner_up_score_basis_points",
        "contradiction_count",
        "local_history_role",
        "artifact_publication_blocked",
        "current_pointer_update_blocked",
        "created_at",
        "updated_at",
    }
    if (
        not isinstance(value, dict)
        or set(value) != required
        or value.get("schema_version") != PROVISIONAL_CLAIM_SCHEMA
        or value.get("state")
        not in {"provisional_active", "promoted", "rejected", "revoked"}
        or value.get("session_key") != session_key
    ):
        raise IdentityError("provisional task claim is invalid")
    for key in (
        "claim_id",
        "request_id",
        "source_id",
        "task_id",
        "proposal_binding_id",
        "snapshot_id",
    ):
        validate_identifier(value.get(key), f"provisional.{key}")
    validate_sha256(
        value.get("expected_source_key_sha256"),
        "provisional.expected_source_key_sha256",
    )
    validate_sha256(
        value.get("initial_evidence_digest_sha256"),
        "provisional.initial_evidence_digest_sha256",
    )
    validate_git_sha(
        value.get("proposal_binding_blob_sha"),
        "provisional proposal binding blob",
    )
    validate_git_sha(
        value.get("task_current_blob_sha"),
        "provisional task CURRENT blob",
    )
    expected_path = (
        f"bindings/candidates/{value['proposal_binding_id']}.json"
    )
    if value.get("proposal_binding_path") != expected_path:
        raise IdentityError("provisional binding path is invalid")
    for key in (
        "goal_score_basis_points",
        "distinctive_score_basis_points",
        "runner_up_score_basis_points",
        "contradiction_count",
    ):
        score = value.get(key)
        if not isinstance(score, int) or isinstance(score, bool) or score < 0:
            raise IdentityError(f"provisional {key} is invalid")
    if (
        value.get("policy_version")
        != "user-authorized-semantic-quorum-v1"
        or value.get("local_history_role") != "reference_only"
        or value.get("artifact_publication_blocked") is not True
        or value.get("current_pointer_update_blocked") is not True
    ):
        raise IdentityError("provisional claim safety policy is invalid")
    return path, value


@dataclasses.dataclass(frozen=True)
class RemoteTaskState:
    commit_sha: str
    task_path: str
    task: Mapping[str, Any]
    current_path: str
    current_blob_sha: str
    current: Mapping[str, Any]
    manifest_path: str
    manifest: Mapping[str, Any]
    memory_projection_path: str | None = None
    memory_projection: Mapping[str, Any] | None = None


def _codex_source_key(session_id: str) -> str:
    if not isinstance(session_id, str) or not session_id:
        raise IdentityError("hook session_id is missing")
    return sha256_bytes(f"codex:{session_id}".encode("utf-8"))


def resolve_source_record(
    git: GitVault, session_id: str
) -> tuple[str, Mapping[str, Any], str]:
    """Resolve only the verified source record for an opaque local task key."""

    external_key = _codex_source_key(session_id)
    source_matches: list[tuple[str, Mapping[str, Any]]] = []
    for path in git.list_paths("sources"):
        match = re.fullmatch(r"sources/([^/]+)/SOURCE\.json", path)
        if match is None:
            continue
        source_id = validate_identifier(match.group(1), "source_id")
        source = git.show_json(path)
        if (
            source.get("schema_version") == "source/v1"
            and source.get("source_id") == source_id
            and source.get("external_source_key_sha256") == external_key
        ):
            source_matches.append((source_id, source))
    if len(source_matches) != 1:
        raise IdentityError(
            "this Codex task has no unique verified source identity in the vault"
        )
    source_id, source = source_matches[0]
    _validate_source(source)
    return source_id, source, external_key


def _confirmed_primary_source_routes(
    git: GitVault,
    source_id: str,
) -> list[SourceRoute]:
    """Return validated primary routes, including immutable superseded history."""

    validated_source = validate_identifier(source_id, "source_id")
    routes: list[SourceRoute] = []
    seen_binding_ids: set[str] = set()
    for path in git.list_paths("bindings/confirmed"):
        if not re.fullmatch(r"bindings/confirmed/[^/]+\.json", path):
            continue
        raw = git.show_bytes(path)
        try:
            binding = strict_json_loads(raw.decode("utf-8"))
        except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
            raise VerificationError(
                "confirmed source binding is invalid"
            ) from exc
        if not isinstance(binding, Mapping):
            raise VerificationError(
                "confirmed source binding is not an object"
            )
        if (
            binding.get("schema_version") != "binding/v1"
            or binding.get("state") != "confirmed"
            or binding.get("subject")
            != {"kind": "source", "id": validated_source}
        ):
            continue
        effective = binding.get("effective_range")
        targets = binding.get("targets")
        if not isinstance(effective, Mapping) or not isinstance(targets, list):
            continue
        start = effective.get("source_sequence_from")
        end = effective.get("source_sequence_to")
        if (
            not isinstance(start, int)
            or isinstance(start, bool)
            or start < 0
            or (
                end is not None
                and (
                    not isinstance(end, int)
                    or isinstance(end, bool)
                    or end < start
                )
            )
        ):
            continue
        primary_targets = [
            target
            for target in targets
            if isinstance(target, Mapping)
            and target.get("relation") == "source_for"
            and target.get("role") == "primary"
        ]
        if not primary_targets:
            continue
        if len(primary_targets) != 1:
            raise ConflictError(
                "a confirmed source binding has multiple primary task targets"
            )
        binding_id = validate_identifier(
            binding.get("binding_id"),
            "binding_id",
        )
        if path != f"bindings/confirmed/{binding_id}.json":
            raise VerificationError(
                "confirmed source binding path is inconsistent"
            )
        if binding_id in seen_binding_ids:
            raise ConflictError("confirmed source binding ID is duplicated")
        seen_binding_ids.add(binding_id)
        git.assert_immutable_path(path, raw)
        supersedes = binding.get("supersedes_binding_id")
        if supersedes is not None:
            supersedes = validate_identifier(
                supersedes,
                "supersedes_binding_id",
            )
            if supersedes == binding_id:
                raise ConflictError("a source route cannot supersede itself")
        routes.append(
            SourceRoute(
                path=path,
                binding_id=binding_id,
                task_id=validate_identifier(
                    primary_targets[0].get("semantic_task_id"),
                    "semantic_task_id",
                ),
                source_sequence_from=start,
                source_sequence_to=end,
                supersedes_binding_id=supersedes,
                document=binding,
            )
        )
    return routes


def _active_primary_source_route(
    git: GitVault,
    source_id: str,
) -> SourceRoute | None:
    """Resolve the unique immutable supersession tip for one source."""

    routes = _confirmed_primary_source_routes(git, source_id)
    if not routes:
        return None
    validated_source_id = validate_identifier(source_id, "source_id")
    source = _assert_source_append_only(git, validated_source_id)
    revisions = source.get("revisions")
    if not isinstance(revisions, list):
        raise VerificationError("source revisions are invalid")
    revision_boundary = len(revisions)
    route_ids = {route.binding_id for route in routes}
    by_id = {route.binding_id: route for route in routes}
    for route in routes:
        if route.source_sequence_from > revision_boundary:
            raise ConflictError(
                "confirmed source route begins beyond the source revision boundary"
            )
        supersedes = route.supersedes_binding_id
        if supersedes is None or supersedes in route_ids:
            if supersedes is not None:
                parent = by_id[supersedes]
                if route.source_sequence_from < parent.source_sequence_from:
                    raise ConflictError(
                        "confirmed source route supersession is not monotonic"
                    )
                if (
                    parent.source_sequence_to is not None
                    and parent.source_sequence_to
                    >= route.source_sequence_from
                ):
                    raise ConflictError(
                        "confirmed source route ranges overlap"
                    )
            continue
        candidate_path = f"bindings/candidates/{supersedes}.json"
        if not git.file_exists(candidate_path):
            raise ConflictError(
                "confirmed source route supersedes an unknown binding"
            )
        candidate_raw = git.show_bytes(candidate_path)
        try:
            candidate = strict_json_loads(candidate_raw.decode("utf-8"))
        except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
            raise VerificationError(
                "source route proposal parent is invalid"
            ) from exc
        if not isinstance(candidate, Mapping):
            raise VerificationError(
                "source route proposal parent is not an object"
            )
        if (
            candidate.get("schema_version") != "binding/v1"
            or candidate.get("binding_id") != supersedes
            or candidate.get("state") != "proposed"
            or candidate.get("subject")
            != {"kind": "source", "id": source_id}
            or candidate.get("targets")
            != [
                {
                    "semantic_task_id": route.task_id,
                    "relation": "source_for",
                    "role": "primary",
                }
            ]
        ):
            raise ConflictError(
                "confirmed source route has an invalid proposal parent"
            )
        git.assert_immutable_path(candidate_path, candidate_raw)
    superseded = {
        route.supersedes_binding_id
        for route in routes
        if route.supersedes_binding_id in route_ids
    }
    tips = [
        route
        for route in routes
        if route.source_sequence_to is None
        and route.binding_id not in superseded
    ]
    if len(tips) != 1:
        raise ConflictError(
            "this source has no unique confirmed primary route tip"
        )
    tip = tips[0]
    visited: set[str] = set()
    cursor: SourceRoute | None = tip
    while cursor is not None:
        if cursor.binding_id in visited:
            raise ConflictError("confirmed source route supersession has a cycle")
        visited.add(cursor.binding_id)
        cursor = (
            by_id.get(cursor.supersedes_binding_id)
            if cursor.supersedes_binding_id is not None
            else None
        )
    return tip


def _validate_source_route_content_attestation(
    value: Any,
    *,
    source_id: str | None = None,
    task_id: str,
) -> dict[str, Any]:
    """Validate the positive proof required for a live primary source route."""

    fields = {
        "schema_version",
        "authority_epoch",
        "matching_policy_version",
        "source_id",
        "request_id",
        "review_nonce",
        "reviewed_remote_commit_sha",
        "candidate_set_sha256",
        "selected_task_id",
        "remote_evidence_receipt_sha256",
        "local_evidence_receipt_sha256",
        "choice_sha256",
        "decision_prompt_sha256",
        "local_transcript_sha256",
        "reviewed_turn_anchor_set_sha256",
        "conversation_coverage",
        "confirmation_mode",
    }
    if not isinstance(value, Mapping):
        raise VerificationError(
            "source route content attestation is missing"
        )
    _require_keys(
        value,
        required=fields,
        allowed=fields,
        label="source route content attestation",
    )
    if (
        value.get("schema_version")
        != SOURCE_ROUTE_CONTENT_ATTESTATION_SCHEMA
        or value.get("authority_epoch") != SOURCE_ROUTE_AUTHORITY_EPOCH
        or value.get("matching_policy_version")
        != MATCHING_POLICY_VERSION
        or (
            source_id is not None
            and value.get("source_id")
            != validate_identifier(source_id, "attested source route source_id")
        )
        or value.get("selected_task_id")
        != validate_identifier(task_id, "attested source route task_id")
        or value.get("conversation_coverage") != "full_visible_task"
        or value.get("confirmation_mode")
        != "next_visible_numeric_choice"
    ):
        raise VerificationError(
            "source route content attestation is not current"
        )
    validate_identifier(
        value.get("source_id"),
        "attested source_id",
    )
    validate_identifier(
        value.get("request_id"),
        "attested routing request_id",
    )
    review_nonce = value.get("review_nonce")
    if not isinstance(review_nonce, str) or not re.fullmatch(
        r"[0-9a-f]{32}",
        review_nonce,
    ):
        raise VerificationError(
            "source route content attestation review nonce is invalid"
        )
    validate_git_sha(
        value.get("reviewed_remote_commit_sha"),
        "attested routing remote commit",
    )
    for field in (
        "candidate_set_sha256",
        "remote_evidence_receipt_sha256",
        "local_evidence_receipt_sha256",
        "choice_sha256",
        "decision_prompt_sha256",
        "local_transcript_sha256",
        "reviewed_turn_anchor_set_sha256",
    ):
        validate_sha256(value.get(field), f"content attestation {field}")
    return dict(value)


def _source_route_has_current_content_attestation(
    route: SourceRoute,
) -> bool:
    document = route.document
    if (
        document.get("confidence") != "user_confirmed"
        or document.get("confirmation_basis")
        != SOURCE_ROUTE_CONFIRMATION_BASIS
    ):
        return False
    try:
        subject = document.get("subject")
        if not isinstance(subject, Mapping):
            return False
        _validate_source_route_content_attestation(
            document.get("content_review_attestation"),
            source_id=str(subject.get("id")),
            task_id=route.task_id,
        )
    except VaultSyncError:
        return False
    return True


def _source_route_requires_content_revalidation(route: SourceRoute) -> bool:
    """Reject every legacy primary route lacking the current positive proof."""

    return bool(
        LEGACY_AUTO_BINDING_DISABLED
        and not _source_route_has_current_content_attestation(route)
    )


def _require_current_attested_source_route(
    git: GitVault,
    *,
    source_id: str,
    task_id: str,
    binding_id: str,
    source_sequence_from: int | None = None,
) -> SourceRoute:
    """Resolve one exact current route before it may alter local task state."""

    source = validate_identifier(source_id, "attested route source_id")
    task = validate_identifier(task_id, "attested route task_id")
    binding = validate_identifier(binding_id, "attested route binding_id")
    route = _active_primary_source_route(git, source)
    if (
        route is None
        or route.binding_id != binding
        or route.task_id != task
        or (
            source_sequence_from is not None
            and route.source_sequence_from != source_sequence_from
        )
        or not _source_route_has_current_content_attestation(route)
    ):
        raise IdentityError(
            "source route is not the current full-content-attested primary "
            "route; local task state was not changed"
        )
    return route


def _source_route_effective_end(
    routes: Sequence[SourceRoute],
    route: SourceRoute,
) -> int | None:
    children = [
        candidate
        for candidate in routes
        if candidate.supersedes_binding_id == route.binding_id
    ]
    if len(children) > 1:
        raise ConflictError(
            "confirmed source route has concurrent supersession children"
        )
    ends: list[int] = []
    if route.source_sequence_to is not None:
        ends.append(route.source_sequence_to)
    if children:
        ends.append(children[0].source_sequence_from - 1)
    return min(ends) if ends else None


def resolve_source_identity(git: GitVault, session_id: str) -> SourceIdentity:
    """Resolve an already-imported Codex task without storing its raw ID."""

    source_id, _source, external_key = resolve_source_record(git, session_id)
    route = _active_primary_source_route(git, source_id)
    if route is None:
        raise IdentityError(
            "this source has no unique confirmed primary task binding"
        )
    if _source_route_requires_content_revalidation(route):
        raise IdentityError(
            "this source route lacks the current full-content attestation and "
            "requires actual conversation and artifact review"
        )
    return SourceIdentity(
        binding_id=route.binding_id,
        task_id=route.task_id,
        source_id=source_id,
        external_source_key_sha256=external_key,
    )


def _historical_task_identity_supported(task: Mapping[str, Any]) -> bool:
    """Accept legacy history without allowing it as the live safety epoch."""

    schema = task.get("schema_version")
    return schema == "task/v1" or (
        schema == TASK_IDENTITY_SCHEMA
        and task.get("minimum_client_protocol") == MINIMUM_CLIENT_PROTOCOL
    )


def load_remote_task_by_id(git: GitVault, task_id: str) -> RemoteTaskState:
    """Load and verify one task without granting local publication authority."""

    task_id = validate_identifier(task_id, "task_id")
    task_path = f"tasks/{task_id}/TASK.json"
    task = git.show_json(task_path)
    if (
        task.get("schema_version") != TASK_IDENTITY_SCHEMA
        or task.get("minimum_client_protocol") != MINIMUM_CLIENT_PROTOCOL
    ):
        raise IdentityError(
            "remote task requires client protocol "
            f"{MINIMUM_CLIENT_PROTOCOL}; update memory-vault-sync before "
            "continuing"
        )
    if (
        task.get("task_id") != task_id
        or task.get("identity_status")
        not in {
            "confirmed",
            "confirmed_from_user_scope",
            "confirmed_semantic_task",
        }
    ):
        raise IdentityError("remote semantic task identity is not confirmed")
    current_path = f"tasks/{task_id}/CURRENT.json"
    current = git.show_json(current_path)
    _validate_task_current(current)
    current_blob = git.blob_sha(current_path)
    if (
        current.get("schema_version") != "task-current/v1"
        or current.get("task_id") != task_id
        or current.get("authority")
        != {
            "strategy": "git-blob-sha-compare-and-swap",
            "timestamps_are_authoritative": False,
        }
    ):
        raise VerificationError("remote CURRENT pointer is invalid")
    generation = current.get("generation")
    if not isinstance(generation, int) or generation < 1:
        raise VerificationError("remote CURRENT generation is invalid")
    manifest_path = validate_repo_path(current.get("manifest_path"), "manifest_path")
    expected_prefix = f"tasks/{task_id}/versions/"
    if not manifest_path.startswith(expected_prefix):
        raise VerificationError("remote CURRENT points outside its task")
    manifest = git.show_json(manifest_path)
    _validate_task_version(manifest)
    if (
        manifest.get("schema_version") != "task-version/v1"
        or manifest.get("task_id") != task_id
        or manifest.get("snapshot_id") != current.get("snapshot_id")
        or manifest.get("generation") != generation
        or manifest.get("transaction_id") != current.get("published_transaction_id")
        or manifest.get("state") != "published"
        or manifest.get("continuation_readiness")
        != current.get("continuation_readiness")
    ):
        raise VerificationError("remote task manifest does not match CURRENT")
    projection_path, projection = _load_task_memory_projection(
        git,
        current=current,
        manifest_path=manifest_path,
        manifest=manifest,
    )
    return RemoteTaskState(
        commit_sha=git.head_sha(),
        task_path=task_path,
        task=task,
        current_path=current_path,
        current_blob_sha=current_blob,
        current=current,
        manifest_path=manifest_path,
        manifest=manifest,
        memory_projection_path=projection_path,
        memory_projection=projection,
    )


def load_remote_task(git: GitVault, identity: TaskIdentity) -> RemoteTaskState:
    task_id = identity.task_id
    binding_path = f"bindings/confirmed/{identity.binding_id}.json"
    binding = git.show_json(binding_path)
    if (
        binding.get("schema_version") != "binding/v1"
        or binding.get("binding_id") != identity.binding_id
        or binding.get("state") != "confirmed"
    ):
        raise IdentityError("remote binding is not confirmed")
    if isinstance(identity, PortableIdentity):
        expected_subject = {
            "kind": "workspace_lineage",
            "id": identity.lineage_id,
        }
        expected_relation = "workspace_for"
        subject_error = "remote binding does not match this portable workspace lineage"
        authority_error = (
            "remote binding does not authorize this primary writable workspace"
        )
    else:
        source_path = f"sources/{identity.source_id}/SOURCE.json"
        source = git.show_json(source_path)
        if (
            source.get("schema_version") != "source/v1"
            or source.get("source_id") != identity.source_id
            or source.get("external_source_key_sha256")
            != identity.external_source_key_sha256
        ):
            raise IdentityError("remote source identity no longer matches this task")
        active_route = _active_primary_source_route(
            git,
            identity.source_id,
        )
        if (
            active_route is None
            or active_route.binding_id != identity.binding_id
            or active_route.task_id != identity.task_id
        ):
            raise IdentityError(
                "conversation source route was superseded or changed"
            )
        if _source_route_requires_content_revalidation(active_route):
            raise IdentityError(
                "conversation source route requires content revalidation"
            )
        expected_subject = {"kind": "source", "id": identity.source_id}
        expected_relation = "source_for"
        subject_error = "remote binding does not match this conversation source"
        authority_error = (
            "remote binding does not authorize conversation-only task updates"
        )
    if binding.get("subject") != expected_subject:
        raise IdentityError(subject_error)
    targets = binding.get("targets")
    if not isinstance(targets, list) or not any(
        isinstance(target, Mapping)
        and target.get("semantic_task_id") == task_id
        and target.get("relation") == expected_relation
        and target.get("role") == "primary"
        for target in targets
    ):
        raise IdentityError(authority_error)
    return load_remote_task_by_id(git, task_id)


def _linked_visible_turn(
    git: GitVault, manifest: Mapping[str, Any]
) -> list[tuple[str, str]]:
    references = manifest.get("conversation_sources")
    if not isinstance(references, list) or not references:
        return []
    result: list[tuple[str, str]] = []
    seen_messages: set[tuple[str, str]] = set()
    for reference in references[-4:]:
        if not isinstance(reference, Mapping):
            raise VerificationError("conversation source reference is invalid")
        source_id = validate_identifier(reference.get("source_id"), "source_id")
        revision_id = validate_identifier(reference.get("revision_id"), "revision_id")
        content_path = validate_repo_path(
            reference.get("content_path"), "conversation content_path"
        )
        expected_path = f"sources/{source_id}/revisions/{revision_id}.json"
        if content_path != expected_path:
            raise VerificationError(
                "conversation source path does not match its identity"
            )
        raw = git.show_bytes(content_path)
        if sha256_bytes(raw) != reference.get("content_sha256"):
            raise VerificationError("conversation source content hash does not match")
        try:
            value = strict_json_loads(raw.decode("utf-8"))
        except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
            raise VerificationError("conversation source content is invalid") from exc
        if (
            not isinstance(value, Mapping)
            or value.get("schema_version") != "conversation-export/v1"
            or value.get("source_id") != source_id
        ):
            raise VerificationError(
                "conversation source document does not match its reference"
            )
        _validate_conversation_export(value)
        messages = value.get("messages")
        if not isinstance(messages, list):
            raise VerificationError("conversation source messages are invalid")
        first_user: tuple[int, Mapping[str, Any]] | None = None
        first_substantive_user: (
            tuple[int, Mapping[str, Any]] | None
        ) = None
        latest_user: tuple[int, Mapping[str, Any]] | None = None
        selected: dict[str, tuple[int, Mapping[str, Any]]] = {}
        for index, item in enumerate(messages):
            if not isinstance(item, Mapping):
                continue
            role = item.get("role")
            if role == "user":
                if first_user is None:
                    first_user = (index, item)
                raw_text = item.get("text")
                if (
                    first_substantive_user is None
                    and isinstance(raw_text, str)
                    and len(raw_text.strip()) >= 8
                ):
                    first_substantive_user = (index, item)
                latest_user = (index, item)
            elif role == "assistant":
                selected["assistant_update"] = (index, item)
                if item.get("phase", "unknown") == "final_answer":
                    selected["assistant_final"] = (index, item)
        initial_user = first_substantive_user or first_user
        if initial_user is not None and (
            latest_user is None or initial_user[0] != latest_user[0]
        ):
            selected["user_initial"] = initial_user
        if latest_user is not None:
            selected["user"] = latest_user
        for _index, kind, item in sorted(
            (
                (index, kind, item)
                for kind, (index, item) in selected.items()
            ),
            key=lambda value: value[0],
        ):
            text = scan_visible_text(
                item.get("text"), "historical visible message"
            )
            base_role = "user" if kind.startswith("user") else "assistant"
            deduplication_key = (base_role, text)
            if deduplication_key in seen_messages:
                continue
            seen_messages.add(deduplication_key)
            result.append((kind, text))
    return result[-16:]


def _source_visible_turn(
    git: GitVault, source_id: str
) -> list[tuple[str, str]]:
    """Read the latest allowlisted visible messages from one verified source."""

    source_id = validate_identifier(source_id, "source_id")
    source = git.show_json(f"sources/{source_id}/SOURCE.json")
    _validate_source(source)
    revision_id = validate_identifier(
        source.get("current_revision_id"), "current_revision_id"
    )
    revisions = source.get("revisions")
    if not isinstance(revisions, list):
        raise VerificationError("source revisions are invalid")
    revision = next(
        (
            item
            for item in revisions
            if isinstance(item, Mapping)
            and item.get("revision_id") == revision_id
        ),
        None,
    )
    if not isinstance(revision, Mapping):
        raise VerificationError("source current revision is missing")
    if revision.get("content_ref") is None:
        return []
    content_path = f"sources/{source_id}/revisions/{revision_id}.json"
    raw = git.show_bytes(content_path)
    if sha256_bytes(raw) != revision.get("content_sha256"):
        raise VerificationError("source revision content hash does not match")
    try:
        value = strict_json_loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
        raise VerificationError("source revision content is invalid") from exc
    if (
        not isinstance(value, Mapping)
        or value.get("schema_version") != "conversation-export/v1"
        or value.get("source_id") != source_id
    ):
        raise VerificationError("source revision does not match its source")
    messages = value.get("messages")
    if not isinstance(messages, list):
        raise VerificationError("source revision messages are invalid")
    result: list[tuple[str, str]] = []
    for item in messages[-8:]:
        if not isinstance(item, Mapping) or item.get("role") not in {
            "user",
            "assistant",
        }:
            continue
        result.append(
            (
                str(item["role"]),
                scan_visible_text(item.get("text"), "historical visible message"),
            )
        )
    return result[-8:]


def _candidate_snapshots(git: GitVault, state: RemoteTaskState) -> list[str]:
    prefix = f"tasks/{state.current['task_id']}/versions"
    candidates: list[str] = []
    for path in git.list_paths(prefix):
        if not path.endswith(".json") or path == state.manifest_path:
            continue
        with contextlib.suppress(VaultSyncError):
            value = git.show_json(path)
            if (
                value.get("schema_version") == "task-version/v1"
                and value.get("task_id") == state.current["task_id"]
                and value.get("state") == "candidate"
            ):
                snapshot = value.get("snapshot_id")
                if isinstance(snapshot, str):
                    candidates.append(
                        validate_identifier(snapshot, "candidate snapshot")
                    )
    return sorted(set(candidates))[-8:]


def _utf8_size(value: str) -> int:
    return len(value.encode("utf-8"))


def _truncate_context_line(value: str, maximum: int) -> str:
    if _utf8_size(value) <= maximum:
        return value
    if maximum <= 3:
        return ""
    suffix = "…"
    available = maximum - _utf8_size(suffix)
    encoded = value.encode("utf-8")[:available]
    while encoded:
        try:
            return encoded.decode("utf-8").rstrip() + suffix
        except UnicodeDecodeError:
            encoded = encoded[:-1]
    return suffix if maximum >= _utf8_size(suffix) else ""


def _append_context_note(
    context: str,
    note: str | None,
    *,
    label: str = "verified optional notice",
) -> str:
    if not note:
        return context
    candidate = f"{context}\n{note}"
    if _utf8_size(candidate) <= CONTINUATION_CONTEXT_MAX_BYTES:
        return candidate
    remaining = (
        CONTINUATION_CONTEXT_MAX_BYTES
        - _utf8_size(context)
        - _utf8_size("\n")
    )
    marker = (
        f"[{label} omitted from compact hook context because it exceeded the "
        "remaining byte budget; the verified task capsule above is unchanged.]"
    )
    if remaining >= _utf8_size(marker):
        return f"{context}\n{marker}"
    return context


def _bounded_context_section(
    heading: str,
    items: Sequence[str],
    *,
    budget: int,
    item_limit: int,
) -> list[str]:
    if not items or budget <= _utf8_size(heading):
        return []
    newline_cost = len(items)
    available = budget - _utf8_size(heading) - newline_cost
    if available <= 0:
        return []
    per_item = max(1, min(item_limit, available // len(items)))
    lines = [heading]
    lines.extend(_truncate_context_line(item, per_item) for item in items)
    while _utf8_size("\n".join(lines)) > budget and len(lines) > 1:
        lines.pop()
    return lines if len(lines) > 1 else []


def _capsule_text(value: Any, maximum: int) -> str:
    text = str(value)
    return (
        text
        if _utf8_size(text) <= maximum
        else _truncate_context_line(text, maximum)
    )


def _projected_continuation_context_verbose(
    state: RemoteTaskState,
    *,
    git: GitVault,
    offline: bool,
) -> str:
    projection = state.memory_projection
    if not isinstance(projection, Mapping):
        raise VerificationError("verified task memory projection is unavailable")
    projection = _projection_with_runtime_completeness_basis(projection)
    legacy_basis = _projection_uses_legacy_runtime_basis(projection)
    task_id = str(state.current["task_id"])
    title = state.task.get("display_title") or task_id
    purpose = state.task.get("purpose")
    completeness = projection["completeness"]
    if projection["unprojected_deltas"] and any(
        completeness[dimension] not in {"partial", "unknown"}
        for dimension in (
            "goal_and_scope",
            "decisions",
            "rationales",
            "progress",
            "artifacts",
            "conflicts",
            "evidence",
        )
    ):
        raise VerificationError(
            "unprojected message deltas require incomplete semantic dimensions"
        )
    lines = [
        "[Private Memory Vault — verified five-layer handoff capsule]",
        f"Task: {title}",
        (
            f"Generation {state.current['generation']} · "
            f"snapshot {state.current['snapshot_id']} · "
            f"projection {projection['projection_id']} · "
            + (
                "readiness partial (legacy completeness basis requires trace)"
                if legacy_basis
                else f"readiness {state.current['continuation_readiness']}"
            )
        ),
        (
            "Authority: this is the last hash-verified cached CURRENT and is "
            "reference-only until remote authority can be rechecked."
            if offline
            else (
                "Authority: the verified CURRENT selects this immutable manifest "
                "and byte-hashed task memory projection."
            )
        ),
        (
            "Memory-use rule: use the active state below. Settled claims remain "
            "decided; superseded/rejected claims, older local conversation and "
            "files, filenames, timestamps, and unclassified artifacts are "
            "reference-only. Never ask the user to re-justify a settled change "
            "merely because old memory differs."
        ),
    ]
    if projection["unprojected_deltas"]:
        lines.append(
            "NEWEST VERIFIED BUT UNPROJECTED MESSAGES: read these before relying "
            "on the older structured goal/claims below. They may change that "
            "state and require semantic reconciliation."
        )
        source_cache: dict[str, Mapping[str, Any]] = {}
        for delta in reversed(projection["unprojected_deltas"]):
            resolved: list[tuple[str, str]] = []
            for reference in delta["message_evidence"]:
                message = _projection_source_message(
                    git,
                    state.manifest,
                    task_id,
                    reference,
                    source_cache,
                )
                resolved.append((str(message["role"]), str(message["text"])))
            exact_lines = [
                f"- {role}: {text}"
                for role, text in resolved
            ]
            exact_bytes = len("\n".join(exact_lines).encode("utf-8"))
            if exact_bytes <= 1400:
                lines.append(
                    f"- Delta [{delta['delta_id']}] exact verified messages:"
                )
                lines.extend(exact_lines)
            else:
                lines.append(
                    f"- Delta [{delta['delta_id']}] is too large for the compact "
                    "delivery capsule; its text is intentionally not shown as "
                    "complete. MANDATORY FIRST ACTION: trace-evidence --task-id "
                    f"{task_id} --entry-id {delta['evidence_entry_id']} before "
                    "substantive work."
                )
    goal = projection["current_goal"]
    lines.append("Current goal and boundary:")
    lines.append(
        (
            f"- Goal: {_capsule_text(goal['statement'], 520)}"
            if goal["status"] == "active"
            else f"- Goal not recovered: {_capsule_text(goal['reason'], 420)}"
        )
    )
    scope = projection["scope_boundaries"]
    for label, key in (("In scope", "in_scope"), ("Out of scope", "out_of_scope")):
        for boundary in scope[key]:
            lines.append(
                f"- {label} [{boundary['boundary_id']}]: "
                f"{_capsule_text(boundary['statement'], 300)}"
            )

    lines.append("Effective settled claims (apply each together with its reason):")
    for claim in projection["effective_claims"]:
        rationale = claim["rationale"]
        reason = (
            _capsule_text(rationale["statement"], 420)
            if rationale["status"] == "known"
            else (
                f"reason not recovered; trace gap {rationale['gap_id']} before "
                "asking or changing the settled outcome"
            )
        )
        lines.append(
            f"- [{claim['claim_id']} | {claim['kind']} | {claim['claim_key']}] "
            f"{_capsule_text(claim['statement'], 460)} Reason: {reason}. "
            f"Reask: {claim['reask_policy']}."
        )
    if not projection["effective_claims"]:
        lines.append("- None recorded; absence means unknown, not implicitly resolved.")

    if projection["contested_claims"]:
        lines.append("Contested claims (not settled; their disputed work is blocked):")
        for claim in projection["contested_claims"]:
            lines.append(
                f"- [{claim['claim_id']} | {claim['claim_key']}] "
                f"{_capsule_text(claim['statement'], 420)}"
            )
    if projection["blocking_conflicts"]:
        lines.append(
            "Blocking conflicts: stop only the disputed work and ask one bounded "
            "resolution question linked to the registered conflict."
        )
        for conflict in projection["blocking_conflicts"]:
            lines.append(
                f"- [{conflict['conflict_id']}] "
                f"{_capsule_text(conflict['statement'], 420)} "
                f"Claims={','.join(conflict['claim_ids']) or 'none'}; "
                f"artifacts={','.join(conflict['artifact_ids']) or 'none'}."
            )
    else:
        lines.append(
            "Blocking conflicts: none registered. Historical disagreement alone "
            "must not be promoted into a question."
        )

    if projection["superseded_claims"]:
        lines.append("Superseded claims (history only; do not re-ask):")
        for claim in projection["superseded_claims"]:
            lines.append(
                f"- [{claim['claim_id']} -> {claim['superseded_by_claim_id']}] "
                f"{_capsule_text(claim['statement'], 300)}"
            )
    if projection["rejected_options"]:
        lines.append("Rejected options (history only, with rejection reasons):")
        for option in projection["rejected_options"]:
            lines.append(
                f"- [{option['option_id']} | {option['claim_key']}] "
                f"{_capsule_text(option['statement'], 260)} Rejected because: "
                f"{_capsule_text(option['rejection_rationale']['statement'], 340)}"
            )

    lines.append("Execution ledger:")
    for item in projection["completed"]:
        lines.append(
            f"- Completed [{item['item_id']}]: "
            f"{_capsule_text(item['statement'], 380)}"
        )
    for item in projection["in_progress"]:
        lines.append(
            f"- In progress [{item['item_id']}]: "
            f"{_capsule_text(item['statement'], 320)} Next checkpoint: "
            f"{_capsule_text(item['next_checkpoint'], 260)}"
        )
    for action in projection["next_actions"]:
        dependencies = ",".join(action["depends_on_claim_ids"]) or "none"
        lines.append(
            f"- Next [{action['action_id']} | claims={dependencies}]: "
            f"{_capsule_text(action['statement'], 420)}"
        )
    if not (
        projection["completed"]
        or projection["in_progress"]
        or projection["next_actions"]
    ):
        lines.append("- No execution state recovered; treat it as a known gap.")

    current_artifacts = [
        authority
        for authority in projection["artifact_authorities"]
        if authority["authority_status"]
        in {"current_authoritative", "current_companion"}
    ]
    lines.append(
        "Authoritative artifact ledger (only these verified current entries may "
        "drive continuation):"
    )
    for authority in current_artifacts:
        checks = ",".join(
            check["kind"]
            for check in authority["verification"]["checks"]
            if check["result"] == "passed"
        )
        lines.append(
            f"- [{authority['authority_status']} | {authority['artifact_id']} | "
            f"role={authority['role']}] "
            f"{_capsule_text(authority['purpose'], 300)}; "
            f"sha256={authority['sha256']}; verified={checks}; "
            f"dependencies={','.join(authority['dependencies']) or 'none'}."
        )
    if not current_artifacts:
        lines.append(
            "- No current authoritative artifact is declared; do not infer one "
            "from a filename or the flat manifest inventory."
        )

    if projection["open_questions"]:
        lines.append("Genuine open questions (not historical disagreements):")
        for question in projection["open_questions"]:
            lines.append(
                f"- [{'BLOCKING' if question['blocking'] else 'nonblocking'} | "
                f"{question['question_id']}]: "
                f"{_capsule_text(question['question'], 380)}"
            )
    if projection["risks"]:
        lines.append("Risks:")
        for risk in projection["risks"]:
            lines.append(
                f"- [{risk['severity']} | "
                f"{'blocking' if risk['blocking'] else 'nonblocking'} | "
                f"{risk['risk_id']}]: {_capsule_text(risk['statement'], 340)}"
            )
    if projection["nonblocking_contradictions"]:
        lines.append("Resolved historical contradictions (reference only):")
        for contradiction in projection["nonblocking_contradictions"]:
            lines.append(
                f"- [{contradiction['contradiction_id']}] "
                f"{_capsule_text(contradiction['statement'], 300)} "
                f"Effective={contradiction['effective_claim_id']}; "
                f"history={','.join(contradiction['historical_claim_ids'])}."
            )
    if projection["known_gaps"]:
        lines.append(
            "Known memory gaps: trace verified evidence first; a gap is not "
            "permission to guess or automatically re-ask."
        )
        for gap in projection["known_gaps"]:
            lines.append(
                f"- [{gap['gap_id']} | {gap['area']} | {gap['trace_status']}]: "
                f"{_capsule_text(gap['statement'], 330)}"
            )
    lines.append(
        "Completeness: "
        + ", ".join(
            f"{key}={completeness[key]}"
            for key in (
                "overall",
                "goal_and_scope",
                "decisions",
                "rationales",
                "progress",
                "artifacts",
                "conflicts",
                "evidence",
            )
        )
    )
    if isinstance(purpose, str) and purpose:
        lines.append(f"Task identity purpose: {_capsule_text(purpose, 350)}")
    lines.append(
        "On-demand evidence entry points (read-only; no local work files or cloud "
        "artifact contents):"
    )
    for entry in projection["evidence_index"]:
        lines.append(
            f"- [{entry['entry_id']}]: {_capsule_text(entry['topic'], 260)}"
        )
    lines.extend(
        [
            (
                "Trace command: trace-evidence --task-id "
                f"{task_id} --entry-id <entry_id>. Trace a missing rationale, "
                "blocking conflict, multiple apparent current artifacts, a user "
                "statement that it was explained before, or any projection gap "
                "before asking or changing state."
            ),
            (
                "Before publishing, preserve object-store-first order, compare the "
                "recorded CURRENT blob, and publish source/event, projection, "
                "manifest, and CURRENT in one append-only transaction."
            ),
        ]
    )
    context = "\n".join(lines)
    if len(context) > CONTINUATION_CONTEXT_MAX_CHARS:
        raise VerificationError(
            "verified five-layer handoff capsule exceeds the safe context limit"
        )
    scan_visible_text(context, "projected continuation context")
    return context


def _compact_capsule_section(
    heading: str,
    items: Sequence[str],
    *,
    budget: int,
    omission: str,
) -> list[str]:
    if not items:
        return [heading]
    result = [heading]
    omitted = 0
    for index, item in enumerate(items):
        candidate = "\n".join([*result, item])
        if _utf8_size(candidate) <= budget:
            result.append(item)
            continue
        omitted = len(items) - index
        break
    if omitted:
        marker = f"- [{omitted} item(s) omitted] {omission}"
        while len(result) > 1 and _utf8_size(
            "\n".join([*result, marker])
        ) > budget:
            result.pop()
            omitted += 1
            marker = f"- [{omitted} item(s) omitted] {omission}"
        if _utf8_size("\n".join([*result, marker])) <= budget:
            result.append(marker)
    return result


def _projected_continuation_context(
    state: RemoteTaskState,
    *,
    git: GitVault,
    offline: bool,
) -> str:
    """Render a priority-ordered, UTF-8-byte-bounded operational capsule."""

    projection = state.memory_projection
    if not isinstance(projection, Mapping):
        raise VerificationError("verified task memory projection is unavailable")
    projection = _projection_with_runtime_completeness_basis(projection)
    legacy_basis = _projection_uses_legacy_runtime_basis(projection)
    task_id = str(state.current["task_id"])
    title = str(state.task.get("display_title") or task_id)
    completeness = projection["completeness"]
    dimensions = (
        "goal_and_scope",
        "decisions",
        "rationales",
        "progress",
        "artifacts",
        "conflicts",
        "evidence",
    )
    if projection["unprojected_deltas"] and any(
        completeness[dimension] not in {"partial", "unknown"}
        for dimension in dimensions
    ):
        raise VerificationError(
            "unprojected message deltas require incomplete semantic dimensions"
        )

    lines = [
        "[Private Memory Vault — verified five-layer handoff capsule]",
        f"Task: {_capsule_text(title, 240)}",
        (
            f"Generation {state.current['generation']} · "
            f"snapshot {state.current['snapshot_id']} · "
            f"projection {projection['projection_id']} · "
            + (
                "readiness partial (legacy completeness basis requires trace)"
                if legacy_basis
                else f"readiness {state.current['continuation_readiness']}"
            )
        ),
        (
            "Authority: cached verified state is reference-only until remote "
            "authority can be rechecked."
            if offline
            else (
                "Authority: verified CURRENT selects this immutable manifest "
                "and byte-hashed projection."
            )
        ),
        (
            "Memory-use rule: newest verified unprojected messages come first. "
            "Then apply active claims together with their reasons. Superseded, "
            "rejected, older-local, and unclassified material is reference-only; "
            "do not ask the user to repeat recoverable evidence."
        ),
    ]
    footer = [
        (
            "Trace rule: use `trace-evidence --task-id "
            f"{task_id} --entry-id <entry_id>` before asking or changing state "
            "when a reason, conflict, authority, prior explanation, or projection "
            "gap is unclear. If no entry ID is visible, run `trace-evidence "
            f"--task-id {task_id}` first to list valid IDs."
        ),
        (
            "Publish rule: preserve artifact-first verification, compare the "
            "recorded CURRENT blob, then commit source/event, projection, "
            "manifest, and CURRENT atomically."
        ),
    ]

    # 1. Exact newest deltas. They outrank the older structured state. Exact
    # message text is never truncated and is replaced by a trace requirement
    # when it cannot fit safely.
    if projection["unprojected_deltas"]:
        delta_items: list[str] = []
        source_cache: dict[str, Mapping[str, Any]] = {}
        deltas = list(reversed(projection["unprojected_deltas"]))
        for delta in deltas:
            resolved = [
                _projection_source_message(
                    git,
                    state.manifest,
                    task_id,
                    reference,
                    source_cache,
                )
                for reference in delta["message_evidence"]
            ]
            exact = "\n".join(
                f"  - {message['role']}: {message['text']}"
                for message in resolved
            )
            item = (
                f"- Delta [{delta['delta_id']}] exact verified messages:\n{exact}"
            )
            if _utf8_size(item) > 1050:
                item = (
                    f"- Delta [{delta['delta_id']}] is larger than the compact "
                    "capsule. MANDATORY FIRST ACTION: `trace-evidence --task-id "
                    f"{task_id} --entry-id {delta['evidence_entry_id']}`; do not "
                    "rely on older structured state before reading it."
                )
            delta_items.append(item)
        lines.extend(
            _compact_capsule_section(
                "1. NEWEST VERIFIED UNPROJECTED MESSAGES — reconcile these "
                "before older structured state:",
                delta_items,
                budget=700,
                omission=(
                    "Additional verified deltas require `trace-evidence`; do not "
                    "claim the task is semantically reconciled."
                ),
            )
        )

    # 2. Goal.
    goal = projection["current_goal"]
    goal_items = [(
        f"- Goal: {_capsule_text(goal['statement'], 320)}"
        if goal["status"] == "active"
        else (
            f"- Goal not recovered: {_capsule_text(goal['reason'], 430)}; trace "
            "evidence before asking or guessing."
        )
    )]
    boundaries = projection["scope_boundaries"]
    goal_items.extend(
        f"- In scope [{item['boundary_id']}]: "
        f"{_capsule_text(item['statement'], 220)}"
        for item in boundaries["in_scope"][:1]
    )
    goal_items.extend(
        f"- Out of scope [{item['boundary_id']}]: "
        f"{_capsule_text(item['statement'], 220)}"
        for item in boundaries["out_of_scope"][:1]
    )
    omitted_boundaries = (
        len(boundaries["in_scope"]) - min(1, len(boundaries["in_scope"]))
        + len(boundaries["out_of_scope"])
        - min(1, len(boundaries["out_of_scope"]))
    )
    if omitted_boundaries:
        goal_items.append(
            f"- [{omitted_boundaries} additional boundary item(s)] Trace the "
            "projection before expanding the task scope."
        )
    lines.extend(
        _compact_capsule_section(
            "2. CURRENT GOAL AND BOUNDARY:",
            goal_items,
            budget=520,
            omission="Goal must be traced before substantive work.",
        )
    )

    # 3. Blocking conflicts precede decisions so they can limit only the
    # disputed work.
    conflict_items = [
        (
            f"- [{conflict['conflict_id']}] "
            f"{_capsule_text(conflict['statement'], 190)} "
            f"claims={','.join(conflict['claim_ids']) or 'none'}; "
            f"artifacts={','.join(conflict['artifact_ids']) or 'none'}"
        )
        for conflict in projection["blocking_conflicts"]
    ]
    if not conflict_items:
        conflict_items = [
            "- None registered; historical disagreement alone is not an open "
            "question."
        ]
    for question in projection["open_questions"]:
        if question["blocking"]:
            conflict_items.append(
                f"- Blocking question [{question['question_id']}]: "
                f"{_capsule_text(question['question'], 260)}"
            )
    lines.extend(
        _compact_capsule_section(
            "3. BLOCKING CONFLICTS:",
            conflict_items,
            budget=380,
            omission=(
                "Trace omitted registered conflicts and stop only their disputed "
                "work."
            ),
        )
    )

    # 4. Effective decisions and reasons.
    claim_items: list[str] = []
    for claim in projection["effective_claims"]:
        rationale = claim["rationale"]
        reason = (
            _capsule_text(rationale["statement"], 220)
            if rationale["status"] == "known"
            else (
                f"reason not recovered; trace gap {rationale['gap_id']} before "
                "changing this settled outcome"
            )
        )
        claim_items.append(
            f"- [{claim['claim_id']} | {claim['claim_key']}] "
            f"{_capsule_text(claim['statement'], 220)} Reason: {reason}. "
            f"Reask={claim['reask_policy']}."
        )
    if not claim_items:
        claim_items = ["- None recorded; absence means unknown, not resolved."]
    lines.extend(
        _compact_capsule_section(
            "4. EFFECTIVE SETTLED CLAIMS — apply each with its reason:",
            claim_items,
            budget=760,
            omission=(
                "Trace the projection before changing omitted active claims; "
                "their omission from this compact view does not unsettle them."
            ),
        )
    )

    # 5. Next action.
    action_items = [
        (
            f"- [{action['action_id']}] "
            f"{_capsule_text(action['statement'], 220)} "
            f"depends_on={','.join(action['depends_on_claim_ids']) or 'none'}"
        )
        for action in projection["next_actions"]
    ]
    if not action_items:
        action_items = ["- No next action recovered; treat this as a known gap."]
    lines.extend(
        _compact_capsule_section(
            "5. NEXT ACTION:",
            action_items,
            budget=360,
            omission="Trace omitted actions before selecting work.",
        )
    )

    # 6. Current artifact authority.
    current_artifacts = [
        authority
        for authority in projection["artifact_authorities"]
        if authority["authority_status"]
        in {"current_authoritative", "current_companion"}
    ]
    artifact_items = [
        (
            f"- [{authority['authority_status']} | {authority['artifact_id']} | "
            f"role={authority['role']}] "
            f"{_capsule_text(authority['purpose'], 150)}; "
            f"sha256={authority['sha256']}; "
            f"verification={authority['verification']['status']}; "
            f"dependencies={','.join(authority['dependencies']) or 'none'}"
        )
        for authority in current_artifacts
    ]
    if not artifact_items:
        artifact_items = [
            "- None declared; never infer authority from a filename, timestamp, "
            "or flat inventory."
        ]
    lines.extend(
        _compact_capsule_section(
            "6. CURRENT AUTHORITATIVE ARTIFACTS:",
            artifact_items,
            budget=520,
            omission=(
                "Trace omitted artifact authorities before opening, replacing, "
                "or publishing an artifact."
            ),
        )
    )

    # 7. Execution status is protected: a handoff must say what is done,
    # underway, and still pending even when the detailed ledger is large.
    progress_items: list[str] = []
    if projection["completed"]:
        item = projection["completed"][0]
        progress_items.append(
            f"- Completed [{item['item_id']}]: "
            f"{_capsule_text(item['statement'], 40)}"
            + (
                f" (+{len(projection['completed']) - 1} more; trace by ID)"
                if len(projection["completed"]) > 1
                else ""
            )
        )
    else:
        progress_items.append("- Completed: none recorded.")
    if projection["in_progress"]:
        item = projection["in_progress"][0]
        progress_items.append(
            f"- In progress [{item['item_id']}]: "
            f"{_capsule_text(item['statement'], 40)}; next="
            f"{_capsule_text(item['next_checkpoint'], 35)}"
            + (
                f" (+{len(projection['in_progress']) - 1} more; trace by ID)"
                if len(projection["in_progress"]) > 1
                else ""
            )
        )
    else:
        progress_items.append("- In progress: none recorded.")
    progress_items.append(
        f"- Pending next actions: {len(projection['next_actions'])}; "
        "the first actionable item is protected in section 5."
    )
    lines.extend(
        _compact_capsule_section(
            "7. EXECUTION STATUS — completed, in progress, pending:",
            progress_items,
            budget=650,
            omission=(
                "Trace omitted progress records; omission does not change "
                "their status."
            ),
        )
    )

    # 8. Rejected and superseded decisions are protected history because they
    # prevent a new client from reviving a settled dead end.
    history_items: list[str] = []
    if projection["rejected_options"]:
        item = projection["rejected_options"][0]
        history_items.append(
            f"- Rejected [{item['option_id']}]: "
            f"{_capsule_text(item['statement'], 110)} because "
            f"{_capsule_text(item['rejection_rationale']['statement'], 140)}"
        )
        if len(projection["rejected_options"]) > 1:
            history_items.append(
                f"- [{len(projection['rejected_options']) - 1} more rejected "
                "option(s)] Trace by stable ID before reconsidering."
            )
    else:
        history_items.append("- Rejected options: none recorded.")
    if projection["superseded_claims"]:
        item = projection["superseded_claims"][0]
        rationale = item.get("rationale")
        rationale_text = (
            _capsule_text(rationale.get("statement"), 110)
            if isinstance(rationale, Mapping)
            and rationale.get("status") == "known"
            else "trace the historical claim for its reason"
        )
        history_items.append(
            f"- Superseded [{item['claim_id']} -> "
            f"{item['superseded_by_claim_id']}]: "
            f"{_capsule_text(item['statement'], 90)}; reason={rationale_text}"
        )
        if len(projection["superseded_claims"]) > 1:
            history_items.append(
                f"- [{len(projection['superseded_claims']) - 1} more "
                "superseded claim(s)] Trace by stable ID."
            )
    else:
        history_items.append("- Superseded claims: none recorded.")
    lines.extend(
        _compact_capsule_section(
            "8. REJECTED / SUPERSEDED HISTORY — reference only:",
            history_items,
            budget=430,
            omission=(
                "Trace omitted rejected or superseded records before reviving "
                "an old option."
            ),
        )
    )

    # 9. Nonblocking questions, risks, and gaps remain visible as operational
    # warnings. Blocking questions already appear in section 3.
    warning_items: list[str] = []
    if projection["open_questions"]:
        item = projection["open_questions"][0]
        warning_items.append(
            f"- Question [{item['question_id']} | "
            f"{'blocking' if item['blocking'] else 'nonblocking'}]: "
            f"{_capsule_text(item['question'], 130)}"
        )
        if len(projection["open_questions"]) > 1:
            warning_items.append(
                f"- [{len(projection['open_questions']) - 1} more question(s)] "
                "Trace before treating them as resolved."
            )
    else:
        warning_items.append("- Open questions: none recorded.")
    if projection["risks"]:
        item = projection["risks"][0]
        warning_items.append(
            f"- Risk [{item['risk_id']} | {item['severity']}]: "
            f"{_capsule_text(item['statement'], 130)}"
        )
        if len(projection["risks"]) > 1:
            warning_items.append(
                f"- [{len(projection['risks']) - 1} more risk(s)] Trace by ID."
            )
    else:
        warning_items.append("- Risks: none recorded.")
    if projection["known_gaps"]:
        item = projection["known_gaps"][0]
        warning_items.append(
            f"- Gap [{item['gap_id']} | {item['area']}]: "
            f"{_capsule_text(item['statement'], 120)}"
        )
        if len(projection["known_gaps"]) > 1:
            warning_items.append(
                f"- [{len(projection['known_gaps']) - 1} more gap(s)] "
                "Use trace-evidence; never guess."
            )
    else:
        warning_items.append("- Known gaps: none recorded.")
    lines.extend(
        _compact_capsule_section(
            "9. OPEN QUESTIONS, RISKS, AND GAPS:",
            warning_items,
            budget=470,
            omission=(
                "Trace omitted warnings by stable ID before treating them as "
                "resolved."
            ),
        )
    )

    evidence_items = [
        f"- [{entry['entry_id']}]: {_capsule_text(entry['topic'], 140)}"
        for entry in projection["evidence_index"]
    ]
    lines.extend(
        _compact_capsule_section(
            "10. VERIFIED EVIDENCE ENTRY IDS:",
            evidence_items or ["- None registered; treat tracing as blocked."],
            budget=300,
            omission=(
                "List additional verified entry IDs with `trace-evidence "
                f"--task-id {state.current['task_id']}`."
            ),
        )
    )

    completeness_line = "11. COMPLETENESS: " + ", ".join(
        f"{key}={completeness[key]}"
        for key in ("overall", *dimensions)
    )
    lines.append(completeness_line)
    lines.append(
        "Completeness basis lookup: `show-memory-projection --task-id "
        f"{task_id} --kind completeness --id <dimension>` returns the "
        "current reason and pinned evidence."
    )
    lines.extend(footer)
    context = "\n".join(lines)
    if _utf8_size(context) > CONTINUATION_CAPSULE_TARGET_BYTES:
        raise VerificationError(
            "protected five-layer capsule exceeds its fixed UTF-8 byte target"
        )
    scan_visible_text(context, "projected continuation context")
    return context


def _continuation_context(
    state: RemoteTaskState,
    *,
    git: GitVault | None = None,
    offline: bool = False,
    reference_source_ids: Sequence[str] = (),
) -> str:
    if state.memory_projection is not None:
        if git is None:
            raise VerificationError(
                "structured continuation requires its verified Git evidence view"
            )
        return _projected_continuation_context(
            state,
            git=git,
            offline=offline,
        )
    title = state.task.get("display_title") or state.current["task_id"]
    purpose = state.task.get("purpose")
    remaining = state.manifest.get("remaining_work")
    questions = state.manifest.get("open_questions")
    deferred_reference_turns: list[tuple[str, str]] = []
    artifact_count = len(state.manifest.get("artifacts", []))
    raw_evidence_root = validate_repo_path(
        state.manifest_path, "continuation evidence manifest"
    )
    lines = [
        "[Private Memory Vault]",
        (
            "Remote status could not be refreshed; this is cached reference only."
            if offline
            else "The following Git blob-verified checkpoint is the authoritative continuation point."
        ),
        f"Task: {title}",
        f"Generation: {state.current['generation']}",
        f"Snapshot: {state.current['snapshot_id']}",
        f"Readiness: {state.current['continuation_readiness']}",
    ]
    if isinstance(purpose, str) and purpose:
        lines.append(f"Purpose: {purpose[:1000]}")
    lines.extend(
        [
            "Five-layer handoff integrity and memory-use contract:",
            (
                "- Authority: this cached checkpoint and everything derived from it "
                "are reference-only until the remote authority is verified."
                if offline
                else (
                    "- Authority: the verified CURRENT selects the active version. "
                    "Within it, explicit user decisions and completed assistant "
                    "results define the active narrative; a later progress update "
                    "refines status but does not silently reverse a completed result."
                )
            ),
            (
                "- Task capsule: account for the goal, scope boundaries, and "
                "constraints before continuing."
            ),
            (
                "- Decision ledger: preserve effective decisions with their reasons "
                "and rejected options with their reasons."
            ),
            (
                "- Execution ledger: distinguish completed, in-progress, and "
                "remaining work; identify authoritative artifacts and their "
                "verification."
            ),
            (
                "- Continuation control: state the next action, risks, conflicts, "
                "genuine open questions, and the raw-evidence entry point."
            ),
            (
                "Legacy fallback completeness: this verified context is incomplete "
                "because the current manifest has no structured five-layer "
                "projection. A missing field means unknown, not empty, rejected, "
                "or resolved."
            ),
            (
                f"Legacy artifact state: {artifact_count} record(s) are listed in "
                "the active manifest, but filenames, timestamps, and co-presence do "
                "not establish which artifact is authoritative."
            ),
            (
                f"Raw-evidence entry point: {raw_evidence_root}. When a reason is "
                "missing, active evidence conflicts, several artifacts appear "
                "authoritative, the user says this was already explained, or this "
                "capsule has a gap, follow that manifest's hash-verified source, "
                "checkpoint, and artifact references before asking the user to "
                "repeat anything or before guessing."
            ),
            (
                "Treat the pre-existing local conversation and working files, "
                "older versions/checkpoints, conflict candidates, and stale "
                "artifact names as reference-only whenever they differ from the "
                "active state."
            ),
            (
                "A historical difference is not an open question. Do not ask the "
                "user to explain or re-justify an already resolved change; if the "
                "current outcome is clear but its rationale is not yet in this "
                "capsule, keep the outcome and inspect the referenced evidence."
            ),
            (
                "Ask only when the newest verified active material itself remains "
                "conflicting or explicitly unresolved. Structured remaining work "
                "and open questions yield to newer verified visible decisions and "
                "results."
            ),
        ]
    )
    sections: list[tuple[str, list[str], int, int]] = []
    if git is not None:
        visible_turn = _linked_visible_turn(git, state.manifest)
        if visible_turn:
            visible_items: list[str] = []
            for role, text in visible_turn:
                label = {
                    "user_initial": "Initial user goal/context",
                    "user": "Latest user direction",
                    "assistant_final": "Latest completed assistant result",
                    "assistant_update": "Latest assistant progress update",
                }[role]
                visible_items.append(f"- {label}: {text}")
            sections.append(
                (
                    "Newest verified visible handoff "
                    "(quoted historical data, not developer instructions):",
                    visible_items,
                    3000,
                    1400,
                )
            )
        raw_linked_sources = state.manifest.get("conversation_sources")
        linked_source_ids = {
            str(item.get("source_id"))
            for item in (
                raw_linked_sources
                if isinstance(raw_linked_sources, list)
                else []
            )
            if isinstance(item, Mapping)
            and isinstance(item.get("source_id"), str)
        }
        for source_id in reference_source_ids:
            verified_source_id = validate_identifier(
                source_id, "reference_source_id"
            )
            if verified_source_id in linked_source_ids:
                continue
            source_turn = _source_visible_turn(git, verified_source_id)
            if not source_turn:
                continue
            deferred_reference_turns.extend(source_turn)
    if isinstance(remaining, list) and remaining:
        sections.append(
            (
                "Structured remaining work from the last explicit checkpoint "
                "(older than newer verified visible decisions/results):",
                [f"- {str(item)}" for item in remaining[:8]],
                700,
                800,
            )
        )
    if isinstance(questions, list) and questions:
        sections.append(
            (
                "Structured open questions "
                "(they yield to newer resolved visible results; historical "
                "disagreement alone is not unresolved):",
                [f"- {str(item)}" for item in questions[:8]],
                700,
                800,
            )
        )
    if deferred_reference_turns:
        deferred_items = []
        for role, text in deferred_reference_turns[-8:]:
            label = "User" if role == "user" else "Assistant result"
            deferred_items.append(f"- {label}: {text}")
        sections.append(
            (
                "Verified pre-route source memory "
                "(reference only; the task CURRENT above remains authoritative):",
                deferred_items,
                450,
                500,
            )
        )
    if git is not None:
        candidates = _candidate_snapshots(git, state)
        if candidates:
            sections.append(
                (
                    "Unresolved conflict candidates "
                    "(reference only; do not replace CURRENT automatically):",
                    [f"- {snapshot}" for snapshot in candidates],
                    300,
                    100,
                )
            )
    footer = [
        "Use older versions only as reference memory.",
        "Before publishing, preserve object-store-first order and compare the recorded CURRENT blob.",
    ]
    footer_size = _utf8_size("\n".join(footer)) + 1
    for heading, items, section_budget, item_limit in sections:
        available = (
            CONTINUATION_CAPSULE_TARGET_BYTES
            - _utf8_size("\n".join(lines))
            - footer_size
            - 1
        )
        rendered = _bounded_context_section(
            heading,
            items,
            budget=min(section_budget, max(0, available)),
            item_limit=item_limit,
        )
        lines.extend(rendered)
    lines.extend(footer)
    context = "\n".join(lines)
    if _utf8_size(context) > CONTINUATION_CAPSULE_TARGET_BYTES:
        raise VerificationError("mandatory continuation context exceeds its limit")
    scan_visible_text(context, "continuation context")
    return context


def _conversation_document(intent: Mapping[str, Any]) -> tuple[str, bytes, Mapping[str, Any]]:
    delta = intent["conversation_delta"]
    source_id = validate_identifier(delta.get("source_id"), "source_id")
    revision_id = validate_identifier(delta.get("revision_id"), "revision_id")
    task_id = validate_identifier(intent.get("task_id"), "task_id")
    prompt = delta.get("prompt")
    assistant = delta.get("last_assistant")
    messages: list[dict[str, Any]] = []
    if isinstance(prompt, str) and prompt:
        messages.append(
            {
                "ordinal": len(messages),
                "role": "user",
                "phase": "unknown",
                "text": scan_visible_text(prompt, "queued user prompt"),
            }
        )
    if isinstance(assistant, str) and assistant:
        messages.append(
            {
                "ordinal": len(messages),
                "role": "assistant",
                "phase": "final_answer",
                "text": scan_visible_text(assistant, "queued assistant message"),
            }
        )
    if not messages:
        raise PrivacyError("conversation delta has no visible messages")
    document = {
        "schema_version": "conversation-export/v1",
        "source_id": source_id,
        "title": f"Visible Codex turn for {task_id}",
        "captured_at": intent["created_at"],
        "coverage": "partial_active_turn",
        "included_content": [
            "visible user prompt",
            "visible final assistant message",
        ],
        "excluded_content": [
            "hidden reasoning",
            "tool traces",
            "runtime transcript",
            "credentials",
            "local absolute paths",
        ],
        "messages": messages,
    }
    assert_remote_safe(document)
    content = pretty_json_bytes(document)
    path = f"sources/{source_id}/revisions/{revision_id}.json"
    return path, content, document


def _source_document(
    git: GitVault,
    intent: Mapping[str, Any],
    conversation_path: str,
    conversation_bytes: bytes,
) -> tuple[str, bytes]:
    delta = intent["conversation_delta"]
    source_id = validate_identifier(delta.get("source_id"), "source_id")
    revision_id = validate_identifier(delta.get("revision_id"), "revision_id")
    source_path = f"sources/{source_id}/SOURCE.json"
    if git.file_exists(source_path):
        existing = dict(git.show_json(source_path))
        if (
            existing.get("schema_version") != "source/v1"
            or existing.get("source_id") != source_id
        ):
            raise VerificationError("existing source identity is invalid")
        revisions = existing.get("revisions")
        if not isinstance(revisions, list):
            raise VerificationError("existing source revisions are invalid")
        if any(
            isinstance(item, Mapping) and item.get("revision_id") == revision_id
            for item in revisions
        ):
            return source_path, pretty_json_bytes(existing)
        sequence = max(
            [
                int(item.get("source_sequence", -1))
                for item in revisions
                if isinstance(item, Mapping)
                and isinstance(item.get("source_sequence"), int)
            ],
            default=-1,
        ) + 1
        previous = existing.get("current_revision_id")
        created_at = existing.get("created_at")
        external_key = existing.get("external_source_key_sha256")
        source_type = existing.get("source_type")
        source_instance_id = existing.get("source_instance_id")
        visibility = existing.get("visibility")
        sensitivity = existing.get("sensitivity")
    else:
        revisions = []
        sequence = 0
        previous = None
        created_at = intent["created_at"]
        external_key = delta.get("external_source_key_sha256")
        validate_sha256(external_key, "external_source_key_sha256")
        source_type = "chat_thread"
        source_instance_id = None
        visibility = "private"
        sensitivity = "restricted"
    revision = {
        "revision_id": revision_id,
        "previous_revision_id": previous,
        "source_sequence": sequence,
        "captured_at": intent["created_at"],
        "coverage": "partial",
        "content_ref": {
            "storage": "git_blob",
            "object_id": git_blob_sha(conversation_bytes),
            "object_revision_id": None,
            "byte_size": len(conversation_bytes),
            "media_type": "application/json",
        },
        "content_sha256": sha256_bytes(conversation_bytes),
        "redaction": {
            "credentials_scanned": True,
            "content_removed": False,
        },
    }
    source = {
        "schema_version": "source/v1",
        "source_id": source_id,
        "source_type": source_type,
        "external_source_key_sha256": external_key,
        "source_instance_id": source_instance_id,
        "visibility": visibility,
        "sensitivity": sensitivity,
        "current_revision_id": revision_id,
        "revisions": [*revisions, revision],
        "created_at": created_at,
    }
    assert_remote_safe(source)
    return source_path, pretty_json_bytes(source)


def _merge_artifacts(
    parent: Mapping[str, Any],
    intent: Mapping[str, Any],
    *,
    preserve_replaced: bool,
) -> list[Mapping[str, Any]]:
    merged: dict[str, Mapping[str, Any]] = {}
    existing_identities: dict[tuple[str, str], str] = {}
    existing = parent.get("artifacts")
    if isinstance(existing, list):
        for item in existing:
            if isinstance(item, Mapping) and isinstance(item.get("logical_path"), str):
                if (
                    isinstance(item.get("sha256"), str)
                    and isinstance(item.get("artifact_id"), str)
                ):
                    existing_identities[
                        (str(item["logical_path"]), str(item["sha256"]))
                    ] = str(item["artifact_id"])
                key = (
                    str(item.get("artifact_id"))
                    if preserve_replaced
                    else str(item["logical_path"])
                )
                merged[key] = dict(item)
    provider_pins = _validate_provider_transaction_pins(
        intent.get("provider_pins")
    )
    object_pin = provider_pins["object_store"]
    for local in intent.get("artifacts", []):
        if not isinstance(local, Mapping):
            raise VerificationError("queued artifact is invalid")
        storage = local.get("storage")
        legacy_storage = not isinstance(storage, Mapping)
        if not isinstance(storage, Mapping):
            storage = local.get("drive")
        if not isinstance(storage, Mapping):
            raise VerificationError(
                "queued artifact has not been object-store verified"
            )
        if storage.get("store_id") not in {None, object_pin.get("store_id")}:
            raise VerificationError(
                "queued artifact object store does not match its provider pin"
            )
        if storage.get("driver") not in {None, object_pin.get("driver")}:
            raise VerificationError(
                "queued artifact adapter does not match its provider pin"
            )
        storage_ref = _validate_artifact_storage_ref(
            {
                "schema_version": ARTIFACT_STORAGE_REF_SCHEMA,
                "store_id": storage.get("store_id")
                or object_pin.get("store_id"),
                "driver": storage.get("driver")
                or object_pin.get("driver"),
                "object_id": storage.get("file_id"),
                "container_id": storage.get("parent_id"),
                "verification_level": (
                    storage.get("verification_level")
                    or (
                        "legacy-drive-reference"
                        if legacy_storage
                        else None
                    )
                ),
            }
        )
        sha256 = validate_sha256(local.get("sha256"), "artifact.sha256")
        logical_path = validate_repo_path(local.get("logical_path"), "artifact logical_path")
        artifact_identity = sha256_bytes(
            f"{logical_path}\0{sha256}".encode("utf-8")
        )
        artifact_id = existing_identities.get(
            (logical_path, sha256),
            f"artifact-{artifact_identity[:32]}",
        )
        storage_mode = storage.get("storage_mode", "full")
        if storage_mode not in {"full", "chunked-v1"}:
            raise VerificationError(
                "queued artifact storage mode is invalid"
            )
        if (
            storage_mode == "chunked-v1"
            and (
                storage_ref["driver"] != RCLONE_OBJECT_STORE_DRIVER
                or re.fullmatch(
                    r"chunk-manifest-[0-9a-f]{64}",
                    storage_ref["object_id"],
                )
                is None
                or storage_ref["verification_level"]
                != "rclone-crypt-chunk-manifest-sha256"
            )
        ):
            raise VerificationError(
                "chunked artifacts require an exact rclone crypt manifest"
            )
        artifact = {
            # The path is part of identity so two logical outputs with the
            # same bytes may share one object without colliding in the
            # artifact authority ledger.
            "artifact_id": artifact_id,
            "role": "workspace-artifact",
            "logical_path": logical_path,
            "display_name": local.get("display_name"),
            "storage_mode": storage_mode,
            "sha256": sha256,
            "size": int(local.get("size")),
            "mime_type": local.get("mime_type"),
            "storage_ref": storage_ref,
        }
        assert_remote_safe(artifact)
        key = str(artifact["artifact_id"]) if preserve_replaced else logical_path
        merged[key] = artifact
    return [merged[key] for key in sorted(merged)]


def _roll_forward_memory_projection(
    state: RemoteTaskState,
    version: MutableMapping[str, Any],
    intent: Mapping[str, Any],
) -> tuple[str, bytes] | None:
    parent = state.memory_projection
    if parent is None:
        return None
    if not isinstance(parent, Mapping):
        raise VerificationError("parent memory projection is invalid")
    projection = strict_json_loads(
        json.dumps(parent, ensure_ascii=False, allow_nan=False)
    )
    if not isinstance(projection, dict):
        raise VerificationError("parent memory projection cannot be rolled forward")
    snapshot_id = str(version["snapshot_id"])
    transaction_id = str(version["transaction_id"])
    projection_id = (
        "proj-"
        + sha256_bytes(
            f"{version['task_id']}:{snapshot_id}:{transaction_id}".encode("utf-8")
        )[:40]
    )
    projection["projection_id"] = projection_id
    projection["basis"] = {
        "task_id": version["task_id"],
        "snapshot_id": snapshot_id,
        "generation": version["generation"],
        "transaction_id": transaction_id,
        "manifest_path": (
            f"tasks/{version['task_id']}/versions/{snapshot_id}.json"
        ),
        "source_current_precondition": {
            "current_blob_sha": state.current_blob_sha,
            "snapshot_id": state.current["snapshot_id"],
            "generation": state.current["generation"],
            "transaction_id": state.current["published_transaction_id"],
        },
    }
    # Reconciliation receipts describe only the transition that created their
    # projection. Audit history remains reachable through immutable parents.
    projection["reconciliation_receipts"] = []

    artifacts = {
        str(artifact["artifact_id"]): artifact
        for artifact in version["artifacts"]
        if isinstance(artifact, Mapping)
    }
    retained_authorities = [
        authority
        for authority in projection["artifact_authorities"]
        if (
            str(authority["artifact_id"]) in artifacts
            and artifacts[str(authority["artifact_id"])].get("sha256")
            == authority.get("sha256")
        )
    ]
    removed_authority = (
        len(retained_authorities) != len(projection["artifact_authorities"])
    )
    projection["artifact_authorities"] = retained_authorities
    classified = {str(item["artifact_id"]) for item in retained_authorities}
    unclassified = set(artifacts) - classified
    if removed_authority or unclassified:
        projection["completeness"]["overall"] = "partial"
        projection["completeness"]["artifacts"] = "partial"
        gap_id = (
            "gap-artifact-rollforward-"
            + sha256_bytes(
                f"{snapshot_id}:{transaction_id}".encode("utf-8")
            )[:24]
        )
        if (
            len(projection["known_gaps"]) < 64
            and not any(
                gap.get("gap_id") == gap_id
                for gap in projection["known_gaps"]
                if isinstance(gap, Mapping)
            )
        ):
            projection["known_gaps"].append(
                {
                    "gap_id": gap_id,
                    "area": "artifact",
                    "statement": (
                        "This successor contains new or replaced artifacts that "
                        "remain reference-only until a later projection explicitly "
                        "classifies and verifies their authority."
                    ),
                    "trace_status": "not_attempted",
                    "evidence": [],
                }
            )

    new_source = intent.get("_projection_new_evidence_source")
    new_messages = intent.get("_projection_new_messages")
    if not isinstance(new_source, Mapping) or not isinstance(new_messages, list):
        raise VerificationError(
            "projected successor lacks a bound durable visible-message delta"
        )
    references: list[Mapping[str, Any]] = []
    for message in new_messages:
        if (
            isinstance(message, Mapping)
            and isinstance(message.get("ordinal"), int)
            and isinstance(message.get("text"), str)
        ):
            references.append(
                {
                    "kind": "source_message",
                    "source_id": new_source["source_id"],
                    "revision_id": new_source["revision_id"],
                    "source_sequence": new_source["source_sequence"],
                    "revision_content_sha256": new_source["content_sha256"],
                    "message_ordinal": message["ordinal"],
                    "evidence_anchor_sha256": sha256_bytes(
                        message["text"].encode("utf-8")
                    ),
                }
            )
    if not references:
        raise VerificationError(
            "projected successor has no visible message evidence"
        )
    if len(references) > 32:
        raise VerificationError(
            "one projected message delta exceeds the exact evidence limit"
        )
    if len(projection["unprojected_deltas"]) >= 32:
        raise VerificationError(
            "projected successor requires semantic reconciliation before "
            "another message delta can be published"
        )
    delta_id = (
        "delta-"
        + sha256_bytes(
            (
                f"{new_source['source_id']}:{new_source['revision_id']}:"
                f"{snapshot_id}"
            ).encode("utf-8")
        )[:40]
    )
    entry_id = (
        "evidence-turn-"
        + sha256_bytes(
            (
                f"{new_source['source_id']}:"
                f"{new_source['revision_id']}"
            ).encode("utf-8")
        )[:32]
    )
    if len(projection["evidence_index"]) >= 128 and not any(
        entry.get("entry_id") == entry_id
        for entry in projection["evidence_index"]
        if isinstance(entry, Mapping)
    ):
        raise VerificationError(
            "projected successor evidence index requires semantic reconciliation"
        )
    projection["unprojected_deltas"].append(
        {
            "delta_id": delta_id,
            "status": "requires_semantic_reconciliation",
            "evidence_entry_id": entry_id,
            "message_evidence": references,
            "handling": (
                "read_newest_verified_messages_before_relying_on_prior_structured_state"
            ),
        }
    )
    projection["completeness"]["overall"] = "partial"
    reconciliation_basis_evidence = [
        dict(reference) for reference in references[:16]
    ]
    completeness_basis: dict[str, Mapping[str, Any]] = {}
    for dimension in (
        "goal_and_scope",
        "decisions",
        "rationales",
        "progress",
        "artifacts",
        "conflicts",
        "evidence",
    ):
        projection["completeness"][dimension] = "partial"
        completeness_basis[dimension] = {
            "status": "partial",
            "reason": UNPROJECTED_DELTA_COMPLETENESS_REASON,
            "evidence": reconciliation_basis_evidence,
        }
    # All seven dimensions deliberately become partial whenever an exact,
    # durable message delta is appended.  Replace the whole basis map so an
    # earlier artifact-only downgrade cannot leave a stale complete basis.
    projection["completeness_basis"] = completeness_basis
    if len(projection["evidence_index"]) < 128:
        if not any(
            entry.get("entry_id") == entry_id
            for entry in projection["evidence_index"]
            if isinstance(entry, Mapping)
        ):
            projection["evidence_index"].append(
                {
                    "entry_id": entry_id,
                    "topic": (
                        "Newest visible conversation delta requiring semantic "
                        "reconciliation before relying on prior structured state."
                    ),
                    "references": references,
                }
            )

    _validate_task_memory_projection_structure(projection)
    assert_remote_safe(projection)
    projection_bytes = pretty_json_bytes(projection)
    projection_path = (
        f"tasks/{version['task_id']}/projections/{projection_id}.json"
    )
    version["memory_projection"] = {
        "projection_id": projection_id,
        "path": projection_path,
        "content_sha256": sha256_bytes(projection_bytes),
    }
    return projection_path, projection_bytes


def _workspace_source_binding_document(
    intent: Mapping[str, Any],
    *,
    source_id: str,
) -> tuple[str, str, bytes | None]:
    task_id = validate_identifier(intent.get("task_id"), "task_id")
    source_id = validate_identifier(source_id, "source_id")
    identity_kind = intent.get("identity_kind")
    if identity_kind == "source":
        binding_id = validate_identifier(intent.get("binding_id"), "binding_id")
        return binding_id, f"bindings/confirmed/{binding_id}.json", None
    if identity_kind != "workspace":
        raise VerificationError(
            "projected successor source cannot receive confirmed evidence authority"
        )
    binding_id = validate_identifier(
        "bnd-evidence-"
        + sha256_bytes(f"{task_id}:{source_id}".encode("utf-8"))[:36],
        "evidence binding_id",
    )
    path = f"bindings/confirmed/{binding_id}.json"
    binding = {
        "schema_version": "binding/v1",
        "binding_id": binding_id,
        "subject": {"kind": "source", "id": source_id},
        "targets": [
            {
                "semantic_task_id": task_id,
                "relation": "source_for",
                "role": "supporting",
            }
        ],
        "effective_range": {
            "source_sequence_from": 0,
            "source_sequence_to": None,
        },
        "state": "confirmed",
        "confidence": "portable_identity_verified",
        "confirmation_basis": "portable_identity",
        "evidence": [
            {
                "evidence_id": (
                    "evidence-workspace-source-"
                    + sha256_bytes(
                        f"{task_id}:{source_id}:portable".encode("utf-8")
                    )[:28]
                ),
                "kind": "portable_identity",
                "strength": "authoritative",
            }
        ],
        "created_at": intent["created_at"],
        "created_by": {
            "actor_kind": "client",
            "actor_id": "memory-vault-sync",
        },
    }
    assert_remote_safe(binding)
    return binding_id, path, pretty_json_bytes(binding)


def _recorded_base_state(
    git: GitVault,
    latest: RemoteTaskState,
    intent: Mapping[str, Any],
) -> RemoteTaskState:
    """Reconstruct one exact session baseline for a coherent conflict candidate."""

    base = intent.get("base")
    if not isinstance(base, Mapping):
        raise VerificationError("queued task baseline is invalid")
    commit = validate_git_sha(base.get("remote_commit_sha"), "base commit")
    git.assert_commit_is_ancestor(commit)
    current_path = validate_repo_path(
        base.get("task_current_path"), "base CURRENT path"
    )
    if current_path != latest.current_path:
        raise VerificationError("queued task baseline CURRENT path changed")
    current_raw = git.show_bytes_at(commit, current_path)
    current_blob = git_blob_sha(current_raw)
    if current_blob != base.get("task_current_blob_sha"):
        raise VerificationError("queued task baseline CURRENT blob is invalid")
    try:
        current = strict_json_loads(current_raw.decode("utf-8"))
    except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
        raise VerificationError("queued task baseline CURRENT is invalid") from exc
    if not isinstance(current, Mapping):
        raise VerificationError("queued task baseline CURRENT is invalid")
    _validate_task_current(current)
    manifest_path = validate_repo_path(
        base.get("manifest_path"), "base manifest path"
    )
    manifest_raw = git.show_bytes_at(commit, manifest_path)
    if git.show_bytes(manifest_path) != manifest_raw:
        raise VerificationError(
            "queued task baseline manifest changed after its declared commit"
        )
    git.assert_immutable_path(manifest_path, manifest_raw)
    try:
        manifest = strict_json_loads(manifest_raw.decode("utf-8"))
    except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
        raise VerificationError("queued task baseline manifest is invalid") from exc
    if not isinstance(manifest, Mapping):
        raise VerificationError("queued task baseline manifest is invalid")
    _validate_task_version(manifest)
    recorded_manifest = intent.get("base_manifest")
    if (
        not isinstance(recorded_manifest, Mapping)
        or jcs_json_bytes(recorded_manifest) != jcs_json_bytes(manifest)
        or current.get("snapshot_id") != base.get("snapshot_id")
        or current.get("generation") != base.get("task_generation")
        or current.get("manifest_path") != manifest_path
        or manifest.get("snapshot_id") != base.get("snapshot_id")
        or manifest.get("generation") != base.get("task_generation")
        or manifest.get("transaction_id")
        != base.get("published_transaction_id")
    ):
        raise VerificationError("queued task baseline identity is inconsistent")
    projection_path: str | None = None
    projection: Mapping[str, Any] | None = None
    reference = manifest.get("memory_projection")
    if reference is not None:
        if not isinstance(reference, Mapping):
            raise VerificationError(
                "queued task baseline projection reference is invalid"
            )
        projection_path = validate_repo_path(
            reference.get("path"), "base memory projection path"
        )
        projection_raw = git.show_bytes_at(commit, projection_path)
        if (
            sha256_bytes(projection_raw) != reference.get("content_sha256")
            or git.show_bytes(projection_path) != projection_raw
        ):
            raise VerificationError(
                "queued task baseline projection is unavailable or was rewritten"
            )
        git.assert_immutable_path(projection_path, projection_raw)
        try:
            projection_value = strict_json_loads(
                projection_raw.decode("utf-8")
            )
        except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
            raise VerificationError(
                "queued task baseline projection is invalid"
            ) from exc
        if not isinstance(projection_value, Mapping):
            raise VerificationError(
                "queued task baseline projection is invalid"
            )
        projection_value = _projection_with_runtime_completeness_basis(
            projection_value
        )
        if projection_value.get("projection_id") != reference.get(
            "projection_id"
        ):
            raise VerificationError(
                "queued task baseline projection identity is invalid"
            )
        projection = projection_value
    return RemoteTaskState(
        commit_sha=commit,
        task_path=latest.task_path,
        task=latest.task,
        current_path=current_path,
        current_blob_sha=current_blob,
        current=current,
        manifest_path=manifest_path,
        manifest=manifest,
        memory_projection_path=projection_path,
        memory_projection=projection,
    )


def _version_documents(
    state: RemoteTaskState,
    intent: Mapping[str, Any],
    *,
    candidate: bool,
) -> tuple[
    str,
    bytes,
    str | None,
    bytes | None,
    str | None,
    bytes | None,
]:
    transaction_id = validate_identifier(
        intent.get("transaction_id"), "transaction_id"
    )
    task_id = state.current["task_id"]
    base = intent["base"]
    generation = int(base["task_generation"]) + 1
    snapshot_id = validate_identifier(intent.get("snapshot_id"), "snapshot_id")
    version_path = f"tasks/{task_id}/versions/{snapshot_id}.json"
    parent_manifest = intent.get("base_manifest")
    if not isinstance(parent_manifest, Mapping):
        parent_manifest = state.manifest
    artifacts = _merge_artifacts(
        parent_manifest,
        intent,
        preserve_replaced=state.memory_projection is not None,
    )
    if intent.get("artifacts") and state.task.get("content_artifacts_allowed") is False:
        raise PrivacyError("this coordination task does not accept content artifacts")
    parent = {
        "kind": "version_snapshot",
        "snapshot_id": base["snapshot_id"],
        "commit": base["remote_commit_sha"],
        "path": base["manifest_path"],
    }
    version: dict[str, Any] = {
        "schema_version": "task-version/v1",
        "snapshot_id": snapshot_id,
        "task_id": task_id,
        "generation": generation,
        "parents": [parent],
        "state": "candidate" if candidate else "published",
        "change_type": "artifact_update" if intent.get("artifacts") else "content_revision",
        "transaction_id": transaction_id,
        "continuation_readiness": (
            "partial"
            if state.memory_projection is not None
            else state.current.get("continuation_readiness", "partial")
        ),
        "artifacts": artifacts,
        "conversation_sources": list(intent.get("conversation_sources", [])),
        "coverage": {
            "artifacts": "catalogued" if artifacts else "not_catalogued",
            "conversation": "partial",
            "decisions": (
                parent_manifest.get("coverage", {}).get("decisions", "not_exported")
                if isinstance(parent_manifest.get("coverage"), Mapping)
                else "not_exported"
            ),
        },
    }
    inherited_evidence = parent_manifest.get("evidence_sources", [])
    durable_evidence: list[Mapping[str, Any]] = []
    if isinstance(inherited_evidence, list):
        durable_evidence.extend(
            dict(item) for item in inherited_evidence if isinstance(item, Mapping)
        )
    new_evidence = intent.get("_projection_new_evidence_source")
    if isinstance(new_evidence, Mapping):
        durable_evidence.append(dict(new_evidence))
    if durable_evidence:
        by_evidence_path = {
            str(item.get("content_path")): item
            for item in durable_evidence
            if isinstance(item.get("content_path"), str)
        }
        if len(by_evidence_path) > 256:
            raise VerificationError(
                "durable evidence source window exceeds the safety limit"
            )
        version["evidence_sources"] = list(by_evidence_path.values())
    for key in ("remaining_work", "open_questions", "observed_children"):
        if key in parent_manifest:
            version[key] = parent_manifest[key]
    if state.memory_projection is None and "memory_checkpoint" in parent_manifest:
        version["memory_checkpoint"] = parent_manifest["memory_checkpoint"]
    rolled_projection = _roll_forward_memory_projection(state, version, intent)
    assert_remote_safe(version)
    if candidate:
        return (
            version_path,
            pretty_json_bytes(version),
            None,
            None,
            rolled_projection[0] if rolled_projection else None,
            rolled_projection[1] if rolled_projection else None,
        )
    current = {
        "schema_version": "task-current/v1",
        "task_id": task_id,
        "generation": generation,
        "state": (
            state.current.get("state")
            if state.current.get("state") in {"active", "paused"}
            else "active"
        ),
        "snapshot_id": snapshot_id,
        "manifest_path": version_path,
        "continuation_readiness": version["continuation_readiness"],
        "published_transaction_id": transaction_id,
        "authority": {
            "strategy": "git-blob-sha-compare-and-swap",
            "timestamps_are_authoritative": False,
        },
    }
    assert_remote_safe(current)
    return (
        version_path,
        pretty_json_bytes(version),
        state.current_path,
        pretty_json_bytes(current),
        rolled_projection[0] if rolled_projection else None,
        rolled_projection[1] if rolled_projection else None,
    )


def _require_keys(
    value: Mapping[str, Any],
    *,
    required: set[str],
    allowed: set[str],
    label: str,
) -> None:
    keys = set(value)
    missing = required - keys
    extra = keys - allowed
    if missing or extra:
        raise VerificationError(
            f"{label} has invalid fields (missing={sorted(missing)}, extra={sorted(extra)})"
        )


def _validate_text_list(value: Any, label: str, *, maximum: int = 4000) -> None:
    if not isinstance(value, list):
        raise VerificationError(f"{label} must be an array")
    for item in value:
        if not isinstance(item, str) or not item or len(item) > maximum:
            raise VerificationError(f"{label} contains invalid text")
        scan_visible_text(item, label)


def _validate_task_current(value: Mapping[str, Any]) -> None:
    fields = {
        "schema_version",
        "task_id",
        "generation",
        "state",
        "snapshot_id",
        "manifest_path",
        "continuation_readiness",
        "published_transaction_id",
        "authority",
    }
    _require_keys(value, required=fields, allowed=fields, label="task CURRENT")
    if value.get("schema_version") != "task-current/v1":
        raise VerificationError("task CURRENT schema is invalid")
    task_id = validate_identifier(value.get("task_id"), "CURRENT.task_id")
    snapshot_id = validate_identifier(
        value.get("snapshot_id"), "CURRENT.snapshot_id"
    )
    validate_identifier(
        value.get("published_transaction_id"), "CURRENT.transaction_id"
    )
    if not isinstance(value.get("generation"), int) or int(value["generation"]) < 1:
        raise VerificationError("task CURRENT generation is invalid")
    if value.get("state") not in {"active", "paused", "archived", "candidate"}:
        raise VerificationError("task CURRENT state is invalid")
    if value.get("continuation_readiness") not in {"ready", "partial", "blocked"}:
        raise VerificationError("task CURRENT readiness is invalid")
    expected_path = f"tasks/{task_id}/versions/{snapshot_id}.json"
    if validate_repo_path(value.get("manifest_path"), "CURRENT.manifest_path") != expected_path:
        raise VerificationError("task CURRENT manifest path is inconsistent")
    authority = value.get("authority")
    if not isinstance(authority, Mapping):
        raise VerificationError("task CURRENT authority is invalid")
    _require_keys(
        authority,
        required={"strategy", "timestamps_are_authoritative"},
        allowed={"strategy", "timestamps_are_authoritative"},
        label="task CURRENT authority",
    )
    if (
        authority.get("strategy") != "git-blob-sha-compare-and-swap"
        or authority.get("timestamps_are_authoritative") is not False
    ):
        raise VerificationError("task CURRENT authority is invalid")


def _validate_artifact(value: Mapping[str, Any]) -> None:
    common_fields = {
        "artifact_id",
        "display_name",
        "logical_path",
        "mime_type",
        "role",
        "sha256",
        "size",
        "storage_mode",
    }
    legacy_fields = {"drive_file_id", "drive_parent_id"}
    generic_fields = {"storage_ref"}
    if "storage_ref" in value:
        _require_keys(
            value,
            required=common_fields | generic_fields,
            allowed=common_fields | generic_fields,
            label="artifact",
        )
        _validate_artifact_storage_ref(value.get("storage_ref"))
    else:
        _require_keys(
            value,
            required=common_fields | legacy_fields,
            allowed=common_fields | legacy_fields,
            label="artifact",
        )
    validate_identifier(value.get("artifact_id"), "artifact.artifact_id")
    validate_identifier(value.get("role"), "artifact.role")
    validate_sha256(value.get("sha256"), "artifact.sha256")
    display = value.get("display_name")
    if (
        not isinstance(display, str)
        or not display
        or len(display) > 255
        or any(character in display for character in "/\\\r\n")
    ):
        raise VerificationError("artifact display name is invalid")
    _scan_text_content(display, "artifact display name")
    if "storage_ref" not in value:
        for key in ("drive_file_id", "drive_parent_id"):
            if not isinstance(value.get(key), str) or not re.fullmatch(
                r"[A-Za-z0-9_-]{2,256}", str(value[key])
            ):
                raise VerificationError(f"artifact {key} is invalid")
    validate_repo_path(value.get("logical_path"), "artifact.logical_path")
    if not isinstance(value.get("mime_type"), str) or not re.fullmatch(
        r"[a-z0-9.+-]+/[a-z0-9.+-]+", str(value["mime_type"])
    ):
        raise VerificationError("artifact MIME type is invalid")
    if not isinstance(value.get("size"), int) or int(value["size"]) < 1:
        raise VerificationError("artifact size is invalid")
    storage_mode = value.get("storage_mode")
    if storage_mode not in {"full", "chunked-v1"}:
        raise VerificationError("artifact storage mode is invalid")
    if storage_mode == "chunked-v1":
        if int(value["size"]) > CHUNK_SIZE_BYTES * MAX_CHUNK_COUNT:
            raise VerificationError("chunked artifact exceeds the size bound")
        storage_ref = _artifact_storage_ref(value)
        if (
            storage_ref["driver"] != RCLONE_OBJECT_STORE_DRIVER
            or re.fullmatch(
                r"chunk-manifest-[0-9a-f]{64}",
                storage_ref["object_id"],
            )
            is None
            or storage_ref["verification_level"]
            != "rclone-crypt-chunk-manifest-sha256"
        ):
            raise VerificationError(
                "chunked artifact needs a verified encrypted manifest"
            )


def _validate_task_version(value: Mapping[str, Any]) -> None:
    required = {
        "schema_version",
        "task_id",
        "snapshot_id",
        "generation",
        "state",
        "transaction_id",
        "change_type",
        "continuation_readiness",
        "parents",
        "artifacts",
    }
    allowed = required | {
        "conversation_sources",
        "evidence_sources",
        "memory_checkpoint",
        "remaining_work",
        "open_questions",
        "coverage",
        "verification",
        "observed_children",
        "memory_projection",
    }
    _require_keys(
        value, required=required, allowed=allowed, label="task version"
    )
    if value.get("schema_version") != "task-version/v1":
        raise VerificationError("task version schema is invalid")
    task_id = validate_identifier(value.get("task_id"), "version.task_id")
    validate_identifier(value.get("snapshot_id"), "version.snapshot_id")
    validate_identifier(value.get("transaction_id"), "version.transaction_id")
    if not isinstance(value.get("generation"), int) or int(value["generation"]) < 1:
        raise VerificationError("task version generation is invalid")
    if value.get("state") not in {
        "published",
        "candidate",
        "rejected",
        "superseded",
    }:
        raise VerificationError("task version state is invalid")
    if value.get("change_type") not in {
        "control_plane_rewrite",
        "metadata_import",
        "content_revision",
        "artifact_update",
        "merge",
        "fork",
        "rollback",
        "structural_event",
    }:
        raise VerificationError("task version change type is invalid")
    if value.get("continuation_readiness") not in {"ready", "partial", "blocked"}:
        raise VerificationError("task version readiness is invalid")
    parents = value.get("parents")
    if not isinstance(parents, list):
        raise VerificationError("task version parents are invalid")
    for parent in parents:
        if not isinstance(parent, Mapping):
            raise VerificationError("task version parent is invalid")
        fields = {"kind", "snapshot_id", "commit", "path"}
        _require_keys(parent, required=fields, allowed=fields, label="version parent")
        if parent.get("kind") not in {
            "legacy_snapshot",
            "version_snapshot",
            "fork_baseline",
            "merge_parent",
            "rollback_target",
        }:
            raise VerificationError("task version parent kind is invalid")
        parent_snapshot = validate_identifier(
            parent.get("snapshot_id"), "parent.snapshot_id"
        )
        validate_git_sha(parent.get("commit"), "parent.commit")
        expected_prefix = f"tasks/{task_id}/versions/"
        parent_path = validate_repo_path(parent.get("path"), "parent.path")
        if not parent_path.startswith(expected_prefix):
            raise VerificationError("task version parent path is inconsistent")
        if (
            parent.get("kind") != "legacy_snapshot"
            and PurePosixPath(parent_path).stem != parent_snapshot
        ):
            raise VerificationError("task version parent snapshot is inconsistent")
    artifacts = value.get("artifacts")
    if not isinstance(artifacts, list):
        raise VerificationError("task version artifacts are invalid")
    for artifact in artifacts:
        if not isinstance(artifact, Mapping):
            raise VerificationError("task version artifact is invalid")
        _validate_artifact(artifact)
    references = value.get("conversation_sources", [])
    if not isinstance(references, list) or len(references) > 8:
        raise VerificationError("conversation source references are invalid")
    paths: set[str] = set()
    for reference in references:
        if not isinstance(reference, Mapping):
            raise VerificationError("conversation source reference is invalid")
        fields = {
            "source_id",
            "revision_id",
            "content_path",
            "content_sha256",
        }
        _require_keys(
            reference,
            required=fields,
            allowed=fields,
            label="conversation source reference",
        )
        source_id = validate_identifier(reference.get("source_id"), "source_id")
        revision_id = validate_identifier(
            reference.get("revision_id"), "revision_id"
        )
        path = validate_repo_path(
            reference.get("content_path"), "conversation content path"
        )
        if path != f"sources/{source_id}/revisions/{revision_id}.json":
            raise VerificationError("conversation source reference is inconsistent")
        validate_sha256(reference.get("content_sha256"), "conversation content hash")
        if path in paths:
            raise VerificationError("conversation source reference is duplicated")
        paths.add(path)
    evidence_sources = value.get("evidence_sources", [])
    if not isinstance(evidence_sources, list) or len(evidence_sources) > 256:
        raise VerificationError("durable evidence source references are invalid")
    evidence_paths: set[str] = set()
    for reference in evidence_sources:
        if not isinstance(reference, Mapping):
            raise VerificationError("durable evidence source reference is invalid")
        fields = {
            "source_id",
            "revision_id",
            "source_sequence",
            "binding_id",
            "content_path",
            "content_sha256",
        }
        _require_keys(
            reference,
            required=fields,
            allowed=fields,
            label="durable evidence source reference",
        )
        source_id = validate_identifier(reference.get("source_id"), "source_id")
        revision_id = validate_identifier(
            reference.get("revision_id"), "revision_id"
        )
        sequence = reference.get("source_sequence")
        if (
            not isinstance(sequence, int)
            or isinstance(sequence, bool)
            or sequence < 0
        ):
            raise VerificationError(
                "durable evidence source sequence is invalid"
            )
        validate_identifier(
            reference.get("binding_id"),
            "durable evidence source binding_id",
        )
        path = validate_repo_path(
            reference.get("content_path"),
            "durable evidence source content path",
        )
        if path != f"sources/{source_id}/revisions/{revision_id}.json":
            raise VerificationError(
                "durable evidence source reference is inconsistent"
            )
        validate_sha256(
            reference.get("content_sha256"),
            "durable evidence source content hash",
        )
        if path in evidence_paths:
            raise VerificationError(
                "durable evidence source reference is duplicated"
            )
        evidence_paths.add(path)
    for key in ("remaining_work", "open_questions"):
        if key in value:
            _validate_text_list(value[key], f"version.{key}")
    if "memory_checkpoint" in value and value["memory_checkpoint"] is not None:
        path = validate_repo_path(value["memory_checkpoint"], "memory checkpoint")
        if not path.startswith("memory/checkpoints/"):
            raise VerificationError("memory checkpoint path is invalid")
    if (
        "memory_projection" in value
        and value["memory_projection"] is not None
    ):
        reference = value["memory_projection"]
        if not isinstance(reference, Mapping):
            raise VerificationError("task memory projection reference is invalid")
        fields = {"projection_id", "path", "content_sha256"}
        _require_keys(
            reference,
            required=fields,
            allowed=fields,
            label="task memory projection reference",
        )
        projection_id = validate_identifier(
            reference.get("projection_id"),
            "memory_projection.projection_id",
        )
        expected_path = (
            f"tasks/{task_id}/projections/{projection_id}.json"
        )
        projection_path = validate_repo_path(
            reference.get("path"),
            "memory_projection.path",
        )
        if projection_path != expected_path:
            raise VerificationError(
                "task memory projection path is inconsistent"
            )
        validate_sha256(
            reference.get("content_sha256"),
            "memory_projection.content_sha256",
        )
    if "coverage" in value:
        coverage = value["coverage"]
        if not isinstance(coverage, Mapping):
            raise VerificationError("task version coverage is invalid")
        fields = {"artifacts", "conversation", "decisions"}
        _require_keys(coverage, required=fields, allowed=fields, label="coverage")
        if coverage.get("artifacts") not in {
            "not_catalogued",
            "partial",
            "catalogued",
            "complete",
        }:
            raise VerificationError("artifact coverage is invalid")
        if coverage.get("conversation") not in {
            "not_exported",
            "partial",
            "complete",
        } or coverage.get("decisions") not in {
            "not_exported",
            "partial",
            "complete",
        }:
            raise VerificationError("task version coverage is invalid")
    if "verification" in value:
        verification = value["verification"]
        if not isinstance(verification, Mapping):
            raise VerificationError("version verification is invalid")
        fields = {"level", "remote_content_checksum"}
        _require_keys(
            verification,
            required=fields,
            allowed=fields,
            label="version verification",
        )
        validate_identifier(verification.get("level"), "verification.level")
        checksum = verification.get("remote_content_checksum")
        if checksum != "not_exposed_by_connector":
            validate_sha256(checksum, "verification checksum")
    if "observed_children" in value:
        children = value["observed_children"]
        if not isinstance(children, list) or not children:
            raise VerificationError("observed children are invalid")
        for child in children:
            if not isinstance(child, Mapping):
                raise VerificationError("observed child is invalid")
            fields = {"task_id", "snapshot_id", "authority"}
            _require_keys(
                child, required=fields, allowed=fields, label="observed child"
            )
            validate_identifier(child.get("task_id"), "child.task_id")
            validate_identifier(child.get("snapshot_id"), "child.snapshot_id")
            if child.get("authority") != "observation_only":
                raise VerificationError("observed child authority is invalid")


def _projection_object(
    value: Any,
    fields: set[str],
    label: str,
) -> Mapping[str, Any]:
    if not isinstance(value, Mapping):
        raise VerificationError(f"{label} must be an object")
    _require_keys(value, required=fields, allowed=fields, label=label)
    return value


def _projection_text(value: Any, label: str) -> str:
    if not isinstance(value, str) or not value or len(value) > 4000:
        raise VerificationError(f"{label} is invalid")
    if any(
        ord(character) < 32 and character not in "\t\n\r"
        or ord(character) == 127
        for character in value
    ):
        raise VerificationError(f"{label} contains a control character")
    return scan_visible_text(value, label)


def _projection_unique_items(
    value: Any,
    label: str,
    *,
    maximum: int,
    minimum: int = 0,
) -> list[Any]:
    if (
        not isinstance(value, list)
        or len(value) < minimum
        or len(value) > maximum
    ):
        raise VerificationError(f"{label} has an invalid item count")
    seen: set[bytes] = set()
    for item in value:
        canonical = jcs_json_bytes(item)
        if canonical in seen:
            raise VerificationError(f"{label} contains a duplicate item")
        seen.add(canonical)
    return value


def _projection_id_list(
    value: Any,
    label: str,
    *,
    maximum: int,
    minimum: int = 0,
) -> list[str]:
    result = _projection_unique_items(
        value,
        label,
        maximum=maximum,
        minimum=minimum,
    )
    return [
        validate_identifier(item, f"{label} item")
        for item in result
    ]


def _validate_projection_evidence_ref(
    value: Any,
    label: str,
) -> Mapping[str, Any]:
    if not isinstance(value, Mapping):
        raise VerificationError(f"{label} must be an evidence object")
    kind = value.get("kind")
    if kind == "memory_event":
        fields = {"kind", "memory_event_id", "event_sha256"}
        _projection_object(value, fields, label)
        validate_identifier(value.get("memory_event_id"), f"{label}.memory_event_id")
        validate_sha256(value.get("event_sha256"), f"{label}.event_sha256")
    elif kind == "source_message":
        fields = {
            "kind",
            "source_id",
            "revision_id",
            "source_sequence",
            "revision_content_sha256",
            "message_ordinal",
            "evidence_anchor_sha256",
        }
        _projection_object(value, fields, label)
        validate_identifier(value.get("source_id"), f"{label}.source_id")
        validate_identifier(value.get("revision_id"), f"{label}.revision_id")
        for field in ("source_sequence", "message_ordinal"):
            number = value.get(field)
            if (
                not isinstance(number, int)
                or isinstance(number, bool)
                or number < 0
            ):
                raise VerificationError(f"{label}.{field} is invalid")
        validate_sha256(
            value.get("revision_content_sha256"),
            f"{label}.revision_content_sha256",
        )
        validate_sha256(
            value.get("evidence_anchor_sha256"),
            f"{label}.evidence_anchor_sha256",
        )
    elif kind == "artifact":
        fields = {"kind", "artifact_id", "sha256"}
        _projection_object(value, fields, label)
        validate_identifier(value.get("artifact_id"), f"{label}.artifact_id")
        validate_sha256(value.get("sha256"), f"{label}.sha256")
    else:
        raise VerificationError(f"{label} has an unsupported evidence kind")
    return value


def _validate_projection_evidence(
    value: Any,
    label: str,
    *,
    required: bool,
) -> list[Mapping[str, Any]]:
    items = _projection_unique_items(
        value,
        label,
        minimum=1 if required else 0,
        maximum=16,
    )
    return [
        _validate_projection_evidence_ref(item, f"{label}[{index}]")
        for index, item in enumerate(items)
    ]


def _validate_projection_rationale(
    value: Any,
    label: str,
) -> None:
    if not isinstance(value, Mapping):
        raise VerificationError(f"{label} is invalid")
    if value.get("status") == "known":
        fields = {"status", "statement", "evidence"}
        _projection_object(value, fields, label)
        _projection_text(value.get("statement"), f"{label}.statement")
        _validate_projection_evidence(
            value.get("evidence"),
            f"{label}.evidence",
            required=True,
        )
    elif value.get("status") == "not_recovered":
        fields = {"status", "gap_id", "evidence"}
        _projection_object(value, fields, label)
        validate_identifier(value.get("gap_id"), f"{label}.gap_id")
        _validate_projection_evidence(
            value.get("evidence"),
            f"{label}.evidence",
            required=False,
        )
    else:
        raise VerificationError(f"{label} has an invalid status")


def _validate_task_memory_projection_structure(
    value: Mapping[str, Any],
) -> None:
    fields = {
        "schema_version",
        "projection_id",
        "authority",
        "basis",
        "completeness",
        "completeness_basis",
        "current_goal",
        "scope_boundaries",
        "unprojected_deltas",
        "reconciliation_receipts",
        "effective_claims",
        "contested_claims",
        "superseded_claims",
        "rejected_options",
        "artifact_authorities",
        "unclassified_artifact_policy",
        "completed",
        "in_progress",
        "next_actions",
        "open_questions",
        "risks",
        "blocking_conflicts",
        "nonblocking_contradictions",
        "known_gaps",
        "evidence_index",
        "trace_policy",
    }
    if not isinstance(value, Mapping):
        raise VerificationError("task memory projection must be an object")
    _require_keys(
        value,
        required=fields - {"completeness_basis"},
        allowed=fields,
        label="task memory projection",
    )
    if value.get("schema_version") != "task-memory-projection/v1":
        raise VerificationError("task memory projection schema is invalid")
    validate_identifier(value.get("projection_id"), "projection.projection_id")
    if value.get("authority") != "rebuildable_task_handoff_cache":
        raise VerificationError("task memory projection authority is invalid")

    basis_fields = {
        "task_id",
        "snapshot_id",
        "generation",
        "transaction_id",
        "manifest_path",
        "source_current_precondition",
    }
    basis = _projection_object(value.get("basis"), basis_fields, "projection.basis")
    validate_identifier(basis.get("task_id"), "projection.basis.task_id")
    validate_identifier(basis.get("snapshot_id"), "projection.basis.snapshot_id")
    validate_identifier(
        basis.get("transaction_id"),
        "projection.basis.transaction_id",
    )
    if (
        not isinstance(basis.get("generation"), int)
        or isinstance(basis.get("generation"), bool)
        or int(basis["generation"]) < 1
    ):
        raise VerificationError("projection basis generation is invalid")
    validate_repo_path(basis.get("manifest_path"), "projection.basis.manifest_path")
    precondition = basis.get("source_current_precondition")
    if precondition is not None:
        precondition_fields = {
            "current_blob_sha",
            "snapshot_id",
            "generation",
            "transaction_id",
        }
        precondition = _projection_object(
            precondition,
            precondition_fields,
            "projection source CURRENT precondition",
        )
        validate_git_sha(
            precondition.get("current_blob_sha"),
            "projection precondition CURRENT blob",
        )
        validate_identifier(
            precondition.get("snapshot_id"),
            "projection precondition snapshot",
        )
        validate_identifier(
            precondition.get("transaction_id"),
            "projection precondition transaction",
        )
        if (
            not isinstance(precondition.get("generation"), int)
            or isinstance(precondition.get("generation"), bool)
            or int(precondition["generation"]) < 1
        ):
            raise VerificationError("projection precondition generation is invalid")

    completeness_fields = {
        "overall",
        "goal_and_scope",
        "decisions",
        "rationales",
        "progress",
        "artifacts",
        "conflicts",
        "evidence",
    }
    completeness = _projection_object(
        value.get("completeness"),
        completeness_fields,
        "projection.completeness",
    )
    if completeness.get("overall") not in {"complete", "partial"}:
        raise VerificationError("projection completeness overall is invalid")
    for key in completeness_fields - {"overall"}:
        if completeness.get(key) not in {"complete", "partial", "unknown"}:
            raise VerificationError(
                f"projection completeness {key} is invalid"
            )
    basis_dimensions = completeness_fields - {"overall"}
    completeness_basis = value.get("completeness_basis")
    if completeness_basis is not None:
        completeness_basis = _projection_object(
            completeness_basis,
            basis_dimensions,
            "projection.completeness_basis",
        )
        for dimension in sorted(basis_dimensions):
            entry = _projection_object(
                completeness_basis.get(dimension),
                {"status", "reason", "evidence"},
                f"projection.completeness_basis.{dimension}",
            )
            if entry.get("status") != completeness.get(dimension):
                raise VerificationError(
                    "projection completeness basis status is inconsistent"
                )
            _projection_text(
                entry.get("reason"),
                f"projection.completeness_basis.{dimension}.reason",
            )
            _validate_projection_evidence(
                entry.get("evidence"),
                f"projection.completeness_basis.{dimension}.evidence",
                required=entry.get("status") == "complete",
            )

    goal = value.get("current_goal")
    if not isinstance(goal, Mapping):
        raise VerificationError("projection current goal is invalid")
    if goal.get("status") == "active":
        fields_for_goal = {"status", "statement", "evidence"}
        _projection_object(goal, fields_for_goal, "projection.current_goal")
        _projection_text(goal.get("statement"), "projection.current_goal.statement")
        _validate_projection_evidence(
            goal.get("evidence"),
            "projection.current_goal.evidence",
            required=True,
        )
    elif goal.get("status") == "unknown":
        fields_for_goal = {"status", "reason", "evidence"}
        _projection_object(goal, fields_for_goal, "projection.current_goal")
        _projection_text(goal.get("reason"), "projection.current_goal.reason")
        _validate_projection_evidence(
            goal.get("evidence"),
            "projection.current_goal.evidence",
            required=False,
        )
    else:
        raise VerificationError("projection current goal status is invalid")

    scope = _projection_object(
        value.get("scope_boundaries"),
        {"in_scope", "out_of_scope"},
        "projection.scope_boundaries",
    )
    for direction in ("in_scope", "out_of_scope"):
        boundaries = _projection_unique_items(
            scope.get(direction),
            f"projection.scope_boundaries.{direction}",
            maximum=128,
        )
        for index, boundary in enumerate(boundaries):
            label = f"projection.scope_boundaries.{direction}[{index}]"
            boundary = _projection_object(
                boundary,
                {"boundary_id", "statement", "evidence"},
                label,
            )
            validate_identifier(boundary.get("boundary_id"), f"{label}.boundary_id")
            _projection_text(boundary.get("statement"), f"{label}.statement")
            _validate_projection_evidence(
                boundary.get("evidence"),
                f"{label}.evidence",
                required=True,
            )

    deltas = _projection_unique_items(
        value.get("unprojected_deltas"),
        "projection.unprojected_deltas",
        maximum=32,
    )
    delta_ids: set[str] = set()
    for index, delta in enumerate(deltas):
        label = f"projection.unprojected_deltas[{index}]"
        delta = _projection_object(
            delta,
            {
                "delta_id",
                "status",
                "evidence_entry_id",
                "message_evidence",
                "handling",
            },
            label,
        )
        delta_id = validate_identifier(
            delta.get("delta_id"), f"{label}.delta_id"
        )
        if delta_id in delta_ids:
            raise VerificationError(
                "projection unprojected delta ID is duplicated"
            )
        delta_ids.add(delta_id)
        validate_identifier(
            delta.get("evidence_entry_id"),
            f"{label}.evidence_entry_id",
        )
        if delta.get("status") != "requires_semantic_reconciliation":
            raise VerificationError(f"{label}.status is invalid")
        message_evidence = _projection_unique_items(
            delta.get("message_evidence"),
            f"{label}.message_evidence",
            minimum=1,
            maximum=32,
        )
        for evidence_index, evidence in enumerate(message_evidence):
            verified = _validate_projection_evidence_ref(
                evidence,
                f"{label}.message_evidence[{evidence_index}]",
            )
            if verified.get("kind") != "source_message":
                raise VerificationError(
                    f"{label}.message_evidence must contain source messages"
                )
        if (
            delta.get("handling")
            != "read_newest_verified_messages_before_relying_on_prior_structured_state"
        ):
            raise VerificationError(f"{label}.handling is invalid")

    receipt_result_kinds = {
        "current_goal",
        "scope_boundary",
        "effective_claim",
        "contested_claim",
        "superseded_claim",
        "rejected_option",
        "artifact_authority",
        "completed_item",
        "in_progress_item",
        "next_action",
        "open_question",
        "risk",
        "blocking_conflict",
        "nonblocking_contradiction",
        "known_gap",
        "evidence_index_entry",
        "completeness",
    }
    receipts = _projection_unique_items(
        value.get("reconciliation_receipts"),
        "projection.reconciliation_receipts",
        maximum=32,
    )
    receipt_ids: set[str] = set()
    for index, receipt in enumerate(receipts):
        label = f"projection.reconciliation_receipts[{index}]"
        receipt_fields = {
            "receipt_id",
            "source_projection_id",
            "resolved_delta_ids",
            "message_evidence",
            "outcome",
            "outcome_rationale",
            "result_refs",
            "retired_refs",
            "retirement_message_evidence",
            "completeness_transitions",
            "evidence_entry_ids",
            "status",
        }
        _require_keys(
            receipt,
            required=receipt_fields - {"completeness_transitions"},
            allowed=receipt_fields,
            label=label,
        )
        receipt_id = validate_identifier(
            receipt.get("receipt_id"), f"{label}.receipt_id"
        )
        if receipt_id in receipt_ids:
            raise VerificationError(
                "projection reconciliation receipt ID is duplicated"
            )
        receipt_ids.add(receipt_id)
        validate_identifier(
            receipt.get("source_projection_id"),
            f"{label}.source_projection_id",
        )
        _projection_id_list(
            receipt.get("resolved_delta_ids"),
            f"{label}.resolved_delta_ids",
            minimum=1,
            maximum=32,
        )
        message_evidence = _projection_unique_items(
            receipt.get("message_evidence"),
            f"{label}.message_evidence",
            minimum=1,
            maximum=256,
        )
        for evidence_index, evidence in enumerate(message_evidence):
            verified = _validate_projection_evidence_ref(
                evidence,
                f"{label}.message_evidence[{evidence_index}]",
            )
            if verified.get("kind") != "source_message":
                raise VerificationError(
                    f"{label}.message_evidence must contain source messages"
                )
        if receipt.get("outcome") not in {
            "state_updated",
            "evidence_only_no_semantic_change",
        }:
            raise VerificationError(f"{label}.outcome is invalid")
        _projection_text(
            receipt.get("outcome_rationale"),
            f"{label}.outcome_rationale",
        )
        result_refs = _projection_unique_items(
            receipt.get("result_refs"),
            f"{label}.result_refs",
            minimum=1,
            maximum=256,
        )
        for result_index, result in enumerate(result_refs):
            result_label = f"{label}.result_refs[{result_index}]"
            result = _projection_object(
                result,
                {"kind", "id"},
                result_label,
            )
            if result.get("kind") not in receipt_result_kinds:
                raise VerificationError(f"{result_label}.kind is invalid")
            result_id = validate_identifier(
                result.get("id"), f"{result_label}.id"
            )
            if result.get("kind") == "current_goal" and result_id != "current_goal":
                raise VerificationError(
                    f"{result_label}.id must be current_goal"
                )
            if (
                result.get("kind") == "completeness"
                and result_id not in (completeness_fields - {"overall"})
            ):
                raise VerificationError(
                    f"{result_label}.id is not a completeness dimension"
                )
        transitions = _projection_unique_items(
            receipt.get("completeness_transitions", []),
            f"{label}.completeness_transitions",
            maximum=8,
        )
        transition_dimensions: set[str] = set()
        for transition_index, transition in enumerate(transitions):
            transition_label = (
                f"{label}.completeness_transitions[{transition_index}]"
            )
            transition = _projection_object(
                transition,
                {
                    "dimension",
                    "before",
                    "after",
                    "change_kind",
                    "before_basis_sha256",
                    "after_basis_sha256",
                    "reason",
                    "evidence",
                },
                transition_label,
            )
            dimension = str(transition.get("dimension"))
            if (
                dimension not in (completeness_fields - {"overall"})
                or dimension in transition_dimensions
            ):
                raise VerificationError(
                    f"{transition_label}.dimension is invalid"
                )
            transition_dimensions.add(dimension)
            valid_statuses = {"complete", "partial", "unknown"}
            if (
                transition.get("before") not in valid_statuses
                or transition.get("after") not in valid_statuses
            ):
                raise VerificationError(
                    f"{transition_label} status transition is invalid"
                )
            change_kind = transition.get("change_kind")
            if (
                change_kind == "status_changed"
                and transition.get("before") == transition.get("after")
            ) or (
                change_kind == "basis_refreshed"
                and transition.get("before") != transition.get("after")
            ) or change_kind not in {
                "status_changed",
                "basis_refreshed",
            }:
                raise VerificationError(
                    f"{transition_label}.change_kind is invalid"
                )
            before_basis_sha256 = validate_sha256(
                transition.get("before_basis_sha256"),
                f"{transition_label}.before_basis_sha256",
            )
            after_basis_sha256 = validate_sha256(
                transition.get("after_basis_sha256"),
                f"{transition_label}.after_basis_sha256",
            )
            if before_basis_sha256 == after_basis_sha256:
                raise VerificationError(
                    f"{transition_label} basis hash did not change"
                )
            _projection_text(
                transition.get("reason"),
                f"{transition_label}.reason",
            )
            evidence = _validate_projection_evidence(
                transition.get("evidence"),
                f"{transition_label}.evidence",
                required=True,
            )
            if not any(
                item.get("kind") == "source_message"
                for item in evidence
            ):
                raise VerificationError(
                    f"{transition_label}.evidence lacks an exact source message"
                )
        completeness_result_ids = {
            str(result["id"])
            for result in result_refs
            if result["kind"] == "completeness"
        }
        if completeness_result_ids != transition_dimensions:
            raise VerificationError(
                f"{label} completeness results and transitions differ"
            )
        retired_refs = _projection_unique_items(
            receipt.get("retired_refs"),
            f"{label}.retired_refs",
            maximum=256,
        )
        for retired_index, retired in enumerate(retired_refs):
            retired_label = f"{label}.retired_refs[{retired_index}]"
            retired = _projection_object(
                retired,
                {"kind", "id"},
                retired_label,
            )
            if retired.get("kind") not in (
                receipt_result_kinds
                - {"current_goal", "evidence_index_entry"}
            ):
                raise VerificationError(f"{retired_label}.kind is invalid")
            validate_identifier(retired.get("id"), f"{retired_label}.id")
        retirement_evidence = _projection_unique_items(
            receipt.get("retirement_message_evidence"),
            f"{label}.retirement_message_evidence",
            maximum=256,
        )
        for evidence_index, evidence in enumerate(retirement_evidence):
            verified = _validate_projection_evidence_ref(
                evidence,
                f"{label}.retirement_message_evidence[{evidence_index}]",
            )
            if verified.get("kind") != "source_message":
                raise VerificationError(
                    f"{label}.retirement_message_evidence must contain "
                    "source messages"
                )
        _projection_id_list(
            receipt.get("evidence_entry_ids"),
            f"{label}.evidence_entry_ids",
            minimum=1,
            maximum=128,
        )
        if receipt.get("status") != "semantically_reconciled":
            raise VerificationError(f"{label}.status is invalid")

    claim_kinds = {
        "decision",
        "constraint",
        "user_preference",
        "factual_state",
        "scope_boundary",
        "artifact_selection",
    }
    effective = _projection_unique_items(
        value.get("effective_claims"),
        "projection.effective_claims",
        maximum=128,
    )
    for index, claim in enumerate(effective):
        label = f"projection.effective_claims[{index}]"
        claim = _projection_object(
            claim,
            {
                "claim_id",
                "claim_key",
                "kind",
                "statement",
                "rationale",
                "settled",
                "superseded_claim_ids",
                "reask_policy",
                "evidence",
            },
            label,
        )
        validate_identifier(claim.get("claim_id"), f"{label}.claim_id")
        validate_identifier(claim.get("claim_key"), f"{label}.claim_key")
        if claim.get("kind") not in claim_kinds:
            raise VerificationError(f"{label}.kind is invalid")
        _projection_text(claim.get("statement"), f"{label}.statement")
        _validate_projection_rationale(claim.get("rationale"), f"{label}.rationale")
        if claim.get("settled") is not True:
            raise VerificationError(f"{label}.settled must be true")
        _projection_id_list(
            claim.get("superseded_claim_ids"),
            f"{label}.superseded_claim_ids",
            maximum=128,
        )
        if claim.get("reask_policy") not in {
            "do_not_reask",
            "reask_only_on_blocking_conflict",
            "reask_only_if_user_explicitly_reopens",
            "reask_on_blocking_conflict_or_explicit_reopen",
        }:
            raise VerificationError(f"{label}.reask_policy is invalid")
        _validate_projection_evidence(
            claim.get("evidence"),
            f"{label}.evidence",
            required=True,
        )

    superseded = _projection_unique_items(
        value.get("superseded_claims"),
        "projection.superseded_claims",
        maximum=256,
    )
    for index, claim in enumerate(superseded):
        label = f"projection.superseded_claims[{index}]"
        claim = _projection_object(
            claim,
            {
                "claim_id",
                "claim_key",
                "kind",
                "statement",
                "rationale",
                "superseded_by_claim_id",
                "evidence",
            },
            label,
        )
        for key in ("claim_id", "claim_key", "superseded_by_claim_id"):
            validate_identifier(claim.get(key), f"{label}.{key}")
        if claim.get("kind") not in claim_kinds:
            raise VerificationError(f"{label}.kind is invalid")
        _projection_text(claim.get("statement"), f"{label}.statement")
        _validate_projection_rationale(claim.get("rationale"), f"{label}.rationale")
        _validate_projection_evidence(
            claim.get("evidence"),
            f"{label}.evidence",
            required=True,
        )

    contested = _projection_unique_items(
        value.get("contested_claims"),
        "projection.contested_claims",
        maximum=128,
    )
    for index, claim in enumerate(contested):
        label = f"projection.contested_claims[{index}]"
        claim = _projection_object(
            claim,
            {
                "claim_id",
                "claim_key",
                "kind",
                "statement",
                "rationale",
                "settled",
                "evidence",
            },
            label,
        )
        validate_identifier(claim.get("claim_id"), f"{label}.claim_id")
        validate_identifier(claim.get("claim_key"), f"{label}.claim_key")
        if claim.get("kind") not in claim_kinds:
            raise VerificationError(f"{label}.kind is invalid")
        _projection_text(claim.get("statement"), f"{label}.statement")
        _validate_projection_rationale(
            claim.get("rationale"),
            f"{label}.rationale",
        )
        if claim.get("settled") is not False:
            raise VerificationError(f"{label}.settled must be false")
        _validate_projection_evidence(
            claim.get("evidence"),
            f"{label}.evidence",
            required=True,
        )

    rejected = _projection_unique_items(
        value.get("rejected_options"),
        "projection.rejected_options",
        maximum=128,
    )
    for index, option in enumerate(rejected):
        label = f"projection.rejected_options[{index}]"
        option = _projection_object(
            option,
            {
                "option_id",
                "claim_key",
                "statement",
                "rejection_rationale",
                "evidence",
            },
            label,
        )
        validate_identifier(option.get("option_id"), f"{label}.option_id")
        validate_identifier(option.get("claim_key"), f"{label}.claim_key")
        _projection_text(option.get("statement"), f"{label}.statement")
        rejection = _projection_object(
            option.get("rejection_rationale"),
            {"statement", "evidence"},
            f"{label}.rejection_rationale",
        )
        _projection_text(
            rejection.get("statement"),
            f"{label}.rejection_rationale.statement",
        )
        _validate_projection_evidence(
            rejection.get("evidence"),
            f"{label}.rejection_rationale.evidence",
            required=True,
        )
        _validate_projection_evidence(
            option.get("evidence"),
            f"{label}.evidence",
            required=True,
        )

    authorities = _projection_unique_items(
        value.get("artifact_authorities"),
        "projection.artifact_authorities",
        maximum=512,
    )
    for index, authority in enumerate(authorities):
        label = f"projection.artifact_authorities[{index}]"
        authority = _projection_object(
            authority,
            {
                "artifact_id",
                "sha256",
                "purpose",
                "role",
                "authority_status",
                "source_snapshot_id",
                "dependencies",
                "verification",
                "relations",
            },
            label,
        )
        validate_identifier(authority.get("artifact_id"), f"{label}.artifact_id")
        validate_sha256(authority.get("sha256"), f"{label}.sha256")
        _projection_text(authority.get("purpose"), f"{label}.purpose")
        validate_identifier(authority.get("role"), f"{label}.role")
        if authority.get("authority_status") not in {
            "current_authoritative",
            "current_companion",
            "reference_only",
            "historical",
            "rejected",
        }:
            raise VerificationError(f"{label}.authority_status is invalid")
        validate_identifier(
            authority.get("source_snapshot_id"),
            f"{label}.source_snapshot_id",
        )
        _projection_id_list(
            authority.get("dependencies"),
            f"{label}.dependencies",
            maximum=512,
        )
        verification = _projection_object(
            authority.get("verification"),
            {"status", "checks", "evidence"},
            f"{label}.verification",
        )
        if verification.get("status") not in {
            "verified",
            "partially_verified",
            "unverified",
            "rejected",
        }:
            raise VerificationError(f"{label}.verification.status is invalid")
        checks = _projection_unique_items(
            verification.get("checks"),
            f"{label}.verification.checks",
            maximum=32,
            minimum=1 if verification.get("status") == "verified" else 0,
        )
        for check_index, check in enumerate(checks):
            check_label = f"{label}.verification.checks[{check_index}]"
            check = _projection_object(
                check,
                {"check_id", "kind", "result", "evidence"},
                check_label,
            )
            validate_identifier(check.get("check_id"), f"{check_label}.check_id")
            if check.get("kind") not in {
                "sha256",
                "size",
                "remote_identity",
                "content",
                "provenance",
                "user_confirmation",
                "manual_inspection",
            }:
                raise VerificationError(f"{check_label}.kind is invalid")
            if check.get("result") not in {"passed", "failed", "not_run"}:
                raise VerificationError(f"{check_label}.result is invalid")
            _validate_projection_evidence(
                check.get("evidence"),
                f"{check_label}.evidence",
                required=False,
            )
        _validate_projection_evidence(
            verification.get("evidence"),
            f"{label}.verification.evidence",
            required=False,
        )
        relations = _projection_unique_items(
            authority.get("relations"),
            f"{label}.relations",
            maximum=64,
        )
        for relation_index, relation in enumerate(relations):
            relation_label = f"{label}.relations[{relation_index}]"
            relation = _projection_object(
                relation,
                {"kind", "target_artifact_id"},
                relation_label,
            )
            if relation.get("kind") not in {
                "derived_from",
                "supersedes",
                "companion_to",
                "alternative_to",
                "rejected_in_favor_of",
                "source_for",
                "contains",
            }:
                raise VerificationError(f"{relation_label}.kind is invalid")
            validate_identifier(
                relation.get("target_artifact_id"),
                f"{relation_label}.target_artifact_id",
            )
    if (
        value.get("unclassified_artifact_policy")
        != "reference_only_do_not_infer_from_filename_or_inventory"
    ):
        raise VerificationError("unclassified artifact policy is invalid")

    simple_collections = {
        "completed": (
            256,
            {"item_id", "statement", "evidence"},
            "item_id",
        ),
        "in_progress": (
            128,
            {"item_id", "statement", "next_checkpoint", "evidence"},
            "item_id",
        ),
        "next_actions": (
            128,
            {"action_id", "statement", "depends_on_claim_ids", "evidence"},
            "action_id",
        ),
        "open_questions": (
            64,
            {
                "question_id",
                "question",
                "blocking",
                "claim_key",
                "related_claim_ids",
                "blocking_conflict_id",
                "evidence",
            },
            "question_id",
        ),
        "risks": (
            64,
            {"risk_id", "statement", "severity", "blocking", "evidence"},
            "risk_id",
        ),
        "blocking_conflicts": (
            32,
            {
                "conflict_id",
                "statement",
                "claim_ids",
                "artifact_ids",
                "evidence",
                "handling",
            },
            "conflict_id",
        ),
        "nonblocking_contradictions": (
            64,
            {
                "contradiction_id",
                "statement",
                "effective_claim_id",
                "historical_claim_ids",
                "evidence",
                "handling",
            },
            "contradiction_id",
        ),
        "known_gaps": (
            64,
            {"gap_id", "area", "statement", "trace_status", "evidence"},
            "gap_id",
        ),
        "evidence_index": (
            128,
            {"entry_id", "topic", "references"},
            "entry_id",
        ),
    }
    for collection_name, (
        maximum,
        item_fields,
        id_field,
    ) in simple_collections.items():
        collection = _projection_unique_items(
            value.get(collection_name),
            f"projection.{collection_name}",
            maximum=maximum,
        )
        for index, raw_item in enumerate(collection):
            label = f"projection.{collection_name}[{index}]"
            item = _projection_object(raw_item, item_fields, label)
            validate_identifier(item.get(id_field), f"{label}.{id_field}")
            text_field = {
                "open_questions": "question",
                "evidence_index": "topic",
            }.get(collection_name, "statement")
            _projection_text(item.get(text_field), f"{label}.{text_field}")
            evidence_field = (
                "references" if collection_name == "evidence_index" else "evidence"
            )
            _validate_projection_evidence(
                item.get(evidence_field),
                f"{label}.{evidence_field}",
                required=collection_name
                in {
                    "completed",
                    "in_progress",
                    "open_questions",
                    "blocking_conflicts",
                    "nonblocking_contradictions",
                    "evidence_index",
                },
            )
            if collection_name == "in_progress":
                _projection_text(
                    item.get("next_checkpoint"),
                    f"{label}.next_checkpoint",
                )
            elif collection_name == "next_actions":
                _projection_id_list(
                    item.get("depends_on_claim_ids"),
                    f"{label}.depends_on_claim_ids",
                    maximum=128,
                )
            elif collection_name == "open_questions":
                if not isinstance(item.get("blocking"), bool):
                    raise VerificationError(f"{label}.blocking is invalid")
                if item.get("claim_key") is not None:
                    validate_identifier(
                        item.get("claim_key"),
                        f"{label}.claim_key",
                    )
                _projection_id_list(
                    item.get("related_claim_ids"),
                    f"{label}.related_claim_ids",
                    maximum=128,
                )
                if item.get("blocking_conflict_id") is not None:
                    validate_identifier(
                        item.get("blocking_conflict_id"),
                        f"{label}.blocking_conflict_id",
                    )
            elif collection_name == "risks":
                if item.get("severity") not in {
                    "low",
                    "medium",
                    "high",
                    "critical",
                } or not isinstance(item.get("blocking"), bool):
                    raise VerificationError(f"{label} severity/blocking is invalid")
            elif collection_name == "blocking_conflicts":
                _projection_id_list(
                    item.get("claim_ids"),
                    f"{label}.claim_ids",
                    maximum=128,
                )
                _projection_id_list(
                    item.get("artifact_ids"),
                    f"{label}.artifact_ids",
                    maximum=512,
                )
                if (
                    item.get("handling")
                    != "stop_disputed_work_and_request_resolution"
                ):
                    raise VerificationError(f"{label}.handling is invalid")
            elif collection_name == "nonblocking_contradictions":
                validate_identifier(
                    item.get("effective_claim_id"),
                    f"{label}.effective_claim_id",
                )
                _projection_id_list(
                    item.get("historical_claim_ids"),
                    f"{label}.historical_claim_ids",
                    maximum=32,
                    minimum=1,
                )
                if (
                    item.get("handling")
                    != "treat_history_as_reference_and_do_not_reask"
                ):
                    raise VerificationError(f"{label}.handling is invalid")
            elif collection_name == "known_gaps":
                if item.get("area") not in {
                    "goal_and_scope",
                    "decision",
                    "rationale",
                    "progress",
                    "artifact",
                    "conflict",
                    "evidence",
                } or item.get("trace_status") not in {
                    "not_attempted",
                    "partial",
                    "exhausted",
                }:
                    raise VerificationError(f"{label} area/status is invalid")

    trace = _projection_object(
        value.get("trace_policy"),
        {"mode", "triggers", "action"},
        "projection.trace_policy",
    )
    if trace.get("mode") != "on_demand_verified_evidence":
        raise VerificationError("projection trace mode is invalid")
    triggers = _projection_object(
        trace.get("triggers"),
        {
            "missing_rationale",
            "blocking_conflict",
            "multiple_same_role_current_authoritative_artifacts",
            "user_says_previously_explained",
            "projection_gap",
        },
        "projection.trace_policy.triggers",
    )
    if any(value is not True for value in triggers.values()):
        raise VerificationError("projection trace triggers are invalid")
    if (
        trace.get("action")
        != "trace_to_original_verified_evidence_before_asking_or_changing_state"
    ):
        raise VerificationError("projection trace action is invalid")


def _projection_with_runtime_completeness_basis(
    value: Mapping[str, Any],
) -> Mapping[str, Any]:
    """Safely read immutable projection/v1 documents created before bases."""

    _validate_task_memory_projection_structure(value)
    if isinstance(value.get("completeness_basis"), Mapping):
        return value
    normalized = strict_json_loads(
        json.dumps(value, ensure_ascii=False, allow_nan=False)
    )
    if not isinstance(normalized, dict):
        raise VerificationError("legacy task memory projection is invalid")
    dimensions = (
        "goal_and_scope",
        "decisions",
        "rationales",
        "progress",
        "artifacts",
        "conflicts",
        "evidence",
    )
    normalized["completeness"]["overall"] = "partial"
    normalized["completeness_basis"] = {}
    for dimension in dimensions:
        normalized["completeness"][dimension] = "unknown"
        normalized["completeness_basis"][dimension] = {
            "status": "unknown",
            "reason": LEGACY_COMPLETENESS_BASIS_REASON,
            "evidence": [],
        }
    _validate_task_memory_projection_structure(normalized)
    return normalized


def _projection_uses_legacy_runtime_basis(
    projection: Mapping[str, Any],
) -> bool:
    basis = projection.get("completeness_basis")
    return isinstance(basis, Mapping) and bool(basis) and all(
        isinstance(entry, Mapping)
        and entry.get("status") == "unknown"
        and entry.get("reason") == LEGACY_COMPLETENESS_BASIS_REASON
        and entry.get("evidence") == []
        for entry in basis.values()
    )


def _validate_conversation_export(value: Mapping[str, Any]) -> None:
    fields = {
        "schema_version",
        "source_id",
        "title",
        "captured_at",
        "coverage",
        "included_content",
        "excluded_content",
        "messages",
    }
    _require_keys(value, required=fields, allowed=fields, label="conversation")
    if value.get("schema_version") != "conversation-export/v1":
        raise VerificationError("conversation schema is invalid")
    validate_identifier(value.get("source_id"), "conversation.source_id")
    if (
        not isinstance(value.get("title"), str)
        or not value["title"]
        or len(value["title"]) > 500
    ):
        raise VerificationError("conversation title is invalid")
    scan_visible_text(value["title"], "conversation title")
    if not isinstance(value.get("captured_at"), str):
        raise VerificationError("conversation timestamp is invalid")
    if value.get("coverage") not in {"full", "partial", "partial_active_turn"}:
        raise VerificationError("conversation coverage is invalid")
    _validate_text_list(value.get("included_content"), "included content", maximum=100)
    _validate_text_list(value.get("excluded_content"), "excluded content", maximum=100)
    messages = value.get("messages")
    if not isinstance(messages, list) or not messages:
        raise VerificationError("conversation messages are invalid")
    for ordinal, message in enumerate(messages):
        if not isinstance(message, Mapping):
            raise VerificationError("conversation message is invalid")
        _require_keys(
            message,
            required={"ordinal", "role", "text"},
            allowed={"ordinal", "role", "phase", "text"},
            label="conversation message",
        )
        if message.get("ordinal") != ordinal:
            raise VerificationError("conversation message order is invalid")
        if message.get("role") not in {"user", "assistant"}:
            raise VerificationError("conversation message role is invalid")
        if message.get("phase", "unknown") not in {
            "commentary",
            "final_answer",
            "unknown",
        }:
            raise VerificationError("conversation message phase is invalid")
        if not isinstance(message.get("text"), str) or not message["text"]:
            raise VerificationError("conversation message text is invalid")
        scan_visible_text(message["text"], "conversation message")


def _validate_memory_episode(value: Mapping[str, Any]) -> None:
    fields = {
        "schema_version",
        "episode_id",
        "source_id",
        "source_sequence",
        "parent_episode_ids",
        "captured_at",
        "coverage",
        "included_content",
        "excluded_content",
        "messages",
        "hash_profile",
        "created_at",
        "episode_sha256",
    }
    _require_keys(value, required=fields, allowed=fields, label="memory episode")
    if value.get("schema_version") != memory_network.EPISODE_SCHEMA:
        raise VerificationError("memory episode schema is invalid")
    episode_id = validate_identifier(value.get("episode_id"), "episode_id")
    source_id = validate_identifier(value.get("source_id"), "episode source_id")
    if re.fullmatch(r"ep-[0-9a-f]{40}", episode_id) is None:
        raise VerificationError("memory episode identity is invalid")
    if re.fullmatch(r"src-[0-9a-f]{40}", source_id) is None:
        raise VerificationError("memory episode source pseudonym is invalid")
    sequence = value.get("source_sequence")
    if (
        not isinstance(sequence, int)
        or isinstance(sequence, bool)
        or sequence < 0
    ):
        raise VerificationError("memory episode source sequence is invalid")
    parents = value.get("parent_episode_ids")
    if not isinstance(parents, list) or len(parents) > 64:
        raise VerificationError("memory episode parents are invalid")
    normalized_parents = [
        validate_identifier(item, "parent episode_id") for item in parents
    ]
    if (
        len(normalized_parents) != len(set(normalized_parents))
        or episode_id in normalized_parents
        or any(
            re.fullmatch(r"ep-[0-9a-f]{40}", parent) is None
            for parent in normalized_parents
        )
    ):
        raise VerificationError("memory episode parent graph is invalid")
    if value.get("coverage") != "partial_active_turn":
        raise VerificationError("memory episode coverage is invalid")
    _validate_text_list(
        value.get("included_content"), "episode included content", maximum=32
    )
    _validate_text_list(
        value.get("excluded_content"), "episode excluded content", maximum=32
    )
    if value.get("captured_at") != value.get("created_at"):
        raise VerificationError("memory episode timestamp is invalid")
    validate_rfc3339(value.get("created_at"), "memory episode timestamp")
    messages = value.get("messages")
    if not isinstance(messages, list) or not 1 <= len(messages) <= 2:
        raise VerificationError("memory episode messages are invalid")
    for ordinal, message in enumerate(messages):
        if not isinstance(message, Mapping):
            raise VerificationError("memory episode message is invalid")
        _require_keys(
            message,
            required={"ordinal", "role", "phase", "text"},
            allowed={"ordinal", "role", "phase", "text"},
            label="memory episode message",
        )
        if (
            message.get("ordinal") != ordinal
            or message.get("role") not in {"user", "assistant"}
            or message.get("phase")
            not in {"commentary", "final_answer", "unknown"}
            or not isinstance(message.get("text"), str)
            or not message["text"]
        ):
            raise VerificationError("memory episode message is invalid")
        scan_visible_text(message["text"], "memory episode message")
    if value.get("hash_profile") != "jcs-rfc8785+sha256/episode-v1":
        raise VerificationError("memory episode hash profile is invalid")
    observed = validate_sha256(
        value.get("episode_sha256"), "memory episode hash"
    )
    domain = dict(value)
    domain.pop("episode_sha256", None)
    if observed != sha256_jcs(domain):
        raise VerificationError("memory episode JCS hash is invalid")
    assert_remote_safe(value)


def _validate_source(value: Mapping[str, Any]) -> None:
    fields = {
        "schema_version",
        "source_id",
        "source_type",
        "external_source_key_sha256",
        "source_instance_id",
        "visibility",
        "sensitivity",
        "current_revision_id",
        "revisions",
        "created_at",
    }
    _require_keys(value, required=fields, allowed=fields, label="source")
    if value.get("schema_version") != "source/v1":
        raise VerificationError("source schema is invalid")
    source_id = validate_identifier(value.get("source_id"), "source.source_id")
    if value.get("source_type") not in {
        "chat_thread",
        "codex_task",
        "workspace_import",
        "document",
        "artifact_manifest",
        "external_note",
        "legacy_record",
    }:
        raise VerificationError("generated source type is invalid")
    if value.get("external_source_key_sha256") is not None:
        validate_sha256(
            value.get("external_source_key_sha256"), "external source key"
        )
    if value.get("source_instance_id") is not None:
        validate_identifier(value["source_instance_id"], "source instance")
    if value.get("visibility") != "private" or value.get("sensitivity") not in {
        "ordinary",
        "restricted",
        "encrypted",
    }:
        raise VerificationError("source privacy fields are invalid")
    current_revision = validate_identifier(
        value.get("current_revision_id"), "current revision"
    )
    revisions = value.get("revisions")
    if not isinstance(revisions, list) or not revisions:
        raise VerificationError("source revisions are invalid")
    seen: set[str] = set()
    previous: str | None = None
    for sequence, revision in enumerate(revisions):
        if not isinstance(revision, Mapping):
            raise VerificationError("source revision is invalid")
        fields = {
            "revision_id",
            "previous_revision_id",
            "source_sequence",
            "captured_at",
            "coverage",
            "content_ref",
            "content_sha256",
            "redaction",
        }
        _require_keys(
            revision, required=fields, allowed=fields, label="source revision"
        )
        revision_id = validate_identifier(
            revision.get("revision_id"), "revision_id"
        )
        if revision_id in seen or revision.get("previous_revision_id") != previous:
            raise VerificationError("source revision lineage is invalid")
        if revision.get("source_sequence") != sequence:
            raise VerificationError("source sequence is invalid")
        if not isinstance(revision.get("captured_at"), str):
            raise VerificationError("source revision timestamp is invalid")
        if revision.get("coverage") not in {"full", "partial", "unknown"}:
            raise VerificationError("source revision coverage is invalid")
        redaction = revision.get("redaction")
        if not isinstance(redaction, Mapping):
            raise VerificationError("source redaction is invalid")
        _require_keys(
            redaction,
            required={"credentials_scanned", "content_removed"},
            allowed={"credentials_scanned", "content_removed", "reason"},
            label="source redaction",
        )
        if not isinstance(
            redaction.get("credentials_scanned"), bool
        ) or not isinstance(redaction.get("content_removed"), bool):
            raise VerificationError("source redaction flags are invalid")
        content_ref = revision.get("content_ref")
        content_sha = revision.get("content_sha256")
        if content_ref is None or content_sha is None:
            if (
                content_ref is not None
                or content_sha is not None
                or redaction.get("content_removed") is not True
            ):
                raise VerificationError("redacted source content reference is invalid")
        else:
            if redaction.get("credentials_scanned") is not True:
                raise VerificationError(
                    "source content was not credential-scanned"
                )
            if not isinstance(content_ref, Mapping):
                raise VerificationError("source content reference is invalid")
            ref_fields = {
                "storage",
                "object_id",
                "object_revision_id",
                "byte_size",
                "media_type",
            }
            _require_keys(
                content_ref,
                required=ref_fields,
                allowed=ref_fields,
                label="source content reference",
            )
            if content_ref.get("storage") != "git_blob":
                raise VerificationError("generated source storage is invalid")
            if not isinstance(content_ref.get("object_id"), str) or not re.fullmatch(
                r"[A-Za-z0-9_-]{2,256}", str(content_ref["object_id"])
            ):
                raise VerificationError("source object ID is invalid")
            if content_ref.get("object_revision_id") is not None:
                raise VerificationError(
                    "generated source revision locator is invalid"
                )
            if not isinstance(content_ref.get("byte_size"), int) or int(
                content_ref["byte_size"]
            ) < 0:
                raise VerificationError("source content size is invalid")
            if content_ref.get("media_type") != "application/json":
                raise VerificationError("source media type is invalid")
            validate_sha256(content_sha, "source content hash")
        previous = revision_id
        seen.add(revision_id)
    if current_revision != previous:
        raise VerificationError("source current revision is inconsistent")
    if not isinstance(value.get("created_at"), str):
        raise VerificationError("source creation time is invalid")
    if not source_id:
        raise VerificationError("source identity is invalid")


def _projection_evidence_refs(value: Any) -> Iterator[Mapping[str, Any]]:
    if isinstance(value, Mapping):
        if value.get("kind") in {"memory_event", "source_message", "artifact"}:
            yield value
            return
        for child in value.values():
            yield from _projection_evidence_refs(child)
    elif isinstance(value, list):
        for child in value:
            yield from _projection_evidence_refs(child)


def _task_version_source_evidence(
    manifest: Mapping[str, Any],
) -> dict[tuple[str, str], Mapping[str, Any]]:
    durable = manifest.get("evidence_sources")
    if not isinstance(durable, list):
        return {}
    result: dict[tuple[str, str], Mapping[str, Any]] = {}
    for reference in durable:
        if not isinstance(reference, Mapping):
            raise VerificationError("durable evidence source is invalid")
        key = (str(reference.get("source_id")), str(reference.get("revision_id")))
        if key in result:
            raise VerificationError("durable evidence source is duplicated")
        result[key] = reference
    return result


def _validate_memory_event_document(
    value: Mapping[str, Any],
    *,
    event_id: str,
) -> None:
    base_fields = {
        "schema_version",
        "memory_event_id",
        "kind",
        "confidence",
        "source",
        "claim_key",
        "parents",
        "supersedes",
        "conflicts_with",
        "resolves",
        "payload",
        "payload_sha256",
        "hash_profile",
        "event_sha256",
        "created_at",
    }
    schema = value.get("schema_version")
    fields = (
        base_fields | {"semantic_task_ids"}
        if schema == memory_network.LEGACY_MEMORY_EVENT_SCHEMA
        else base_fields
    )
    _require_keys(value, required=fields, allowed=fields, label="memory event")
    if (
        schema not in memory_network.MEMORY_EVENT_SCHEMAS
        or value.get("memory_event_id") != event_id
    ):
        raise VerificationError("memory event identity is invalid")
    validate_identifier(event_id, "memory_event_id")
    if (
        schema == memory_network.MEMORY_EVENT_SCHEMA
        and re.fullmatch(r"evt-[0-9a-f]{40}", event_id) is None
    ):
        raise VerificationError("memory event v2 identity is invalid")
    allowed_kinds = {
        "decision",
        "constraint",
        "progress",
        "next_action",
        "hypothesis",
        "artifact_created",
        "artifact_verified",
        "correction",
        "user_preference",
        "conflict_declared",
        "conflict_resolved",
        "checkpoint_note",
    }
    if schema == memory_network.LEGACY_MEMORY_EVENT_SCHEMA:
        allowed_kinds.add("binding_decision")
    if value.get("kind") not in allowed_kinds:
        raise VerificationError("memory event kind is invalid")
    allowed_confidences = (
        {
            "user_confirmed",
            "artifact_verified",
            "source_explicit",
            "imported_unverified",
            "assistant_inferred",
        }
        if schema == memory_network.LEGACY_MEMORY_EVENT_SCHEMA
        else {"source_explicit", "assistant_inferred"}
    )
    if value.get("confidence") not in allowed_confidences:
        raise VerificationError("memory event confidence is invalid")
    if schema == memory_network.LEGACY_MEMORY_EVENT_SCHEMA:
        task_ids = _projection_id_list(
            value.get("semantic_task_ids"),
            "memory event semantic_task_ids",
            maximum=128,
        )
        if len(task_ids) != len(set(task_ids)):
            raise VerificationError("memory event task scope is duplicated")
    source = _projection_object(
        value.get("source"),
        {
            "source_id",
            "revision_id",
            "source_sequence",
            "evidence_anchor_sha256",
        },
        "memory event source",
    )
    validate_identifier(source.get("source_id"), "memory event source_id")
    validate_identifier(source.get("revision_id"), "memory event revision_id")
    if schema == memory_network.MEMORY_EVENT_SCHEMA and (
        re.fullmatch(r"src-[0-9a-f]{40}", str(source.get("source_id"))) is None
        or re.fullmatch(r"ep-[0-9a-f]{40}", str(source.get("revision_id")))
        is None
    ):
        raise VerificationError("memory event v2 evidence identity is invalid")
    sequence = source.get("source_sequence")
    if (
        not isinstance(sequence, int)
        or isinstance(sequence, bool)
        or sequence < 0
    ):
        raise VerificationError("memory event source sequence is invalid")
    if (
        schema == memory_network.MEMORY_EVENT_SCHEMA
        and source.get("evidence_anchor_sha256") is None
    ):
        raise VerificationError("memory event v2 has no episode evidence anchor")
    if source.get("evidence_anchor_sha256") is not None:
        validate_sha256(
            source.get("evidence_anchor_sha256"),
            "memory event evidence anchor",
        )
    if value.get("claim_key") is not None:
        validate_identifier(value.get("claim_key"), "memory event claim_key")
    relation_values: dict[str, list[str]] = {}
    for key in ("parents", "supersedes", "conflicts_with", "resolves"):
        identifiers = _projection_id_list(
            value.get(key),
            f"memory event {key}",
            maximum=256,
        )
        if (
            schema == memory_network.MEMORY_EVENT_SCHEMA
            and any(
                re.fullmatch(r"evt-[0-9a-f]{40}", item) is None
                for item in identifiers
            )
        ):
            raise VerificationError(
                "memory event v2 relation target is not taskless"
            )
        if event_id in identifiers:
            raise VerificationError("memory event contains a self-reference")
        relation_values[key] = identifiers
    if (
        value.get("kind") == "conflict_declared"
        and len(relation_values["conflicts_with"]) < 2
    ):
        raise VerificationError(
            "conflict_declared memory requires at least two conflict targets"
        )
    if (
        value.get("kind") == "conflict_resolved"
        and not relation_values["resolves"]
    ):
        raise VerificationError(
            "conflict_resolved memory requires a resolved target"
        )
    payload = value.get("payload")
    if not isinstance(payload, Mapping):
        raise VerificationError("memory event payload is invalid")
    assert_remote_safe(payload)
    if schema == memory_network.MEMORY_EVENT_SCHEMA:
        profile = payload.get("profile")
        if profile == memory_network.EPISODE_EVENT_PROFILE:
            _require_keys(
                payload,
                required={
                    "memory_form",
                    "profile",
                    "message_count",
                    "roles",
                    "continuity",
                },
                allowed={
                    "memory_form",
                    "profile",
                    "message_count",
                    "roles",
                    "continuity",
                },
                label="episode memory event payload",
            )
            roles = payload.get("roles")
            if (
                value.get("kind") != "checkpoint_note"
                or value.get("confidence") != "source_explicit"
                or value.get("claim_key") is not None
                or payload.get("memory_form") != "episodic"
                or not isinstance(roles, list)
                or not 1 <= len(roles) <= 2
                or any(role not in {"user", "assistant"} for role in roles)
                or payload.get("message_count") != len(roles)
                or payload.get("continuity") not in {"origin", "continues"}
                or bool(relation_values["parents"])
                != (payload.get("continuity") == "continues")
                or len(relation_values["parents"]) > 1
                or any(
                    relation_values[key]
                    for key in ("supersedes", "conflicts_with", "resolves")
                )
            ):
                raise VerificationError("episode memory event profile is invalid")
        elif profile == "memory-network-semantic/v1":
            _require_keys(
                payload,
                required={"profile", "claim"},
                allowed={"profile", "claim"},
                label="semantic memory event payload",
            )
            if (
                value.get("confidence") != "assistant_inferred"
                or not isinstance(payload.get("claim"), Mapping)
                or not payload["claim"]
            ):
                raise VerificationError("semantic memory event profile is invalid")
        else:
            raise VerificationError("memory event v2 profile is invalid")
    expected_hash_profile = (
        "jcs-rfc8785+sha256/event-v1"
        if schema == memory_network.LEGACY_MEMORY_EVENT_SCHEMA
        else "jcs-rfc8785+sha256/event-v2"
    )
    if value.get("hash_profile") != expected_hash_profile:
        raise VerificationError("memory event hash profile is invalid")
    payload_hash = validate_sha256(
        value.get("payload_sha256"),
        "memory event payload hash",
    )
    if payload_hash != sha256_jcs(value.get("payload")):
        raise VerificationError("memory event payload JCS hash is invalid")
    event_hash = validate_sha256(
        value.get("event_sha256"),
        "memory event hash",
    )
    domain = dict(value)
    domain.pop("event_sha256", None)
    if event_hash != sha256_jcs(domain):
        raise VerificationError("memory event JCS hash is invalid")
    validate_rfc3339(value.get("created_at"), "memory event creation time")


def _validate_v2_event_episode(
    event: Mapping[str, Any],
    episode: Mapping[str, Any],
) -> None:
    """Bind every v2 event to its exact immutable visible evidence."""

    if event.get("schema_version") != memory_network.MEMORY_EVENT_SCHEMA:
        raise VerificationError("taskless memory event schema is invalid")
    _validate_memory_episode(episode)
    source = event.get("source")
    if not isinstance(source, Mapping):
        raise VerificationError("taskless memory event source is invalid")
    if (
        episode.get("source_id") != source.get("source_id")
        or episode.get("episode_id") != source.get("revision_id")
        or episode.get("source_sequence") != source.get("source_sequence")
        or episode.get("episode_sha256")
        != source.get("evidence_anchor_sha256")
    ):
        raise VerificationError(
            "taskless memory event does not match its immutable episode"
        )
    payload = event.get("payload")
    if (
        isinstance(payload, Mapping)
        and payload.get("profile") == memory_network.EPISODE_EVENT_PROFILE
    ):
        source_id = str(episode["source_id"])
        episode_id = str(episode["episode_id"])
        expected_event_id = memory_network.episode_event_id(
            source_id, episode_id
        )
        episode_parents = list(episode["parent_episode_ids"])
        expected_parents = (
            [memory_network.episode_event_id(source_id, episode_parents[-1])]
            if episode_parents
            else []
        )
        if (
            event.get("memory_event_id") != expected_event_id
            or event.get("parents") != expected_parents
            or payload.get("roles")
            != [message["role"] for message in episode["messages"]]
        ):
            raise VerificationError(
                "episode continuity event is not deterministic evidence"
            )
    elif (
        isinstance(payload, Mapping)
        and payload.get("profile") == "memory-network-semantic/v1"
    ):
        identity_domain = {
            "source_id": source["source_id"],
            "episode_id": source["revision_id"],
            "kind": event["kind"],
            "claim_key": event["claim_key"],
            "parents": event["parents"],
            "supersedes": event["supersedes"],
            "conflicts_with": event["conflicts_with"],
            "resolves": event["resolves"],
            "payload": payload,
        }
        expected_event_id = "evt-" + sha256_jcs(identity_domain)[:40]
        if event.get("memory_event_id") != expected_event_id:
            raise VerificationError(
                "semantic memory event identity is not content-addressed"
            )


def _assert_source_append_only(
    git: GitVault,
    source_id: str,
) -> Mapping[str, Any]:
    source_path = f"sources/{source_id}/SOURCE.json"
    commits = list(reversed(git.path_commits(source_path, maximum=256)))
    if not commits:
        raise VerificationError("projection source identity is missing")
    previous: Mapping[str, Any] | None = None
    current: Mapping[str, Any] | None = None
    stable_fields = {
        "schema_version",
        "source_id",
        "source_type",
        "external_source_key_sha256",
        "source_instance_id",
        "visibility",
        "sensitivity",
        "created_at",
    }
    for commit in commits:
        try:
            raw = git.show_bytes_at(commit, source_path)
            candidate = strict_json_loads(raw.decode("utf-8"))
        except (VaultSyncError, UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
            raise VerificationError(
                "projection source history is not append-only JSON"
            ) from exc
        if not isinstance(candidate, Mapping):
            raise VerificationError("projection source history is invalid")
        _validate_source(candidate)
        if candidate.get("source_id") != source_id:
            raise VerificationError("projection source history changed identity")
        if previous is not None:
            if any(candidate.get(key) != previous.get(key) for key in stable_fields):
                raise VerificationError(
                    "projection source identity metadata changed in history"
                )
            previous_revisions = previous.get("revisions")
            candidate_revisions = candidate.get("revisions")
            if (
                not isinstance(previous_revisions, list)
                or not isinstance(candidate_revisions, list)
                or len(candidate_revisions) < len(previous_revisions)
                or candidate_revisions[: len(previous_revisions)]
                != previous_revisions
            ):
                raise VerificationError(
                    "projection source revision history is not append-only"
                )
        previous = candidate
        current = candidate
    if current is None or current != git.show_json(source_path):
        raise VerificationError("projection source history does not match HEAD")
    return current


def _confirmed_source_binding(
    git: GitVault,
    *,
    task_id: str,
    source_id: str,
    source_sequence: int,
    expected_binding_id: str | None = None,
) -> str:
    primary_routes = _confirmed_primary_source_routes(git, source_id)
    if primary_routes:
        _active_primary_source_route(git, source_id)
    primary_by_id = {
        route.binding_id: route for route in primary_routes
    }
    paths = (
        [f"bindings/confirmed/{validate_identifier(expected_binding_id, 'source evidence binding_id')}.json"]
        if expected_binding_id is not None
        else git.list_paths("bindings/confirmed")
    )
    matches: list[tuple[str, bytes]] = []
    for path in paths:
        match = re.fullmatch(r"bindings/confirmed/([^/]+)\.json", path)
        if match is None:
            continue
        try:
            raw = git.show_bytes(path)
            binding = strict_json_loads(raw.decode("utf-8"))
        except (VaultSyncError, UnicodeDecodeError, ValueError, json.JSONDecodeError):
            continue
        if not isinstance(binding, Mapping):
            continue
        if (
            binding.get("schema_version") != "binding/v1"
            or binding.get("state") != "confirmed"
            or binding.get("subject") != {"kind": "source", "id": source_id}
        ):
            continue
        effective = binding.get("effective_range")
        if not isinstance(effective, Mapping):
            continue
        try:
            binding_id = validate_identifier(
                binding.get("binding_id"),
                "source evidence binding_id",
            )
        except IdentityError:
            continue
        start = effective.get("source_sequence_from")
        end = effective.get("source_sequence_to")
        primary_route = primary_by_id.get(binding_id)
        if primary_route is not None:
            end = _source_route_effective_end(
                primary_routes,
                primary_route,
            )
        if (
            not isinstance(start, int)
            or isinstance(start, bool)
            or start < 0
            or source_sequence < start
            or (
                end is not None
                and (
                    not isinstance(end, int)
                    or isinstance(end, bool)
                    or source_sequence > end
                )
            )
        ):
            continue
        targets = binding.get("targets")
        if not isinstance(targets, list) or not any(
            isinstance(target, Mapping)
            and target.get("semantic_task_id") == task_id
            and target.get("relation") == "source_for"
            and target.get("role")
            in {"primary", "supporting", "coordination", "reference"}
            for target in targets
        ):
            continue
        if path != f"bindings/confirmed/{binding_id}.json":
            raise VerificationError("source evidence binding path is inconsistent")
        matches.append((binding_id, raw))
    if len(matches) != 1:
        raise VerificationError(
            "source evidence has no unique confirmed task binding"
        )
    binding_id, raw = matches[0]
    if expected_binding_id is not None and binding_id != expected_binding_id:
        raise VerificationError("source evidence binding ID is inconsistent")
    git.assert_immutable_path(f"bindings/confirmed/{binding_id}.json", raw)
    return binding_id


def _projection_source_message(
    git: GitVault,
    manifest: Mapping[str, Any],
    task_id: str,
    reference: Mapping[str, Any],
    source_cache: MutableMapping[str, Mapping[str, Any]],
) -> Mapping[str, Any]:
    source_id = str(reference["source_id"])
    revision_id = str(reference["revision_id"])
    durable = _task_version_source_evidence(manifest).get(
        (source_id, revision_id)
    )
    if durable is None:
        raise VerificationError(
            "source-message evidence is not retained in evidence_sources"
        )
    if (
        durable.get("source_sequence") != reference.get("source_sequence")
        or durable.get("content_sha256")
        != reference.get("revision_content_sha256")
    ):
        raise VerificationError("source-message durable identity is inconsistent")
    binding_id = validate_identifier(
        durable.get("binding_id"),
        "source-message evidence binding_id",
    )
    _confirmed_source_binding(
        git,
        task_id=task_id,
        source_id=source_id,
        source_sequence=int(reference["source_sequence"]),
        expected_binding_id=binding_id,
    )
    content_path = validate_repo_path(
        durable.get("content_path"),
        "source-message content path",
    )
    expected_path = f"sources/{source_id}/revisions/{revision_id}.json"
    if content_path != expected_path:
        raise VerificationError("source-message content path is inconsistent")
    raw = git.show_bytes(content_path)
    if sha256_bytes(raw) != reference.get("revision_content_sha256"):
        raise VerificationError("source-message revision byte hash is invalid")
    git.assert_immutable_path(content_path, raw)
    try:
        conversation = strict_json_loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
        raise VerificationError("source-message revision JSON is invalid") from exc
    if not isinstance(conversation, Mapping):
        raise VerificationError("source-message revision is not an object")
    _validate_conversation_export(conversation)
    if conversation.get("source_id") != source_id:
        raise VerificationError("source-message revision source is inconsistent")

    source = source_cache.get(source_id)
    if source is None:
        source = _assert_source_append_only(git, source_id)
        source_cache[source_id] = source
    revisions = source.get("revisions")
    matches = [
        revision
        for revision in revisions or []
        if isinstance(revision, Mapping)
        and revision.get("revision_id") == revision_id
    ] if isinstance(revisions, list) else []
    if len(matches) != 1:
        raise VerificationError("source-message revision cannot be resolved")
    revision = matches[0]
    if (
        revision.get("source_sequence") != reference.get("source_sequence")
        or revision.get("content_sha256")
        != reference.get("revision_content_sha256")
    ):
        raise VerificationError("source-message revision metadata is stale")
    content_ref = revision.get("content_ref")
    if (
        not isinstance(content_ref, Mapping)
        or content_ref.get("storage") != "git_blob"
        or content_ref.get("byte_size") != len(raw)
        or content_ref.get("object_id") != git_blob_sha(raw)
    ):
        raise VerificationError("source-message Git blob identity is invalid")
    messages = conversation.get("messages")
    ordinal = reference.get("message_ordinal")
    if (
        not isinstance(messages, list)
        or not isinstance(ordinal, int)
        or isinstance(ordinal, bool)
        or ordinal < 0
        or ordinal >= len(messages)
    ):
        raise VerificationError("source-message ordinal is unavailable")
    message = messages[ordinal]
    if (
        not isinstance(message, Mapping)
        or message.get("ordinal") != ordinal
        or message.get("role") not in {"user", "assistant"}
        or not isinstance(message.get("text"), str)
    ):
        raise VerificationError("source-message anchor is invalid")
    if sha256_bytes(message["text"].encode("utf-8")) != reference.get(
        "evidence_anchor_sha256"
    ):
        raise VerificationError("source-message text anchor hash is invalid")
    return message


def _projection_memory_event(
    git: GitVault,
    manifest: Mapping[str, Any],
    task_id: str,
    reference: Mapping[str, Any],
    *,
    expected_claim_key: str | None,
) -> Mapping[str, Any]:
    event_id = str(reference["memory_event_id"])
    event_path = f"memory/events/{event_id}.json"
    raw = git.show_bytes(event_path)
    git.assert_immutable_path(event_path, raw)
    try:
        value = strict_json_loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
        raise VerificationError("memory event JSON is invalid") from exc
    if not isinstance(value, Mapping):
        raise VerificationError("memory event is not an object")
    _validate_memory_event_document(value, event_id=event_id)
    if value.get("event_sha256") != reference.get("event_sha256"):
        raise VerificationError("memory event evidence hash is stale")
    if task_id not in value.get("semantic_task_ids", []):
        raise VerificationError("memory event is not scoped to this task")
    if (
        expected_claim_key is not None
        and value.get("claim_key") != expected_claim_key
    ):
        raise VerificationError(
            "memory event claim key does not match projected claim"
        )
    source = value["source"]
    source_id = str(source["source_id"])
    revision_id = str(source["revision_id"])
    source_sequence = int(source["source_sequence"])
    durable = _task_version_source_evidence(manifest).get(
        (source_id, revision_id)
    )
    if durable is None:
        raise VerificationError(
            "memory-event source is not retained in evidence_sources"
        )
    if durable.get("source_sequence") != source_sequence:
        raise VerificationError("memory-event durable source sequence is stale")
    binding_id = validate_identifier(
        durable.get("binding_id"),
        "memory-event evidence binding_id",
    )
    _confirmed_source_binding(
        git,
        task_id=task_id,
        source_id=source_id,
        source_sequence=source_sequence,
        expected_binding_id=binding_id,
    )
    source_document = _assert_source_append_only(git, source_id)
    revisions = source_document.get("revisions")
    matches = [
        revision
        for revision in revisions or []
        if isinstance(revision, Mapping)
        and revision.get("revision_id") == revision_id
    ] if isinstance(revisions, list) else []
    if len(matches) != 1:
        raise VerificationError("memory event source revision is missing")
    revision = matches[0]
    if revision.get("source_sequence") != source_sequence:
        raise VerificationError("memory event source sequence is stale")
    if durable.get("content_sha256") != revision.get("content_sha256"):
        raise VerificationError("memory-event durable source hash is stale")
    content_path = validate_repo_path(
        durable.get("content_path"),
        "memory-event content path",
    )
    if content_path != f"sources/{source_id}/revisions/{revision_id}.json":
        raise VerificationError("memory-event durable source path is invalid")
    anchor = source.get("evidence_anchor_sha256")
    content_ref = revision.get("content_ref")
    raw_source = git.show_bytes(content_path)
    git.assert_immutable_path(content_path, raw_source)
    if (
        sha256_bytes(raw_source) != revision.get("content_sha256")
        or not isinstance(content_ref, Mapping)
        or content_ref.get("storage") != "git_blob"
        or content_ref.get("object_id") != git_blob_sha(raw_source)
        or content_ref.get("byte_size") != len(raw_source)
    ):
        raise VerificationError("memory event source content is invalid")
    try:
        source_value = strict_json_loads(raw_source.decode("utf-8"))
    except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
        raise VerificationError(
            "memory event source revision JSON is invalid"
        ) from exc
    if not isinstance(source_value, Mapping):
        raise VerificationError(
            "memory event source revision is not an object"
        )
    _validate_conversation_export(source_value)
    if source_value.get("source_id") != source_id:
        raise VerificationError(
            "memory event source revision identity is invalid"
        )
    if anchor is not None:
        messages = source_value.get("messages")
        anchored = [
            message
            for message in messages or []
            if isinstance(message, Mapping)
            and isinstance(message.get("text"), str)
            and sha256_bytes(message["text"].encode("utf-8")) == anchor
        ] if isinstance(messages, list) else []
        if len(anchored) != 1:
            raise VerificationError(
                "memory event source anchor is not a unique exact message"
            )
        declared_ordinal = value.get("payload", {}).get(
            "evidence_message_ordinal"
        )
        if declared_ordinal is not None and (
            not isinstance(declared_ordinal, int)
            or isinstance(declared_ordinal, bool)
            or anchored[0].get("ordinal") != declared_ordinal
        ):
            raise VerificationError(
                "memory event evidence message ordinal is inconsistent"
            )
    return value


def _projection_artifact(
    manifest: Mapping[str, Any],
    reference: Mapping[str, Any],
) -> Mapping[str, Any]:
    matches = [
        artifact
        for artifact in manifest.get("artifacts", [])
        if isinstance(artifact, Mapping)
        and artifact.get("artifact_id") == reference.get("artifact_id")
    ] if isinstance(manifest.get("artifacts"), list) else []
    if len(matches) != 1 or matches[0].get("sha256") != reference.get("sha256"):
        raise VerificationError(
            "artifact evidence does not match this task version"
        )
    return matches[0]


def _verify_projection_reference(
    git: GitVault,
    manifest: Mapping[str, Any],
    task_id: str,
    reference: Mapping[str, Any],
    *,
    expected_claim_key: str | None = None,
    source_cache: MutableMapping[str, Mapping[str, Any]],
) -> Mapping[str, Any]:
    kind = reference.get("kind")
    if kind == "memory_event":
        return _projection_memory_event(
            git,
            manifest,
            task_id,
            reference,
            expected_claim_key=expected_claim_key,
        )
    if kind == "source_message":
        return _projection_source_message(
            git,
            manifest,
            task_id,
            reference,
            source_cache,
        )
    if kind == "artifact":
        return _projection_artifact(manifest, reference)
    raise VerificationError("projection evidence kind is invalid")


def _projection_ancestor_manifests(
    git: GitVault,
    manifest: Mapping[str, Any],
    *,
    required_snapshot_ids: set[str],
) -> dict[str, Mapping[str, Any]]:
    task_id = str(manifest["task_id"])
    result = {str(manifest["snapshot_id"]): manifest}
    unresolved = set(required_snapshot_ids) - set(result)
    if not unresolved:
        return result
    pending = list(manifest.get("parents", []))
    visited_paths: set[str] = set()
    while pending:
        if len(visited_paths) >= 256:
            raise VerificationError("task version ancestry exceeds the safety limit")
        parent = pending.pop()
        if not isinstance(parent, Mapping):
            raise VerificationError("task version parent is invalid")
        path = validate_repo_path(parent.get("path"), "task version parent path")
        if path in visited_paths:
            continue
        visited_paths.add(path)
        parent_commit = validate_git_sha(
            parent.get("commit"),
            "task version parent commit",
        )
        git.assert_commit_is_ancestor(parent_commit)
        raw = git.show_bytes_at(parent_commit, path)
        try:
            value = strict_json_loads(raw.decode("utf-8"))
        except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
            raise VerificationError("task version ancestor is invalid JSON") from exc
        if not isinstance(value, Mapping):
            raise VerificationError("task version ancestor is not an object")
        _validate_task_version(value)
        if (
            value.get("task_id") != task_id
            or value.get("snapshot_id") != parent.get("snapshot_id")
        ):
            raise VerificationError("task version ancestry identity is invalid")
        snapshot_id = str(value["snapshot_id"])
        if snapshot_id in unresolved:
            if git.show_bytes(path) != raw:
                raise VerificationError(
                    "cited immutable ancestor version changed after its "
                    "declared commit"
                )
            git.assert_immutable_path(path, raw)
            result[snapshot_id] = value
            unresolved.remove(snapshot_id)
            if not unresolved:
                break
        pending.extend(value.get("parents", []))
    if unresolved:
        raise VerificationError(
            "artifact authority source snapshot is not reachable"
        )
    return result


def _validate_projection_precondition(
    git: GitVault,
    current: Mapping[str, Any],
    manifest: Mapping[str, Any],
    basis: Mapping[str, Any],
) -> None:
    generation = int(basis["generation"])
    precondition = basis.get("source_current_precondition")
    if generation == 1:
        if precondition is not None or manifest.get("parents"):
            raise VerificationError(
                "first-generation projection has a prior CURRENT precondition"
            )
        return
    if not isinstance(precondition, Mapping):
        raise VerificationError(
            "projection lacks its preceding CURRENT precondition"
        )
    if int(precondition["generation"]) != generation - 1:
        raise VerificationError(
            "projection precondition is not the preceding generation"
        )
    parents = manifest.get("parents")
    immediate = [
        parent
        for parent in parents or []
        if isinstance(parent, Mapping)
        and parent.get("snapshot_id") == precondition.get("snapshot_id")
        and parent.get("kind")
        in {"version_snapshot", "fork_baseline", "merge_parent", "rollback_target"}
    ] if isinstance(parents, list) else []
    if len(immediate) != 1:
        raise VerificationError(
            "projection precondition has no unique manifest parent"
        )
    parent = immediate[0]
    parent_commit = validate_git_sha(parent.get("commit"), "version parent commit")
    git.assert_commit_is_ancestor(parent_commit)
    parent_path = validate_repo_path(parent.get("path"), "version parent path")
    parent_raw = git.show_bytes_at(parent_commit, parent_path)
    if git.show_bytes(parent_path) != parent_raw:
        raise VerificationError(
            "projection immediate parent changed after its declared commit"
        )
    try:
        parent_manifest = strict_json_loads(parent_raw.decode("utf-8"))
    except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
        raise VerificationError("projection parent manifest is invalid") from exc
    if not isinstance(parent_manifest, Mapping):
        raise VerificationError("projection parent manifest is not an object")
    _validate_task_version(parent_manifest)
    if (
        parent_manifest.get("task_id") != current.get("task_id")
        or parent_manifest.get("snapshot_id") != precondition.get("snapshot_id")
        or parent_manifest.get("generation") != precondition.get("generation")
        or parent_manifest.get("transaction_id")
        != precondition.get("transaction_id")
    ):
        raise VerificationError("projection precondition parent identity is invalid")
    current_path = f"tasks/{current['task_id']}/CURRENT.json"
    previous_current_raw = git.show_bytes_at(parent_commit, current_path)
    if git_blob_sha(previous_current_raw) != precondition.get("current_blob_sha"):
        raise VerificationError(
            "projection precondition is not the parent commit CURRENT blob"
        )
    try:
        previous_current = strict_json_loads(previous_current_raw.decode("utf-8"))
    except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
        raise VerificationError("projection prior CURRENT is invalid") from exc
    if not isinstance(previous_current, Mapping):
        raise VerificationError("projection prior CURRENT is not an object")
    _validate_task_current(previous_current)
    if (
        previous_current.get("task_id") != current.get("task_id")
        or previous_current.get("snapshot_id") != precondition.get("snapshot_id")
        or previous_current.get("generation") != precondition.get("generation")
        or previous_current.get("published_transaction_id")
        != precondition.get("transaction_id")
        or previous_current.get("manifest_path") != parent_path
    ):
        raise VerificationError("projection prior CURRENT identity is inconsistent")


def _validate_projection_reconciliation_receipts(
    git: GitVault,
    manifest: Mapping[str, Any],
    projection: Mapping[str, Any],
) -> None:
    """Require every direct-parent delta to be retained or audibly absorbed."""

    parent_projections: dict[str, Mapping[str, Any]] = {}
    for parent in manifest.get("parents", []):
        if not isinstance(parent, Mapping):
            continue
        parent_commit = validate_git_sha(
            parent.get("commit"), "projection receipt parent commit"
        )
        parent_path = validate_repo_path(
            parent.get("path"), "projection receipt parent path"
        )
        raw_manifest = git.show_bytes_at(parent_commit, parent_path)
        try:
            parent_manifest = strict_json_loads(raw_manifest.decode("utf-8"))
        except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
            raise VerificationError(
                "projection receipt parent manifest is invalid"
            ) from exc
        if not isinstance(parent_manifest, Mapping):
            raise VerificationError(
                "projection receipt parent manifest is invalid"
            )
        _validate_task_version(parent_manifest)
        if (
            parent_manifest.get("task_id") != manifest.get("task_id")
            or parent_manifest.get("snapshot_id") != parent.get("snapshot_id")
        ):
            raise VerificationError(
                "projection receipt parent manifest identity is invalid"
            )
        reference = parent_manifest.get("memory_projection")
        if reference is None:
            continue
        if not isinstance(reference, Mapping):
            raise VerificationError(
                "projection receipt parent reference is invalid"
            )
        source_projection_id = validate_identifier(
            reference.get("projection_id"),
            "receipt source projection ID",
        )
        source_path = validate_repo_path(
            reference.get("path"),
            "receipt source projection path",
        )
        expected_source_path = (
            f"tasks/{manifest['task_id']}/projections/"
            f"{source_projection_id}.json"
        )
        if source_path != expected_source_path:
            raise VerificationError(
                "receipt source projection path is inconsistent"
            )
        raw_projection = git.show_bytes_at(parent_commit, source_path)
        if sha256_bytes(raw_projection) != reference.get("content_sha256"):
            raise VerificationError(
                "projection receipt source projection hash is invalid"
            )
        if git.show_bytes(source_path) != raw_projection:
            raise VerificationError(
                "projection receipt source was absent or changed after "
                "the declared parent commit"
            )
        git.assert_immutable_path(source_path, raw_projection)
        try:
            source_projection = strict_json_loads(
                raw_projection.decode("utf-8")
            )
        except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
            raise VerificationError(
                "projection receipt source projection is invalid"
            ) from exc
        if not isinstance(source_projection, Mapping):
            raise VerificationError(
                "projection receipt source projection is invalid"
            )
        source_projection = _projection_with_runtime_completeness_basis(
            source_projection
        )
        if source_projection.get("projection_id") != source_projection_id:
            raise VerificationError(
                "projection receipt source projection identity is invalid"
            )
        previous_projection = parent_projections.get(source_projection_id)
        if (
            previous_projection is not None
            and jcs_json_bytes(previous_projection)
            != jcs_json_bytes(source_projection)
        ):
            raise VerificationError(
                "direct parents reuse one projection ID for different content"
            )
        parent_projections[source_projection_id] = source_projection

    current_deltas = {
        str(delta["delta_id"]): delta
        for delta in projection["unprojected_deltas"]
    }
    evidence_entries = {
        str(entry["entry_id"]): entry
        for entry in projection["evidence_index"]
    }
    scope = projection["scope_boundaries"]
    result_ids: dict[str, set[str]] = {
        "current_goal": {"current_goal"},
        "scope_boundary": {
            str(item["boundary_id"])
            for group in (scope["in_scope"], scope["out_of_scope"])
            for item in group
        },
        "effective_claim": {
            str(item["claim_id"]) for item in projection["effective_claims"]
        },
        "contested_claim": {
            str(item["claim_id"]) for item in projection["contested_claims"]
        },
        "superseded_claim": {
            str(item["claim_id"]) for item in projection["superseded_claims"]
        },
        "rejected_option": {
            str(item["option_id"]) for item in projection["rejected_options"]
        },
        "artifact_authority": {
            str(item["artifact_id"])
            for item in projection["artifact_authorities"]
        },
        "completed_item": {
            str(item["item_id"]) for item in projection["completed"]
        },
        "in_progress_item": {
            str(item["item_id"]) for item in projection["in_progress"]
        },
        "next_action": {
            str(item["action_id"]) for item in projection["next_actions"]
        },
        "open_question": {
            str(item["question_id"]) for item in projection["open_questions"]
        },
        "risk": {str(item["risk_id"]) for item in projection["risks"]},
        "blocking_conflict": {
            str(item["conflict_id"])
            for item in projection["blocking_conflicts"]
        },
        "nonblocking_contradiction": {
            str(item["contradiction_id"])
            for item in projection["nonblocking_contradictions"]
        },
        "known_gap": {
            str(item["gap_id"]) for item in projection["known_gaps"]
        },
        "evidence_index_entry": set(evidence_entries),
        "completeness": {
            "goal_and_scope",
            "decisions",
            "rationales",
            "progress",
            "artifacts",
            "conflicts",
            "evidence",
        },
    }

    audit_completeness = isinstance(
        projection.get("completeness_basis"),
        Mapping,
    )
    audit_completeness_basis = (
        audit_completeness
        and all(
            isinstance(parent.get("completeness_basis"), Mapping)
            for parent in parent_projections.values()
        )
    )

    def semantic_results(
        candidate: Mapping[str, Any],
    ) -> dict[tuple[str, str], Mapping[str, Any]]:
        candidate_scope = candidate["scope_boundaries"]
        groups: tuple[tuple[str, Sequence[Mapping[str, Any]], str], ...] = (
            ("effective_claim", candidate["effective_claims"], "claim_id"),
            ("contested_claim", candidate["contested_claims"], "claim_id"),
            ("superseded_claim", candidate["superseded_claims"], "claim_id"),
            ("rejected_option", candidate["rejected_options"], "option_id"),
            (
                "artifact_authority",
                candidate["artifact_authorities"],
                "artifact_id",
            ),
            ("completed_item", candidate["completed"], "item_id"),
            ("in_progress_item", candidate["in_progress"], "item_id"),
            ("next_action", candidate["next_actions"], "action_id"),
            ("open_question", candidate["open_questions"], "question_id"),
            ("risk", candidate["risks"], "risk_id"),
            (
                "blocking_conflict",
                candidate["blocking_conflicts"],
                "conflict_id",
            ),
            (
                "nonblocking_contradiction",
                candidate["nonblocking_contradictions"],
                "contradiction_id",
            ),
            ("known_gap", candidate["known_gaps"], "gap_id"),
        )
        result: dict[tuple[str, str], Mapping[str, Any]] = {
            ("current_goal", "current_goal"): candidate["current_goal"]
        }
        if audit_completeness:
            for dimension in (
                "goal_and_scope",
                "decisions",
                "rationales",
                "progress",
                "artifacts",
                "conflicts",
                "evidence",
            ):
                completeness_result: dict[str, Any] = {
                    "dimension": dimension,
                    "status": candidate["completeness"][dimension],
                }
                if audit_completeness_basis:
                    completeness_result["basis"] = candidate[
                        "completeness_basis"
                    ][dimension]
                result[("completeness", dimension)] = (
                    completeness_result
                )
        for direction in ("in_scope", "out_of_scope"):
            for item in candidate_scope[direction]:
                result[
                    ("scope_boundary", str(item["boundary_id"]))
                ] = {
                    "direction": direction,
                    "boundary": item,
                }
        for kind, items, id_field in groups:
            for item in items:
                result[(kind, str(item[id_field]))] = item
        return result

    successor_results = semantic_results(projection)

    def result_key(result: Mapping[str, Any]) -> tuple[str, str]:
        kind = str(result["kind"])
        return (
            ("current_goal", "current_goal")
            if kind == "current_goal"
            else (kind, str(result["id"]))
        )

    def result_resolved_messages(
        value: Mapping[str, Any],
        expected_messages: set[bytes],
    ) -> set[bytes]:
        expected_by_anchor = {
            (
                str(reference["source_id"]),
                str(reference["revision_id"]),
                int(reference["source_sequence"]),
                str(reference["evidence_anchor_sha256"]),
            ): reference_bytes
            for reference_bytes in expected_messages
            for reference in [strict_json_loads(reference_bytes.decode("utf-8"))]
            if isinstance(reference, Mapping)
            and reference.get("kind") == "source_message"
        }
        matched: set[bytes] = set()
        for reference in _projection_evidence_refs(value):
            if reference.get("kind") == "source_message":
                if jcs_json_bytes(reference) in expected_messages:
                    matched.add(jcs_json_bytes(reference))
            elif reference.get("kind") == "memory_event":
                event = _projection_memory_event(
                    git,
                    manifest,
                    str(manifest["task_id"]),
                    reference,
                    expected_claim_key=None,
                )
                source = event["source"]
                anchored = (
                    str(source["source_id"]),
                    str(source["revision_id"]),
                    int(source["source_sequence"]),
                    str(source.get("evidence_anchor_sha256")),
                )
                if anchored in expected_by_anchor:
                    matched.add(expected_by_anchor[anchored])
        return matched

    resolved_by_source: dict[str, set[str]] = {}
    receipt_groups: dict[
        str,
        list[
            tuple[
                Mapping[str, Any],
                set[bytes],
                set[bytes],
                set[tuple[str, str]],
                set[tuple[str, str]],
            ]
        ],
    ] = {}
    for receipt in projection["reconciliation_receipts"]:
        source_projection_id = str(receipt["source_projection_id"])
        source_projection = parent_projections.get(source_projection_id)
        if source_projection is None:
            raise VerificationError(
                "reconciliation receipt does not cite a direct-parent projection"
            )
        source_deltas = {
            str(delta["delta_id"]): delta
            for delta in source_projection["unprojected_deltas"]
        }
        resolved = set(receipt["resolved_delta_ids"])
        if not resolved <= set(source_deltas):
            raise VerificationError(
                "reconciliation receipt resolves an unknown parent delta"
            )
        if resolved & set(current_deltas):
            raise VerificationError(
                "reconciliation receipt also retains a resolved delta"
            )
        previously_resolved = resolved_by_source.setdefault(
            source_projection_id, set()
        )
        if previously_resolved & resolved:
            raise VerificationError(
                "a parent delta is claimed by multiple reconciliation receipts"
            )
        previously_resolved.update(resolved)
        expected_messages = {
            jcs_json_bytes(reference)
            for delta_id in resolved
            for reference in source_deltas[delta_id]["message_evidence"]
        }
        actual_messages = {
            jcs_json_bytes(reference)
            for reference in receipt["message_evidence"]
        }
        if not expected_messages or actual_messages != expected_messages:
            raise VerificationError(
                "reconciliation receipt changed its parent message evidence"
            )
        retirement_messages = {
            jcs_json_bytes(reference)
            for reference in receipt["retirement_message_evidence"]
        }
        if not retirement_messages <= actual_messages:
            raise VerificationError(
                "retirement message evidence is outside the resolved receipt"
            )
        entry_ids = set(receipt["evidence_entry_ids"])
        if not entry_ids <= set(evidence_entries):
            raise VerificationError(
                "reconciliation receipt names an unknown evidence entry"
            )
        covered_messages = {
            jcs_json_bytes(reference)
            for entry_id in entry_ids
            for reference in evidence_entries[entry_id]["references"]
        }
        if not actual_messages <= covered_messages:
            raise VerificationError(
                "reconciliation receipt evidence is not retained in the index"
            )
        result_refs = receipt["result_refs"]
        if any(
            str(result["id"])
            not in result_ids.get(str(result["kind"]), set())
            for result in result_refs
        ):
            raise VerificationError(
                "reconciliation receipt names an unavailable semantic result"
            )
        result_entry_ids = {
            str(result["id"])
            for result in result_refs
            if result["kind"] == "evidence_index_entry"
        }
        if result_entry_ids != entry_ids:
            raise VerificationError(
                "reconciliation receipt result evidence IDs are inconsistent"
            )
        completeness_transitions = {
            str(transition["dimension"]): transition
            for transition in receipt.get(
                "completeness_transitions",
                [],
            )
        }
        for dimension, transition in completeness_transitions.items():
            source_basis = (
                _projection_completeness_basis_for_reconciliation(
                    source_projection
                )[dimension]
            )
            successor_basis = (
                _projection_completeness_basis_for_reconciliation(
                    projection
                )[dimension]
            )
            if (
                transition.get("before")
                != source_projection["completeness"][dimension]
                or transition.get("after")
                != projection["completeness"][dimension]
                or transition.get("before_basis_sha256")
                != sha256_jcs(source_basis)
                or transition.get("after_basis_sha256")
                != sha256_jcs(successor_basis)
                or transition.get("reason")
                != successor_basis.get("reason")
                or jcs_json_bytes(transition.get("evidence"))
                != jcs_json_bytes(successor_basis.get("evidence"))
            ):
                raise VerificationError(
                    "completeness transition does not match parent and "
                    "successor status or basis"
                )
            transition_messages = {
                jcs_json_bytes(reference)
                for reference in transition["evidence"]
                if reference.get("kind") == "source_message"
            }
            if (
                not transition_messages
                or not transition_messages <= actual_messages
            ):
                raise VerificationError(
                    "completeness transition evidence is outside its "
                    "resolved receipt"
                )
        non_evidence = any(
            result["kind"] != "evidence_index_entry"
            for result in result_refs
        ) or bool(receipt["retired_refs"])
        if (
            receipt["outcome"] == "state_updated" and not non_evidence
        ) or (
            receipt["outcome"] == "evidence_only_no_semantic_change"
            and non_evidence
        ):
            raise VerificationError(
                "reconciliation receipt outcome contradicts its result refs"
            )
        referenced_result_keys = {
            result_key(result)
            for result in result_refs
            if result["kind"] != "evidence_index_entry"
        }
        retired_result_keys = {
            result_key(result) for result in receipt["retired_refs"]
        }
        if (
            receipt["outcome"] == "evidence_only_no_semantic_change"
            and retired_result_keys
        ):
            raise VerificationError(
                "evidence-only reconciliation cannot retire semantic results"
            )
        if bool(retired_result_keys) != bool(retirement_messages):
            raise VerificationError(
                "retired results require exact retirement message evidence"
            )
        receipt_groups.setdefault(source_projection_id, []).append(
            (
                receipt,
                actual_messages,
                retirement_messages,
                referenced_result_keys,
                retired_result_keys,
            )
        )

    for source_projection_id, source_projection in parent_projections.items():
        parent_deltas = {
            str(delta["delta_id"]): delta
            for delta in source_projection["unprojected_deltas"]
        }
        for delta_id, parent_delta in parent_deltas.items():
            retained = current_deltas.get(delta_id)
            if retained is not None and jcs_json_bytes(retained) != jcs_json_bytes(
                parent_delta
            ):
                raise VerificationError(
                    "successor changed a retained unprojected delta"
                )
        accounted = set(current_deltas) | resolved_by_source.get(
            source_projection_id, set()
        )
        if set(parent_deltas) - accounted:
            raise VerificationError(
                "successor silently dropped a parent unprojected delta"
            )
        source_results = semantic_results(source_projection)
        removed_keys = set(source_results) - set(successor_results)
        changed_or_added_keys = {
            key
            for key in successor_results
            if key not in source_results
            or jcs_json_bytes(source_results[key])
            != jcs_json_bytes(successor_results[key])
        }
        deterministic_gap_id = (
            "gap-artifact-rollforward-"
            + sha256_bytes(
                (
                    f"{manifest['snapshot_id']}:"
                    f"{manifest['transaction_id']}"
                ).encode("utf-8")
            )[:24]
        )
        deterministic_gap_value = {
            "gap_id": deterministic_gap_id,
            "area": "artifact",
            "statement": (
                "This successor contains new or replaced artifacts that "
                "remain reference-only until a later projection explicitly "
                "classifies and verifies their authority."
            ),
            "trace_status": "not_attempted",
            "evidence": [],
        }
        manifest_artifacts = {
            str(item["artifact_id"]): item
            for item in manifest["artifacts"]
            if isinstance(item, Mapping)
        }
        successor_authorities = {
            str(item["artifact_id"]): item
            for item in projection["artifact_authorities"]
            if isinstance(item, Mapping)
        }
        source_authorities = {
            str(item["artifact_id"]): item
            for item in source_projection["artifact_authorities"]
            if isinstance(item, Mapping)
        }
        has_rollforward_artifact_change = bool(
            set(manifest_artifacts) - set(successor_authorities)
        ) or any(
            artifact_id not in manifest_artifacts
            or manifest_artifacts[artifact_id].get("sha256")
            != authority.get("sha256")
            for artifact_id, authority in source_authorities.items()
        )
        deterministic_gap_keys = {
            ("known_gap", deterministic_gap_id)
        } if (
            has_rollforward_artifact_change
            and ("known_gap", deterministic_gap_id) in changed_or_added_keys
            and ("known_gap", deterministic_gap_id) not in source_results
            and successor_results.get(("known_gap", deterministic_gap_id))
            == deterministic_gap_value
        ) else set()
        new_delta_ids = set(current_deltas) - set(parent_deltas)
        delta_downgrade_keys: set[tuple[str, str]] = set()
        if len(new_delta_ids) == 1:
            new_delta = current_deltas[next(iter(new_delta_ids))]
            expected_delta_evidence = [
                dict(reference)
                for reference in new_delta["message_evidence"][:16]
            ]
            for dimension in (
                "goal_and_scope",
                "decisions",
                "rationales",
                "progress",
                "artifacts",
                "conflicts",
                "evidence",
            ):
                key = ("completeness", dimension)
                expected_result = {
                    "dimension": dimension,
                    "status": "partial",
                    "basis": {
                        "status": "partial",
                        "reason": UNPROJECTED_DELTA_COMPLETENESS_REASON,
                        "evidence": expected_delta_evidence,
                    },
                }
                if (
                    key in changed_or_added_keys
                    and successor_results.get(key) == expected_result
                ):
                    delta_downgrade_keys.add(key)
        auditable_changed_keys = (
            changed_or_added_keys
            - deterministic_gap_keys
            - delta_downgrade_keys
        )
        grouped_receipts = receipt_groups.get(source_projection_id, [])
        grouped_changed_refs: set[tuple[str, str]] = set()
        grouped_retired_refs: set[tuple[str, str]] = set()
        for (
            receipt,
            receipt_messages,
            retirement_messages,
            receipt_changed_refs,
            receipt_retired_refs,
        ) in grouped_receipts:
            if grouped_changed_refs & receipt_changed_refs:
                raise VerificationError(
                    "semantic result is claimed by multiple reconciliation "
                    "receipts"
                )
            if grouped_retired_refs & receipt_retired_refs:
                raise VerificationError(
                    "retired result is claimed by multiple reconciliation "
                    "receipts"
                )
            grouped_changed_refs.update(receipt_changed_refs)
            grouped_retired_refs.update(receipt_retired_refs)
            if receipt["outcome"] == "state_updated":
                matched_messages: set[bytes] = set()
                for key in receipt_changed_refs:
                    result_value = successor_results.get(key)
                    if result_value is None:
                        raise VerificationError(
                            "reconciliation result is absent from successor"
                        )
                    if key[0] == "completeness":
                        transition = {
                            str(item["dimension"]): item
                            for item in receipt.get(
                                "completeness_transitions",
                                [],
                            )
                        }.get(key[1])
                        result_matches = (
                            {
                                jcs_json_bytes(reference)
                                for reference in transition["evidence"]
                                if jcs_json_bytes(reference)
                                in receipt_messages
                            }
                            if isinstance(transition, Mapping)
                            else set()
                        )
                    else:
                        result_matches = result_resolved_messages(
                            result_value,
                            receipt_messages,
                        )
                    if not result_matches:
                        raise VerificationError(
                            "changed semantic result is not grounded in a "
                            "resolved source message"
                        )
                    matched_messages.update(result_matches)
                if (
                    matched_messages | retirement_messages
                ) != receipt_messages:
                    raise VerificationError(
                        "state reconciliation does not ground every resolved "
                        "message in its changed semantic results"
                    )
        if grouped_changed_refs != auditable_changed_keys:
            raise VerificationError(
                "reconciliation receipts do not account for every new or "
                "changed semantic result"
            )
        if grouped_retired_refs != removed_keys:
            raise VerificationError(
                "reconciliation receipts do not account for every retired "
                "semantic result"
            )


def _validate_projection_handoff_integrity(
    projection: Mapping[str, Any],
    *,
    strict_successor: bool,
) -> None:
    """Keep projected handoff identities and successor state unambiguous."""

    def unique_ids(
        items: list[Any],
        id_field: str,
        label: str,
    ) -> set[str]:
        seen: set[str] = set()
        for item in items:
            if not isinstance(item, Mapping):
                continue
            identifier = str(item[id_field])
            if identifier in seen:
                raise VerificationError(
                    f"projection {label} ID is duplicated"
                )
            seen.add(identifier)
        return seen

    scope = projection["scope_boundaries"]
    scope_ids: set[str] = set()
    for direction in ("in_scope", "out_of_scope"):
        for boundary in scope[direction]:
            boundary_id = str(boundary["boundary_id"])
            if boundary_id in scope_ids:
                raise VerificationError(
                    "projection scope boundary ID is duplicated"
                )
            scope_ids.add(boundary_id)

    unique_ids(
        projection["rejected_options"],
        "option_id",
        "rejected option",
    )

    progress_buckets = {
        "completed": unique_ids(
            projection["completed"],
            "item_id",
            "completed progress item",
        ),
        "in_progress": unique_ids(
            projection["in_progress"],
            "item_id",
            "in-progress item",
        ),
        "next_actions": unique_ids(
            projection["next_actions"],
            "action_id",
            "next-action item",
        ),
    }
    claimed_bucket: dict[str, str] = {}
    for bucket, identifiers in progress_buckets.items():
        for identifier in identifiers:
            previous = claimed_bucket.get(identifier)
            if previous is not None:
                raise VerificationError(
                    "projection progress ID appears in multiple status buckets"
                )
            claimed_bucket[identifier] = bucket

    if not strict_successor:
        return

    gap_areas = {
        str(gap["area"])
        for gap in projection["known_gaps"]
        if isinstance(gap, Mapping)
    }
    progress_basis = projection.get("completeness_basis", {}).get(
        "progress"
    )
    if (
        projection["current_goal"].get("status") == "active"
        and not projection["next_actions"]
        and "progress" not in gap_areas
        and not (
            isinstance(progress_basis, Mapping)
            and progress_basis.get("status") == "unknown"
        )
    ):
        raise VerificationError(
            "active projection goal lacks both a next action and an explicit "
            "progress gap"
        )

    if not scope["in_scope"] and not scope["out_of_scope"]:
        if "goal_and_scope" not in gap_areas:
            raise VerificationError(
                "empty projection scope lacks an explicit goal-and-scope gap"
            )
        if projection["completeness"]["goal_and_scope"] == "complete":
            raise VerificationError(
                "empty projection scope cannot be complete"
            )


def _validate_projection_semantics(
    git: GitVault,
    current: Mapping[str, Any],
    manifest_path: str,
    manifest: Mapping[str, Any],
    projection: Mapping[str, Any],
    *,
    strict_successor: bool = False,
) -> None:
    task_id = str(current["task_id"])
    basis = projection["basis"]
    expected_basis = {
        "task_id": task_id,
        "snapshot_id": manifest["snapshot_id"],
        "generation": manifest["generation"],
        "transaction_id": manifest["transaction_id"],
        "manifest_path": manifest_path,
    }
    if any(basis.get(key) != expected for key, expected in expected_basis.items()):
        raise VerificationError(
            "task memory projection basis does not match CURRENT and manifest"
        )
    _validate_projection_precondition(git, current, manifest, basis)
    _validate_projection_handoff_integrity(
        projection,
        strict_successor=strict_successor,
    )

    source_cache: dict[str, Mapping[str, Any]] = {}
    verified_refs: set[bytes] = set()
    for reference in _projection_evidence_refs(projection):
        key = jcs_json_bytes(reference)
        if key in verified_refs:
            continue
        _verify_projection_reference(
            git,
            manifest,
            task_id,
            reference,
            source_cache=source_cache,
        )
        verified_refs.add(key)
    for collection_name in (
        "effective_claims",
        "contested_claims",
        "superseded_claims",
        "rejected_options",
    ):
        collection = projection.get(collection_name)
        if not isinstance(collection, list):
            continue
        for claim in collection:
            if not isinstance(claim, Mapping):
                continue
            claim_key = str(claim["claim_key"])
            for reference in _projection_evidence_refs(claim):
                _verify_projection_reference(
                    git,
                    manifest,
                    task_id,
                    reference,
                    expected_claim_key=claim_key,
                    source_cache=source_cache,
                )
    evidence_entries = {
        str(entry["entry_id"]): entry
        for entry in projection["evidence_index"]
    }
    if len(evidence_entries) != len(projection["evidence_index"]):
        raise VerificationError("projection evidence entry ID is duplicated")
    for delta in projection["unprojected_deltas"]:
        entry = evidence_entries.get(str(delta["evidence_entry_id"]))
        if entry is None or {
            jcs_json_bytes(reference)
            for reference in entry["references"]
        } != {
            jcs_json_bytes(reference)
            for reference in delta["message_evidence"]
        }:
            raise VerificationError(
                "unprojected delta has no matching evidence-index entry"
            )

    effective = {
        str(claim["claim_id"]): claim
        for claim in projection["effective_claims"]
    }
    contested = {
        str(claim["claim_id"]): claim
        for claim in projection["contested_claims"]
    }
    superseded = {
        str(claim["claim_id"]): claim
        for claim in projection["superseded_claims"]
    }
    all_claims: dict[str, Mapping[str, Any]] = {}
    for collection in (effective, contested, superseded):
        for claim_id, claim in collection.items():
            if claim_id in all_claims:
                raise VerificationError("projection claim ID is duplicated")
            all_claims[claim_id] = claim
    effective_keys: dict[str, str] = {}
    for claim_id, claim in effective.items():
        claim_key = str(claim["claim_key"])
        if claim_key in effective_keys:
            raise VerificationError(
                "projection has multiple effective claims for one claim key"
            )
        effective_keys[claim_key] = claim_id
        for old_id in claim["superseded_claim_ids"]:
            old = superseded.get(str(old_id))
            if (
                old is None
                or old.get("superseded_by_claim_id") != claim_id
                or old.get("claim_key") != claim_key
            ):
                raise VerificationError(
                    "projection supersedes relation is not bidirectional"
                )
    for old_id, old in superseded.items():
        new = effective.get(str(old["superseded_by_claim_id"]))
        if (
            new is None
            or old_id not in new["superseded_claim_ids"]
            or new.get("claim_key") != old.get("claim_key")
        ):
            raise VerificationError(
                "projection superseded claim has no effective successor"
            )

    gaps = {
        str(gap["gap_id"]): gap
        for gap in projection["known_gaps"]
    }
    for claim in all_claims.values():
        rationale = claim["rationale"]
        if rationale.get("status") == "not_recovered":
            gap = gaps.get(str(rationale["gap_id"]))
            if gap is None or gap.get("area") != "rationale":
                raise VerificationError(
                    "unrecovered claim rationale lacks a rationale gap"
                )
    for action in projection["next_actions"]:
        if any(
            claim_id not in effective
            for claim_id in action["depends_on_claim_ids"]
        ):
            raise VerificationError(
                "next action depends on a non-effective claim"
            )

    conflicts = {
        str(conflict["conflict_id"]): conflict
        for conflict in projection["blocking_conflicts"]
    }
    if len(conflicts) != len(projection["blocking_conflicts"]):
        raise VerificationError("blocking conflict ID is duplicated")
    contested_covered: set[str] = set()
    for conflict in conflicts.values():
        if not conflict["claim_ids"] and not conflict["artifact_ids"]:
            raise VerificationError("blocking conflict has no contested subject")
        for claim_id in conflict["claim_ids"]:
            if claim_id not in all_claims:
                raise VerificationError(
                    "blocking conflict refers to an unknown claim"
                )
            if claim_id in contested:
                contested_covered.add(claim_id)
    if contested_covered != set(contested):
        raise VerificationError(
            "every contested claim must belong to a blocking conflict"
        )
    contested_by_key: dict[str, set[str]] = {}
    for claim_id, claim in contested.items():
        contested_by_key.setdefault(str(claim["claim_key"]), set()).add(claim_id)
    for claim_key, contested_ids in contested_by_key.items():
        effective_id = effective_keys.get(claim_key)
        complete_set = set(contested_ids)
        if effective_id is not None:
            complete_set.add(effective_id)
        if not any(
            complete_set <= set(conflict["claim_ids"])
            for conflict in conflicts.values()
        ):
            raise VerificationError(
                "one blocking conflict must cover every claim contesting the same key"
            )
    for question in projection["open_questions"]:
        related = set(question["related_claim_ids"])
        if any(claim_id not in all_claims for claim_id in related):
            raise VerificationError("open question refers to an unknown claim")
        conflict_id = question.get("blocking_conflict_id")
        if conflict_id is not None and conflict_id not in conflicts:
            raise VerificationError(
                "open question refers to an unknown blocking conflict"
            )
        if question["blocking"] and not (
            conflict_id is not None
            or related & set(contested)
            or (
                question.get("claim_key") is not None
                and any(
                    claim.get("claim_key") == question["claim_key"]
                    for claim in contested.values()
                )
            )
        ):
            raise VerificationError(
                "blocking open question is not linked to a contested claim or conflict"
            )
        question_claim_key = question.get("claim_key")
        if (
            question_claim_key in effective_keys
            and conflict_id is None
        ):
            raise VerificationError(
                "open question reopens a settled claim without a blocking conflict"
            )

    for contradiction in projection["nonblocking_contradictions"]:
        effective_id = str(contradiction["effective_claim_id"])
        current_claim = effective.get(effective_id)
        if current_claim is None:
            raise VerificationError(
                "nonblocking contradiction lacks an effective claim"
            )
        explicit_history = set(current_claim["superseded_claim_ids"])
        if any(
            old_id not in superseded or old_id not in explicit_history
            for old_id in contradiction["historical_claim_ids"]
        ):
            raise VerificationError(
                "nonblocking contradiction has unsuperseded history"
            )

    manifest_artifacts = {
        str(artifact["artifact_id"]): artifact
        for artifact in manifest["artifacts"]
        if isinstance(artifact, Mapping)
    }
    if len(manifest_artifacts) != len(manifest["artifacts"]):
        raise VerificationError("task version artifact ID is duplicated")
    authorities = {
        str(authority["artifact_id"]): authority
        for authority in projection["artifact_authorities"]
    }
    if len(authorities) != len(projection["artifact_authorities"]):
        raise VerificationError("artifact authority ID is duplicated")
    for conflict in conflicts.values():
        if any(
            artifact_id not in authorities
            for artifact_id in conflict["artifact_ids"]
        ):
            raise VerificationError(
                "blocking conflict refers to an unknown artifact authority"
            )
    required_source_snapshots = {
        str(authority["source_snapshot_id"])
        for authority in projection["artifact_authorities"]
    }
    ancestors = _projection_ancestor_manifests(
        git,
        manifest,
        required_snapshot_ids=required_source_snapshots,
    )
    dependency_graph: dict[str, set[str]] = {}
    current_ids_by_role: dict[str, set[str]] = {}
    for artifact_id, authority in authorities.items():
        artifact = manifest_artifacts.get(artifact_id)
        if artifact is None or artifact.get("sha256") != authority.get("sha256"):
            raise VerificationError(
                "artifact authority does not match the task version"
            )
        source_manifest = ancestors.get(str(authority["source_snapshot_id"]))
        if source_manifest is None:
            raise VerificationError(
                "artifact authority source snapshot is not current or ancestral"
            )
        source_artifacts = [
            artifact
            for artifact in source_manifest.get("artifacts", [])
            if isinstance(artifact, Mapping)
            and artifact.get("artifact_id") == artifact_id
            and artifact.get("sha256") == authority.get("sha256")
        ] if isinstance(source_manifest.get("artifacts"), list) else []
        if len(source_artifacts) != 1:
            raise VerificationError(
                "artifact authority provenance does not exist in its source snapshot"
            )
        dependencies = set(authority["dependencies"])
        if artifact_id in dependencies or any(
            dependency not in authorities for dependency in dependencies
        ):
            raise VerificationError("artifact authority dependency is invalid")
        dependency_graph[artifact_id] = dependencies
        for relation in authority["relations"]:
            target = str(relation["target_artifact_id"])
            if target == artifact_id or target not in authorities:
                raise VerificationError("artifact authority relation is invalid")
            source_status = str(authority["authority_status"])
            target_status = str(authorities[target]["authority_status"])
            kind = str(relation["kind"])
            if kind == "supersedes" and target_status in {
                "current_authoritative",
                "current_companion",
            }:
                raise VerificationError(
                    "superseded artifact cannot remain current"
                )
            if kind == "rejected_in_favor_of" and not (
                source_status == "rejected"
                and target_status
                in {"current_authoritative", "current_companion"}
            ):
                raise VerificationError(
                    "artifact rejection relation contradicts authority status"
                )
            if kind == "companion_to" and "current_companion" not in {
                source_status,
                target_status,
            }:
                raise VerificationError(
                    "artifact companion relation contradicts authority status"
                )
            if (
                kind == "alternative_to"
                and source_status
                in {"current_authoritative", "current_companion"}
                and target_status
                in {"current_authoritative", "current_companion"}
                and not any(
                    {artifact_id, target} <= set(conflict["artifact_ids"])
                    for conflict in conflicts.values()
                )
            ):
                raise VerificationError(
                    "current artifact alternatives lack a blocking conflict"
                )
        verification = authority["verification"]
        if verification["status"] == "verified":
            checks = verification["checks"]
            kinds = {check["kind"] for check in checks}
            if (
                not checks
                or any(check["result"] != "passed" for check in checks)
                or "sha256" not in kinds
                or not ({"remote_identity", "size"} & kinds)
                or not verification["evidence"]
                or any(not check["evidence"] for check in checks)
            ):
                raise VerificationError(
                    "verified artifact lacks passed integrity checks and evidence"
                )
        if authority["authority_status"] in {
            "current_authoritative",
            "current_companion",
        } and verification["status"] != "verified":
            raise VerificationError("current artifact is not verified")
        if authority["authority_status"] == "current_authoritative":
            current_ids_by_role.setdefault(
                str(authority["role"]),
                set(),
            ).add(artifact_id)
    visiting: set[str] = set()
    visited: set[str] = set()

    def dependency_cycle(artifact_id: str) -> bool:
        if artifact_id in visiting:
            return True
        if artifact_id in visited:
            return False
        visiting.add(artifact_id)
        cyclic = any(
            dependency_cycle(child)
            for child in dependency_graph[artifact_id]
        )
        visiting.remove(artifact_id)
        visited.add(artifact_id)
        return cyclic

    if any(dependency_cycle(artifact_id) for artifact_id in dependency_graph):
        raise VerificationError("artifact authority dependency graph is cyclic")
    if (
        projection["completeness"]["artifacts"] == "complete"
        and set(authorities) != set(manifest_artifacts)
    ):
        raise VerificationError(
            "complete artifact projection does not classify every manifest artifact"
        )
    for role, current_ids in current_ids_by_role.items():
        if len(current_ids) <= 1:
            continue
        if not any(
            current_ids <= set(conflict["artifact_ids"])
            for conflict in conflicts.values()
        ):
            raise VerificationError(
                "multiple current authoritative artifacts in role "
                f"{role} require one blocking conflict covering that slot"
            )

    area_by_dimension = {
        "goal_and_scope": "goal_and_scope",
        "decisions": "decision",
        "rationales": "rationale",
        "progress": "progress",
        "artifacts": "artifact",
        "conflicts": "conflict",
        "evidence": "evidence",
    }
    gap_areas = {gap["area"] for gap in projection["known_gaps"]}
    completeness = projection["completeness"]
    if projection["unprojected_deltas"] and any(
        completeness[dimension] not in {"partial", "unknown"}
        for dimension in (
            "goal_and_scope",
            "decisions",
            "rationales",
            "progress",
            "artifacts",
            "conflicts",
            "evidence",
        )
    ):
        raise VerificationError(
            "unprojected message deltas require incomplete semantic dimensions"
        )
    if (
        projection["unprojected_deltas"]
        and manifest.get("continuation_readiness") == "ready"
    ):
        raise VerificationError(
            "unprojected message deltas cannot advertise ready continuation"
        )
    if (
        projection["blocking_conflicts"]
        and manifest.get("continuation_readiness") != "blocked"
    ):
        raise VerificationError(
            "blocking conflicts require blocked continuation readiness"
        )
    if (
        manifest.get("continuation_readiness") == "ready"
        and (
            projection["unprojected_deltas"]
            or projection["blocking_conflicts"]
        )
    ):
        raise VerificationError(
            "ready continuation cannot contain unresolved deltas or conflicts"
        )
    for dimension, area in area_by_dimension.items():
        if completeness[dimension] == "complete" and area in gap_areas:
            raise VerificationError(
                "projection completeness contradicts a known gap"
            )
    if completeness["overall"] == "complete" and (
        projection["known_gaps"]
        or any(
            completeness[dimension] != "complete"
            for dimension in area_by_dimension
        )
    ):
        raise VerificationError(
            "overall complete projection still contains incomplete dimensions"
        )
    _validate_projection_reconciliation_receipts(
        git,
        manifest,
        projection,
    )


def _load_task_memory_projection(
    git: GitVault,
    *,
    current: Mapping[str, Any],
    manifest_path: str,
    manifest: Mapping[str, Any],
) -> tuple[str | None, Mapping[str, Any] | None]:
    reference = manifest.get("memory_projection")
    if reference is None:
        return None, None
    if not isinstance(reference, Mapping):
        raise VerificationError("task memory projection reference is invalid")
    projection_id = validate_identifier(
        reference.get("projection_id"),
        "memory projection ID",
    )
    projection_path = validate_repo_path(
        reference.get("path"),
        "memory projection path",
    )
    expected_path = (
        f"tasks/{current['task_id']}/projections/{projection_id}.json"
    )
    if projection_path != expected_path:
        raise VerificationError("task memory projection path is inconsistent")
    if git.blob_size(projection_path) > MAX_CODEX_JSON_BYTES:
        raise VerificationError("task memory projection exceeds the fixed size limit")
    raw = git.show_bytes(projection_path)
    if sha256_bytes(raw) != reference.get("content_sha256"):
        raise VerificationError("task memory projection byte hash is invalid")
    git.assert_immutable_path(manifest_path, git.show_bytes(manifest_path))
    git.assert_immutable_path(projection_path, raw)
    try:
        value = strict_json_loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
        raise VerificationError("task memory projection JSON is invalid") from exc
    if not isinstance(value, Mapping):
        raise VerificationError("task memory projection is not an object")
    assert_remote_safe(value)
    has_persisted_completeness_basis = isinstance(
        value.get("completeness_basis"),
        Mapping,
    )
    value = _projection_with_runtime_completeness_basis(value)
    if value.get("projection_id") != projection_id:
        raise VerificationError("task memory projection ID is inconsistent")
    _validate_projection_semantics(
        git,
        current,
        manifest_path,
        manifest,
        value,
        strict_successor=has_persisted_completeness_basis,
    )
    return projection_path, value


def _validate_generated_evidence_binding(value: Mapping[str, Any]) -> None:
    fields = {
        "schema_version",
        "binding_id",
        "subject",
        "targets",
        "effective_range",
        "state",
        "confidence",
        "confirmation_basis",
        "evidence",
        "created_at",
        "created_by",
    }
    _require_keys(
        value,
        required=fields,
        allowed=fields
        | {
            "supersedes_binding_id",
            "route_correction",
            "route_revalidation",
            "content_review_attestation",
        },
        label="generated evidence binding",
    )
    binding_id = validate_identifier(value.get("binding_id"), "binding_id")
    subject = value.get("subject")
    if (
        value.get("schema_version") != "binding/v1"
        or value.get("state") != "confirmed"
        or not isinstance(subject, Mapping)
        or set(subject) != {"kind", "id"}
        or subject.get("kind") != "source"
    ):
        raise VerificationError("generated evidence binding is invalid")
    validate_identifier(subject.get("id"), "binding source_id")
    targets = value.get("targets")
    if not isinstance(targets, list) or len(targets) != 1:
        raise VerificationError("generated evidence binding target is invalid")
    target = targets[0]
    if (
        not isinstance(target, Mapping)
        or set(target) != {"semantic_task_id", "relation", "role"}
        or target.get("relation") != "source_for"
        or target.get("role") not in {
            "primary",
            "supporting",
            "coordination",
            "reference",
        }
    ):
        raise VerificationError("generated evidence binding target is invalid")
    validate_identifier(target.get("semantic_task_id"), "binding task_id")
    effective = value.get("effective_range")
    if (
        not isinstance(effective, Mapping)
        or set(effective) != {
            "source_sequence_from",
            "source_sequence_to",
        }
        or not isinstance(effective.get("source_sequence_from"), int)
        or isinstance(effective.get("source_sequence_from"), bool)
        or int(effective["source_sequence_from"]) < 0
        or (
            effective.get("source_sequence_to") is not None
            and (
                not isinstance(effective.get("source_sequence_to"), int)
                or isinstance(effective.get("source_sequence_to"), bool)
                or int(effective["source_sequence_to"])
                < int(effective["source_sequence_from"])
            )
        )
    ):
        raise VerificationError("generated evidence binding range is invalid")
    if not isinstance(value.get("created_at"), str):
        raise VerificationError("generated evidence binding time is invalid")
    if "supersedes_binding_id" in value:
        supersedes = validate_identifier(
            value.get("supersedes_binding_id"),
            "supersedes_binding_id",
        )
        if supersedes == binding_id:
            raise VerificationError(
                "generated evidence binding cannot supersede itself"
            )
    attestation = value.get("content_review_attestation")
    if (
        value.get("confirmation_basis") == SOURCE_ROUTE_CONFIRMATION_BASIS
        or attestation is not None
    ):
        if (
            value.get("confidence") != "user_confirmed"
            or value.get("confirmation_basis")
            != SOURCE_ROUTE_CONFIRMATION_BASIS
            or target.get("role") != "primary"
        ):
            raise VerificationError(
                "generated content-attested source binding is invalid"
            )
        _validate_source_route_content_attestation(
            attestation,
            source_id=str(subject["id"]),
            task_id=str(target["semantic_task_id"]),
        )
    revalidation = value.get("route_revalidation")
    if revalidation is not None:
        if (
            "supersedes_binding_id" not in value
            or value.get("route_correction") is not None
            or not isinstance(revalidation, Mapping)
            or set(revalidation) != {"reason", "target_task_id"}
            or revalidation.get("reason")
            != "missing_current_content_attestation"
            or revalidation.get("target_task_id")
            != target.get("semantic_task_id")
        ):
            raise VerificationError("route revalidation scope is invalid")
    correction = value.get("route_correction")
    if correction is not None:
        if "supersedes_binding_id" not in value:
            raise VerificationError(
                "route correction has no superseded binding"
            )
        if not isinstance(correction, Mapping):
            raise VerificationError("route correction is invalid")
        correction_fields = {
            "previous_task_id",
            "effective_source_sequence_from",
            "historical_content_review_required",
            "potentially_misrouted_sequence_count",
        }
        _require_keys(
            correction,
            required=correction_fields,
            allowed=correction_fields,
            label="route correction",
        )
        validate_identifier(
            correction.get("previous_task_id"),
            "route correction previous task",
        )
        effective_from = correction.get(
            "effective_source_sequence_from"
        )
        count = correction.get(
            "potentially_misrouted_sequence_count"
        )
        if (
            not isinstance(effective_from, int)
            or isinstance(effective_from, bool)
            or effective_from < 0
            or not isinstance(count, int)
            or isinstance(count, bool)
            or count < 0
            or (
                correction.get("historical_content_review_required")
                is not (count > 0)
            )
        ):
            raise VerificationError("route correction scope is invalid")
    assert_remote_safe(value)
    if not binding_id:
        raise VerificationError("generated evidence binding ID is invalid")


def _validate_generated_document(
    repo_path: str, value: Mapping[str, Any]
) -> None:
    episode_match = re.fullmatch(
        r"memory/episodes/([0-9a-f]{2})/([^/]+)\.json", repo_path
    )
    event_match = re.fullmatch(
        r"memory/events/(?:(?P<shard>[0-9a-f]{2})/)?(?P<event>[^/]+)\.json",
        repo_path,
    )
    if episode_match is not None:
        _validate_memory_episode(value)
        episode_id = validate_identifier(value.get("episode_id"), "episode_id")
        if (
            episode_id != episode_match.group(2)
            or not episode_id.startswith(f"ep-{episode_match.group(1)}")
        ):
            raise VerificationError("memory episode path is inconsistent")
    elif event_match is not None:
        event_id = event_match.group("event")
        _validate_memory_event_document(value, event_id=event_id)
        shard = event_match.group("shard")
        if value.get("schema_version") == memory_network.MEMORY_EVENT_SCHEMA:
            if (
                shard is None
                or not event_id.startswith(f"evt-{shard}")
                or re.fullmatch(r"evt-[0-9a-f]{40}", event_id) is None
            ):
                raise VerificationError(
                    "memory event v2 path is not content-sharded"
                )
        elif shard is not None and (
            not event_id.startswith(f"evt-{shard}")
            or re.fullmatch(r"evt-[0-9a-f]{40}", event_id) is None
        ):
            raise VerificationError("sharded memory event path is inconsistent")
    elif repo_path.endswith("/CURRENT.json"):
        _validate_task_current(value)
    elif "/versions/" in repo_path:
        _validate_task_version(value)
    elif repo_path.endswith("/SOURCE.json"):
        _validate_source(value)
    elif "/revisions/" in repo_path:
        _validate_conversation_export(value)
    elif "/projections/" in repo_path:
        if not isinstance(value.get("completeness_basis"), Mapping):
            raise VerificationError(
                "new task memory projection lacks completeness bases"
            )
        receipts = value.get("reconciliation_receipts")
        if not isinstance(receipts, list) or any(
            not isinstance(receipt, Mapping)
            or "completeness_transitions" not in receipt
            for receipt in receipts
        ):
            raise VerificationError(
                "new task memory projection has an incomplete "
                "reconciliation receipt"
            )
        _validate_task_memory_projection_structure(value)
    elif repo_path.startswith("bindings/confirmed/"):
        _validate_generated_evidence_binding(value)
    else:
        raise VerificationError("transaction attempted an unsupported remote file")


@dataclasses.dataclass(frozen=True)
class WorkspaceAuthority:
    binding_id: str
    task_id: str
    lineage_id: str


def _discover_remote_task_catalog(
    git: GitVault,
) -> tuple[dict[str, RemoteTaskState], Mapping[str, Any]]:
    """Discover tasks from the index and verify it against task identity files."""

    indexed: dict[str, Mapping[str, Any]] = {}
    index_present = git.file_exists("tasks/INDEX.json")
    if index_present:
        index = git.show_json("tasks/INDEX.json")
        if (
            index.get("schema_version") != "task-index/v1"
            or index.get("authority") != "discovery_only"
            or not isinstance(index.get("tasks"), list)
        ):
            raise VerificationError("remote task index is invalid")
        if len(index["tasks"]) > 1000:
            raise VerificationError("remote task index exceeds the safety limit")
        for raw in index["tasks"]:
            if not isinstance(raw, Mapping):
                raise VerificationError("remote task index entry is invalid")
            task_id = validate_identifier(raw.get("task_id"), "index.task_id")
            if task_id in indexed:
                raise VerificationError("remote task index contains a duplicate task")
            expected_current = f"tasks/{task_id}/CURRENT.json"
            if raw.get("current") != expected_current:
                raise VerificationError("remote task index CURRENT path is invalid")
            indexed[task_id] = raw

    discovered_ids: set[str] = set()
    for path in git.list_paths("tasks"):
        match = re.fullmatch(r"tasks/([^/]+)/TASK\.json", path)
        if match is not None:
            discovered_ids.add(validate_identifier(match.group(1), "task_id"))
    if len(discovered_ids) > 1000:
        raise VerificationError("remote task catalog exceeds the safety limit")
    if not discovered_ids:
        raise VerificationError("remote task catalog is empty")

    states: dict[str, RemoteTaskState] = {}
    for task_id in sorted(discovered_ids):
        state = load_remote_task_by_id(git, task_id)
        indexed_entry = indexed.get(task_id)
        if indexed_entry is not None:
            if (
                indexed_entry.get("status") != state.task.get("status")
                or indexed_entry.get("task_type") != state.task.get("task_type")
            ):
                raise VerificationError(
                    "remote task index disagrees with a task identity file"
                )
        states[task_id] = state
    stale_index_ids = sorted(set(indexed) - discovered_ids)
    if stale_index_ids:
        raise VerificationError("remote task index references a missing task")
    missing_index_ids = sorted(discovered_ids - set(indexed))
    return states, {
        "present": index_present,
        "consistent": index_present and not missing_index_ids,
        "missing_task_ids": missing_index_ids,
    }


def _discover_workspace_authorities(
    git: GitVault, task_ids: set[str]
) -> dict[str, list[WorkspaceAuthority]]:
    authorities: dict[str, list[WorkspaceAuthority]] = {}
    for path in git.list_paths("bindings/confirmed"):
        if not re.fullmatch(r"bindings/confirmed/[^/]+\.json", path):
            continue
        binding = git.show_json(path)
        subject = binding.get("subject")
        if (
            binding.get("schema_version") != "binding/v1"
            or binding.get("state") != "confirmed"
            or not isinstance(subject, Mapping)
            or subject.get("kind") != "workspace_lineage"
        ):
            continue
        binding_id = validate_identifier(binding.get("binding_id"), "binding_id")
        lineage_id = validate_identifier(subject.get("id"), "workspace_lineage_id")
        targets = binding.get("targets")
        if not isinstance(targets, list):
            continue
        for target in targets:
            if (
                not isinstance(target, Mapping)
                or target.get("relation") != "workspace_for"
                or target.get("role") != "primary"
            ):
                continue
            task_id = validate_identifier(
                target.get("semantic_task_id"), "semantic_task_id"
            )
            if task_id not in task_ids:
                raise VerificationError(
                    "workspace binding targets an undiscoverable task"
                )
            authority = WorkspaceAuthority(
                binding_id=binding_id,
                task_id=task_id,
                lineage_id=lineage_id,
            )
            if authority not in authorities.setdefault(task_id, []):
                authorities[task_id].append(authority)
    return authorities


def _discover_structural_splits(
    git: GitVault, task_ids: set[str]
) -> list[Mapping[str, Any]]:
    splits: list[Mapping[str, Any]] = []
    if not git.file_exists("bindings/structural"):
        return splits
    for path in git.list_paths("bindings/structural"):
        match = re.fullmatch(r"bindings/structural/([^/]+)\.json", path)
        if match is None:
            continue
        value = git.show_json(path)
        if value.get("event_type") != "source_split":
            continue
        if (
            value.get("schema_version") != "structural-binding/v1"
            or value.get("state") != "confirmed"
        ):
            raise VerificationError("confirmed source split record is invalid")
        event_id = validate_identifier(
            value.get("structural_event_id"), "structural_event_id"
        )
        if event_id != match.group(1):
            raise VerificationError("source split path does not match its identity")
        source_id = validate_identifier(value.get("source_id"), "source_id")
        raw_children = value.get("child_task_ids")
        if not isinstance(raw_children, list) or len(raw_children) < 2:
            raise VerificationError("source split children are invalid")
        children = [
            validate_identifier(item, "child_task_id") for item in raw_children
        ]
        if len(set(children)) != len(children) or any(
            child not in task_ids for child in children
        ):
            raise VerificationError("source split children are not discoverable")
        coordinator = validate_identifier(
            value.get("coordinator_task_id"), "coordinator_task_id"
        )
        if coordinator not in task_ids:
            raise VerificationError("source split coordinator is not discoverable")
        policy = value.get("policy")
        if not isinstance(policy, Mapping):
            raise VerificationError("source split policy is invalid")
        route = policy.get("continuation_route")
        normalized_route: Mapping[str, Any] | None = None
        if route is not None:
            if not isinstance(route, Mapping):
                raise VerificationError("source split continuation route is invalid")
            route_source = validate_identifier(
                route.get("source_id"), "route.source_id"
            )
            route_target = validate_identifier(
                route.get("target_task_id"), "route.target_task_id"
            )
            route_binding = validate_identifier(
                route.get("binding_id"), "route.binding_id"
            )
            route_sequence = route.get("source_sequence_from")
            if (
                route.get("state") != "confirmed"
                or route_source != source_id
                or route_target not in children
                or not isinstance(route_sequence, int)
                or route_sequence < 0
            ):
                raise VerificationError("source split continuation route is invalid")
            normalized_route = {
                "state": "confirmed",
                "source_id": route_source,
                "target_task_id": route_target,
                "binding_id": route_binding,
                "source_sequence_from": route_sequence,
            }
        splits.append(
            {
                "structural_event_id": event_id,
                "source_id": source_id,
                "child_task_ids": children,
                "coordinator_task_id": coordinator,
                "continuation_route": normalized_route,
            }
        )
    return splits


def _portable_identities_in_workspace(workspace: Path) -> list[PortableIdentity]:
    single = workspace / ".vault_identity.yaml"
    identity_set = workspace / ".vault_identities.json"
    if single.exists() and identity_set.exists():
        raise IdentityError("workspace contains conflicting portable identity files")
    if single.exists():
        return [parse_identity(single)]
    if not identity_set.exists():
        return []
    assert_plain_path(identity_set, require_file=True)
    value = load_json(identity_set)
    if (
        not isinstance(value, Mapping)
        or set(value) != {"schema_version", "vault_id", "identities"}
        or value.get("schema_version") != "portable-workspace-set/v1"
        or value.get("vault_id") != VAULT_ID
        or not isinstance(value.get("identities"), list)
    ):
        raise IdentityError("workspace has an invalid portable identity set")
    identities: list[PortableIdentity] = []
    for raw in value["identities"]:
        if not isinstance(raw, Mapping):
            raise IdentityError("workspace has an invalid portable identity set")
        identities.append(_parse_identity_value(raw, identity_set))
    return identities


def _projection_state_path(data_dir: Path) -> Path:
    return data_dir / "state" / "task-projection.json"


def _portable_identity_document(
    git: GitVault,
    remote: RemoteTaskState,
    authority: WorkspaceAuthority,
) -> Mapping[str, Any]:
    manifest_bytes = git.show_bytes(remote.manifest_path)
    return {
        "schema_version": "portable-workspace-identity/v1",
        "vault_id": VAULT_ID,
        "binding_id": authority.binding_id,
        "semantic_task_id": authority.task_id,
        "workspace_lineage_id": authority.lineage_id,
        "binding_state": "confirmed",
        "base": {
            "snapshot_id": remote.current["snapshot_id"],
            "manifest_sha256": sha256_bytes(manifest_bytes),
            "current_blob_sha": remote.current_blob_sha,
            "transaction_id": remote.current["published_transaction_id"],
        },
    }


def _portable_identity_value(identity: PortableIdentity) -> Mapping[str, Any]:
    return {
        "schema_version": "portable-workspace-identity/v1",
        "vault_id": VAULT_ID,
        "binding_id": identity.binding_id,
        "semantic_task_id": identity.task_id,
        "workspace_lineage_id": identity.lineage_id,
        "binding_state": "confirmed",
        "base": dict(identity.base),
    }


def _merge_workspace_identity_documents(
    workspace: Path,
    documents: Sequence[Mapping[str, Any]],
) -> list[str]:
    """Add exact identities without silently replacing an existing task."""

    single_marker = workspace / ".vault_identity.yaml"
    set_marker = workspace / ".vault_identities.json"
    if single_marker.exists() and set_marker.exists():
        raise IdentityError("workspace contains conflicting portable identity files")

    identities: dict[str, Mapping[str, Any]] = {}
    if single_marker.exists():
        current = parse_identity(single_marker)
        identities[current.task_id] = _portable_identity_value(current)
    elif set_marker.exists():
        for current in _portable_identities_in_workspace(workspace):
            identities[current.task_id] = _portable_identity_value(current)

    for document in documents:
        candidate = _parse_identity_value(document, set_marker)
        existing = identities.get(candidate.task_id)
        if existing is not None:
            current = _parse_identity_value(existing, set_marker)
            if (
                current.binding_id != candidate.binding_id
                or current.lineage_id != candidate.lineage_id
            ):
                raise IdentityError(
                    "workspace already has a different identity for this task"
                )
        identities[candidate.task_id] = dict(document)

    ordered = [identities[key] for key in sorted(identities)]
    if not ordered:
        raise IdentityError("native handoff has no portable task identity")
    if len(ordered) == 1 and not set_marker.exists():
        atomic_write_bytes(
            single_marker,
            pretty_json_bytes(ordered[0]),
            mode=0o644,
        )
        return sorted(identities)

    payload = {
        "schema_version": "portable-workspace-set/v1",
        "vault_id": VAULT_ID,
        "identities": ordered,
    }
    if single_marker.exists():
        backup = workspace / f".vault_identity.handoff-{uuid.uuid4().hex}.bak"
        os.replace(single_marker, backup)
        try:
            atomic_write_json(set_marker, payload)
        except Exception:
            with contextlib.suppress(OSError):
                os.replace(backup, single_marker)
            raise
        with contextlib.suppress(OSError):
            backup.unlink()
    else:
        atomic_write_json(set_marker, payload)
    return sorted(identities)


def _replace_workspace_identity_document(
    data_dir: Path,
    workspace: Path,
    document: Mapping[str, Any],
) -> Mapping[str, Any]:
    """Replace active marker only after a durable device-local audit record."""

    target = _parse_identity_value(
        document,
        workspace / ".vault_identity.yaml",
    )
    previous = [
        _portable_identity_value(identity)
        for identity in _portable_identities_in_workspace(workspace)
    ]
    operation_id = validate_identifier(
        f"identity-reassign-{uuid.uuid4().hex}",
        "identity reassignment operation_id",
    )
    audit_path = (
        data_dir
        / "state"
        / "identity-reassignments"
        / f"{operation_id}.json"
    )
    audit = {
        "schema_version": "memory-vault-identity-reassignment/v1",
        "operation_id": operation_id,
        "workspace_fingerprint_sha256": sha256_bytes(
            str(workspace.resolve()).encode("utf-8")
        ),
        "mode": "replace_workspace",
        "state": "prepared",
        "previous_identities": previous,
        "target_identity": dict(document),
        "previous_identity_set_sha256": sha256_bytes(
            canonical_json_bytes(previous)
        ),
        "target_identity_sha256": sha256_bytes(
            canonical_json_bytes(document)
        ),
        "created_at": utc_now(),
        "completed_at": None,
    }
    atomic_write_json(audit_path, audit)

    single_marker = workspace / ".vault_identity.yaml"
    set_marker = workspace / ".vault_identities.json"
    displaced: Path | None = None
    active_marker: Path | None = None
    if single_marker.exists():
        active_marker = single_marker
    elif set_marker.exists():
        active_marker = set_marker
    if active_marker is not None:
        displaced = (
            workspace
            / f".vault_identity.reassign-{operation_id}.pending"
        )
        os.replace(active_marker, displaced)
    try:
        atomic_write_bytes(
            single_marker,
            pretty_json_bytes(document),
            mode=0o644,
        )
        verified = parse_identity(single_marker)
        if (
            verified.task_id != target.task_id
            or verified.binding_id != target.binding_id
            or verified.lineage_id != target.lineage_id
        ):
            raise IdentityError(
                "replacement workspace identity could not be verified"
            )
    except Exception:
        with contextlib.suppress(FileNotFoundError):
            single_marker.unlink()
        if displaced is not None and active_marker is not None:
            os.replace(displaced, active_marker)
        audit["state"] = "rolled_back"
        audit["completed_at"] = utc_now()
        atomic_write_json(audit_path, audit)
        raise
    if displaced is not None:
        with contextlib.suppress(FileNotFoundError):
            displaced.unlink()
    audit["state"] = "completed"
    audit["completed_at"] = utc_now()
    atomic_write_json(audit_path, audit)
    return {
        "operation_id": operation_id,
        "previous_task_ids": sorted(
            str(item["semantic_task_id"]) for item in previous
        ),
        "task_id": target.task_id,
    }


def _write_route_switch_adoption_guard(
    data_dir: Path,
    workspace: Path,
    session_id: str,
    identity: PortableIdentity,
    remote: RemoteTaskState,
) -> Mapping[str, Any]:
    """Block artifact publication after a manual conversation correction."""

    device = _device_state(data_dir)
    now = utc_now()
    preexisting_publish = _publish_manifest_fingerprint(identity)
    guard = {
        "schema_version": ADOPTION_GUARD_SCHEMA,
        "task_id": identity.task_id,
        "binding_id": identity.binding_id,
        "workspace_lineage_id": identity.lineage_id,
        "workspace_root": str(workspace.resolve()),
        "expected_source_key_sha256": _codex_source_key(session_id),
        "cloud_snapshot_id": remote.current["snapshot_id"],
        "cloud_current_blob_sha": remote.current_blob_sha,
        "preexisting_publish_manifest_sha256": preexisting_publish,
        "approved_publish_manifest_sha256": None,
        "artifact_publication_blocked": True,
        "state": "cloud_current_loaded",
        "created_at": now,
        "updated_at": now,
    }
    atomic_write_json(
        _adoption_guard_path(
            data_dir,
            device,
            workspace,
            identity.task_id,
        ),
        guard,
    )
    portable_guard = {
        key: guard[key]
        for key in (
            "task_id",
            "binding_id",
            "workspace_lineage_id",
            "cloud_snapshot_id",
            "cloud_current_blob_sha",
            "preexisting_publish_manifest_sha256",
            "approved_publish_manifest_sha256",
            "artifact_publication_blocked",
            "state",
            "created_at",
            "updated_at",
        )
    }
    _write_portable_adoption(workspace, portable_guard)
    return guard


def _source_route_supersedes_prior_binding(
    git: GitVault,
    identity: SourceIdentity,
) -> bool:
    binding = git.show_json(
        f"bindings/confirmed/{identity.binding_id}.json"
    )
    supersedes = binding.get("supersedes_binding_id")
    return isinstance(supersedes, str) and bool(supersedes)


def _workspace_has_complete_route_guard(
    data_dir: Path,
    workspace_identity: PortableIdentity,
    session_id: str,
) -> bool:
    device = _device_state(data_dir)
    local = _load_adoption_guard(
        data_dir,
        device,
        workspace_identity.workspace_root,
        workspace_identity.task_id,
    )
    portable = _portable_adoption_for(workspace_identity)
    if local is None or not isinstance(portable, Mapping):
        return False
    records = (local[1], portable)
    if any(
        record.get("binding_id") != workspace_identity.binding_id
        or record.get("workspace_lineage_id")
        != workspace_identity.lineage_id
        for record in records
    ):
        return False
    return (
        local[1].get("expected_source_key_sha256")
        == _codex_source_key(session_id)
        and isinstance(
            local[1].get("artifact_publication_blocked"),
            bool,
        )
        and isinstance(
            portable.get("artifact_publication_blocked"),
            bool,
        )
    )


class SyncEngine:
    def __init__(self, config: Mapping[str, Any], data_dir: Path):
        self.config = validate_config(dict(config))
        self.data_dir = data_dir.resolve()
        ensure_private_dir(self.data_dir)
        self.provider_pins = _provider_transaction_pins(self.config)
        self.git = GitVault(self.config, self.data_dir)
        # ``drive`` stays as the primary-adapter compatibility seam used by
        # existing integrations and fault tests. Historical storage
        # references are routed through the per-store cache below.
        self.drive: DriveAdapter | None = None
        self.object_stores: dict[str, DriveAdapter] = {}
        self.lock_path = self.data_dir / "locks" / "sync.lock"

    def _memory_network_enabled(self) -> bool:
        # Production has one memory model.  The conditional exists solely so
        # the repository can continue to characterize import-only legacy
        # fixtures without shipping a task-binding activation path.
        if (
            self.config.get("_test_mode") is True
            and os.environ.get("MEMORY_VAULT_SYNC_TESTING") == "1"
        ):
            return bool(
                self.config["sync"].get("memory_network_enabled", True)
            )
        return True

    def _memory_index(self) -> memory_network.AssociativeIndex:
        return memory_network.AssociativeIndex(
            _memory_network_index_path(self.data_dir)
        )

    def _quarantine_memory_network_index(self) -> Path:
        """Move an incompatible derived index aside for recoverable rebuild."""

        index_path = _memory_network_index_path(self.data_dir)
        recovery = (
            self.data_dir
            / "memory-network"
            / "recovery"
            / f"index-{uuid.uuid4().hex}"
        )
        ensure_private_dir(recovery)
        for candidate in (
            index_path,
            Path(str(index_path) + "-wal"),
            Path(str(index_path) + "-shm"),
        ):
            if not candidate.exists():
                continue
            assert_plain_path(candidate, require_file=True)
            os.replace(candidate, recovery / candidate.name)
        return recovery

    def _memory_session(
        self,
        session_id: str,
        *,
        persist: bool = True,
    ) -> tuple[Path, dict[str, Any]]:
        if not isinstance(session_id, str) or not session_id:
            raise IdentityError("hook session_id is missing")
        device = _device_state(self.data_dir)
        session_key = _session_key(device, session_id)
        path = _memory_network_session_path(self.data_dir, session_key)
        source_key = _codex_source_key(session_id)
        try:
            source_id = memory_network.source_id_for_key(source_key)
        except memory_network.MemoryNetworkError as exc:
            raise VerificationError("memory source identity is invalid") from exc
        if path.exists():
            value = load_json(path)
            if (
                not isinstance(value, dict)
                or set(value)
                != {
                    "schema_version",
                    "session_key",
                    "source_key_sha256",
                    "source_id",
                    "next_source_sequence",
                    "last_episode_id",
                    "created_at",
                    "updated_at",
                }
                or value.get("schema_version")
                != MEMORY_NETWORK_SESSION_SCHEMA
                or value.get("session_key") != session_key
                or value.get("source_key_sha256") != source_key
                or value.get("source_id") != source_id
                or not isinstance(value.get("next_source_sequence"), int)
                or isinstance(value.get("next_source_sequence"), bool)
                or int(value["next_source_sequence"]) < 0
                or (
                    value.get("last_episode_id") is not None
                    and not isinstance(value.get("last_episode_id"), str)
                )
            ):
                raise ConfigurationError("local memory network session is invalid")
            return path, value
        next_sequence = 0
        last_episode_id: str | None = None
        index_path = _memory_network_index_path(self.data_dir)
        if index_path.exists():
            try:
                tip = self._memory_index().source_tip(source_id)
            except memory_network.MemoryNetworkError as exc:
                raise VerificationError("local memory index is invalid") from exc
            if tip is not None:
                next_sequence = tip[0] + 1
                last_episode_id = tip[1]
        now = utc_now()
        value = {
            "schema_version": MEMORY_NETWORK_SESSION_SCHEMA,
            "session_key": session_key,
            "source_key_sha256": source_key,
            "source_id": source_id,
            "next_source_sequence": next_sequence,
            "last_episode_id": last_episode_id,
            "created_at": now,
            "updated_at": now,
        }
        if persist:
            atomic_write_json(path, value)
        return path, value

    def _memory_network_intent_signature(
        self,
        value: Mapping[str, Any],
    ) -> str:
        unsigned = dict(value)
        unsigned.pop("integrity_hmac_sha256", None)
        device = _device_state(self.data_dir)
        return hmac.new(
            str(device["device_secret"]).encode("ascii"),
            jcs_json_bytes(unsigned),
            hashlib.sha256,
        ).hexdigest()

    def _validate_memory_network_intent_content(
        self,
        value: Any,
        *,
        schema_version: str,
        signed: bool,
    ) -> dict[str, Any]:
        fields = {
            "schema_version",
            "transaction_id",
            "session_key",
            "source_key_sha256",
            "source_id",
            "turn_key",
            "source_sequence",
            "parent_episode_ids",
            "prompt",
            "last_assistant",
            "created_at",
            "attempt_count",
        }
        if signed:
            fields.add("integrity_hmac_sha256")
        if not isinstance(value, dict) or set(value) != fields:
            raise VerificationError("memory network outbox intent is invalid")
        if value.get("schema_version") != schema_version:
            raise VerificationError("memory network outbox schema is invalid")
        if signed:
            signature = validate_sha256(
                value.get("integrity_hmac_sha256"),
                "memory network outbox integrity signature",
            )
            if not hmac.compare_digest(
                signature,
                self._memory_network_intent_signature(value),
            ):
                raise VerificationError(
                    "memory network outbox integrity check failed"
                )
        transaction = validate_identifier(
            value.get("transaction_id"), "transaction_id"
        )
        if re.fullmatch(r"tx-[0-9a-f]{32}", transaction) is None:
            raise VerificationError("memory network transaction is invalid")
        if not re.fullmatch(r"[0-9a-f]{32}", str(value.get("session_key") or "")):
            raise VerificationError("memory network session key is invalid")
        source_key = validate_sha256(
            value.get("source_key_sha256"), "memory source key"
        )
        try:
            expected_source = memory_network.source_id_for_key(source_key)
        except memory_network.MemoryNetworkError as exc:
            raise VerificationError("memory network source is invalid") from exc
        if value.get("source_id") != expected_source:
            raise VerificationError("memory network source is inconsistent")
        if not re.fullmatch(r"[0-9a-f]{32}", str(value.get("turn_key") or "")):
            raise VerificationError("memory network turn key is invalid")
        sequence = value.get("source_sequence")
        if (
            not isinstance(sequence, int)
            or isinstance(sequence, bool)
            or sequence < 0
        ):
            raise VerificationError("memory network sequence is invalid")
        parents = value.get("parent_episode_ids")
        if not isinstance(parents, list) or len(parents) > 64:
            raise VerificationError("memory network episode parents are invalid")
        normalized_parents: list[str] = []
        for parent in parents:
            normalized = validate_identifier(parent, "parent episode_id")
            if re.fullmatch(r"ep-[0-9a-f]{40}", normalized) is None:
                raise VerificationError(
                    "memory network episode parent is invalid"
                )
            normalized_parents.append(normalized)
        if len(normalized_parents) != len(set(normalized_parents)):
            raise VerificationError("memory network episode parents repeat")
        for key in ("prompt", "last_assistant"):
            text = value.get(key)
            if text is not None:
                scan_visible_text(text, f"memory network {key}")
        if value.get("prompt") is None and value.get("last_assistant") is None:
            raise VerificationError("memory network episode has no visible content")
        validate_rfc3339(value.get("created_at"), "memory network timestamp")
        attempts = value.get("attempt_count")
        if (
            not isinstance(attempts, int)
            or isinstance(attempts, bool)
            or attempts < 0
            or attempts > 1000
        ):
            raise VerificationError("memory network attempt count is invalid")
        return value

    def _validate_memory_network_intent(self, value: Any) -> dict[str, Any]:
        return self._validate_memory_network_intent_content(
            value,
            schema_version=MEMORY_NETWORK_OUTBOX_SCHEMA,
            signed=True,
        )

    def _validate_legacy_memory_network_intent(
        self,
        value: Any,
    ) -> dict[str, Any]:
        # Legacy v1 carried no authenticator.  These checks establish that its
        # shape, content, and eventual destination are safe; they cannot prove
        # that another local process did not modify it before this migration.
        return self._validate_memory_network_intent_content(
            value,
            schema_version=LEGACY_MEMORY_NETWORK_OUTBOX_SCHEMA,
            signed=False,
        )

    @staticmethod
    def _decode_memory_network_intent_document(raw: bytes) -> dict[str, Any]:
        if raw.startswith(b"\xef\xbb\xbf"):
            raise VerificationError("memory network outbox intent has a UTF-8 BOM")
        try:
            value = strict_json_loads(raw.decode("utf-8"))
        except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
            raise VerificationError(
                "memory network outbox intent is invalid JSON"
            ) from exc
        if not isinstance(value, dict):
            raise VerificationError("memory network outbox intent is invalid")
        return value

    def _memory_network_recovery_receipt(
        self,
        *,
        transaction_id: str,
        filename: str,
        raw: bytes,
    ) -> dict[str, Any]:
        receipt: dict[str, Any] = {
            "schema_version": MEMORY_NETWORK_RECOVERY_RECEIPT_SCHEMA,
            "transaction_id": validate_identifier(
                transaction_id, "transaction_id"
            ),
            "recovered_filename": filename,
            "recovered_sha256": sha256_bytes(raw),
            "recovered_size": len(raw),
            "source_schema": LEGACY_MEMORY_NETWORK_OUTBOX_SCHEMA,
            "disposition": "preserved_not_publishable",
        }
        device = _device_state(self.data_dir)
        receipt["integrity_hmac_sha256"] = hmac.new(
            str(device["device_secret"]).encode("ascii"),
            b"memory-network-outbox-recovery-receipt-v1\0"
            + jcs_json_bytes(receipt),
            hashlib.sha256,
        ).hexdigest()
        return receipt

    def _recover_legacy_memory_network_intent(
        self,
        outbox: _MemoryNetworkOutbox,
        name: str,
        raw: bytes,
        value: Any,
    ) -> None:
        # Validation proves only schema/content safety. The exact original
        # bytes remain unauthenticated and are therefore preserved, never
        # signed as v2 and never admitted to publication.
        legacy = self._validate_legacy_memory_network_intent(value)
        if name != f"{legacy['transaction_id']}.json":
            raise VerificationError("memory network outbox path is invalid")
        receipt = self._memory_network_recovery_receipt(
            transaction_id=str(legacy["transaction_id"]),
            filename=name,
            raw=raw,
        )
        receipt_name = name.removesuffix(".json") + ".receipt.json"
        # The deterministic content-free receipt is durable first. If the
        # process stops here, the next scan computes identical bytes and can
        # safely finish the original-byte recovery.
        outbox.write_new(
            "recovery-v1",
            receipt_name,
            pretty_json_bytes(receipt),
            receipt=True,
            allow_existing_equal=True,
        )
        outbox.move_to_recovery(name, expected_raw=raw)

    def _load_pending_memory_network_intent(
        self,
        outbox: _MemoryNetworkOutbox,
        name: str,
    ) -> tuple[bytes, dict[str, Any]] | None:
        raw = outbox.read("pending", name)
        value = self._decode_memory_network_intent_document(raw)
        if value.get("schema_version") == LEGACY_MEMORY_NETWORK_OUTBOX_SCHEMA:
            self._recover_legacy_memory_network_intent(
                outbox,
                name,
                raw,
                value,
            )
            return None
        validated = self._validate_memory_network_intent(value)
        if name != f"{validated['transaction_id']}.json":
            raise VerificationError("memory network outbox path is invalid")
        return raw, validated

    def _increment_memory_network_intent_attempt(
        self,
        outbox: _MemoryNetworkOutbox,
        name: str,
        expected_raw: bytes,
        intent: Mapping[str, Any],
    ) -> tuple[bytes, dict[str, Any]]:
        # Re-read through the held safe directory before signing an update. A
        # stale caller may neither overwrite nor authenticate replacement data.
        current_raw = outbox.read("pending", name)
        if current_raw != expected_raw:
            raise BusyError("memory network outbox changed before retry update")
        current = self._validate_memory_network_intent(
            self._decode_memory_network_intent_document(current_raw)
        )
        if current != dict(intent):
            raise BusyError("memory network outbox changed before retry update")
        attempts = int(current["attempt_count"])
        if attempts >= 1000:
            raise VerificationError("memory network attempt count is exhausted")
        updated = dict(current)
        updated["attempt_count"] = attempts + 1
        updated.pop("integrity_hmac_sha256", None)
        updated["integrity_hmac_sha256"] = (
            self._memory_network_intent_signature(updated)
        )
        self._validate_memory_network_intent(updated)
        updated_raw = pretty_json_bytes(updated)
        outbox.replace(
            "pending",
            name,
            expected_raw=current_raw,
            replacement_raw=updated_raw,
        )
        persisted_raw = outbox.read("pending", name)
        if persisted_raw != updated_raw:
            raise VerificationError("memory network retry update was not durable")
        return persisted_raw, updated

    def _stage_memory_network_prompt(
        self,
        *,
        session_id: str,
        turn_id: str,
        prompt: str,
    ) -> None:
        device = _device_state(self.data_dir)
        session_key = _session_key(device, session_id)
        turn_key = _turn_key(device, session_id, turn_id)
        self._memory_session(session_id)
        staged = {
            "schema_version": MEMORY_NETWORK_PROMPT_SCHEMA,
            "session_key": session_key,
            "turn_key": turn_key,
            "prompt": scan_visible_text(prompt, "visible user prompt"),
            "created_at": utc_now(),
        }
        atomic_write_json(
            _memory_network_prompt_path(
                self.data_dir, session_key, turn_key
            ),
            staged,
        )

    def _queue_memory_network_stop(
        self,
        hook_input: Mapping[str, Any],
    ) -> tuple[str, str]:
        session_id = hook_input.get("session_id")
        turn_id = hook_input.get("turn_id")
        if not isinstance(session_id, str) or not isinstance(turn_id, str):
            raise IdentityError("Stop hook is missing session or turn identity")
        device = _device_state(self.data_dir)
        session_key = _session_key(device, session_id)
        turn_key = _turn_key(device, session_id, turn_id)
        transaction = _transaction_id(device, session_id, turn_id)
        existing = _find_memory_network_outbox_state(
            self.data_dir, transaction
        )
        if existing is not None:
            return transaction, existing
        queue_lock = self.data_dir / "locks" / f"memory-queue-{session_key}.lock"
        with FileLock(queue_lock):
            existing = _find_memory_network_outbox_state(
                self.data_dir, transaction
            )
            if existing is not None:
                return transaction, existing
            session_path, session = self._memory_session(session_id)
            prompt: str | None = None
            prompt_path = _memory_network_prompt_path(
                self.data_dir, session_key, turn_key
            )
            if prompt_path.exists():
                staged = load_json(prompt_path)
                if (
                    not isinstance(staged, Mapping)
                    or staged.get("schema_version")
                    != MEMORY_NETWORK_PROMPT_SCHEMA
                    or staged.get("session_key") != session_key
                    or staged.get("turn_key") != turn_key
                ):
                    raise VerificationError(
                        "staged memory network prompt is invalid"
                    )
                prompt = scan_visible_text(
                    staged.get("prompt"), "staged visible prompt"
                )
            assistant_raw = hook_input.get("last_assistant_message")
            assistant = (
                scan_visible_text(assistant_raw, "visible assistant message")
                if isinstance(assistant_raw, str) and assistant_raw
                else None
            )
            if prompt is None and assistant is None:
                raise PrivacyError("Stop hook has no visible content to back up")
            sequence = int(session["next_source_sequence"])
            parent = session.get("last_episode_id")
            parents = [str(parent)] if isinstance(parent, str) else []
            intent = {
                "schema_version": MEMORY_NETWORK_OUTBOX_SCHEMA,
                "transaction_id": transaction,
                "session_key": session_key,
                "source_key_sha256": session["source_key_sha256"],
                "source_id": session["source_id"],
                "turn_key": turn_key,
                "source_sequence": sequence,
                "parent_episode_ids": parents,
                "prompt": prompt,
                "last_assistant": assistant,
                "created_at": utc_now(),
                "attempt_count": 0,
            }
            intent["integrity_hmac_sha256"] = (
                self._memory_network_intent_signature(intent)
            )
            self._validate_memory_network_intent(intent)
            with _MemoryNetworkOutbox(self.data_dir) as outbox:
                outbox.write_new(
                    "pending",
                    f"{transaction}.json",
                    pretty_json_bytes(intent),
                )
            try:
                episode_id = memory_network.episode_id_for_turn(
                    str(session["source_key_sha256"]), turn_key
                )
            except memory_network.MemoryNetworkError as exc:
                raise VerificationError("memory episode identity is invalid") from exc
            session["next_source_sequence"] = sequence + 1
            session["last_episode_id"] = episode_id
            session["updated_at"] = utc_now()
            atomic_write_json(session_path, session)
            with contextlib.suppress(FileNotFoundError):
                prompt_path.unlink()
        return transaction, "pending"

    def _pending_memory_network_intents(
        self,
        outbox: _MemoryNetworkOutbox | None = None,
    ) -> list[tuple[str, bytes, dict[str, Any]]]:
        owned = outbox is None
        active = outbox or _MemoryNetworkOutbox(self.data_dir)
        if owned:
            active.__enter__()
        try:
            names = active.list_raw_names("pending")
            if len(names) > 100_000:
                raise VerificationError(
                    "memory network outbox exceeds its safety limit"
                )
            candidates: list[tuple[str, bytes, dict[str, Any]]] = []
            for name in names:
                loaded = self._load_pending_memory_network_intent(active, name)
                if loaded is None:
                    continue
                raw, value = loaded
                candidates.append((name, raw, value))
        finally:
            if owned:
                active.__exit__(*sys.exc_info())
        candidates.sort(
            key=lambda item: (str(item[2]["created_at"]), str(item[2]["transaction_id"]))
        )
        selected: list[tuple[str, bytes, dict[str, Any]]] = []
        total = 0
        for item in candidates:
            size = len(canonical_json_bytes(item[2]))
            if selected and (
                len(selected) >= MAX_MEMORY_NETWORK_BATCH_ITEMS
                or total + size > MAX_MEMORY_NETWORK_BATCH_BYTES
            ):
                break
            selected.append(item)
            total += size
        return selected

    def _memory_network_files(
        self,
        intent: Mapping[str, Any],
    ) -> tuple[dict[str, bytes], str, str]:
        validated = self._validate_memory_network_intent(dict(intent))
        try:
            (episode_path, episode), (event_path, event) = (
                memory_network.build_episode_packet(
                    source_key_sha256=str(validated["source_key_sha256"]),
                    turn_key=str(validated["turn_key"]),
                    source_sequence=int(validated["source_sequence"]),
                    prompt=validated.get("prompt"),
                    assistant=validated.get("last_assistant"),
                    created_at=str(validated["created_at"]),
                    parent_episode_ids=list(validated["parent_episode_ids"]),
                )
            )
        except memory_network.MemoryNetworkError as exc:
            raise VerificationError("memory episode packet is invalid") from exc
        if episode.get("source_id") != validated.get("source_id"):
            raise VerificationError("memory episode source changed while queued")
        files = {
            episode_path: pretty_json_bytes(episode),
            event_path: pretty_json_bytes(event),
        }
        for path, raw in files.items():
            document = strict_json_loads(raw.decode("utf-8"))
            if not isinstance(document, Mapping):
                raise VerificationError("memory packet is not an object")
            assert_remote_safe(document)
            _validate_generated_document(path, document)
        return files, str(episode["episode_id"]), str(event["memory_event_id"])

    def _finish_memory_network_intent(
        self,
        outbox: _MemoryNetworkOutbox,
        pending_name: str,
        pending_raw: bytes,
        intent: Mapping[str, Any],
        *,
        episode_id: str,
        event_id: str,
        remote_commit: str,
    ) -> None:
        receipt = {
            "schema_version": MEMORY_NETWORK_RECEIPT_SCHEMA,
            "transaction_id": intent["transaction_id"],
            "episode_id": episode_id,
            "memory_event_id": event_id,
            "remote_commit_sha": validate_git_sha(
                remote_commit, "memory network remote commit"
            ),
            "result": "published",
            "finished_at": utc_now(),
        }
        receipt_raw = pretty_json_bytes(receipt)
        outbox.write_new(
            "done",
            f"{intent['transaction_id']}.json",
            receipt_raw,
            allow_existing_equal=True,
        )
        outbox.unlink(
            "pending",
            pending_name,
            expected_raw=pending_raw,
        )

    def _publish_memory_network_batch(
        self,
        *,
        remote_ready: bool = False,
    ) -> Mapping[str, Any]:
        with _MemoryNetworkOutbox(self.data_dir) as outbox:
            batch = self._pending_memory_network_intents(outbox)
            if not batch:
                return {"state": "idle", "published": 0}
            # One counter advance represents one top-level flush attempt.
            # Compare-and-replace the exact authenticated bytes through the
            # held directory before any network I/O.
            batch = [
                (
                    pending_name,
                    *self._increment_memory_network_intent_attempt(
                        outbox,
                        pending_name,
                        pending_raw,
                        intent,
                    ),
                )
                for pending_name, pending_raw, intent in batch
            ]
        if not remote_ready:
            # Do not pre-fetch on the ordinary Stop path.  The immutable
            # additions are attempted against the verified cached head; a
            # non-fast-forward fetches and replays once below.  We still repeat
            # the repository privacy proof before any publication.
            if self.git.has_cache():
                self.git.ensure(fetch_remote=False)
            else:
                self.git.ensure()
        elif not self.git.has_cache():
            self.git.ensure()
        prepared: list[
            tuple[str, bytes, dict[str, Any], dict[str, bytes], str, str]
        ] = []
        generated: dict[str, bytes] = {}
        for pending_name, pending_raw, intent in batch:
            files, episode_id, event_id = self._memory_network_files(intent)
            for path, raw in files.items():
                if path in generated and generated[path] != raw:
                    raise ConflictError("memory batch contains an identity collision")
                if self.git.file_exists(path):
                    if self.git.show_bytes(path) != raw:
                        raise ConflictError(
                            "immutable memory path contains different evidence"
                        )
                    continue
                generated[path] = raw
            prepared.append(
                (
                    pending_name,
                    pending_raw,
                    intent,
                    files,
                    episode_id,
                    event_id,
                )
            )
        before = self.git.head_sha()
        commit = before
        if generated:
            batch_id = validate_identifier(
                "net-"
                + sha256_bytes(
                    "\0".join(
                        str(item[2]["transaction_id"]) for item in prepared
                    ).encode("ascii")
                )[:40],
                "memory network batch_id",
            )
            remaining = dict(generated)
            for attempt in range(2):
                base = self.git.head_sha()
                try:
                    with self.git.create_worktree() as worktree:
                        self.git.write_generated_files(worktree, remaining)
                        self._validate_worktree(worktree, remaining)
                        commit = self.git.commit_and_push(
                            worktree,
                            remaining,
                            "memory-network",
                            batch_id,
                        )
                    self.git.accept_pushed_commit(base, commit)
                    break
                except VaultSyncError:
                    # Immutable memory additions commute.  If another device
                    # advanced the branch, fetch once, prove any overlapping
                    # paths byte-for-byte, and replay only the still-missing
                    # additions.  Other failures remain queued without a loop.
                    self.git.fetch()
                    advanced = self.git.head_sha() != base
                    if attempt != 0 or not advanced:
                        raise
                    next_remaining: dict[str, bytes] = {}
                    for path, raw in remaining.items():
                        if self.git.file_exists(path):
                            if self.git.show_bytes(path) != raw:
                                raise ConflictError(
                                    "concurrent memory path contains different evidence"
                                )
                        else:
                            next_remaining[path] = raw
                    remaining = next_remaining
                    if not remaining:
                        commit = self.git.head_sha()
                        break
        head = self.git.head_sha()
        self.git.assert_ancestor(commit, head)
        with _MemoryNetworkOutbox(self.data_dir) as outbox:
            for (
                pending_name,
                pending_raw,
                intent,
                files,
                episode_id,
                event_id,
            ) in prepared:
                persisted_raw = outbox.read("pending", pending_name)
                if persisted_raw != pending_raw:
                    raise BusyError(
                        "memory network outbox changed before completion"
                    )
                self._validate_memory_network_intent(
                    self._decode_memory_network_intent_document(persisted_raw)
                )
                for path, raw in files.items():
                    if self.git.show_bytes(path) != raw:
                        raise VerificationError(
                            "published memory packet failed remote verification"
                        )
                self._finish_memory_network_intent(
                    outbox,
                    pending_name,
                    pending_raw,
                    intent,
                    episode_id=episode_id,
                    event_id=event_id,
                    remote_commit=head,
                )
        receive = self._receive_memory_network()
        return {
            "state": "published",
            "published": len(prepared),
            "remote_head": head,
            "receive": receive,
        }

    def _memory_documents_for_paths(
        self,
        path_blobs: Mapping[str, str],
        *,
        blob_values: Mapping[str, bytes] | None = None,
    ) -> tuple[list[memory_network.IndexedDocument], int]:
        documents: list[memory_network.IndexedDocument] = []
        skipped_legacy_revisions = 0
        source_cache: dict[str, Mapping[str, Any]] = {}
        episode_cache: dict[str, Mapping[str, Any]] = {}
        if blob_values is None:
            blob_values = self.git.show_blob_bytes_many(
                list(path_blobs.values())
            )
        for path in sorted(path_blobs):
            blob = validate_git_sha(path_blobs[path], "memory document blob")
            try:
                raw = blob_values[blob]
            except KeyError as exc:
                raise VerificationError(
                    "remote memory blob batch is incomplete"
                ) from exc
            if not isinstance(raw, bytes):
                raise VerificationError("remote memory blob batch is invalid")
            try:
                value = strict_json_loads(raw.decode("utf-8"))
            except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
                raise VerificationError("remote memory document is invalid JSON") from exc
            if not isinstance(value, Mapping):
                raise VerificationError("remote memory document is not an object")
            source_sequence: int | None = None
            if re.fullmatch(r"memory/episodes/[0-9a-f]{2}/[^/]+\.json", path):
                _validate_memory_episode(value)
                _validate_generated_document(path, value)
                source_sequence = int(value["source_sequence"])
                episode_cache[str(value["episode_id"])] = value
            elif re.fullmatch(
                r"memory/events/(?:[0-9a-f]{2}/)?[^/]+\.json", path
            ):
                match = re.fullmatch(
                    r"memory/events/(?:[0-9a-f]{2}/)?([^/]+)\.json", path
                )
                assert match is not None
                _validate_generated_document(path, value)
                source = value.get("source")
                if not isinstance(source, Mapping):
                    raise VerificationError("memory event source is invalid")
                source_sequence = int(source["source_sequence"])
                if (
                    value.get("schema_version")
                    == memory_network.MEMORY_EVENT_SCHEMA
                ):
                    episode_id = str(source["revision_id"])
                    episode_path = (
                        f"memory/episodes/{episode_id[3:5]}/"
                        f"{episode_id}.json"
                    )
                    episode = episode_cache.get(episode_id)
                    if episode is None:
                        if not self.git.file_exists(episode_path):
                            raise VerificationError(
                                "taskless memory event has no immutable episode"
                            )
                        episode = self.git.show_json(episode_path)
                    _validate_v2_event_episode(
                        value,
                        episode,
                    )
            else:
                revision_match = re.fullmatch(
                    r"sources/([^/]+)/revisions/([^/]+)\.json", path
                )
                if revision_match is None:
                    continue
                if value.get("schema_version") != "conversation-export/v1":
                    skipped_legacy_revisions += 1
                    continue
                try:
                    _validate_conversation_export(value)
                    source_id = revision_match.group(1)
                    revision_id = revision_match.group(2)
                    if value.get("source_id") != source_id:
                        raise VerificationError(
                            "legacy conversation source is inconsistent"
                        )
                    source = source_cache.get(source_id)
                    source_path = f"sources/{source_id}/SOURCE.json"
                    if source is None and self.git.file_exists(source_path):
                        source = self.git.show_json(source_path)
                        _validate_source(source)
                        source_cache[source_id] = source
                    if source is None:
                        # Early vaults retained some immutable conversation
                        # blobs only through a version manifest. They remain
                        # reference memory but never acquire task authority.
                        source_sequence = 0
                    else:
                        revision = next(
                            (
                                item
                                for item in source.get("revisions", [])
                                if isinstance(item, Mapping)
                                and item.get("revision_id") == revision_id
                            ),
                            None,
                        )
                        if not isinstance(revision, Mapping):
                            raise VerificationError(
                                "legacy conversation revision is not retained"
                            )
                        content_ref = revision.get("content_ref")
                        if (
                            revision.get("content_sha256")
                            != sha256_bytes(raw)
                            or not isinstance(content_ref, Mapping)
                            or content_ref.get("object_id")
                            != git_blob_sha(raw)
                            or content_ref.get("byte_size") != len(raw)
                        ):
                            raise VerificationError(
                                "legacy conversation revision failed "
                                "integrity validation"
                            )
                        source_sequence = int(revision["source_sequence"])
                except VaultSyncError:
                    # Legacy revisions are optional migration evidence. A
                    # malformed or unretained legacy record must never enter
                    # recall, but it also must not block valid taskless
                    # episode/event receive on a long-lived private vault.
                    skipped_legacy_revisions += 1
                    continue
            documents.append(
                memory_network.IndexedDocument(
                    path=path,
                    blob_sha=blob,
                    value=value,
                    source_sequence=source_sequence,
                )
            )
        return documents, skipped_legacy_revisions

    def _receive_memory_network(self) -> Mapping[str, Any]:
        index = self._memory_index()
        head = self.git.head_sha()
        try:
            cursor = index.remote_head()
            known = index.document_versions()
        except memory_network.MemoryNetworkError:
            # The index contains no unique durable state.  Preserve its bytes
            # locally for diagnosis, then rebuild from verified remote objects
            # instead of blocking the user's memory forever after an upgrade.
            self._quarantine_memory_network_index()
            index = self._memory_index()
            cursor = None
            known = {}
        if cursor == head:
            return {
                "state": "current",
                "remote_head": head,
                "documents": 0,
                "fragments": 0,
            }
        selected: dict[str, str] = {}
        immutable_patterns = (
            re.compile(r"memory/episodes/[0-9a-f]{2}/[^/]+\.json"),
            re.compile(r"memory/events/(?:[0-9a-f]{2}/)?[^/]+\.json"),
            re.compile(r"sources/[^/]+/revisions/[^/]+\.json"),
        )
        if cursor is None:
            listing = self.git.list_blob_paths(
                ["memory/episodes", "memory/events", "sources"]
            )
            selected = {
                path: blob
                for path, blob in listing.items()
                if any(pattern.fullmatch(path) for pattern in immutable_patterns)
            }
        else:
            changes = self.git.changed_paths_between(
                cursor,
                head,
                ["memory/episodes", "memory/events", "sources"],
            )
            for path, status in changes.items():
                immutable = any(
                    pattern.fullmatch(path) for pattern in immutable_patterns
                )
                if immutable and status != "A":
                    raise VerificationError(
                        "append-only remote memory was modified or removed"
                    )
                if re.fullmatch(r"sources/[^/]+/SOURCE\.json", path):
                    if status == "D":
                        raise VerificationError("legacy memory source was removed")
                    source_id = path.split("/")[1]
                    _assert_source_append_only(self.git, source_id)
                if immutable and status == "A":
                    selected[path] = self.git.blob_sha(path)
        for path, expected_blob in selected.items():
            observed = known.get(path)
            if observed is not None and observed != expected_blob:
                raise VerificationError(
                    "indexed immutable memory changed in remote history"
                )
        documents, skipped_legacy_revisions = (
            self._memory_documents_for_paths(selected)
        )
        available_paths = set(known) | set(selected)
        for document in documents:
            if (
                document.value.get("schema_version")
                != memory_network.MEMORY_EVENT_SCHEMA
            ):
                continue
            for relation in (
                "parents",
                "supersedes",
                "conflicts_with",
                "resolves",
            ):
                for target in document.value[relation]:
                    if (
                        memory_network.event_relative_path(target)
                        not in available_paths
                    ):
                        raise VerificationError(
                            "taskless memory graph has a missing relation target"
                        )
        try:
            result = index.apply(documents, remote_head=head)
        except memory_network.MemoryNetworkError as exc:
            raise VerificationError("memory index update failed") from exc
        return {
            "state": "updated",
            **result,
            "skipped_legacy_revisions": skipped_legacy_revisions,
        }

    def memory_network_session_start(
        self,
        hook_input: Mapping[str, Any],
    ) -> dict[str, Any]:
        if hook_input.get("hook_event_name") != "SessionStart":
            raise PrivacyError("wrong hook event for memory session-start")
        if not self.config.get("enabled"):
            return hook_json("SessionStart")
        session_id = hook_input.get("session_id")
        if isinstance(session_id, str):
            self._memory_session(session_id)
        if hook_input.get("source") == "compact":
            return hook_json("SessionStart")
        if hook_input.get("source") not in {"startup", "resume", "clear"}:
            return hook_json("SessionStart")
        if not self.config["sync"].get("startup_pull", True):
            return hook_json("SessionStart")
        warning: str | None = None
        with FileLock(self.lock_path):
            try:
                self.git.ensure()
                if self.config["sync"].get("stop_publish", True):
                    publication = self._publish_memory_network_batch(
                        remote_ready=True
                    )
                    if publication.get("state") == "idle":
                        self._receive_memory_network()
                else:
                    self._receive_memory_network()
            except OfflineError:
                warning = (
                    "Private Memory Network is offline; locally indexed memory "
                    "remains available and new visible turns stay queued."
                )
            except ConflictError:
                warning = (
                    "Private Memory Network detected rewritten remote history; "
                    "the last verified local index remains reference-only."
                )
        return hook_json("SessionStart", warning=warning)

    def memory_network_user_prompt_submit(
        self,
        hook_input: Mapping[str, Any],
    ) -> dict[str, Any]:
        if hook_input.get("hook_event_name") != "UserPromptSubmit":
            raise PrivacyError("wrong hook event for memory prompt")
        if not self.config.get("enabled"):
            return hook_json("UserPromptSubmit")
        session_id = hook_input.get("session_id")
        turn_id = hook_input.get("turn_id")
        raw_prompt = hook_input.get("prompt")
        if (
            not isinstance(session_id, str)
            or not isinstance(turn_id, str)
            or not isinstance(raw_prompt, str)
        ):
            return hook_json("UserPromptSubmit")
        try:
            prompt = scan_visible_text(raw_prompt, "visible user prompt")
            if self.config["sync"].get("conversation_backup", True):
                self._stage_memory_network_prompt(
                    session_id=session_id,
                    turn_id=turn_id,
                    prompt=prompt,
                )
        except PrivacyError:
            return hook_json(
                "UserPromptSubmit",
                warning=(
                    "This visible turn contains private local data and was not "
                    "queued or used for associative recall."
                ),
            )
        context: str | None = None
        if self.config["sync"].get("associative_recall_enabled", True):
            index_path = _memory_network_index_path(self.data_dir)
            if index_path.exists():
                try:
                    hits = self._memory_index().query(
                        prompt,
                        limit=int(
                            self.config["sync"].get(
                                "memory_recall_limit",
                                DEFAULT_MEMORY_RECALL_LIMIT,
                            )
                        ),
                    )
                    context = memory_network.format_recall_context(
                        hits,
                        maximum_bytes=int(
                            self.config["sync"].get(
                                "memory_recall_context_bytes",
                                DEFAULT_MEMORY_RECALL_CONTEXT_BYTES,
                            )
                        ),
                    )
                    if context is not None:
                        scan_visible_text(context, "associative memory context")
                except memory_network.MemoryNetworkError:
                    return hook_json(
                        "UserPromptSubmit",
                        warning=(
                            "The derived local memory index needs a verified "
                            "SessionStart rebuild; this turn remains queued."
                        ),
                    )
        return hook_json("UserPromptSubmit", context=context)

    def memory_network_stop(
        self,
        hook_input: Mapping[str, Any],
    ) -> dict[str, Any]:
        if hook_input.get("hook_event_name") != "Stop":
            raise PrivacyError("wrong hook event for memory stop")
        if not self.config.get("enabled") or not self.config["sync"].get(
            "conversation_backup", True
        ):
            return hook_json("Stop")
        try:
            transaction, state = self._queue_memory_network_stop(hook_input)
        except (PrivacyError, VerificationError) as exc:
            session_id = hook_input.get("session_id")
            turn_id = hook_input.get("turn_id")
            if isinstance(session_id, str) and isinstance(turn_id, str):
                device = _device_state(self.data_dir)
                transaction = _transaction_id(device, session_id, turn_id)
                quarantine = {
                        "schema_version": "memory-network-quarantine/v1",
                        "transaction_id": transaction,
                        "reason_code": exc.code,
                        "content_preserved": False,
                        "created_at": utc_now(),
                }
                name = f"{transaction}.json"
                with _MemoryNetworkOutbox(self.data_dir) as outbox:
                    if not outbox.exists("quarantine", name):
                        outbox.write_new(
                            "quarantine",
                            name,
                            pretty_json_bytes(quarantine),
                        )
            return hook_json(
                "Stop",
                warning=(
                    "The visible memory packet failed its privacy or integrity "
                    "check and was not transmitted."
                ),
            )
        if state in {"done", "quarantine"}:
            return hook_json("Stop")
        if not self.config["sync"].get("stop_publish", True):
            return hook_json(
                "Stop",
                warning="The visible memory packet is safely queued locally.",
            )
        try:
            with FileLock(self.lock_path):
                result = self._publish_memory_network_batch()
        except BusyError:
            return hook_json(
                "Stop",
                warning=(
                    "The visible memory packet is safely queued and will join "
                    "the next incremental transfer."
                ),
            )
        except (OfflineError, ConflictError):
            return hook_json(
                "Stop",
                warning=(
                    "The visible memory packet is safely queued; another "
                    "connection will transmit it without rebuilding old memory."
                ),
            )
        if result.get("state") == "published":
            return hook_json("Stop")
        return hook_json(
            "Stop",
            warning="The visible memory packet is safely queued locally.",
        )

    def recall_memory(
        self,
        query: str,
        *,
        limit: int = DEFAULT_MEMORY_RECALL_LIMIT,
    ) -> Mapping[str, Any]:
        if not self._memory_network_enabled():
            raise ConfigurationError("taskless memory network is not enabled")
        query = scan_visible_text(query, "associative memory query")
        if not _memory_network_index_path(self.data_dir).exists():
            hits: list[memory_network.RecallHit] = []
        else:
            try:
                hits = self._memory_index().query(query, limit=limit)
            except memory_network.MemoryNetworkError as exc:
                raise VerificationError("local memory index is invalid") from exc
        context = memory_network.format_recall_context(
            hits,
            maximum_bytes=int(
                self.config["sync"].get(
                    "memory_recall_context_bytes",
                    DEFAULT_MEMORY_RECALL_CONTEXT_BYTES,
                )
            ),
        )
        return {
            "schema_version": "memory-network-recall/v2",
            "query_sha256": sha256_bytes(query.encode("utf-8")),
            "network_accessed": False,
            "retrieval_mode": "hybrid_local",
            "semantic_adapter": memory_network.SEMANTIC_ADAPTER,
            "lexical_fallback": True,
            "result_count": len(hits),
            "hits": [
                {
                    **dataclasses.asdict(hit),
                    "score": round(hit.score, 6),
                }
                for hit in hits
            ],
            "context": context,
        }

    def memory_network_views(
        self,
        *,
        claim_key: str | None = None,
        limit: int = 256,
        include_proposals: bool = True,
    ) -> Mapping[str, Any]:
        """Return a bounded, rebuildable current-claim projection."""

        if not self._memory_network_enabled():
            raise ConfigurationError("taskless memory network is not enabled")
        index_path = _memory_network_index_path(self.data_dir)
        if not index_path.exists():
            return {
                "schema_version": "memory-network-views/v1",
                "contract": "memory-network-current-view/v1",
                "claims": [],
                "consolidation_proposals": [],
            }
        try:
            return self._memory_index().claim_views(
                claim_key=claim_key,
                limit=limit,
                include_proposals=include_proposals,
            )
        except memory_network.MemoryNetworkError as exc:
            raise VerificationError(
                "derived claim view needs a verified rebuild"
            ) from exc

    def pack_memory_network(self, output_path: Path) -> Mapping[str, Any]:
        """Stream a verified portable bundle into a bounded memory pack."""

        output = output_path.expanduser().resolve()
        if output.exists():
            raise ConflictError("memory pack destination already exists")
        ensure_private_dir(output.parent)
        temporary = output.parent / f".{output.name}.{secrets.token_hex(8)}.zip"
        try:
            self.export_memory_network(temporary)
            summary = packs.pack_zip_archive(temporary, output)
        except packs.PackError as exc:
            raise VerificationError("memory pack could not be created") from exc
        finally:
            temporary.unlink(missing_ok=True)
        return {
            "schema_version": "memory-network-pack-result/v1",
            "output": str(output),
            "object_count": summary.object_count,
            "raw_bytes": summary.raw_bytes,
            "pack_bytes": summary.pack_bytes,
            "pack_sha256": summary.sha256,
            "object_root_sha256": summary.object_root_sha256,
        }

    def import_memory_pack(self, pack_path: Path) -> Mapping[str, Any]:
        """Verify and restore a pack through the canonical bundle importer."""

        source = pack_path.expanduser()
        assert_plain_path(source, require_file=True)
        source = source.resolve(strict=True)
        temporary = self.data_dir / f".memory-pack-{secrets.token_hex(8)}.zip"
        try:
            packs.unpack_to_zip(source, temporary)
            return self.import_memory_network(temporary)
        except packs.PackError as exc:
            raise VerificationError("memory pack is invalid") from exc
        finally:
            temporary.unlink(missing_ok=True)

    def copy_memory_pack(
        self,
        pack_path: Path,
        output_path: Path,
        journal_path: Path,
    ) -> Mapping[str, Any]:
        """Resume a verified pack copy using a bounded private journal."""

        source = pack_path.expanduser().resolve(strict=True)
        output = output_path.expanduser().resolve()
        journal = journal_path.expanduser().resolve()
        assert_plain_path(source, require_file=True)
        if output == source or journal in {source, output}:
            raise ConflictError("pack source, destination and journal must differ")
        ensure_private_dir(output.parent)
        ensure_private_dir(journal.parent)
        try:
            result = transport.resumable_copy(source, output, journal)
        except transport.TransportError as exc:
            raise VerificationError("memory pack copy could not resume safely") from exc
        return {
            "schema_version": "memory-network-pack-copy-result/v1",
            "output": str(output),
            "journal": str(journal),
            "source_sha256": result.source_sha256,
            "source_bytes": result.source_bytes,
            "copied_bytes": result.copied_bytes,
            "resumed": result.resumed,
            "complete": result.complete,
        }

    def checkpoint_memory_pack(
        self,
        pack_path: Path,
        output_path: Path,
        *,
        generation: int,
        previous_checkpoint_sha256: str | None = None,
    ) -> Mapping[str, Any]:
        """Create a hash checkpoint; signature/trust distribution stays external."""

        output = output_path.expanduser().resolve()
        if output.exists():
            raise ConflictError("checkpoint destination already exists")
        source = pack_path.expanduser()
        assert_plain_path(source, require_file=True)
        try:
            with packs.PackReader(source.resolve(strict=True)) as reader:
                summary = reader.verify()
        except packs.PackError as exc:
            raise VerificationError("memory pack is invalid") from exc
        remote_head = self._memory_index().remote_head()
        if not remote_head:
            raise VerificationError("memory network has no verified remote head")
        value = checkpoint.build_checkpoint(
            object_root_sha256=summary.object_root_sha256,
            remote_commit_sha=remote_head,
            generation=generation,
            object_count=summary.object_count,
            previous_checkpoint_sha256=previous_checkpoint_sha256,
        )
        ensure_private_dir(output.parent)
        descriptor, temporary_name = tempfile.mkstemp(
            prefix=f".{output.name}.", suffix=".tmp", dir=str(output.parent)
        )
        os.close(descriptor)
        temporary = Path(temporary_name)
        try:
            temporary.write_bytes(canonical_json_bytes(value))
            temporary.chmod(0o600)
            os.replace(temporary, output)
        finally:
            temporary.unlink(missing_ok=True)
        return {
            "schema_version": "memory-network-checkpoint-result/v1",
            "output": str(output),
            "checkpoint_sha256": value["checkpoint_sha256"],
            "generation": value["generation"],
            "object_count": value["object_count"],
        }

    def verify_network_checkpoint(
        self,
        checkpoint_path: Path,
        *,
        trusted_checkpoint_sha256: str | None = None,
    ) -> Mapping[str, Any]:
        source = checkpoint_path.expanduser().resolve(strict=True)
        assert_plain_path(source, require_file=True)
        if source.stat().st_size > 16 * 1024:
            raise VerificationError("checkpoint is too large")
        try:
            value = strict_json_loads(source.read_text(encoding="utf-8"))
            verified = checkpoint.verify_checkpoint(value)
            if trusted_checkpoint_sha256 is not None:
                checkpoint.verify_chain(
                    [verified],
                    trusted_checkpoint_sha256=trusted_checkpoint_sha256,
                )
        except (OSError, UnicodeDecodeError, ValueError) as exc:
            raise VerificationError("checkpoint is invalid") from exc
        return {
            "schema_version": "memory-network-checkpoint-verification/v1",
            "valid": True,
            "checkpoint_sha256": verified["checkpoint_sha256"],
            "generation": verified["generation"],
            "object_count": verified["object_count"],
            "trusted_anchor_checked": trusted_checkpoint_sha256 is not None,
        }

    def _device_trust_state_path(self, requested: Path | None = None) -> Path:
        """Resolve a device-trust state strictly inside private plugin data."""

        # Resolve platform-owned aliases such as macOS /var -> /private/var;
        # an application-created link that escapes this root is rejected by
        # the containment check below.
        root = self.data_dir.resolve()
        candidate = (
            _memory_network_device_trust_path(root)
            if requested is None
            else requested.expanduser().resolve(strict=False)
        )
        try:
            relative = candidate.relative_to(root)
        except ValueError as exc:
            raise PrivacyError(
                "device trust state must remain inside private plugin data"
            ) from exc
        current = root
        for component in relative.parts[:-1]:
            current = current / component
            try:
                observed = current.lstat()
            except FileNotFoundError:
                current.mkdir()
                _safe_chmod(current, 0o700)
                observed = current.lstat()
            except OSError as exc:
                raise PrivacyError(
                    "device trust state directory could not be inspected"
                ) from exc
            if (
                not stat.S_ISDIR(observed.st_mode)
                or stat.S_ISLNK(observed.st_mode)
                or _is_reparse_point(current)
            ):
                raise PrivacyError(
                    "device trust state directory links are forbidden"
                )
        assert_plain_directory_chain(root, candidate.parent)
        if os.path.lexists(candidate):
            assert_plain_path(candidate, require_file=True)
        return candidate

    @staticmethod
    def _device_trust_summary(
        state: device_trust.TrustState,
        path: Path,
        *,
        created: bool,
    ) -> Mapping[str, Any]:
        return {
            "schema_version": "memory-device-trust-status/v1",
            "state_path": str(path),
            "state_sha256": state.sha256,
            "installation_fingerprint": state.installation_fingerprint,
            "generation": state.generation,
            "key_epoch": state.key_epoch,
            "recovery_epoch": state.recovery_epoch,
            "recovery_threshold": state.recovery_threshold,
            "device_count": len(state.devices),
            "active_device_count": sum(
                item.status == "active" for item in state.devices
            ),
            "revoked_device_count": sum(
                item.status == "revoked" for item in state.devices
            ),
            "device_fingerprints": [
                item.device_fingerprint for item in state.devices
            ],
            "created": created,
            "external_authority_configured": False,
            "private_keys_present": False,
        }

    def initialize_device_trust_state(
        self,
        *,
        installation_fingerprint: str,
        device_fingerprint: str,
        public_key_fingerprint: str,
        key_epoch: int = 1,
        state_path: Path | None = None,
    ) -> Mapping[str, Any]:
        """Bootstrap opaque local trust metadata without generating secrets.

        This creates only a versioned state file.  Enrolling other devices,
        changing the recovery quorum, rotating keys, signing catalogs, and
        producing encrypted recovery material remain external authority
        operations and are intentionally unavailable here.
        """

        path = self._device_trust_state_path(state_path)
        if os.path.lexists(path):
            raise ConflictError("device trust state already exists")
        try:
            state = device_trust.new_trust_state(
                installation_fingerprint,
                device_fingerprint,
                public_key_fingerprint,
                key_epoch=key_epoch,
            )
        except device_trust.DeviceTrustError as exc:
            raise ConfigurationError(str(exc)) from exc
        atomic_write_json(path, state.as_dict())
        assert_plain_directory_chain(self.data_dir, path.parent)
        assert_plain_path(path, require_file=True)
        return self._device_trust_summary(state, path, created=True)

    def device_trust_status(self, state_path: Path | None = None) -> Mapping[str, Any]:
        """Read and validate opaque local trust metadata without network I/O."""

        path = self._device_trust_state_path(state_path)
        if not path.exists():
            raise IdentityError("device trust state has not been initialized")
        assert_plain_path(path, require_file=True)
        try:
            if path.stat().st_size > 256 * 1024:
                raise device_trust.DeviceTrustError(
                    "device trust state exceeds the local size bound"
                )
            state = device_trust.TrustState.from_value(load_json(path))
        except (OSError, PrivacyError, ConfigurationError, device_trust.DeviceTrustError) as exc:
            raise VerificationError("device trust state is invalid") from exc
        return self._device_trust_summary(state, path, created=False)

    def share_memory_network(
        self,
        selector: Mapping[str, Any],
        output_path: Path,
        *,
        recipient_fingerprint: str,
        key_epoch: int,
    ) -> Mapping[str, Any]:
        """Select a closed subgraph and require an audited crypto provider.

        The current production configuration intentionally has no provider.
        The temporary verified share is deleted when provider setup fails, so
        this command cannot silently produce or leave a plaintext handoff.
        """

        parsed = sharing.parse_selector(selector)
        recipient_fingerprint = crypto_adapter.validate_recipient_fingerprint(
            recipient_fingerprint
        )
        output = output_path.expanduser().resolve()
        if output.exists():
            raise ConflictError("encrypted share destination already exists")
        ensure_private_dir(output.parent)
        source_bundle = self.data_dir / f".memory-share-source-{secrets.token_hex(8)}.zip"
        plaintext_share = self.data_dir / f".memory-share-plaintext-{secrets.token_hex(8)}.zip"
        try:
            self.export_memory_network(source_bundle)
            summary = sharing.select_subgraph(source_bundle, plaintext_share, parsed)
            envelope = crypto_adapter.seal_with_provider(
                plaintext_share,
                output,
                crypto_adapter.UnconfiguredCryptoProvider(),
                capability_scope_sha256=summary.selector_sha256,
                key_epoch=key_epoch,
            )
        except sharing.ShareError as exc:
            raise VerificationError("memory share selection is invalid") from exc
        except crypto_adapter.CryptoUnavailable as exc:
            raise ConfigurationError(str(exc)) from exc
        except crypto_adapter.CryptoError as exc:
            raise VerificationError("memory share envelope could not be created") from exc
        finally:
            source_bundle.unlink(missing_ok=True)
            plaintext_share.unlink(missing_ok=True)
        return {
            "schema_version": "memory-share-result/v1",
            "output": str(output),
            "ciphertext_bytes": envelope.ciphertext_bytes,
            "ciphertext_sha256": envelope.ciphertext_sha256,
            "recipient_fingerprint": envelope.recipient_fingerprint,
            "key_epoch": envelope.key_epoch,
            "capability_scope_sha256": envelope.capability_scope_sha256,
            "crypto_profile": envelope.crypto_profile,
            "provider_version": envelope.provider_version,
        }

    def verify_memory_share_envelope(self, envelope_path: Path) -> Mapping[str, Any]:
        """Verify only the opaque envelope; never decrypt or expose payload."""

        try:
            header, key_epoch = crypto_adapter.read_envelope(
                envelope_path.expanduser().resolve(strict=True)
            )
        except crypto_adapter.CryptoError as exc:
            raise VerificationError("memory share envelope is invalid") from exc
        return {
            "schema_version": "memory-share-envelope-verification/v1",
            "valid": True,
            "crypto_profile": header["crypto_profile"],
            "provider_version": header["provider_version"],
            "recipient_fingerprint": header["recipient_fingerprint"],
            "key_epoch": key_epoch,
            "ciphertext_bytes": header["ciphertext_bytes"],
            "ciphertext_sha256": header["ciphertext_sha256"],
            "capability_scope_sha256": header["capability_scope_sha256"],
        }

    def export_memory_network(self, output_path: Path) -> Mapping[str, Any]:
        """Export a self-verifying taskless memory graph to one local bundle."""

        output = output_path.expanduser().resolve()
        if output.exists():
            raise ConflictError("memory network export destination already exists")
        ensure_private_dir(output.parent)
        with FileLock(self.lock_path):
            self.git.ensure()
            listing = self.git.list_blob_paths(
                ["memory/episodes", "memory/events", "sources"],
                maximum=MAX_MEMORY_NETWORK_BUNDLE_ENTRIES * 2,
            )
            episode_paths = {
                path: blob
                for path, blob in listing.items()
                if re.fullmatch(
                    r"memory/episodes/[0-9a-f]{2}/[^/]+\.json", path
                )
            }
            event_paths = {
                path: blob
                for path, blob in listing.items()
                if re.fullmatch(
                    r"memory/events/(?:[0-9a-f]{2}/)?[^/]+\.json", path
                )
            }
            legacy_paths = {
                path: blob
                for path, blob in listing.items()
                if re.fullmatch(
                    r"sources/[^/]+/revisions/[^/]+\.json", path
                )
            }
            immutable_paths = {
                **episode_paths,
                **event_paths,
                **legacy_paths,
            }
            if len(immutable_paths) > MAX_MEMORY_NETWORK_BUNDLE_ENTRIES:
                raise VerificationError("memory network export is too large")
            immutable_values = self.git.show_blob_bytes_many(
                list(immutable_paths.values())
            )
            episode_values: dict[str, bytes] = {}
            episode_documents: dict[str, Mapping[str, Any]] = {}
            for path, blob in sorted(episode_paths.items()):
                raw = immutable_values[blob]
                try:
                    value = strict_json_loads(raw.decode("utf-8"))
                except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
                    raise VerificationError("export episode is invalid JSON") from exc
                if not isinstance(value, Mapping):
                    raise VerificationError("export episode is not an object")
                _validate_generated_document(path, value)
                episode_values[path] = raw
                episode_documents[str(value["episode_id"])] = value
            event_values: dict[str, bytes] = {}
            event_documents: dict[str, Mapping[str, Any]] = {}
            for path, blob in sorted(event_paths.items()):
                match = re.fullmatch(
                    r"memory/events/(?:[0-9a-f]{2}/)?([^/]+)\.json", path
                )
                assert match is not None
                raw = immutable_values[blob]
                try:
                    value = strict_json_loads(raw.decode("utf-8"))
                except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
                    raise VerificationError("export memory event is invalid JSON") from exc
                if not isinstance(value, Mapping):
                    raise VerificationError("export memory event is not an object")
                if (
                    value.get("schema_version")
                    != memory_network.MEMORY_EVENT_SCHEMA
                ):
                    # v1 may contain task scope and remains local migration
                    # evidence. A portable taskless bundle contains v2 only.
                    continue
                _validate_generated_document(path, value)
                source = value.get("source")
                if not isinstance(source, Mapping):
                    raise VerificationError("export memory event source is invalid")
                revision_id = str(source.get("revision_id") or "")
                episode = episode_documents.get(revision_id)
                if episode is None:
                    raise VerificationError(
                        "export taskless event has no included episode evidence"
                    )
                _validate_v2_event_episode(value, episode)
                event_id = str(value["memory_event_id"])
                if event_id in event_documents:
                    raise VerificationError(
                        "export memory event identity is duplicated"
                    )
                event_documents[event_id] = value
                event_values[path] = raw
            event_ids = set(event_documents)
            for event in event_documents.values():
                for relation in (
                    "parents",
                    "supersedes",
                    "conflicts_with",
                    "resolves",
                ):
                    missing_targets = set(event[relation]) - event_ids
                    if missing_targets:
                        raise VerificationError(
                            "export memory graph has a relation outside the taskless bundle"
                        )
            legacy_visible_values: dict[str, bytes] = {}
            legacy_documents, skipped_legacy_revisions = (
                self._memory_documents_for_paths(
                    legacy_paths,
                    blob_values=immutable_values,
                )
            )
            for document in legacy_documents:
                if document.value.get("schema_version") != "conversation-export/v1":
                    continue
                legacy_visible_values[document.path] = immutable_values[
                    document.blob_sha
                ]
            files = {
                **episode_values,
                **event_values,
                **legacy_visible_values,
            }
            if len(files) > MAX_MEMORY_NETWORK_BUNDLE_ENTRIES:
                raise VerificationError("memory network export is too large")
            entries = [
                {
                    "path": path,
                    "sha256": sha256_bytes(raw),
                    "size": len(raw),
                }
                for path, raw in sorted(files.items())
            ]
            total_bytes = sum(int(item["size"]) for item in entries)
            if total_bytes > MAX_MEMORY_NETWORK_BUNDLE_TOTAL_BYTES:
                raise VerificationError("memory network export bytes exceed the limit")
            manifest_domain = {
                "schema_version": "memory-network-bundle/v1",
                "network_contract": memory_network.PORTABLE_NETWORK_CONTRACT,
                "remote_commit_sha": self.git.head_sha(),
                "exported_at": utc_now(),
                "native_conversation_ids_included": False,
                "credentials_included": False,
                "entries": entries,
            }
            manifest = {
                **manifest_domain,
                "network_sha256": sha256_jcs(manifest_domain),
            }
            manifest_bytes = pretty_json_bytes(manifest)
        descriptor, temporary_name = tempfile.mkstemp(
            prefix=f".{output.name}.",
            suffix=".network-export",
            dir=str(output.parent),
        )
        os.close(descriptor)
        temporary = Path(temporary_name)
        try:
            with zipfile.ZipFile(
                temporary,
                "w",
                compression=zipfile.ZIP_DEFLATED,
                compresslevel=6,
            ) as archive:
                archive.writestr("MANIFEST.json", manifest_bytes)
                for path, raw in sorted(files.items()):
                    archive.writestr(path, raw)
            _safe_chmod(temporary, 0o600)
            os.replace(temporary, output)
            _safe_chmod(output, 0o600)
        finally:
            with contextlib.suppress(FileNotFoundError):
                temporary.unlink()
        return {
            "schema_version": "memory-network-export-result/v1",
            "output": str(output),
            "network_sha256": manifest["network_sha256"],
            "entries": len(entries),
            "episodes": len(episode_values),
            "events": len(event_values),
            "legacy_visible_revisions": len(legacy_visible_values),
            "skipped_legacy_revisions": skipped_legacy_revisions,
            "uncompressed_bytes": total_bytes,
        }

    def import_memory_network(self, bundle_path: Path) -> Mapping[str, Any]:
        """Import only absent immutable nodes/edges from a verified bundle."""

        bundle = bundle_path.expanduser().resolve(strict=True)
        assert_plain_path(bundle, require_file=True)
        if bundle.stat().st_size > MAX_MEMORY_NETWORK_BUNDLE_TOTAL_BYTES:
            raise VerificationError("memory network bundle exceeds the size limit")
        try:
            archive = zipfile.ZipFile(bundle, "r")
        except (OSError, zipfile.BadZipFile) as exc:
            raise VerificationError("memory network bundle is not a valid archive") from exc
        with archive:
            infos = archive.infolist()
            if len(infos) > MAX_MEMORY_NETWORK_BUNDLE_ENTRIES + 1:
                raise VerificationError("memory network bundle has too many entries")
            names: set[str] = set()
            total = 0
            for info in infos:
                if info.filename in names or info.is_dir():
                    raise VerificationError("memory network bundle entry is invalid")
                names.add(info.filename)
                member_limit = (
                    MAX_MEMORY_NETWORK_BUNDLE_MANIFEST_BYTES
                    if info.filename == "MANIFEST.json"
                    else MAX_MEMORY_NETWORK_BUNDLE_MEMBER_BYTES
                )
                if info.file_size > member_limit or info.file_size < 0:
                    raise VerificationError("memory network bundle member is too large")
                total += info.file_size
                if total > MAX_MEMORY_NETWORK_BUNDLE_TOTAL_BYTES:
                    raise VerificationError("memory network bundle expands too large")
                mode = (info.external_attr >> 16) & 0o170000
                if mode == stat.S_IFLNK:
                    raise PrivacyError("memory network bundle contains a symlink")
                if (
                    info.compress_size > 0
                    and info.file_size > info.compress_size * 250
                ):
                    raise VerificationError("memory network bundle compression ratio is unsafe")
            if "MANIFEST.json" not in names:
                raise VerificationError("memory network bundle manifest is missing")
            try:
                manifest = strict_json_loads(
                    archive.read("MANIFEST.json").decode("utf-8")
                )
            except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
                raise VerificationError("memory network bundle manifest is invalid") from exc
            manifest_fields = {
                "schema_version",
                "network_contract",
                "remote_commit_sha",
                "exported_at",
                "native_conversation_ids_included",
                "credentials_included",
                "entries",
                "network_sha256",
            }
            if not isinstance(manifest, Mapping) or set(manifest) != manifest_fields:
                raise VerificationError("memory network bundle manifest fields are invalid")
            if (
                manifest.get("schema_version") != "memory-network-bundle/v1"
                or manifest.get("network_contract")
                not in {
                    memory_network.PORTABLE_NETWORK_CONTRACT,
                    *memory_network.LEGACY_PORTABLE_NETWORK_CONTRACTS,
                }
                or manifest.get("native_conversation_ids_included") is not False
                or manifest.get("credentials_included") is not False
            ):
                raise PrivacyError("memory network bundle privacy profile is invalid")
            validate_git_sha(
                manifest.get("remote_commit_sha"), "bundle source commit"
            )
            domain = dict(manifest)
            observed_network_hash = validate_sha256(
                domain.pop("network_sha256"), "bundle network hash"
            )
            if observed_network_hash != sha256_jcs(domain):
                raise VerificationError("memory network bundle hash is invalid")
            raw_entries = manifest.get("entries")
            if not isinstance(raw_entries, list) or len(raw_entries) > MAX_MEMORY_NETWORK_BUNDLE_ENTRIES:
                raise VerificationError("memory network bundle entries are invalid")
            files: dict[str, bytes] = {}
            bundle_documents: dict[str, Mapping[str, Any]] = {}
            expected_names = {"MANIFEST.json"}
            previous_path: str | None = None
            for raw_entry in raw_entries:
                if not isinstance(raw_entry, Mapping) or set(raw_entry) != {
                    "path",
                    "sha256",
                    "size",
                }:
                    raise VerificationError("memory network bundle entry is invalid")
                path = validate_repo_path(raw_entry.get("path"), "bundle path")
                if not (
                    re.fullmatch(r"memory/episodes/[0-9a-f]{2}/[^/]+\.json", path)
                    or re.fullmatch(
                        r"memory/events/(?:[0-9a-f]{2}/)?[^/]+\.json", path
                    )
                    or re.fullmatch(
                        r"sources/[^/]+/revisions/[^/]+\.json", path
                    )
                ):
                    raise PrivacyError("bundle attempts to write outside memory network")
                if previous_path is not None and path <= previous_path:
                    raise VerificationError("memory network bundle paths are not canonical")
                previous_path = path
                expected_names.add(path)
                raw = archive.read(path)
                size = raw_entry.get("size")
                if (
                    not isinstance(size, int)
                    or isinstance(size, bool)
                    or size != len(raw)
                    or sha256_bytes(raw)
                    != validate_sha256(raw_entry.get("sha256"), "bundle entry hash")
                ):
                    raise VerificationError("memory network bundle entry hash is invalid")
                try:
                    value = strict_json_loads(raw.decode("utf-8"))
                except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
                    raise VerificationError("memory network bundle document is invalid") from exc
                if not isinstance(value, Mapping):
                    raise VerificationError("memory network bundle document is not an object")
                _validate_generated_document(path, value)
                if (
                    path.startswith("memory/events/")
                    and value.get("schema_version")
                    != memory_network.MEMORY_EVENT_SCHEMA
                ):
                    raise PrivacyError(
                        "portable memory bundles cannot contain legacy task-scoped events"
                    )
                files[path] = raw
                bundle_documents[path] = value
            if names != expected_names:
                raise VerificationError("memory network bundle contains undeclared files")
            episode_documents = {
                str(value["episode_id"]): value
                for path, value in bundle_documents.items()
                if path.startswith("memory/episodes/")
            }
            event_documents: dict[str, Mapping[str, Any]] = {}
            for path, value in bundle_documents.items():
                if not path.startswith("memory/events/"):
                    continue
                event_id = str(value["memory_event_id"])
                if event_id in event_documents:
                    raise VerificationError(
                        "memory network bundle repeats an event identity"
                    )
                event_documents[event_id] = value
            event_ids = set(event_documents)
            for event in event_documents.values():
                source = event.get("source")
                if not isinstance(source, Mapping):
                    raise VerificationError(
                        "memory network bundle event source is invalid"
                    )
                episode = episode_documents.get(str(source["revision_id"]))
                if episode is None:
                    raise VerificationError(
                        "memory network bundle event has no episode evidence"
                    )
                _validate_v2_event_episode(event, episode)
                for relation in (
                    "parents",
                    "supersedes",
                    "conflicts_with",
                    "resolves",
                ):
                    if set(event[relation]) - event_ids:
                        raise VerificationError(
                            "memory network bundle relation is not self-contained"
                        )

        with FileLock(self.lock_path):
            self.git.ensure()
            missing: dict[str, bytes] = {}
            reused = 0
            for path, raw in files.items():
                if self.git.file_exists(path):
                    if self.git.show_bytes(path) != raw:
                        raise ConflictError(
                            "imported immutable memory conflicts with remote evidence"
                        )
                    reused += 1
                else:
                    missing[path] = raw
            ordered_paths = sorted(
                missing,
                key=lambda path: (0 if path.startswith("memory/episodes/") else 1, path),
            )
            commits: list[str] = []
            cursor = 0
            while cursor < len(ordered_paths):
                batch_paths: list[str] = []
                batch_bytes = 0
                while cursor < len(ordered_paths):
                    path = ordered_paths[cursor]
                    size = len(missing[path])
                    if batch_paths and (
                        len(batch_paths) >= MEMORY_NETWORK_IMPORT_COMMIT_ITEMS
                        or batch_bytes + size > MEMORY_NETWORK_IMPORT_COMMIT_BYTES
                        or (
                            batch_paths[0].startswith("memory/episodes/")
                            != path.startswith("memory/episodes/")
                        )
                    ):
                        break
                    batch_paths.append(path)
                    batch_bytes += size
                    cursor += 1
                batch_files = {path: missing[path] for path in batch_paths}
                transaction = validate_identifier(
                    "import-"
                    + sha256_bytes(
                        f"{observed_network_hash}\0{len(commits)}".encode("ascii")
                    )[:40],
                    "memory import transaction",
                )
                base = self.git.head_sha()
                with self.git.create_worktree() as worktree:
                    self.git.write_generated_files(worktree, batch_files)
                    self._validate_worktree(
                        worktree,
                        batch_files,
                        verified_episodes=episode_documents,
                    )
                    commit = self.git.commit_and_push(
                        worktree,
                        batch_files,
                        "memory-network",
                        transaction,
                    )
                self.git.accept_pushed_commit(base, commit)
                commits.append(commit)
            receive = self._receive_memory_network()
        return {
            "schema_version": "memory-network-import-result/v1",
            "network_sha256": observed_network_hash,
            "imported": len(missing),
            "reused": reused,
            "commits": commits,
            "receive": receive,
        }

    def record_semantic_memory(
        self,
        proposal: Mapping[str, Any],
    ) -> Mapping[str, Any]:
        """Append an AI-inferred semantic edge anchored to visible evidence."""

        fields = {
            "schema_version",
            "source_id",
            "episode_id",
            "kind",
            "claim_key",
            "parents",
            "supersedes",
            "conflicts_with",
            "resolves",
            "payload",
        }
        if set(proposal) != fields or proposal.get("schema_version") != (
            "memory-network-semantic-proposal/v1"
        ):
            raise VerificationError("semantic memory proposal fields are invalid")
        source_id = validate_identifier(proposal.get("source_id"), "source_id")
        episode_id = validate_identifier(proposal.get("episode_id"), "episode_id")
        if not episode_id.startswith("ep-"):
            raise VerificationError("semantic memory evidence is not an episode")
        kind = proposal.get("kind")
        if kind not in {
            "decision",
            "constraint",
            "progress",
            "next_action",
            "hypothesis",
            "artifact_created",
            "artifact_verified",
            "correction",
            "user_preference",
            "conflict_declared",
            "conflict_resolved",
            "checkpoint_note",
        }:
            raise VerificationError("semantic memory kind is invalid")
        claim_key = proposal.get("claim_key")
        if claim_key is not None:
            claim_key = validate_identifier(claim_key, "semantic memory claim_key")
        relations: dict[str, list[str]] = {}
        for relation in ("parents", "supersedes", "conflicts_with", "resolves"):
            raw_targets = proposal.get(relation)
            if not isinstance(raw_targets, list) or len(raw_targets) > 128:
                raise VerificationError("semantic memory relation is invalid")
            targets = [
                validate_identifier(item, f"semantic memory {relation}")
                for item in raw_targets
            ]
            if len(targets) != len(set(targets)):
                raise VerificationError("semantic memory relation repeats a target")
            relations[relation] = targets
        raw_payload = proposal.get("payload")
        if not isinstance(raw_payload, Mapping) or not raw_payload:
            raise VerificationError("semantic memory payload is invalid")
        assert_remote_safe(raw_payload)
        episode_path = (
            f"memory/episodes/{episode_id[3:5]}/{episode_id}.json"
        )
        with FileLock(self.lock_path):
            self.git.ensure()
            episode = self.git.show_json(episode_path)
            _validate_memory_episode(episode)
            if episode.get("source_id") != source_id:
                raise VerificationError(
                    "semantic memory evidence source is inconsistent"
                )
            continuity_id = memory_network.episode_event_id(
                source_id, episode_id
            )
            try:
                continuity_path = memory_network.event_relative_path(
                    continuity_id
                )
            except memory_network.MemoryNetworkError as exc:
                raise VerificationError(
                    "semantic memory continuity identity is invalid"
                ) from exc
            if self.git.file_exists(continuity_path) and continuity_id not in relations[
                "parents"
            ]:
                relations["parents"] = [
                    continuity_id,
                    *relations["parents"],
                ]
            for relation, targets in relations.items():
                for target in targets:
                    target_paths = [f"memory/events/{target}.json"]
                    if re.fullmatch(r"evt-[0-9a-f]{40}", target):
                        target_paths.insert(
                            0, memory_network.event_relative_path(target)
                        )
                    existing_paths = [
                        path
                        for path in target_paths
                        if self.git.file_exists(path)
                    ]
                    if len(existing_paths) != 1:
                        raise VerificationError(
                            f"semantic memory {relation} target is missing or ambiguous"
                        )
                    target_path = existing_paths[0]
                    target_value = self.git.show_json(target_path)
                    _validate_memory_event_document(
                        target_value, event_id=target
                    )
                    if (
                        target_value.get("schema_version")
                        != memory_network.MEMORY_EVENT_SCHEMA
                    ):
                        raise VerificationError(
                            "taskless semantic memory cannot depend on a legacy task event"
                        )
            payload: Mapping[str, Any] = {
                "profile": "memory-network-semantic/v1",
                "claim": dict(raw_payload),
            }
            identity_domain = {
                "source_id": source_id,
                "episode_id": episode_id,
                "kind": kind,
                "claim_key": claim_key,
                **relations,
                "payload": payload,
            }
            event_id = validate_identifier(
                "evt-" + sha256_jcs(identity_domain)[:40],
                "semantic memory event_id",
            )
            if any(event_id in targets for targets in relations.values()):
                raise VerificationError("semantic memory event references itself")
            event: dict[str, Any] = {
                "schema_version": memory_network.MEMORY_EVENT_SCHEMA,
                "memory_event_id": event_id,
                "kind": kind,
                # An assistant may structure evidence, but only the original
                # episode proves what the user actually said.
                "confidence": "assistant_inferred",
                "source": {
                    "source_id": source_id,
                    "revision_id": episode_id,
                    "source_sequence": int(episode["source_sequence"]),
                    "evidence_anchor_sha256": episode["episode_sha256"],
                },
                "claim_key": claim_key,
                **relations,
                "payload": payload,
                "payload_sha256": sha256_jcs(payload),
                "hash_profile": "jcs-rfc8785+sha256/event-v2",
                "created_at": utc_now(),
            }
            event["event_sha256"] = sha256_jcs(event)
            try:
                path = memory_network.event_relative_path(event_id)
            except memory_network.MemoryNetworkError as exc:
                raise VerificationError(
                    "semantic memory event path is invalid"
                ) from exc
            raw = pretty_json_bytes(event)
            _validate_generated_document(path, event)
            if self.git.file_exists(path):
                existing = self.git.show_json(path)
                _validate_memory_event_document(existing, event_id=event_id)
                existing_identity = {
                    "source_id": existing.get("source", {}).get("source_id")
                    if isinstance(existing.get("source"), Mapping)
                    else None,
                    "episode_id": existing.get("source", {}).get("revision_id")
                    if isinstance(existing.get("source"), Mapping)
                    else None,
                    "kind": existing.get("kind"),
                    "claim_key": existing.get("claim_key"),
                    "parents": existing.get("parents"),
                    "supersedes": existing.get("supersedes"),
                    "conflicts_with": existing.get("conflicts_with"),
                    "resolves": existing.get("resolves"),
                    "payload": existing.get("payload"),
                }
                if existing_identity != identity_domain:
                    raise ConflictError("semantic memory identity is occupied")
                commit = self.git.head_sha()
                state = "already_recorded"
            else:
                transaction = validate_identifier(
                    "semantic-" + event_id.removeprefix("evt-")[:40],
                    "semantic memory transaction",
                )
                base = self.git.head_sha()
                with self.git.create_worktree() as worktree:
                    self.git.write_generated_files(worktree, {path: raw})
                    self._validate_worktree(worktree, {path: raw})
                    commit = self.git.commit_and_push(
                        worktree,
                        {path: raw},
                        "memory-network",
                        transaction,
                    )
                self.git.accept_pushed_commit(base, commit)
                state = "recorded"
            receive = self._receive_memory_network()
        return {
            "schema_version": "memory-network-semantic-result/v1",
            "state": state,
            "memory_event_id": event_id,
            "remote_commit_sha": commit,
            "confidence": "assistant_inferred",
            "receive": receive,
        }

    def _projection_root(self) -> Path | None:
        projection = self.config["projection"]
        raw = projection.get("root")
        if not projection.get("enabled") or not isinstance(raw, str):
            return None
        root = Path(raw).resolve()
        if not any(
            _path_is_within(root, Path(item).resolve())
            for item in self.config["privacy"]["allowed_roots"]
        ):
            raise ConfigurationError(
                "task projection root is outside the configured allowed roots"
            )
        assert_plain_path(root, require_file=False)
        return root

    def _known_local_observations(
        self,
        *,
        extra_source_ids: Sequence[str] = (),
        extra_workspaces: Sequence[Path] = (),
    ) -> tuple[dict[str, list[dict[str, Any]]], set[str], list[str]]:
        """Inspect only plugin-known workspaces, sessions, and one projection root."""

        coverage: dict[str, list[dict[str, Any]]] = {}
        observed_source_ids = {
            validate_identifier(item, "observed_source_id")
            for item in extra_source_ids
        }
        errors: list[str] = []
        workspace_paths = {item.resolve() for item in extra_workspaces}
        workspace_state_path = self.data_dir / "state" / "workspaces.json"
        if workspace_state_path.exists():
            try:
                value = load_json(workspace_state_path)
                if (
                    not isinstance(value, Mapping)
                    or value.get("schema_version")
                    != "memory-vault-sync-workspaces/v1"
                    or not isinstance(value.get("items"), Mapping)
                ):
                    raise ConfigurationError("local workspace state is invalid")
                for item in value["items"].values():
                    if isinstance(item, Mapping) and isinstance(
                        item.get("local_path"), str
                    ):
                        workspace_paths.add(Path(str(item["local_path"])).resolve())
            except VaultSyncError as exc:
                errors.append(f"workspace_registry:{exc.code}")
        projection_root = self._projection_root()
        if projection_root is not None:
            entries = list(projection_root.iterdir())
            if len(entries) > 1000:
                raise VerificationError(
                    "task projection root exceeds the safety limit"
                )
            workspace_paths.add(projection_root)
            for entry in entries:
                if entry.is_dir() and not entry.is_symlink():
                    workspace_paths.add(entry.resolve())

        allowed = [
            Path(item).resolve()
            for item in self.config["privacy"]["allowed_roots"]
        ]
        for workspace in sorted(workspace_paths, key=lambda item: str(item)):
            if (
                not workspace.exists()
                or not workspace.is_dir()
                or workspace.is_symlink()
                or not any(_path_is_within(workspace, root) for root in allowed)
            ):
                continue
            try:
                for identity in _portable_identities_in_workspace(workspace):
                    remote = load_remote_task(self.git, identity)
                    is_projected = (
                        projection_root is not None
                        and workspace.parent == projection_root
                    )
                    coverage.setdefault(identity.task_id, []).append(
                        {
                            "kind": "workspace",
                            "binding_id": identity.binding_id,
                            "workspace_lineage_id": identity.lineage_id,
                            "current_blob_sha": identity.base.get(
                                "current_blob_sha"
                            ),
                            "local_path": str(workspace),
                            "projected": is_projected,
                            "opened": False,
                            "remote_verified": (
                                remote.current["task_id"] == identity.task_id
                            ),
                        }
                    )
            except VaultSyncError as exc:
                errors.append(f"workspace_identity:{exc.code}")

        sessions_root = self.data_dir / "state" / "sessions"
        if sessions_root.exists():
            session_paths = sorted(sessions_root.glob("*.json"))
            if len(session_paths) > 5000:
                raise VerificationError("local session registry exceeds the safety limit")
            for path in session_paths:
                try:
                    session = load_json(path)
                    if (
                        not isinstance(session, Mapping)
                        or session.get("schema_version") != SESSION_SCHEMA
                    ):
                        raise ConfigurationError("local session state is invalid")
                    task_id = validate_identifier(
                        session.get("task_id"), "session.task_id"
                    )
                    source_id = session.get("source_id")
                    if isinstance(source_id, str):
                        observed_source_ids.add(
                            validate_identifier(source_id, "session.source_id")
                        )
                    identity_kind = session.get("identity_kind", "workspace")
                    if identity_kind == "source":
                        identity = SourceIdentity(
                            binding_id=validate_identifier(
                                session.get("binding_id"), "binding_id"
                            ),
                            task_id=task_id,
                            source_id=validate_identifier(
                                source_id, "source_id"
                            ),
                            external_source_key_sha256=validate_sha256(
                                session.get("source_external_key_sha256"),
                                "source_external_key_sha256",
                            ),
                        )
                        _require_current_attested_source_route(
                            self.git,
                            source_id=identity.source_id,
                            task_id=identity.task_id,
                            binding_id=identity.binding_id,
                        )
                        source_document = self.git.show_json(
                            f"sources/{identity.source_id}/SOURCE.json"
                        )
                        _validate_source(source_document)
                        if (
                            source_document.get(
                                "external_source_key_sha256"
                            )
                            != identity.external_source_key_sha256
                        ):
                            raise IdentityError(
                                "local source session key no longer matches "
                                "the verified source"
                            )
                        load_remote_task(self.git, identity)
                        coverage.setdefault(task_id, []).append(
                            {
                                "kind": "conversation",
                                "binding_id": identity.binding_id,
                                "source_id": identity.source_id,
                                "current_blob_sha": (
                                    session.get("base", {}).get(
                                        "task_current_blob_sha"
                                    )
                                    if isinstance(session.get("base"), Mapping)
                                    else None
                                ),
                                "remote_verified": True,
                            }
                        )
                    elif identity_kind == "provisional_source":
                        session_key = path.stem
                        claim_record = _load_provisional_claim(
                            self.data_dir,
                            session_key,
                        )
                        if claim_record is None:
                            raise IdentityError(
                                "provisional session has no active claim"
                            )
                        remote = self._verify_provisional_claim(
                            claim_record[1],
                            require_original_current=False,
                        )
                        coverage.setdefault(task_id, []).append(
                            {
                                "kind": "provisional_conversation",
                                "binding_id": session.get("binding_id"),
                                "source_id": source_id,
                                "current_blob_sha": remote.current_blob_sha,
                                "remote_verified": True,
                            }
                        )
                    elif identity_kind == "workspace":
                        workspace_root = session.get("workspace_root")
                        if (
                            not isinstance(workspace_root, str)
                            or not Path(workspace_root).is_absolute()
                        ):
                            raise IdentityError(
                                "workspace session has no valid local root"
                            )
                        identity = resolve_workspace(
                            Path(workspace_root),
                            self.config["privacy"]["allowed_roots"],
                            task_id=task_id,
                        )
                        if identity.binding_id != session.get("binding_id"):
                            raise IdentityError(
                                "workspace session binding no longer matches"
                            )
                        load_remote_task(self.git, identity)
                        is_projected = (
                            projection_root is not None
                            and identity.workspace_root.parent
                            == projection_root
                        )
                        coverage.setdefault(task_id, []).append(
                            {
                                "kind": "workspace",
                                "binding_id": identity.binding_id,
                                "workspace_lineage_id": identity.lineage_id,
                                "current_blob_sha": (
                                    session.get("base", {}).get(
                                        "task_current_blob_sha"
                                    )
                                    if isinstance(session.get("base"), Mapping)
                                    else None
                                ),
                                "local_path": str(identity.workspace_root),
                                "projected": is_projected,
                                "opened": True,
                                "remote_verified": True,
                            }
                        )
                    else:
                        raise IdentityError(
                            "local session identity kind is invalid"
                        )
                except VaultSyncError as exc:
                    errors.append(f"session_identity:{exc.code}")
        for task_id, entries in coverage.items():
            unique: dict[tuple[str, str, str], dict[str, Any]] = {}
            for item in entries:
                key = (
                    str(item.get("kind")),
                    str(item.get("binding_id")),
                    str(item.get("local_path") or item.get("source_id") or ""),
                )
                unique[key] = item
            coverage[task_id] = list(unique.values())
        return coverage, observed_source_ids, sorted(set(errors))

    def _materialize_projection_task(
        self,
        remote: RemoteTaskState,
        authority: WorkspaceAuthority,
        projection_root: Path,
    ) -> tuple[Mapping[str, Any], PortableIdentity]:
        task_id = authority.task_id
        workspace = projection_root / task_id
        created = False
        if workspace.exists():
            assert_plain_path(workspace, require_file=False)
            existing_identities = _portable_identities_in_workspace(workspace)
            if existing_identities:
                if len(existing_identities) != 1:
                    raise IdentityError(
                        "projected task workspace contains multiple identities"
                    )
                identity = existing_identities[0]
                if identity.task_id != task_id:
                    raise IdentityError(
                        "projected task workspace belongs to another task"
                    )
                load_remote_task(self.git, identity)
                return (
                    {
                        "task_id": task_id,
                        "state": "already_present",
                        "local_path": str(workspace),
                    },
                    identity,
                )
            if any(workspace.iterdir()):
                raise IdentityError(
                    "projected task path exists and is not an empty vault workspace"
                )
        else:
            ensure_private_dir(workspace)
            created = True
        identity_path = workspace / ".vault_identity.yaml"
        placeholder = PortableIdentity(
            path=identity_path,
            workspace_root=workspace,
            binding_id=authority.binding_id,
            task_id=task_id,
            lineage_id=authority.lineage_id,
            base={},
        )
        verified = load_remote_task(self.git, placeholder)
        document = _portable_identity_document(self.git, verified, authority)
        atomic_write_bytes(identity_path, pretty_json_bytes(document), mode=0o644)
        identity = parse_identity(identity_path)
        device = _device_state(self.data_dir)
        _workspace_instance(self.data_dir, device, workspace)
        return (
            {
                "task_id": task_id,
                "state": "created" if created else "bound_empty_workspace",
                "local_path": str(workspace),
            },
            identity,
        )

    def _save_projection_state(
        self, payload: MutableMapping[str, Any]
    ) -> bool:
        path = _projection_state_path(self.data_dir)
        previous: Mapping[str, Any] | None = None
        if path.exists():
            loaded = load_json(path)
            if (
                isinstance(loaded, Mapping)
                and loaded.get("schema_version") == PROJECTION_SCHEMA
            ):
                previous = loaded
        comparison = dict(payload)
        comparison.pop("updated_at", None)
        previous_comparison = dict(previous or {})
        previous_comparison.pop("updated_at", None)
        changed = comparison != previous_comparison
        if changed:
            payload["updated_at"] = utc_now()
            atomic_write_json(path, payload)
        elif previous is not None:
            payload["updated_at"] = previous.get("updated_at")
        return changed

    def _reconcile_cached(
        self,
        *,
        materialize: bool,
        extra_source_ids: Sequence[str] = (),
        extra_workspaces: Sequence[Path] = (),
    ) -> Mapping[str, Any]:
        catalog, index_status = _discover_remote_task_catalog(self.git)
        task_ids = set(catalog)
        authorities = _discover_workspace_authorities(self.git, task_ids)
        splits = _discover_structural_splits(self.git, task_ids)
        coverage, observed_sources, local_errors = self._known_local_observations(
            extra_source_ids=extra_source_ids,
            extra_workspaces=extra_workspaces,
        )

        decisions: list[dict[str, Any]] = []
        blocked_by_route: set[str] = set()
        shared_history: dict[str, list[str]] = {}
        for split in splits:
            source_id = str(split["source_id"])
            children = [str(item) for item in split["child_task_ids"]]
            for child in children:
                shared_history.setdefault(child, []).append(source_id)
            if source_id not in observed_sources:
                continue
            route = split.get("continuation_route")
            if isinstance(route, Mapping):
                target = str(route["target_task_id"])
                binding_id = str(route["binding_id"])
                try:
                    active_route = _require_current_attested_source_route(
                        self.git,
                        source_id=source_id,
                        task_id=target,
                        binding_id=binding_id,
                        source_sequence_from=int(
                            route["source_sequence_from"]
                        ),
                    )
                except VaultSyncError:
                    unresolved = []
                    for child in children:
                        entries = coverage.get(child, [])
                        has_preexisting_entry = any(
                            not item.get("projected") or item.get("opened")
                            for item in entries
                        )
                        if not has_preexisting_entry:
                            unresolved.append(child)
                    blocked_by_route.update(unresolved)
                    decisions.append(
                        {
                            "structural_event_id": split[
                                "structural_event_id"
                            ],
                            "status": "needs_content_revalidation",
                            "candidate_task_ids": unresolved or children,
                        }
                    )
                    continue
                binding = active_route.document
                effective = binding.get("effective_range")
                binding_targets = binding.get("targets")
                if (
                    binding.get("schema_version") != "binding/v1"
                    or binding.get("state") != "confirmed"
                    or binding.get("subject")
                    != {"kind": "source", "id": source_id}
                    or not isinstance(binding_targets, list)
                    or not any(
                        isinstance(item, Mapping)
                        and item.get("semantic_task_id") == target
                        and item.get("relation") == "source_for"
                        and item.get("role") == "primary"
                        for item in binding_targets
                    )
                    or not isinstance(effective, Mapping)
                    or effective.get("source_sequence_from")
                    != route.get("source_sequence_from")
                    or effective.get("source_sequence_to") is not None
                ):
                    raise VerificationError(
                        "source split route binding is not authoritative"
                    )
                coverage.setdefault(target, []).append(
                    {
                        "kind": "split_route",
                        "binding_id": binding_id,
                        "source_id": source_id,
                        "current_blob_sha": None,
                        "remote_verified": True,
                    }
                )
            else:
                unresolved = []
                for child in children:
                    entries = coverage.get(child, [])
                    has_preexisting_entry = any(
                        not item.get("projected") or item.get("opened")
                        for item in entries
                    )
                    if not has_preexisting_entry:
                        unresolved.append(child)
                blocked_by_route.update(unresolved)
                decisions.append(
                    {
                        "structural_event_id": split["structural_event_id"],
                        "status": "needs_one_time_decision",
                        "candidate_task_ids": unresolved or children,
                    }
                )

        projection_root = self._projection_root()
        should_materialize = (
            materialize
            and projection_root is not None
            and bool(self.config["projection"].get("materialize_missing"))
        )
        task_rows: list[dict[str, Any]] = []
        materialized: list[Mapping[str, Any]] = []
        for task_id, remote in sorted(catalog.items()):
            entries = coverage.get(task_id, [])
            observed_blobs = {
                str(item["current_blob_sha"])
                for item in entries
                if isinstance(item.get("current_blob_sha"), str)
            }
            if task_id in blocked_by_route:
                local_state = "awaiting_split_route"
                action = "confirm_one_time_split_route"
            elif any(
                item.get("kind") == "provisional_conversation"
                for item in entries
            ):
                local_state = "provisional_mapped"
                action = "complete_consistency_check"
            elif entries:
                local_state = (
                    "in_sync"
                    if remote.current_blob_sha in observed_blobs
                    else "mapped"
                    if not observed_blobs
                    else "behind_remote"
                )
                action = "continue_latest_remote"
            elif (
                remote.task.get("status") == "active"
                and remote.task.get("task_type") == "semantic_task"
            ):
                local_state = "remote_only"
                action = "materialize_continuation_workspace"
            else:
                local_state = "reference_only"
                action = "none"

            local_workspace: str | None = next(
                (
                    str(item["local_path"])
                    for item in entries
                    if isinstance(item.get("local_path"), str)
                ),
                None,
            )
            if local_state == "remote_only" and should_materialize:
                task_authorities = authorities.get(task_id, [])
                if len(task_authorities) == 1:
                    try:
                        result, identity = self._materialize_projection_task(
                            remote, task_authorities[0], projection_root
                        )
                        materialized.append(result)
                        local_workspace = str(identity.workspace_root)
                        local_state = "ready_to_open"
                        action = "open_workspace_to_continue"
                        coverage.setdefault(task_id, []).append(
                            {
                                "kind": "workspace",
                                "binding_id": identity.binding_id,
                                "workspace_lineage_id": identity.lineage_id,
                                "current_blob_sha": identity.base.get(
                                    "current_blob_sha"
                                ),
                                "local_path": local_workspace,
                                "projected": True,
                                "opened": False,
                                "remote_verified": True,
                            }
                        )
                    except VaultSyncError as exc:
                        local_state = "materialization_blocked"
                        action = exc.code
                elif not task_authorities:
                    local_state = "materialization_blocked"
                    action = "no_primary_workspace_binding"
                else:
                    local_state = "materialization_blocked"
                    action = "ambiguous_primary_workspace_binding"
            task_rows.append(
                {
                    "task_id": task_id,
                    "display_title": str(
                        remote.task.get("display_title") or task_id
                    )[:300],
                    "task_type": remote.task.get("task_type"),
                    "remote_status": remote.task.get("status"),
                    "generation": remote.current["generation"],
                    "snapshot_id": remote.current["snapshot_id"],
                    "current_blob_sha": remote.current_blob_sha,
                    "local_state": local_state,
                    "local_entry_count": len(coverage.get(task_id, [])),
                    "local_workspace": local_workspace,
                    "shared_history_source_count": len(
                        set(shared_history.get(task_id, []))
                    ),
                    "action": action,
                }
            )

        summary: dict[str, int] = {}
        for row in task_rows:
            state = str(row["local_state"])
            summary[state] = summary.get(state, 0) + 1
        payload: dict[str, Any] = {
            "schema_version": PROJECTION_SCHEMA,
            "remote_commit_sha": self.git.head_sha(),
            "coverage_scope": (
                "plugin-known sessions, plugin-known workspaces, and the "
                "configured projection root only"
            ),
            "sidebar_enumeration_available": False,
            "native_task_creation_mode": (
                "agent_orchestrated_when_codex_app_tools_are_available"
            ),
            "index": dict(index_status),
            "summary": summary,
            "tasks": task_rows,
            "decisions": decisions,
            "local_errors": local_errors,
            "updated_at": utc_now(),
        }
        changed = self._save_projection_state(payload)
        return {
            "schema_version": "memory-vault-sync-reconcile/v1",
            "changed": changed,
            "remote_commit_sha": payload["remote_commit_sha"],
            "summary": summary,
            "tasks": task_rows,
            "decisions": decisions,
            "materialized": materialized,
            "coverage_scope": payload["coverage_scope"],
            "sidebar_enumeration_available": False,
            "native_task_creation_mode": payload[
                "native_task_creation_mode"
            ],
            "index": payload["index"],
            "local_errors": local_errors,
        }

    def reconcile(
        self,
        *,
        materialize: bool | None = None,
        already_locked: bool = False,
        fetch: bool = True,
        extra_source_ids: Sequence[str] = (),
        extra_workspaces: Sequence[Path] = (),
    ) -> Mapping[str, Any]:
        apply_projection = (
            bool(self.config["projection"].get("enabled"))
            if materialize is None
            else materialize
        )

        def execute() -> Mapping[str, Any]:
            if fetch:
                self.git.ensure()
            elif not self.git.has_cache():
                raise OfflineError("no verified remote cache is available")
            return self._reconcile_cached(
                materialize=apply_projection,
                extra_source_ids=extra_source_ids,
                extra_workspaces=extra_workspaces,
            )

        if already_locked:
            return execute()
        with FileLock(self.lock_path):
            return execute()

    @staticmethod
    def _projection_notification(result: Mapping[str, Any]) -> str | None:
        materialized = result.get("materialized")
        decisions = result.get("decisions")
        lines: list[str] = []
        if isinstance(materialized, list) and materialized:
            lines.append(
                f"Memory Vault prepared {len(materialized)} missing local "
                "continuation workspace(s)."
            )
        if isinstance(decisions, list) and decisions:
            lines.append(
                f"{len(decisions)} split source(s) need one explicit route "
                "decision before automatic matching can continue."
            )
        if not lines:
            return None
        lines.append(
            "When Codex app task tools are available, the active agent can "
            "create each missing native sidebar task through a verified "
            "one-time handoff. Other clients can open the prepared workspace."
        )
        return "\n".join(lines)

    def _routing_context(
        self,
        request: Mapping[str, Any],
        *,
        state: str = "unbound_pending_model",
        claim_id: str | None = None,
        issue_decision_token: bool = False,
        candidate_preview: Sequence[Mapping[str, Any]] | None = None,
        selection_hint: Mapping[str, Any] | None = None,
    ) -> str:
        payload: dict[str, Any] = {
            "schema_version": "memory-vault-routing/v1",
            "routing_state": state,
            "request_id": request["request_id"],
            "candidate_count": len(request["candidate_task_ids"]),
            "next_model_action": (
                "show_numbered_lightweight_candidate_preview_and_ask_user_"
                "before_deep_content_evidence"
                if candidate_preview is not None
                else (
                    "read_exact_native_task_conversation_then_compare_full_"
                    "verified_candidate_evidence_and_declared_artifacts"
                )
            ),
            "selection_policy": (
                "legacy_auto_binding_disabled;actual_conversation_and_artifact_"
                "evidence_required;ask_once_if_not_fully_proven"
            ),
            "timestamps_are_authoritative": False,
            "raw_thread_id_must_not_be_shown": True,
        }
        choice_record = _load_routing_choice(
            self.data_dir,
            str(request["request_id"]),
            required=False,
        )
        if (
            choice_record is not None
            and choice_record[1].get("state") == "awaiting_user_reply"
        ):
            payload["accepted_user_reply"] = (
                "exactly_one_displayed_numeric_choice_code_or_0_for_none"
            )
            payload["free_text_never_confirms_a_route"] = True
        if issue_decision_token:
            decision_token = _issue_routing_decision_token(
                self.data_dir,
                request,
            )
            if decision_token is not None:
                payload["user_decision_token"] = decision_token
                payload["decision_token_scope"] = (
                    "exact_visible_user_turn_remote_commit_candidate_set_"
                    "and_presented_shortlist"
                )
            else:
                payload["user_choice_token_pending"] = True
        if claim_id is not None:
            payload["claim_id"] = claim_id
            payload["next_model_action"] = (
                "compare_loaded_cloud_checkpoint_with_visible_local_goal_then_"
                "promote_if_consistent_or_ask_once"
            )
        if candidate_preview is not None:
            compact_preview: list[dict[str, Any]] = []
            for index, row in enumerate(candidate_preview, 1):
                if not isinstance(row, Mapping):
                    continue
                title = scan_visible_text(
                    str(row.get("display_title") or row.get("task_id") or ""),
                    "routing candidate title",
                )[:160]
                purpose = scan_visible_text(
                    str(row.get("purpose") or ""),
                    "routing candidate purpose",
                )[:240]
                compact_preview.append(
                    {
                        "choice_code": str(index),
                        "task_id": str(row.get("task_id")),
                        "display_title": title,
                        "purpose": purpose,
                        "generation": int(row.get("generation", 0)),
                        "continuation_readiness": str(
                            row.get("continuation_readiness") or "partial"
                        ),
                    }
                )
            payload["candidate_preview"] = compact_preview
            payload["candidate_preview_policy"] = (
                "retrieval_only;user_selection_does_not_bypass_final_"
                "content_validation"
            )
        if selection_hint is not None:
            payload["user_selected_candidate_hint"] = {
                "choice_code": str(selection_hint.get("choice_code")),
                "task_id": str(selection_hint.get("task_id")),
                "scope": (
                    "prioritize_deep_validation_only;not_a_binding_or_"
                    "publication_authorization"
                ),
            }
        return (
            "MEMORY_VAULT_ROUTING "
            + json.dumps(
                payload,
                ensure_ascii=False,
                sort_keys=True,
                separators=(",", ":"),
            )
        )

    def _ensure_routing_request(
        self,
        hook_input: Mapping[str, Any],
    ) -> tuple[dict[str, Any], str] | None:
        matching = self.config["matching"]
        if not matching.get("enabled"):
            return None
        session_id = hook_input.get("session_id")
        cwd = hook_input.get("cwd")
        if (
            not isinstance(session_id, str)
            or not session_id
            or not isinstance(cwd, str)
            or not os.path.isabs(cwd)
        ):
            return None
        try:
            workspace_root = Path(cwd).resolve(strict=True)
        except OSError as exc:
            raise IdentityError("task matching workspace cannot be resolved") from exc
        workspace_fingerprint = _routing_workspace_identity_fingerprint(
            workspace_root,
            self.config["privacy"]["allowed_roots"],
        )
        catalog, _index = _discover_remote_task_catalog(self.git)
        candidate_ids = [
            task_id
            for task_id, remote in sorted(catalog.items())
            if remote.task.get("task_type") == "semantic_task"
            and remote.task.get("status") == "active"
        ]
        if not candidate_ids:
            return None
        device = _device_state(self.data_dir)
        session_key = _session_key(device, session_id)
        request_id = _routing_request_id(device, session_id)
        path = _routing_request_path(self.data_dir, request_id)
        now_epoch = int(time.time())
        existing: dict[str, Any] | None = None
        if path.exists():
            try:
                _existing_path, existing = _load_routing_request(
                    self.data_dir,
                    request_id,
                )
            except IdentityError:
                if path.exists():
                    raise
        if (
            isinstance(existing, Mapping)
            and existing.get("state")
            in {"pending", "awaiting_user_reply", "provisional"}
            and (
                existing.get("workspace_root") != str(workspace_root)
                or existing.get("workspace_identity_fingerprint")
                != workspace_fingerprint
            )
        ):
            raise IdentityError(
                "task matching workspace or portable identity changed"
            )
        legacy_source_route = False
        legacy_source_binding_id: str | None = None
        if LEGACY_AUTO_BINDING_DISABLED:
            with contextlib.suppress(VaultSyncError):
                source_id, _source, _external_key = resolve_source_record(
                    self.git,
                    session_id,
                )
                active_route = _active_primary_source_route(
                    self.git,
                    source_id,
                )
                legacy_source_route = bool(
                    active_route is not None
                    and _source_route_requires_content_revalidation(
                        active_route
                    )
                )
                if legacy_source_route and active_route is not None:
                    legacy_source_binding_id = active_route.binding_id
        retained_state = (
            str(existing["state"])
            if isinstance(existing, Mapping)
            and existing.get("state")
            in {
                "pending",
                "awaiting_user_reply",
                "provisional",
                "promoted",
                "confirmed_by_user",
                "rejected",
            }
            else "pending"
        )
        remote_review_changed = bool(
            isinstance(existing, Mapping)
            and (
                set(existing.get("candidate_task_ids", []))
                != set(candidate_ids)
                or existing.get("remote_commit_sha") != self.git.head_sha()
            )
        )
        current_legacy_choice = bool(
            legacy_source_route
            and legacy_source_binding_id is not None
            and isinstance(existing, Mapping)
            and existing.get("state") == "awaiting_user_reply"
            and _routing_choice_has_current_content_review(
                self.data_dir,
                existing,
                previous_binding_id=legacy_source_binding_id,
            )
        )
        legacy_route_reset = bool(
            legacy_source_route
            and (
                not isinstance(existing, Mapping)
                or (
                    existing.get("state") == "awaiting_user_reply"
                    and not current_legacy_choice
                )
                or existing.get("state") not in {
                    "pending",
                    "awaiting_user_reply",
                }
            )
        )
        reset_review = (
            not isinstance(existing, Mapping)
            or legacy_route_reset
            or remote_review_changed
        )
        if (
            remote_review_changed
            and retained_state in {"pending", "awaiting_user_reply"}
        ):
            retained_state = "pending"
            with contextlib.suppress(FileNotFoundError):
                _routing_choice_path(
                    self.data_dir,
                    request_id,
                ).unlink()
        if legacy_route_reset:
            retained_state = "pending"
            claim_record = _load_provisional_claim(
                self.data_dir,
                session_key,
            )
            if claim_record is not None and claim_record[1].get(
                "state"
            ) in {"provisional_active", "promoted"}:
                claim = claim_record[1]
                claim["state"] = "revoked"
                claim["updated_at"] = utc_now()
                atomic_write_json(claim_record[0], claim)
            with contextlib.suppress(FileNotFoundError):
                _routing_choice_path(
                    self.data_dir,
                    request_id,
                ).unlink()
        value = {
            "schema_version": ROUTING_REQUEST_SCHEMA,
            "request_id": request_id,
            "state": retained_state,
            "session_key": session_key,
            "session_id": session_id,
            "source_external_key_sha256": _codex_source_key(session_id),
            "workspace_root": str(workspace_root),
            "workspace_identity_fingerprint": workspace_fingerprint,
            "review_nonce": (
                uuid.uuid4().hex
                if reset_review
                else str(existing["review_nonce"])
            ),
            "remote_commit_sha": self.git.head_sha(),
            "candidate_task_ids": candidate_ids,
            "pending_turn_id": (
                existing.get("pending_turn_id")
                if isinstance(existing, Mapping)
                and not reset_review
                else None
            ),
            "pending_prompt": (
                existing.get("pending_prompt")
                if isinstance(existing, Mapping)
                and not reset_review
                else None
            ),
            "created_at": (
                str(existing["created_at"])
                if isinstance(existing, Mapping)
                and isinstance(existing.get("created_at"), str)
                else utc_now()
            ),
            "updated_at": utc_now(),
            "expires_at_epoch": now_epoch + ROUTING_REQUEST_TTL_SECONDS,
        }
        atomic_write_json(path, value)
        return value, self._routing_context(
            value,
            candidate_preview=_routing_candidate_rows(
                {
                    task_id: remote
                    for task_id, remote in catalog.items()
                    if task_id in candidate_ids
                }
            ),
        )

    def _verified_routing_request(
        self,
        request_id: str,
        *,
        ensure_remote: bool = True,
    ) -> tuple[Path, dict[str, Any], dict[str, RemoteTaskState]]:
        path, request = _load_routing_request(self.data_dir, request_id)
        if (
            LEGACY_AUTO_BINDING_DISABLED
            and request.get("state") == "provisional"
        ):
            claim_record = _load_provisional_claim(
                self.data_dir,
                str(request["session_key"]),
            )
            if claim_record is not None:
                claim_path, claim = claim_record
                if claim.get("state") == "provisional_active":
                    claim["state"] = "revoked"
                    claim["updated_at"] = utc_now()
                    atomic_write_json(claim_path, claim)
            session_path = _session_path(
                self.data_dir,
                str(request["session_key"]),
            )
            if session_path.exists():
                archived_root = (
                    self.data_dir
                    / "state"
                    / "legacy-provisional-sessions"
                )
                ensure_private_dir(archived_root)
                destination = archived_root / (
                    f"{request['session_key']}-{uuid.uuid4().hex}.json"
                )
                os.replace(session_path, destination)
            request["state"] = "pending"
            request["updated_at"] = utc_now()
            atomic_write_json(path, request)
        current_fingerprint = _routing_workspace_identity_fingerprint(
            Path(str(request["workspace_root"])),
            self.config["privacy"]["allowed_roots"],
        )
        if (
            request.get("state")
            in {"pending", "awaiting_user_reply", "provisional"}
            and current_fingerprint
            != request.get("workspace_identity_fingerprint")
        ):
            raise IdentityError(
                "workspace identity changed while task matching was pending"
            )
        if ensure_remote:
            self.git.ensure()
        elif not self.git.has_cache():
            raise OfflineError("no verified remote cache is available")
        catalog, _index = _discover_remote_task_catalog(self.git)
        current_candidates = {
            task_id: remote
            for task_id, remote in catalog.items()
            if remote.task.get("task_type") == "semantic_task"
            and remote.task.get("status") == "active"
        }
        current_head = self.git.head_sha()
        candidate_set_changed = (
            set(request["candidate_task_ids"]) != set(current_candidates)
        )
        commit_changed = request.get("remote_commit_sha") != current_head
        if (
            request.get("state") in {"awaiting_user_reply", "provisional"}
            and (candidate_set_changed or commit_changed)
        ):
            raise ConflictError(
                "remote task evidence changed after routing evidence was frozen"
            )
        if (
            request.get("state") == "pending"
            and (candidate_set_changed or commit_changed)
        ):
            request["candidate_task_ids"] = sorted(current_candidates)
            request["remote_commit_sha"] = current_head
            request["review_nonce"] = uuid.uuid4().hex
            request["pending_turn_id"] = None
            request["pending_prompt"] = None
            request["updated_at"] = utc_now()
            atomic_write_json(path, request)
            with contextlib.suppress(FileNotFoundError):
                _routing_choice_path(
                    self.data_dir,
                    str(request["request_id"]),
                ).unlink()
        return path, request, current_candidates

    def _verify_provisional_claim(
        self,
        claim: Mapping[str, Any],
        *,
        require_original_current: bool,
    ) -> RemoteTaskState:
        if claim.get("state") != "provisional_active":
            raise IdentityError("provisional task claim is not active")
        proposal_path = validate_repo_path(
            claim.get("proposal_binding_path"),
            "provisional proposal path",
        )
        if not self.git.file_exists(proposal_path):
            raise IdentityError("provisional task proposal no longer exists")
        if self.git.blob_sha(proposal_path) != claim.get(
            "proposal_binding_blob_sha"
        ):
            raise ConflictError("provisional task proposal changed remotely")
        binding = self.git.show_json(proposal_path)
        source_id = validate_identifier(claim.get("source_id"), "source_id")
        task_id = validate_identifier(claim.get("task_id"), "task_id")
        if (
            binding.get("schema_version") != "binding/v1"
            or binding.get("binding_id") != claim.get("proposal_binding_id")
            or binding.get("state") != "proposed"
            or binding.get("confidence") != "assistant_inferred"
            or binding.get("confirmation_basis") is not None
            or binding.get("subject") != {"kind": "source", "id": source_id}
            or binding.get("targets")
            != [
                {
                    "semantic_task_id": task_id,
                    "relation": "source_for",
                    "role": "primary",
                }
            ]
        ):
            raise IdentityError("provisional task proposal is invalid")
        assessment = binding.get("proposal_assessment")
        if (
            not isinstance(assessment, Mapping)
            or assessment.get("policy_version")
            != "user-authorized-semantic-quorum-v1"
            or assessment.get("evidence_digest_sha256")
            != claim.get("initial_evidence_digest_sha256")
        ):
            raise IdentityError("provisional task assessment is invalid")
        source_path = f"sources/{source_id}/SOURCE.json"
        source = self.git.show_json(source_path)
        _validate_source(source)
        if source.get("external_source_key_sha256") != claim.get(
            "expected_source_key_sha256"
        ):
            raise IdentityError("provisional source identity changed")
        for path in self.git.list_paths("bindings/confirmed"):
            if not re.fullmatch(r"bindings/confirmed/[^/]+\.json", path):
                continue
            confirmed = self.git.show_json(path)
            if (
                confirmed.get("schema_version") == "binding/v1"
                and confirmed.get("state") == "confirmed"
                and confirmed.get("subject")
                == {"kind": "source", "id": source_id}
            ):
                raise ConflictError(
                    "provisional source already has a confirmed route"
                )
        remote = load_remote_task_by_id(self.git, task_id)
        if (
            remote.task.get("task_type") != "semantic_task"
            or remote.task.get("status") != "active"
        ):
            raise IdentityError(
                "provisional target is no longer an active semantic task"
            )
        if require_original_current and remote.current_blob_sha != claim.get(
            "task_current_blob_sha"
        ):
            raise ConflictError(
                "cloud task advanced during the provisional consistency check"
            )
        return remote

    def _drive(self) -> DriveAdapter:
        if self.drive is None:
            self.drive = make_drive_adapter(
                self.config,
                data_dir=self.data_dir,
            )
        return self.drive

    def _object_store(self, store_id: str | None = None) -> DriveAdapter:
        if store_id is None:
            return self._drive()
        selected = validate_identifier(store_id, "store_id")
        primary = _object_store_config(self.config)
        if selected == primary.get("store_id"):
            return self._drive()
        cached = self.object_stores.get(selected)
        if cached is None:
            cached = make_drive_adapter(
                self.config,
                store_id=selected,
                data_dir=self.data_dir,
            )
            self.object_stores[selected] = cached
        return cached

    def _artifact_store(self, artifact: Mapping[str, Any]) -> DriveAdapter:
        if artifact.get("storage_ref") is None:
            # Pre-v0.13.7 manifests used Drive-only fields. After switching
            # the writable primary, they must continue to route to the
            # archived default Google store. Test-only legacy manifests fall
            # back to their configured primary adapter.
            legacy = _object_store_config(self.config)
            with contextlib.suppress(VaultSyncError):
                candidate = _object_store_config(
                    self.config,
                    DEFAULT_OBJECT_STORE_ID,
                )
                if candidate.get("driver") == "google-drive-v3":
                    legacy = candidate
            storage_ref = _artifact_storage_ref(
                artifact,
                legacy_store_id=str(legacy["store_id"]),
                legacy_driver=str(legacy["driver"]),
            )
        else:
            storage_ref = _artifact_storage_ref(artifact)
        adapter = self._object_store(storage_ref["store_id"])
        if adapter.driver != storage_ref["driver"]:
            raise VerificationError(
                "artifact storage reference driver does not match its "
                "configured store"
            )
        return adapter

    def _identity_for_input(
        self,
        hook_input: Mapping[str, Any],
        *,
        task_id: str | None = None,
    ) -> PortableIdentity:
        cwd = hook_input.get("cwd")
        if not isinstance(cwd, str) or not os.path.isabs(cwd):
            raise IdentityError("hook working directory is invalid")
        return resolve_workspace(
            Path(cwd),
            self.config["privacy"]["allowed_roots"],
            task_id=task_id,
        )

    def _identity_from_session_input(
        self,
        hook_input: Mapping[str, Any],
        session: Mapping[str, Any],
    ) -> TaskIdentity:
        identity_kind = session.get("identity_kind", "workspace")
        if identity_kind in {"source", "provisional_source"}:
            session_id = hook_input.get("session_id")
            external_key = _codex_source_key(session_id)
            if external_key != session.get("source_external_key_sha256"):
                raise IdentityError("conversation source changed after SessionStart")
            if identity_kind == "provisional_source":
                device = _device_state(self.data_dir)
                session_key = _session_key(device, str(session_id))
                claim_record = _load_provisional_claim(
                    self.data_dir,
                    session_key,
                )
                if claim_record is None:
                    raise IdentityError("provisional task claim is missing")
                claim = claim_record[1]
                if (
                    claim.get("state") != "provisional_active"
                    or claim.get("claim_id") != session.get("claim_id")
                    or claim.get("task_id") != session.get("task_id")
                    or claim.get("proposal_binding_id")
                    != session.get("binding_id")
                    or claim.get("source_id") != session.get("source_id")
                    or claim.get("expected_source_key_sha256")
                    != external_key
                ):
                    raise IdentityError("provisional task claim changed")
            return SourceIdentity(
                binding_id=validate_identifier(
                    session.get("binding_id"), "binding_id"
                ),
                task_id=validate_identifier(session.get("task_id"), "task_id"),
                source_id=validate_identifier(
                    session.get("source_id"), "source_id"
                ),
                external_source_key_sha256=external_key,
            )
        if identity_kind != "workspace":
            raise IdentityError("local session identity kind is invalid")
        return self._identity_for_input(
            hook_input,
            task_id=validate_identifier(session.get("task_id"), "task_id"),
        )

    def _materialize_remote_artifacts(
        self,
        identity: PortableIdentity,
        remote: RemoteTaskState,
        *,
        maximum_bytes: int | None = None,
    ) -> tuple[str | None, str | None]:
        if not self.config["sync"].get("pull_artifacts", True):
            return None, None
        artifacts = remote.manifest.get("artifacts")
        if not isinstance(artifacts, list) or not artifacts:
            return None, None
        snapshot_id = validate_identifier(
            remote.current.get("snapshot_id"), "snapshot_id"
        )
        task_id = validate_identifier(remote.current.get("task_id"), "task_id")
        relative_root = PurePosixPath(
            ".memory-vault", "versions", task_id, snapshot_id
        )
        root = identity.workspace_root / relative_root
        cursor = identity.workspace_root
        for component in relative_root.parts:
            cursor = cursor / component
            if cursor.exists():
                assert_plain_path(cursor, require_file=False)
            else:
                ensure_private_dir(cursor)
        maximum = (
            int(maximum_bytes)
            if maximum_bytes is not None
            else int(self.config["sync"].get("max_auto_pull_bytes"))
        )
        planned = 0
        downloaded = 0
        already_present = 0
        deferred = 0
        for raw_artifact in artifacts:
            if not isinstance(raw_artifact, Mapping):
                raise VerificationError("remote artifact entry is invalid")
            artifact_id = validate_identifier(
                raw_artifact.get("artifact_id"), "artifact_id"
            )
            sha256 = validate_sha256(
                raw_artifact.get("sha256"), "artifact.sha256"
            )
            size = int(raw_artifact.get("size"))
            if size < 1:
                raise VerificationError("remote artifact has an invalid size")
            display_name = raw_artifact.get("display_name")
            suffix = ""
            if isinstance(display_name, str):
                candidate = Path(display_name).suffix.lower()
                if re.fullmatch(r"\.[a-z0-9]{1,12}", candidate):
                    suffix = candidate
            filename = f"{artifact_id}-{sha256[:12]}{suffix}"
            destination = root / filename
            if destination.exists():
                existing_sha, existing_size = stable_hash_file(
                    destination, inspect_text=False
                )
                if existing_sha != sha256 or existing_size != size:
                    raise VerificationError(
                        "a versioned artifact path contains different content"
                    )
                already_present += 1
                continue
            if planned + size > maximum:
                deferred += 1
                continue
            planned += size
            self._artifact_store(raw_artifact).download_and_verify(
                raw_artifact,
                destination,
            )
            receipt = {
                "schema_version": "memory-vault-local-artifact/v1",
                "task_id": task_id,
                "snapshot_id": snapshot_id,
                "artifact_id": artifact_id,
                "sha256": sha256,
                "size": size,
                "relative_path": (
                    relative_root / filename
                ).as_posix(),
                "verified_at": utc_now(),
                "source": "private-object-store",
                "working_files_overwritten": False,
            }
            atomic_write_json(root / f"RECEIPT-{artifact_id}.json", receipt)
            downloaded += 1
        note = (
            "Versioned artifacts: "
            f"{downloaded} downloaded, {already_present} already verified"
        )
        if deferred:
            note += f", {deferred} deferred by the foreground size limit"
        note += f" under {relative_root.as_posix()}; working files were not overwritten."
        warning = (
            "Some private object-store artifacts were deferred; use the plugin sync command "
            "when a longer transfer window is available."
            if deferred
            else None
        )
        return note, warning

    def _assert_existing_adoption_session_ready(
        self,
        session_id: str,
        task_id: str,
    ) -> None:
        """Refuse to overwrite an old local baseline or unqueued visible turn."""

        device = _device_state(self.data_dir)
        session_key = _session_key(device, session_id)
        loaded = _load_session(self.data_dir, device, session_id)
        if loaded is not None and loaded[1].get("task_id") != task_id:
            raise ConflictError(
                "the existing native task already has a different local task baseline"
            )
        prompt_root = self.data_dir / "state" / "prompts" / session_key
        if prompt_root.exists() and any(prompt_root.glob("*.json")):
            raise BusyError(
                "the existing native task has an unfinished visible turn"
            )
        pending_root = self.data_dir / "outbox" / "pending"
        if pending_root.exists():
            for path in sorted(pending_root.glob("*.json")):
                value = load_json(path)
                if (
                    isinstance(value, Mapping)
                    and value.get("session_key") == session_key
                ):
                    raise BusyError(
                        "the existing native task has an unfinished checkpoint"
                    )

    def _register_native_handoff_source(
        self,
        session_id: str,
        task_id: str,
        mode: str,
        *,
        allow_user_reassignment: bool = False,
        allow_legacy_revalidation: bool = False,
        content_review_attestation: Mapping[str, Any] | None = None,
    ) -> SourceIdentity:
        """Create the exact source identity for one user-approved native task."""

        if mode not in NATIVE_HANDOFF_MODES:
            raise IdentityError("native task handoff mode is invalid")
        task_id = validate_identifier(task_id, "native handoff task_id")
        external_key = _codex_source_key(session_id)
        source_matches: list[tuple[str, Mapping[str, Any]]] = []
        for path in self.git.list_paths("sources"):
            match = re.fullmatch(r"sources/([^/]+)/SOURCE\.json", path)
            if match is None:
                continue
            source_id = validate_identifier(match.group(1), "source_id")
            source = self.git.show_json(path)
            if source.get("external_source_key_sha256") == external_key:
                _validate_source(source)
                source_matches.append((source_id, source))
        if len(source_matches) > 1:
            raise ConflictError(
                "the native Codex task matches more than one remote source"
            )

        now = utc_now()
        files: dict[str, bytes] = {}
        if source_matches:
            source_id, source = source_matches[0]
            catalog, _index = _discover_remote_task_catalog(self.git)
            for split in _discover_structural_splits(
                self.git,
                set(catalog),
            ):
                if split.get("source_id") != source_id:
                    continue
                route = split.get("continuation_route")
                if not isinstance(route, Mapping):
                    raise ConflictError(
                        "this native task is a split source and requires its "
                        "one-time continuation route first"
                    )
                _require_current_attested_source_route(
                    self.git,
                    source_id=source_id,
                    task_id=str(route["target_task_id"]),
                    binding_id=str(route["binding_id"]),
                    source_sequence_from=int(
                        route["source_sequence_from"]
                    ),
                )
                if route.get("target_task_id") != task_id:
                    raise StructuralRouteCorrectionRequired(
                        "this native task already routes to another split child; "
                        "an append-only structural route correction is required"
                    )
        else:
            source_id = validate_identifier(
                f"src-codex-{external_key[:32]}",
                "source_id",
            )
            source_path = f"sources/{source_id}/SOURCE.json"
            if self.git.file_exists(source_path):
                raise ConflictError(
                    "the deterministic native source path is already occupied"
                )
            revision_id = validate_identifier(
                f"rev-handoff-{external_key[:32]}",
                "revision_id",
            )
            source = {
                "schema_version": "source/v1",
                "source_id": source_id,
                "source_type": "codex_task",
                "external_source_key_sha256": external_key,
                "source_instance_id": None,
                "visibility": "private",
                "sensitivity": "restricted",
                "current_revision_id": revision_id,
                "revisions": [
                    {
                        "revision_id": revision_id,
                        "previous_revision_id": None,
                        "source_sequence": 0,
                        "captured_at": now,
                        "coverage": "unknown",
                        "content_ref": None,
                        "content_sha256": None,
                        "redaction": {
                            "credentials_scanned": True,
                            "content_removed": True,
                            "reason": (
                                "Native task identity metadata; no prompt "
                                "content was stored in this revision."
                            ),
                        },
                    }
                ],
                "created_at": now,
            }
            _validate_source(source)
            assert_remote_safe(source)
            files[source_path] = pretty_json_bytes(source)

        validated_attestation = (
            _validate_source_route_content_attestation(
                content_review_attestation,
                source_id=source_id,
                task_id=task_id,
            )
            if content_review_attestation is not None
            else None
        )
        previous_route = _active_primary_source_route(self.git, source_id)
        retired_legacy_route = bool(
            previous_route is not None
            and _source_route_requires_content_revalidation(previous_route)
        )
        if (
            previous_route is not None
            and previous_route.task_id == task_id
            and not retired_legacy_route
        ):
            binding_id = previous_route.binding_id
        elif (
            previous_route is not None
            and retired_legacy_route
            and not allow_legacy_revalidation
        ):
            raise ConflictError(
                "the legacy source route requires a current "
                "content review and visible-turn confirmation"
            )
        elif (
            previous_route is not None
            and not allow_user_reassignment
            and not (
                retired_legacy_route
                and allow_legacy_revalidation
            )
        ):
            raise ConflictError(
                "the native Codex task already has a different primary route"
            )
        else:
            if previous_route is not None and mode != "existing_adoption":
                raise ConflictError(
                    "only an explicitly adopted existing task can change route"
                )
            if (
                validated_attestation is None
                and LEGACY_AUTO_BINDING_DISABLED
            ):
                raise IdentityError(
                    "a new primary source route requires the frozen full-content "
                    "review and next-visible-turn confirmation"
                )
            source_sequence_from = len(source["revisions"])
            binding_key = sha256_bytes(
                (
                    f"{source_id}\0{task_id}\0{source_sequence_from}\0"
                    f"{previous_route.binding_id if previous_route else ''}"
                ).encode("utf-8")
            )
            binding_id = validate_identifier(
                f"bnd-native-{binding_key[:32]}",
                "binding_id",
            )
            binding_path = f"bindings/confirmed/{binding_id}.json"
            if self.git.file_exists(binding_path):
                raise ConflictError(
                    "the deterministic native binding path is already occupied"
                )
            evidence_id = validate_identifier(
                f"evidence-native-{binding_key[:24]}",
                "evidence_id",
            )
            binding = {
                "schema_version": "binding/v1",
                "binding_id": binding_id,
                "subject": {"kind": "source", "id": source_id},
                "targets": [
                    {
                        "semantic_task_id": task_id,
                        "relation": "source_for",
                        "role": "primary",
                    }
                ],
                "effective_range": {
                    "source_sequence_from": source_sequence_from,
                    "source_sequence_to": None,
                },
                "state": "confirmed",
                "confidence": "user_confirmed",
                "confirmation_basis": (
                    SOURCE_ROUTE_CONFIRMATION_BASIS
                    if validated_attestation is not None
                    else "user_confirmation"
                ),
                "evidence": [
                    {
                        "evidence_id": evidence_id,
                        "kind": "user_confirmation",
                        "strength": "authoritative",
                        "assertion": (
                            (
                                "The user explicitly corrected this exact "
                                "native Codex task from its prior confirmed "
                                "route to the selected semantic task."
                            )
                            if previous_route is not None
                            else (
                                "The user approved adopting this exact existing "
                                "native Codex task as a continuation of the "
                                "selected semantic task."
                            )
                            if mode == "existing_adoption"
                            else (
                                "The user approved creating this native Codex "
                                "continuation task for the selected semantic task."
                            )
                        ),
                    }
                ],
                "created_at": now,
                "created_by": {
                    "actor_kind": "client",
                    "actor_id": "memory-vault-sync",
                },
            }
            if validated_attestation is not None:
                binding["content_review_attestation"] = (
                    validated_attestation
                )
            if previous_route is not None:
                binding["supersedes_binding_id"] = previous_route.binding_id
                if previous_route.task_id == task_id:
                    binding["route_revalidation"] = {
                        "reason": "missing_current_content_attestation",
                        "target_task_id": task_id,
                    }
                else:
                    prior_content_sequences = [
                        int(revision["source_sequence"])
                        for revision in source["revisions"]
                        if isinstance(revision, Mapping)
                        and isinstance(revision.get("source_sequence"), int)
                        and int(revision["source_sequence"])
                        >= previous_route.source_sequence_from
                        and int(revision["source_sequence"])
                        < source_sequence_from
                        and revision.get("content_ref") is not None
                    ]
                    binding["route_correction"] = {
                        "previous_task_id": previous_route.task_id,
                        "effective_source_sequence_from": (
                            source_sequence_from
                        ),
                        "historical_content_review_required": bool(
                            prior_content_sequences
                        ),
                        "potentially_misrouted_sequence_count": len(
                            prior_content_sequences
                        ),
                    }
            assert_remote_safe(binding)
            files[binding_path] = pretty_json_bytes(binding)

        if files:
            transaction_id = f"native-{uuid.uuid4().hex}"
            with self.git.create_worktree() as worktree:
                self.git.write_generated_files(worktree, files)
                self._validate_worktree(worktree, files)
                self.git.commit_and_push(
                    worktree,
                    files,
                    task_id,
                    transaction_id,
                )
            self.git.fetch()
        identity = resolve_source_identity(self.git, session_id)
        if identity.task_id != task_id or identity.binding_id != binding_id:
            raise VerificationError(
                "native Codex task source binding could not be verified"
            )
        return identity

    def _activate_native_handoff(
        self,
        hook_input: Mapping[str, Any],
        token: str,
    ) -> str:
        handoff_path, handoff = _load_native_handoff(self.data_dir, token)
        mode = str(handoff["mode"])
        cwd = hook_input.get("cwd")
        if not isinstance(cwd, str) or not os.path.isabs(cwd):
            raise IdentityError("native task working directory is invalid")
        workspace_root = Path(str(handoff["workspace_root"])).resolve(strict=True)
        resolved_cwd = Path(cwd).resolve(strict=True)
        if not _path_is_within(resolved_cwd, workspace_root):
            raise IdentityError(
                "native task opened outside its approved project workspace"
            )
        task_id = validate_identifier(handoff["task_id"], "handoff.task_id")
        session_id = hook_input.get("session_id")
        if not isinstance(session_id, str) or not session_id:
            raise IdentityError("native task session identity is missing")
        if (
            mode == "existing_adoption"
            and _codex_source_key(session_id)
            != handoff.get("expected_source_key_sha256")
        ):
            raise IdentityError(
                "existing native task adoption was sent to the wrong task"
            )

        self.git.ensure()
        if mode == "existing_adoption":
            expected_source = resolve_source_identity(self.git, session_id)
            if (
                expected_source.task_id != task_id
                or expected_source.source_id
                != handoff.get("expected_source_id")
                or expected_source.binding_id
                != handoff.get("expected_source_binding_id")
            ):
                raise IdentityError(
                    "existing-task adoption source route changed after preparation"
                )
            device = _device_state(self.data_dir)
            existing_guard_record = _load_adoption_guard(
                self.data_dir,
                device,
                workspace_root,
                task_id,
            )
            if existing_guard_record is not None:
                existing_guard = existing_guard_record[1]
                if (
                    existing_guard.get("expected_source_key_sha256")
                    != _codex_source_key(session_id)
                    or existing_guard.get("binding_id")
                    != handoff.get("binding_id")
                    or existing_guard.get("workspace_lineage_id")
                    != handoff.get("workspace_lineage_id")
                ):
                    raise IdentityError(
                        "existing-task adoption journal is inconsistent"
                    )
            fingerprint_matches = (
                _workspace_identity_fingerprint(workspace_root)
                == handoff.get("workspace_identity_fingerprint")
            )
            if not fingerprint_matches:
                safe_resume = False
                if existing_guard_record is not None:
                    existing_guard = existing_guard_record[1]
                    prepared_documents = handoff.get("identity_documents")
                    observed = {
                        item.task_id: (item.binding_id, item.lineage_id)
                        for item in _portable_identities_in_workspace(
                            workspace_root
                        )
                    }
                    expected: dict[str, tuple[str, str]] = {}
                    if isinstance(prepared_documents, list):
                        for document in prepared_documents:
                            if not isinstance(document, Mapping):
                                break
                            parsed = _parse_identity_value(
                                document,
                                workspace_root / ".vault_identities.json",
                            )
                            expected[parsed.task_id] = (
                                parsed.binding_id,
                                parsed.lineage_id,
                            )
                    portable_gate = _load_portable_adoptions(
                        workspace_root
                    ).get(task_id)
                    safe_resume = (
                        bool(expected)
                        and all(observed.get(key) == value for key, value in expected.items())
                        and existing_guard.get("expected_source_key_sha256")
                        == _codex_source_key(session_id)
                        and existing_guard.get("artifact_publication_blocked")
                        is True
                        and isinstance(portable_gate, Mapping)
                        and portable_gate.get("artifact_publication_blocked")
                        is True
                    )
                if not safe_resume:
                    raise IdentityError(
                        "workspace identity changed after adoption preparation"
                    )
            self._assert_existing_adoption_session_ready(session_id, task_id)
            documents = handoff.get("identity_documents")
            if not isinstance(documents, list):
                raise IdentityError("existing native task adoption has no identities")
            refreshed_documents: list[Mapping[str, Any]] = []
            for document in documents:
                if not isinstance(document, Mapping):
                    raise IdentityError(
                        "existing native task adoption identity is invalid"
                    )
                prepared = _parse_identity_value(
                    document,
                    workspace_root / ".vault_identities.json",
                )
                verified = load_remote_task(self.git, prepared)
                refreshed_documents.append(
                    _portable_identity_document(
                        self.git,
                        verified,
                        WorkspaceAuthority(
                            binding_id=prepared.binding_id,
                            task_id=prepared.task_id,
                            lineage_id=prepared.lineage_id,
                        ),
                    )
                )
            documents = refreshed_documents
            target_documents = [
                document
                for document in documents
                if isinstance(document, Mapping)
                and document.get("semantic_task_id") == task_id
            ]
            if len(target_documents) != 1:
                raise IdentityError("existing native task adoption target is ambiguous")
            prepared_identity = _parse_identity_value(
                target_documents[0],
                workspace_root / ".vault_identities.json",
            )
            remote = load_remote_task(self.git, prepared_identity)
        else:
            identity = resolve_workspace(
                resolved_cwd,
                self.config["privacy"]["allowed_roots"],
                task_id=task_id,
            )
            if (
                identity.binding_id != handoff.get("binding_id")
                or identity.lineage_id != handoff.get("workspace_lineage_id")
            ):
                raise IdentityError(
                    "native task portable identity changed after preparation"
                )
            remote = load_remote_task(self.git, identity)
        if (
            remote.task.get("status") != "active"
            or remote.task.get("task_type") != "semantic_task"
        ):
            raise IdentityError(
                "native task target is no longer an active semantic task"
            )
        source_identity = self._register_native_handoff_source(
            session_id,
            task_id,
            mode,
        )
        if mode == "existing_adoption":
            now = utc_now()
            preexisting_publish = _publish_manifest_fingerprint(
                PortableIdentity(
                    path=workspace_root / ".vault_identities.json",
                    workspace_root=workspace_root,
                    binding_id=str(handoff["binding_id"]),
                    task_id=task_id,
                    lineage_id=str(handoff["workspace_lineage_id"]),
                    base={},
                )
            )
            local_guard = {
                "schema_version": ADOPTION_GUARD_SCHEMA,
                "task_id": task_id,
                "binding_id": str(handoff["binding_id"]),
                "workspace_lineage_id": str(handoff["workspace_lineage_id"]),
                "workspace_root": str(workspace_root),
                "expected_source_key_sha256": _codex_source_key(session_id),
                "cloud_snapshot_id": remote.current["snapshot_id"],
                "cloud_current_blob_sha": remote.current_blob_sha,
                "preexisting_publish_manifest_sha256": preexisting_publish,
                "approved_publish_manifest_sha256": None,
                "artifact_publication_blocked": True,
                "state": "binding_committed",
                "created_at": now,
                "updated_at": now,
            }
            guard_path = _adoption_guard_path(
                self.data_dir,
                device,
                workspace_root,
                task_id,
            )
            if existing_guard_record is not None:
                previous_guard = existing_guard_record[1]
                if (
                    previous_guard.get("expected_source_key_sha256")
                    != local_guard["expected_source_key_sha256"]
                    or previous_guard.get("binding_id")
                    != local_guard["binding_id"]
                    or previous_guard.get("workspace_lineage_id")
                    != local_guard["workspace_lineage_id"]
                ):
                    raise IdentityError(
                        "existing-task adoption journal is inconsistent"
                    )
                local_guard["created_at"] = previous_guard["created_at"]
                local_guard["preexisting_publish_manifest_sha256"] = (
                    previous_guard["preexisting_publish_manifest_sha256"]
                )
            atomic_write_json(guard_path, local_guard)
            portable_guard = {
                key: local_guard[key]
                for key in (
                    "task_id",
                    "binding_id",
                    "workspace_lineage_id",
                    "cloud_snapshot_id",
                    "cloud_current_blob_sha",
                    "preexisting_publish_manifest_sha256",
                    "approved_publish_manifest_sha256",
                    "artifact_publication_blocked",
                    "state",
                    "created_at",
                    "updated_at",
                )
            }
            _write_portable_adoption(workspace_root, portable_guard)
            _merge_workspace_identity_documents(workspace_root, documents)
            identity = resolve_workspace(
                resolved_cwd,
                self.config["privacy"]["allowed_roots"],
                task_id=task_id,
            )
            local_guard["state"] = "cloud_current_loaded"
            local_guard["updated_at"] = utc_now()
            portable_guard["state"] = "cloud_current_loaded"
            portable_guard["updated_at"] = local_guard["updated_at"]
            atomic_write_json(guard_path, local_guard)
            _write_portable_adoption(workspace_root, portable_guard)
        if (
            identity.binding_id != handoff.get("binding_id")
            or identity.lineage_id != handoff.get("workspace_lineage_id")
        ):
            raise IdentityError("native task portable identity is inconsistent")
        remote = load_remote_task(self.git, identity)
        context = _continuation_context(
            remote,
            git=self.git,
            reference_source_ids=[source_identity.source_id],
        )
        adoption: Mapping[str, Any] | None = None
        artifact_snapshot_override: Mapping[str, Any] | None = None
        if mode == "existing_adoption":
            adoption = {
                "mode": mode,
                "state": "cloud_current_loaded",
                "cloud_snapshot_id": remote.current["snapshot_id"],
                "cloud_current_blob_sha": remote.current_blob_sha,
                "local_history_role": "reference_only",
                "artifact_publication_blocked": True,
            }
            artifact_snapshot_override = {}
        try:
            artifact_note, artifact_warning = (
                self._materialize_remote_artifacts(identity, remote)
            )
        except (AuthenticationError, ConfigurationError, OfflineError) as exc:
            artifact_note = (
                "Versioned artifacts are not materialized on this device yet."
            )
            artifact_warning = (
                "Private artifacts remain remote because local object-store "
                f"access is unavailable ({exc.code})."
            )
        if artifact_note:
            context = _append_context_note(
                context, artifact_note, label="artifact materialization notice"
            )
        if artifact_warning:
            context = _append_context_note(
                context, artifact_warning, label="artifact warning"
            )
        _session_key_value, saved_session = self._session_start_state(
            hook_input,
            identity,
            remote,
            continuation_context=context,
            source_id_override=source_identity.source_id,
            source_external_key_override=(
                source_identity.external_source_key_sha256
            ),
            artifact_snapshot_override=artifact_snapshot_override,
            adoption=adoption,
        )
        _consume_native_handoff(handoff_path)
        saved_context = saved_session.get("continuation_context")
        return saved_context if isinstance(saved_context, str) else context

    def _lazy_source_session(
        self,
        hook_input: Mapping[str, Any],
    ) -> str | None:
        session_id = hook_input.get("session_id")
        if not isinstance(session_id, str) or not session_id:
            return None
        self.git.ensure()
        source_identity = resolve_source_identity(self.git, session_id)
        try:
            identity: TaskIdentity = self._identity_for_input(
                hook_input,
                task_id=source_identity.task_id,
            )
        except (UnboundIdentityError, IdentityError):
            # Exact conversation identity wins over a conflicting folder
            # marker, but remains conversation-only and cannot publish files.
            identity = source_identity
        remote = load_remote_task(self.git, identity)
        context = _continuation_context(
            remote,
            git=self.git,
            reference_source_ids=[source_identity.source_id],
        )
        self._session_start_state(
            hook_input,
            identity,
            remote,
            continuation_context=context,
            source_id_override=source_identity.source_id,
            source_external_key_override=(
                source_identity.external_source_key_sha256
            ),
        )
        return context

    def _session_start_state(
        self,
        hook_input: Mapping[str, Any],
        identity: TaskIdentity,
        remote: RemoteTaskState,
        continuation_context: str,
        *,
        source_id_override: str | None = None,
        source_external_key_override: str | None = None,
        artifact_snapshot_override: Mapping[str, Any] | None = None,
        adoption: Mapping[str, Any] | None = None,
    ) -> tuple[str, dict[str, Any]]:
        session_id = hook_input.get("session_id")
        if not isinstance(session_id, str) or not session_id:
            raise IdentityError("hook session_id is missing")
        device = _device_state(self.data_dir)
        key = _session_key(device, session_id)
        existing = _load_session(self.data_dir, device, session_id)
        if source_id_override is not None or source_external_key_override is not None:
            if source_id_override is None or source_external_key_override is None:
                raise IdentityError("session source override is incomplete")
            source_id = source_id_override
            external_key = source_external_key_override
        elif (
            isinstance(identity, PortableIdentity)
            and existing is not None
            and existing[1].get("identity_kind", "workspace") == "workspace"
        ):
            _, previous = existing
            source_id = previous.get("source_id")
            external_key = previous.get("source_external_key_sha256")
        elif isinstance(identity, SourceIdentity):
            source_id = identity.source_id
            external_key = identity.external_source_key_sha256
        else:
            source_id = f"src-{uuid.uuid4().hex}"
            external_key = sha256_bytes(secrets.token_bytes(32))
        source_id = validate_identifier(source_id, "source_id")
        validate_sha256(external_key, "source_external_key_sha256")
        if isinstance(identity, PortableIdentity):
            local_adoption = _load_adoption_guard(
                self.data_dir,
                device,
                identity.workspace_root,
                identity.task_id,
            )
            portable_adoption = _portable_adoption_for(identity)
            adoption_records = [
                record
                for record in (
                    local_adoption[1] if local_adoption is not None else None,
                    portable_adoption,
                )
                if isinstance(record, Mapping)
            ]
            adoption_is_blocked = (
                (portable_adoption is None) != (local_adoption is None)
            ) or (
                local_adoption is not None
                and bool(
                    local_adoption[1].get("artifact_publication_blocked")
                )
            )
            for record in adoption_records:
                if (
                    record.get("binding_id") != identity.binding_id
                    or record.get("workspace_lineage_id") != identity.lineage_id
                ):
                    raise IdentityError(
                        "existing-task adoption conflicts with workspace identity"
                    )
            if adoption is None and adoption_records:
                record = adoption_records[0]
                adoption = {
                    "mode": "existing_adoption",
                    "state": record["state"],
                    "cloud_snapshot_id": record["cloud_snapshot_id"],
                    "cloud_current_blob_sha": record["cloud_current_blob_sha"],
                    "local_history_role": "reference_only",
                    "artifact_publication_blocked": adoption_is_blocked,
                }
            if adoption_is_blocked:
                artifact_snapshot_override = {}
            if adoption_records or adoption is not None:
                continuation_context = _with_adoption_context(
                    continuation_context,
                    blocked=adoption_is_blocked,
                )
        value = {
            "schema_version": SESSION_SCHEMA,
            "continuation_context_contract": CONTINUATION_CONTEXT_CONTRACT,
            "identity_kind": (
                "workspace" if isinstance(identity, PortableIdentity) else "source"
            ),
            "task_id": identity.task_id,
            "binding_id": identity.binding_id,
            "source_id": source_id,
            "source_external_key_sha256": external_key,
            "base": {
                "remote_commit_sha": remote.commit_sha,
                "task_current_path": remote.current_path,
                "task_current_blob_sha": remote.current_blob_sha,
                "task_generation": remote.current["generation"],
                "snapshot_id": remote.current["snapshot_id"],
                "manifest_path": remote.manifest_path,
                "published_transaction_id": remote.current[
                    "published_transaction_id"
                ],
            },
            "base_manifest": dict(remote.manifest),
            "artifact_snapshot": (
                dict(artifact_snapshot_override)
                if artifact_snapshot_override is not None
                else (
                    artifact_snapshot(identity, remote.manifest)
                    if isinstance(identity, PortableIdentity)
                    else {}
                )
            ),
            "continuation_context": continuation_context,
            "reconciliation_required": bool(
                isinstance(remote.memory_projection, Mapping)
                and remote.memory_projection.get("unprojected_deltas")
            ),
            "pending_context_injection": False,
            "needs_remote_refresh": False,
            "started_at": utc_now(),
        }
        if adoption is not None:
            value["adoption"] = dict(adoption)
        if isinstance(identity, PortableIdentity):
            value.update(
                {
                    "workspace_lineage_id": identity.lineage_id,
                    "workspace_instance_id": _workspace_instance(
                        self.data_dir, device, identity.workspace_root
                    ),
                    "workspace_root": str(identity.workspace_root.resolve()),
                }
            )
        _save_session(self.data_dir, key, value)
        return key, value

    def session_start(self, hook_input: Mapping[str, Any]) -> dict[str, Any]:
        if hook_input.get("hook_event_name") != "SessionStart":
            raise PrivacyError("wrong hook event for session-start")
        if self._memory_network_enabled():
            return self.memory_network_session_start(hook_input)
        if not self.config["sync"].get("legacy_task_handoff_enabled", False):
            return hook_json("SessionStart")
        source = hook_input.get("source")
        if source == "compact":
            if not self.config.get("enabled") or not self.config["sync"].get(
                "startup_pull", True
            ):
                return hook_json("SessionStart")
            session_id = hook_input.get("session_id")
            if not isinstance(session_id, str):
                return hook_json("SessionStart")
            device = _device_state(self.data_dir)
            loaded = _load_session(self.data_dir, device, session_id)
            if loaded is None:
                return hook_json("SessionStart")
            session = loaded[1]
            if session.get("identity_kind", "workspace") == "source":
                if not self.git.has_cache():
                    return hook_json(
                        "SessionStart",
                        warning=(
                            "Cached conversation memory was not loaded because "
                            "its current full-content route could not be verified."
                        ),
                    )
                try:
                    current_identity = resolve_source_identity(
                        self.git,
                        session_id,
                    )
                    if (
                        session.get("source_id")
                        != current_identity.source_id
                        or session.get("task_id")
                        != current_identity.task_id
                        or session.get("binding_id")
                        != current_identity.binding_id
                        or session.get("source_external_key_sha256")
                        != current_identity.external_source_key_sha256
                    ):
                        raise IdentityError(
                            "cached source session no longer matches the "
                            "current attested route"
                        )
                except VaultSyncError:
                    return hook_json(
                        "SessionStart",
                        warning=(
                            "Cached conversation memory requires full-content "
                            "route revalidation and was not loaded."
                        ),
                    )
            context = session.get("continuation_context")
            return hook_json(
                "SessionStart",
                context=context if isinstance(context, str) else None,
            )
        if source not in {"startup", "resume", "clear"}:
            return hook_json("SessionStart")
        if not self.config.get("enabled") or not self.config["sync"].get(
            "startup_pull", True
        ):
            return hook_json("SessionStart")
        # Resolve an exact conversation route before parsing any portable
        # workspace marker. A marker controls artifact authority only and must
        # never block or select conversation memory.
        workspace_identity: PortableIdentity | None = None
        reference_only = False
        reference_warning: str | None = None
        identity_warning: str | None = None
        projection_note: str | None = None
        with FileLock(self.lock_path):
            try:
                self.git.ensure()
            except OfflineError:
                if not self.git.has_cache():
                    return hook_json(
                        "SessionStart",
                        warning="Private Memory Vault is offline; no remote checkpoint was loaded.",
                    )
                reference_only = True
                reference_warning = (
                    "Private Memory Vault is offline; cached memory is reference-only."
                )
            except ConflictError:
                if not self.git.has_cache():
                    return hook_json(
                        "SessionStart",
                        warning=(
                            "The remote vault history was rewritten; no unverified "
                            "checkpoint was loaded."
                        ),
                    )
                reference_only = True
                reference_warning = (
                    "The remote vault history moved backwards or was rewritten. "
                    "The last verified checkpoint is reference-only until an explicit "
                    "rollback review is completed."
                )
            session_id = hook_input.get("session_id")
            source_identity: SourceIdentity | None = None
            if isinstance(session_id, str):
                with contextlib.suppress(IdentityError):
                    source_identity = resolve_source_identity(
                        self.git,
                        session_id,
                    )

            identity: TaskIdentity | None = None
            if source_identity is not None:
                try:
                    resolved_workspace_identity = self._identity_for_input(
                        hook_input,
                        task_id=source_identity.task_id,
                    )
                    if isinstance(
                        resolved_workspace_identity,
                        PortableIdentity,
                    ):
                        workspace_identity = resolved_workspace_identity
                        identity = resolved_workspace_identity
                    else:
                        identity = source_identity
                except UnboundIdentityError:
                    identity = source_identity
                except IdentityError:
                    # An exact conversation route is authoritative for memory
                    # continuation.  A conflicting workspace marker must never
                    # override it or grant artifact access.
                    identity = source_identity
                    identity_warning = (
                        "Private Memory Vault：已按当前对话的确认身份加载云端"
                        "进度；这个文件夹仍标记为另一个任务，成果发布已暂停。"
                        "可选择仅切换对话、设为多任务文件夹，或将整个文件夹"
                        "安全改绑。"
                    )
            else:
                try:
                    possible_workspace_identity = self._identity_for_input(
                        hook_input
                    )
                    if isinstance(
                        possible_workspace_identity,
                        PortableIdentity,
                    ):
                        workspace_identity = possible_workspace_identity
                except UnboundIdentityError:
                    workspace_identity = None
                except IdentityError:
                    workspace_identity = None
                    identity_warning = (
                        "Private Memory Vault：这个文件夹的成果身份无效，"
                        "因此成果读取与发布已暂停；当前对话仍可继续进行"
                        "内容证据匹配。"
                    )
                if (
                    isinstance(identity, PortableIdentity)
                    and _source_route_supersedes_prior_binding(
                        self.git,
                        source_identity,
                    )
                    and not _workspace_has_complete_route_guard(
                        self.data_dir,
                        identity,
                        session_id,
                    )
                ):
                    identity = source_identity
                    identity_warning = (
                        "Private Memory Vault：已按当前对话的纠正路由加载"
                        "云端进度，但文件夹的成果安全门不完整；当前仅启用"
                        "对话记忆，成果读取与发布均已暂停。"
                    )

            # A portable marker proves only file/workspace authority.  It does
            # not prove that an otherwise unknown native conversation belongs
            # to that task.  Let the bounded content-matching flow identify the
            # conversation first.
            safe_to_flush_current_route = identity is not None
            if not reference_only:
                lifecycle_session_id = hook_input.get("session_id")
                if isinstance(lifecycle_session_id, str):
                    with contextlib.suppress(VaultSyncError):
                        _recover_pending_reconciliations(
                            self,
                            session_key=_session_key(
                                _device_state(self.data_dir),
                                lifecycle_session_id,
                            ),
                            already_locked=True,
                        )
                if safe_to_flush_current_route:
                    with contextlib.suppress(VaultSyncError):
                        self.flush_once(already_locked=True, ready_only=True)
                try:
                    self.git.fetch()
                except OfflineError:
                    reference_only = True
                    reference_warning = (
                        "Private Memory Vault is offline; cached memory is reference-only."
                    )
                except ConflictError:
                    reference_only = True
                    reference_warning = (
                        "The remote vault history moved backwards or was rewritten. "
                        "The last verified checkpoint is reference-only until an explicit "
                        "rollback review is completed."
                    )
            observed_source_ids: list[str] = []
            if source_identity is not None:
                observed_source_ids.append(source_identity.source_id)
            elif isinstance(session_id, str):
                with contextlib.suppress(IdentityError):
                    source_id, _source_record, _external_key = (
                        resolve_source_record(self.git, session_id)
                    )
                    observed_source_ids.append(source_id)
            try:
                projection_result = self.reconcile(
                    materialize=(
                        False
                        if reference_only
                        else bool(self.config["projection"].get("enabled"))
                    ),
                    already_locked=True,
                    fetch=False,
                    extra_source_ids=observed_source_ids,
                    extra_workspaces=(
                        [workspace_identity.workspace_root]
                        if isinstance(workspace_identity, PortableIdentity)
                        else []
                    ),
                )
                projection_note = self._projection_notification(
                    projection_result
                )
            except VaultSyncError:
                projection_note = None
            if identity is None:
                if not isinstance(session_id, str):
                    return hook_json(
                        "SessionStart",
                        context=projection_note,
                        warning=reference_warning,
                    )
                device = _device_state(self.data_dir)
                existing_local = _load_session(
                    self.data_dir,
                    device,
                    session_id,
                )
                retired_automatic_local = False
                if (
                    LEGACY_AUTO_BINDING_DISABLED
                    and existing_local is not None
                    and existing_local[1].get("identity_kind")
                    in {"source", "provisional_source"}
                ):
                    with contextlib.suppress(VaultSyncError):
                        local_source_id = validate_identifier(
                            existing_local[1].get("source_id"),
                            "source_id",
                        )
                        local_route = _active_primary_source_route(
                            self.git,
                            local_source_id,
                        )
                        retired_automatic_local = bool(
                            local_route is not None
                            and local_route.binding_id
                            == existing_local[1].get("binding_id")
                            and _source_route_requires_content_revalidation(
                                local_route
                            )
                        )
                if (
                    existing_local is not None
                    and (
                        existing_local[1].get(
                            "identity_kind",
                            "workspace",
                        )
                        == "workspace"
                        or retired_automatic_local
                    )
                ):
                    if self._session_has_pending_local_work(existing_local[0]):
                        return hook_json(
                            "SessionStart",
                            context=projection_note,
                            warning=(
                                "Private Memory Vault：这个对话过去仅凭文件夹"
                                "标记建立了身份，但仍有未完成的本地检查点。已暂停"
                                "写回；请先完成安全改绑，旧进度不会被覆盖。"
                            ),
                        )
                    archive_root = (
                        self.data_dir
                        / "state"
                        / (
                            "retired-auto-route-sessions"
                            if retired_automatic_local
                            else "superseded-workspace-sessions"
                        )
                    )
                    ensure_private_dir(archive_root)
                    archive_path = (
                        archive_root
                        / f"{existing_local[0]}-{uuid.uuid4().hex}.json"
                    )
                    os.replace(
                        _session_path(self.data_dir, existing_local[0]),
                        archive_path,
                    )
                try:
                    source_identity = resolve_source_identity(self.git, session_id)
                except IdentityError:
                    device = _device_state(self.data_dir)
                    session_key = _session_key(device, session_id)
                    provisional_record = _load_provisional_claim(
                        self.data_dir,
                        session_key,
                    )
                    if provisional_record is not None:
                        claim_path, claim = provisional_record
                        try:
                            request_record = (
                                _load_routing_request_for_session(
                                    self.data_dir,
                                    device,
                                    session_id,
                                )
                            )
                            if request_record is None:
                                raise IdentityError(
                                    "provisional task matching request is missing"
                                )
                            try:
                                _assert_routing_request_matches_workspace(
                                    request_record[1],
                                    str(hook_input.get("cwd") or ""),
                                    self.config["privacy"]["allowed_roots"],
                                )
                            except VaultSyncError:
                                return hook_json(
                                    "SessionStart",
                                    context=projection_note,
                                    warning=(
                                        "Private Memory Vault kept the "
                                        "provisional route unchanged but did "
                                        "not load it in a different workspace."
                                    ),
                                )
                            (
                                _request_path,
                                verified_request,
                                _catalog,
                            ) = self._verified_routing_request(
                                str(request_record[1]["request_id"]),
                                ensure_remote=False,
                            )
                            if verified_request.get("state") != "provisional":
                                raise IdentityError(
                                    "provisional task matching request changed"
                                )
                            remote = self._verify_provisional_claim(
                                claim,
                                require_original_current=False,
                            )
                        except VaultSyncError as exc:
                            if exc.retryable:
                                return hook_json(
                                    "SessionStart",
                                    context=projection_note,
                                    warning=(
                                        reference_warning
                                        or (
                                            "Private Memory Vault could not "
                                            "recheck the provisional route yet; "
                                            "it remains unchanged."
                                        )
                                    ),
                                )
                            claim["state"] = "revoked"
                            claim["updated_at"] = utc_now()
                            atomic_write_json(claim_path, claim)
                        else:
                            provisional_identity = SourceIdentity(
                                binding_id=validate_identifier(
                                    claim["proposal_binding_id"],
                                    "proposal_binding_id",
                                ),
                                task_id=validate_identifier(
                                    claim["task_id"],
                                    "task_id",
                                ),
                                source_id=validate_identifier(
                                    claim["source_id"],
                                    "source_id",
                                ),
                                external_source_key_sha256=validate_sha256(
                                    claim["expected_source_key_sha256"],
                                    "expected_source_key_sha256",
                                ),
                            )
                            context = _continuation_context(
                                remote,
                                git=self.git,
                                offline=reference_only,
                                reference_source_ids=[
                                    provisional_identity.source_id
                                ],
                            )
                            context = _append_context_note(
                                context,
                                self._routing_context(
                                    verified_request,
                                    state="provisional_consistency_check",
                                    claim_id=str(claim["claim_id"]),
                                ),
                                label="provisional routing control",
                            )
                            self._session_start_state(
                                hook_input,
                                provisional_identity,
                                remote,
                                continuation_context=context,
                                source_id_override=(
                                    provisional_identity.source_id
                                ),
                                source_external_key_override=(
                                    provisional_identity
                                    .external_source_key_sha256
                                ),
                                adoption={
                                    "mode": "provisional_existing_adoption",
                                    "state": "cloud_current_loaded",
                                    "cloud_snapshot_id": remote.current[
                                        "snapshot_id"
                                    ],
                                    "cloud_current_blob_sha": (
                                        remote.current_blob_sha
                                    ),
                                    "local_history_role": "reference_only",
                                    "artifact_publication_blocked": True,
                                },
                            )
                            loaded = _load_session(
                                self.data_dir,
                                device,
                                session_id,
                            )
                            if loaded is not None:
                                loaded[1]["identity_kind"] = (
                                    "provisional_source"
                                )
                                loaded[1]["claim_id"] = claim["claim_id"]
                                _save_session(
                                    self.data_dir,
                                    loaded[0],
                                    loaded[1],
                                )
                            return hook_json(
                                "SessionStart",
                                context=context,
                                warning=(
                                    reference_warning
                                    if reference_warning
                                    else (
                                        "Private Memory Vault：已加载最可能的"
                                        "云端最新进度，正在做最终一致性核对；"
                                        "当前不会覆盖云端正式版本。"
                                    )
                                ),
                            )
                    routing = self._ensure_routing_request(hook_input)
                    routing_context = (
                        routing[1] if routing is not None else projection_note
                    )
                    return hook_json(
                        "SessionStart",
                        context=routing_context,
                        warning=(
                            reference_warning
                            if reference_warning
                            else identity_warning
                            or (
                                "Private Memory Vault：这个本地任务尚未绑定。"
                                "发送任意消息后将核对实际对话、谱系和已声明"
                                "成果；证据不完整或有歧义时会请你选择一次。"
                            )
                        ),
                    )
                try:
                    resolved_workspace_identity = self._identity_for_input(
                        hook_input,
                        task_id=source_identity.task_id,
                    )
                    if isinstance(
                        resolved_workspace_identity,
                        PortableIdentity,
                    ):
                        workspace_identity = resolved_workspace_identity
                        identity = resolved_workspace_identity
                    else:
                        identity = source_identity
                except UnboundIdentityError:
                    identity = source_identity
                except IdentityError:
                    identity = source_identity
                    identity_warning = (
                        "Private Memory Vault：已按当前对话的确认身份加载云端"
                        "进度；文件夹身份与之冲突或无效，成果读取与发布"
                        "已暂停。"
                    )
            remote = load_remote_task(self.git, identity)
            context = _continuation_context(
                remote,
                git=self.git,
                offline=reference_only,
                reference_source_ids=(
                    [identity.source_id]
                    if isinstance(identity, SourceIdentity)
                    else []
                ),
            )
            artifact_warning: str | None = None
            if not reference_only and isinstance(identity, PortableIdentity):
                try:
                    artifact_note, artifact_warning = (
                        self._materialize_remote_artifacts(identity, remote)
                    )
                except (AuthenticationError, ConfigurationError, OfflineError) as exc:
                    artifact_note = (
                        "Versioned artifacts are not materialized on this device yet."
                    )
                    artifact_warning = (
                        "Private object-store artifacts remain remote because "
                        "local object-store access is unavailable "
                        f"({exc.code})."
                    )
                if artifact_note:
                    context = _append_context_note(
                        context,
                        artifact_note,
                        label="artifact materialization notice",
                    )
            if projection_note:
                context = _append_context_note(
                    context,
                    projection_note,
                    label="task projection notice",
                )
            _session_key_value, saved_session = self._session_start_state(
                hook_input,
                identity,
                remote,
                continuation_context=context,
                source_id_override=(
                    source_identity.source_id
                    if source_identity is not None
                    else None
                ),
                source_external_key_override=(
                    source_identity.external_source_key_sha256
                    if source_identity is not None
                    else None
                ),
            )
            saved_context = saved_session.get("continuation_context")
            if isinstance(saved_context, str):
                context = saved_context
        return hook_json(
            "SessionStart",
            context=context,
            warning=(
                reference_warning
                if reference_only
                else identity_warning or artifact_warning
            ),
        )

    def _session_has_pending_local_work(self, session_key: str) -> bool:
        session_task_id: str | None = None
        session_path = _session_path(self.data_dir, session_key)
        if session_path.exists():
            value = load_json(session_path)
            if isinstance(value, Mapping):
                if isinstance(
                    value.get("active_reconciliation_token_sha256"),
                    str,
                ):
                    return True
                raw_task_id = value.get("task_id")
                if isinstance(raw_task_id, str):
                    session_task_id = raw_task_id
        prompt_root = self.data_dir / "state" / "prompts" / session_key
        if prompt_root.exists() and any(
            path.is_file() and path.suffix == ".json"
            for path in prompt_root.iterdir()
        ):
            return True
        pending_root = self.data_dir / "outbox" / "pending"
        if pending_root.exists():
            for path in pending_root.iterdir():
                if not path.is_file() or path.suffix != ".json":
                    continue
                with contextlib.suppress(
                    VaultSyncError,
                    OSError,
                    ValueError,
                    json.JSONDecodeError,
                ):
                    value = load_json(path)
                    if (
                        isinstance(value, Mapping)
                        and value.get("session_key") == session_key
                    ):
                        return True
        for root_name in (
            "reconciliation-pending",
            "reconciliation-needs-authorization",
        ):
            root = self.data_dir / "state" / root_name
            if not root.exists():
                continue
            for path in root.glob("*.json"):
                if path.name.endswith(".reason.json"):
                    continue
                with contextlib.suppress(
                    VaultSyncError,
                    OSError,
                    ValueError,
                ):
                    pending = load_json(path)
                    if not isinstance(pending, Mapping):
                        continue
                    authorization = pending.get("authorization")
                    if (
                        isinstance(authorization, Mapping)
                        and authorization.get("session_key")
                        == session_key
                    ):
                        return True
                    if (
                        authorization is None
                        and session_task_id is not None
                        and pending.get("task_id") == session_task_id
                    ):
                        return True
        return False

    def _refresh_open_session(
        self,
        hook_input: Mapping[str, Any],
        session_key: str,
        session: MutableMapping[str, Any],
    ) -> tuple[dict[str, Any], str | None]:
        if session.get("identity_kind") == "provisional_source":
            return dict(session), None
        pending_local_work = self._session_has_pending_local_work(
            session_key
        )
        try:
            identity = self._identity_from_session_input(
                hook_input,
                session,
            )
        except (IdentityError, PrivacyError):
            raise IdentityError(
                "open session identity changed before CURRENT refresh"
            )
        try:
            with FileLock(self.lock_path):
                self.git.ensure()
                remote = load_remote_task(self.git, identity)
                base = session.get("base")
                if not isinstance(base, Mapping):
                    raise VerificationError(
                        "open session has no verified CURRENT baseline"
                    )
                if (
                    remote.current_blob_sha
                    != base.get("task_current_blob_sha")
                    or session.get("needs_remote_refresh") is True
                ):
                    if pending_local_work:
                        _invalidate_session_reconciliation_ticket(
                            self.data_dir,
                            session,
                        )
                        session["needs_remote_refresh"] = True
                        session["pending_context_injection"] = True
                        _save_session(
                            self.data_dir,
                            session_key,
                            session,
                        )
                        return dict(session), (
                            "Private Memory Vault detected a newer cloud "
                            "CURRENT but preserved pending local work instead "
                            "of rebasing it. No stale reconciliation token was "
                            "issued."
                        )
                    self._refresh_session_after_publish(
                        {
                            "session_key": session_key,
                            "task_id": session["task_id"],
                            "binding_id": session["binding_id"],
                        },
                        remote,
                        pending_injection=True,
                        remote_advance=True,
                    )
                    refreshed = load_json(
                        _session_path(self.data_dir, session_key)
                    )
                    if not isinstance(refreshed, dict):
                        raise VerificationError(
                            "refreshed session state is invalid"
                        )
                    return refreshed, None
        except OfflineError:
            return dict(session), (
                "Private Memory Vault could not compare cloud CURRENT while "
                "offline; the last verified baseline remains reference-only."
            )
        return dict(session), None

    def _issue_reconciliation_ticket(
        self,
        *,
        session_key: str,
        session: MutableMapping[str, Any],
        turn_id: str,
        turn_key: str,
    ) -> tuple[str | None, str | None]:
        if session.get("pending_context_injection") is not True:
            return None, None
        if session.get("needs_remote_refresh") is True:
            # A candidate/push race may leave a prompt or outbox pending.  Do
            # not mint a capability against the known-stale CURRENT; keep the
            # pending injection intact so a later verified refresh can retry.
            return None, None
        context = session.get("continuation_context")
        if not isinstance(context, str):
            raise VerificationError(
                "pending continuation injection has no capsule"
            )
        session["pending_context_injection"] = False
        if session.get("reconciliation_required") is not True:
            _save_session(self.data_dir, session_key, session)
            return context, None
        base = session.get("base")
        manifest = session.get("base_manifest")
        if not isinstance(base, Mapping) or not isinstance(
            manifest, Mapping
        ):
            raise VerificationError(
                "reconciliation ticket has no exact session baseline"
            )
        projection_reference = manifest.get("memory_projection")
        if not isinstance(projection_reference, Mapping):
            raise VerificationError(
                "reconciliation ticket has no source projection"
            )
        source_projection_id = validate_identifier(
            projection_reference.get("projection_id"),
            "ticket source projection ID",
        )
        _invalidate_session_reconciliation_ticket(self.data_dir, session)
        token = secrets.token_urlsafe(32)
        if len(token) != 43 or not re.fullmatch(
            r"[A-Za-z0-9_-]{43}",
            token,
        ):
            raise VerificationError(
                "reconciliation token generation failed"
            )
        token_sha256 = sha256_bytes(token.encode("ascii"))
        issued = dt.datetime.now(dt.timezone.utc)
        expires = issued + dt.timedelta(
            seconds=RECONCILIATION_TICKET_TTL_SECONDS
        )
        ticket = {
            "schema_version": "memory-vault-reconciliation-ticket/v1",
            "token_sha256": token_sha256,
            "session_key": session_key,
            "task_id": session["task_id"],
            "turn_id": turn_id,
            "turn_key": turn_key,
            "binding_id": session["binding_id"],
            "identity_kind": session["identity_kind"],
            "workspace_lineage_id": session.get("workspace_lineage_id"),
            "source_projection_id": source_projection_id,
            "expected_current_blob_sha": base[
                "task_current_blob_sha"
            ],
            "issued_at": issued.isoformat().replace("+00:00", "Z"),
            "expires_at": expires.isoformat().replace("+00:00", "Z"),
            "state": "issued",
        }
        atomic_write_json(
            _reconciliation_ticket_path(self.data_dir, token_sha256),
            ticket,
        )
        session["active_reconciliation_token_sha256"] = token_sha256
        _save_session(self.data_dir, session_key, session)
        control = (
            "Memory reconciliation control: use this one-time token only in "
            "the current turn after reading the newest delta. Run "
            "`reconcile-memory --session-token "
            + token
            + " --task-id "
            + str(session["task_id"])
            + " --expected-current-blob-sha "
            + str(base["task_current_blob_sha"])
            + " --proposal-file <typed-v2-patch.json>`. The token is scoped "
            "to this task, turn, CURRENT blob, and source projection."
        )
        return _append_context_note(
            context,
            control,
            label="memory reconciliation control",
        ), token

    def user_prompt_submit(self, hook_input: Mapping[str, Any]) -> dict[str, Any]:
        if hook_input.get("hook_event_name") != "UserPromptSubmit":
            raise PrivacyError("wrong hook event for user-prompt-submit")
        if self._memory_network_enabled():
            return self.memory_network_user_prompt_submit(hook_input)
        if not self.config["sync"].get("legacy_task_handoff_enabled", False):
            return hook_json("UserPromptSubmit")
        if not self.config.get("enabled"):
            return hook_json("UserPromptSubmit")
        session_id = hook_input.get("session_id")
        turn_id = hook_input.get("turn_id")
        if not isinstance(session_id, str) or not isinstance(turn_id, str):
            return hook_json("UserPromptSubmit")
        try:
            handoff_token, prompt = _extract_native_handoff_prompt(
                hook_input.get("prompt")
            )
        except PrivacyError as exc:
            device = _device_state(self.data_dir)
            transaction = _transaction_id(device, session_id, turn_id)
            quarantine = {
                "schema_version": "memory-vault-sync-quarantine/v1",
                "transaction_id": transaction,
                "reason_code": exc.code,
                "created_at": utc_now(),
                "content_preserved": False,
            }
            atomic_write_json(
                _outbox_path(self.data_dir, "quarantine", transaction),
                quarantine,
            )
            return hook_json(
                "UserPromptSubmit",
                warning=(
                    "This turn contains private local data that was not queued "
                    "for remote backup."
                ),
            )

        device = _device_state(self.data_dir)
        loaded = _load_session(self.data_dir, device, session_id)
        context: str | None = None
        recovery_warning: str | None = None
        if handoff_token is not None:
            try:
                with FileLock(self.lock_path):
                    context = self._activate_native_handoff(
                        hook_input,
                        handoff_token,
                    )
                loaded = _load_session(self.data_dir, device, session_id)
            except VaultSyncError:
                return hook_json(
                    "UserPromptSubmit",
                    warning=(
                        "The one-time private task handoff could not be "
                        "verified. No task identity was guessed or changed."
                    ),
                )
        elif (
            self.config["sync"].get("startup_pull", True)
            and (
                loaded is None
                or loaded[1].get("continuation_context_contract")
                != CONTINUATION_CONTEXT_CONTRACT
            )
            and _contract_recovery_due(
                self.data_dir,
                _session_key(device, session_id),
            )
        ):
            previous_loaded = loaded
            recovery_session_key = _session_key(device, session_id)
            try:
                recovery_input = dict(hook_input)
                recovery_input["hook_event_name"] = "SessionStart"
                recovery_input["source"] = "resume"
                recovery = self.session_start(recovery_input)
                specific = recovery.get("hookSpecificOutput")
                if isinstance(specific, Mapping):
                    recovered_context = specific.get("additionalContext")
                    if isinstance(recovered_context, str):
                        context = recovered_context
                recovered_warning = recovery.get("systemMessage")
                if isinstance(recovered_warning, str):
                    recovery_warning = recovered_warning
                refreshed = _load_session(self.data_dir, device, session_id)
                if (
                    refreshed is not None
                    and refreshed[1].get("continuation_context_contract")
                    == CONTINUATION_CONTEXT_CONTRACT
                ):
                    loaded = refreshed
                    _clear_contract_recovery_failure(
                        self.data_dir, recovery_session_key
                    )
                    if context is None:
                        saved_context = refreshed[1].get(
                            "continuation_context"
                        )
                        if isinstance(saved_context, str):
                            context = saved_context
                else:
                    loaded = previous_loaded
                    context = None
                    _record_contract_recovery_failure(
                        self.data_dir, recovery_session_key
                    )
                    if previous_loaded is not None and recovery_warning is None:
                        recovery_warning = (
                            "Private Memory Vault could not refresh this open "
                            "task's memory-use contract; the prior local session "
                            "was left unchanged."
                        )
            except VaultSyncError as exc:
                recovery_warning = (
                    "Private Memory Vault could not repair the missing or older "
                    f"startup state ({exc.code}); no task route was changed."
                )
                loaded = previous_loaded
                context = None
                _record_contract_recovery_failure(
                    self.data_dir, recovery_session_key
                )
        try:
            switch_routing_record = _load_routing_request_for_session(
                self.data_dir,
                device,
                session_id,
            )
        except IdentityError:
            stale_request_path = _routing_request_path(
                self.data_dir,
                _routing_request_id(device, session_id),
            )
            if stale_request_path.exists():
                return hook_json(
                    "UserPromptSubmit",
                    warning=(
                        "Private Memory Vault refused an invalid local task "
                        "routing record. No route or conversation memory was changed."
                    ),
                )
            switch_routing_record = None
        if (
            switch_routing_record is not None
            and switch_routing_record[1].get("state")
            == "awaiting_user_reply"
        ):
            try:
                switch_choice_record = _load_routing_choice(
                    self.data_dir,
                    str(switch_routing_record[1]["request_id"]),
                    required=False,
                )
            except VaultSyncError:
                return hook_json(
                    "UserPromptSubmit",
                    warning=(
                        "Private Memory Vault refused an invalid pending task "
                        "switch. No route or conversation memory was changed."
                    ),
                )
            if (
                switch_choice_record is not None
                and switch_choice_record[1].get("operation")
                == "route_switch"
                and switch_choice_record[1].get("state")
                == "awaiting_user_reply"
            ):
                switch_path, switch_request = switch_routing_record
                try:
                    _assert_routing_request_matches_workspace(
                        switch_request,
                        str(hook_input.get("cwd") or ""),
                        self.config["privacy"]["allowed_roots"],
                    )
                except VaultSyncError:
                    return hook_json(
                        "UserPromptSubmit",
                        warning=(
                            "Private Memory Vault refused a task-switch choice "
                            "after the workspace identity changed."
                        ),
                    )
                switch_request["pending_turn_id"] = turn_id
                switch_request["pending_prompt"] = prompt
                switch_request["updated_at"] = utc_now()
                atomic_write_json(switch_path, switch_request)
                return hook_json(
                    "UserPromptSubmit",
                    context=self._routing_context(
                        switch_request,
                        state="route_switch_user_confirmation",
                        issue_decision_token=True,
                    ),
                    warning=recovery_warning,
                )
        if loaded is None:
            routing_record = _load_routing_request_for_session(
                self.data_dir,
                device,
                session_id,
            )
            if routing_record is not None:
                routing_path, routing = routing_record
                if routing.get("state") in {
                    "pending",
                    "awaiting_user_reply",
                    "provisional",
                }:
                    try:
                        _assert_routing_request_matches_workspace(
                            routing,
                            str(hook_input.get("cwd") or ""),
                            self.config["privacy"]["allowed_roots"],
                        )
                    except VaultSyncError:
                        return hook_json(
                            "UserPromptSubmit",
                            warning=(
                                recovery_warning
                                or (
                                    "Private Memory Vault refused a stale task "
                                    "matching request after the workspace changed."
                                )
                            ),
                        )
                    if routing.get("state") == "pending":
                        routing["review_nonce"] = uuid.uuid4().hex
                        with contextlib.suppress(FileNotFoundError):
                            _local_routing_review_receipt_path(
                                self.data_dir,
                                str(routing["request_id"]),
                            ).unlink()
                    selection_hint: Mapping[str, Any] | None = None
                    if routing.get("state") == "pending":
                        normalized_selection = unicodedata.normalize(
                            "NFKC",
                            prompt,
                        ).strip()
                        if normalized_selection.isdigit():
                            choice_index = int(normalized_selection)
                            candidate_ids = routing.get(
                                "candidate_task_ids"
                            )
                            if (
                                isinstance(candidate_ids, list)
                                and 1 <= choice_index <= len(candidate_ids)
                            ):
                                selection_hint = {
                                    "choice_code": str(choice_index),
                                    "task_id": candidate_ids[
                                        choice_index - 1
                                    ],
                                }
                    routing["pending_turn_id"] = turn_id
                    routing["pending_prompt"] = prompt
                    routing["updated_at"] = utc_now()
                    atomic_write_json(routing_path, routing)
                    context = self._routing_context(
                        routing,
                        state=(
                            "provisional_consistency_check"
                            if routing.get("state") == "provisional"
                            else (
                                "routing_choice_requires_exact_code"
                                if routing.get("state")
                                == "awaiting_user_reply"
                                else "unbound_pending_model"
                            )
                        ),
                        issue_decision_token=(
                            routing.get("state")
                            == "awaiting_user_reply"
                        ),
                        selection_hint=selection_hint,
                    )
            return hook_json(
                "UserPromptSubmit",
                context=context,
                warning=recovery_warning,
            )
        session_key, session = loaded
        try:
            session, refresh_warning = self._refresh_open_session(
                hook_input,
                session_key,
                session,
            )
        except (IdentityError, PrivacyError, VerificationError):
            return hook_json(
                "UserPromptSubmit",
                warning=(
                    "Private Memory Vault refused to refresh an open task "
                    "whose local identity or baseline changed."
                ),
            )
        if recovery_warning is None:
            recovery_warning = refresh_warning
        try:
            with FileLock(self.lock_path):
                recovery = _recover_pending_reconciliations(
                    self,
                    session_key=session_key,
                    already_locked=True,
                )
            if recovery.get("terminal") is True:
                reloaded = _load_session(
                    self.data_dir,
                    device,
                    session_id,
                )
                if reloaded is not None:
                    session_key, session = reloaded
                    session, post_recovery_warning = (
                        self._refresh_open_session(
                            hook_input,
                            session_key,
                            session,
                        )
                    )
                    if recovery_warning is None:
                        recovery_warning = post_recovery_warning
        except VaultSyncError:
            # The signed pending record remains local.  This lifecycle turn
            # continues from the already verified session and never guesses a
            # new baseline.
            pass
        turn_key = _turn_key(device, session_id, turn_id)
        if not self.config["sync"].get("conversation_backup", True):
            if session.get("pending_context_injection") is True:
                saved_context = session.get("continuation_context")
                if isinstance(saved_context, str):
                    context = saved_context
                session["pending_context_injection"] = False
                _save_session(self.data_dir, session_key, session)
            return hook_json(
                "UserPromptSubmit",
                context=context,
                warning=recovery_warning,
            )
        try:
            identity = self._identity_from_session_input(hook_input, session)
            if (
                identity.task_id != session.get("task_id")
                or identity.binding_id != session.get("binding_id")
            ):
                raise IdentityError("hook workspace changed after SessionStart")
        except (PrivacyError, IdentityError) as exc:
            transaction = _transaction_id(device, session_id, turn_id)
            quarantine = {
                "schema_version": "memory-vault-sync-quarantine/v1",
                "transaction_id": transaction,
                "task_id": session.get("task_id"),
                "reason_code": exc.code,
                "created_at": utc_now(),
                "content_preserved": False,
            }
            atomic_write_json(
                _outbox_path(self.data_dir, "quarantine", transaction), quarantine
            )
            return hook_json(
                "UserPromptSubmit",
                warning="This turn contains private local data that was not queued for remote backup.",
            )
        staged = {
            "schema_version": "memory-vault-sync-prompt/v1",
            "turn_key": turn_key,
            "task_id": session["task_id"],
            "prompt": prompt,
            "created_at": utc_now(),
        }
        atomic_write_json(_prompt_path(self.data_dir, session_key, turn_key), staged)
        if session.get("identity_kind") != "provisional_source":
            injected_context, _issued_token = (
                self._issue_reconciliation_ticket(
                    session_key=session_key,
                    session=session,
                    turn_id=turn_id,
                    turn_key=turn_key,
                )
            )
            if injected_context is not None:
                context = injected_context
        if session.get("identity_kind") == "provisional_source":
            routing_record = _load_routing_request_for_session(
                self.data_dir,
                device,
                session_id,
            )
            if routing_record is not None:
                claim_id = session.get("claim_id")
                context = self._routing_context(
                    routing_record[1],
                    state="provisional_consistency_check",
                    claim_id=(
                        str(claim_id)
                        if isinstance(claim_id, str)
                        else None
                    ),
                    issue_decision_token=True,
                )
        return hook_json(
            "UserPromptSubmit",
            context=context,
            warning=recovery_warning,
        )

    def _spool_artifacts(
        self, artifacts: Sequence[Mapping[str, Any]]
    ) -> list[dict[str, Any]]:
        spooled: list[dict[str, Any]] = []
        allowed = [
            Path(root).resolve()
            for root in self.config["privacy"]["allowed_roots"]
            if isinstance(root, str) and os.path.isabs(root)
        ]
        for source_artifact in artifacts:
            artifact = dict(source_artifact)
            raw_path = artifact.pop("local_path", None)
            if not isinstance(raw_path, str) or not os.path.isabs(raw_path):
                raise PrivacyError("artifact has no absolute source path")
            source = Path(raw_path)
            resolved = source.resolve(strict=True)
            if not any(_path_is_within(resolved, root) for root in allowed):
                raise PrivacyError("artifact source is outside allowed roots")
            assert_plain_path(source, require_file=True)
            sha256 = validate_sha256(artifact.get("sha256"), "artifact.sha256")
            size = int(artifact.get("size"))
            relative = f"spool/sha256/{sha256[:2]}/{sha256}"
            validate_repo_path(relative, "spool path")
            destination = self.data_dir / PurePosixPath(relative)
            ensure_private_dir(destination.parent)
            with FileLock(self.data_dir / "locks" / f"spool-{sha256}.lock"):
                created = False
                if not destination.exists():
                    fd, temporary_name = tempfile.mkstemp(
                        prefix=f".{sha256}.",
                        suffix=".spool",
                        dir=str(destination.parent),
                    )
                    temporary = Path(temporary_name)
                    try:
                        digest = hashlib.sha256()
                        copied = 0
                        with source.open("rb", buffering=0) as input_stream, os.fdopen(
                            fd, "wb", buffering=0
                        ) as output_stream:
                            while True:
                                chunk = input_stream.read(1024 * 1024)
                                if not chunk:
                                    break
                                output_stream.write(chunk)
                                digest.update(chunk)
                                copied += len(chunk)
                            output_stream.flush()
                            os.fsync(output_stream.fileno())
                        if digest.hexdigest() != sha256 or copied != size:
                            raise VerificationError(
                                "artifact changed before its immutable spool copy completed"
                            )
                        _publish_temp_exclusive(
                            temporary, destination, sha256, size
                        )
                        created = True
                    finally:
                        with contextlib.suppress(FileNotFoundError):
                            temporary.unlink()
                if not created:
                    actual_sha, actual_size = stable_hash_file(destination)
                    if actual_sha != sha256 or actual_size != size:
                        raise VerificationError(
                            "immutable artifact spool verification failed"
                        )
            artifact["spool_path"] = relative
            spooled.append(artifact)
        return spooled

    def _artifact_publication_plan(
        self,
        identity: PortableIdentity,
        device: Mapping[str, Any],
    ) -> tuple[bool, list[str] | None]:
        local = _load_adoption_guard(
            self.data_dir,
            device,
            identity.workspace_root,
            identity.task_id,
        )
        portable = _portable_adoption_for(identity)
        if local is None and portable is None:
            return True, None
        if local is None or portable is None:
            return False, []
        local_path, local_guard = local
        records = [local_guard]
        if isinstance(portable, Mapping):
            records.append(portable)
        for record in records:
            if (
                record.get("binding_id") != identity.binding_id
                or record.get("workspace_lineage_id") != identity.lineage_id
            ):
                raise IdentityError(
                    "existing-task adoption conflicts with workspace identity"
                )
        if local_guard.get("artifact_publication_blocked") is not False:
            return False, []

        def revoke() -> None:
            local_guard["approved_publish_manifest_sha256"] = None
            local_guard["artifact_publication_blocked"] = True
            local_guard["state"] = "cloud_current_loaded"
            local_guard["updated_at"] = utc_now()
            atomic_write_json(local_path, local_guard)

        try:
            current, value = _publish_manifest_snapshot(identity, parse=True)
        except (PrivacyError, ConfigurationError, VerificationError):
            revoke()
            raise
        if current is None or value is None:
            revoke()
            return False, []
        if local_guard.get("approved_publish_manifest_sha256") != current:
            revoke()
            return False, []
        try:
            declarations = _artifact_declarations_from_value(identity, value)
        except (PrivacyError, ConfigurationError, VerificationError):
            revoke()
            raise
        return True, declarations

    def _queue_stop(
        self,
        hook_input: Mapping[str, Any],
    ) -> tuple[str, str]:
        session_id = hook_input.get("session_id")
        turn_id = hook_input.get("turn_id")
        if not isinstance(session_id, str) or not isinstance(turn_id, str):
            raise IdentityError("Stop hook is missing session or turn identity")
        device = _device_state(self.data_dir)
        loaded = _load_session(self.data_dir, device, session_id)
        if loaded is None:
            raise IdentityError("this session has no verified startup baseline")
        session_key, session = loaded
        transaction = _transaction_id(device, session_id, turn_id)
        existing = _find_outbox_state(self.data_dir, transaction)
        if existing is not None:
            return transaction, existing
        identity = self._identity_from_session_input(hook_input, session)
        if (
            identity.task_id != session.get("task_id")
            or identity.binding_id != session.get("binding_id")
        ):
            raise IdentityError("task identity changed after SessionStart")
        if isinstance(identity, PortableIdentity) and (
            str(identity.workspace_root.resolve()) != session.get("workspace_root")
        ):
            raise IdentityError("workspace identity changed after SessionStart")
        turn_key = _turn_key(device, session_id, turn_id)
        prompt_file = _prompt_path(self.data_dir, session_key, turn_key)
        prompt: str | None = None
        if prompt_file.exists():
            staged = load_json(prompt_file)
            if isinstance(staged, Mapping):
                prompt = scan_visible_text(staged.get("prompt"), "staged prompt")
        if (
            prompt is None
            and session.get("identity_kind") == "provisional_source"
        ):
            routing_record = _load_routing_request_for_session(
                self.data_dir,
                device,
                session_id,
            )
            if routing_record is not None:
                routing = routing_record[1]
                if routing.get("pending_turn_id") == turn_id:
                    pending_prompt = routing.get("pending_prompt")
                    if isinstance(pending_prompt, str):
                        prompt = scan_visible_text(
                            pending_prompt,
                            "pending routing prompt",
                        )
        assistant_raw = hook_input.get("last_assistant_message")
        assistant = (
            scan_visible_text(assistant_raw, "assistant message")
            if isinstance(assistant_raw, str) and assistant_raw
            else None
        )
        if prompt is None and assistant is None:
            raise PrivacyError("Stop hook has no visible content to back up")
        previous_snapshot = session.get("artifact_snapshot")
        if not isinstance(previous_snapshot, Mapping):
            previous_snapshot = {}
        try:
            artifact_publication_allowed, declarations_override = (
                self._artifact_publication_plan(identity, device)
                if isinstance(identity, PortableIdentity)
                else (False, [])
            )
            if session.get(
                "artifact_publication_blocked_due_remote_advance"
            ) is True:
                artifact_publication_allowed = False
                declarations_override = []
        except (PrivacyError, ConfigurationError, VerificationError):
            adoption = session.get("adoption")
            if isinstance(adoption, dict):
                adoption["artifact_publication_blocked"] = True
                adoption["state"] = "cloud_current_loaded"
                context = session.get("continuation_context")
                if isinstance(context, str):
                    session["continuation_context"] = _with_adoption_context(
                        context,
                        blocked=True,
                    )
                _save_session(self.data_dir, session_key, session)
            raise
        adoption = session.get("adoption")
        if isinstance(adoption, dict):
            adoption["artifact_publication_blocked"] = (
                not artifact_publication_allowed
            )
            adoption["state"] = (
                "artifacts_reconciled"
                if artifact_publication_allowed
                else "cloud_current_loaded"
            )
            context = session.get("continuation_context")
            if isinstance(context, str):
                session["continuation_context"] = _with_adoption_context(
                    context,
                    blocked=not artifact_publication_allowed,
                )
        artifacts = (
            self._spool_artifacts(
                changed_artifacts(
                    identity,
                    previous_snapshot,
                    self.config,
                    declarations_override=declarations_override,
                )
            )
            if isinstance(identity, PortableIdentity)
            and artifact_publication_allowed
            else []
        )
        base = session.get("base")
        if not isinstance(base, Mapping):
            raise VerificationError("startup baseline is missing")
        snapshot_id = validate_identifier(
            "snap-"
            + _opaque_key(
                str(device["device_secret"]),
                identity.task_id,
                transaction,
                length=40,
            ),
            "snapshot_id",
        )
        revision_id = validate_identifier(
            "rev-" + sha256_bytes(transaction.encode("ascii"))[:40],
            "revision_id",
        )
        intent = {
            "schema_version": OUTBOX_SCHEMA,
            "provider_pins": _json_clone(self.provider_pins),
            "transaction_id": transaction,
            "snapshot_id": snapshot_id,
            "state": "queued",
            "created_at": utc_now(),
            "identity_kind": (
                "workspace"
                if isinstance(identity, PortableIdentity)
                else (
                    "provisional_source"
                    if session.get("identity_kind") == "provisional_source"
                    else "source"
                )
            ),
            "task_id": identity.task_id,
            "binding_id": identity.binding_id,
            "session_key": session_key,
            "base": dict(base),
            "base_manifest": dict(session.get("base_manifest", {})),
            "conversation_delta": {
                "source_id": session["source_id"],
                "external_source_key_sha256": session[
                    "source_external_key_sha256"
                ],
                "revision_id": revision_id,
                "prompt": prompt,
                "last_assistant": assistant,
            },
            "artifacts": artifacts,
            "attempts": {
                "count": 0,
                "last_error_code": None,
                "last_attempt_at": None,
            },
            "recovery": _outbox_recovery_default(),
        }
        if isinstance(identity, PortableIdentity):
            intent.update(
                {
                    "workspace_lineage_id": identity.lineage_id,
                    "workspace_instance_id": session["workspace_instance_id"],
                    "workspace_root": session["workspace_root"],
                }
            )
        else:
            intent["bound_source_id"] = identity.source_id
            if session.get("identity_kind") == "provisional_source":
                claim_id = validate_identifier(
                    session.get("claim_id"),
                    "provisional claim_id",
                )
                claim_record = _load_provisional_claim(
                    self.data_dir,
                    session_key,
                )
                if (
                    claim_record is None
                    or claim_record[1].get("claim_id") != claim_id
                ):
                    raise IdentityError("provisional task claim is missing")
                claim = claim_record[1]
                intent.update(
                    {
                        "claim_id": claim_id,
                        "proposal_binding_path": claim[
                            "proposal_binding_path"
                        ],
                        "proposal_binding_blob_sha": claim[
                            "proposal_binding_blob_sha"
                        ],
                        "force_candidate": True,
                    }
                )
        pending = _outbox_path(self.data_dir, "pending", transaction)
        queue_lock = self.data_dir / "locks" / f"queue-{transaction}.lock"
        with FileLock(queue_lock):
            if _find_outbox_state(self.data_dir, transaction) is None:
                atomic_write_json(pending, intent)
        if isinstance(identity, PortableIdentity):
            declarations = (
                list(declarations_override)
                if declarations_override is not None
                else _artifact_declarations(identity)
                if artifact_publication_allowed
                else []
            )
            captured_snapshot = {
                relative: previous_snapshot.get(
                    relative, [-1, -1, -1, -1, None]
                )
                for relative in declarations
            }
            for artifact in artifacts:
                relative = artifact.get("relative_path")
                observed = artifact.get("stat")
                if (
                    isinstance(relative, str)
                    and relative in captured_snapshot
                    and isinstance(observed, list)
                    and len(observed) == 5
                ):
                    captured_snapshot[relative] = list(observed)
            session["artifact_snapshot"] = captured_snapshot
        _save_session(self.data_dir, session_key, session)
        with contextlib.suppress(OSError):
            prompt_file.unlink()
        return transaction, "pending"

    def _pending_unverified_artifact_bytes(self, transaction_id: str) -> int:
        """Return the bytes that would require a remote upload now.

        This is intentionally metadata-only. The immutable spool has already
        been captured by ``_queue_stop``; the Stop hook can therefore decide
        whether to open a network window without rereading artifact content.
        """

        pending = _outbox_path(self.data_dir, "pending", transaction_id)
        if not pending.exists():
            return 0
        value = load_json(pending)
        if not isinstance(value, Mapping):
            raise VerificationError("queued outbox intent is invalid")
        artifacts = value.get("artifacts")
        if not isinstance(artifacts, list):
            raise VerificationError("queued outbox artifacts are invalid")
        total = 0
        for artifact in artifacts:
            if not isinstance(artifact, Mapping):
                raise VerificationError("queued outbox artifact is invalid")
            if _local_artifact_storage(artifact) is not None:
                continue
            size = artifact.get("size")
            if not isinstance(size, int) or isinstance(size, bool) or size < 1:
                raise VerificationError("queued outbox artifact size is invalid")
            total += size
        return total

    def stop(self, hook_input: Mapping[str, Any]) -> dict[str, Any]:
        if hook_input.get("hook_event_name") != "Stop":
            raise PrivacyError("wrong hook event for stop")
        if self._memory_network_enabled():
            return self.memory_network_stop(hook_input)
        if not self.config["sync"].get("legacy_task_handoff_enabled", False):
            return hook_json("Stop")
        if not self.config.get("enabled") or not self.config["sync"].get(
            "stop_publish", True
        ):
            return hook_json("Stop")
        try:
            transaction, state = self._queue_stop(hook_input)
        except IdentityError:
            return hook_json("Stop")
        except (PrivacyError, VerificationError) as exc:
            session_id = hook_input.get("session_id")
            turn_id = hook_input.get("turn_id")
            if isinstance(session_id, str) and isinstance(turn_id, str):
                device = _device_state(self.data_dir)
                transaction = _transaction_id(device, session_id, turn_id)
                quarantine = {
                    "schema_version": "memory-vault-sync-quarantine/v1",
                    "transaction_id": transaction,
                    "reason_code": exc.code,
                    "created_at": utc_now(),
                    "content_preserved": False,
                }
                atomic_write_json(
                    _outbox_path(self.data_dir, "quarantine", transaction),
                    quarantine,
                )
            return hook_json(
                "Stop",
                warning="The private checkpoint was quarantined locally and did not move the remote pointer.",
            )
        if state in {"done", "candidate", "quarantine"}:
            return hook_json("Stop")
        if state == "pending":
            pending_path = _outbox_path(
                self.data_dir,
                "pending",
                transaction,
            )
            with contextlib.suppress(OSError, ValueError, VaultSyncError):
                pending_value = load_json(pending_path)
                if isinstance(pending_value, Mapping):
                    recovery = _outbox_recovery_value(pending_value)
                    if recovery["status"] == "blocked":
                        return hook_json(
                            "Stop",
                            warning=(
                                "The previous private checkpoint is blocked "
                                "locally; remediate the reported issue and "
                                "run `flush --retry-blocked`."
                            ),
                        )
        if state == "blocked":
            return hook_json(
                "Stop",
                warning=(
                    "The previous private checkpoint is blocked locally; "
                    "remediate the reported issue and run `flush --retry-blocked`."
                ),
            )
        max_stop_upload = int(
            self.config["sync"].get(
                "max_stop_upload_bytes",
                DEFAULT_MAX_STOP_UPLOAD_BYTES,
            )
        )
        pending_artifact_bytes = self._pending_unverified_artifact_bytes(
            transaction
        )
        if pending_artifact_bytes > max_stop_upload:
            return hook_json(
                "Stop",
                warning=(
                    "Private Memory Vault queued this checkpoint locally; "
                    f"{pending_artifact_bytes} bytes of artifacts will be "
                    "uploaded during an explicit `flush` window so the "
                    "conversation does not wait for object-store validation."
                ),
            )
        try:
            with FileLock(self.lock_path):
                result = self.flush_once(
                    transaction_id=transaction,
                    already_locked=True,
                )
        except BusyError:
            return hook_json(
                "Stop",
                warning="The private checkpoint is safely queued and will retry at the next lifecycle event.",
            )
        if result in {"done", "published_then_advanced"}:
            return hook_json("Stop")
        if result == "candidate":
            return hook_json(
                "Stop",
                warning="Another device advanced this task; this work was preserved as a conflict candidate.",
            )
        if result == "provisional_candidate":
            return hook_json(
                "Stop",
                warning=(
                    "Private Memory Vault kept this provisional continuation as "
                    "a recoverable candidate; the cloud CURRENT was not changed."
                ),
            )
        if result == "quarantined":
            return hook_json(
                "Stop",
                warning=(
                    "Private Memory Vault kept this checkpoint in local "
                    "quarantine because its provider identity could not be "
                    "verified. No remote provider was changed."
                ),
            )
        if result == "blocked":
            return hook_json(
                "Stop",
                warning=(
                    "Private Memory Vault blocked this checkpoint locally; "
                    "no remote provider was changed. Remediate the issue and "
                    "run `flush --retry-blocked`."
                ),
            )
        return hook_json(
            "Stop",
            warning="The private checkpoint is safely queued for an offline retry.",
        )

    def _verify_local_artifact(self, artifact: Mapping[str, Any]) -> Path:
        relative = validate_repo_path(artifact.get("spool_path"), "spool path")
        sha256 = validate_sha256(artifact.get("sha256"), "artifact.sha256")
        expected = f"spool/sha256/{sha256[:2]}/{sha256}"
        if relative != expected:
            raise PrivacyError("queued artifact spool path is not content-addressed")
        path = self.data_dir / PurePosixPath(relative)
        resolved = path.resolve(strict=True)
        if not _path_is_within(resolved, self.data_dir):
            raise PrivacyError("queued artifact spool escapes plugin data")
        assert_plain_path(path, require_file=True)
        sha, size = stable_hash_file(path)
        if sha != sha256 or size != artifact.get("size"):
            raise VerificationError("queued immutable artifact failed verification")
        return path

    def _upload_artifacts(self, intent: dict[str, Any], pending: Path) -> None:
        artifacts = intent.get("artifacts")
        if not isinstance(artifacts, list):
            raise VerificationError("outbox artifacts are invalid")
        if not artifacts:
            return

        # Verify every immutable local input before starting any network write,
        # then group identical content addresses so concurrent declarations do
        # not cause duplicate uploads.
        groups: dict[
            tuple[str, int, str],
            dict[str, Any],
        ] = {}
        verified_spools: dict[tuple[str, int], Path] = {}
        for artifact_index, artifact in enumerate(artifacts):
            if not isinstance(artifact, dict):
                raise VerificationError("outbox artifact is invalid")
            sha256 = validate_sha256(artifact.get("sha256"), "artifact.sha256")
            raw_size = artifact.get("size")
            if (
                not isinstance(raw_size, int)
                or isinstance(raw_size, bool)
                or raw_size < 1
            ):
                raise VerificationError("outbox artifact size is invalid")
            size = raw_size
            mime_type = artifact.get("mime_type")
            if not isinstance(mime_type, str) or not re.fullmatch(
                r"[a-z0-9.+-]+/[a-z0-9.+-]+", mime_type
            ):
                raise VerificationError("outbox artifact MIME type is invalid")
            validate_repo_path(
                artifact.get("logical_path"),
                "artifact logical_path",
            )
            # Every declaration still proves its content-addressed path, but
            # duplicate declarations of the same immutable bytes share the
            # expensive local SHA-256 pass before any network write.
            relative = validate_repo_path(
                artifact.get("spool_path"),
                "spool path",
            )
            if relative != f"spool/sha256/{sha256[:2]}/{sha256}":
                raise PrivacyError(
                    "queued artifact spool path is not content-addressed"
                )
            spool_identity = (sha256, size)
            path = verified_spools.get(spool_identity)
            if path is None:
                path = self._verify_local_artifact(artifact)
                verified_spools[spool_identity] = path
            key = (sha256, size, mime_type)
            group = groups.setdefault(
                key,
                {
                    "path": path,
                    "artifact_indexes": [],
                    "existing_ids": set(),
                },
            )
            group["artifact_indexes"].append(artifact_index)
            existing = _local_artifact_storage(artifact)
            if isinstance(existing, Mapping):
                file_id = existing.get("file_id")
                if isinstance(file_id, str):
                    group["existing_ids"].add(file_id)

        ordered_groups = list(groups.items())
        drive = self._drive()
        drive.assert_private()

        def transfer(
            item: tuple[
                tuple[str, int, str],
                dict[str, Any],
            ],
        ) -> VerifiedDriveObject:
            (sha256, size, mime_type), group = item
            verified: VerifiedDriveObject | None = None
            chunked = drive.should_chunk(size)
            if not chunked:
                found = drive.find_verified(sha256, size, mime_type)
                if found is not None:
                    existing_ids = group["existing_ids"]
                    if not existing_ids or found.file_id in existing_ids:
                        verified = found
                    else:
                        # A provider may legitimately return another immutable
                        # object with the same verified content address. Reusing
                        # it is safe and avoids a redundant upload.
                        verified = found
            if verified is None:
                verified = drive.upload_and_verify(
                    group["path"],
                    sha256,
                    size,
                    mime_type,
                )
            # Adapters are explicit, reviewed code, but the engine still
            # verifies their returned identity before persisting or publishing
            # it. This keeps a future adapter bug inside the local outbox.
            _storage_ref_from_verified(verified)
            if (
                verified.store_id != drive.store_id
                or verified.driver != drive.driver
                or verified.sha256 != sha256
                or verified.size != size
                or verified.mime_type != mime_type
                or verified.storage_mode not in {"full", "chunked-v1"}
                or (
                    verified.storage_mode
                    != ("chunked-v1" if chunked else "full")
                )
            ):
                raise VerificationError(
                    "object-store adapter returned a mismatched verified object"
                )
            return verified

        max_workers = min(
            int(
                self.config["sync"].get(
                    "max_parallel_artifact_uploads",
                    DEFAULT_MAX_PARALLEL_ARTIFACT_UPLOADS,
                )
            ),
            len(ordered_groups),
        )
        results: dict[int, VerifiedDriveObject] = {}
        failures: dict[int, VaultSyncError] = {}
        if max_workers <= 1:
            for index, group in enumerate(ordered_groups):
                try:
                    results[index] = transfer(group)
                except VaultSyncError as exc:
                    failures[index] = exc
                    break
        else:
            with concurrent.futures.ThreadPoolExecutor(
                max_workers=max_workers,
                thread_name_prefix="memory-vault-upload",
            ) as executor:
                future_indexes = {
                    executor.submit(transfer, group): index
                    for index, group in enumerate(ordered_groups)
                }
                for future in concurrent.futures.as_completed(future_indexes):
                    index = future_indexes[future]
                    try:
                        results[index] = future.result()
                    except VaultSyncError as exc:
                        failures[index] = exc
                    except Exception:
                        failures[index] = VerificationError(
                            "object-store transfer failed unexpectedly"
                        )

        # Persist every successful immutable upload even when a peer transfer
        # failed. A later bounded retry can reuse those exact verified objects.
        for index in sorted(results):
            verified = results[index]
            _key, group = ordered_groups[index]
            serialized = dataclasses.asdict(verified)
            for artifact_index in group["artifact_indexes"]:
                artifact = artifacts[artifact_index]
                artifact["storage"] = serialized
                artifact.pop("drive", None)
        if not failures:
            intent["state"] = "drive_verified"
        if results:
            # One durable write records the complete successful subset. On a
            # partial failure the state remains queued, but later retries can
            # safely reuse every verified object recorded here.
            atomic_write_json(pending, intent)
        if failures:
            raise failures[min(failures)]

    def _remote_has_transaction(
        self, intent: Mapping[str, Any], remote: RemoteTaskState
    ) -> str | None:
        transaction = intent["transaction_id"]
        if remote.current.get("published_transaction_id") == transaction:
            return "done"
        version_path = (
            f"tasks/{intent['task_id']}/versions/{intent['snapshot_id']}.json"
        )
        if self.git.file_exists(version_path):
            version = self.git.show_json(version_path)
            if version.get("transaction_id") != transaction:
                raise VerificationError("snapshot path is occupied by another transaction")
            if version.get("state") == "candidate":
                return "candidate"
            if version.get("state") == "published":
                return "published_then_advanced"
        return None

    def _build_remote_files(
        self,
        intent: Mapping[str, Any],
        remote: RemoteTaskState,
        *,
        candidate: bool,
    ) -> dict[str, bytes]:
        (
            conversation_path,
            conversation_bytes,
            conversation_document,
        ) = _conversation_document(intent)
        source_path, source_bytes = _source_document(
            self.git,
            intent,
            conversation_path,
            conversation_bytes,
        )
        enriched_intent = dict(intent)
        try:
            source_document = strict_json_loads(source_bytes.decode("utf-8"))
        except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
            raise VerificationError("generated source document is invalid") from exc
        if not isinstance(source_document, Mapping):
            raise VerificationError("generated source document is not an object")
        revision_id = str(intent["conversation_delta"]["revision_id"])
        revisions = source_document.get("revisions")
        revision = next(
            (
                item
                for item in revisions or []
                if isinstance(item, Mapping)
                and item.get("revision_id") == revision_id
            ),
            None,
        ) if isinstance(revisions, list) else None
        if not isinstance(revision, Mapping):
            raise VerificationError("generated source revision is missing")
        evidence_binding_path: str | None = None
        evidence_binding_bytes: bytes | None = None
        if intent.get("identity_kind") != "provisional_source":
            (
                evidence_binding_id,
                evidence_binding_path,
                proposed_binding_bytes,
            ) = _workspace_source_binding_document(
                intent,
                source_id=str(intent["conversation_delta"]["source_id"]),
            )
            if self.git.file_exists(evidence_binding_path):
                _confirmed_source_binding(
                    self.git,
                    task_id=str(intent["task_id"]),
                    source_id=str(intent["conversation_delta"]["source_id"]),
                    source_sequence=int(revision["source_sequence"]),
                    expected_binding_id=evidence_binding_id,
                )
            else:
                if proposed_binding_bytes is None:
                    raise VerificationError(
                        "successor source binding is missing"
                    )
                evidence_binding_bytes = proposed_binding_bytes
            # Pin every confirmed visible Stop revision as durable task-bound
            # evidence, even for a legacy task without its first projection.
            enriched_intent["_projection_new_evidence_source"] = {
                "source_id": intent["conversation_delta"]["source_id"],
                "revision_id": revision_id,
                "source_sequence": revision["source_sequence"],
                "binding_id": evidence_binding_id,
                "content_path": conversation_path,
                "content_sha256": sha256_bytes(conversation_bytes),
            }
            if remote.memory_projection is not None:
                enriched_intent["_projection_new_messages"] = list(
                    conversation_document["messages"]
                )
        inherited = intent.get("base_manifest", {}).get("conversation_sources", [])
        references: list[Mapping[str, Any]] = []
        if isinstance(inherited, list):
            references.extend(item for item in inherited if isinstance(item, Mapping))
        references.append(
            {
                "source_id": intent["conversation_delta"]["source_id"],
                "revision_id": intent["conversation_delta"]["revision_id"],
                "content_path": conversation_path,
                "content_sha256": sha256_bytes(conversation_bytes),
            }
        )
        by_path = {
            str(item.get("content_path")): dict(item)
            for item in references
            if isinstance(item.get("content_path"), str)
        }
        enriched_intent["conversation_sources"] = list(by_path.values())[-8:]
        version_state = (
            dataclasses.replace(
                remote,
                memory_projection_path=None,
                memory_projection=None,
            )
            if intent.get("identity_kind") == "provisional_source"
            else remote
        )
        (
            version_path,
            version_bytes,
            current_path,
            current_bytes,
            projection_path,
            projection_bytes,
        ) = _version_documents(
            version_state,
            enriched_intent,
            candidate=candidate,
        )
        files = {
            conversation_path: conversation_bytes,
            source_path: source_bytes,
            version_path: version_bytes,
        }
        if current_path is not None and current_bytes is not None:
            files[current_path] = current_bytes
        if projection_path is not None and projection_bytes is not None:
            files[projection_path] = projection_bytes
        if (
            evidence_binding_path is not None
            and evidence_binding_bytes is not None
        ):
            files[evidence_binding_path] = evidence_binding_bytes
        for repo_path, raw in files.items():
            validate_repo_path(repo_path)
            parsed = strict_json_loads(raw.decode("utf-8"))
            assert_remote_safe(parsed)
        return files

    def _validate_worktree(
        self,
        worktree: Path,
        generated_files: Mapping[str, bytes],
        *,
        verified_episodes: Mapping[str, Mapping[str, Any]] | None = None,
    ) -> None:
        root = worktree.resolve()
        documents: dict[str, Mapping[str, Any]] = {}
        for repo_path, expected in generated_files.items():
            safe_path = validate_repo_path(repo_path)
            destination = worktree / PurePosixPath(safe_path)
            resolved = destination.resolve(strict=True)
            if not _path_is_within(resolved, root):
                raise PrivacyError("generated file escaped the isolated worktree")
            assert_plain_path(destination, require_file=True)
            actual = destination.read_bytes()
            if actual != expected:
                raise PrivacyError("generated file changed before Git staging")
            try:
                document = strict_json_loads(actual.decode("utf-8"))
            except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
                raise VerificationError("generated remote JSON is invalid") from exc
            if not isinstance(document, Mapping):
                raise VerificationError("generated remote JSON is not an object")
            assert_remote_safe(document)
            _validate_generated_document(safe_path, document)
            documents[safe_path] = document
        for path, event in documents.items():
            if not path.startswith("memory/events/"):
                continue
            source = event.get("source")
            payload = event.get("payload")
            if not isinstance(source, Mapping) or not isinstance(payload, Mapping):
                raise VerificationError("generated memory event source is invalid")
            is_v2 = (
                event.get("schema_version")
                == memory_network.MEMORY_EVENT_SCHEMA
            )
            if (
                not is_v2
                and payload.get("profile")
                != memory_network.EPISODE_EVENT_PROFILE
            ):
                # Rich semantic events may reference legacy source revisions;
                # their own strict validator remains authoritative.
                continue
            revision_id = validate_identifier(
                source.get("revision_id"), "memory event revision_id"
            )
            if not revision_id.startswith("ep-"):
                raise VerificationError("episode event has no episode revision")
            episode_path = (
                f"memory/episodes/{revision_id[3:5]}/{revision_id}.json"
            )
            episode = documents.get(episode_path)
            if episode is None and verified_episodes is not None:
                episode = verified_episodes.get(revision_id)
            if episode is None and self.git.file_exists(episode_path):
                episode = self.git.show_json(episode_path)
                _validate_memory_episode(episode)
            if not isinstance(episode, Mapping):
                raise VerificationError(
                    "episode event does not share durable evidence"
                )
            if is_v2:
                _validate_v2_event_episode(event, episode)
                continue
            if (
                episode.get("source_id") != source.get("source_id")
                or episode.get("episode_id") != revision_id
                or episode.get("source_sequence")
                != source.get("source_sequence")
                or episode.get("episode_sha256")
                != source.get("evidence_anchor_sha256")
            ):
                raise VerificationError(
                    "episode event and immutable evidence are inconsistent"
                )
        for path, current in documents.items():
            if not path.endswith("/CURRENT.json"):
                continue
            manifest_path = str(current["manifest_path"])
            manifest = documents.get(manifest_path)
            if not isinstance(manifest, Mapping):
                raise VerificationError(
                    "generated CURRENT does not share a commit with its manifest"
                )
            if (
                manifest.get("task_id") != current.get("task_id")
                or manifest.get("snapshot_id") != current.get("snapshot_id")
                or manifest.get("generation") != current.get("generation")
                or manifest.get("transaction_id")
                != current.get("published_transaction_id")
                or manifest.get("state") != "published"
            ):
                raise VerificationError(
                    "generated CURRENT and task version are inconsistent"
                )
        for path, version in documents.items():
            if "/versions/" not in path:
                continue
            projection_reference = version.get("memory_projection")
            if projection_reference is not None:
                if not isinstance(projection_reference, Mapping):
                    raise VerificationError(
                        "generated task projection reference is invalid"
                    )
                projection_path = str(projection_reference["path"])
                projection = documents.get(projection_path)
                if not isinstance(projection, Mapping):
                    raise VerificationError(
                        "generated task version does not share a commit "
                        "with its memory projection"
                    )
                if (
                    sha256_bytes(generated_files[projection_path])
                    != projection_reference.get("content_sha256")
                    or projection.get("projection_id")
                    != projection_reference.get("projection_id")
                ):
                    raise VerificationError(
                        "generated task projection hash or identity is inconsistent"
                    )
                basis = projection.get("basis")
                expected_basis = {
                    "task_id": version.get("task_id"),
                    "snapshot_id": version.get("snapshot_id"),
                    "generation": version.get("generation"),
                    "transaction_id": version.get("transaction_id"),
                    "manifest_path": path,
                }
                if not isinstance(basis, Mapping) or any(
                    basis.get(key) != expected
                    for key, expected in expected_basis.items()
                ):
                    raise VerificationError(
                        "generated task projection basis is inconsistent"
                    )
            for reference in version.get("conversation_sources", []):
                content_path = str(reference["content_path"])
                if content_path not in generated_files:
                    continue
                if sha256_bytes(generated_files[content_path]) != reference.get(
                    "content_sha256"
                ):
                    raise VerificationError(
                        "generated conversation reference hash is inconsistent"
                    )
            for reference in version.get("evidence_sources", []):
                content_path = str(reference["content_path"])
                if content_path in generated_files and sha256_bytes(
                    generated_files[content_path]
                ) != reference.get("content_sha256"):
                    raise VerificationError(
                        "generated durable evidence source hash is inconsistent"
                    )
                binding_path = (
                    f"bindings/confirmed/{reference['binding_id']}.json"
                )
                binding = documents.get(binding_path)
                if isinstance(binding, Mapping):
                    subject = binding.get("subject")
                    targets = binding.get("targets")
                    effective = binding.get("effective_range")
                    if (
                        subject
                        != {
                            "kind": "source",
                            "id": reference.get("source_id"),
                        }
                        or not isinstance(targets, list)
                        or not any(
                            isinstance(target, Mapping)
                            and target.get("semantic_task_id")
                            == version.get("task_id")
                            and target.get("relation") == "source_for"
                            for target in targets
                        )
                        or not isinstance(effective, Mapping)
                        or int(effective.get("source_sequence_from", -1))
                        > int(reference["source_sequence"])
                        or (
                            effective.get("source_sequence_to") is not None
                            and int(effective["source_sequence_to"])
                            < int(reference["source_sequence"])
                        )
                    ):
                        raise VerificationError(
                            "generated durable evidence binding is inconsistent"
                        )

    def _publish_git(
        self, intent: Mapping[str, Any], *, candidate: bool
    ) -> tuple[str, str, str, RemoteTaskState]:
        self.git.fetch()
        identity_kind = intent.get("identity_kind", "workspace")
        provisional = False
        if identity_kind == "source":
            artifacts = intent.get("artifacts")
            if artifacts != []:
                raise PrivacyError(
                    "conversation-only identity cannot publish artifacts"
                )
            source_id = validate_identifier(
                intent.get("bound_source_id"), "bound_source_id"
            )
            delta = intent.get("conversation_delta")
            if (
                not isinstance(delta, Mapping)
                or delta.get("source_id") != source_id
            ):
                raise IdentityError(
                    "conversation-only source changed before publication"
                )
            identity: TaskIdentity = SourceIdentity(
                binding_id=validate_identifier(
                    intent.get("binding_id"), "binding_id"
                ),
                task_id=validate_identifier(intent.get("task_id"), "task_id"),
                source_id=source_id,
                external_source_key_sha256=validate_sha256(
                    delta.get("external_source_key_sha256"),
                    "external_source_key_sha256",
                ),
            )
        elif identity_kind == "provisional_source":
            provisional = True
            if intent.get("artifacts") != [] or intent.get(
                "force_candidate"
            ) is not True:
                raise PrivacyError(
                    "provisional task claim may only publish a candidate conversation"
                )
            session_key = intent.get("session_key")
            claim_record = (
                _load_provisional_claim(self.data_dir, str(session_key))
                if isinstance(session_key, str)
                else None
            )
            if claim_record is None:
                raise IdentityError("provisional task claim is missing")
            claim = claim_record[1]
            if (
                claim.get("claim_id") != intent.get("claim_id")
                or claim.get("proposal_binding_path")
                != intent.get("proposal_binding_path")
                or claim.get("proposal_binding_blob_sha")
                != intent.get("proposal_binding_blob_sha")
                or claim.get("task_id") != intent.get("task_id")
                or claim.get("source_id") != intent.get("bound_source_id")
            ):
                raise IdentityError("queued provisional task claim changed")
            delta = intent.get("conversation_delta")
            if (
                not isinstance(delta, Mapping)
                or delta.get("source_id") != claim.get("source_id")
                or delta.get("external_source_key_sha256")
                != claim.get("expected_source_key_sha256")
            ):
                raise IdentityError(
                    "provisional conversation source changed before publication"
                )
            remote = self._verify_provisional_claim(
                claim,
                require_original_current=False,
            )
            identity = SourceIdentity(
                binding_id=validate_identifier(
                    claim.get("proposal_binding_id"),
                    "proposal_binding_id",
                ),
                task_id=validate_identifier(
                    claim.get("task_id"),
                    "task_id",
                ),
                source_id=validate_identifier(
                    claim.get("source_id"),
                    "source_id",
                ),
                external_source_key_sha256=validate_sha256(
                    claim.get("expected_source_key_sha256"),
                    "external_source_key_sha256",
                ),
            )
        elif identity_kind == "workspace":
            identity = PortableIdentity(
                path=Path(str(intent["workspace_root"]))
                / ".vault_identity.yaml",
                workspace_root=Path(str(intent["workspace_root"])),
                binding_id=validate_identifier(
                    intent["binding_id"], "binding_id"
                ),
                task_id=validate_identifier(intent["task_id"], "task_id"),
                lineage_id=validate_identifier(
                    intent["workspace_lineage_id"], "workspace_lineage_id"
                ),
                base={},
            )
        else:
            raise IdentityError("queued task identity kind is invalid")
        if not provisional:
            remote = load_remote_task(self.git, identity)
        already = self._remote_has_transaction(intent, remote)
        if already is not None:
            return already, remote.commit_sha, remote.current_blob_sha, remote
        expected = validate_git_sha(
            intent["base"]["task_current_blob_sha"], "expected CURRENT blob"
        )
        observed = remote.current_blob_sha
        should_candidate = provisional or candidate or observed != expected
        if remote.task.get("status") in {"archived", "split", "candidate"}:
            should_candidate = True
        build_state = (
            _recorded_base_state(self.git, remote, intent)
            if observed != expected
            else remote
        )
        files = self._build_remote_files(
            intent,
            build_state,
            candidate=should_candidate,
        )
        with self.git.create_worktree() as worktree:
            self.git.write_generated_files(worktree, files)
            self._validate_worktree(worktree, files)
            commit = self.git.commit_and_push(
                worktree,
                files,
                str(intent["task_id"]),
                str(intent["transaction_id"]),
            )
        self.git.fetch()
        verify_remote = (
            load_remote_task_by_id(
                self.git,
                validate_identifier(intent.get("task_id"), "task_id"),
            )
            if provisional
            else load_remote_task(self.git, identity)
        )
        if should_candidate:
            version_path = (
                f"tasks/{intent['task_id']}/versions/{intent['snapshot_id']}.json"
            )
            version = self.git.show_json(version_path)
            if (
                version.get("state") != "candidate"
                or version.get("transaction_id") != intent["transaction_id"]
                or verify_remote.current_blob_sha != observed
            ):
                raise VerificationError("remote candidate verification failed")
            return "candidate", commit, observed, verify_remote
        if (
            verify_remote.current.get("published_transaction_id")
            != intent["transaction_id"]
        ):
            raise VerificationError("remote CURRENT did not publish the transaction")
        return "done", commit, verify_remote.current_blob_sha, verify_remote

    def _refresh_session_after_publish(
        self,
        intent: Mapping[str, Any],
        remote: RemoteTaskState,
        *,
        pending_injection: bool = True,
        remote_advance: bool = False,
        invalidate_ticket: bool = True,
    ) -> None:
        session_key = intent.get("session_key")
        if not isinstance(session_key, str) or not re.fullmatch(
            r"[0-9a-f]{32}", session_key
        ):
            return
        path = _session_path(self.data_dir, session_key)
        if not path.exists():
            return
        value = load_json(path)
        if (
            not isinstance(value, dict)
            or value.get("schema_version") != SESSION_SCHEMA
            or value.get("task_id") != intent.get("task_id")
            or value.get("binding_id") != intent.get("binding_id")
        ):
            raise VerificationError("session changed before baseline refresh")
        if invalidate_ticket:
            _invalidate_session_reconciliation_ticket(self.data_dir, value)
        value["base"] = {
            "remote_commit_sha": remote.commit_sha,
            "task_current_path": remote.current_path,
            "task_current_blob_sha": remote.current_blob_sha,
            "task_generation": remote.current["generation"],
            "snapshot_id": remote.current["snapshot_id"],
            "manifest_path": remote.manifest_path,
            "published_transaction_id": remote.current[
                "published_transaction_id"
            ],
        }
        value["base_manifest"] = dict(remote.manifest)
        context = _continuation_context(remote, git=self.git)
        adoption = value.get("adoption")
        if isinstance(adoption, dict):
            workspace_root = value.get("workspace_root")
            lineage_id = value.get("workspace_lineage_id")
            if not isinstance(workspace_root, str) or not isinstance(
                lineage_id, str
            ):
                raise VerificationError(
                    "adopted session lost its workspace identity"
                )
            identity = PortableIdentity(
                path=Path(workspace_root) / ".vault_identities.json",
                workspace_root=Path(workspace_root),
                binding_id=validate_identifier(
                    value.get("binding_id"), "binding_id"
                ),
                task_id=validate_identifier(value.get("task_id"), "task_id"),
                lineage_id=validate_identifier(
                    lineage_id, "workspace_lineage_id"
                ),
                base={},
            )
            device = _device_state(self.data_dir)
            local = _load_adoption_guard(
                self.data_dir,
                device,
                identity.workspace_root,
                identity.task_id,
            )
            portable = _portable_adoption_for(identity)
            blocked = (
                local is None
                or portable is None
                or bool(local[1].get("artifact_publication_blocked"))
            )
            adoption.update(
                {
                    "state": (
                        "cloud_current_loaded"
                        if blocked
                        else "artifacts_reconciled"
                    ),
                    "cloud_snapshot_id": remote.current["snapshot_id"],
                    "cloud_current_blob_sha": remote.current_blob_sha,
                    "artifact_publication_blocked": blocked,
                }
            )
            context = _with_adoption_context(context, blocked=blocked)
        value["continuation_context"] = context
        value["continuation_context_contract"] = (
            CONTINUATION_CONTEXT_CONTRACT
        )
        value["reconciliation_required"] = bool(
            isinstance(remote.memory_projection, Mapping)
            and remote.memory_projection.get("unprojected_deltas")
        )
        value["pending_context_injection"] = bool(pending_injection)
        value["needs_remote_refresh"] = False
        if (
            remote_advance
            and value.get("identity_kind") == "workspace"
        ):
            # An already-open workspace may still contain artifacts from the
            # old cloud baseline.  Conversation work may continue, but those
            # local files cannot be promoted until a fresh materialization or
            # explicit artifact adoption check occurs.
            value["artifact_publication_blocked_due_remote_advance"] = True
        value["last_baseline_refresh_at"] = utc_now()
        _save_session(self.data_dir, session_key, value)

    def _release_spool(self, intent: Mapping[str, Any]) -> None:
        paths = {
            item.get("spool_path")
            for item in intent.get("artifacts", [])
            if isinstance(item, Mapping) and isinstance(item.get("spool_path"), str)
        }
        if not paths:
            return
        pending_root = self.data_dir / "outbox" / "pending"
        still_referenced: set[str] = set()
        if pending_root.exists():
            for candidate in pending_root.glob("*.json"):
                with contextlib.suppress(VaultSyncError, OSError, ValueError):
                    value = load_json(candidate)
                    if isinstance(value, Mapping):
                        for item in value.get("artifacts", []):
                            if isinstance(item, Mapping) and isinstance(
                                item.get("spool_path"), str
                            ):
                                still_referenced.add(str(item["spool_path"]))
        for relative in paths - still_referenced:
            safe = validate_repo_path(relative, "spool path")
            target = self.data_dir / PurePosixPath(safe)
            with contextlib.suppress(FileNotFoundError):
                target.unlink()

    def _finish_outbox(
        self,
        pending: Path,
        intent: Mapping[str, Any],
        state: str,
        commit: str,
        observed_blob: str,
        remote: RemoteTaskState,
    ) -> None:
        receipt = {
            "schema_version": "memory-vault-sync-receipt/v1",
            "transaction_id": intent["transaction_id"],
            "task_id": intent["task_id"],
            "snapshot_id": intent["snapshot_id"],
            "result": state,
            "remote_commit_sha": commit,
            "expected_current_blob_sha": intent["base"]["task_current_blob_sha"],
            "observed_current_blob_sha": observed_blob,
            "finished_at": utc_now(),
        }
        assert_remote_safe(receipt)
        destination = _outbox_path(
            self.data_dir,
            "candidate" if state == "candidate" else "done",
            str(intent["transaction_id"]),
        )
        atomic_write_json(destination, receipt)
        with contextlib.suppress(FileNotFoundError):
            pending.unlink()
        if state != "candidate":
            self._refresh_session_after_publish(intent, remote)
        else:
            session_key = intent.get("session_key")
            if isinstance(session_key, str) and re.fullmatch(
                r"[0-9a-f]{32}", session_key
            ):
                path = _session_path(self.data_dir, session_key)
                if path.exists():
                    session = load_json(path)
                    if (
                        isinstance(session, dict)
                        and session.get("schema_version") == SESSION_SCHEMA
                        and session.get("task_id") == intent.get("task_id")
                    ):
                        _invalidate_session_reconciliation_ticket(
                            self.data_dir,
                            session,
                        )
                        session["needs_remote_refresh"] = True
                        session["pending_context_injection"] = True
                        _save_session(self.data_dir, session_key, session)
        self._release_spool(intent)

    def _quarantine_pending_outbox(
        self,
        pending: Path,
        intent: Mapping[str, Any],
        *,
        reason_code: str,
    ) -> None:
        transaction_id = validate_identifier(
            intent.get("transaction_id"),
            "transaction_id",
        )
        quarantine = {
            "schema_version": "memory-vault-sync-quarantine/v1",
            "transaction_id": transaction_id,
            "task_id": intent.get("task_id"),
            "reason_code": reason_code,
            "created_at": utc_now(),
            "content_preserved": True,
            "pending_intent": _json_clone(intent),
        }
        atomic_write_json(
            _outbox_path(
                self.data_dir,
                "quarantine",
                transaction_id,
            ),
            quarantine,
        )
        with contextlib.suppress(FileNotFoundError):
            pending.unlink()

    def _block_pending_outbox(
        self,
        pending: Path,
        intent: Mapping[str, Any],
        *,
        reason_code: str,
    ) -> None:
        transaction_id = validate_identifier(
            intent.get("transaction_id"),
            "transaction_id",
        )
        blocked = {
            "schema_version": "memory-vault-sync-blocked/v1",
            "transaction_id": transaction_id,
            "task_id": intent.get("task_id"),
            "reason_code": reason_code,
            "created_at": utc_now(),
            "content_preserved": True,
            "pending_intent": _json_clone(intent),
        }
        destination = _outbox_path(
            self.data_dir,
            "blocked",
            transaction_id,
        )
        atomic_write_json(destination, blocked)
        with contextlib.suppress(FileNotFoundError):
            pending.unlink()

    def _legacy_outbox_provider_pins(self) -> dict[str, Any]:
        receipt_path = _config_v2_migration_receipt_path(self.data_dir)
        if not receipt_path.exists():
            raise VerificationError(
                "legacy outbox has no verified config migration receipt"
            )
        receipt = load_json(receipt_path)
        if (
            not isinstance(receipt, Mapping)
            or receipt.get("schema_version") != CONFIG_MIGRATION_SCHEMA
            or receipt.get("from_schema") != LEGACY_CONFIG_SCHEMA
            or receipt.get("to_schema") != CONFIG_SCHEMA
        ):
            raise VerificationError(
                "legacy outbox config migration receipt is invalid"
            )
        pins = _validate_provider_transaction_pins(
            receipt.get("provider_pins")
        )
        if receipt.get("provider_profile_id") != pins.get("profile_id"):
            raise VerificationError(
                "legacy outbox provider profile receipt is inconsistent"
            )
        return pins

    def _prepare_pending_outbox(
        self,
        pending: Path,
        intent: dict[str, Any],
    ) -> dict[str, Any] | None:
        schema = intent.get("schema_version")
        if schema == LEGACY_OUTBOX_SCHEMA:
            try:
                pins = self._legacy_outbox_provider_pins()
            except VaultSyncError:
                self._quarantine_pending_outbox(
                    pending,
                    intent,
                    reason_code="legacy_outbox_provider_unverified",
                )
                return None
            if pins != self.provider_pins:
                self._quarantine_pending_outbox(
                    pending,
                    intent,
                    reason_code="legacy_outbox_provider_changed",
                )
                return None
            migrated = _json_clone(intent)
            migrated["schema_version"] = OUTBOX_SCHEMA
            migrated["provider_pins"] = _json_clone(pins)
            migrated["migrated_from_schema"] = LEGACY_OUTBOX_SCHEMA
            migrated["migrated_at"] = utc_now()
            atomic_write_json(pending, migrated)
            intent = migrated
        elif schema != OUTBOX_SCHEMA:
            raise VerificationError("outbox entry is invalid")
        try:
            pins = _validate_provider_transaction_pins(
                intent.get("provider_pins")
            )
        except VaultSyncError:
            self._quarantine_pending_outbox(
                pending,
                intent,
                reason_code="outbox_provider_pins_invalid",
            )
            return None
        if pins != self.provider_pins:
            self._quarantine_pending_outbox(
                pending,
                intent,
                reason_code="outbox_provider_changed",
            )
            return None
        recovery = _outbox_recovery_value(intent)
        if intent.get("recovery") != recovery:
            intent["recovery"] = recovery
            atomic_write_json(pending, intent)
        return intent

    def _attempt_pending(self, pending: Path) -> str:
        intent = load_json(pending)
        if not isinstance(intent, dict):
            raise VerificationError("outbox entry is invalid")
        validate_identifier(intent.get("transaction_id"), "transaction_id")
        intent = self._prepare_pending_outbox(pending, intent)
        if intent is None:
            return "quarantined"
        attempts = intent.get("attempts")
        if not isinstance(attempts, dict):
            raise VerificationError("outbox attempt state is invalid")
        attempts["count"] = int(attempts.get("count", 0)) + 1
        attempts["last_attempt_at"] = utc_now()
        attempts["last_error_code"] = None
        recovery = _outbox_recovery_value(intent)
        recovery.update(
            {
                "status": "in_flight",
                "attempt_count": attempts["count"],
                "last_error_code": None,
                "next_attempt_at": None,
                "updated_at": utc_now(),
            }
        )
        intent["recovery"] = recovery
        atomic_write_json(pending, intent)
        try:
            self._upload_artifacts(intent, pending)
            # _publish_git performs the authoritative fetch immediately before
            # comparing CURRENT. Avoid a redundant privacy check and fetch here;
            # this is the hot path for queued recovery and large artifact flush.
            self.git.ensure(fetch_remote=False)
            result, commit, observed, remote = self._publish_git(
                intent, candidate=False
            )
        except VaultSyncError as exc:
            attempts["last_error_code"] = exc.code
            intent["state"] = (
                "drive_verified"
                if all(
                    isinstance(item, Mapping)
                    and _local_artifact_storage(item) is not None
                    for item in intent.get("artifacts", [])
                )
                else "queued"
            )
            recovery["last_error_code"] = exc.code
            recovery["last_error_at"] = utc_now()
            recovery["updated_at"] = utc_now()
            if (
                exc.code in OUTBOX_BLOCKED_ERROR_CODES
                or attempts["count"] >= OUTBOX_MAX_RETRY_ATTEMPTS
            ):
                recovery["status"] = "blocked"
                recovery["next_attempt_at"] = None
                intent["recovery"] = recovery
                atomic_write_json(pending, intent)
                return "blocked"
            delay = _outbox_retry_delay_seconds(attempts["count"])
            recovery["status"] = "retryable"
            recovery["next_attempt_at"] = (
                dt.datetime.now(dt.timezone.utc)
                + dt.timedelta(seconds=delay)
            ).isoformat().replace("+00:00", "Z")
            intent["recovery"] = recovery
            atomic_write_json(pending, intent)
            return "pending"
        self._finish_outbox(pending, intent, result, commit, observed, remote)
        if (
            result == "candidate"
            and intent.get("identity_kind") == "provisional_source"
        ):
            return "provisional_candidate"
        return result

    def flush_once(
        self,
        *,
        transaction_id: str | None = None,
        already_locked: bool = False,
        ready_only: bool = False,
        retry_blocked: bool = False,
    ) -> str:
        def is_ready(path: Path, *, force: bool = False) -> bool:
            value = load_json(path)
            if not isinstance(value, Mapping):
                return False
            if not _outbox_recovery_due(value, force=force):
                return False
            if not ready_only:
                return True
            artifacts = value.get("artifacts")
            if not isinstance(artifacts, list):
                return False
            return not artifacts or all(
                isinstance(item, Mapping)
                and _local_artifact_storage(item) is not None
                for item in artifacts
            )

        def restore_blocked(path: Path) -> Path | None:
            value = load_json(path)
            if not isinstance(value, Mapping):
                raise VerificationError("blocked outbox entry is invalid")
            intent = value.get("pending_intent")
            if not isinstance(intent, Mapping):
                raise VerificationError("blocked outbox intent is missing")
            transaction = validate_identifier(
                intent.get("transaction_id"),
                "blocked transaction_id",
            )
            pending = _outbox_path(self.data_dir, "pending", transaction)
            restored = _json_clone(intent)
            recovery = _outbox_recovery_value(restored)
            recovery.update(
                {
                    "status": "ready",
                    "next_attempt_at": None,
                    "updated_at": utc_now(),
                }
            )
            restored["recovery"] = recovery
            atomic_write_json(pending, restored)
            with contextlib.suppress(FileNotFoundError):
                path.unlink()
            return pending

        def execute() -> str:
            force = transaction_id is not None or retry_blocked
            if transaction_id is not None:
                state = _find_outbox_state(self.data_dir, transaction_id)
                if state == "blocked":
                    if not retry_blocked:
                        return "blocked"
                    blocked = _outbox_path(
                        self.data_dir, "blocked", transaction_id
                    )
                    pending = restore_blocked(blocked)
                    paths = [pending]
                elif state == "pending":
                    pending = _outbox_path(
                        self.data_dir, "pending", transaction_id
                    )
                    value = load_json(pending)
                    if (
                        isinstance(value, Mapping)
                        and _outbox_recovery_value(value)["status"] == "blocked"
                        and not retry_blocked
                    ):
                        return "blocked"
                    paths = [pending] if is_ready(pending, force=force) else []
                else:
                    paths = []
            else:
                roots = [self.data_dir / "outbox" / "pending"]
                if retry_blocked:
                    roots.append(self.data_dir / "outbox" / "blocked")
                candidates: list[Path] = []
                for root in roots:
                    if not root.exists():
                        continue
                    for path in root.iterdir():
                        if not path.is_file() or path.suffix != ".json":
                            continue
                        if root.name == "blocked":
                            blocked_value = load_json(path)
                            if not isinstance(blocked_value, Mapping):
                                continue
                            pending_intent = blocked_value.get("pending_intent")
                            if not isinstance(pending_intent, Mapping):
                                continue
                            if not is_ready(
                                Path(path),
                                force=True,
                            ):
                                # Blocked entries are only considered when the
                                # caller explicitly requested recovery.
                                continue
                        elif not is_ready(path, force=force):
                            continue
                        candidates.append(path)
                paths = sorted(
                    candidates,
                    key=lambda item: (item.stat().st_mtime_ns, item.name),
                )[:1]
            if not paths:
                return "noop"
            selected = paths[0]
            if selected.parent.name == "blocked":
                selected = restore_blocked(selected)
                if selected is None:
                    return "noop"
            return self._attempt_pending(selected)

        if already_locked:
            return execute()
        with FileLock(self.lock_path):
            return execute()

    def pull_context(
        self,
        workspace: Path,
        *,
        task_id: str | None = None,
        include_artifacts: bool = True,
    ) -> tuple[str, str | None]:
        identity = resolve_workspace(
            workspace,
            self.config["privacy"]["allowed_roots"],
            task_id=task_id,
        )
        with FileLock(self.lock_path):
            self.git.ensure()
            remote = load_remote_task(self.git, identity)
            context = _continuation_context(remote, git=self.git)
            note: str | None = None
            if include_artifacts:
                note, _ = self._materialize_remote_artifacts(
                    identity,
                    remote,
                    maximum_bytes=int(
                        self.config["sync"]["max_total_bytes_per_turn"]
                    ),
                )
        return context, note

    def status(self) -> Mapping[str, Any]:
        network_mode = self._memory_network_enabled()
        network_counts: dict[str, int] = {}
        for state in ("pending", "done", "quarantine"):
            root = self.data_dir / "memory-network" / "outbox" / state
            network_counts[state] = (
                sum(1 for path in root.glob("*.json") if path.is_file())
                if root.exists()
                else 0
            )
        network_index: Mapping[str, Any] = {
            "schema_version": memory_network.INDEX_CONTRACT,
            "remote_head": None,
            "documents": 0,
            "fragments": 0,
            "tokens": 0,
            "edges": 0,
        }
        if _memory_network_index_path(self.data_dir).exists():
            try:
                network_index = self._memory_index().stats()
            except memory_network.MemoryNetworkError:
                network_index = {
                    **network_index,
                    "state": "invalid_rebuild_required",
                }
        counts: dict[str, int] = {}
        recovery_counts = {
            "ready": 0,
            "retryable": 0,
            "blocked": 0,
        }
        needs_authorization: Mapping[str, Any] = {}
        projection_state: Mapping[str, Any] | None = None
        routing_counts = {
            "pending": 0,
            "provisional": 0,
            "promoted": 0,
            "confirmed_by_user": 0,
            "rejected": 0,
        }
        if not network_mode:
            for state in (
                "pending",
                "blocked",
                "done",
                "candidate",
                "quarantine",
            ):
                root = self.data_dir / "outbox" / state
                counts[state] = (
                    sum(
                        1
                        for path in root.iterdir()
                        if path.is_file() and path.suffix == ".json"
                    )
                    if root.exists()
                    else 0
                )
            recovery_counts["blocked"] = counts.get("blocked", 0)
            pending_root = self.data_dir / "outbox" / "pending"
            if pending_root.exists():
                for path in pending_root.glob("*.json"):
                    with contextlib.suppress(
                        VaultSyncError, OSError, ValueError
                    ):
                        value = load_json(path)
                        if isinstance(value, Mapping):
                            status = _outbox_recovery_value(value)["status"]
                            if status in {"in_flight", "ready"}:
                                status = "ready"
                            if status in recovery_counts:
                                recovery_counts[status] += 1
            needs_authorization = (
                _reconciliation_needs_authorization_summary(self.data_dir)
            )
            projection_path = _projection_state_path(self.data_dir)
            if projection_path.exists():
                loaded = load_json(projection_path)
                if (
                    isinstance(loaded, Mapping)
                    and loaded.get("schema_version") == PROJECTION_SCHEMA
                ):
                    projection_state = loaded
            routing_root = self.data_dir / "state" / "routing-requests"
            if routing_root.exists():
                for path in list(routing_root.glob("*.json"))[:1000]:
                    with contextlib.suppress(
                        VaultSyncError, OSError, ValueError
                    ):
                        _loaded_path, request = _load_routing_request(
                            self.data_dir,
                            path.stem,
                        )
                        state = request.get("state")
                        if state in routing_counts:
                            routing_counts[str(state)] += 1
        update_state: Mapping[str, Any] | None = None
        with contextlib.suppress(VaultSyncError, OSError, ValueError):
            update_state = _load_update_state(self.data_dir)
        signed_update_trust = _signed_update_trust_report(self.data_dir)
        try:
            private_diagnostics = diagnostics_command(
                self.data_dir,
                limit=0,
            )
        except VaultSyncError:
            private_diagnostics = {
                "schema_version": DIAGNOSTIC_SUMMARY_SCHEMA,
                "available": False,
                "private_local_only": True,
                "record_count": 0,
                "corrupt_record_count": 0,
                "recent_records": [],
                "retention": {
                    "maximum_record_bytes": MAX_DIAGNOSTIC_RECORD_BYTES,
                    "maximum_records": MAX_DIAGNOSTIC_RECORDS,
                    "maximum_total_bytes": MAX_DIAGNOSTIC_TOTAL_BYTES,
                },
                "captured_sensitive_content": False,
            }
        result = {
            "schema_version": "memory-vault-sync-status/v1",
            "plugin_version": VERSION,
            "configured": (self.data_dir / "config.json").is_file(),
            "enabled": bool(self.config.get("enabled")),
            "outbox": counts,
            "outbox_recovery": recovery_counts,
            "private_diagnostics": private_diagnostics,
            "needs_authorization": needs_authorization,
            "cache_available": self.git.has_cache(),
            "memory_network": {
                "enabled": network_mode,
                "mode": "taskless_associative",
                "transport": "append_only_incremental_git",
                "receive_strategy": "commit_delta_after_initial_index",
                "ordinary_turn_objects": 2,
                "batch_max_items": MAX_MEMORY_NETWORK_BATCH_ITEMS,
                "batch_max_bytes": MAX_MEMORY_NETWORK_BATCH_BYTES,
                "outbox": network_counts,
                "index": dict(network_index),
                "associative_recall_enabled": bool(
                    self.config["sync"].get(
                        "associative_recall_enabled", True
                    )
                ),
            },
            "task_projection": {
                "enabled": bool(
                    self.config.get("projection", {}).get("enabled")
                ),
                "root_configured": bool(
                    self.config.get("projection", {}).get("root")
                ),
                "last_summary": (
                    dict(projection_state.get("summary", {}))
                    if projection_state is not None
                    and isinstance(projection_state.get("summary"), Mapping)
                    else {}
                ),
                "sidebar_enumeration_available": False,
            },
            "artifact_chunking": {
                "enabled": bool(
                    self.config["sync"].get(
                        "chunked_artifacts_enabled",
                        False,
                    )
                ),
                "reader_protocol": CHUNK_READER_PROTOCOL,
                "algorithm": CHUNK_ALGORITHM,
                "encryption_policy": CHUNK_ENCRYPTION_POLICY,
                "chunk_size": CHUNK_SIZE_BYTES,
                "maximum_chunks": MAX_CHUNK_COUNT,
                "minimum_artifact_bytes": int(
                    self.config["sync"].get(
                        "chunked_artifact_min_bytes",
                        DEFAULT_CHUNK_MINIMUM_BYTES,
                    )
                ),
                "remote_deletion_enabled": False,
            },
            "automatic_task_matching": {
                "enabled": bool(
                    self.config.get("matching", {}).get("enabled")
                )
                and not network_mode,
                "mode": (
                    "retired_from_memory_runtime"
                    if network_mode
                    else "content_review_then_explicit_confirmation"
                ),
                "automatic_binding_enabled": False,
                "legacy_auto_match_disabled": LEGACY_AUTO_BINDING_DISABLED,
                "auto_provisional": False,
                "auto_promote_after_consistency_check": False,
                "prompt_on_ambiguity": bool(
                    self.config.get("matching", {}).get(
                        "prompt_on_ambiguity"
                    )
                ) and not network_mode,
                "policy_version": MATCHING_POLICY_VERSION,
                "routing_requests": routing_counts,
            },
            "automatic_updates": {
                "enabled": bool(self.config["updates"].get("enabled")),
                "auto_install": bool(
                    self.config["updates"].get("auto_install")
                ),
                "check_interval_hours": (
                    int(self.config["updates"]["check_interval_seconds"])
                    // (60 * 60)
                ),
                "last_status": (
                    update_state.get("status")
                    if update_state is not None
                    else "never_checked"
                ),
                "available_version": (
                    update_state.get("available_version")
                    if update_state is not None
                    else None
                ),
                "installed_version": (
                    update_state.get("installed_version")
                    if update_state is not None
                    else VERSION
                ),
                "signed_update_trust": signed_update_trust,
            },
        }
        if network_mode:
            for retired_key in (
                "outbox",
                "outbox_recovery",
                "needs_authorization",
                "task_projection",
                "automatic_task_matching",
            ):
                result.pop(retired_key, None)
        return result

    def doctor(self, *, online: bool = False) -> Mapping[str, Any]:
        checks: list[dict[str, Any]] = []

        def add(name: str, ok: bool, detail: str) -> None:
            checks.append({"name": name, "ok": ok, "detail": detail})

        add(
            "python",
            sys.version_info >= (3, 10),
            f"{sys.version_info.major}.{sys.version_info.minor}.{sys.version_info.micro}",
        )
        try:
            version = run_process(["git", "--version"], timeout=5).stdout.decode(
                "utf-8", "replace"
            ).strip()
            add("git", True, version)
        except VaultSyncError:
            add("git", False, "Git is unavailable")
        add(
            "allowed_roots",
            bool(self.config["privacy"]["allowed_roots"]),
            (
                f"{len(self.config['privacy']['allowed_roots'])} configured"
                if self.config["privacy"]["allowed_roots"]
                else "none configured"
            ),
        )
        local_status = self.status()
        if self._memory_network_enabled():
            network_status = local_status.get("memory_network", {})
            network_outbox = (
                network_status.get("outbox", {})
                if isinstance(network_status, Mapping)
                else {}
            )
            pending_count = int(network_outbox.get("pending", 0))
            quarantined_count = int(network_outbox.get("quarantine", 0))
            add(
                "memory_network_outbox",
                quarantined_count == 0,
                (
                    f"{pending_count} safely queued"
                    if quarantined_count == 0
                    else f"{quarantined_count} privacy/integrity quarantines"
                ),
            )
        else:
            outbox_status = local_status["outbox_recovery"]
            blocked_count = int(outbox_status.get("blocked", 0))
            add(
                "outbox_recovery",
                blocked_count == 0,
                (
                    "ready"
                    if blocked_count == 0
                    else f"{blocked_count} blocked; remediate before retry"
                ),
            )
        diagnostic_status = local_status["private_diagnostics"]
        add(
            "private_diagnostics",
            bool(diagnostic_status.get("available"))
            and int(diagnostic_status.get("corrupt_record_count", 0)) == 0,
            (
                "private diagnostic store is unavailable"
                if not diagnostic_status.get("available")
                else (
                    f"{diagnostic_status.get('record_count', 0)} valid, "
                    f"{diagnostic_status.get('corrupt_record_count', 0)} "
                    "corrupt bounded local records"
                )
            ),
        )
        if not self._memory_network_enabled():
            projection = self.config["projection"]
            if projection.get("enabled"):
                try:
                    root = self._projection_root()
                    add(
                        "task_projection",
                        root is not None,
                        "configured local continuation root",
                    )
                except VaultSyncError as exc:
                    add("task_projection", False, exc.code)
            else:
                add("task_projection", True, "disabled")
        chunking_enabled = bool(
            self.config["sync"].get("chunked_artifacts_enabled", False)
        )
        add(
            "encrypted_artifact_chunking",
            True,
            (
                f"enabled; fixed chunk size {CHUNK_SIZE_BYTES} bytes"
                if chunking_enabled
                else "disabled for new uploads; historical chunks remain readable"
            ),
        )
        if self._memory_network_enabled():
            network_status = local_status.get("memory_network", {})
            index_status = (
                network_status.get("index", {})
                if isinstance(network_status, Mapping)
                else {}
            )
            add(
                "associative_memory_network",
                not isinstance(index_status, Mapping)
                or index_status.get("state") != "invalid_rebuild_required",
                (
                    "taskless append-only network; commit-delta receive and "
                    "local associative recall enabled"
                ),
            )
        else:
            matching = self.config.get("matching", {})
            add(
                "task_matching",
                bool(matching.get("enabled")),
                (
                    "content review enabled; legacy score-only automatic binding disabled"
                    if matching.get("enabled")
                    else "disabled"
                ),
            )
        if self.config["updates"].get("enabled"):
            try:
                _trusted_codex_executable(self.config, self.data_dir)
                add(
                    "automatic_updates",
                    True,
                    "trusted Codex executable available",
                )
            except VaultSyncError as exc:
                add("automatic_updates", False, exc.code)
        else:
            add("automatic_updates", True, "disabled")
        signed_trust = local_status["automatic_updates"][
            "signed_update_trust"
        ]
        signed_trust_ok = bool(signed_trust.get("valid")) and not bool(
            signed_trust.get("root_expired")
        )
        if not signed_trust.get("required"):
            signed_trust_detail = (
                "not provisioned; exact repository, bundle, and commit "
                "identity remains active"
            )
        elif not signed_trust.get("valid"):
            signed_trust_detail = (
                "configured trust is invalid; signed updates fail closed"
            )
        elif signed_trust.get("root_expired"):
            signed_trust_detail = (
                "trusted root is expired; a valid sequential rotation is required"
            )
        else:
            signed_trust_detail = (
                f"required; trusted root version "
                f"{signed_trust.get('root_version')}"
            )
        add(
            "signed_update_trust",
            signed_trust_ok,
            signed_trust_detail,
        )
        if not self._memory_network_enabled():
            needs_authorization = (
                _reconciliation_needs_authorization_summary(self.data_dir)
            )
            needs_authorization_ids = needs_authorization["pending_ids"]
            add(
                "reconciliation_needs_authorization",
                needs_authorization["count"] == 0,
                (
                    "none"
                    if needs_authorization["count"] == 0
                    else (
                        f"{needs_authorization['count']} preserved: "
                        + ", ".join(str(item) for item in needs_authorization_ids)
                        + "; "
                        + str(needs_authorization["next_step"])
                    )
                ),
            )
        if online:
            try:
                self.git.ensure()
                add(
                    "control_plane_private",
                    True,
                    "private repository verified",
                )
            except VaultSyncError as exc:
                add("control_plane_private", False, exc.code)
            adapter: DriveAdapter | None = None
            if self.config["sync"].get("artifact_mode") != "none":
                try:
                    adapter = self._drive()
                    adapter.assert_private()
                    add(
                        "object_store_private",
                        True,
                        "private object-store root verified",
                    )
                except VaultSyncError as exc:
                    add("object_store_private", False, exc.code)
            if chunking_enabled or isinstance(adapter, RcloneCryptAdapter):
                try:
                    if not isinstance(adapter, RcloneCryptAdapter):
                        raise ConfigurationError(
                            "chunking requires rclone crypt"
                        )
                    names = set(adapter._list_names(""))
                    if CHUNK_POLICY_PATH not in names:
                        if chunking_enabled:
                            adapter._chunk_policy()
                        add(
                            "encrypted_chunk_policy",
                            True,
                            "not initialized; whole objects only",
                        )
                    else:
                        adapter._chunk_policy()
                        add(
                            "encrypted_chunk_policy",
                            True,
                            (
                                "encrypted key epoch and algorithm policy "
                                "verified"
                            ),
                        )
                except VaultSyncError as exc:
                    add("encrypted_chunk_policy", False, exc.code)
        result = {
            "schema_version": "memory-vault-sync-doctor/v1",
            "ok": all(item["ok"] for item in checks),
            "checks": checks,
        }
        if not self._memory_network_enabled():
            result["needs_authorization"] = needs_authorization
        return result


def _read_rclone_config_password(args: argparse.Namespace) -> str:
    if bool(getattr(args, "config_password_stdin", False)):
        raw = sys.stdin.buffer.read(4097)
        if len(raw) > 4096:
            raise PrivacyError(
                "rclone configuration password exceeds the fixed limit"
            )
        if raw.endswith(b"\r\n"):
            raw = raw[:-2]
        elif raw.endswith((b"\r", b"\n")):
            raw = raw[:-1]
        if b"\r" in raw or b"\n" in raw or b"\x00" in raw:
            raise PrivacyError("rclone configuration password is invalid")
        try:
            password = raw.decode("utf-8", "strict")
        except UnicodeDecodeError as exc:
            raise PrivacyError(
                "rclone configuration password must be UTF-8"
            ) from exc
    else:
        password = getpass.getpass("Encrypted rclone config password: ")
    if not password or any(item in password for item in ("\x00", "\r", "\n")):
        raise AuthenticationError(
            "encrypted rclone configuration password is required"
        )
    return password


def _assert_object_store_switch_ready(data_dir: Path) -> None:
    unfinished: list[str] = []
    for state in ("pending", "blocked", "candidate"):
        root = data_dir / "outbox" / state
        if not root.exists():
            continue
        assert_plain_path(root, require_file=False)
        entries = [
            path
            for path in root.iterdir()
            if path.is_file() and path.suffix == ".json"
        ]
        if len(entries) > 1000:
            raise VerificationError("outbox exceeds the safety limit")
        if entries:
            unfinished.append(state)
    if unfinished:
        raise BusyError(
            "finish or explicitly resolve unfinished outbox transactions "
            "before changing the primary object store"
        )


def _assert_rclone_configuration_preflight(
    config: Mapping[str, Any],
    data_dir: Path,
) -> None:
    profile = _provider_profile(config)
    stores = profile.get("object_stores")
    if not isinstance(stores, list):
        raise ConfigurationError("provider object stores are invalid")
    primary = [
        item
        for item in stores
        if isinstance(item, Mapping)
        and item.get("role") == "primary"
        and item.get("access") == "read_write"
    ]
    if len(primary) != 1:
        raise ConfigurationError("active primary object store is ambiguous")
    if primary[0].get("driver") != RCLONE_OBJECT_STORE_DRIVER:
        _assert_object_store_switch_ready(data_dir)


def configure_rclone_store_command(
    args: argparse.Namespace,
    data_dir: Path,
) -> Mapping[str, Any]:
    with FileLock(data_dir / "locks" / "sync.lock"):
        preflight_config = load_config(data_dir)
        _assert_rclone_configuration_preflight(
            preflight_config
            if preflight_config is not None
            else default_config(),
            data_dir,
        )
    executable = Path(args.rclone_executable).expanduser().resolve(
        strict=True
    )
    config_path = Path(args.rclone_config).expanduser().resolve(strict=True)
    assert_plain_path(executable, require_file=True)
    assert_plain_path(config_path, require_file=True)
    password = _read_rclone_config_password(args)
    try:
        with FileLock(data_dir / "locks" / "sync.lock"):
            return _configure_rclone_store_locked(
                args,
                data_dir,
                password,
            )
    finally:
        del password


def _configure_rclone_store_locked(
    args: argparse.Namespace,
    data_dir: Path,
    password: str,
) -> Mapping[str, Any]:
    existing = load_config(data_dir)
    config = existing if existing is not None else default_config()
    _assert_rclone_configuration_preflight(config, data_dir)
    executable = Path(args.rclone_executable).expanduser().resolve(
        strict=True
    )
    config_path = Path(args.rclone_config).expanduser().resolve(strict=True)
    assert_plain_path(executable, require_file=True)
    assert_plain_path(config_path, require_file=True)
    executable_sha256, _ = stable_hash_file(
        executable,
        inspect_text=False,
    )
    rclone_adapter: RcloneCryptAdapter | None = None
    credential_written = False
    activation_committed = False
    preserve_new_credential_on_failure = False
    previous_credential_password: str | None = None
    try:
        probe = _probe_rclone_boundary(
            executable=executable,
            expected_executable_sha256=executable_sha256,
            config_path=config_path,
            remote_name=args.rclone_remote,
            config_password=password,
        )
        profile = _provider_profile(config)
        stores = profile.get("object_stores")
        adapter_configs = config.get("adapter_configs")
        credential_bindings = config.get("credential_bindings")
        if (
            not isinstance(stores, list)
            or not isinstance(adapter_configs, MutableMapping)
            or not isinstance(credential_bindings, MutableMapping)
        ):
            raise ConfigurationError("provider configuration is invalid")
        primary = [
            item
            for item in stores
            if isinstance(item, MutableMapping)
            and item.get("role") == "primary"
            and item.get("access") == "read_write"
        ]
        if len(primary) != 1:
            raise ConfigurationError(
                "active primary object store is ambiguous"
            )
        current = primary[0]
        was_rclone_primary = (
            current.get("driver") == RCLONE_OBJECT_STORE_DRIVER
        )
        if was_rclone_primary:
            store_id = validate_identifier(
                current.get("store_id"),
                "store_id",
            )
            adapter_ref = str(current.get("adapter_config_ref"))
            credential_ref = str(current.get("credential_ref"))
            previous = _validate_rclone_adapter_config(
                _adapter_config(config, adapter_ref)
            )
            preserve_new_credential_on_failure = (
                previous["config_path"] == str(config_path)
            )
            if (
                previous["remote_name"] != args.rclone_remote
                or previous["remote_fingerprint"]
                != probe["remote_fingerprint"]
            ):
                raise ConfigurationError(
                    "an existing encrypted object-store scope cannot be "
                    "changed in place"
                )
        else:
            if any(
                isinstance(item, Mapping)
                and item.get("store_id") == RCLONE_OBJECT_STORE_ID
                for item in stores
            ):
                raise ConfigurationError(
                    "rclone object-store identity is already configured"
                )
            current["role"] = "archive"
            current["access"] = "read_only"
            store_id = RCLONE_OBJECT_STORE_ID
            adapter_ref = RCLONE_OBJECT_ADAPTER_REF
            credential_ref = RCLONE_OBJECT_CREDENTIAL_REF
            stores.append(
                {
                    "store_id": store_id,
                    "driver": RCLONE_OBJECT_STORE_DRIVER,
                    "adapter_config_ref": adapter_ref,
                    "credential_ref": credential_ref,
                    "scope_fingerprint": "0" * 64,
                    "role": "primary",
                    "access": "read_write",
                }
            )
        adapter_configs[adapter_ref] = {
            "executable": str(executable),
            "executable_sha256": probe["executable_sha256"],
            "config_path": str(config_path),
            "remote_name": args.rclone_remote,
            "remote_fingerprint": probe["remote_fingerprint"],
            "minimum_version": probe["minimum_version"],
            "verified_version": probe["verified_version"],
        }
        credential_bindings[credential_ref] = {
            "helper_host": RCLONE_CONFIG_CREDENTIAL_HOST,
        }
        _refresh_provider_scope_fingerprints(config)
        config = validate_config(config)
        rclone_adapter = RcloneCryptAdapter(
            config,
            store_id=store_id,
            config_password_override=password,
            data_dir=data_dir,
        )
        if args.no_initialize_root:
            root_result = rclone_adapter.inspect_initialization_state()
        else:
            root_result = rclone_adapter.initialize_private_root(data_dir)
        if was_rclone_primary and not preserve_new_credential_on_failure:
            with contextlib.suppress(AuthenticationError):
                previous_credential = credential_get(
                    RCLONE_CONFIG_CREDENTIAL_HOST,
                    store_id,
                )
                if isinstance(previous_credential.get("password"), str):
                    previous_credential_password = previous_credential[
                        "password"
                    ]
        credential_store(
            RCLONE_CONFIG_CREDENTIAL_HOST,
            store_id,
            password,
        )
        credential_written = True
        stable_runtime = _refresh_stable_runtime(data_dir)
        atomic_write_json(data_dir / "config.json", config)
        activation_committed = True
    except Exception as activation_error:
        if (
            credential_written
            and not activation_committed
            and not preserve_new_credential_on_failure
        ):
            try:
                if previous_credential_password is None:
                    credential_erase(
                        RCLONE_CONFIG_CREDENTIAL_HOST,
                        store_id,
                    )
                else:
                    credential_store(
                        RCLONE_CONFIG_CREDENTIAL_HOST,
                        store_id,
                        previous_credential_password,
                    )
            except Exception as rollback_error:
                raise VerificationError(
                    "rclone activation failed and credential rollback could "
                    "not be verified"
                ) from activation_error
        if isinstance(activation_error, OSError):
            raise ConfigurationError(
                "rclone configuration could not be committed safely"
            ) from activation_error
        raise
    finally:
        if rclone_adapter is not None:
            rclone_adapter._config_password_override = None
    return {
        "schema_version": "memory-vault-rclone-configured/v1",
        "configured": True,
        "store_id": store_id,
        "driver": RCLONE_OBJECT_STORE_DRIVER,
        "backend_type": probe["backend_type"],
        "verified_rclone_version": probe["verified_version"],
        "executable_pinned": True,
        "encrypted_config_verified": True,
        "remote_fingerprint": probe["remote_fingerprint"],
        "credentials_stored_in_config": False,
        "credentials_stored_in_os_helper": True,
        "marker_created": bool(root_result.get("marker_created")),
        "encrypted_root_verified": bool(
            root_result.get("encrypted_root_verified")
        ),
        "stable_runtime_version": stable_runtime["plugin_version"],
        "stable_runtime_updated": stable_runtime["updated"],
    }


def rclone_auth_command(
    args: argparse.Namespace,
    config: Mapping[str, Any],
) -> Mapping[str, Any]:
    store = _object_store_config(config)
    if store.get("driver") != RCLONE_OBJECT_STORE_DRIVER:
        raise ConfigurationError(
            "the active object store is not rclone crypt"
        )
    adapter = _validate_rclone_adapter_config(
        _adapter_config(config, store.get("adapter_config_ref"))
    )
    password = _read_rclone_config_password(args)
    try:
        probe = _probe_rclone_boundary(
            executable=Path(adapter["executable"]),
            expected_executable_sha256=adapter["executable_sha256"],
            config_path=Path(adapter["config_path"]),
            remote_name=adapter["remote_name"],
            config_password=password,
        )
        if (
            probe["remote_fingerprint"] != adapter["remote_fingerprint"]
            or probe["verified_version"] != adapter["verified_version"]
        ):
            raise PrivacyError(
                "rclone executable or encrypted remote changed"
            )
        credential_store(
            str(store["credential_host"]),
            str(store["store_id"]),
            password,
        )
    finally:
        del password
    RcloneCryptAdapter(config).assert_private()
    return {
        "schema_version": "memory-vault-sync-auth/v1",
        "service": "rclone-crypt",
        "stored_in_os_credential_helper": True,
        "encrypted_config_verified": True,
        "encrypted_root_verified": True,
    }


def initialize_object_store_command(
    engine: SyncEngine,
) -> Mapping[str, Any]:
    adapter = engine._drive()
    if isinstance(adapter, RcloneCryptAdapter):
        return adapter.initialize_private_root(engine.data_dir)
    adapter.assert_private()
    return {
        "schema_version": "memory-vault-object-store-root/v1",
        "store_id": adapter.store_id,
        "driver": adapter.driver,
        "marker_created": False,
        "private_root_verified": True,
    }


def configure_chunking_command(
    args: argparse.Namespace,
    engine: SyncEngine,
) -> Mapping[str, Any]:
    if bool(args.enable) == bool(args.disable):
        raise ConfigurationError(
            "choose exactly one of chunking enable or disable"
        )
    with FileLock(engine.lock_path):
        _assert_object_store_switch_ready(engine.data_dir)
        config = load_config(engine.data_dir)
        if config is None:
            raise ConfigurationError("run configure first")
        store = _object_store_config(config)
        if store.get("driver") != RCLONE_OBJECT_STORE_DRIVER:
            raise ConfigurationError(
                "encrypted chunking requires an active rclone crypt store"
            )
        minimum = (
            int(args.minimum_bytes)
            if args.minimum_bytes is not None
            else int(
                config["sync"].get(
                    "chunked_artifact_min_bytes",
                    DEFAULT_CHUNK_MINIMUM_BYTES,
                )
            )
        )
        if not (
            CHUNK_SIZE_BYTES
            <= minimum
            <= CHUNK_SIZE_BYTES * MAX_CHUNK_COUNT
        ):
            raise ConfigurationError(
                "chunk minimum must be between one fixed chunk and the "
                "maximum chunked artifact size"
            )
        policy_result: Mapping[str, Any] | None = None
        enabled = bool(args.enable)
        if enabled:
            adapter = engine._drive()
            if not isinstance(adapter, RcloneCryptAdapter):
                raise ConfigurationError(
                    "encrypted chunking requires rclone crypt"
                )
            policy_result = adapter.initialize_chunk_policy()
        config["sync"]["chunked_artifacts_enabled"] = enabled
        config["sync"]["chunked_artifact_min_bytes"] = minimum
        validated = validate_config(config)
        stable_runtime = _refresh_stable_runtime(engine.data_dir)
        atomic_write_json(engine.data_dir / "config.json", validated)
        persisted = load_config(engine.data_dir)
        if (
            persisted is None
            or persisted["sync"]["chunked_artifacts_enabled"] is not enabled
            or persisted["sync"]["chunked_artifact_min_bytes"] != minimum
        ):
            raise VerificationError(
                "chunking configuration could not be verified"
            )
    return {
        "schema_version": "memory-vault-chunking-configured/v1",
        "enabled": enabled,
        "store_id": store["store_id"],
        "driver": store["driver"],
        "reader_protocol": CHUNK_READER_PROTOCOL,
        "algorithm": CHUNK_ALGORITHM,
        "encryption_policy": CHUNK_ENCRYPTION_POLICY,
        "chunk_size": CHUNK_SIZE_BYTES,
        "maximum_chunks": MAX_CHUNK_COUNT,
        "minimum_artifact_bytes": minimum,
        "policy_initialized": policy_result is not None,
        "remote_deletion_performed": False,
        "historical_whole_objects_readable": True,
        "historical_chunked_objects_readable": True,
        "stable_runtime_version": stable_runtime["plugin_version"],
        "stable_runtime_updated": stable_runtime["updated"],
    }


def configure_command(args: argparse.Namespace, data_dir: Path) -> Mapping[str, Any]:
    config = default_config()
    existing = load_config(data_dir)
    if existing is not None:
        config = existing
    profile = _provider_profile(config)
    control = profile.get("control_plane")
    if not isinstance(control, MutableMapping):
        raise ConfigurationError("active control-plane profile is invalid")
    control_ref = control.get("adapter_config_ref")
    control_adapter = _adapter_config(config, control_ref)
    if not isinstance(control_adapter, MutableMapping):
        raise ConfigurationError("control-plane adapter config is not mutable")
    credential_ref = control.get("credential_ref")
    credential_bindings = config.get("credential_bindings")
    control_credential = (
        credential_bindings.get(credential_ref)
        if isinstance(credential_bindings, MutableMapping)
        else None
    )
    if not isinstance(control_credential, MutableMapping):
        raise ConfigurationError("control-plane credential binding is not mutable")
    stores = profile.get("object_stores")
    if not isinstance(stores, list):
        raise ConfigurationError("active object-store profile is invalid")
    primary = [
        store
        for store in stores
        if isinstance(store, MutableMapping)
        and store.get("role") == "primary"
        and store.get("access") == "read_write"
    ]
    if len(primary) != 1:
        raise ConfigurationError("active primary object store is ambiguous")
    object_store = primary[0]
    object_ref = object_store.get("adapter_config_ref")
    object_adapter = _adapter_config(config, object_ref)
    if not isinstance(object_adapter, MutableMapping):
        raise ConfigurationError("object-store adapter config is not mutable")
    object_driver = object_store.get("driver")
    drive_arguments_present = bool(
        args.drive_root_folder_id or args.drive_oauth_client_id
    )
    if drive_arguments_present and object_driver != "google-drive-v3":
        raise ConfigurationError(
            "Google Drive options require a Google Drive primary object store"
        )
    if existing is not None:
        if args.repo_url and args.repo_url != control_adapter.get("repo_url"):
            raise ConfigurationError(
                "an existing control-plane scope cannot be changed in place; "
                "create and verify a new provider profile"
            )
        if args.branch and args.branch != control_adapter.get("branch"):
            raise ConfigurationError(
                "an existing control-plane branch cannot be changed in place; "
                "create and verify a new provider profile"
            )
        if (
            args.control_privacy_verifier
            and args.control_privacy_verifier
            != control_adapter.get("privacy_verifier")
        ):
            raise ConfigurationError(
                "an existing control-plane privacy verifier cannot be changed "
                "in place; create and verify a new provider profile"
            )
        if (
            args.control_credential_host
            and args.control_credential_host
            != control_credential.get("helper_host")
        ):
            raise ConfigurationError(
                "an existing control-plane credential scope cannot be changed "
                "in place; create and verify a new provider profile"
            )
        if object_driver == "google-drive-v3":
            old_root = object_adapter.get("root_folder_id")
            if (
                args.drive_root_folder_id
                and old_root is not None
                and args.drive_root_folder_id != old_root
            ):
                raise ConfigurationError(
                    "an existing object-store scope cannot be changed in place; "
                    "create and verify a new provider profile"
                )
    if args.repo_url:
        control_adapter["repo_url"] = args.repo_url
    if args.branch:
        control_adapter["branch"] = args.branch
    if args.expected_repository:
        control_adapter["expected_repository"] = args.expected_repository
    if args.control_privacy_verifier:
        control_adapter["privacy_verifier"] = args.control_privacy_verifier
    if args.control_credential_host:
        control_credential["helper_host"] = args.control_credential_host
    if args.drive_root_folder_id:
        object_adapter["root_folder_id"] = args.drive_root_folder_id
    if args.drive_oauth_client_id:
        object_adapter["oauth_client_id"] = args.drive_oauth_client_id
    if args.allow_root:
        roots = []
        for value in args.allow_root:
            path = Path(value).expanduser().resolve(strict=True)
            assert_plain_path(path, require_file=False)
            text = str(path)
            if text not in roots:
                roots.append(text)
        config["privacy"]["allowed_roots"] = roots
    if args.auto_update is not None:
        config["updates"]["enabled"] = bool(args.auto_update)
        config["updates"]["auto_install"] = bool(args.auto_update)
    if args.update_check_hours is not None:
        config["updates"]["check_interval_seconds"] = (
            int(args.update_check_hours) * 60 * 60
        )
    if args.codex_executable:
        codex_executable = Path(args.codex_executable).expanduser().resolve(
            strict=True
        )
        assert_plain_path(codex_executable, require_file=True)
        config["updates"]["codex_executable"] = str(codex_executable)
    if args.artifact_mode:
        config["sync"]["artifact_mode"] = args.artifact_mode
    if args.max_stop_upload_bytes is not None:
        if args.max_stop_upload_bytes < 0:
            raise ConfigurationError(
                "--max-stop-upload-bytes must be non-negative"
            )
        config["sync"]["max_stop_upload_bytes"] = int(
            args.max_stop_upload_bytes
        )
    if args.max_parallel_artifact_uploads is not None:
        config["sync"]["max_parallel_artifact_uploads"] = int(
            args.max_parallel_artifact_uploads
        )
    config["enabled"] = not args.disable
    _refresh_provider_scope_fingerprints(config)
    config = validate_config(config)
    stable_runtime = _refresh_stable_runtime(data_dir)
    atomic_write_json(data_dir / "config.json", config)
    active_object = _object_store_config(config)
    return {
        "schema_version": "memory-vault-sync-configured/v1",
        "configured": True,
        "enabled": config["enabled"],
        "allowed_root_count": len(config["privacy"]["allowed_roots"]),
        "object_store_root_configured": bool(
            active_object.get("root_folder_id")
            or active_object.get("remote_fingerprint")
        ),
        "object_store_oauth_client_configured": bool(
            active_object.get("oauth_client_id")
        ),
        "active_provider_profile_id": profile.get("profile_id"),
        "active_control_plane_driver": control.get("driver"),
        "active_object_store_id": object_store.get("store_id"),
        "active_object_store_driver": object_store.get("driver"),
        "credentials_stored_in_config": False,
        "stable_runtime_version": stable_runtime["plugin_version"],
        "stable_runtime_updated": stable_runtime["updated"],
        "automatic_updates_enabled": bool(config["updates"]["enabled"]),
        "automatic_update_interval_hours": (
            int(config["updates"]["check_interval_seconds"]) // (60 * 60)
        ),
        "max_stop_upload_bytes": int(
            config["sync"].get(
                "max_stop_upload_bytes",
                DEFAULT_MAX_STOP_UPLOAD_BYTES,
            )
        ),
        "max_parallel_artifact_uploads": int(
            config["sync"].get(
                "max_parallel_artifact_uploads",
                DEFAULT_MAX_PARALLEL_ARTIFACT_UPLOADS,
            )
        ),
    }


def control_auth_command(
    args: argparse.Namespace, config: Mapping[str, Any], data_dir: Path
) -> Mapping[str, Any]:
    control = _control_plane_config(config)
    verifier = control.get("privacy_verifier")
    if verifier == "github-private-v1":
        service = "GitHub"
        token_label = "Fine-grained GitHub token"
    elif verifier == "gitlab-private-v1":
        service = "GitLab"
        token_label = "Scoped GitLab access token"
    else:
        raise ConfigurationError(
            "control-plane privacy verifier is unsupported"
        )
    username = args.username or input(f"{service} username: ").strip()
    if not username:
        raise AuthenticationError(f"{service} username is required")
    token = getpass.getpass(
        f"{token_label} (private vault repository only): "
    )
    if not token:
        raise AuthenticationError(f"{service} token is required")
    host = str(control["credential_host"])
    credential_store(host, username, token)
    del token
    git = GitVault(config, data_dir)
    git.assert_remote_private()
    return {
        "schema_version": "memory-vault-sync-auth/v1",
        "service": service.lower(),
        "stored_in_os_credential_helper": True,
        "private_repository_verified": True,
    }


def github_auth_command(
    args: argparse.Namespace,
    config: Mapping[str, Any],
    data_dir: Path,
) -> Mapping[str, Any]:
    """Compatibility alias for deployments that used ``auth-github``."""

    return control_auth_command(args, config, data_dir)


@dataclasses.dataclass
class OAuthCallback:
    code: str | None = None
    state: str | None = None
    error: str | None = None


def _drive_oauth_callback(
    expected_state: str,
) -> tuple[http.server.HTTPServer, OAuthCallback, str]:
    callback = OAuthCallback()

    class Handler(http.server.BaseHTTPRequestHandler):
        def do_GET(self) -> None:
            parsed = urllib.parse.urlparse(self.path)
            query = urllib.parse.parse_qs(parsed.query)
            callback.code = query.get("code", [None])[0]
            callback.state = query.get("state", [None])[0]
            callback.error = query.get("error", [None])[0]
            success = (
                callback.code is not None
                and callback.state == expected_state
                and callback.error is None
            )
            body = (
                "Memory Vault authorization received. You may close this tab."
                if success
                else "Memory Vault authorization failed. Return to the terminal."
            ).encode("utf-8")
            self.send_response(200 if success else 400)
            self.send_header("Content-Type", "text/plain; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def log_message(self, format: str, *arguments: Any) -> None:
            return

    server = http.server.HTTPServer(("127.0.0.1", 0), Handler)
    redirect_uri = f"http://127.0.0.1:{server.server_port}/oauth2/callback"
    return server, callback, redirect_uri


def drive_auth_command(
    args: argparse.Namespace, config: MutableMapping[str, Any], data_dir: Path
) -> Mapping[str, Any]:
    store_config = _object_store_config(config)
    if store_config.get("driver") != "google-drive-v3":
        raise ConfigurationError(
            "the active object store is not Google Drive"
        )
    client_id = args.client_id or store_config.get("oauth_client_id")
    if not isinstance(client_id, str) or not client_id:
        raise ConfigurationError("Google desktop OAuth client ID is required")
    client_secret = (
        getpass.getpass("Google desktop OAuth client secret (blank if none): ")
        if not args.no_client_secret
        else ""
    )
    verifier = base64.urlsafe_b64encode(secrets.token_bytes(48)).decode().rstrip("=")
    challenge = (
        base64.urlsafe_b64encode(hashlib.sha256(verifier.encode()).digest())
        .decode()
        .rstrip("=")
    )
    state = secrets.token_urlsafe(32)
    server, callback, redirect_uri = _drive_oauth_callback(state)
    parameters = {
        "client_id": client_id,
        "redirect_uri": redirect_uri,
        "response_type": "code",
        "scope": "https://www.googleapis.com/auth/drive",
        "access_type": "offline",
        "prompt": "consent",
        "state": state,
        "code_challenge": challenge,
        "code_challenge_method": "S256",
    }
    authorization_url = (
        "https://accounts.google.com/o/oauth2/v2/auth?"
        + urllib.parse.urlencode(parameters)
    )
    print("Open this URL in your browser to authorize the private Drive folder:")
    print(authorization_url)
    server.timeout = 180
    deadline = time.monotonic() + 180
    while callback.code is None and callback.error is None and time.monotonic() < deadline:
        server.handle_request()
    server.server_close()
    if callback.error or not callback.code or callback.state != state:
        raise AuthenticationError("Drive OAuth authorization was not completed")
    form = {
        "client_id": client_id,
        "code": callback.code,
        "code_verifier": verifier,
        "redirect_uri": redirect_uri,
        "grant_type": "authorization_code",
    }
    if client_secret:
        form["client_secret"] = client_secret
    request = urllib.request.Request(
        GoogleDriveAdapter.TOKEN_URL,
        data=urllib.parse.urlencode(form).encode("ascii"),
        headers={"Content-Type": "application/x-www-form-urlencoded"},
        method="POST",
    )
    try:
        with open_verified_url(
            request,
            timeout=30,
            policy=GOOGLE_OAUTH_POLICY,
        ) as response:
            token = strict_json_loads(response.read(1024 * 1024).decode("utf-8"))
    except (urllib.error.URLError, urllib.error.HTTPError, TimeoutError) as exc:
        raise AuthenticationError("Drive OAuth token exchange failed") from exc
    refresh_token = token.get("refresh_token") if isinstance(token, Mapping) else None
    if not isinstance(refresh_token, str) or not refresh_token:
        raise AuthenticationError("Google did not return a refresh token")
    secret_payload = {
        "refresh_token": refresh_token,
        "client_secret": client_secret or None,
    }
    host = str(store_config["credential_host"])
    credential_store(
        host,
        "oauth",
        json.dumps(secret_payload, separators=(",", ":"), ensure_ascii=True),
    )
    profile = _provider_profile(config)
    stores = profile.get("object_stores")
    if not isinstance(stores, list):
        raise ConfigurationError("active object-store profile is invalid")
    active_store = [
        store
        for store in stores
        if isinstance(store, Mapping)
        and store.get("store_id") == store_config.get("store_id")
    ]
    if len(active_store) != 1:
        raise ConfigurationError("active object store is missing")
    adapter_ref = active_store[0].get("adapter_config_ref")
    adapter = _adapter_config(config, adapter_ref)
    if not isinstance(adapter, MutableMapping):
        raise ConfigurationError("object-store adapter config is not mutable")
    adapter["oauth_client_id"] = client_id
    _refresh_provider_scope_fingerprints(config)
    config = validate_config(config)
    atomic_write_json(data_dir / "config.json", config)
    del refresh_token, client_secret, secret_payload
    adapter = GoogleDriveAdapter(
        config,
        store_id=str(store_config["store_id"]),
    )
    adapter.assert_private()
    return {
        "schema_version": "memory-vault-sync-auth/v1",
        "service": "google-drive",
        "stored_in_os_credential_helper": True,
        "owner_only_root_verified": True,
    }


def bind_command(
    args: argparse.Namespace,
    engine: SyncEngine,
) -> Mapping[str, Any]:
    workspace = Path(args.workspace).expanduser().resolve(strict=True)
    assert_plain_path(workspace, require_file=False)
    if not any(
        _path_is_within(workspace, Path(root).resolve())
        for root in engine.config["privacy"]["allowed_roots"]
    ):
        raise IdentityError("workspace is not inside a configured allowed root")
    task_id = validate_identifier(args.task_id, "task_id")
    binding_id = validate_identifier(args.binding_id, "binding_id")
    lineage_id = validate_identifier(
        args.lineage_id or f"lineage-{uuid.uuid4().hex}",
        "workspace_lineage_id",
    )
    shared_workspace = bool(getattr(args, "shared_workspace", False))
    identity_path = workspace / (
        ".vault_identities.json"
        if shared_workspace
        else ".vault_identity.yaml"
    )
    placeholder = PortableIdentity(
        path=identity_path,
        workspace_root=workspace,
        binding_id=binding_id,
        task_id=task_id,
        lineage_id=lineage_id,
        base={},
    )
    with FileLock(engine.lock_path):
        engine.git.ensure()
        remote = load_remote_task(engine.git, placeholder)
    manifest_bytes = engine.git.show_bytes(remote.manifest_path)
    identity = {
        "schema_version": "portable-workspace-identity/v1",
        "vault_id": VAULT_ID,
        "binding_id": binding_id,
        "semantic_task_id": task_id,
        "workspace_lineage_id": lineage_id,
        "binding_state": "confirmed",
        "base": {
            "snapshot_id": remote.current["snapshot_id"],
            "manifest_sha256": sha256_bytes(manifest_bytes),
            "current_blob_sha": remote.current_blob_sha,
            "transaction_id": remote.current["published_transaction_id"],
        },
    }
    single_marker = workspace / ".vault_identity.yaml"
    set_marker = workspace / ".vault_identities.json"
    if shared_workspace:
        if single_marker.exists():
            raise IdentityError(
                "workspace already has a single-task portable identity"
            )
        identities: list[Mapping[str, Any]] = []
        if set_marker.exists():
            assert_plain_path(set_marker, require_file=True)
            existing = load_json(set_marker)
            if (
                not isinstance(existing, Mapping)
                or set(existing) != {"schema_version", "vault_id", "identities"}
                or existing.get("schema_version") != "portable-workspace-set/v1"
                or existing.get("vault_id") != VAULT_ID
                or not isinstance(existing.get("identities"), list)
            ):
                raise IdentityError("workspace has an invalid portable identity set")
            for raw_identity in existing["identities"]:
                if not isinstance(raw_identity, Mapping):
                    raise IdentityError(
                        "workspace has an invalid portable identity set"
                    )
                current = _parse_identity_value(raw_identity, set_marker)
                if current.task_id == task_id and (
                    current.binding_id != binding_id
                    or current.lineage_id != lineage_id
                ):
                    raise IdentityError(
                        "workspace already has a different identity for this task"
                    )
                if current.task_id != task_id:
                    identities.append(raw_identity)
        identities.append(identity)
        identities.sort(key=lambda item: str(item["semantic_task_id"]))
        atomic_write_json(
            set_marker,
            {
                "schema_version": "portable-workspace-set/v1",
                "vault_id": VAULT_ID,
                "identities": identities,
            },
        )
    else:
        if set_marker.exists():
            raise IdentityError(
                "workspace already has a shared portable identity set"
            )
        if single_marker.exists():
            current = parse_identity(single_marker)
            if (
                current.task_id != task_id
                or current.binding_id != binding_id
                or current.lineage_id != lineage_id
            ):
                raise IdentityError(
                    "workspace already has a different portable identity"
                )
        atomic_write_bytes(single_marker, pretty_json_bytes(identity), mode=0o644)
    return {
        "schema_version": "memory-vault-sync-binding/v1",
        "task_id": task_id,
        "binding_id": binding_id,
        "workspace_lineage_id": lineage_id,
        "base_snapshot_id": remote.current["snapshot_id"],
        "portable_identity_written": True,
        "shared_workspace": shared_workspace,
    }


def _routing_candidate_rows(
    catalog: Mapping[str, RemoteTaskState],
) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for task_id, remote in sorted(catalog.items()):
        remaining_work = remote.manifest.get("remaining_work")
        open_questions = remote.manifest.get("open_questions")
        rows.append(
            {
                "task_id": task_id,
                "display_title": str(
                    remote.task.get("display_title") or task_id
                )[:300],
                "purpose": str(remote.task.get("purpose") or "")[:600],
                "generation": int(remote.current["generation"]),
                "snapshot_id": str(remote.current["snapshot_id"]),
                "continuation_readiness": str(
                    remote.current.get("continuation_readiness") or "partial"
                ),
                "remaining_work": [
                    str(item)[:400]
                    for item in (
                        remaining_work
                        if isinstance(remaining_work, list)
                        else []
                    )[:5]
                    if isinstance(item, str)
                ],
                "open_questions": [
                    str(item)[:400]
                    for item in (
                        open_questions
                        if isinstance(open_questions, list)
                        else []
                    )[:5]
                    if isinstance(item, str)
                ],
            }
        )
    return rows


def routing_candidates_command(
    args: argparse.Namespace,
    engine: SyncEngine,
) -> Mapping[str, Any]:
    request_id = validate_identifier(args.request_id, "routing_request_id")
    with FileLock(engine.lock_path):
        _path, request, catalog = engine._verified_routing_request(request_id)
    return {
        "schema_version": "memory-vault-routing-candidates/v1",
        "request_id": request_id,
        "routing_state": request["state"],
        "remote_commit_sha": request["remote_commit_sha"],
        "candidates": _routing_candidate_rows(catalog),
        "automatic_policy": {
            "automatic_binding_enabled": False,
            "disabled_reason": (
                "legacy scorer did not prove full conversation and artifact "
                "content inspection"
            ),
            "contradictions_allowed": 0,
            "timestamps_are_authoritative": False,
            "required_evidence_groups": [
                "actual_local_conversation",
                "verified_remote_conversation_and_state",
                "bidirectional_declared_artifact_content_when_available",
                "lineage_and_negative_constraints",
            ],
            "first_action": "show_numbered_lightweight_preview_and_ask_user",
            "deep_validation_scope": (
                "after_user_selection;selected_candidate_first;"
                "unselected_candidates_may_remain_uncertain"
            ),
            "fallback_action": "ask_user_once",
        },
    }


class _ArtifactExtractionUnavailable(Exception):
    """A non-fatal format/coverage result for routing evidence."""

    def __init__(self, reason: str):
        super().__init__(reason)
        self.reason = reason


def _stable_file_observations_match(
    left: os.stat_result,
    right: os.stat_result,
    *,
    cross_interface: bool = False,
) -> bool:
    """Compare stable observations without conflating path and handle stat ABIs."""

    if stat.S_IFMT(left.st_mode) != stat.S_IFMT(right.st_mode):
        return False
    fields = ["st_size"]
    if not cross_interface:
        fields.extend(("st_mtime_ns", "st_ctime_ns"))
    for field in fields:
        if getattr(left, field, None) != getattr(right, field, None):
            return False
    # Windows pathname stat and handle fstat can expose different timestamp
    # and identity representations. Across those APIs, timestamps are not
    # compared. Zero identity/link fields mean unavailable, never "same".
    for field in ("st_dev", "st_ino", "st_nlink"):
        left_value = int(getattr(left, field, 0) or 0)
        right_value = int(getattr(right, field, 0) or 0)
        if cross_interface:
            if left_value and right_value and left_value != right_value:
                return False
        elif left_value != right_value:
            return False
    return True


def _routing_artifact_anchor(
    object_sha256: str,
    extractor_profile: str,
    locator: str,
    text_sha256: str,
) -> str:
    validate_sha256(object_sha256, "artifact object sha256")
    validate_sha256(text_sha256, "artifact text sha256")
    return validate_identifier(
        "anc-"
        + sha256_bytes(
            b"memory-vault-artifact-anchor-v1\0"
            + canonical_json_bytes(
                {
                    "object_sha256": object_sha256,
                    "extractor_profile": extractor_profile,
                    "locator": locator,
                    "text_sha256": text_sha256,
                }
            )
        )[:32],
        "artifact anchor_id",
    )


def _bounded_artifact_blocks(
    raw_blocks: Iterable[tuple[str, str, str]],
    *,
    object_sha256: str,
    extractor_profile: str,
) -> tuple[list[dict[str, Any]], str]:
    """Normalize and byte-bound extracted text while retaining exact locators."""

    blocks: list[dict[str, Any]] = []
    total = 0
    coverage = "full"
    for kind, locator, raw_text in raw_blocks:
        text = unicodedata.normalize(
            "NFC",
            str(raw_text).replace("\r\n", "\n").replace("\r", "\n"),
        ).strip()
        if not text:
            continue
        encoded = text.encode("utf-8")
        chunks: list[bytes] = []
        while encoded:
            if len(encoded) <= MAX_ROUTING_ARTIFACT_BLOCK_BYTES:
                chunks.append(encoded)
                break
            boundary = MAX_ROUTING_ARTIFACT_BLOCK_BYTES
            while boundary > 0 and (encoded[boundary] & 0xC0) == 0x80:
                boundary -= 1
            chunk = encoded[:boundary]
            newline = chunk.rfind(b"\n")
            if newline >= max(1, boundary // 2):
                boundary = newline + 1
                chunk = encoded[:boundary]
            chunks.append(chunk)
            encoded = encoded[boundary:]
        for part_index, chunk in enumerate(chunks):
            if (
                len(blocks) >= MAX_ROUTING_ARTIFACT_BLOCKS
                or total + len(chunk) > MAX_ROUTING_ARTIFACT_TEXT_BYTES
            ):
                coverage = "bounded"
                return blocks, coverage
            part_text = chunk.decode("utf-8").strip()
            if not part_text:
                continue
            _scan_text_content(
                part_text,
                "routing artifact extracted text",
                reject_absolute_paths=False,
            )
            part_locator = (
                locator
                if len(chunks) == 1
                else f"{locator}#part-{part_index + 1:04d}"
            )
            if len(part_locator.encode("utf-8")) > 1000:
                raise _ArtifactExtractionUnavailable("invalid_locator")
            text_sha = sha256_bytes(part_text.encode("utf-8"))
            blocks.append(
                {
                    "anchor_id": _routing_artifact_anchor(
                        object_sha256,
                        extractor_profile,
                        part_locator,
                        text_sha,
                    ),
                    "kind": str(kind)[:64],
                    "locator": part_locator,
                    "text": part_text,
                    "text_sha256": text_sha,
                }
            )
            total += len(part_text.encode("utf-8"))
    return blocks, coverage


def _read_routing_artifact_bytes(path: Path) -> bytes:
    assert_plain_path(path, require_file=True)
    before = path.stat()
    if (
        not stat.S_ISREG(before.st_mode)
        or before.st_size < 1
        or before.st_size > MAX_ROUTING_ARTIFACT_BYTES
    ):
        raise _ArtifactExtractionUnavailable("file_size_out_of_scope")
    with path.open("rb", buffering=0) as stream:
        opened = os.fstat(stream.fileno())
        if not _stable_file_observations_match(
            before,
            opened,
            cross_interface=True,
        ):
            raise BusyError("routing artifact changed before extraction")
        raw = stream.read(MAX_ROUTING_ARTIFACT_BYTES + 1)
        opened_after = os.fstat(stream.fileno())
    after = path.stat()
    if (
        not _stable_file_observations_match(opened, opened_after)
        or not _stable_file_observations_match(before, after)
    ):
        raise BusyError("routing artifact changed during extraction")
    if len(raw) != before.st_size:
        raise BusyError("routing artifact size changed during extraction")
    return raw


def _safe_ooxml_members(path: Path) -> tuple[zipfile.ZipFile, dict[str, zipfile.ZipInfo]]:
    suffix = path.suffix.lower()
    if suffix in {".docm", ".dotm", ".pptm", ".potm", ".ppsm", ".xlsm", ".xltm"}:
        raise _ArtifactExtractionUnavailable("macro_enabled_office")
    try:
        archive = zipfile.ZipFile(path)
    except (
        OSError,
        zipfile.BadZipFile,
        zipfile.LargeZipFile,
    ) as exc:
        raise _ArtifactExtractionUnavailable("invalid_ooxml_container") from exc
    members = archive.infolist()
    if len(members) > MAX_ROUTING_ZIP_ENTRIES:
        archive.close()
        raise _ArtifactExtractionUnavailable("zip_entry_limit")
    index: dict[str, zipfile.ZipInfo] = {}
    declared_total = 0
    for member in members:
        name = unicodedata.normalize("NFC", member.filename)
        pure = PurePosixPath(name)
        unix_mode = (member.external_attr >> 16) & 0xFFFF
        if (
            not name
            or name.startswith("/")
            or "\\" in name
            or any(part in {"", ".", ".."} for part in pure.parts)
            or stat.S_ISLNK(unix_mode)
        ):
            archive.close()
            raise _ArtifactExtractionUnavailable("unsafe_zip_member")
        if member.flag_bits & 0x1:
            archive.close()
            raise _ArtifactExtractionUnavailable("encrypted")
        if member.is_dir():
            continue
        if member.file_size > MAX_ROUTING_ZIP_MEMBER_BYTES:
            archive.close()
            raise _ArtifactExtractionUnavailable("zip_member_limit")
        declared_total += max(int(member.file_size), 0)
        if declared_total > MAX_ROUTING_ZIP_TOTAL_BYTES:
            archive.close()
            raise _ArtifactExtractionUnavailable("zip_total_limit")
        if (
            member.file_size > 1024 * 1024
            and member.compress_size > 0
            and member.file_size
            > member.compress_size * MAX_ROUTING_ZIP_RATIO
        ):
            archive.close()
            raise _ArtifactExtractionUnavailable("zip_ratio_limit")
        lowered = name.lower()
        if lowered.endswith("vbaproject.bin") or "/embeddings/" in lowered:
            archive.close()
            raise _ArtifactExtractionUnavailable(
                "active_or_embedded_office_content"
            )
        index[name] = member

    for name, member in index.items():
        if not name.lower().endswith(".rels"):
            continue
        try:
            raw = archive.read(member)
        except (RuntimeError, OSError, zipfile.BadZipFile) as exc:
            archive.close()
            raise _ArtifactExtractionUnavailable("invalid_ooxml_relationships") from exc
        if b"<!DOCTYPE" in raw.upper() or b"<!ENTITY" in raw.upper():
            archive.close()
            raise _ArtifactExtractionUnavailable("unsafe_xml")
        try:
            root = ET.fromstring(raw)
        except ET.ParseError as exc:
            archive.close()
            raise _ArtifactExtractionUnavailable("invalid_ooxml_relationships") from exc
        for relation in root.iter():
            if relation.attrib.get("TargetMode", "").lower() == "external":
                relationship_type = str(relation.attrib.get("Type") or "")
                # A normal document hyperlink is inert text metadata here.  We
                # neither resolve nor request its target. External templates,
                # images, OLE objects, and other active relationships remain
                # unavailable because they can affect rendered meaning.
                if relationship_type.rstrip("/").endswith("/hyperlink"):
                    continue
                archive.close()
                raise _ArtifactExtractionUnavailable(
                    "external_office_relationship"
                )
    return archive, index


def _read_safe_xml(
    archive: zipfile.ZipFile,
    member: zipfile.ZipInfo,
) -> ET.Element:
    try:
        raw = archive.read(member)
    except (RuntimeError, OSError, zipfile.BadZipFile) as exc:
        raise _ArtifactExtractionUnavailable("ooxml_member_read_failed") from exc
    if (
        len(raw) != member.file_size
        or b"<!DOCTYPE" in raw.upper()
        or b"<!ENTITY" in raw.upper()
    ):
        raise _ArtifactExtractionUnavailable("unsafe_xml")
    try:
        return ET.fromstring(raw)
    except ET.ParseError as exc:
        raise _ArtifactExtractionUnavailable("invalid_ooxml_xml") from exc


def _xml_local_name(tag: str) -> str:
    return tag.rsplit("}", 1)[-1]


def _extract_docx_blocks(
    archive: zipfile.ZipFile,
    index: Mapping[str, zipfile.ZipInfo],
) -> Iterable[tuple[str, str, str]]:
    paths = [
        name
        for name in index
        if (
            name == "word/document.xml"
            or re.fullmatch(
                r"word/(?:header|footer|footnotes|endnotes)\d*\.xml",
                name,
            )
        )
    ]
    if "word/document.xml" not in paths:
        raise _ArtifactExtractionUnavailable("missing_ooxml_document")
    for name in sorted(paths, key=lambda item: (item != "word/document.xml", item)):
        root = _read_safe_xml(archive, index[name])
        paragraph_number = 0
        for element in root.iter():
            if _xml_local_name(element.tag) != "p":
                continue
            text = "".join(
                node.text or ""
                for node in element.iter()
                if _xml_local_name(node.tag) in {"t", "tab", "br"}
            )
            if text.strip():
                paragraph_number += 1
                yield (
                    "paragraph",
                    f"{name}#paragraph-{paragraph_number:06d}",
                    text,
                )


def _extract_pptx_blocks(
    archive: zipfile.ZipFile,
    index: Mapping[str, zipfile.ZipInfo],
) -> Iterable[tuple[str, str, str]]:
    slides = sorted(
        (
            name
            for name in index
            if re.fullmatch(r"ppt/slides/slide\d+\.xml", name)
        ),
        key=lambda name: int(re.search(r"(\d+)", Path(name).stem).group(1)),
    )
    if not slides:
        raise _ArtifactExtractionUnavailable("missing_ooxml_slides")
    for number, name in enumerate(slides, 1):
        root = _read_safe_xml(archive, index[name])
        texts = [
            element.text or ""
            for element in root.iter()
            if _xml_local_name(element.tag) == "t" and (element.text or "").strip()
        ]
        if texts:
            yield ("slide", f"slide-{number:06d}", "\n".join(texts))


def _xlsx_shared_strings(
    archive: zipfile.ZipFile,
    index: Mapping[str, zipfile.ZipInfo],
) -> list[str]:
    member = index.get("xl/sharedStrings.xml")
    if member is None:
        return []
    root = _read_safe_xml(archive, member)
    result: list[str] = []
    for item in root.iter():
        if _xml_local_name(item.tag) != "si":
            continue
        result.append(
            "".join(
                node.text or ""
                for node in item.iter()
                if _xml_local_name(node.tag) == "t"
            )
        )
    return result


def _extract_xlsx_blocks(
    archive: zipfile.ZipFile,
    index: Mapping[str, zipfile.ZipInfo],
) -> Iterable[tuple[str, str, str]]:
    sheets = sorted(
        (
            name
            for name in index
            if re.fullmatch(r"xl/worksheets/sheet\d+\.xml", name)
        ),
        key=lambda name: int(re.search(r"(\d+)", Path(name).stem).group(1)),
    )
    if not sheets:
        raise _ArtifactExtractionUnavailable("missing_ooxml_worksheets")
    shared = _xlsx_shared_strings(archive, index)
    for sheet_number, name in enumerate(sheets, 1):
        root = _read_safe_xml(archive, index[name])
        for cell in root.iter():
            if _xml_local_name(cell.tag) != "c":
                continue
            reference = cell.attrib.get("r") or "unknown"
            cell_type = cell.attrib.get("t")
            formula = ""
            value = ""
            inline: list[str] = []
            for child in cell.iter():
                local = _xml_local_name(child.tag)
                if local == "f":
                    formula = child.text or ""
                elif local == "v":
                    value = child.text or ""
                elif local == "t":
                    inline.append(child.text or "")
            if cell_type == "s" and value:
                try:
                    value = shared[int(value)]
                except (ValueError, IndexError):
                    raise _ArtifactExtractionUnavailable(
                        "invalid_xlsx_shared_string"
                    )
            elif cell_type == "inlineStr":
                value = "".join(inline)
            rendered = value
            if formula:
                rendered = f"formula={formula}\nvalue={value}"
            if rendered.strip():
                yield (
                    "cell",
                    f"sheet-{sheet_number:06d}!{reference}",
                    rendered,
                )


def _json_blocks(value: Any) -> Iterable[tuple[str, str, str]]:
    if isinstance(value, Mapping):
        for key in sorted(value, key=lambda item: str(item)):
            locator = "$." + str(key).replace("~", "~0").replace("/", "~1")
            yield (
                "json_value",
                locator,
                json.dumps(
                    value[key],
                    ensure_ascii=False,
                    sort_keys=True,
                    separators=(",", ":"),
                ),
            )
    elif isinstance(value, list):
        for index, item in enumerate(value):
            yield (
                "json_value",
                f"$[{index}]",
                json.dumps(
                    item,
                    ensure_ascii=False,
                    sort_keys=True,
                    separators=(",", ":"),
                ),
            )
    else:
        yield (
            "json_value",
            "$",
            json.dumps(value, ensure_ascii=False, separators=(",", ":")),
        )


def _extract_routing_artifact(
    path: Path,
    *,
    object_sha256: str,
    mime_type: str,
) -> tuple[str, str, list[dict[str, Any]], str | None]:
    """Return profile, coverage, blocks, and an unavailable reason."""

    suffix = path.suffix.lower()
    if suffix in {
        ".pdf",
        ".png",
        ".jpg",
        ".jpeg",
        ".gif",
        ".webp",
        ".tif",
        ".tiff",
        ".bmp",
        ".heic",
        ".doc",
        ".ppt",
        ".xls",
    }:
        return "unavailable/v1", "failed", [], "unsupported_format"
    try:
        if suffix in {".txt", ".md", ".rst"} or (
            mime_type.startswith("text/")
            and suffix not in {".csv", ".tsv", ".json"}
        ):
            raw = _read_routing_artifact_bytes(path)
            if raw.startswith((codecs.BOM_UTF16_LE, codecs.BOM_UTF16_BE)):
                raise _ArtifactExtractionUnavailable("unsupported_text_encoding")
            text = raw.decode("utf-8-sig")
            profile = "plain-text-utf8/v1"
            raw_blocks = (
                (
                    "line_group",
                    f"lines-{start + 1:06d}-{min(start + 50, len(lines)):06d}",
                    "\n".join(lines[start : start + 50]),
                )
                for lines in [text.splitlines()]
                for start in range(0, len(lines), 50)
            )
        elif suffix in {".csv", ".tsv"}:
            raw = _read_routing_artifact_bytes(path)
            if raw.startswith((codecs.BOM_UTF16_LE, codecs.BOM_UTF16_BE)):
                raise _ArtifactExtractionUnavailable("unsupported_text_encoding")
            text = raw.decode("utf-8-sig")
            profile = "delimited-text-utf8/v1"
            delimiter = "\t" if suffix == ".tsv" else ","
            rows = csv.reader(io.StringIO(text), delimiter=delimiter)
            raw_blocks = (
                (
                    "row",
                    f"row-{index + 1:06d}",
                    json.dumps(row, ensure_ascii=False, separators=(",", ":")),
                )
                for index, row in enumerate(rows)
            )
        elif suffix == ".json" or mime_type == "application/json":
            raw = _read_routing_artifact_bytes(path)
            if raw.startswith((codecs.BOM_UTF16_LE, codecs.BOM_UTF16_BE)):
                raise _ArtifactExtractionUnavailable("unsupported_text_encoding")
            try:
                parsed = strict_json_loads(raw.decode("utf-8-sig"))
            except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
                raise _ArtifactExtractionUnavailable("invalid_json") from exc
            profile = "json-structure/v1"
            raw_blocks = _json_blocks(parsed)
        elif suffix in {".docx", ".pptx", ".xlsx"}:
            archive, index = _safe_ooxml_members(path)
            with archive:
                if suffix == ".docx":
                    profile = "ooxml-docx-text/v1"
                    extracted = list(_extract_docx_blocks(archive, index))
                elif suffix == ".pptx":
                    profile = "ooxml-pptx-text/v1"
                    extracted = list(_extract_pptx_blocks(archive, index))
                else:
                    profile = "ooxml-xlsx-cells/v1"
                    extracted = list(_extract_xlsx_blocks(archive, index))
            raw_blocks = extracted
        else:
            return "unavailable/v1", "failed", [], "unsupported_format"
        blocks, coverage = _bounded_artifact_blocks(
            raw_blocks,
            object_sha256=object_sha256,
            extractor_profile=profile,
        )
        if not blocks:
            return profile, "failed", [], "no_extractable_text"
        return profile, coverage, blocks, None
    except UnicodeDecodeError:
        return "unavailable/v1", "failed", [], "unsupported_text_encoding"
    except _ArtifactExtractionUnavailable as exc:
        return "unavailable/v1", "failed", [], exc.reason
    except (
        csv.Error,
        ET.ParseError,
        OSError,
        RuntimeError,
        zipfile.BadZipFile,
        zipfile.LargeZipFile,
    ):
        return "unavailable/v1", "failed", [], "extraction_failed"


def _artifact_bundle_digest(value: Mapping[str, Any]) -> str:
    unsigned = {
        key: child
        for key, child in value.items()
        if key not in {"bundle_sha256", "integrity_hmac_sha256"}
    }
    return sha256_bytes(canonical_json_bytes(unsigned))


def _artifact_bundle_hmac(
    data_dir: Path,
    value: Mapping[str, Any],
) -> str:
    device = _device_state(data_dir)
    unsigned = {
        key: child
        for key, child in value.items()
        if key != "integrity_hmac_sha256"
    }
    return hmac.new(
        str(device["device_secret"]).encode("ascii"),
        b"memory-vault-artifact-extraction-v1\0"
        + canonical_json_bytes(unsigned),
        hashlib.sha256,
    ).hexdigest()


def _write_artifact_extraction_bundle(
    engine: SyncEngine,
    *,
    request: Mapping[str, Any],
    source_kind: str,
    source_path: Path | None,
    task_id: str | None,
    artifact_id: str | None,
    role: str,
    mime_type: str,
    object_sha256: str,
    object_size: int,
    extractor_profile: str,
    coverage: str,
    blocks: Sequence[Mapping[str, Any]],
    unavailable_reason: str | None,
) -> Mapping[str, Any]:
    scope = {
        "request_id": request["request_id"],
        "review_nonce": request["review_nonce"],
        "remote_commit_sha": request["remote_commit_sha"],
        "source_kind": source_kind,
        "task_id": task_id,
        "artifact_id": artifact_id,
        "path_fingerprint": (
            sha256_bytes(str(source_path).encode("utf-8"))
            if source_path is not None
            else None
        ),
        "role_sha256": sha256_bytes(role.encode("utf-8")),
        "object_sha256": object_sha256,
        "object_size": object_size,
        "extractor_profile": extractor_profile,
    }
    receipt_id = validate_identifier(
        "artx-"
        + sha256_bytes(
            b"memory-vault-artifact-extraction-receipt-v1\0"
            + canonical_json_bytes(scope)
        )[:32],
        "artifact_receipt_id",
    )
    value: dict[str, Any] = {
        "schema_version": ARTIFACT_EXTRACTION_SCHEMA,
        "receipt_id": receipt_id,
        **scope,
        # This path is private device state. It is required to prove that the
        # explicit local file did not change between review and confirmation.
        "source_path": str(source_path) if source_path is not None else None,
        "mime_type": mime_type,
        "status": (
            "available"
            if unavailable_reason is None and coverage in {"full", "bounded"}
            else "unavailable"
        ),
        "coverage": coverage,
        "unavailable_reason": unavailable_reason,
        "blocks": [dict(block) for block in blocks],
        "created_at": utc_now(),
    }
    value["bundle_sha256"] = _artifact_bundle_digest(value)
    value["integrity_hmac_sha256"] = _artifact_bundle_hmac(
        engine.data_dir,
        value,
    )
    atomic_write_json(
        _artifact_extraction_receipt_path(
            engine.data_dir,
            str(request["request_id"]),
            receipt_id,
        ),
        value,
    )
    return value


def _public_artifact_extraction_bundle(
    value: Mapping[str, Any],
) -> Mapping[str, Any]:
    return {
        key: child
        for key, child in value.items()
        if key not in {"source_path", "integrity_hmac_sha256"}
    }


def _load_artifact_extraction_bundle(
    data_dir: Path,
    request: Mapping[str, Any],
    receipt_id: str,
    *,
    expected_source_kind: str | None = None,
    expected_task_id: str | None = None,
) -> tuple[Mapping[str, Any], str]:
    receipt = validate_identifier(receipt_id, "artifact_receipt_id")
    path = _artifact_extraction_receipt_path(
        data_dir,
        str(request["request_id"]),
        receipt,
    )
    if not path.exists():
        raise IdentityError("artifact extraction receipt is missing")
    value = load_json(path)
    fields = {
        "schema_version",
        "receipt_id",
        "request_id",
        "review_nonce",
        "remote_commit_sha",
        "source_kind",
        "task_id",
        "artifact_id",
        "path_fingerprint",
        "role_sha256",
        "object_sha256",
        "object_size",
        "extractor_profile",
        "source_path",
        "mime_type",
        "status",
        "coverage",
        "unavailable_reason",
        "blocks",
        "created_at",
        "bundle_sha256",
        "integrity_hmac_sha256",
    }
    if not isinstance(value, Mapping):
        raise IdentityError("artifact extraction receipt is invalid")
    _require_keys(
        value,
        required=fields,
        allowed=fields,
        label="artifact extraction receipt",
    )
    if (
        value.get("schema_version") != ARTIFACT_EXTRACTION_SCHEMA
        or value.get("receipt_id") != receipt
        or value.get("request_id") != request.get("request_id")
        or value.get("review_nonce") != request.get("review_nonce")
        or value.get("remote_commit_sha") != request.get("remote_commit_sha")
        or (
            expected_source_kind is not None
            and value.get("source_kind") != expected_source_kind
        )
        or (
            expected_task_id is not None
            and value.get("task_id") != expected_task_id
        )
    ):
        raise IdentityError(
            "artifact extraction receipt belongs to another routing scope"
        )
    if value.get("source_kind") not in {"local", "remote"}:
        raise IdentityError("artifact extraction source kind is invalid")
    for key in (
        "role_sha256",
        "object_sha256",
        "bundle_sha256",
        "integrity_hmac_sha256",
    ):
        validate_sha256(value.get(key), f"artifact extraction {key}")
    if _artifact_bundle_digest(value) != value.get("bundle_sha256"):
        raise IdentityError("artifact extraction receipt content changed")
    if not hmac.compare_digest(
        _artifact_bundle_hmac(data_dir, value),
        str(value.get("integrity_hmac_sha256")),
    ):
        raise IdentityError("artifact extraction receipt signature changed")
    size = value.get("object_size")
    if (
        not isinstance(size, int)
        or isinstance(size, bool)
        or size < 1
        or size > MAX_LOCAL_MIGRATION_BYTES
    ):
        raise IdentityError("artifact extraction object size is invalid")
    status = value.get("status")
    coverage = value.get("coverage")
    blocks = value.get("blocks")
    if (
        status not in {"available", "unavailable"}
        or coverage not in {"full", "bounded", "failed"}
        or not isinstance(blocks, list)
        or len(blocks) > MAX_ROUTING_ARTIFACT_BLOCKS
    ):
        raise IdentityError("artifact extraction result is invalid")
    if status == "available" and (coverage == "failed" or not blocks):
        raise IdentityError("available artifact extraction has no content")
    if status == "unavailable" and (
        coverage != "failed"
        or blocks
        or not isinstance(value.get("unavailable_reason"), str)
    ):
        raise IdentityError("unavailable artifact extraction is malformed")
    anchor_ids: set[str] = set()
    total_text = 0
    for block in blocks:
        if not isinstance(block, Mapping):
            raise IdentityError("artifact extraction block is invalid")
        block_fields = {
            "anchor_id",
            "kind",
            "locator",
            "text",
            "text_sha256",
        }
        _require_keys(
            block,
            required=block_fields,
            allowed=block_fields,
            label="artifact extraction block",
        )
        anchor_id = validate_identifier(
            block.get("anchor_id"),
            "artifact extraction anchor_id",
        )
        if anchor_id in anchor_ids:
            raise IdentityError("artifact extraction anchor is duplicated")
        anchor_ids.add(anchor_id)
        text = _canonical_local_session_text(
            block.get("text"),
            "artifact extraction text",
            maximum_bytes=MAX_ROUTING_ARTIFACT_BLOCK_BYTES,
        ).strip()
        text_sha = validate_sha256(
            block.get("text_sha256"),
            "artifact extraction text_sha256",
        )
        if (
            sha256_bytes(text.encode("utf-8")) != text_sha
            or _routing_artifact_anchor(
                str(value["object_sha256"]),
                str(value["extractor_profile"]),
                str(block["locator"]),
                text_sha,
            )
            != anchor_id
        ):
            raise IdentityError("artifact extraction anchor no longer verifies")
        total_text += len(text.encode("utf-8"))
    if total_text > MAX_ROUTING_ARTIFACT_TEXT_BYTES:
        raise IdentityError("artifact extraction text exceeds the fixed limit")
    if value.get("source_kind") == "local":
        raw_path = value.get("source_path")
        if not isinstance(raw_path, str) or not os.path.isabs(raw_path):
            raise IdentityError("local artifact extraction path is invalid")
        try:
            local_path = Path(raw_path).resolve(strict=True)
        except OSError as exc:
            raise IdentityError(
                "local artifact changed or disappeared after extraction"
            ) from exc
        if value.get("path_fingerprint") != sha256_bytes(
            str(local_path).encode("utf-8")
        ):
            raise IdentityError("local artifact extraction path changed")
        digest, actual_size = stable_hash_file(
            local_path,
            inspect_text=False,
        )
        if (
            digest != value.get("object_sha256")
            or actual_size != value.get("object_size")
        ):
            raise IdentityError("local artifact changed after extraction")
    return value, str(value["bundle_sha256"])


def local_artifact_evidence_command(
    args: argparse.Namespace,
    engine: SyncEngine,
) -> Mapping[str, Any]:
    request_id = validate_identifier(args.request_id, "routing_request_id")
    document = getattr(args, "artifact_document", None)
    if not isinstance(document, Mapping):
        raise IdentityError(
            "local artifact evidence requires private structured input"
        )
    _require_keys(
        document,
        required={"path", "role"},
        allowed={"path", "role"},
        label="local artifact evidence input",
    )
    raw_path = document.get("path")
    if not isinstance(raw_path, str) or not os.path.isabs(raw_path):
        raise PrivacyError(
            "local routing artifact path must be absolute and explicit"
        )
    role = _bounded_private_text(
        document.get("role"),
        "local routing artifact role",
        maximum_bytes=500,
    )
    with FileLock(engine.lock_path):
        _request_path, request, _catalog = engine._verified_routing_request(
            request_id
        )
        if request.get("state") != "pending":
            raise IdentityError("artifact evidence request is not pending")
        workspace = Path(str(request["workspace_root"])).resolve(strict=True)
        path = Path(raw_path).resolve(strict=True)
        if not _path_is_within(path, workspace):
            raise PrivacyError(
                "local routing artifact is outside this exact request workspace"
            )
        if not any(
            _path_is_within(path, Path(root).resolve())
            for root in engine.config["privacy"]["allowed_roots"]
        ):
            raise PrivacyError("local routing artifact is outside an allowed root")
        object_sha, object_size = stable_hash_file(path, inspect_text=False)
        if object_size > MAX_ROUTING_ARTIFACT_BYTES:
            extractor_profile = "unavailable/v1"
            coverage = "failed"
            blocks: list[dict[str, Any]] = []
            unavailable_reason = "file_size_out_of_scope"
        else:
            mime_type = (
                mimetypes.guess_type(path.name)[0]
                or "application/octet-stream"
            )
            (
                extractor_profile,
                coverage,
                blocks,
                unavailable_reason,
            ) = _extract_routing_artifact(
                path,
                object_sha256=object_sha,
                mime_type=mime_type,
            )
            post_sha, post_size = stable_hash_file(path, inspect_text=False)
            if (post_sha, post_size) != (object_sha, object_size):
                raise BusyError("routing artifact changed during extraction")
        mime_type = (
            mimetypes.guess_type(path.name)[0]
            or "application/octet-stream"
        )
        bundle = _write_artifact_extraction_bundle(
            engine,
            request=request,
            source_kind="local",
            source_path=path,
            task_id=None,
            artifact_id=None,
            role=role,
            mime_type=mime_type,
            object_sha256=object_sha,
            object_size=object_size,
            extractor_profile=extractor_profile,
            coverage=coverage,
            blocks=blocks,
            unavailable_reason=unavailable_reason,
        )
    return {
        "schema_version": "memory-vault-artifact-evidence-result/v1",
        "request_id": request_id,
        "source_kind": "local",
        "evidence": _public_artifact_extraction_bundle(bundle),
    }


def remote_artifact_evidence_command(
    args: argparse.Namespace,
    engine: SyncEngine,
) -> Mapping[str, Any]:
    request_id = validate_identifier(args.request_id, "routing_request_id")
    task_id = validate_identifier(args.task_id, "task_id")
    artifact_id = validate_identifier(args.artifact_id, "artifact_id")
    with FileLock(engine.lock_path):
        _request_path, request, catalog = engine._verified_routing_request(
            request_id
        )
        if request.get("state") != "pending":
            raise IdentityError("artifact evidence request is not pending")
        _assert_routing_request_matches_workspace(
            request,
            str(request["workspace_root"]),
            engine.config["privacy"]["allowed_roots"],
        )
        remote = catalog.get(task_id)
        if remote is None or remote.commit_sha != request["remote_commit_sha"]:
            raise IdentityError(
                "remote artifact is outside this verified candidate request"
            )
        artifacts = remote.manifest.get("artifacts")
        if not isinstance(artifacts, list):
            raise VerificationError("candidate artifact manifest is invalid")
        matches = [
            artifact
            for artifact in artifacts
            if isinstance(artifact, Mapping)
            and artifact.get("artifact_id") == artifact_id
        ]
        if len(matches) != 1:
            raise IdentityError(
                "remote artifact is not uniquely declared by the candidate"
            )
        artifact = matches[0]
        _validate_artifact(artifact)
        object_sha = validate_sha256(
            artifact.get("sha256"),
            "remote artifact sha256",
        )
        object_size = int(artifact["size"])
        pinned_current_blob_sha = remote.current_blob_sha
        role = validate_identifier(artifact.get("role"), "artifact role")
        mime_type = str(artifact["mime_type"])
        if object_size > MAX_ROUTING_ARTIFACT_BYTES:
            extractor_profile = "unavailable/v1"
            coverage = "failed"
            blocks = []
            unavailable_reason = "file_size_out_of_scope"
        else:
            with tempfile.TemporaryDirectory(
                prefix="memory-vault-routing-artifact-"
            ) as temporary:
                suffix = Path(str(artifact["display_name"])).suffix
                destination = Path(temporary) / f"artifact{suffix}"
                engine._artifact_store(artifact).download_and_verify(
                    artifact,
                    destination,
                )
                downloaded_sha, downloaded_size = stable_hash_file(
                    destination,
                    inspect_text=False,
                )
                if (
                    downloaded_sha != object_sha
                    or downloaded_size != object_size
                ):
                    raise VerificationError(
                        "downloaded routing artifact failed exact manifest hash"
                    )
                (
                    extractor_profile,
                    coverage,
                    blocks,
                    unavailable_reason,
                ) = _extract_routing_artifact(
                    destination,
                    object_sha256=object_sha,
                    mime_type=mime_type,
                )
                post_sha, post_size = stable_hash_file(
                    destination,
                    inspect_text=False,
                )
                if (post_sha, post_size) != (object_sha, object_size):
                    raise VerificationError(
                        "downloaded routing artifact changed during extraction"
                    )
        _latest_path, latest_request, latest_catalog = (
            engine._verified_routing_request(request_id)
        )
        latest_remote = latest_catalog.get(task_id)
        latest_artifacts = (
            latest_remote.manifest.get("artifacts")
            if latest_remote is not None
            else None
        )
        latest_matches = [
            item
            for item in (latest_artifacts or [])
            if isinstance(item, Mapping)
            and item.get("artifact_id") == artifact_id
        ]
        if (
            latest_request.get("review_nonce") != request.get("review_nonce")
            or latest_request.get("remote_commit_sha")
            != request.get("remote_commit_sha")
            or latest_remote is None
            or latest_remote.current_blob_sha != pinned_current_blob_sha
            or len(latest_matches) != 1
            or canonical_json_bytes(latest_matches[0])
            != canonical_json_bytes(artifact)
        ):
            raise ConflictError(
                "remote artifact evidence changed during read-only extraction"
            )
        bundle = _write_artifact_extraction_bundle(
            engine,
            request=request,
            source_kind="remote",
            source_path=None,
            task_id=task_id,
            artifact_id=artifact_id,
            role=role,
            mime_type=mime_type,
            object_sha256=object_sha,
            object_size=object_size,
            extractor_profile=extractor_profile,
            coverage=coverage,
            blocks=blocks,
            unavailable_reason=unavailable_reason,
        )
    return {
        "schema_version": "memory-vault-artifact-evidence-result/v1",
        "request_id": request_id,
        "source_kind": "remote",
        "task_id": task_id,
        "artifact_id": artifact_id,
        "evidence": _public_artifact_extraction_bundle(bundle),
    }


def routing_candidate_evidence_command(
    args: argparse.Namespace,
    engine: SyncEngine,
) -> Mapping[str, Any]:
    """Return verified content evidence for one candidate, never just a title."""

    request_id = validate_identifier(args.request_id, "routing_request_id")
    task_id = validate_identifier(args.task_id, "task_id")
    with FileLock(engine.lock_path):
        _path, request, catalog = engine._verified_routing_request(request_id)
        remote = catalog.get(task_id)
        if remote is None:
            raise IdentityError("selected task is not an active routing candidate")
        if remote.commit_sha != request["remote_commit_sha"]:
            raise ConflictError(
                "routing evidence is not pinned to one remote commit"
            )

        conversation_documents: list[Mapping[str, Any]] = []
        total_conversation_bytes = 0
        references = remote.manifest.get("conversation_sources")
        if references is not None and not isinstance(references, list):
            raise VerificationError(
                "candidate conversation source references are invalid"
            )
        for reference in (references or [])[-8:]:
            if not isinstance(reference, Mapping):
                raise VerificationError(
                    "candidate conversation source reference is invalid"
                )
            source_id = validate_identifier(
                reference.get("source_id"),
                "source_id",
            )
            revision_id = validate_identifier(
                reference.get("revision_id"),
                "revision_id",
            )
            content_path = validate_repo_path(
                reference.get("content_path"),
                "conversation content_path",
            )
            if (
                content_path
                != f"sources/{source_id}/revisions/{revision_id}.json"
            ):
                raise VerificationError(
                    "candidate conversation source path is inconsistent"
                )
            raw = engine.git.show_bytes(content_path)
            if sha256_bytes(raw) != reference.get("content_sha256"):
                raise VerificationError(
                    "candidate conversation source hash is inconsistent"
                )
            engine.git.assert_immutable_path(content_path, raw)
            total_conversation_bytes += len(raw)
            if total_conversation_bytes > 256 * 1024:
                raise VerificationError(
                    "candidate conversation evidence exceeds the fixed limit"
                )
            try:
                document = strict_json_loads(raw.decode("utf-8"))
            except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
                raise VerificationError(
                    "candidate conversation source is invalid"
                ) from exc
            if not isinstance(document, Mapping):
                raise VerificationError(
                    "candidate conversation source is not an object"
                )
            _validate_conversation_export(document)
            if document.get("source_id") != source_id:
                raise VerificationError(
                    "candidate conversation source identity changed"
                )
            conversation_documents.append(
                {
                    "source_id": source_id,
                    "revision_id": revision_id,
                    "content_path": content_path,
                    "content_sha256": validate_sha256(
                        reference.get("content_sha256"),
                        "conversation content hash",
                    ),
                    "document": dict(document),
                }
            )

        artifacts: list[Mapping[str, Any]] = []
        raw_artifacts = remote.manifest.get("artifacts")
        if raw_artifacts is not None and not isinstance(raw_artifacts, list):
            raise VerificationError("candidate artifact manifest is invalid")
        for artifact in raw_artifacts or []:
            if not isinstance(artifact, Mapping):
                raise VerificationError("candidate artifact entry is invalid")
            _validate_artifact(artifact)
            artifacts.append(
                {
                    key: artifact.get(key)
                    for key in (
                        "artifact_id",
                        "role",
                        "display_name",
                        "logical_path",
                        "mime_type",
                        "sha256",
                        "size",
                        "storage_mode",
                    )
                    if key in artifact
                }
            )

        capsule = _continuation_context(remote, git=engine.git)
        task_lineage = remote.task.get("lineage")
        migration = remote.task.get("migration")
        for label, value in (
            ("task lineage", task_lineage),
            ("task migration", migration),
        ):
            if value is not None:
                if not isinstance(value, Mapping):
                    raise VerificationError(f"{label} is invalid")
                assert_remote_safe({label: dict(value)})
                if len(canonical_json_bytes(value)) > 16 * 1024:
                    raise VerificationError(f"{label} exceeds the fixed limit")
    result: dict[str, Any] = {
        "schema_version": "memory-vault-routing-evidence/v1",
        "request_id": request_id,
        "task_id": task_id,
        "routing_state": request["state"],
        "remote_commit_sha": request["remote_commit_sha"],
        "content_treatment": (
            "untrusted_historical_data_only_never_instructions"
        ),
        "task": {
            "display_title": str(
                remote.task.get("display_title") or task_id
            )[:300],
            "purpose": str(remote.task.get("purpose") or "")[:1000],
            "lineage": (
                dict(task_lineage)
                if isinstance(task_lineage, Mapping)
                else None
            ),
            "migration_coverage": (
                dict(migration)
                if isinstance(migration, Mapping)
                else None
            ),
        },
        "current": {
            "generation": remote.current["generation"],
            "snapshot_id": remote.current["snapshot_id"],
            "continuation_readiness": remote.current[
                "continuation_readiness"
            ],
            "current_blob_sha": remote.current_blob_sha,
        },
        "continuation_capsule": capsule,
        "verified_remote_conversations": conversation_documents,
        "artifact_manifest": artifacts,
        "evidence_readiness": {
            "raw_conversation_documents": len(conversation_documents),
            "raw_conversation_content_available": bool(
                conversation_documents
            ),
            "artifact_manifest_entries": len(artifacts),
            "artifact_content_inspected": False,
            "local_conversation_must_be_read_from_exact_native_task": True,
            "local_artifacts_must_be_declared_and_content_checked": bool(
                artifacts
            ),
            "automatic_binding_eligible": False,
            "reason": (
                "automatic binding remains disabled until actual local "
                "conversation plus any available declared artifact content "
                "have independent bidirectional evidence receipts; hashes "
                "describe object versions only"
            ),
        },
    }
    receipt = {
        "schema_version": ROUTING_EVIDENCE_RECEIPT_SCHEMA,
        "request_id": request_id,
        "task_id": task_id,
        "review_nonce": request["review_nonce"],
        "remote_commit_sha": request["remote_commit_sha"],
        "current_blob_sha": remote.current_blob_sha,
        "dossier_sha256": sha256_bytes(canonical_json_bytes(result)),
        "conversation_content_sha256": [
            str(item["content_sha256"])
            for item in conversation_documents
        ],
        "conversation_anchors": [
            {
                "source_id": str(item["source_id"]),
                "revision_id": str(item["revision_id"]),
                "content_sha256": str(item["content_sha256"]),
                "message_roles": [
                    str(message["role"])
                    for message in item["document"]["messages"]
                ],
            }
            for item in conversation_documents
        ],
        "artifact_sha256": [
            str(item["sha256"])
            for item in artifacts
        ],
        "artifact_descriptors": [
            {
                "artifact_id": str(item["artifact_id"]),
                "role_sha256": sha256_bytes(
                    str(item["role"]).encode("utf-8")
                ),
                "sha256": str(item["sha256"]),
                "size": int(item["size"]),
            }
            for item in artifacts
        ],
        "created_at": utc_now(),
    }
    receipt_sha256 = sha256_bytes(canonical_json_bytes(receipt))
    atomic_write_json(
        _routing_evidence_receipt_path(
            engine.data_dir,
            request_id,
            task_id,
        ),
        receipt,
    )
    result["evidence_receipt_sha256"] = receipt_sha256
    return result


def _load_routing_evidence_receipt(
    data_dir: Path,
    request: Mapping[str, Any],
    remote: RemoteTaskState,
) -> tuple[Mapping[str, Any], str]:
    task_id = validate_identifier(
        remote.current.get("task_id"),
        "routing evidence task_id",
    )
    path = _routing_evidence_receipt_path(
        data_dir,
        str(request["request_id"]),
        task_id,
    )
    if not path.exists():
        raise IdentityError(
            "candidate content evidence has not been inspected"
        )
    value = load_json(path)
    fields = {
        "schema_version",
        "request_id",
        "task_id",
        "review_nonce",
        "remote_commit_sha",
        "current_blob_sha",
        "dossier_sha256",
        "conversation_content_sha256",
        "conversation_anchors",
        "artifact_sha256",
        "artifact_descriptors",
        "created_at",
    }
    if not isinstance(value, Mapping):
        raise IdentityError("routing evidence receipt is invalid")
    _require_keys(
        value,
        required=fields,
        allowed=fields,
        label="routing evidence receipt",
    )
    if (
        value.get("schema_version")
        != ROUTING_EVIDENCE_RECEIPT_SCHEMA
        or value.get("request_id") != request.get("request_id")
        or value.get("task_id") != task_id
        or value.get("review_nonce") != request.get("review_nonce")
        or value.get("remote_commit_sha")
        != request.get("remote_commit_sha")
        or value.get("current_blob_sha") != remote.current_blob_sha
    ):
        raise IdentityError(
            "routing evidence receipt no longer matches the candidate"
        )
    validate_sha256(value.get("dossier_sha256"), "routing dossier hash")
    for key in ("conversation_content_sha256", "artifact_sha256"):
        hashes = value.get(key)
        if not isinstance(hashes, list) or len(hashes) > 1000:
            raise IdentityError("routing evidence receipt hashes are invalid")
        for digest in hashes:
            validate_sha256(digest, "routing evidence content hash")
    anchors = value.get("conversation_anchors")
    if not isinstance(anchors, list) or len(anchors) > 8:
        raise IdentityError("routing conversation anchors are invalid")
    anchor_keys: set[tuple[str, str]] = set()
    for anchor in anchors:
        if not isinstance(anchor, Mapping):
            raise IdentityError("routing conversation anchor is invalid")
        _require_keys(
            anchor,
            required={
                "source_id",
                "revision_id",
                "content_sha256",
                "message_roles",
            },
            allowed={
                "source_id",
                "revision_id",
                "content_sha256",
                "message_roles",
            },
            label="routing conversation anchor",
        )
        source_id = validate_identifier(
            anchor.get("source_id"),
            "routing conversation source_id",
        )
        revision_id = validate_identifier(
            anchor.get("revision_id"),
            "routing conversation revision_id",
        )
        if (source_id, revision_id) in anchor_keys:
            raise IdentityError("routing conversation anchor is duplicated")
        anchor_keys.add((source_id, revision_id))
        validate_sha256(
            anchor.get("content_sha256"),
            "routing conversation content hash",
        )
        roles = anchor.get("message_roles")
        if (
            not isinstance(roles, list)
            or not roles
            or len(roles) > 5000
            or any(role not in {"user", "assistant"} for role in roles)
        ):
            raise IdentityError(
                "routing conversation anchor roles are invalid"
            )
    if [anchor["content_sha256"] for anchor in anchors] != value.get(
        "conversation_content_sha256"
    ):
        raise IdentityError(
            "routing conversation anchors do not match their content hashes"
        )
    descriptors = value.get("artifact_descriptors")
    if not isinstance(descriptors, list) or len(descriptors) > 1000:
        raise IdentityError("routing artifact descriptors are invalid")
    descriptor_ids: set[str] = set()
    for descriptor in descriptors:
        if not isinstance(descriptor, Mapping):
            raise IdentityError("routing artifact descriptor is invalid")
        _require_keys(
            descriptor,
            required={"artifact_id", "role_sha256", "sha256", "size"},
            allowed={"artifact_id", "role_sha256", "sha256", "size"},
            label="routing artifact descriptor",
        )
        artifact_id = validate_identifier(
            descriptor.get("artifact_id"),
            "routing artifact_id",
        )
        if artifact_id in descriptor_ids:
            raise IdentityError("routing artifact descriptor is duplicated")
        descriptor_ids.add(artifact_id)
        validate_sha256(
            descriptor.get("role_sha256"),
            "routing artifact role hash",
        )
        validate_sha256(
            descriptor.get("sha256"),
            "routing artifact hash",
        )
        size = descriptor.get("size")
        if (
            not isinstance(size, int)
            or isinstance(size, bool)
            or size < 0
        ):
            raise IdentityError("routing artifact size is invalid")
    if [descriptor["sha256"] for descriptor in descriptors] != value.get(
        "artifact_sha256"
    ):
        raise IdentityError(
            "routing artifact descriptors do not match their content hashes"
        )
    return value, sha256_bytes(canonical_json_bytes(value))


def _bounded_private_text(
    value: Any,
    label: str,
    *,
    maximum_bytes: int,
) -> str:
    """Validate local-only review text without treating it as remote content."""

    if not isinstance(value, str) or not value.strip() or "\x00" in value:
        raise PrivacyError(f"{label} is invalid")
    if len(value.encode("utf-8")) > maximum_bytes:
        raise PrivacyError(f"{label} exceeds the fixed limit")
    return unicodedata.normalize("NFC", value)


def _canonical_local_session_text(
    value: Any,
    label: str,
    *,
    maximum_bytes: int = 256 * 1024,
) -> str:
    """Validate exact visible session text, changing line endings only."""

    if not isinstance(value, str) or not value or "\x00" in value:
        raise PrivacyError(f"{label} is invalid")
    normalized = value.replace("\r\n", "\n").replace("\r", "\n")
    if len(normalized.encode("utf-8")) > maximum_bytes:
        raise PrivacyError(f"{label} exceeds the fixed limit")
    return normalized


def _bounded_session_log_identifier(value: Any, label: str) -> str:
    if not isinstance(value, str) or not value or "\x00" in value:
        raise IdentityError(f"{label} is invalid")
    if len(value.encode("utf-8")) > 512:
        raise IdentityError(f"{label} exceeds the fixed limit")
    return value


def _codex_sessions_root() -> Path:
    try:
        root = (_codex_home() / "sessions").resolve(strict=True)
    except OSError as exc:
        raise IdentityError(
            "local Codex session evidence is unavailable"
        ) from exc
    assert_plain_path(root, require_file=False)
    return root


def _same_open_file(
    left: os.stat_result,
    right: os.stat_result,
) -> bool:
    for field in ("st_dev", "st_ino"):
        left_value = int(getattr(left, field, 0))
        right_value = int(getattr(right, field, 0))
        if left_value and right_value and left_value != right_value:
            return False
    return True


def _session_log_file_identity_sha256(metadata: os.stat_result) -> str:
    return sha256_bytes(
        canonical_json_bytes(
            {
                "st_dev": int(getattr(metadata, "st_dev", 0)),
                "st_ino": int(getattr(metadata, "st_ino", 0)),
                "file_type": int(stat.S_IFMT(metadata.st_mode)),
            }
        )
    )


def _open_codex_session_log(
    path: Path,
) -> tuple[Any, os.stat_result]:
    assert_plain_path(path, require_file=True)
    named = path.lstat()
    if (
        not stat.S_ISREG(named.st_mode)
        or int(getattr(named, "st_nlink", 1)) != 1
        or named.st_size < 1
        or named.st_size > MAX_CODEX_SESSION_LOG_BYTES
    ):
        raise PrivacyError(
            "local Codex session evidence is not a bounded ordinary file"
        )
    flags = (
        os.O_RDONLY
        | getattr(os, "O_BINARY", 0)
        | getattr(os, "O_NOFOLLOW", 0)
        | getattr(os, "O_NOINHERIT", 0)
    )
    try:
        descriptor = os.open(path, flags)
    except OSError as exc:
        raise IdentityError(
            "local Codex session evidence could not be opened"
        ) from exc
    stream = os.fdopen(descriptor, "rb", buffering=0)
    try:
        opened = os.fstat(stream.fileno())
        if (
            not stat.S_ISREG(opened.st_mode)
            or int(getattr(opened, "st_nlink", 1)) != 1
            or not _same_open_file(named, opened)
        ):
            raise PrivacyError(
                "local Codex session evidence changed before it was opened"
            )
    except Exception:
        stream.close()
        raise
    return stream, opened


def _assert_open_session_log_still_named(
    path: Path,
    opened: os.stat_result,
    *,
    minimum_size: int,
) -> os.stat_result:
    assert_plain_path(path, require_file=True)
    named = path.lstat()
    if (
        not stat.S_ISREG(named.st_mode)
        or int(getattr(named, "st_nlink", 1)) != 1
        or not _same_open_file(opened, named)
        or named.st_size < minimum_size
        or named.st_size > MAX_CODEX_SESSION_LOG_BYTES
    ):
        raise VerificationError(
            "local Codex session evidence changed during verification"
        )
    return named


def _session_log_meta_id(path: Path) -> str:
    stream, opened = _open_codex_session_log(path)
    try:
        raw = stream.readline(MAX_CODEX_SESSION_LOG_LINE_BYTES + 1)
        if (
            not raw
            or len(raw) > MAX_CODEX_SESSION_LOG_LINE_BYTES
            or not raw.endswith(b"\n")
        ):
            raise IdentityError(
                "local Codex session metadata is incomplete or too large"
            )
    finally:
        stream.close()
    _assert_open_session_log_still_named(
        path,
        opened,
        minimum_size=len(raw),
    )
    if raw.startswith(codecs.BOM_UTF8):
        raise PrivacyError("local Codex session log must be UTF-8 without BOM")
    try:
        value = strict_json_loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
        raise IdentityError(
            "local Codex session metadata is invalid"
        ) from exc
    if (
        not isinstance(value, Mapping)
        or value.get("type") != "session_meta"
        or not isinstance(value.get("payload"), Mapping)
    ):
        raise IdentityError("local Codex session metadata is missing")
    return _bounded_session_log_identifier(
        value["payload"].get("id"),
        "local Codex rollout id",
    )


def _locate_codex_session_log(session_id: str) -> tuple[Path, Path]:
    exact_session_id = _bounded_session_log_identifier(
        session_id,
        "native task session id",
    )
    sessions_root = _codex_sessions_root()
    suffix = f"-{exact_session_id}.jsonl"
    matches: list[Path] = []
    for raw_directory, directory_names, file_names in os.walk(
        sessions_root,
        followlinks=False,
    ):
        directory = Path(raw_directory)
        safe_directories: list[str] = []
        for name in directory_names:
            candidate = directory / name
            if not candidate.is_symlink() and not _is_reparse_point(candidate):
                safe_directories.append(name)
        directory_names[:] = safe_directories
        for name in file_names:
            if not name.startswith("rollout-") or not name.endswith(suffix):
                continue
            candidate = directory / name
            assert_plain_path(candidate, require_file=True)
            if not _path_is_within(
                candidate.resolve(strict=True),
                sessions_root,
            ):
                raise PrivacyError(
                    "local Codex session evidence escapes its trusted root"
                )
            matches.append(candidate)
            if len(matches) > 1:
                break
        if len(matches) > 1:
            break
    if len(matches) != 1:
        raise IdentityError(
            "local Codex session evidence is missing or ambiguous"
        )
    path = matches[0]
    if _session_log_meta_id(path) != exact_session_id:
        raise IdentityError(
            "local Codex session evidence belongs to another native task"
        )
    return sessions_root, path


def _response_item_text_matches(
    payload: Mapping[str, Any],
    content_type: str,
    expected_text: str,
) -> bool:
    content = payload.get("content")
    if not isinstance(content, list):
        return False
    texts: list[str] = []
    for item in content:
        if not isinstance(item, Mapping) or item.get("type") != content_type:
            continue
        texts.append(
            _canonical_local_session_text(
                item.get("text"),
                "local Codex visible response text",
            )
        )
    exact_count = sum(text == expected_text for text in texts)
    if exact_count > 1:
        raise IdentityError(
            "local Codex visible message pairing is ambiguous"
        )
    if exact_count == 1:
        return True
    return bool(texts) and "".join(texts) == expected_text


def _session_response_identity(
    payload: Mapping[str, Any],
) -> tuple[str, str]:
    record_id = _bounded_session_log_identifier(
        payload.get("id"),
        "local Codex visible record id",
    )
    metadata = payload.get("internal_chat_message_metadata_passthrough")
    if not isinstance(metadata, Mapping):
        raise IdentityError(
            "local Codex visible message has no exact turn metadata"
        )
    turn_id = _bounded_session_log_identifier(
        metadata.get("turn_id"),
        "local Codex visible turn id",
    )
    return record_id, turn_id


def _session_turn_anchor(turn: Mapping[str, Any]) -> dict[str, Any]:
    record_id = str(turn["record_id"])
    turn_id = str(turn["turn_id"])
    text = str(turn["text"])
    anchor_material = {
        "parser_version": CODEX_SESSION_LOG_PARSER_VERSION,
        "ordinal": int(turn["ordinal"]),
        "record_id": record_id,
        "turn_id": turn_id,
        "role": str(turn["role"]),
        "phase": turn.get("phase"),
        "text_sha256": sha256_bytes(text.encode("utf-8")),
    }
    return {
        "ordinal": int(turn["ordinal"]),
        "anchor_sha256": sha256_bytes(
            b"memory-vault-local-visible-turn-v1\0"
            + canonical_json_bytes(anchor_material)
        ),
        "record_id_sha256": sha256_bytes(record_id.encode("utf-8")),
        "turn_id_sha256": sha256_bytes(turn_id.encode("utf-8")),
        "role": str(turn["role"]),
        "phase": turn.get("phase"),
        "text_sha256": anchor_material["text_sha256"],
    }


def _capture_codex_session_evidence(
    session_id: str,
) -> dict[str, Any]:
    sessions_root, path = _locate_codex_session_log(session_id)
    relative_path = path.relative_to(sessions_root).as_posix()
    stream, opened = _open_codex_session_log(path)
    prefix_bytes = int(opened.st_size)
    prefix_digest = hashlib.sha256()
    turns: list[dict[str, Any]] = []
    pending_user: list[Mapping[str, Any]] = []
    pending_agent: list[dict[str, Any]] = []
    seen_record_ids: set[str] = set()
    total_visible_text_bytes = 0
    remaining = prefix_bytes
    line_number = 0
    try:
        while remaining:
            raw = stream.readline(
                min(MAX_CODEX_SESSION_LOG_LINE_BYTES + 1, remaining)
            )
            if not raw:
                raise VerificationError(
                    "local Codex session log ended before its captured boundary"
                )
            remaining -= len(raw)
            line_number += 1
            prefix_digest.update(raw)
            if (
                len(raw) > MAX_CODEX_SESSION_LOG_LINE_BYTES
                or not raw.endswith(b"\n")
            ):
                raise IdentityError(
                    "local Codex session log contains an incomplete or oversized "
                    "record"
                )
            if line_number == 1 and raw.startswith(codecs.BOM_UTF8):
                raise PrivacyError(
                    "local Codex session log must be UTF-8 without BOM"
                )
            try:
                record = strict_json_loads(raw.decode("utf-8"))
            except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
                raise IdentityError(
                    "local Codex session log contains invalid JSON"
                ) from exc
            if not isinstance(record, Mapping):
                raise IdentityError(
                    "local Codex session log record is invalid"
                )
            payload = record.get("payload")
            if not isinstance(payload, Mapping):
                continue
            if line_number == 1:
                if (
                    record.get("type") != "session_meta"
                    or payload.get("id") != session_id
                ):
                    raise IdentityError(
                        "local Codex session log does not match the exact task"
                    )
                continue
            outer_type = record.get("type")
            payload_type = payload.get("type")
            if (
                outer_type == "response_item"
                and payload_type == "message"
                and payload.get("role") == "user"
            ):
                pending_user.append(payload)
                if len(pending_user) > 64:
                    raise IdentityError(
                        "local Codex user message pairing is ambiguous"
                    )
                continue
            if (
                outer_type == "event_msg"
                and payload_type == "user_message"
            ):
                event_text = _canonical_local_session_text(
                    payload.get("message"),
                    "local Codex visible user message",
                )
                matching = [
                    candidate
                    for candidate in pending_user
                    if _response_item_text_matches(
                        candidate,
                        "input_text",
                        event_text,
                    )
                ]
                if len(matching) != 1:
                    raise IdentityError(
                        "local Codex visible user message has no unique record "
                        "pair"
                    )
                record_id, turn_id = _session_response_identity(matching[0])
                if record_id in seen_record_ids:
                    raise IdentityError(
                        "local Codex visible record id is duplicated"
                    )
                seen_record_ids.add(record_id)
                total_visible_text_bytes += len(event_text.encode("utf-8"))
                turns.append(
                    {
                        "ordinal": len(turns),
                        "record_id": record_id,
                        "turn_id": turn_id,
                        "role": "user",
                        "phase": None,
                        "text": event_text,
                    }
                )
                pending_user.clear()
                continue
            if (
                outer_type == "event_msg"
                and payload_type == "agent_message"
            ):
                event_text = _canonical_local_session_text(
                    payload.get("message"),
                    "local Codex visible assistant message",
                )
                phase = _bounded_session_log_identifier(
                    payload.get("phase"),
                    "local Codex visible assistant phase",
                )
                pending_agent.append({"text": event_text, "phase": phase})
                if len(pending_agent) > 16:
                    raise IdentityError(
                        "local Codex assistant message pairing is ambiguous"
                    )
                continue
            if (
                outer_type == "response_item"
                and payload_type == "message"
                and payload.get("role") == "assistant"
            ):
                response_phase = _bounded_session_log_identifier(
                    payload.get("phase"),
                    "local Codex visible assistant phase",
                )
                matching_agent = [
                    event
                    for event in pending_agent
                    if event["phase"] == response_phase
                    and _response_item_text_matches(
                        payload,
                        "output_text",
                        str(event["text"]),
                    )
                ]
                if not pending_agent:
                    continue
                if len(matching_agent) != 1 or len(pending_agent) != 1:
                    raise IdentityError(
                        "local Codex visible assistant message has no unique "
                        "record pair"
                    )
                record_id, turn_id = _session_response_identity(payload)
                if record_id in seen_record_ids:
                    raise IdentityError(
                        "local Codex visible record id is duplicated"
                    )
                seen_record_ids.add(record_id)
                event = matching_agent[0]
                total_visible_text_bytes += len(
                    str(event["text"]).encode("utf-8")
                )
                turns.append(
                    {
                        "ordinal": len(turns),
                        "record_id": record_id,
                        "turn_id": turn_id,
                        "role": "assistant",
                        "phase": response_phase,
                        "text": event["text"],
                    }
                )
                pending_agent.clear()
        opened_after = os.fstat(stream.fileno())
    finally:
        stream.close()
    if (
        not _same_open_file(opened, opened_after)
        or opened_after.st_size < prefix_bytes
    ):
        raise VerificationError(
            "local Codex session log changed during capture"
        )
    _assert_open_session_log_still_named(
        path,
        opened,
        minimum_size=prefix_bytes,
    )
    if pending_agent:
        raise IdentityError(
            "local Codex assistant message pairing is incomplete"
        )
    if (
        not turns
        or not any(turn["role"] == "user" for turn in turns)
        or len(turns) > 5000
        or total_visible_text_bytes > 512 * 1024
    ):
        raise IdentityError(
            "local Codex visible conversation is missing or exceeds the fixed "
            "review limit"
        )
    anchors = [_session_turn_anchor(turn) for turn in turns]
    return {
        "turns": turns,
        "anchors": anchors,
        "proof": {
            "parser_version": CODEX_SESSION_LOG_PARSER_VERSION,
            "rollout_id_sha256": sha256_bytes(session_id.encode("utf-8")),
            "relative_path_sha256": sha256_bytes(
                relative_path.encode("utf-8")
            ),
            "file_identity_sha256": _session_log_file_identity_sha256(opened),
            "prefix_bytes": prefix_bytes,
            "prefix_sha256": prefix_digest.hexdigest(),
            "transcript_sha256": sha256_bytes(
                canonical_json_bytes(anchors)
            ),
        },
    }


def _verify_codex_session_prefix(
    request: Mapping[str, Any],
    receipt: Mapping[str, Any],
) -> None:
    session_id = _bounded_session_log_identifier(
        request.get("session_id"),
        "native task session id",
    )
    sessions_root, path = _locate_codex_session_log(session_id)
    proof = receipt.get("session_log_proof")
    if not isinstance(proof, Mapping):
        raise IdentityError(
            "local Codex session prefix proof is missing"
        )
    relative_path = path.relative_to(sessions_root).as_posix()
    if proof.get("relative_path_sha256") != sha256_bytes(
        relative_path.encode("utf-8")
    ):
        raise IdentityError(
            "local Codex session evidence moved after review"
        )
    prefix_bytes = proof.get("prefix_bytes")
    if (
        not isinstance(prefix_bytes, int)
        or isinstance(prefix_bytes, bool)
        or prefix_bytes < 1
        or prefix_bytes > MAX_CODEX_SESSION_LOG_BYTES
    ):
        raise IdentityError(
            "local Codex session prefix boundary is invalid"
        )
    stream, opened = _open_codex_session_log(path)
    if proof.get("file_identity_sha256") != (
        _session_log_file_identity_sha256(opened)
    ):
        stream.close()
        raise IdentityError(
            "local Codex session evidence was replaced after review"
        )
    digest = hashlib.sha256()
    remaining = prefix_bytes
    try:
        while remaining:
            chunk = stream.read(min(1024 * 1024, remaining))
            if not chunk:
                raise VerificationError(
                    "local Codex session evidence was truncated after review"
                )
            digest.update(chunk)
            remaining -= len(chunk)
        opened_after = os.fstat(stream.fileno())
    finally:
        stream.close()
    _assert_open_session_log_still_named(
        path,
        opened,
        minimum_size=prefix_bytes,
    )
    if (
        not _same_open_file(opened, opened_after)
        or digest.hexdigest() != proof.get("prefix_sha256")
    ):
        raise VerificationError(
            "local Codex session evidence changed after review"
        )


def _routing_semantic_features(texts: Iterable[str]) -> set[str]:
    """Return bounded, deterministic lexical features for a fail-closed guard."""

    def tokenize(value: str) -> set[str]:
        normalized = unicodedata.normalize("NFKC", value).casefold()
        features = {
            token
            for token in re.findall(r"[a-z][a-z0-9_-]{2,}", normalized)
        }
        for run in re.findall(r"[\u3400-\u4dbf\u4e00-\u9fff]{2,}", normalized):
            for width in (2, 3):
                features.update(
                    run[index : index + width]
                    for index in range(max(0, len(run) - width + 1))
                )
        return features

    generic = tokenize(ROUTING_GENERIC_SEMANTIC_TEXT)
    observed: set[str] = set()
    for text in texts:
        if isinstance(text, str):
            observed.update(tokenize(text))
        if len(observed) > 32768:
            break
    distinctive = observed - generic
    if len(distinctive) > 16384:
        return set(sorted(distinctive)[:16384])
    return distinctive


def _routing_deterministic_content_signal(
    local_texts: Iterable[str],
    remote_texts: Iterable[str],
) -> Mapping[str, Any]:
    """Compare real extracted text without treating hashes as semantics."""

    local = _routing_semantic_features(local_texts)
    remote = _routing_semantic_features(remote_texts)
    overlap = local & remote
    smaller = min(len(local), len(remote))
    containment_bp = (
        len(overlap) * 10000 // smaller if smaller else 0
    )
    union = local | remote
    jaccard_bp = len(overlap) * 10000 // len(union) if union else 0
    positive = bool(
        smaller >= 2
        and (
            (len(overlap) >= 2 and containment_bp >= 500)
            or len(overlap) >= 6
        )
    )
    clearly_unrelated = bool(
        smaller >= 3
        and (
            not overlap
            or (smaller >= 8 and containment_bp < 100)
        )
    )
    return {
        "local_feature_count": len(local),
        "remote_feature_count": len(remote),
        "overlap_count": len(overlap),
        "containment_basis_points": containment_bp,
        "jaccard_basis_points": jaccard_bp,
        "positive": positive,
        "clearly_unrelated": clearly_unrelated,
    }


def _verified_remote_routing_conversation_texts(
    git: GitVault,
    remote: RemoteTaskState,
    receipt: Mapping[str, Any],
) -> list[str]:
    """Re-read the exact Git-pinned remote conversation used by the receipt."""

    references = remote.manifest.get("conversation_sources")
    if not isinstance(references, list):
        raise VerificationError(
            "candidate conversation source references are invalid"
        )
    texts: list[str] = []
    observed_hashes: list[str] = []
    for reference in references[-8:]:
        if not isinstance(reference, Mapping):
            raise VerificationError(
                "candidate conversation source reference is invalid"
            )
        source_id = validate_identifier(
            reference.get("source_id"),
            "routing semantic source_id",
        )
        revision_id = validate_identifier(
            reference.get("revision_id"),
            "routing semantic revision_id",
        )
        content_path = validate_repo_path(
            reference.get("content_path"),
            "routing semantic content_path",
        )
        if (
            content_path
            != f"sources/{source_id}/revisions/{revision_id}.json"
        ):
            raise VerificationError(
                "candidate conversation source path is inconsistent"
            )
        raw = git.show_bytes(content_path)
        digest = sha256_bytes(raw)
        if digest != reference.get("content_sha256"):
            raise VerificationError(
                "candidate conversation source hash is inconsistent"
            )
        try:
            document = strict_json_loads(raw.decode("utf-8"))
        except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
            raise VerificationError(
                "candidate conversation source is invalid"
            ) from exc
        if not isinstance(document, Mapping):
            raise VerificationError(
                "candidate conversation source is not an object"
            )
        _validate_conversation_export(document)
        observed_hashes.append(digest)
        texts.extend(
            str(message["text"])
            for message in document["messages"]
            if isinstance(message, Mapping)
            and isinstance(message.get("text"), str)
        )
    if observed_hashes != receipt.get("conversation_content_sha256"):
        raise IdentityError(
            "deterministic content guard did not receive the exact inspected "
            "remote conversation"
        )
    return texts


def _routing_required_core_artifacts(
    remote: RemoteTaskState,
) -> tuple[set[str], bool]:
    """Return core artifact IDs and whether every returned ID is mandatory."""

    manifest_artifacts = remote.manifest.get("artifacts")
    if not isinstance(manifest_artifacts, list):
        raise VerificationError("candidate artifact manifest is invalid")
    manifest_by_id = {
        str(artifact["artifact_id"]): artifact
        for artifact in manifest_artifacts
        if isinstance(artifact, Mapping)
    }
    projection = remote.memory_projection
    authorities = (
        projection.get("artifact_authorities")
        if isinstance(projection, Mapping)
        else None
    )
    if isinstance(authorities, list):
        authoritative = {
            str(authority["artifact_id"])
            for authority in authorities
            if isinstance(authority, Mapping)
            and authority.get("authority_status") == "current_authoritative"
            and str(authority.get("artifact_id")) in manifest_by_id
        }
        if authoritative:
            return authoritative, True
        non_core = {
            str(authority["artifact_id"])
            for authority in authorities
            if isinstance(authority, Mapping)
            and authority.get("authority_status")
            in {
                "current_companion",
                "reference_only",
                "historical",
                "rejected",
            }
        }
    else:
        non_core = set()

    fallback: set[str] = set()
    for artifact_id, artifact in manifest_by_id.items():
        if artifact_id in non_core:
            continue
        role = str(artifact.get("role") or "").casefold().replace("_", "-")
        if any(
            marker.replace("_", "-") in role
            for marker in ROUTING_SUPPORTING_ARTIFACT_ROLE_MARKERS
        ):
            continue
        fallback.add(artifact_id)
    return fallback, False


def record_local_routing_review_command(
    args: argparse.Namespace,
    engine: SyncEngine,
) -> Mapping[str, Any]:
    """Create a private receipt proving actual local content was reviewed.

    The transcript and semantic comparison are accepted only over private
    stdin (or directly by tests). Transcript text and comparison prose are
    reduced to hashes; actual artifact blocks remain only in device-signed
    private extraction receipts and are never written to the control plane.
    """

    request_id = validate_identifier(args.request_id, "routing_request_id")
    document = getattr(args, "review_document", None)
    if not isinstance(document, Mapping):
        raise IdentityError(
            "local routing review requires a private structured evidence document"
        )
    fields = {
        "schema_version",
        "request_id",
        "source_session_id",
        "conversation",
        "artifacts",
        "candidate_reviews",
    }
    _require_keys(
        document,
        required=fields,
        allowed=fields,
        label="local routing review",
    )
    if (
        document.get("schema_version") != LOCAL_ROUTING_REVIEW_SCHEMA
        or document.get("request_id") != request_id
    ):
        raise IdentityError("local routing review identity is invalid")
    source_session_id = _bounded_session_log_identifier(
        document.get("source_session_id"),
        "local routing native task identity",
    )
    _preflight_request_path, preflight_request = _load_routing_request(
        engine.data_dir,
        request_id,
    )
    if (
        preflight_request.get("state") != "pending"
        or preflight_request.get("session_id") != source_session_id
        or preflight_request.get("source_external_key_sha256")
        != _codex_source_key(source_session_id)
    ):
        raise IdentityError(
            "local routing review came from a different native task"
        )
    request_workspace = Path(
        str(preflight_request["workspace_root"])
    ).resolve(strict=True)
    session_evidence = _capture_codex_session_evidence(source_session_id)
    canonical_turns = session_evidence["turns"]
    canonical_turns_by_ordinal = {
        int(turn["ordinal"]): turn for turn in canonical_turns
    }
    canonical_anchors_by_ordinal = {
        int(anchor["ordinal"]): anchor
        for anchor in session_evidence["anchors"]
    }

    conversation = document.get("conversation")
    if not isinstance(conversation, Mapping):
        raise IdentityError("local routing conversation evidence is invalid")
    conversation_fields = {"coverage", "omission_reason", "turns"}
    _require_keys(
        conversation,
        required=conversation_fields,
        allowed=conversation_fields,
        label="local routing conversation evidence",
    )
    coverage = conversation.get("coverage")
    omission_reason = conversation.get("omission_reason")
    if coverage not in {"full_visible_task", "bounded_with_reason"}:
        raise IdentityError("local routing conversation coverage is invalid")
    if coverage == "full_visible_task":
        if omission_reason is not None:
            raise IdentityError(
                "complete local conversation review cannot claim omitted turns"
            )
    else:
        _bounded_private_text(
            omission_reason,
            "local routing omission reason",
            maximum_bytes=2000,
        )
    turns = conversation.get("turns")
    if (
        not isinstance(turns, list)
        or not turns
        or len(turns) > 5000
    ):
        raise IdentityError("local routing transcript is missing or too large")
    normalized_turns: list[dict[str, Any]] = []
    previous_ordinal = -1
    total_text_bytes = 0
    user_turns = 0
    assistant_turns = 0
    for item in turns:
        if not isinstance(item, Mapping):
            raise IdentityError("local routing transcript turn is invalid")
        _require_keys(
            item,
            required={
                "ordinal",
                "record_id",
                "turn_id",
                "role",
                "phase",
                "text",
            },
            allowed={
                "ordinal",
                "record_id",
                "turn_id",
                "role",
                "phase",
                "text",
            },
            label="local routing transcript turn",
        )
        ordinal = item.get("ordinal")
        record_id = _bounded_session_log_identifier(
            item.get("record_id"),
            "local routing visible record id",
        )
        turn_id = _bounded_session_log_identifier(
            item.get("turn_id"),
            "local routing visible turn id",
        )
        role = item.get("role")
        phase = item.get("phase")
        text = item.get("text")
        if (
            not isinstance(ordinal, int)
            or isinstance(ordinal, bool)
            or ordinal < 0
            or ordinal <= previous_ordinal
        ):
            raise IdentityError(
                "local routing transcript ordinals must increase"
            )
        if role not in {"user", "assistant"}:
            raise IdentityError(
                "local routing transcript must contain only visible user and "
                "assistant turns"
            )
        if (
            (role == "user" and phase is not None)
            or (
                role == "assistant"
                and (
                    not isinstance(phase, str)
                    or not phase
                    or len(phase.encode("utf-8")) > 512
                )
            )
        ):
            raise IdentityError(
                "local routing transcript phase is invalid"
            )
        normalized_text = _canonical_local_session_text(
            text,
            "local routing transcript text",
            maximum_bytes=256 * 1024,
        )
        total_text_bytes += len(normalized_text.encode("utf-8"))
        if total_text_bytes > 512 * 1024:
            raise PrivacyError("local routing transcript exceeds the fixed limit")
        normalized_turn = {
            "ordinal": ordinal,
            "record_id": record_id,
            "turn_id": turn_id,
            "role": role,
            "phase": phase,
            "text": normalized_text,
        }
        if canonical_turns_by_ordinal.get(ordinal) != normalized_turn:
            raise IdentityError(
                "local routing transcript does not match the exact native "
                "session log"
            )
        previous_ordinal = ordinal
        user_turns += int(role == "user")
        assistant_turns += int(role == "assistant")
        normalized_turns.append(normalized_turn)
    if user_turns == 0:
        raise IdentityError(
            "local routing transcript contains no visible user request"
        )
    if (
        coverage == "full_visible_task"
        and normalized_turns != canonical_turns
    ):
        raise IdentityError(
            "full local routing review omitted, added, or reordered a visible "
            "native task message"
        )

    artifacts = document.get("artifacts")
    if not isinstance(artifacts, Mapping):
        raise IdentityError("local routing artifact evidence is invalid")
    _require_keys(
        artifacts,
        required={"disposition", "extraction_receipt_ids"},
        allowed={"disposition", "extraction_receipt_ids"},
        label="local routing artifact evidence",
    )
    disposition = artifacts.get("disposition")
    raw_receipt_ids = artifacts.get("extraction_receipt_ids")
    if (
        not isinstance(raw_receipt_ids, list)
        or len(raw_receipt_ids) > 32
        or len(set(raw_receipt_ids)) != len(raw_receipt_ids)
    ):
        raise IdentityError(
            "local routing artifact extraction receipt list is invalid"
        )
    if disposition == "none_declared_for_task_identity":
        if raw_receipt_ids:
            raise IdentityError(
                "no-declared-artifact review cannot contain extraction receipts"
            )
    elif disposition == "extracted_declared_artifacts":
        if not raw_receipt_ids:
            raise IdentityError(
                "declared artifact review must contain extraction receipts"
            )
    else:
        raise IdentityError("local routing artifact disposition is invalid")

    artifact_receipts: list[dict[str, Any]] = []
    local_artifact_bundles: dict[str, Mapping[str, Any]] = {}
    for raw_receipt_id in raw_receipt_ids:
        receipt_id = validate_identifier(
            raw_receipt_id,
            "local artifact extraction receipt_id",
        )
        bundle, bundle_sha = _load_artifact_extraction_bundle(
            engine.data_dir,
            preflight_request,
            receipt_id,
            expected_source_kind="local",
        )
        source_path = Path(str(bundle["source_path"])).resolve(strict=True)
        if not _path_is_within(source_path, request_workspace):
            raise PrivacyError(
                "local artifact extraction is outside this exact task workspace"
            )
        local_artifact_bundles[receipt_id] = bundle
        artifact_receipts.append(
            {
                "receipt_id": receipt_id,
                "bundle_sha256": bundle_sha,
                "path_fingerprint": bundle["path_fingerprint"],
                "role_sha256": bundle["role_sha256"],
                "object_sha256": bundle["object_sha256"],
                "object_size": bundle["object_size"],
                "extractor_profile": bundle["extractor_profile"],
                "status": bundle["status"],
                "coverage": bundle["coverage"],
                "anchor_ids": [
                    block["anchor_id"] for block in bundle["blocks"]
                ],
            }
        )

    candidate_reviews = document.get("candidate_reviews")
    if (
        not isinstance(candidate_reviews, list)
        or not candidate_reviews
        or len(candidate_reviews) > 8
    ):
        raise IdentityError("local routing candidate reviews are missing")

    with FileLock(engine.lock_path):
        request_path, request, catalog = engine._verified_routing_request(
            request_id
        )
        if request.get("state") != "pending":
            raise IdentityError(
                "local routing review is not for a pending request"
            )
        if (
            request.get("review_nonce")
            != preflight_request.get("review_nonce")
            or request.get("remote_commit_sha")
            != preflight_request.get("remote_commit_sha")
            or request.get("workspace_root")
            != preflight_request.get("workspace_root")
        ):
            raise ConflictError(
                "routing request changed after local artifact extraction"
            )
        if (
            request.get("session_id") != source_session_id
            or request.get("source_external_key_sha256")
            != _codex_source_key(source_session_id)
        ):
            raise IdentityError(
                "local routing review no longer matches the exact native task"
            )
        if len(catalog) > 8:
            raise ConfigurationError(
                "formal content routing currently supports at most eight "
                "active semantic candidates; no partial-catalog match was "
                "recorded"
            )
        normalized_reviews: list[dict[str, Any]] = []
        reviewed_task_ids: set[str] = set()
        for item in candidate_reviews:
            if not isinstance(item, Mapping):
                raise IdentityError("local routing candidate review is invalid")
            review_fields = {
                "task_id",
                "verdict",
                "local_turn_ordinals",
                "remote_conversation_anchors",
                "contradictions",
                "identity_assessment",
                "version_assessment",
                "dimension_matrix",
                "artifact_pairs",
                "local_artifact_gaps",
                "rationale",
            }
            _require_keys(
                item,
                required=review_fields,
                allowed=review_fields,
                label="local routing candidate review",
            )
            task_id = validate_identifier(item.get("task_id"), "task_id")
            if task_id in reviewed_task_ids:
                raise IdentityError("local routing candidate review is duplicated")
            reviewed_task_ids.add(task_id)
            remote = catalog.get(task_id)
            if remote is None:
                raise IdentityError(
                    "local review contains an inactive candidate"
                )
            remote_receipt, remote_receipt_sha = (
                _load_routing_evidence_receipt(
                    engine.data_dir,
                    request,
                    remote,
                )
            )
            verdict = item.get("verdict")
            if verdict not in {"consistent", "uncertain", "contradictory"}:
                raise IdentityError("local routing candidate verdict is invalid")
            if verdict == "consistent" and coverage != "full_visible_task":
                raise IdentityError(
                    "a bounded local transcript cannot prove a consistent "
                    "task identity"
                )
            conversation_signal = _routing_deterministic_content_signal(
                (
                    str(turn["text"])
                    for turn in normalized_turns
                ),
                _verified_remote_routing_conversation_texts(
                    engine.git,
                    remote,
                    remote_receipt,
                ),
            )
            local_ordinals = item.get("local_turn_ordinals")
            if (
                not isinstance(local_ordinals, list)
                or not local_ordinals
                or len(local_ordinals) > 100
                or len(set(local_ordinals)) != len(local_ordinals)
            ):
                raise IdentityError(
                    "local routing candidate anchors are invalid"
                )
            available_ordinals = {
                int(turn["ordinal"]) for turn in normalized_turns
            }
            selected_local_roles: set[str] = set()
            selected_local_anchors: list[str] = []
            for ordinal in local_ordinals:
                if (
                    not isinstance(ordinal, int)
                    or isinstance(ordinal, bool)
                    or ordinal not in available_ordinals
                ):
                    raise IdentityError(
                        "local routing candidate anchor is outside the transcript"
                    )
                selected_local_roles.add(
                    str(
                        next(
                            turn["role"]
                            for turn in normalized_turns
                            if turn["ordinal"] == ordinal
                        )
                    )
                )
                selected_local_anchors.append(
                    str(
                        canonical_anchors_by_ordinal[ordinal][
                            "anchor_sha256"
                        ]
                    )
                )
            if "user" not in selected_local_roles:
                raise IdentityError(
                    "local routing candidate must anchor an actual user turn"
                )
            if (
                verdict == "consistent"
                and assistant_turns
                and "assistant" not in selected_local_roles
            ):
                raise IdentityError(
                    "a consistent routing candidate must anchor the local "
                    "assistant outcome when one is available"
                )

            raw_remote_anchors = item.get(
                "remote_conversation_anchors"
            )
            if (
                not isinstance(raw_remote_anchors, list)
                or not raw_remote_anchors
                or len(raw_remote_anchors) > 8
            ):
                raise IdentityError(
                    "routing review must anchor actual remote conversation "
                    "content"
                )
            available_remote_anchors = {
                (
                    str(anchor["source_id"]),
                    str(anchor["revision_id"]),
                ): anchor
                for anchor in remote_receipt["conversation_anchors"]
                if isinstance(anchor, Mapping)
            }
            normalized_remote_anchors: list[dict[str, Any]] = []
            selected_remote_roles: set[str] = set()
            seen_remote_anchors: set[tuple[str, str]] = set()
            for anchor in raw_remote_anchors:
                if not isinstance(anchor, Mapping):
                    raise IdentityError(
                        "remote routing conversation anchor is invalid"
                    )
                _require_keys(
                    anchor,
                    required={
                        "source_id",
                        "revision_id",
                        "message_ordinals",
                    },
                    allowed={
                        "source_id",
                        "revision_id",
                        "message_ordinals",
                    },
                    label="remote routing conversation anchor",
                )
                source_id = validate_identifier(
                    anchor.get("source_id"),
                    "remote routing source_id",
                )
                revision_id = validate_identifier(
                    anchor.get("revision_id"),
                    "remote routing revision_id",
                )
                anchor_key = (source_id, revision_id)
                if anchor_key in seen_remote_anchors:
                    raise IdentityError(
                        "remote routing conversation anchor is duplicated"
                    )
                seen_remote_anchors.add(anchor_key)
                verified_anchor = available_remote_anchors.get(anchor_key)
                if verified_anchor is None:
                    raise IdentityError(
                        "remote routing conversation anchor was not in the "
                        "verified candidate evidence"
                    )
                ordinals = anchor.get("message_ordinals")
                roles = verified_anchor.get("message_roles")
                if (
                    not isinstance(ordinals, list)
                    or not ordinals
                    or len(ordinals) > 100
                    or len(set(ordinals)) != len(ordinals)
                    or not isinstance(roles, list)
                ):
                    raise IdentityError(
                        "remote routing message anchors are invalid"
                    )
                for ordinal in ordinals:
                    if (
                        not isinstance(ordinal, int)
                        or isinstance(ordinal, bool)
                        or ordinal < 0
                        or ordinal >= len(roles)
                    ):
                        raise IdentityError(
                            "remote routing message anchor is outside the "
                            "verified conversation"
                        )
                    selected_remote_roles.add(str(roles[ordinal]))
                normalized_remote_anchors.append(
                    {
                        "source_id": source_id,
                        "revision_id": revision_id,
                        "message_ordinals": list(ordinals),
                    }
                )
            if "user" not in selected_remote_roles:
                raise IdentityError(
                    "routing review must anchor an actual remote user turn"
                )
            remote_has_assistant_turn = any(
                "assistant" in anchor.get("message_roles", [])
                for anchor in remote_receipt["conversation_anchors"]
                if isinstance(anchor, Mapping)
            )
            if (
                verdict == "consistent"
                and remote_has_assistant_turn
                and "assistant" not in selected_remote_roles
            ):
                raise IdentityError(
                    "a consistent routing candidate must anchor the verified "
                    "remote assistant outcome when one is available"
                )
            contradictions = item.get("contradictions")
            if (
                not isinstance(contradictions, list)
                or len(contradictions) > 20
            ):
                raise IdentityError("local routing contradictions are invalid")
            normalized_contradictions = [
                _bounded_private_text(
                    fact,
                    "local routing contradiction",
                    maximum_bytes=2000,
                )
                for fact in contradictions
            ]
            if verdict == "consistent" and normalized_contradictions:
                raise IdentityError(
                    "consistent routing review cannot contain a material "
                    "contradiction"
                )
            if verdict == "contradictory" and not normalized_contradictions:
                raise IdentityError(
                    "contradictory routing review must record the conflict"
                )

            identity_assessment = item.get("identity_assessment")
            if identity_assessment not in {
                "same_work_lineage",
                "related_work",
                "different_work",
                "uncertain",
            }:
                raise IdentityError(
                    "routing identity assessment is invalid"
                )
            if (
                verdict == "consistent"
                and identity_assessment != "same_work_lineage"
            ):
                raise IdentityError(
                    "consistent routing requires same-work-lineage identity"
                )
            if (
                verdict == "contradictory"
                and identity_assessment == "same_work_lineage"
            ):
                raise IdentityError(
                    "contradictory routing cannot claim the same work identity"
                )
            version_assessment = item.get("version_assessment")
            if version_assessment not in {
                "byte_identical",
                "local_predecessor",
                "local_successor",
                "parallel_revision",
                "structural_rewrite",
                "unknown",
            }:
                raise IdentityError(
                    "routing version assessment is invalid"
                )

            remote_artifacts = {
                str(descriptor["artifact_id"]): descriptor
                for descriptor in remote_receipt["artifact_descriptors"]
                if isinstance(descriptor, Mapping)
            }
            candidate_has_artifacts = bool(remote_artifacts)
            local_has_artifacts = bool(artifact_receipts)
            if (
                verdict == "consistent"
                and len(remote_artifacts) > MAX_ROUTING_CANDIDATE_ARTIFACTS
            ):
                raise IdentityError(
                    "candidate has too many artifacts for complete bounded "
                    "human disclosure"
                )
            raw_artifact_pairs = item.get("artifact_pairs")
            if (
                not isinstance(raw_artifact_pairs, list)
                or len(raw_artifact_pairs) > 32
            ):
                raise IdentityError("routing artifact pairs are invalid")
            normalized_artifact_pairs: list[dict[str, Any]] = []
            seen_artifact_pairs: set[tuple[str, str]] = set()
            paired_local_receipt_ids: set[str] = set()
            paired_remote_artifact_ids: set[str] = set()
            resolved_artifact_pairs: list[
                tuple[Mapping[str, Any], Mapping[str, Any]]
            ] = []
            artifact_semantic_support = False
            local_anchor_scope: dict[str, str] = {}
            remote_anchor_scope: dict[str, str] = {}
            for pair in raw_artifact_pairs:
                if not isinstance(pair, Mapping):
                    raise IdentityError("routing artifact pair is invalid")
                _require_keys(
                    pair,
                    required={
                        "local_receipt_id",
                        "remote_receipt_id",
                    },
                    allowed={
                        "local_receipt_id",
                        "remote_receipt_id",
                    },
                    label="routing artifact pair",
                )
                local_receipt_id = validate_identifier(
                    pair.get("local_receipt_id"),
                    "local artifact receipt_id",
                )
                local_bundle = local_artifact_bundles.get(local_receipt_id)
                if local_bundle is None:
                    raise IdentityError(
                        "routing artifact pair has no declared local "
                        "extraction receipt"
                    )
                remote_receipt_id = validate_identifier(
                    pair.get("remote_receipt_id"),
                    "remote artifact receipt_id",
                )
                remote_bundle, remote_bundle_sha = (
                    _load_artifact_extraction_bundle(
                        engine.data_dir,
                        request,
                        remote_receipt_id,
                        expected_source_kind="remote",
                        expected_task_id=task_id,
                    )
                )
                remote_artifact_id = validate_identifier(
                    remote_bundle.get("artifact_id"),
                    "remote artifact_id",
                )
                remote_artifact = remote_artifacts.get(remote_artifact_id)
                if remote_artifact is None:
                    raise IdentityError(
                        "routing artifact extraction is not declared by this "
                        "candidate manifest"
                    )
                if (
                    remote_bundle.get("object_sha256")
                    != remote_artifact.get("sha256")
                    or remote_bundle.get("object_size")
                    != remote_artifact.get("size")
                    or remote_bundle.get("role_sha256")
                    != remote_artifact.get("role_sha256")
                ):
                    raise IdentityError(
                        "remote artifact extraction no longer matches the "
                        "verified manifest"
                    )
                pair_key = (local_receipt_id, remote_receipt_id)
                if pair_key in seen_artifact_pairs:
                    raise IdentityError("routing artifact pair is duplicated")
                if (
                    local_receipt_id in paired_local_receipt_ids
                    or remote_artifact_id in paired_remote_artifact_ids
                ):
                    raise IdentityError(
                        "routing artifact pairing must be one-to-one"
                    )
                seen_artifact_pairs.add(pair_key)
                paired_local_receipt_ids.add(local_receipt_id)
                paired_remote_artifact_ids.add(remote_artifact_id)
                local_bundle_sha = next(
                    receipt["bundle_sha256"]
                    for receipt in artifact_receipts
                    if receipt["receipt_id"] == local_receipt_id
                )
                normalized_artifact_pairs.append(
                    {
                        "local_receipt_id": local_receipt_id,
                        "local_bundle_sha256": local_bundle_sha,
                        "remote_receipt_id": remote_receipt_id,
                        "remote_bundle_sha256": remote_bundle_sha,
                        "remote_artifact_id": remote_artifact_id,
                        "local_object_sha256": local_bundle[
                            "object_sha256"
                        ],
                        "remote_object_sha256": remote_bundle[
                            "object_sha256"
                        ],
                    }
                )
                resolved_artifact_pairs.append(
                    (local_bundle, remote_bundle)
                )
                artifact_signal = _routing_deterministic_content_signal(
                    (
                        str(block["text"])
                        for block in local_bundle["blocks"]
                    ),
                    (
                        str(block["text"])
                        for block in remote_bundle["blocks"]
                    ),
                )
                pair_content_available = bool(
                    local_bundle.get("status") == "available"
                    and local_bundle.get("coverage") == "full"
                    and remote_bundle.get("status") == "available"
                    and remote_bundle.get("coverage") == "full"
                )
                if (
                    verdict == "consistent"
                    and pair_content_available
                    and not artifact_signal["positive"]
                ):
                    raise IdentityError(
                        "deterministic content guard found no semantic support "
                        "between a paired local and remote artifact; object "
                        "hash equality alone is not task identity"
                    )
                artifact_semantic_support = bool(
                    artifact_semantic_support
                    or (
                        pair_content_available
                        and artifact_signal["positive"]
                    )
                )
                for block in local_bundle["blocks"]:
                    local_anchor_scope[str(block["anchor_id"])] = (
                        local_receipt_id
                    )
                for block in remote_bundle["blocks"]:
                    remote_anchor_scope[str(block["anchor_id"])] = (
                        remote_receipt_id
                    )

            raw_local_gaps = item.get("local_artifact_gaps")
            if (
                not isinstance(raw_local_gaps, list)
                or len(raw_local_gaps) > 32
            ):
                raise IdentityError("routing local artifact gaps are invalid")
            normalized_local_gaps: list[dict[str, Any]] = []
            local_gap_receipt_ids: set[str] = set()
            for gap in raw_local_gaps:
                if not isinstance(gap, Mapping):
                    raise IdentityError(
                        "routing local artifact gap is invalid"
                    )
                _require_keys(
                    gap,
                    required={"local_receipt_id", "reason"},
                    allowed={"local_receipt_id", "reason"},
                    label="routing local artifact gap",
                )
                gap_receipt_id = validate_identifier(
                    gap.get("local_receipt_id"),
                    "local artifact gap receipt_id",
                )
                if (
                    gap_receipt_id not in local_artifact_bundles
                    or gap_receipt_id in paired_local_receipt_ids
                    or gap_receipt_id in local_gap_receipt_ids
                ):
                    raise IdentityError(
                        "routing local artifact gap is missing, paired, or "
                        "duplicated"
                    )
                reason = _bounded_private_text(
                    gap.get("reason"),
                    "routing local artifact gap reason",
                    maximum_bytes=2000,
                )
                local_gap_receipt_ids.add(gap_receipt_id)
                normalized_local_gaps.append(
                    {
                        "local_receipt_id": gap_receipt_id,
                        "reason": reason,
                        "reason_sha256": sha256_bytes(
                            reason.encode("utf-8")
                        ),
                    }
                )
            if (
                paired_local_receipt_ids | local_gap_receipt_ids
                != set(local_artifact_bundles)
            ):
                raise IdentityError(
                    "every local artifact extraction must be paired or "
                    "explicitly disclosed as a gap"
                )
            if verdict == "consistent" and normalized_local_gaps:
                raise IdentityError(
                    "a consistent candidate cannot leave a declared local "
                    "identity artifact as a gap"
                )
            uncompared_remote_artifacts = sorted(
                set(remote_artifacts) - paired_remote_artifact_ids
            )
            required_core_ids, require_every_core = (
                _routing_required_core_artifacts(remote)
            )
            if (
                verdict == "consistent"
                and candidate_has_artifacts
                and not required_core_ids
            ):
                raise IdentityError(
                    "candidate artifact manifest has no authoritative or "
                    "non-supporting core result; supporting artifacts alone "
                    "cannot establish task identity"
                )
            if verdict == "consistent" and required_core_ids:
                missing_core = required_core_ids - paired_remote_artifact_ids
                if (
                    (require_every_core and missing_core)
                    or not (
                        required_core_ids & paired_remote_artifact_ids
                    )
                ):
                    raise IdentityError(
                        "authoritative identity artifact content must be "
                        "compared; a generic supporting artifact cannot "
                        "substitute for the candidate's core result"
                    )

            raw_dimensions = item.get("dimension_matrix")
            if (
                not isinstance(raw_dimensions, list)
                or len(raw_dimensions) != len(ROUTING_ARTIFACT_DIMENSIONS)
            ):
                raise IdentityError(
                    "routing comparison must contain the complete six-dimension "
                    "matrix"
                )
            normalized_dimensions: list[dict[str, Any]] = []
            seen_dimensions: set[str] = set()
            relations: dict[str, str] = {}
            for dimension_row in raw_dimensions:
                if not isinstance(dimension_row, Mapping):
                    raise IdentityError(
                        "routing dimension comparison is invalid"
                    )
                dimension_fields = {
                    "dimension",
                    "relation",
                    "local_anchor_ids",
                    "remote_anchor_ids",
                    "summary",
                }
                _require_keys(
                    dimension_row,
                    required=dimension_fields,
                    allowed=dimension_fields,
                    label="routing dimension comparison",
                )
                dimension = dimension_row.get("dimension")
                if (
                    dimension not in ROUTING_ARTIFACT_DIMENSIONS
                    or dimension in seen_dimensions
                ):
                    raise IdentityError(
                        "routing dimension comparison is missing or duplicated"
                    )
                seen_dimensions.add(str(dimension))
                relation = dimension_row.get("relation")
                if relation not in {
                    "preserved",
                    "evolved",
                    "added",
                    "removed",
                    "contradictory",
                    "unrelated",
                    "unknown",
                }:
                    raise IdentityError(
                        "routing dimension relation is invalid"
                    )
                local_anchor_ids = dimension_row.get("local_anchor_ids")
                remote_anchor_ids = dimension_row.get("remote_anchor_ids")
                if (
                    not isinstance(local_anchor_ids, list)
                    or not isinstance(remote_anchor_ids, list)
                    or len(local_anchor_ids) > 64
                    or len(remote_anchor_ids) > 64
                    or len(set(local_anchor_ids)) != len(local_anchor_ids)
                    or len(set(remote_anchor_ids)) != len(remote_anchor_ids)
                ):
                    raise IdentityError(
                        "routing dimension artifact anchors are invalid"
                    )
                normalized_local_anchor_ids = [
                    validate_identifier(
                        anchor_id,
                        "local artifact anchor_id",
                    )
                    for anchor_id in local_anchor_ids
                ]
                normalized_remote_anchor_ids = [
                    validate_identifier(
                        anchor_id,
                        "remote artifact anchor_id",
                    )
                    for anchor_id in remote_anchor_ids
                ]
                if any(
                    anchor_id not in local_anchor_scope
                    for anchor_id in normalized_local_anchor_ids
                ) or any(
                    anchor_id not in remote_anchor_scope
                    for anchor_id in normalized_remote_anchor_ids
                ):
                    raise IdentityError(
                        "routing dimension contains a forged or cross-candidate "
                        "artifact anchor"
                    )
                summary = _bounded_private_text(
                    dimension_row.get("summary"),
                    "routing dimension summary",
                    maximum_bytes=2000,
                )
                relations[str(dimension)] = str(relation)
                normalized_dimensions.append(
                    {
                        "dimension": dimension,
                        "relation": relation,
                        "local_anchor_ids": normalized_local_anchor_ids,
                        "remote_anchor_ids": normalized_remote_anchor_ids,
                        "summary": summary,
                        "summary_sha256": sha256_bytes(
                            summary.encode("utf-8")
                        ),
                    }
                )
            if seen_dimensions != set(ROUTING_ARTIFACT_DIMENSIONS):
                raise IdentityError(
                    "routing dimension matrix does not cover all dimensions"
                )

            has_full_bidirectional_artifacts = bool(
                resolved_artifact_pairs
                and all(
                    local_bundle.get("status") == "available"
                    and local_bundle.get("coverage") == "full"
                    and remote_bundle.get("status") == "available"
                    and remote_bundle.get("coverage") == "full"
                    for local_bundle, remote_bundle in resolved_artifact_pairs
                )
            )
            if (
                (candidate_has_artifacts or local_has_artifacts)
                and verdict == "consistent"
                and not has_full_bidirectional_artifacts
            ):
                raise IdentityError(
                    "a consistent artifact-bearing candidate requires at "
                    "least one one-to-one supported full extraction pair"
                )
            if (
                verdict == "consistent"
                and has_full_bidirectional_artifacts
                and any(
                    not row["local_anchor_ids"]
                    or not row["remote_anchor_ids"]
                    for row in normalized_dimensions
                )
            ):
                raise IdentityError(
                    "a consistent artifact-bearing candidate requires "
                    "bidirectional content anchors in every dimension"
                )
            if (
                verdict == "consistent"
                and conversation_signal["clearly_unrelated"]
                and not artifact_semantic_support
            ):
                raise IdentityError(
                    "deterministic content guard found the local and remote "
                    "conversations clearly unrelated"
                )
            if verdict == "consistent" and any(
                relation in {"contradictory", "unrelated", "unknown"}
                for relation in relations.values()
            ):
                raise IdentityError(
                    "a consistent routing candidate has an unresolved semantic "
                    "dimension"
                )
            if (
                version_assessment == "byte_identical"
                and not any(
                    local_bundle["object_sha256"]
                    == remote_bundle["object_sha256"]
                    and local_bundle["object_size"]
                    == remote_bundle["object_size"]
                    for local_bundle, remote_bundle in resolved_artifact_pairs
                )
            ):
                raise IdentityError(
                    "byte-identical is a version fact and requires an exact "
                    "object hash and size"
                )
            rationale = _bounded_private_text(
                item.get("rationale"),
                "local routing candidate rationale",
                maximum_bytes=4000,
            )
            normalized_reviews.append(
                {
                    "task_id": task_id,
                    "verdict": verdict,
                    "local_turn_anchor_sha256": selected_local_anchors,
                    "remote_conversation_anchors": (
                        normalized_remote_anchors
                    ),
                    "contradictions_sha256": sha256_bytes(
                        canonical_json_bytes(normalized_contradictions)
                    ),
                    "identity_assessment": identity_assessment,
                    "version_assessment": version_assessment,
                    "dimension_matrix": normalized_dimensions,
                    "artifact_pairs": normalized_artifact_pairs,
                    "local_artifact_gaps": normalized_local_gaps,
                    "uncompared_remote_artifacts": (
                        uncompared_remote_artifacts
                    ),
                    "rationale_sha256": sha256_bytes(
                        rationale.encode("utf-8")
                    ),
                    "remote_evidence_receipt_sha256": remote_receipt_sha,
                }
            )
        if reviewed_task_ids != set(catalog):
            raise IdentityError(
                "formal routing review must compare every active semantic "
                "candidate so a title-selected runner-up cannot be omitted"
            )

        receipt = {
            "schema_version": LOCAL_ROUTING_REVIEW_RECEIPT_SCHEMA,
            "request_id": request_id,
            "session_key": request["session_key"],
            "review_nonce": request["review_nonce"],
            "source_external_key_sha256": request[
                "source_external_key_sha256"
            ],
            "workspace_identity_fingerprint": request[
                "workspace_identity_fingerprint"
            ],
            "remote_commit_sha": request["remote_commit_sha"],
            "candidate_set_sha256": _routing_candidate_set_sha256(request),
            "review_document_sha256": sha256_bytes(
                canonical_json_bytes(document)
            ),
            "session_log_proof": dict(session_evidence["proof"]),
            "visible_turn_anchors": list(session_evidence["anchors"]),
            "reviewed_turn_anchor_sha256": [
                canonical_anchors_by_ordinal[int(turn["ordinal"])][
                    "anchor_sha256"
                ]
                for turn in normalized_turns
            ],
            "transcript_coverage": coverage,
            "visible_turn_count": len(canonical_turns),
            "reviewed_turn_count": len(normalized_turns),
            "user_turn_count": sum(
                int(turn["role"] == "user") for turn in canonical_turns
            ),
            "assistant_turn_count": sum(
                int(turn["role"] == "assistant") for turn in canonical_turns
            ),
            "artifact_disposition": disposition,
            "artifact_receipts": artifact_receipts,
            "candidate_reviews": normalized_reviews,
            "created_at": utc_now(),
        }
        atomic_write_json(
            _local_routing_review_receipt_path(
                engine.data_dir,
                request_id,
            ),
            receipt,
        )
    return {
        "schema_version": "memory-vault-local-routing-review-result/v1",
        "status": "recorded_private_receipt",
        "request_id": request_id,
        "visible_turn_count": len(canonical_turns),
        "reviewed_turn_count": len(normalized_turns),
        "artifact_count": len(artifact_receipts),
        "reviewed_task_ids": sorted(reviewed_task_ids),
        "raw_review_document_persisted": False,
        "transcript_text_persisted": False,
        "artifact_extraction_receipts_persisted": bool(artifact_receipts),
        "artifact_extraction_content_persisted": any(
            bool(receipt["anchor_ids"]) for receipt in artifact_receipts
        ),
        "artifact_extraction_persistence_scope": (
            "private_device_only" if artifact_receipts else "none"
        ),
        "artifact_extraction_content_uploaded": False,
        "semantic_dimension_summaries_persisted": True,
        "semantic_dimension_summary_scope": "private_device_only",
        "receipt_sha256": sha256_bytes(canonical_json_bytes(receipt)),
    }


def _load_local_routing_review_receipt(
    data_dir: Path,
    request: Mapping[str, Any],
) -> tuple[Mapping[str, Any], str]:
    path = _local_routing_review_receipt_path(
        data_dir,
        str(request["request_id"]),
    )
    if not path.exists():
        raise IdentityError(
            "actual local conversation and artifact evidence has not been reviewed"
        )
    value = load_json(path)
    required = {
        "schema_version",
        "request_id",
        "session_key",
        "review_nonce",
        "source_external_key_sha256",
        "workspace_identity_fingerprint",
        "remote_commit_sha",
        "candidate_set_sha256",
        "review_document_sha256",
        "session_log_proof",
        "visible_turn_anchors",
        "reviewed_turn_anchor_sha256",
        "transcript_coverage",
        "visible_turn_count",
        "reviewed_turn_count",
        "user_turn_count",
        "assistant_turn_count",
        "artifact_disposition",
        "artifact_receipts",
        "candidate_reviews",
        "created_at",
    }
    if not isinstance(value, Mapping):
        raise IdentityError("local routing review receipt is invalid")
    _require_keys(
        value,
        required=required,
        allowed=required,
        label="local routing review receipt",
    )
    if (
        value.get("schema_version") != LOCAL_ROUTING_REVIEW_RECEIPT_SCHEMA
        or value.get("request_id") != request.get("request_id")
        or value.get("session_key") != request.get("session_key")
        or value.get("review_nonce") != request.get("review_nonce")
        or value.get("source_external_key_sha256")
        != request.get("source_external_key_sha256")
        or value.get("workspace_identity_fingerprint")
        != request.get("workspace_identity_fingerprint")
        or value.get("remote_commit_sha") != request.get("remote_commit_sha")
        or value.get("candidate_set_sha256")
        != _routing_candidate_set_sha256(request)
    ):
        raise IdentityError(
            "local routing review receipt no longer matches this exact task"
        )
    validate_sha256(
        value.get("review_document_sha256"),
        "review_document_sha256",
    )
    proof = value.get("session_log_proof")
    proof_fields = {
        "parser_version",
        "rollout_id_sha256",
        "relative_path_sha256",
        "file_identity_sha256",
        "prefix_bytes",
        "prefix_sha256",
        "transcript_sha256",
    }
    if not isinstance(proof, Mapping):
        raise IdentityError("local Codex session proof is invalid")
    _require_keys(
        proof,
        required=proof_fields,
        allowed=proof_fields,
        label="local Codex session proof",
    )
    if proof.get("parser_version") != CODEX_SESSION_LOG_PARSER_VERSION:
        raise IdentityError("local Codex session parser version is invalid")
    for key in (
        "rollout_id_sha256",
        "relative_path_sha256",
        "file_identity_sha256",
        "prefix_sha256",
        "transcript_sha256",
    ):
        validate_sha256(proof.get(key), f"session_log_proof.{key}")
    if proof.get("rollout_id_sha256") != sha256_bytes(
        str(request.get("session_id")).encode("utf-8")
    ):
        raise IdentityError(
            "local Codex session proof belongs to another native task"
        )
    prefix_bytes = proof.get("prefix_bytes")
    if (
        not isinstance(prefix_bytes, int)
        or isinstance(prefix_bytes, bool)
        or prefix_bytes < 1
        or prefix_bytes > MAX_CODEX_SESSION_LOG_BYTES
    ):
        raise IdentityError("local Codex session prefix boundary is invalid")
    anchors = value.get("visible_turn_anchors")
    if (
        not isinstance(anchors, list)
        or not anchors
        or len(anchors) > 5000
    ):
        raise IdentityError("local Codex visible turn anchors are invalid")
    anchor_fields = {
        "ordinal",
        "anchor_sha256",
        "record_id_sha256",
        "turn_id_sha256",
        "role",
        "phase",
        "text_sha256",
    }
    anchor_hashes: list[str] = []
    for expected_ordinal, anchor in enumerate(anchors):
        if not isinstance(anchor, Mapping):
            raise IdentityError("local Codex visible turn anchor is invalid")
        _require_keys(
            anchor,
            required=anchor_fields,
            allowed=anchor_fields,
            label="local Codex visible turn anchor",
        )
        if anchor.get("ordinal") != expected_ordinal:
            raise IdentityError(
                "local Codex visible turn anchor order is invalid"
            )
        for key in (
            "anchor_sha256",
            "record_id_sha256",
            "turn_id_sha256",
            "text_sha256",
        ):
            validate_sha256(anchor.get(key), f"visible_turn_anchor.{key}")
        if anchor.get("role") not in {"user", "assistant"}:
            raise IdentityError("local Codex visible turn role is invalid")
        phase = anchor.get("phase")
        if (
            (anchor.get("role") == "user" and phase is not None)
            or (
                anchor.get("role") == "assistant"
                and (not isinstance(phase, str) or not phase)
            )
        ):
            raise IdentityError("local Codex visible turn phase is invalid")
        anchor_hashes.append(str(anchor["anchor_sha256"]))
    if proof.get("transcript_sha256") != sha256_bytes(
        canonical_json_bytes(anchors)
    ):
        raise IdentityError(
            "local Codex transcript proof does not match its anchors"
        )
    reviewed_anchor_hashes = value.get("reviewed_turn_anchor_sha256")
    if (
        not isinstance(reviewed_anchor_hashes, list)
        or not reviewed_anchor_hashes
        or len(reviewed_anchor_hashes) > len(anchor_hashes)
        or len(set(reviewed_anchor_hashes)) != len(reviewed_anchor_hashes)
        or any(anchor not in anchor_hashes for anchor in reviewed_anchor_hashes)
    ):
        raise IdentityError("local routing reviewed turn anchors are invalid")
    for anchor in reviewed_anchor_hashes:
        validate_sha256(anchor, "local routing reviewed turn anchor")
    for key in (
        "visible_turn_count",
        "reviewed_turn_count",
        "user_turn_count",
        "assistant_turn_count",
    ):
        count = value.get(key)
        if (
            not isinstance(count, int)
            or isinstance(count, bool)
            or count < 0
        ):
            raise IdentityError("local routing review counters are invalid")
    if value.get("user_turn_count", 0) < 1:
        raise IdentityError("local routing review has no visible user turn")
    if (
        value.get("visible_turn_count") != len(anchors)
        or value.get("reviewed_turn_count") != len(reviewed_anchor_hashes)
        or value.get("user_turn_count")
        != sum(int(anchor["role"] == "user") for anchor in anchors)
        or value.get("assistant_turn_count")
        != sum(int(anchor["role"] == "assistant") for anchor in anchors)
    ):
        raise IdentityError("local routing review counters do not match anchors")
    if value.get("transcript_coverage") not in {
        "full_visible_task",
        "bounded_with_reason",
    }:
        raise IdentityError("local routing review coverage is invalid")
    if (
        value.get("transcript_coverage") == "full_visible_task"
        and reviewed_anchor_hashes != anchor_hashes
    ):
        raise IdentityError(
            "full local routing review does not cover every visible turn"
        )
    if value.get("artifact_disposition") not in {
        "none_declared_for_task_identity",
        "extracted_declared_artifacts",
    }:
        raise IdentityError("local routing review artifact disposition is invalid")
    artifact_receipts = value.get("artifact_receipts")
    if (
        not isinstance(artifact_receipts, list)
        or len(artifact_receipts) > 32
    ):
        raise IdentityError("local routing artifact receipts are invalid")
    if (
        value.get("artifact_disposition")
        == "none_declared_for_task_identity"
        and artifact_receipts
    ):
        raise IdentityError("local routing artifact receipt scope is invalid")
    if (
        value.get("artifact_disposition")
        == "extracted_declared_artifacts"
        and not artifact_receipts
    ):
        raise IdentityError("local routing artifact extraction scope is empty")
    artifact_by_id: dict[str, Mapping[str, Any]] = {}
    for artifact in artifact_receipts:
        if not isinstance(artifact, Mapping):
            raise IdentityError("local routing artifact receipt is invalid")
        artifact_fields = {
            "receipt_id",
            "bundle_sha256",
            "path_fingerprint",
            "role_sha256",
            "object_sha256",
            "object_size",
            "extractor_profile",
            "status",
            "coverage",
            "anchor_ids",
        }
        _require_keys(
            artifact,
            required=artifact_fields,
            allowed=artifact_fields,
            label="local routing artifact receipt",
        )
        for key in (
            "bundle_sha256",
            "path_fingerprint",
            "role_sha256",
            "object_sha256",
        ):
            validate_sha256(artifact.get(key), key)
        receipt_id = validate_identifier(
            artifact.get("receipt_id"),
            "local artifact receipt_id",
        )
        if receipt_id in artifact_by_id:
            raise IdentityError("local artifact receipt is duplicated")
        size = artifact.get("object_size")
        if (
            not isinstance(size, int)
            or isinstance(size, bool)
            or size < 1
            or size > MAX_LOCAL_MIGRATION_BYTES
        ):
            raise IdentityError(
                "local routing artifact receipt size is invalid"
            )
        if (
            artifact.get("status") not in {"available", "unavailable"}
            or artifact.get("coverage") not in {"full", "bounded", "failed"}
            or not isinstance(artifact.get("extractor_profile"), str)
        ):
            raise IdentityError(
                "local routing artifact extraction status is invalid"
            )
        anchor_ids = artifact.get("anchor_ids")
        if (
            not isinstance(anchor_ids, list)
            or len(anchor_ids) > MAX_ROUTING_ARTIFACT_BLOCKS
            or len(set(anchor_ids)) != len(anchor_ids)
        ):
            raise IdentityError(
                "local routing artifact anchor list is invalid"
            )
        for anchor_id in anchor_ids:
            validate_identifier(anchor_id, "local artifact anchor_id")
        bundle, bundle_sha = _load_artifact_extraction_bundle(
            data_dir,
            request,
            receipt_id,
            expected_source_kind="local",
        )
        if (
            bundle_sha != artifact.get("bundle_sha256")
            or bundle.get("path_fingerprint")
            != artifact.get("path_fingerprint")
            or bundle.get("role_sha256") != artifact.get("role_sha256")
            or bundle.get("object_sha256")
            != artifact.get("object_sha256")
            or bundle.get("object_size") != artifact.get("object_size")
            or bundle.get("extractor_profile")
            != artifact.get("extractor_profile")
            or bundle.get("status") != artifact.get("status")
            or bundle.get("coverage") != artifact.get("coverage")
            or [block["anchor_id"] for block in bundle["blocks"]]
            != anchor_ids
        ):
            raise IdentityError(
                "local artifact extraction receipt changed after review"
            )
        artifact_by_id[receipt_id] = artifact
    reviews = value.get("candidate_reviews")
    if not isinstance(reviews, list) or not reviews or len(reviews) > 8:
        raise IdentityError("local routing review candidates are invalid")
    reviewed_ids: set[str] = set()
    for review in reviews:
        if not isinstance(review, Mapping):
            raise IdentityError("local routing review candidate is invalid")
        review_fields = {
            "task_id",
            "verdict",
            "local_turn_anchor_sha256",
            "remote_conversation_anchors",
            "contradictions_sha256",
            "identity_assessment",
            "version_assessment",
            "dimension_matrix",
            "artifact_pairs",
            "local_artifact_gaps",
            "uncompared_remote_artifacts",
            "rationale_sha256",
            "remote_evidence_receipt_sha256",
        }
        _require_keys(
            review,
            required=review_fields,
            allowed=review_fields,
            label="local routing candidate receipt",
        )
        task_id = validate_identifier(review.get("task_id"), "task_id")
        if task_id in reviewed_ids:
            raise IdentityError(
                "local routing review candidate receipt is duplicated"
            )
        reviewed_ids.add(task_id)
        if review.get("verdict") not in {
            "consistent",
            "uncertain",
            "contradictory",
        }:
            raise IdentityError(
                "local routing candidate receipt verdict is invalid"
            )
        local_anchor_hashes = review.get("local_turn_anchor_sha256")
        if (
            not isinstance(local_anchor_hashes, list)
            or not local_anchor_hashes
            or len(local_anchor_hashes) > 100
            or len(set(local_anchor_hashes)) != len(local_anchor_hashes)
            or any(
                anchor not in reviewed_anchor_hashes
                for anchor in local_anchor_hashes
            )
        ):
            raise IdentityError(
                "local routing candidate receipt anchors are invalid"
            )
        for anchor in local_anchor_hashes:
            validate_sha256(anchor, "local routing candidate turn anchor")
        for key in (
            "contradictions_sha256",
            "rationale_sha256",
            "remote_evidence_receipt_sha256",
        ):
            validate_sha256(review.get(key), key)
        if review.get("identity_assessment") not in {
            "same_work_lineage",
            "related_work",
            "different_work",
            "uncertain",
        } or review.get("version_assessment") not in {
            "byte_identical",
            "local_predecessor",
            "local_successor",
            "parallel_revision",
            "structural_rewrite",
            "unknown",
        }:
            raise IdentityError(
                "local routing candidate receipt identity/version is invalid"
            )
        if (
            review.get("verdict") == "consistent"
            and review.get("identity_assessment") != "same_work_lineage"
        ):
            raise IdentityError(
                "consistent routing receipt lost same-lineage identity"
            )
        remote_anchors = review.get("remote_conversation_anchors")
        if (
            not isinstance(remote_anchors, list)
            or not remote_anchors
            or len(remote_anchors) > 8
        ):
            raise IdentityError(
                "local routing candidate receipt has no remote content anchors"
            )
        remote_anchor_keys: set[tuple[str, str]] = set()
        for anchor in remote_anchors:
            if not isinstance(anchor, Mapping):
                raise IdentityError(
                    "local routing remote conversation anchor is invalid"
                )
            _require_keys(
                anchor,
                required={
                    "source_id",
                    "revision_id",
                    "message_ordinals",
                },
                allowed={
                    "source_id",
                    "revision_id",
                    "message_ordinals",
                },
                label="local routing remote conversation anchor",
            )
            source_id = validate_identifier(
                anchor.get("source_id"),
                "local routing remote source_id",
            )
            revision_id = validate_identifier(
                anchor.get("revision_id"),
                "local routing remote revision_id",
            )
            anchor_key = (source_id, revision_id)
            if anchor_key in remote_anchor_keys:
                raise IdentityError(
                    "local routing remote conversation anchor is duplicated"
                )
            remote_anchor_keys.add(anchor_key)
            ordinals = anchor.get("message_ordinals")
            if (
                not isinstance(ordinals, list)
                or not ordinals
                or len(ordinals) > 100
                or len(set(ordinals)) != len(ordinals)
                or any(
                    not isinstance(ordinal, int)
                    or isinstance(ordinal, bool)
                    or ordinal < 0
                    for ordinal in ordinals
                )
            ):
                raise IdentityError(
                    "local routing remote message anchors are invalid"
                )
        artifact_pairs = review.get("artifact_pairs")
        if not isinstance(artifact_pairs, list) or len(artifact_pairs) > 32:
            raise IdentityError(
                "local routing candidate receipt artifact pairs are invalid"
            )
        pair_keys: set[tuple[str, str]] = set()
        local_artifact_anchor_ids: set[str] = set()
        remote_artifact_anchor_ids: set[str] = set()
        exact_object_pair = False
        full_bidirectional = bool(artifact_pairs)
        for pair in artifact_pairs:
            if not isinstance(pair, Mapping):
                raise IdentityError(
                    "local routing candidate receipt artifact pair is invalid"
                )
            _require_keys(
                pair,
                required={
                    "local_receipt_id",
                    "local_bundle_sha256",
                    "remote_receipt_id",
                    "remote_bundle_sha256",
                    "remote_artifact_id",
                    "local_object_sha256",
                    "remote_object_sha256",
                },
                allowed={
                    "local_receipt_id",
                    "local_bundle_sha256",
                    "remote_receipt_id",
                    "remote_bundle_sha256",
                    "remote_artifact_id",
                    "local_object_sha256",
                    "remote_object_sha256",
                },
                label="local routing candidate artifact pair",
            )
            local_receipt_id = validate_identifier(
                pair.get("local_receipt_id"),
                "local artifact receipt_id",
            )
            local_receipt = artifact_by_id.get(local_receipt_id)
            if local_receipt is None:
                raise IdentityError(
                    "local routing candidate has an unknown local extraction"
                )
            local_bundle_sha = validate_sha256(
                pair.get("local_bundle_sha256"),
                "local artifact bundle_sha256",
            )
            if local_bundle_sha != local_receipt.get("bundle_sha256"):
                raise IdentityError(
                    "local artifact bundle changed after candidate review"
                )
            remote_receipt_id = validate_identifier(
                pair.get("remote_receipt_id"),
                "remote artifact receipt_id",
            )
            remote_bundle_sha = validate_sha256(
                pair.get("remote_bundle_sha256"),
                "remote artifact bundle_sha256",
            )
            remote_bundle, observed_remote_bundle_sha = (
                _load_artifact_extraction_bundle(
                    data_dir,
                    request,
                    remote_receipt_id,
                    expected_source_kind="remote",
                    expected_task_id=task_id,
                )
            )
            if observed_remote_bundle_sha != remote_bundle_sha:
                raise IdentityError(
                    "remote artifact bundle changed after candidate review"
                )
            artifact_id = validate_identifier(
                pair.get("remote_artifact_id"),
                "local routing remote artifact_id",
            )
            if artifact_id != remote_bundle.get("artifact_id"):
                raise IdentityError(
                    "remote artifact receipt was forged or crossed candidates"
                )
            local_object_sha = validate_sha256(
                pair.get("local_object_sha256"),
                "local artifact object_sha256",
            )
            remote_object_sha = validate_sha256(
                pair.get("remote_object_sha256"),
                "remote artifact object_sha256",
            )
            if (
                local_object_sha != local_receipt.get("object_sha256")
                or remote_object_sha != remote_bundle.get("object_sha256")
            ):
                raise IdentityError(
                    "artifact version anchors changed after candidate review"
                )
            pair_key = (local_receipt_id, remote_receipt_id)
            if pair_key in pair_keys:
                raise IdentityError(
                    "local routing candidate receipt artifact pair is duplicated"
                )
            pair_keys.add(pair_key)
            local_artifact_anchor_ids.update(
                str(anchor_id)
                for anchor_id in local_receipt["anchor_ids"]
            )
            remote_artifact_anchor_ids.update(
                str(block["anchor_id"])
                for block in remote_bundle["blocks"]
            )
            exact_object_pair = exact_object_pair or (
                local_object_sha == remote_object_sha
                and local_receipt.get("object_size")
                == remote_bundle.get("object_size")
            )
            full_bidirectional = full_bidirectional and (
                local_receipt.get("status") == "available"
                and local_receipt.get("coverage") == "full"
                and remote_bundle.get("status") == "available"
                and remote_bundle.get("coverage") == "full"
            )
        if (
            review.get("version_assessment") == "byte_identical"
            and not exact_object_pair
        ):
            raise IdentityError(
                "byte-identical routing receipt has no exact object pair"
            )
        dimensions = review.get("dimension_matrix")
        if (
            not isinstance(dimensions, list)
            or len(dimensions) != len(ROUTING_ARTIFACT_DIMENSIONS)
        ):
            raise IdentityError(
                "local routing candidate receipt dimension matrix is invalid"
            )
        seen_dimensions: set[str] = set()
        for dimension in dimensions:
            if not isinstance(dimension, Mapping):
                raise IdentityError(
                    "local routing candidate receipt dimension is invalid"
                )
            dimension_fields = {
                "dimension",
                "relation",
                "local_anchor_ids",
                "remote_anchor_ids",
                "summary",
                "summary_sha256",
            }
            _require_keys(
                dimension,
                required=dimension_fields,
                allowed=dimension_fields,
                label="local routing candidate receipt dimension",
            )
            name = dimension.get("dimension")
            if (
                name not in ROUTING_ARTIFACT_DIMENSIONS
                or name in seen_dimensions
            ):
                raise IdentityError(
                    "local routing candidate receipt dimension is duplicated"
                )
            seen_dimensions.add(str(name))
            relation = dimension.get("relation")
            if relation not in {
                "preserved",
                "evolved",
                "added",
                "removed",
                "contradictory",
                "unrelated",
                "unknown",
            }:
                raise IdentityError(
                    "local routing candidate receipt relation is invalid"
                )
            summary = _bounded_private_text(
                dimension.get("summary"),
                "routing dimension summary",
                maximum_bytes=2000,
            )
            summary_sha = validate_sha256(
                dimension.get("summary_sha256"),
                "routing dimension summary_sha256",
            )
            if sha256_bytes(summary.encode("utf-8")) != summary_sha:
                raise IdentityError(
                    "routing dimension summary changed after review"
                )
            for key, available in (
                ("local_anchor_ids", local_artifact_anchor_ids),
                ("remote_anchor_ids", remote_artifact_anchor_ids),
            ):
                ids = dimension.get(key)
                if (
                    not isinstance(ids, list)
                    or len(ids) > 64
                    or len(set(ids)) != len(ids)
                ):
                    raise IdentityError(
                        "local routing dimension anchor list is invalid"
                    )
                for anchor_id in ids:
                    validate_identifier(
                        anchor_id,
                        "routing artifact anchor_id",
                    )
                    if anchor_id not in available:
                        raise IdentityError(
                            "routing dimension has a forged or cross-candidate "
                            "artifact anchor"
                        )
            if review.get("verdict") == "consistent" and relation in {
                "contradictory",
                "unrelated",
                "unknown",
            }:
                raise IdentityError(
                    "consistent routing receipt has an unresolved dimension"
                )
            if (
                review.get("verdict") == "consistent"
                and full_bidirectional
                and (
                    not dimension["local_anchor_ids"]
                    or not dimension["remote_anchor_ids"]
                )
            ):
                raise IdentityError(
                    "consistent routing receipt lacks bidirectional artifact "
                    "anchors"
                )
        if seen_dimensions != set(ROUTING_ARTIFACT_DIMENSIONS):
            raise IdentityError(
                "local routing receipt does not cover all dimensions"
            )
        local_gaps = review.get("local_artifact_gaps")
        if not isinstance(local_gaps, list) or len(local_gaps) > 32:
            raise IdentityError(
                "local routing candidate receipt gaps are invalid"
            )
        gap_receipt_ids: set[str] = set()
        paired_local_ids = {
            str(pair["local_receipt_id"]) for pair in artifact_pairs
        }
        for gap in local_gaps:
            if not isinstance(gap, Mapping):
                raise IdentityError(
                    "local routing candidate receipt gap is invalid"
                )
            gap_fields = {
                "local_receipt_id",
                "reason",
                "reason_sha256",
            }
            _require_keys(
                gap,
                required=gap_fields,
                allowed=gap_fields,
                label="local routing candidate receipt gap",
            )
            receipt_id = validate_identifier(
                gap.get("local_receipt_id"),
                "local routing gap receipt_id",
            )
            if (
                receipt_id not in artifact_by_id
                or receipt_id in paired_local_ids
                or receipt_id in gap_receipt_ids
            ):
                raise IdentityError(
                    "local routing candidate receipt gap scope is invalid"
                )
            reason = _bounded_private_text(
                gap.get("reason"),
                "local routing artifact gap reason",
                maximum_bytes=2000,
            )
            if sha256_bytes(reason.encode("utf-8")) != validate_sha256(
                gap.get("reason_sha256"),
                "local routing artifact gap reason_sha256",
            ):
                raise IdentityError(
                    "local routing artifact gap reason changed"
                )
            gap_receipt_ids.add(receipt_id)
        if paired_local_ids | gap_receipt_ids != set(artifact_by_id):
            raise IdentityError(
                "local routing candidate receipt hides a local artifact"
            )
        if review.get("verdict") == "consistent" and gap_receipt_ids:
            raise IdentityError(
                "consistent routing receipt contains a local artifact gap"
            )
        uncompared_remote = review.get("uncompared_remote_artifacts")
        if (
            not isinstance(uncompared_remote, list)
            or len(uncompared_remote) > 1000
            or len(set(uncompared_remote)) != len(uncompared_remote)
        ):
            raise IdentityError(
                "uncompared remote artifact disclosure is invalid"
            )
        for artifact_id in uncompared_remote:
            validate_identifier(
                artifact_id,
                "uncompared remote artifact_id",
            )
    if reviewed_ids != set(request.get("candidate_task_ids", [])):
        raise IdentityError(
            "local routing review receipt does not cover the full candidate "
            "catalog"
        )
    _verify_codex_session_prefix(request, value)
    return value, sha256_bytes(canonical_json_bytes(value))


def _routing_choice_artifact_disclosures(
    remote: RemoteTaskState,
    review: Mapping[str, Any],
) -> Mapping[str, Any]:
    raw_artifacts = remote.manifest.get("artifacts")
    if not isinstance(raw_artifacts, list):
        raise VerificationError("candidate artifact manifest is invalid")
    artifacts: dict[str, Mapping[str, Any]] = {}
    if len(raw_artifacts) > MAX_ROUTING_CANDIDATE_ARTIFACTS:
        raise IdentityError(
            "candidate has too many artifacts for complete bounded disclosure"
        )
    for artifact in raw_artifacts:
        if not isinstance(artifact, Mapping):
            raise VerificationError("candidate artifact entry is invalid")
        _validate_artifact(artifact)
        artifact_id = str(artifact["artifact_id"])
        if artifact_id in artifacts:
            raise VerificationError(
                "candidate artifact identity is duplicated"
            )
        artifacts[artifact_id] = artifact
    pairs = review.get("artifact_pairs")
    if not isinstance(pairs, list):
        raise IdentityError("candidate artifact pair receipt is invalid")
    paired_remote_ids = {
        str(pair["remote_artifact_id"])
        for pair in pairs
        if isinstance(pair, Mapping)
    }
    if not paired_remote_ids.issubset(artifacts):
        raise IdentityError(
            "candidate artifact pair is outside the verified manifest"
        )
    disclosed = review.get("uncompared_remote_artifacts")
    expected_uncompared = sorted(set(artifacts) - paired_remote_ids)
    if disclosed != expected_uncompared:
        raise IdentityError(
            "candidate review hides or invents an uncompared remote artifact"
        )
    local_gaps = review.get("local_artifact_gaps")
    if not isinstance(local_gaps, list):
        raise IdentityError("candidate local artifact gap receipt is invalid")
    return {
        "dimension_comparison": [
            {
                "dimension": row["dimension"],
                "relation": row["relation"],
                "summary": row["summary"],
            }
            for row in review["dimension_matrix"]
        ],
        "local_artifact_gaps": [
            {
                "reason": gap["reason"],
            }
            for gap in local_gaps
        ],
        "local_artifact_gap_count": len(local_gaps),
        "uncompared_remote_artifacts": [
            {
                "artifact_id": artifact_id,
                "display_name": artifacts[artifact_id]["display_name"],
                "role": artifacts[artifact_id]["role"],
                "sha256": artifacts[artifact_id]["sha256"],
                "size": artifacts[artifact_id]["size"],
            }
            for artifact_id in expected_uncompared
        ],
        "uncompared_remote_artifact_count": len(expected_uncompared),
        "artifact_evidence_persistence": {
            "extracted_blocks": "private_device_only",
            "dimension_summaries": "private_device_only",
            "uploaded": False,
        },
    }


def prepare_routing_choice_command(
    args: argparse.Namespace,
    engine: SyncEngine,
) -> Mapping[str, Any]:
    request_id = validate_identifier(args.request_id, "routing_request_id")
    requested = getattr(args, "task_id", None)
    if not isinstance(requested, list):
        requested = [requested] if requested is not None else []
    shortlist: list[str] = []
    for value in requested:
        task_id = validate_identifier(value, "task_id")
        if task_id not in shortlist:
            shortlist.append(task_id)
    if not shortlist or len(shortlist) > 8:
        raise IdentityError(
            "routing choice requires one to eight inspected candidates"
        )

    with FileLock(engine.lock_path):
        request_path, request, catalog = engine._verified_routing_request(
            request_id
        )
        if request.get("state") != "pending":
            raise IdentityError("routing request is not awaiting a choice")
        local_review, local_review_sha = _load_local_routing_review_receipt(
            engine.data_dir,
            request,
        )
        reviewed = {
            str(item["task_id"]): item
            for item in local_review["candidate_reviews"]
            if isinstance(item, Mapping)
        }
        receipts: dict[str, str] = {}
        choices: list[Mapping[str, Any]] = []
        for task_id in shortlist:
            remote = catalog.get(task_id)
            if remote is None:
                raise IdentityError(
                    "routing choice contains an inactive candidate"
                )
            local_candidate_review = reviewed.get(task_id)
            if local_candidate_review is None:
                raise IdentityError(
                    "routing choice contains a candidate whose actual local "
                    "content comparison was not recorded"
                )
            if local_candidate_review.get("verdict") != "consistent":
                raise IdentityError(
                    "only a fully consistent candidate can be offered; "
                    "uncertain evidence requires more inspection"
                )
            _receipt, receipt_sha = _load_routing_evidence_receipt(
                engine.data_dir,
                request,
                remote,
            )
            if (
                local_candidate_review.get(
                    "remote_evidence_receipt_sha256"
                )
                != receipt_sha
            ):
                raise IdentityError(
                    "local content comparison no longer matches the verified "
                    "remote candidate evidence"
                )
            receipts[task_id] = receipt_sha
            choice_code = str(len(choices) + 1)
            artifact_disclosures = _routing_choice_artifact_disclosures(
                remote,
                local_candidate_review,
            )
            choices.append(
                {
                    "choice_code": choice_code,
                    "task_id": task_id,
                    "display_title": str(
                        remote.task.get("display_title") or task_id
                    )[:300],
                    "purpose": str(
                        remote.task.get("purpose") or ""
                    )[:1000],
                    "generation": remote.current["generation"],
                    "snapshot_id": remote.current["snapshot_id"],
                    "content_verdict": local_candidate_review["verdict"],
                    "identity_assessment": local_candidate_review[
                        "identity_assessment"
                    ],
                    "version_assessment": local_candidate_review[
                        "version_assessment"
                    ],
                    "aligned_dimensions": [
                        row["dimension"]
                        for row in local_candidate_review[
                            "dimension_matrix"
                        ]
                        if row["relation"] in {"preserved", "evolved"}
                    ],
                    "different_dimensions": [
                        row["dimension"]
                        for row in local_candidate_review[
                            "dimension_matrix"
                        ]
                        if row["relation"]
                        in {"evolved", "added", "removed"}
                    ],
                    "remote_conversation_anchor_count": sum(
                        len(anchor["message_ordinals"])
                        for anchor in local_candidate_review[
                            "remote_conversation_anchors"
                        ]
                    ),
                    "artifact_pair_count": len(
                        local_candidate_review["artifact_pairs"]
                    ),
                    "artifact_manifest_count": len(
                        remote.manifest.get("artifacts") or []
                    ),
                    **artifact_disclosures,
                }
            )
        now_epoch = int(time.time())
        choice = {
            "schema_version": ROUTING_CHOICE_SCHEMA,
            "request_id": request_id,
            "state": "awaiting_user_reply",
            "shortlist_task_ids": shortlist,
            "selection_codes": {
                str(index + 1): task_id
                for index, task_id in enumerate(shortlist)
            },
            "remote_commit_sha": request["remote_commit_sha"],
            "candidate_set_sha256": _routing_candidate_set_sha256(request),
            "workspace_identity_fingerprint": request[
                "workspace_identity_fingerprint"
            ],
            "evidence_receipt_sha256": receipts,
            "local_evidence_receipt_sha256": local_review_sha,
            "operation": "initial_binding",
            "previous_binding_id": None,
            "previous_task_id": None,
            "workspace_mode": None,
            "created_at": utc_now(),
            "completed_at": None,
            "expires_at_epoch": now_epoch + ROUTING_CHOICE_TTL_SECONDS,
        }
        atomic_write_json(
            _routing_choice_path(engine.data_dir, request_id),
            choice,
        )
        request["state"] = "awaiting_user_reply"
        request["pending_turn_id"] = None
        request["pending_prompt"] = None
        request["updated_at"] = utc_now()
        atomic_write_json(request_path, request)
    return {
        "schema_version": "memory-vault-routing-choice-ready/v1",
        "status": "awaiting_user_choice",
        "request_id": request_id,
        "choices": choices,
        "reject_choice_code": "0",
        "next_action": (
            "show_numbered_content_evidence_then_ask_for_one_code_only"
        ),
        "automatic_binding_performed": False,
    }


def begin_route_switch_review_command(
    args: argparse.Namespace,
    engine: SyncEngine,
) -> Mapping[str, Any]:
    """Open a content-review request for one already-bound native task."""

    session_id = args.existing_session_id
    if not isinstance(session_id, str) or not session_id:
        raise IdentityError("existing native task identity is missing")
    workspace = Path(args.workspace).expanduser().resolve(strict=True)
    assert_plain_path(workspace, require_file=False)
    if not any(
        _path_is_within(workspace, Path(root).resolve())
        for root in engine.config["privacy"]["allowed_roots"]
    ):
        raise IdentityError("route switch workspace is outside an allowed root")
    workspace_mode = str(args.workspace_mode)
    if workspace_mode not in {"session-only", "shared", "replace"}:
        raise IdentityError("route switch workspace mode is invalid")

    with FileLock(engine.lock_path):
        engine.git.ensure()
        source_id, _source, _external_key = resolve_source_record(
            engine.git,
            session_id,
        )
        previous_route = _active_primary_source_route(
            engine.git,
            source_id,
        )
        if previous_route is None:
            raise IdentityError(
                "route switching requires an existing exact source route"
            )
        routing = engine._ensure_routing_request(
            {
                "session_id": session_id,
                "cwd": str(workspace),
            }
        )
        if routing is None:
            raise IdentityError("no active semantic task candidates are available")
        request, _context = routing
        request_path = _routing_request_path(
            engine.data_dir,
            str(request["request_id"]),
        )
        request["state"] = "pending"
        request["review_nonce"] = uuid.uuid4().hex
        request["pending_turn_id"] = None
        request["pending_prompt"] = None
        request["updated_at"] = utc_now()
        atomic_write_json(request_path, request)
        with contextlib.suppress(FileNotFoundError):
            _routing_choice_path(
                engine.data_dir,
                str(request["request_id"]),
            ).unlink()
        with contextlib.suppress(FileNotFoundError):
            _local_routing_review_receipt_path(
                engine.data_dir,
                str(request["request_id"]),
            ).unlink()
        candidates = _routing_candidate_rows(
            {
                task_id: remote
                for task_id, remote in _discover_remote_task_catalog(
                    engine.git
                )[0].items()
                if task_id in request["candidate_task_ids"]
            }
        )
    return {
        "schema_version": "memory-vault-route-switch-review/v1",
        "status": "content_review_required",
        "request_id": request["request_id"],
        "previous_task_id": previous_route.task_id,
        "previous_binding_id": previous_route.binding_id,
        "workspace_mode": workspace_mode,
        "candidates": candidates,
        "next_action": (
            "read_exact_local_conversation_and_verified_candidate_evidence"
        ),
        "automatic_binding_performed": False,
    }


def prepare_route_switch_choice_command(
    args: argparse.Namespace,
    engine: SyncEngine,
) -> Mapping[str, Any]:
    """Pin inspected route-correction choices before the user's next reply."""

    request_id = validate_identifier(args.request_id, "routing_request_id")
    session_id = args.existing_session_id
    if not isinstance(session_id, str) or not session_id:
        raise IdentityError("existing native task identity is missing")
    workspace = Path(args.workspace).expanduser().resolve(strict=True)
    assert_plain_path(workspace, require_file=False)
    workspace_mode = str(args.workspace_mode)
    if workspace_mode not in {"session-only", "shared", "replace"}:
        raise IdentityError("route switch workspace mode is invalid")
    requested = getattr(args, "task_id", None)
    if not isinstance(requested, list):
        requested = [requested] if requested is not None else []
    shortlist: list[str] = []
    for value in requested:
        task_id = validate_identifier(value, "task_id")
        if task_id not in shortlist:
            shortlist.append(task_id)
    if not shortlist or len(shortlist) > 8:
        raise IdentityError(
            "route switch choice requires one to eight inspected candidates"
        )

    with FileLock(engine.lock_path):
        request_path, request, catalog = engine._verified_routing_request(
            request_id
        )
        if request.get("state") != "pending":
            raise IdentityError("route switch request is not awaiting a choice")
        device = _device_state(engine.data_dir)
        if (
            request.get("session_id") != session_id
            or request.get("session_key")
            != _session_key(device, session_id)
        ):
            raise IdentityError("route switch request belongs to another task")
        _assert_routing_request_matches_workspace(
            request,
            str(workspace),
            engine.config["privacy"]["allowed_roots"],
        )
        source_id, _source, _external_key = resolve_source_record(
            engine.git,
            session_id,
        )
        previous_route = _active_primary_source_route(
            engine.git,
            source_id,
        )
        if previous_route is None:
            raise IdentityError("existing task route is missing")
        local_review, local_review_sha = _load_local_routing_review_receipt(
            engine.data_dir,
            request,
        )
        reviewed = {
            str(item["task_id"]): item
            for item in local_review["candidate_reviews"]
            if isinstance(item, Mapping)
        }
        receipts: dict[str, str] = {}
        choices: list[Mapping[str, Any]] = []
        for task_id in shortlist:
            remote = catalog.get(task_id)
            if remote is None:
                raise IdentityError(
                    "route switch choice contains an inactive candidate"
                )
            local_candidate_review = reviewed.get(task_id)
            if local_candidate_review is None:
                raise IdentityError(
                    "route switch contains a candidate whose actual local "
                    "content comparison was not recorded"
                )
            if local_candidate_review.get("verdict") != "consistent":
                raise IdentityError(
                    "only a fully consistent route-switch candidate can be "
                    "offered; uncertain evidence requires more inspection"
                )
            if (
                task_id == previous_route.task_id
                and not _source_route_requires_content_revalidation(
                    previous_route
                )
            ):
                raise IdentityError(
                    "route switch target is already the confirmed active task"
                )
            _receipt, receipt_sha = _load_routing_evidence_receipt(
                engine.data_dir,
                request,
                remote,
            )
            if (
                local_candidate_review.get(
                    "remote_evidence_receipt_sha256"
                )
                != receipt_sha
            ):
                raise IdentityError(
                    "local route-switch comparison no longer matches the "
                    "verified remote candidate evidence"
                )
            receipts[task_id] = receipt_sha
            choice_code = str(len(choices) + 1)
            artifact_disclosures = _routing_choice_artifact_disclosures(
                remote,
                local_candidate_review,
            )
            choices.append(
                {
                    "choice_code": choice_code,
                    "task_id": task_id,
                    "display_title": str(
                        remote.task.get("display_title") or task_id
                    )[:300],
                    "purpose": str(
                        remote.task.get("purpose") or ""
                    )[:1000],
                    "generation": remote.current["generation"],
                    "snapshot_id": remote.current["snapshot_id"],
                    "content_verdict": local_candidate_review["verdict"],
                    "identity_assessment": local_candidate_review[
                        "identity_assessment"
                    ],
                    "version_assessment": local_candidate_review[
                        "version_assessment"
                    ],
                    "aligned_dimensions": [
                        row["dimension"]
                        for row in local_candidate_review[
                            "dimension_matrix"
                        ]
                        if row["relation"] in {"preserved", "evolved"}
                    ],
                    "different_dimensions": [
                        row["dimension"]
                        for row in local_candidate_review[
                            "dimension_matrix"
                        ]
                        if row["relation"]
                        in {"evolved", "added", "removed"}
                    ],
                    "remote_conversation_anchor_count": sum(
                        len(anchor["message_ordinals"])
                        for anchor in local_candidate_review[
                            "remote_conversation_anchors"
                        ]
                    ),
                    "artifact_pair_count": len(
                        local_candidate_review["artifact_pairs"]
                    ),
                    "artifact_manifest_count": len(
                        remote.manifest.get("artifacts") or []
                    ),
                    **artifact_disclosures,
                }
            )
        choice = {
            "schema_version": ROUTING_CHOICE_SCHEMA,
            "request_id": request_id,
            "state": "awaiting_user_reply",
            "shortlist_task_ids": shortlist,
            "selection_codes": {
                str(index + 1): task_id
                for index, task_id in enumerate(shortlist)
            },
            "remote_commit_sha": request["remote_commit_sha"],
            "candidate_set_sha256": _routing_candidate_set_sha256(request),
            "workspace_identity_fingerprint": request[
                "workspace_identity_fingerprint"
            ],
            "evidence_receipt_sha256": receipts,
            "local_evidence_receipt_sha256": local_review_sha,
            "operation": "route_switch",
            "previous_binding_id": previous_route.binding_id,
            "previous_task_id": previous_route.task_id,
            "workspace_mode": workspace_mode,
            "created_at": utc_now(),
            "completed_at": None,
            "expires_at_epoch": (
                int(time.time()) + ROUTING_CHOICE_TTL_SECONDS
            ),
        }
        atomic_write_json(
            _routing_choice_path(engine.data_dir, request_id),
            choice,
        )
        request["state"] = "awaiting_user_reply"
        request["pending_turn_id"] = None
        request["pending_prompt"] = None
        request["updated_at"] = utc_now()
        atomic_write_json(request_path, request)
    return {
        "schema_version": "memory-vault-route-switch-choice-ready/v1",
        "status": "awaiting_user_choice",
        "request_id": request_id,
        "previous_task_id": previous_route.task_id,
        "workspace_mode": workspace_mode,
        "choices": choices,
        "reject_choice_code": "0",
        "next_action": (
            "show_numbered_content_evidence_then_ask_for_one_code_only"
        ),
        "automatic_binding_performed": False,
    }


def _validate_auto_match_assessment(
    *,
    goal_score: int,
    distinctive_score: int,
    runner_up_score: int,
    contradiction_count: int,
    evidence_sha256: str,
) -> str:
    for label, score in (
        ("goal_score", goal_score),
        ("distinctive_score", distinctive_score),
        ("runner_up_score", runner_up_score),
    ):
        if (
            not isinstance(score, int)
            or isinstance(score, bool)
            or not 0 <= score <= 10000
        ):
            raise IdentityError(f"{label} must be between 0 and 10000")
    if (
        not isinstance(contradiction_count, int)
        or isinstance(contradiction_count, bool)
        or contradiction_count < 0
    ):
        raise IdentityError("contradiction_count is invalid")
    if (
        goal_score < AUTO_MATCH_MIN_SCORE_BP
        or distinctive_score < AUTO_MATCH_MIN_SCORE_BP
        or min(goal_score, distinctive_score) - runner_up_score
        < AUTO_MATCH_MIN_MARGIN_BP
        or contradiction_count != 0
    ):
        raise IdentityError(
            "semantic assessment is not eligible for automatic provisional matching"
        )
    return validate_sha256(evidence_sha256, "semantic evidence digest")


def _source_for_routing_request(
    engine: SyncEngine,
    request: Mapping[str, Any],
) -> tuple[str, Mapping[str, Any], dict[str, bytes]]:
    external_key = validate_sha256(
        request.get("source_external_key_sha256"),
        "routing source identity",
    )
    matches: list[tuple[str, Mapping[str, Any]]] = []
    for path in engine.git.list_paths("sources"):
        match = re.fullmatch(r"sources/([^/]+)/SOURCE\.json", path)
        if match is None:
            continue
        source = engine.git.show_json(path)
        if source.get("external_source_key_sha256") == external_key:
            _validate_source(source)
            matches.append(
                (
                    validate_identifier(match.group(1), "source_id"),
                    source,
                )
            )
    if len(matches) > 1:
        raise ConflictError("routing source matches multiple remote sources")
    if matches:
        return matches[0][0], matches[0][1], {}
    source_id = validate_identifier(
        f"src-codex-{external_key[:32]}",
        "source_id",
    )
    source_path = f"sources/{source_id}/SOURCE.json"
    if engine.git.file_exists(source_path):
        raise ConflictError("deterministic routing source path is occupied")
    revision_id = validate_identifier(
        f"rev-routing-{external_key[:32]}",
        "revision_id",
    )
    now = utc_now()
    source = {
        "schema_version": "source/v1",
        "source_id": source_id,
        "source_type": "codex_task",
        "external_source_key_sha256": external_key,
        "source_instance_id": None,
        "visibility": "private",
        "sensitivity": "restricted",
        "current_revision_id": revision_id,
        "revisions": [
            {
                "revision_id": revision_id,
                "previous_revision_id": None,
                "source_sequence": 0,
                "captured_at": now,
                "coverage": "unknown",
                "content_ref": None,
                "content_sha256": None,
                "redaction": {
                    "credentials_scanned": True,
                    "content_removed": True,
                    "reason": (
                        "Native task identity metadata; no prompt content "
                        "was stored in this revision."
                    ),
                },
            }
        ],
        "created_at": now,
    }
    _validate_source(source)
    assert_remote_safe(source)
    return source_id, source, {source_path: pretty_json_bytes(source)}


def _assert_source_has_no_confirmed_route(
    engine: SyncEngine,
    source_id: str,
) -> None:
    if _active_primary_source_route(engine.git, source_id) is not None:
        raise ConflictError("routing source already has a confirmed task")


def _stage_pending_routing_prompt(
    engine: SyncEngine,
    request: Mapping[str, Any],
) -> None:
    turn_id = request.get("pending_turn_id")
    prompt = request.get("pending_prompt")
    if not isinstance(turn_id, str) or not isinstance(prompt, str):
        return
    session_id = str(request["session_id"])
    device = _device_state(engine.data_dir)
    loaded = _load_session(engine.data_dir, device, session_id)
    if loaded is None:
        raise IdentityError("matched task session was not initialized")
    session_key, _session = loaded
    turn_key = _turn_key(device, session_id, turn_id)
    atomic_write_json(
        _prompt_path(engine.data_dir, session_key, turn_key),
        {
            "schema_version": "memory-vault-sync-prompt/v1",
            "turn_key": turn_key,
            "task_id": _session["task_id"],
            "prompt": scan_visible_text(prompt, "pending routing prompt"),
            "created_at": utc_now(),
        },
    )


def prepare_auto_match_command(
    args: argparse.Namespace,
    engine: SyncEngine,
) -> Mapping[str, Any]:
    if LEGACY_AUTO_BINDING_DISABLED:
        raise ConfigurationError(
            "legacy automatic matching is disabled because it did not verify "
            "full conversation and artifact evidence"
        )
    if not engine.config["matching"].get("auto_provisional"):
        raise ConfigurationError("automatic provisional matching is disabled")
    request_id = validate_identifier(args.request_id, "routing_request_id")
    task_id = validate_identifier(args.task_id, "task_id")
    evidence_digest = _validate_auto_match_assessment(
        goal_score=args.goal_score_bp,
        distinctive_score=args.distinctive_score_bp,
        runner_up_score=args.runner_up_score_bp,
        contradiction_count=args.contradiction_count,
        evidence_sha256=args.evidence_sha256,
    )
    with FileLock(engine.lock_path):
        request_path, request, catalog = engine._verified_routing_request(
            request_id
        )
        if request.get("state") not in {"pending", "provisional"}:
            raise IdentityError("task matching request is no longer pending")
        remote = catalog.get(task_id)
        if remote is None:
            raise IdentityError("selected task is not an active semantic task")
        device = _device_state(engine.data_dir)
        session_key = str(request["session_key"])
        existing_claim = _load_provisional_claim(
            engine.data_dir,
            session_key,
        )
        if existing_claim is not None:
            claim = existing_claim[1]
            if (
                claim.get("state") == "provisional_active"
                and claim.get("task_id") == task_id
                and claim.get("initial_evidence_digest_sha256")
                == evidence_digest
            ):
                verified = engine._verify_provisional_claim(
                    claim,
                    require_original_current=False,
                )
                return {
                    "schema_version": "memory-vault-auto-match/v1",
                    "status": "provisional_active",
                    "request_id": request_id,
                    "claim_id": claim["claim_id"],
                    "task_id": task_id,
                    "snapshot_id": verified.current["snapshot_id"],
                    "cloud_current_loaded": True,
                    "authority": "read_only_provisional",
                    "context": _continuation_context(
                        verified,
                        git=engine.git,
                        reference_source_ids=[str(claim["source_id"])],
                    ),
                    "next_action": "independent_consistency_check",
                }
            raise ConflictError(
                "this local task already has a different provisional claim"
            )
        source_id, source, files = _source_for_routing_request(
            engine,
            request,
        )
        _assert_source_has_no_confirmed_route(engine, source_id)
        source_sequence_from = len(source["revisions"])
        binding_key = sha256_bytes(
            (
                f"{source_id}\0{task_id}\0{request_id}\0{evidence_digest}"
            ).encode("utf-8")
        )
        binding_id = validate_identifier(
            f"bnd-proposed-{binding_key[:32]}",
            "binding_id",
        )
        binding_path = f"bindings/candidates/{binding_id}.json"
        if engine.git.file_exists(binding_path):
            raise ConflictError("provisional binding path is occupied")
        now = utc_now()
        proposal = {
            "schema_version": "binding/v1",
            "binding_id": binding_id,
            "subject": {"kind": "source", "id": source_id},
            "targets": [
                {
                    "semantic_task_id": task_id,
                    "relation": "source_for",
                    "role": "primary",
                }
            ],
            "effective_range": {
                "source_sequence_from": source_sequence_from,
                "source_sequence_to": None,
            },
            "state": "proposed",
            "confidence": "assistant_inferred",
            "confirmation_basis": None,
            "evidence": [
                {
                    "evidence_id": validate_identifier(
                        f"evidence-goal-{binding_key[:24]}",
                        "evidence_id",
                    ),
                    "kind": "content_similarity",
                    "strength": "strong",
                    "object_sha256": evidence_digest,
                    "method": "model-semantic-assessment-v1",
                    "score_basis_points": args.goal_score_bp,
                    "input_digest_sha256": evidence_digest,
                    "independence_group": "visible_goal",
                    "assertion": (
                        "The visible local goal uniquely matches this remote "
                        "semantic task under the fixed provisional policy."
                    ),
                },
                {
                    "evidence_id": validate_identifier(
                        f"evidence-distinct-{binding_key[:24]}",
                        "evidence_id",
                    ),
                    "kind": "content_similarity",
                    "strength": "strong",
                    "object_sha256": evidence_digest,
                    "method": "model-semantic-assessment-v1",
                    "score_basis_points": args.distinctive_score_bp,
                    "input_digest_sha256": evidence_digest,
                    "independence_group": "distinctive_context",
                    "assertion": (
                        "Distinctive visible concepts separate the selected "
                        "task from the runner-up candidate."
                    ),
                },
            ],
            "proposal_assessment": {
                "policy_version": "user-authorized-semantic-quorum-v1",
                "goal_score_basis_points": args.goal_score_bp,
                "distinctive_score_basis_points": args.distinctive_score_bp,
                "runner_up_score_basis_points": args.runner_up_score_bp,
                "runner_up_margin_basis_points": (
                    min(args.goal_score_bp, args.distinctive_score_bp)
                    - args.runner_up_score_bp
                ),
                "candidate_count": len(catalog),
                "independent_signal_groups": 2,
                "contradiction_count": args.contradiction_count,
                "evidence_digest_sha256": evidence_digest,
                "basis_remote_commit_sha": engine.git.head_sha(),
                "basis_current_blob_sha": remote.current_blob_sha,
            },
            "created_at": now,
            "created_by": {
                "actor_kind": "client",
                "actor_id": "memory-vault-sync",
            },
        }
        assert_remote_safe(proposal)
        files[binding_path] = pretty_json_bytes(proposal)
        transaction_id = validate_identifier(
            f"auto-proposal-{uuid.uuid4().hex}",
            "transaction_id",
        )
        with engine.git.create_worktree() as worktree:
            engine.git.write_generated_files(worktree, files)
            engine.git.commit_and_push(
                worktree,
                files,
                task_id,
                transaction_id,
            )
        engine.git.fetch()
        proposal_blob = engine.git.blob_sha(binding_path)
        claim_id = validate_identifier(
            f"claim-{binding_key[:32]}",
            "claim_id",
        )
        claim = {
            "schema_version": PROVISIONAL_CLAIM_SCHEMA,
            "claim_id": claim_id,
            "state": "provisional_active",
            "request_id": request_id,
            "session_key": session_key,
            "expected_source_key_sha256": request[
                "source_external_key_sha256"
            ],
            "source_id": source_id,
            "task_id": task_id,
            "proposal_binding_id": binding_id,
            "proposal_binding_path": binding_path,
            "proposal_binding_blob_sha": proposal_blob,
            "task_current_blob_sha": remote.current_blob_sha,
            "snapshot_id": remote.current["snapshot_id"],
            "policy_version": "user-authorized-semantic-quorum-v1",
            "initial_evidence_digest_sha256": evidence_digest,
            "goal_score_basis_points": args.goal_score_bp,
            "distinctive_score_basis_points": args.distinctive_score_bp,
            "runner_up_score_basis_points": args.runner_up_score_bp,
            "contradiction_count": args.contradiction_count,
            "local_history_role": "reference_only",
            "artifact_publication_blocked": True,
            "current_pointer_update_blocked": True,
            "created_at": now,
            "updated_at": now,
        }
        atomic_write_json(
            _provisional_claim_path(engine.data_dir, session_key),
            claim,
        )
        request["state"] = "provisional"
        request["updated_at"] = utc_now()
        atomic_write_json(request_path, request)
        identity = SourceIdentity(
            binding_id=binding_id,
            task_id=task_id,
            source_id=source_id,
            external_source_key_sha256=str(
                request["source_external_key_sha256"]
            ),
        )
        context = _continuation_context(
            remote,
            git=engine.git,
            reference_source_ids=[source_id],
        )
        context = _append_context_note(
            context,
            engine._routing_context(
                request,
                state="provisional_consistency_check",
                claim_id=claim_id,
            ),
            label="provisional routing control",
        )
        engine._session_start_state(
            {
                "session_id": request["session_id"],
                "cwd": request["workspace_root"],
            },
            identity,
            remote,
            continuation_context=context,
            source_id_override=source_id,
            source_external_key_override=str(
                request["source_external_key_sha256"]
            ),
            adoption={
                "mode": "provisional_existing_adoption",
                "state": "cloud_current_loaded",
                "cloud_snapshot_id": remote.current["snapshot_id"],
                "cloud_current_blob_sha": remote.current_blob_sha,
                "local_history_role": "reference_only",
                "artifact_publication_blocked": True,
            },
        )
        loaded = _load_session(
            engine.data_dir,
            device,
            str(request["session_id"]),
        )
        if loaded is None:
            raise VerificationError("provisional session was not created")
        loaded[1]["identity_kind"] = "provisional_source"
        loaded[1]["claim_id"] = claim_id
        _save_session(engine.data_dir, loaded[0], loaded[1])
    return {
        "schema_version": "memory-vault-auto-match/v1",
        "status": "provisional_active",
        "request_id": request_id,
        "claim_id": claim_id,
        "task_id": task_id,
        "snapshot_id": remote.current["snapshot_id"],
        "cloud_current_loaded": True,
        "authority": "read_only_provisional",
        "local_history_role": "reference_only",
        "artifacts_loaded": False,
        "context": context,
        "next_action": "independent_consistency_check",
    }


def _claim_by_id(
    data_dir: Path,
    claim_id: str,
) -> tuple[Path, dict[str, Any]]:
    target = validate_identifier(claim_id, "claim_id")
    root = data_dir / "state" / "provisional-claims"
    if not root.exists():
        raise IdentityError("provisional task claim is missing")
    paths = sorted(root.glob("*.json"))
    if len(paths) > 256:
        raise BusyError("too many provisional task claims")
    matches: list[tuple[Path, dict[str, Any]]] = []
    for path in paths:
        session_key = path.stem
        record = _load_provisional_claim(data_dir, session_key)
        if record is not None and record[1].get("claim_id") == target:
            matches.append(record)
    if len(matches) != 1:
        raise IdentityError("provisional task claim is missing or ambiguous")
    return matches[0]


def _activate_confirmed_routing(
    engine: SyncEngine,
    request: Mapping[str, Any],
    task_id: str,
) -> tuple[str, str]:
    session_id = str(request["session_id"])
    workspace = Path(str(request["workspace_root"])).resolve(strict=True)
    mode = "conversation_only"
    source_identity = resolve_source_identity(engine.git, session_id)
    if source_identity.task_id != task_id:
        raise IdentityError("confirmed routing target changed")
    remote = load_remote_task(engine.git, source_identity)
    context = _continuation_context(
        remote,
        git=engine.git,
        reference_source_ids=[source_identity.source_id],
    )
    context = _with_adoption_context(context, blocked=True)
    engine._session_start_state(
        {
            "session_id": session_id,
            "cwd": str(workspace),
        },
        source_identity,
        remote,
        continuation_context=context,
        source_id_override=source_identity.source_id,
        source_external_key_override=(
            source_identity.external_source_key_sha256
        ),
        adoption={
            "mode": "conversation_route",
            "state": "cloud_current_loaded",
            "cloud_snapshot_id": remote.current["snapshot_id"],
            "cloud_current_blob_sha": remote.current_blob_sha,
            "local_history_role": "reference_only",
            "artifact_publication_blocked": True,
        },
    )
    _stage_pending_routing_prompt(engine, request)
    return context, mode


def promote_auto_match_command(
    args: argparse.Namespace,
    engine: SyncEngine,
) -> Mapping[str, Any]:
    if LEGACY_AUTO_BINDING_DISABLED:
        raise ConfigurationError(
            "legacy automatic promotion is disabled because it did not verify "
            "full conversation and artifact evidence"
        )
    matching = engine.config["matching"]
    if not matching.get("auto_promote_after_consistency_check"):
        raise ConfigurationError("automatic semantic promotion is disabled")
    consistency_score = args.consistency_score_bp
    if (
        not isinstance(consistency_score, int)
        or isinstance(consistency_score, bool)
        or not AUTO_MATCH_MIN_CONSISTENCY_BP <= consistency_score <= 10000
        or args.contradiction_count != 0
    ):
        raise IdentityError(
            "cloud consistency check is not eligible for automatic promotion"
        )
    verification_digest = validate_sha256(
        args.evidence_sha256,
        "consistency evidence digest",
    )
    claim_path, claim = _claim_by_id(engine.data_dir, args.claim_id)
    if verification_digest == claim.get("initial_evidence_digest_sha256"):
        raise IdentityError(
            "consistency check must use an independent evidence digest"
        )
    request_path, request = _load_routing_request(
        engine.data_dir,
        str(claim["request_id"]),
    )
    with FileLock(engine.lock_path):
        engine.git.ensure()
        remote = engine._verify_provisional_claim(
            claim,
            require_original_current=True,
        )
        source_id = validate_identifier(claim["source_id"], "source_id")
        _assert_source_has_no_confirmed_route(engine, source_id)
        proposal = engine.git.show_json(str(claim["proposal_binding_path"]))
        proposal_assessment = proposal.get("proposal_assessment")
        if not isinstance(proposal_assessment, Mapping):
            raise IdentityError("provisional assessment is missing")
        binding_key = sha256_bytes(
            (
                f"{claim['proposal_binding_id']}\0{verification_digest}"
            ).encode("utf-8")
        )
        binding_id = validate_identifier(
            f"bnd-auto-{binding_key[:32]}",
            "binding_id",
        )
        binding_path = f"bindings/confirmed/{binding_id}.json"
        if engine.git.file_exists(binding_path):
            raise ConflictError("automatic confirmed binding path is occupied")
        now = utc_now()
        confirmed = {
            "schema_version": "binding/v1",
            "binding_id": binding_id,
            "subject": {"kind": "source", "id": source_id},
            "targets": [
                {
                    "semantic_task_id": claim["task_id"],
                    "relation": "source_for",
                    "role": "primary",
                }
            ],
            "effective_range": dict(proposal["effective_range"]),
            "state": "confirmed",
            "confidence": "assistant_inferred",
            "confirmation_basis": "user_authorized_semantic_quorum",
            "evidence": [
                {
                    "evidence_id": validate_identifier(
                        f"evidence-policy-{binding_key[:24]}",
                        "evidence_id",
                    ),
                    "kind": "user_policy_authorization",
                    "strength": "authoritative",
                    "assertion": (
                        "The user enabled automatic confirmation only after "
                        "a high-confidence provisional match and an independent "
                        "cloud consistency check."
                    ),
                },
                {
                    "evidence_id": validate_identifier(
                        f"evidence-initial-{binding_key[:24]}",
                        "evidence_id",
                    ),
                    "kind": "content_similarity",
                    "strength": "strong",
                    "object_sha256": claim[
                        "initial_evidence_digest_sha256"
                    ],
                    "method": "model-semantic-assessment-v1",
                    "score_basis_points": min(
                        int(claim["goal_score_basis_points"]),
                        int(claim["distinctive_score_basis_points"]),
                    ),
                    "input_digest_sha256": claim[
                        "initial_evidence_digest_sha256"
                    ],
                    "independence_group": "local_visible_task",
                    "assertion": (
                        "The initial local-task assessment uniquely selected "
                        "this semantic task."
                    ),
                },
                {
                    "evidence_id": validate_identifier(
                        f"evidence-verify-{binding_key[:24]}",
                        "evidence_id",
                    ),
                    "kind": "cloud_consistency_check",
                    "strength": "strong",
                    "object_sha256": verification_digest,
                    "method": "model-cloud-checkpoint-consistency-v1",
                    "score_basis_points": consistency_score,
                    "input_digest_sha256": verification_digest,
                    "independence_group": "verified_cloud_checkpoint",
                    "assertion": (
                        "An independent comparison with the verified cloud "
                        "checkpoint found no task-identity contradiction."
                    ),
                },
            ],
            "created_at": now,
            "created_by": {
                "actor_kind": "client",
                "actor_id": "memory-vault-sync",
            },
            "supersedes_binding_id": claim["proposal_binding_id"],
        }
        assert_remote_safe(confirmed)
        files = {binding_path: pretty_json_bytes(confirmed)}
        transaction_id = validate_identifier(
            f"auto-promote-{uuid.uuid4().hex}",
            "transaction_id",
        )
        with engine.git.create_worktree() as worktree:
            engine.git.write_generated_files(worktree, files)
            engine.git.commit_and_push(
                worktree,
                files,
                str(claim["task_id"]),
                transaction_id,
            )
        engine.git.fetch()
        source_identity = resolve_source_identity(
            engine.git,
            str(request["session_id"]),
        )
        if (
            source_identity.task_id != claim["task_id"]
            or source_identity.binding_id != binding_id
        ):
            raise VerificationError(
                "automatic confirmed task route could not be verified"
            )
        claim["state"] = "promoted"
        claim["updated_at"] = utc_now()
        atomic_write_json(claim_path, claim)
        request["state"] = "promoted"
        request["updated_at"] = utc_now()
        atomic_write_json(request_path, request)
    context, mode = _activate_confirmed_routing(
        engine,
        request,
        str(claim["task_id"]),
    )
    return {
        "schema_version": "memory-vault-auto-match/v1",
        "status": "confirmed",
        "task_id": claim["task_id"],
        "snapshot_id": remote.current["snapshot_id"],
        "cloud_current_loaded": True,
        "binding_mode": mode,
        "local_history_role": "reference_only",
        "context": context,
    }


def confirm_routing_match_command(
    args: argparse.Namespace,
    engine: SyncEngine,
) -> Mapping[str, Any]:
    request_id = validate_identifier(args.request_id, "routing_request_id")
    decision_token = getattr(args, "user_decision_token", None)
    if not isinstance(decision_token, str):
        raise IdentityError(
            "routing confirmation requires the current visible-turn token"
        )
    with FileLock(engine.lock_path):
        request_path, request, catalog = engine._verified_routing_request(
            request_id
        )
        if request.get("state") != "awaiting_user_reply":
            raise IdentityError("task matching request is no longer selectable")
        decision_path, decision = _load_routing_decision(
            engine.data_dir,
            decision_token,
        )
        choice = _assert_routing_decision_matches(
            engine.data_dir,
            decision,
            request,
        )
        _assert_frozen_routing_evidence(
            engine,
            request,
            choice,
            catalog,
            remote_artifact_task_id=str(
                decision.get("selected_task_id")
            ),
        )
        if decision.get("operation") != "initial_binding":
            raise IdentityError(
                "routing decision was not issued for an initial task binding"
            )
        if (
            decision.get("decision_kind") != "select"
            or not isinstance(decision.get("selected_task_id"), str)
        ):
            raise IdentityError(
                "the visible user turn did not select a task"
            )
        task_id = validate_identifier(
            decision["selected_task_id"],
            "selected_task_id",
        )
        requested_task = getattr(args, "task_id", None)
        if requested_task is not None and validate_identifier(
            requested_task,
            "task_id",
        ) != task_id:
            raise IdentityError(
                "caller task does not match the user's exact visible choice"
            )
        if decision.get("state") == "consumed":
            raise IdentityError("routing decision token was already used")
        remote = catalog.get(task_id)
        if remote is None:
            raise IdentityError("selected task is not an active semantic task")
        content_review_attestation = (
            _build_source_route_content_attestation(
                engine.data_dir,
                request,
                choice,
                decision,
                source_id=_source_for_routing_request(
                    engine,
                    request,
                )[0],
                task_id=task_id,
            )
        )
        if decision.get("state") == "issued":
            decision["state"] = "consuming"
            atomic_write_json(decision_path, decision)
        source_identity = engine._register_native_handoff_source(
            str(request["session_id"]),
            task_id,
            "existing_adoption",
            allow_legacy_revalidation=True,
            content_review_attestation=content_review_attestation,
        )
        if source_identity.task_id != task_id:
            raise VerificationError("user-confirmed task route changed")
        request["state"] = "confirmed_by_user"
        request["updated_at"] = utc_now()
        atomic_write_json(request_path, request)
        decision["state"] = "consumed"
        decision["completed_at"] = utc_now()
        atomic_write_json(decision_path, decision)
        choice_record = _load_routing_choice(
            engine.data_dir,
            request_id,
        )
        assert choice_record is not None
        choice_path, choice = choice_record
        choice["state"] = "consumed"
        choice["completed_at"] = utc_now()
        atomic_write_json(choice_path, choice)
    context, mode = _activate_confirmed_routing(
        engine,
        request,
        task_id,
    )
    return {
        "schema_version": "memory-vault-routing-confirmation/v1",
        "status": "confirmed",
        "task_id": task_id,
        "snapshot_id": remote.current["snapshot_id"],
        "cloud_current_loaded": True,
        "binding_mode": mode,
        "local_history_role": "reference_only",
        "context": context,
    }


def reject_routing_match_command(
    args: argparse.Namespace,
    engine: SyncEngine,
) -> Mapping[str, Any]:
    request_id = validate_identifier(args.request_id, "routing_request_id")
    decision_token = getattr(args, "user_decision_token", None)
    if not isinstance(decision_token, str):
        raise IdentityError(
            "routing rejection requires the current visible-turn token"
        )
    with FileLock(engine.lock_path):
        request_path, request, catalog = engine._verified_routing_request(
            request_id,
        )
        if request.get("state") != "awaiting_user_reply":
            raise IdentityError("task matching request is no longer selectable")
        decision_path, decision = _load_routing_decision(
            engine.data_dir,
            decision_token,
        )
        choice = _assert_routing_decision_matches(
            engine.data_dir,
            decision,
            request,
        )
        _assert_frozen_routing_evidence(
            engine,
            request,
            choice,
            catalog,
            remote_artifact_task_id=None,
        )
        if (
            decision.get("operation") != "initial_binding"
            or decision.get("decision_kind") != "reject"
            or decision.get("selected_task_id") is not None
        ):
            raise IdentityError(
                "the visible user turn did not reject all candidates"
            )
        if decision.get("state") != "issued":
            raise IdentityError("routing decision token was already used")
        decision["state"] = "consuming"
        atomic_write_json(decision_path, decision)
        request["state"] = "rejected"
        request["updated_at"] = utc_now()
        atomic_write_json(request_path, request)
        claim_record = _load_provisional_claim(
            engine.data_dir,
            str(request["session_key"]),
        )
        if claim_record is not None and claim_record[1].get(
            "state"
        ) == "provisional_active":
            claim = claim_record[1]
            claim["state"] = "rejected"
            claim["updated_at"] = utc_now()
            atomic_write_json(claim_record[0], claim)
        session_path = _session_path(
            engine.data_dir,
            str(request["session_key"]),
        )
        with contextlib.suppress(FileNotFoundError):
            session_path.unlink()
        decision["state"] = "consumed"
        decision["completed_at"] = utc_now()
        atomic_write_json(decision_path, decision)
        choice_path = _routing_choice_path(engine.data_dir, request_id)
        choice["state"] = "consumed"
        choice["completed_at"] = utc_now()
        atomic_write_json(choice_path, choice)
    return {
        "schema_version": "memory-vault-routing-rejection/v1",
        "status": "rejected",
        "request_id": request_id,
        "remote_current_changed": False,
    }


def _prepare_native_task_command(
    args: argparse.Namespace,
    engine: SyncEngine,
    *,
    mode: str,
) -> Mapping[str, Any]:
    """Prepare a short-lived, exact handoff for one native Codex task."""

    if mode not in NATIVE_HANDOFF_MODES:
        raise IdentityError("native task handoff mode is invalid")
    workspace = Path(args.workspace).expanduser().resolve(strict=True)
    assert_plain_path(workspace, require_file=False)
    if not any(
        _path_is_within(workspace, Path(root).resolve())
        for root in engine.config["privacy"]["allowed_roots"]
    ):
        raise IdentityError("native task workspace is outside an allowed root")
    task_id = validate_identifier(args.task_id, "task_id")
    preserve_ids: list[str] = []
    for value in getattr(args, "preserve_task_id", None) or []:
        candidate = validate_identifier(value, "preserve_task_id")
        if candidate != task_id and candidate not in preserve_ids:
            preserve_ids.append(candidate)
    requested_ids = [task_id, *preserve_ids]

    with FileLock(engine.lock_path):
        engine.git.ensure()
        catalog, _index = _discover_remote_task_catalog(engine.git)
        authorities = _discover_workspace_authorities(
            engine.git,
            set(catalog),
        )
        documents: list[Mapping[str, Any]] = []
        target_remote: RemoteTaskState | None = None
        target_authority: WorkspaceAuthority | None = None
        for requested_id in requested_ids:
            remote = catalog.get(requested_id)
            if remote is None:
                raise IdentityError("native handoff task is not discoverable")
            if (
                remote.task.get("status") != "active"
                or remote.task.get("task_type") != "semantic_task"
            ):
                raise IdentityError(
                    "native handoff requires an active semantic task"
                )
            task_authorities = authorities.get(requested_id, [])
            if len(task_authorities) != 1:
                raise IdentityError(
                    "native handoff task has no unique writable workspace authority"
                )
            authority = task_authorities[0]
            placeholder = PortableIdentity(
                path=workspace / ".vault_identities.json",
                workspace_root=workspace,
                binding_id=authority.binding_id,
                task_id=authority.task_id,
                lineage_id=authority.lineage_id,
                base={},
            )
            verified = load_remote_task(engine.git, placeholder)
            documents.append(
                _portable_identity_document(
                    engine.git,
                    verified,
                    authority,
                )
            )
            if requested_id == task_id:
                target_remote = verified
                target_authority = authority
        if target_remote is None or target_authority is None:
            raise VerificationError("native handoff target could not be verified")
        expected_source_key: str | None = None
        expected_source_id: str | None = None
        expected_source_binding_id: str | None = None
        identity_documents: list[Mapping[str, Any]] | None = None
        identity_fingerprint: str | None = None
        if mode == "existing_adoption":
            session_id = getattr(args, "existing_session_id", None)
            if not isinstance(session_id, str) or not session_id:
                raise IdentityError("existing native task identity is missing")
            try:
                source_identity = resolve_source_identity(
                    engine.git,
                    session_id,
                )
            except IdentityError as exc:
                raise IdentityError(
                    "existing native task must complete content review and "
                    "explicit routing confirmation before adoption"
                ) from exc
            if source_identity.task_id != task_id:
                raise IdentityError(
                    "existing native task must complete content review and "
                    "explicit routing confirmation before adoption"
                )
            expected_source_id = source_identity.source_id
            expected_source_binding_id = source_identity.binding_id
            existing_identities = _portable_identities_in_workspace(workspace)
            existing_ids = {identity.task_id for identity in existing_identities}
            allowed_existing_ids = set(requested_ids)
            unexpected = sorted(existing_ids - allowed_existing_ids)
            if unexpected:
                raise IdentityError(
                    "workspace has another task identity that was not explicitly preserved"
                )
            prepared_pairs = {
                parsed.task_id: (parsed.binding_id, parsed.lineage_id)
                for parsed in (
                    _parse_identity_value(
                        document,
                        workspace / ".vault_identities.json",
                    )
                    for document in documents
                )
            }
            for existing_identity in existing_identities:
                if prepared_pairs.get(existing_identity.task_id) != (
                    existing_identity.binding_id,
                    existing_identity.lineage_id,
                ):
                    raise IdentityError(
                        "workspace already has a conflicting identity for adoption"
                    )
            existing_portable_gate = _load_portable_adoptions(workspace).get(
                task_id
            )
            if isinstance(existing_portable_gate, Mapping) and (
                existing_portable_gate.get("binding_id")
                != target_authority.binding_id
                or existing_portable_gate.get("workspace_lineage_id")
                != target_authority.lineage_id
            ):
                raise IdentityError(
                    "workspace has a conflicting portable adoption gate"
                )
            expected_source_key = _codex_source_key(session_id)
            identity_documents = list(documents)
            identity_fingerprint = _workspace_identity_fingerprint(workspace)
            workspace_task_ids = sorted(existing_ids | set(requested_ids))
        else:
            workspace_task_ids = _merge_workspace_identity_documents(
                workspace,
                documents,
            )

        handoff_root = engine.data_dir / "state" / "native-handoffs"
        ensure_private_dir(handoff_root)
        existing = sorted(handoff_root.glob("*.json"))
        if len(existing) > 256:
            raise BusyError("too many pending native task handoffs")
        now_epoch = int(time.time())
        for path in existing:
            with contextlib.suppress(VaultSyncError, OSError, ValueError):
                value = load_json(path)
                if (
                    isinstance(value, Mapping)
                    and isinstance(value.get("expires_at_epoch"), int)
                    and int(value["expires_at_epoch"]) < now_epoch
                ):
                    path.unlink()

        token = base64.urlsafe_b64encode(secrets.token_bytes(32)).decode(
            "ascii"
        ).rstrip("=")
        token_path = _native_handoff_path(engine.data_dir, token)
        handoff = {
            "schema_version": NATIVE_HANDOFF_SCHEMA,
            "mode": mode,
            "token_sha256": sha256_bytes(token.encode("ascii")),
            "task_id": task_id,
            "binding_id": target_authority.binding_id,
            "workspace_lineage_id": target_authority.lineage_id,
            "workspace_root": str(workspace),
            "expected_source_key_sha256": expected_source_key,
            "expected_source_id": expected_source_id,
            "expected_source_binding_id": expected_source_binding_id,
            "identity_documents": identity_documents,
            "workspace_identity_fingerprint": identity_fingerprint,
            "created_at": utc_now(),
            "expires_at_epoch": now_epoch + NATIVE_HANDOFF_TTL_SECONDS,
        }
        atomic_write_json(token_path, handoff)

    if mode == "existing_adoption":
        initial_prompt = (
            "请把当前这个已有任务精确认领到已选择的云端任务，并从验证后的"
            "权威 CURRENT 和交接记忆直接继续。云端已决结论是当前状态；当前"
            "任务原有对话与工作文件只作参考。不要仅因旧记录不同就要求用户"
            "再次解释或证明已经完成的变更；只有最新权威内容本身仍冲突或明确"
            "未决时才提问。不要把旧文件当作最新版发布。\n"
            f"[[memory-vault-handoff:{token}]]"
        )
    else:
        initial_prompt = (
            "请接收这个已确认的私人记忆接力，并从最新权威继续点开始。直接"
            "使用已验证的当前结论、完成结果和下一步，不要把较旧历史重新变成"
            "未决问题。\n"
            f"[[memory-vault-handoff:{token}]]"
        )
    result: dict[str, Any] = {
        "schema_version": "memory-vault-native-task-preparation/v1",
        "status": "ready",
        "mode": mode,
        "task_id": task_id,
        "display_title": str(
            target_remote.task.get("display_title") or task_id
        )[:300],
        "workspace_identity_task_ids": workspace_task_ids,
        "expires_in_seconds": NATIVE_HANDOFF_TTL_SECONDS,
    }
    if mode == "existing_adoption":
        result["native_adoption"] = {
            "tool": "codex_app.send_message_to_thread",
            "target": "exact_existing_native_task",
            "initial_prompt": initial_prompt,
        }
    else:
        result["native_creation"] = {
            "tool": "codex_app.create_thread",
            "target": "same_local_project",
            "initial_prompt": initial_prompt,
        }
    return result


def prepare_native_handoff_command(
    args: argparse.Namespace,
    engine: SyncEngine,
) -> Mapping[str, Any]:
    raise ConfigurationError(
        "new native task handoff is disabled until Codex provides an exact "
        "create-thread receipt; open the new task unbound and use the formal "
        "content-evidence routing flow"
    )


def prepare_existing_adoption_command(
    args: argparse.Namespace,
    engine: SyncEngine,
) -> Mapping[str, Any]:
    return _prepare_native_task_command(
        args,
        engine,
        mode="existing_adoption",
    )


def switch_task_route_command(
    args: argparse.Namespace,
    engine: SyncEngine,
) -> Mapping[str, Any]:
    """Explicitly correct one existing native task without deleting history."""

    requested_task_id = getattr(args, "task_id", None)
    session_id = args.existing_session_id
    if not isinstance(session_id, str) or not session_id:
        raise IdentityError("existing native task identity is missing")
    workspace = Path(args.workspace).expanduser().resolve(strict=True)
    assert_plain_path(workspace, require_file=False)
    if not any(
        _path_is_within(workspace, Path(root).resolve())
        for root in engine.config["privacy"]["allowed_roots"]
    ):
        raise IdentityError("route switch workspace is outside an allowed root")
    workspace_mode = str(
        getattr(args, "workspace_mode", "session-only")
    )
    if workspace_mode not in {"session-only", "shared", "replace"}:
        raise IdentityError("route switch workspace mode is invalid")
    decision_token = getattr(args, "user_decision_token", None)
    if not isinstance(decision_token, str):
        raise IdentityError(
            "route switching requires the current visible-turn token"
        )

    device = _device_state(engine.data_dir)
    session_key = _session_key(device, session_id)
    if engine._session_has_pending_local_work(session_key):
        raise BusyError(
            "the existing native task has an unfinished local checkpoint"
        )

    with FileLock(engine.lock_path):
        if engine._session_has_pending_local_work(session_key):
            raise BusyError(
                "the existing native task gained an unfinished local checkpoint"
            )
        engine.git.ensure()
        decision_path, decision = _load_routing_decision(
            engine.data_dir,
            decision_token,
        )
        request_path, request, catalog = engine._verified_routing_request(
            str(decision["request_id"]),
            ensure_remote=False,
        )
        if request.get("state") != "awaiting_user_reply":
            raise IdentityError("route switch is no longer awaiting a choice")
        choice = _assert_routing_decision_matches(
            engine.data_dir,
            decision,
            request,
        )
        _assert_frozen_routing_evidence(
            engine,
            request,
            choice,
            catalog,
            remote_artifact_task_id=str(
                decision.get("selected_task_id")
            ),
        )
        if (
            decision.get("operation") != "route_switch"
            or decision.get("workspace_mode") != workspace_mode
            or request.get("session_id") != session_id
            or request.get("session_key") != session_key
        ):
            raise IdentityError(
                "route switch decision does not match this task or mode"
            )
        _assert_routing_request_matches_workspace(
            request,
            str(workspace),
            engine.config["privacy"]["allowed_roots"],
        )
        if (
            decision.get("decision_kind") != "select"
            or not isinstance(decision.get("selected_task_id"), str)
        ):
            raise IdentityError(
                "the visible user turn did not select a task"
            )
        task_id = validate_identifier(
            decision["selected_task_id"],
            "selected_task_id",
        )
        if requested_task_id is not None and validate_identifier(
            requested_task_id,
            "task_id",
        ) != task_id:
            raise IdentityError(
                "caller task does not match the user's exact visible choice"
            )
        if decision.get("state") == "consumed":
            raise IdentityError("routing decision token was already used")
        source_id, _source, _external_key = resolve_source_record(
            engine.git,
            session_id,
        )
        previous_route = _active_primary_source_route(
            engine.git,
            source_id,
        )
        if previous_route is None:
            raise IdentityError("existing native task route is missing")
        expected_previous_binding = validate_identifier(
            decision.get("previous_binding_id"),
            "previous_binding_id",
        )
        expected_previous_task = validate_identifier(
            decision.get("previous_task_id"),
            "previous_task_id",
        )
        route_already_switched = bool(
            previous_route.task_id == task_id
            and previous_route.supersedes_binding_id
            == expected_previous_binding
        )
        if not route_already_switched and (
            previous_route.binding_id != expected_previous_binding
            or previous_route.task_id != expected_previous_task
        ):
            raise ConflictError(
                "the existing task route changed after the choice was shown"
            )
        remote = catalog.get(task_id)
        if (
            remote is None
            or remote.task.get("task_type") != "semantic_task"
            or remote.task.get("status") != "active"
        ):
            raise IdentityError(
                "selected route target is not an active semantic task"
            )
        content_review_attestation = (
            _build_source_route_content_attestation(
                engine.data_dir,
                request,
                choice,
                decision,
                source_id=source_id,
                task_id=task_id,
            )
        )
        full_catalog, _index = _discover_remote_task_catalog(engine.git)
        for split in _discover_structural_splits(
            engine.git,
            set(full_catalog),
        ):
            if split.get("source_id") != source_id:
                continue
            structural_route = split.get("continuation_route")
            if isinstance(structural_route, Mapping):
                _require_current_attested_source_route(
                    engine.git,
                    source_id=source_id,
                    task_id=str(structural_route["target_task_id"]),
                    binding_id=str(structural_route["binding_id"]),
                    source_sequence_from=int(
                        structural_route["source_sequence_from"]
                    ),
                )
            if (
                isinstance(structural_route, Mapping)
                and structural_route.get("target_task_id") != task_id
            ):
                raise StructuralRouteCorrectionRequired(
                    "this source has a different confirmed structural split "
                    "route; no generic route switch was performed"
                )
        if decision.get("state") == "issued":
            decision["state"] = "consuming"
            atomic_write_json(decision_path, decision)
        existing_workspace_identities = (
            _portable_identities_in_workspace(workspace)
        )
        workspace_identity_task_ids = [
            identity.task_id
            for identity in existing_workspace_identities
        ]
        planned_workspace_document: Mapping[str, Any] | None = None
        planned_portable: PortableIdentity | None = None
        if workspace_mode in {"shared", "replace"}:
            authorities = _discover_workspace_authorities(
                engine.git,
                set(catalog),
            ).get(task_id, [])
            if len(authorities) != 1:
                raise IdentityError(
                    "selected task has no unique writable workspace authority"
                )
            planned_workspace_document = _portable_identity_document(
                engine.git,
                remote,
                authorities[0],
            )
            _parse_identity_value(
                planned_workspace_document,
                workspace / ".vault_identities.json",
            )
            planned_portable = _parse_identity_value(
                planned_workspace_document,
                workspace / ".vault_identities.json",
            )
            _write_route_switch_adoption_guard(
                engine.data_dir,
                workspace,
                session_id,
                planned_portable,
                remote,
            )

        if route_already_switched:
            if (
                previous_route.document.get(
                    "content_review_attestation"
                )
                != content_review_attestation
            ):
                raise ConflictError(
                    "the completed route switch does not match this frozen "
                    "content review"
                )
            source_identity = resolve_source_identity(
                engine.git,
                session_id,
            )
        else:
            source_identity = engine._register_native_handoff_source(
                session_id,
                task_id,
                "existing_adoption",
                allow_user_reassignment=True,
                allow_legacy_revalidation=True,
                content_review_attestation=content_review_attestation,
            )
        remote = load_remote_task(engine.git, source_identity)
        active_binding = engine.git.show_json(
            f"bindings/confirmed/{source_identity.binding_id}.json"
        )
        correction = active_binding.get("route_correction")
        historical_repair_required = bool(
            isinstance(correction, Mapping)
            and correction.get(
                "historical_content_review_required"
            )
            is True
        )
        potentially_misrouted_sequence_count = (
            int(correction["potentially_misrouted_sequence_count"])
            if isinstance(correction, Mapping)
            and isinstance(
                correction.get(
                    "potentially_misrouted_sequence_count"
                ),
                int,
            )
            else 0
        )
        selected_identity: TaskIdentity = source_identity
        identity_audit: Mapping[str, Any] | None = None
        if workspace_mode in {"shared", "replace"}:
            if planned_workspace_document is None:
                raise VerificationError(
                    "route switch workspace plan is incomplete"
                )
            if workspace_mode == "shared":
                workspace_identity_task_ids = (
                    _merge_workspace_identity_documents(
                        workspace,
                        [planned_workspace_document],
                    )
                )
            else:
                identity_audit = _replace_workspace_identity_document(
                    engine.data_dir,
                    workspace,
                    planned_workspace_document,
                )
                workspace_identity_task_ids = [task_id]
            portable = resolve_workspace(
                workspace,
                engine.config["privacy"]["allowed_roots"],
                task_id=task_id,
            )
            selected_identity = portable

        context = _continuation_context(
            remote,
            git=engine.git,
            reference_source_ids=[source_identity.source_id],
        )
        context = _with_adoption_context(context, blocked=True)
        if historical_repair_required:
            context = _append_context_note(
                context,
                (
                    "Route correction warning: older source revisions may "
                    "have been projected into the previous task. They remain "
                    "audit evidence only until an explicit historical memory "
                    "repair retires the wrong-task claims and reprojects the "
                    "same evidence into this task."
                ),
                label="route correction history warning",
            )
        _session_key_value, session = engine._session_start_state(
            {
                "session_id": session_id,
                "cwd": str(workspace),
            },
            selected_identity,
            remote,
            continuation_context=context,
            source_id_override=source_identity.source_id,
            source_external_key_override=(
                source_identity.external_source_key_sha256
            ),
            artifact_snapshot_override={},
            adoption={
                "mode": "explicit_route_correction",
                "state": "cloud_current_loaded",
                "cloud_snapshot_id": remote.current["snapshot_id"],
                "cloud_current_blob_sha": remote.current_blob_sha,
                "local_history_role": "reference_only",
                "artifact_publication_blocked": True,
            },
        )
        _stage_pending_routing_prompt(engine, request)
        request["state"] = "confirmed_by_user"
        request["updated_at"] = utc_now()
        atomic_write_json(request_path, request)
        choice_record = _load_routing_choice(
            engine.data_dir,
            str(request["request_id"]),
        )
        assert choice_record is not None
        choice_path, choice = choice_record
        choice["state"] = "consumed"
        choice["completed_at"] = utc_now()
        atomic_write_json(choice_path, choice)
        decision["state"] = "consumed"
        decision["completed_at"] = utc_now()
        atomic_write_json(decision_path, decision)

    result: dict[str, Any] = {
        "schema_version": "memory-vault-route-correction/v1",
        "status": "corrected",
        "task_id": task_id,
        "previous_task_id": expected_previous_task,
        "source_binding_id": source_identity.binding_id,
        "workspace_mode": workspace_mode,
        "workspace_identity_task_ids": sorted(
            set(workspace_identity_task_ids)
        ),
        "cloud_current_loaded": True,
        "snapshot_id": remote.current["snapshot_id"],
        "local_history_role": "reference_only",
        "artifact_publication_blocked": True,
        "historical_repair_required": historical_repair_required,
        "potentially_misrouted_sequence_count": (
            potentially_misrouted_sequence_count
        ),
        "identity_kind": session["identity_kind"],
        "context": context,
    }
    if identity_audit is not None:
        result["identity_reassignment_audit"] = dict(identity_audit)
    return result


def _inspect_existing_adoption_artifacts(
    args: argparse.Namespace,
    engine: SyncEngine,
) -> Mapping[str, Any]:
    workspace = Path(args.workspace).expanduser().resolve(strict=True)
    assert_plain_path(workspace, require_file=False)
    if not any(
        _path_is_within(workspace, Path(root).resolve())
        for root in engine.config["privacy"]["allowed_roots"]
    ):
        raise IdentityError("existing-task adoption workspace is outside an allowed root")
    session_id = args.existing_session_id
    if not isinstance(session_id, str) or not session_id:
        raise IdentityError("existing native task identity is missing")
    device = _device_state(engine.data_dir)
    loaded = _load_session(engine.data_dir, device, session_id)
    if loaded is None:
        raise IdentityError("existing native task has no verified cloud baseline")
    _session_key_value, session = loaded
    task_id = validate_identifier(session.get("task_id"), "task_id")
    identity = resolve_workspace(
        workspace,
        engine.config["privacy"]["allowed_roots"],
        task_id=task_id,
    )
    if (
        session.get("binding_id") != identity.binding_id
        or session.get("workspace_lineage_id") != identity.lineage_id
    ):
        raise IdentityError("existing native task baseline changed before inspection")
    portable = _portable_adoption_for(identity)
    if (
        not isinstance(portable, Mapping)
        or portable.get("binding_id") != identity.binding_id
        or portable.get("workspace_lineage_id") != identity.lineage_id
    ):
        raise IdentityError("existing-task adoption safety gate is incomplete")
    fingerprint, manifest = _publish_manifest_snapshot(identity, parse=True)
    if fingerprint is None or manifest is None:
        raise PrivacyError(
            "write a task-scoped vault-publish/v2 manifest after reconciliation"
        )
    if not isinstance(manifest, Mapping) or manifest.get(
        "schema_version"
    ) != "vault-publish/v2":
        raise PrivacyError(
            "existing-task adoption requires a task-scoped vault-publish/v2 manifest"
        )
    declarations = _artifact_declarations_from_value(identity, manifest)
    return {
        "schema_version": "memory-vault-existing-adoption-inspection/v1",
        "status": "ready_for_explicit_approval",
        "task_id": task_id,
        "manifest_sha256": fingerprint,
        "artifacts": declarations,
    }


def inspect_existing_adoption_artifacts_command(
    args: argparse.Namespace,
    engine: SyncEngine,
) -> Mapping[str, Any]:
    with FileLock(engine.lock_path):
        return _inspect_existing_adoption_artifacts(args, engine)


def _approve_existing_adoption_artifacts(
    args: argparse.Namespace,
    engine: SyncEngine,
) -> Mapping[str, Any]:
    """Unlock only one explicitly reconciled, task-scoped artifact manifest."""

    workspace = Path(args.workspace).expanduser().resolve(strict=True)
    assert_plain_path(workspace, require_file=False)
    if not any(
        _path_is_within(workspace, Path(root).resolve())
        for root in engine.config["privacy"]["allowed_roots"]
    ):
        raise IdentityError("existing-task adoption workspace is outside an allowed root")
    session_id = args.existing_session_id
    if not isinstance(session_id, str) or not session_id:
        raise IdentityError("existing native task identity is missing")
    device = _device_state(engine.data_dir)
    loaded = _load_session(engine.data_dir, device, session_id)
    if loaded is None:
        raise IdentityError("existing native task has no verified cloud baseline")
    session_key, session = loaded
    task_id = validate_identifier(session.get("task_id"), "task_id")
    identity = resolve_workspace(
        workspace,
        engine.config["privacy"]["allowed_roots"],
        task_id=task_id,
    )
    if (
        session.get("binding_id") != identity.binding_id
        or session.get("workspace_lineage_id") != identity.lineage_id
    ):
        raise IdentityError("existing native task baseline changed before approval")
    local = _load_adoption_guard(
        engine.data_dir,
        device,
        identity.workspace_root,
        identity.task_id,
    )
    portable = _portable_adoption_for(identity)
    if portable is None:
        raise IdentityError("existing-task adoption safety gate is incomplete")
    if local is None:
        now = utc_now()
        guard_path = _adoption_guard_path(
            engine.data_dir,
            device,
            identity.workspace_root,
            identity.task_id,
        )
        local_guard = {
            "schema_version": ADOPTION_GUARD_SCHEMA,
            "task_id": identity.task_id,
            "binding_id": identity.binding_id,
            "workspace_lineage_id": identity.lineage_id,
            "workspace_root": str(identity.workspace_root.resolve()),
            "expected_source_key_sha256": _codex_source_key(session_id),
            "cloud_snapshot_id": portable["cloud_snapshot_id"],
            "cloud_current_blob_sha": portable["cloud_current_blob_sha"],
            "preexisting_publish_manifest_sha256": portable[
                "preexisting_publish_manifest_sha256"
            ],
            "approved_publish_manifest_sha256": None,
            "artifact_publication_blocked": True,
            "state": "cloud_current_loaded",
            "created_at": now,
            "updated_at": now,
        }
        atomic_write_json(guard_path, local_guard)
    else:
        guard_path, local_guard = local
    if (
        local_guard.get("expected_source_key_sha256")
        != _codex_source_key(session_id)
        or local_guard.get("binding_id") != identity.binding_id
        or local_guard.get("workspace_lineage_id") != identity.lineage_id
        or portable.get("binding_id") != identity.binding_id
        or portable.get("workspace_lineage_id") != identity.lineage_id
    ):
        raise IdentityError("existing-task adoption safety gate is inconsistent")
    expected = validate_sha256(
        args.expected_manifest_sha256,
        "expected_manifest_sha256",
    )

    def revoke_local_approval() -> None:
        now = utc_now()
        local_guard.update(
            {
                "approved_publish_manifest_sha256": None,
                "artifact_publication_blocked": True,
                "state": "cloud_current_loaded",
                "updated_at": now,
            }
        )
        atomic_write_json(guard_path, local_guard)
        session["adoption"] = {
            "mode": "existing_adoption",
            "state": "cloud_current_loaded",
            "cloud_snapshot_id": local_guard["cloud_snapshot_id"],
            "cloud_current_blob_sha": local_guard["cloud_current_blob_sha"],
            "local_history_role": "reference_only",
            "artifact_publication_blocked": True,
        }
        existing_context = session.get("continuation_context")
        if isinstance(existing_context, str):
            session["continuation_context"] = _with_adoption_context(
                existing_context,
                blocked=True,
            )
        _save_session(engine.data_dir, session_key, session)

    try:
        approved, manifest = _publish_manifest_snapshot(identity, parse=True)
        if approved is None or manifest is None:
            raise PrivacyError(
                "write a task-scoped vault-publish/v2 manifest after reconciliation"
            )
        if approved != expected:
            raise ConflictError(
                "artifact declaration changed after reconciliation inspection"
            )
        if not isinstance(manifest, Mapping) or manifest.get(
            "schema_version"
        ) != "vault-publish/v2":
            raise PrivacyError(
                "existing-task adoption requires a task-scoped "
                "vault-publish/v2 manifest"
            )
        _artifact_declarations_from_value(identity, manifest)
    except (PrivacyError, ConfigurationError, VerificationError, ConflictError):
        revoke_local_approval()
        raise
    now = utc_now()
    local_guard.update(
        {
            "approved_publish_manifest_sha256": approved,
            "artifact_publication_blocked": False,
            "state": "artifacts_reconciled",
            "updated_at": now,
        }
    )
    atomic_write_json(guard_path, local_guard)
    session["adoption"] = {
        "mode": "existing_adoption",
        "state": "artifacts_reconciled",
        "cloud_snapshot_id": local_guard["cloud_snapshot_id"],
        "cloud_current_blob_sha": local_guard["cloud_current_blob_sha"],
        "local_history_role": "reference_only",
        "artifact_publication_blocked": False,
    }
    existing_context = session.get("continuation_context")
    if isinstance(existing_context, str):
        session["continuation_context"] = _with_adoption_context(
            existing_context,
            blocked=False,
        )
    _save_session(engine.data_dir, session_key, session)
    return {
        "schema_version": "memory-vault-existing-adoption-approval/v1",
        "status": "artifacts_reconciled",
        "task_id": task_id,
        "approved_publish_manifest_sha256": approved,
    }


def approve_existing_adoption_artifacts_command(
    args: argparse.Namespace,
    engine: SyncEngine,
) -> Mapping[str, Any]:
    with FileLock(engine.lock_path):
        return _approve_existing_adoption_artifacts(args, engine)


def _rebase_local_sessions_for_split_route(
    engine: SyncEngine,
    source_id: str,
    target_task_id: str,
    binding_id: str,
) -> int:
    _require_current_attested_source_route(
        engine.git,
        source_id=source_id,
        task_id=target_task_id,
        binding_id=binding_id,
    )
    sessions_root = engine.data_dir / "state" / "sessions"
    if not sessions_root.exists():
        return 0
    paths = sorted(sessions_root.glob("*.json"))
    if len(paths) > 5000:
        raise VerificationError("local session registry exceeds the safety limit")
    source = engine.git.show_json(f"sources/{source_id}/SOURCE.json")
    _validate_source(source)
    external_key = validate_sha256(
        source.get("external_source_key_sha256"),
        "external_source_key_sha256",
    )
    source_identity = SourceIdentity(
        binding_id=binding_id,
        task_id=target_task_id,
        source_id=source_id,
        external_source_key_sha256=external_key,
    )
    remote = load_remote_task(engine.git, source_identity)
    context = _continuation_context(
        remote,
        git=engine.git,
        reference_source_ids=[source_id],
    )
    rebased = 0
    for path in paths:
        value = load_json(path)
        if (
            not isinstance(value, dict)
            or value.get("schema_version") != SESSION_SCHEMA
            or value.get("source_id") != source_id
        ):
            continue
        if value.get("source_external_key_sha256") != external_key:
            raise IdentityError("local split session source key is inconsistent")
        value.update(
            {
                "identity_kind": "source",
                "task_id": target_task_id,
                "binding_id": binding_id,
                "base": {
                    "remote_commit_sha": remote.commit_sha,
                    "task_current_path": remote.current_path,
                    "task_current_blob_sha": remote.current_blob_sha,
                    "task_generation": remote.current["generation"],
                    "snapshot_id": remote.current["snapshot_id"],
                    "manifest_path": remote.manifest_path,
                    "published_transaction_id": remote.current[
                        "published_transaction_id"
                    ],
                },
                "base_manifest": dict(remote.manifest),
                "artifact_snapshot": {},
                "continuation_context": context,
                "continuation_context_contract": (
                    CONTINUATION_CONTEXT_CONTRACT
                ),
                "started_at": utc_now(),
            }
        )
        for local_key in (
            "workspace_lineage_id",
            "workspace_instance_id",
            "workspace_root",
        ):
            value.pop(local_key, None)
        atomic_write_json(path, value)
        rebased += 1
    return rebased


def confirm_split_route_command(
    args: argparse.Namespace,
    engine: SyncEngine,
) -> Mapping[str, Any]:
    """Record one explicit, cross-device continuation route atomically."""

    event_id = validate_identifier(args.event_id, "structural_event_id")
    target_task_id = validate_identifier(args.target_task_id, "target_task_id")
    event_path = f"bindings/structural/{event_id}.json"
    with FileLock(engine.lock_path):
        engine.git.ensure()
        catalog, _index = _discover_remote_task_catalog(engine.git)
        splits = {
            str(item["structural_event_id"]): item
            for item in _discover_structural_splits(engine.git, set(catalog))
        }
        split = splits.get(event_id)
        if split is None:
            raise IdentityError("confirmed source split event was not found")
        children = [str(item) for item in split["child_task_ids"]]
        if target_task_id not in children:
            raise IdentityError("route target is not a child of this split")
        source_id = validate_identifier(split["source_id"], "source_id")
        existing_route = split.get("continuation_route")
        if isinstance(existing_route, Mapping):
            if existing_route.get("target_task_id") != target_task_id:
                raise StructuralRouteCorrectionRequired(
                    "this split already has a different confirmed continuation "
                    "route; an append-only structural correction is required"
                )
            existing_binding_id = validate_identifier(
                existing_route["binding_id"],
                "binding_id",
            )
            _require_current_attested_source_route(
                engine.git,
                source_id=source_id,
                task_id=target_task_id,
                binding_id=existing_binding_id,
                source_sequence_from=int(
                    existing_route["source_sequence_from"]
                ),
            )
            local_sessions_rebased = _rebase_local_sessions_for_split_route(
                engine,
                source_id,
                target_task_id,
                existing_binding_id,
            )
            return {
                "schema_version": "memory-vault-sync-split-route/v1",
                "status": "already_confirmed",
                "structural_event_id": event_id,
                "target_task_id": target_task_id,
                "binding_id": existing_route["binding_id"],
                "remote_commit_sha": engine.git.head_sha(),
                "local_sessions_rebased": local_sessions_rebased,
            }

        raise StructuralRouteCorrectionRequired(
            "new structural split routes are fail-closed until the same "
            "full-content, next-visible-turn authorization flow used by normal "
            "routing is available"
        )


def trace_evidence_command(
    args: argparse.Namespace,
    engine: SyncEngine,
) -> Mapping[str, Any]:
    """Resolve one projection evidence entry from immutable verified sources."""

    task_id = validate_identifier(args.task_id, "task_id")
    if args.entry_id is None and args.reference_index is not None:
        raise VerificationError(
            "--reference-index requires an explicit --entry-id"
        )
    authority = "remote_verified"
    with FileLock(engine.lock_path):
        try:
            engine.git.ensure()
        except (OfflineError, ConflictError):
            if not engine.git.has_cache():
                raise
            authority = "cached_reference_only"
        remote = load_remote_task_by_id(engine.git, task_id)
    projection = remote.memory_projection
    if not isinstance(projection, Mapping):
        raise VerificationError(
            "task has no structured memory projection to trace"
        )
    entries = {
        str(entry["entry_id"]): entry
        for entry in projection["evidence_index"]
    }
    if args.entry_id is None:
        return {
            "schema_version": "memory-vault-evidence-index/v1",
            "task_id": task_id,
            "snapshot_id": remote.current["snapshot_id"],
            "projection_id": projection["projection_id"],
            "authority": authority,
            "entries": [
                {
                    "entry_id": entry_id,
                    "topic": entry["topic"],
                    "reference_count": len(entry["references"]),
                }
                for entry_id, entry in entries.items()
            ],
        }
    entry_id = validate_identifier(args.entry_id, "entry_id")
    entry = entries.get(entry_id)
    if entry is None:
        raise VerificationError("projection evidence entry does not exist")
    references = list(entry["references"])
    if args.reference_index is not None:
        if args.reference_index < 0 or args.reference_index >= len(references):
            raise VerificationError("evidence reference index is out of range")
        indexed_references = [(args.reference_index, references[args.reference_index])]
    else:
        indexed_references = list(enumerate(references))
    source_cache: dict[str, Mapping[str, Any]] = {}
    resolved: list[Mapping[str, Any]] = []
    for index, reference in indexed_references:
        value = _verify_projection_reference(
            engine.git,
            remote.manifest,
            task_id,
            reference,
            source_cache=source_cache,
        )
        kind = str(reference["kind"])
        if kind == "source_message":
            resolved.append(
                {
                    "reference_index": index,
                    "kind": kind,
                    "source_id": reference["source_id"],
                    "revision_id": reference["revision_id"],
                    "source_sequence": reference["source_sequence"],
                    "message_ordinal": reference["message_ordinal"],
                    "role": value["role"],
                    "phase": value.get("phase"),
                    "text": value["text"],
                    "evidence_anchor_sha256": reference[
                        "evidence_anchor_sha256"
                    ],
                    "content_path": (
                        f"sources/{reference['source_id']}/revisions/"
                        f"{reference['revision_id']}.json"
                    ),
                }
            )
        elif kind == "memory_event":
            event_source = value["source"]
            anchor = event_source.get("evidence_anchor_sha256")
            event_result: dict[str, Any] = {
                "reference_index": index,
                "kind": kind,
                "memory_event_id": value["memory_event_id"],
                "event_kind": value["kind"],
                "claim_key": value["claim_key"],
                "confidence": value["confidence"],
                "source": value["source"],
                "payload": value["payload"],
                "event_sha256": value["event_sha256"],
                "content_path": (
                    f"memory/events/{value['memory_event_id']}.json"
                ),
            }
            if anchor is None:
                event_result.update(
                    {
                        "anchor_resolution": {
                            "status": "reference_only",
                            "reason": "no_raw_anchor",
                            "raw_message_available": False,
                        },
                        "anchored_message": None,
                    }
                )
                resolved.append(event_result)
                continue
            durable = _task_version_source_evidence(remote.manifest).get(
                (
                    str(event_source["source_id"]),
                    str(event_source["revision_id"]),
                )
            )
            if durable is None:
                raise VerificationError(
                    "memory-event trace lost its durable source"
                )
            raw_source = engine.git.show_bytes(
                validate_repo_path(
                    durable["content_path"],
                    "memory-event trace content path",
                )
            )
            source_value = strict_json_loads(raw_source.decode("utf-8"))
            if not isinstance(source_value, Mapping):
                raise VerificationError(
                    "memory-event trace source is invalid"
                )
            anchored = [
                message
                for message in source_value.get("messages", [])
                if isinstance(message, Mapping)
                and isinstance(message.get("text"), str)
                and sha256_bytes(message["text"].encode("utf-8")) == anchor
            ]
            if len(anchored) != 1:
                raise VerificationError(
                    "memory-event trace anchor is not unique"
                )
            anchored_message = anchored[0]
            event_result.update(
                {
                    "anchor_resolution": {
                        "status": "exact_message",
                        "reason": "unique_sha256_anchor_verified",
                        "raw_message_available": True,
                    },
                    "anchored_message": {
                        "ordinal": anchored_message["ordinal"],
                        "role": anchored_message["role"],
                        "phase": anchored_message.get("phase"),
                        "text": anchored_message["text"],
                        "evidence_anchor_sha256": anchor,
                    },
                }
            )
            resolved.append(event_result)
        else:
            resolved.append(
                {
                    "reference_index": index,
                    "kind": kind,
                    "artifact": dict(value),
                    "manifest_path": remote.manifest_path,
                }
            )
    result = {
        "schema_version": "memory-vault-evidence-trace/v1",
        "task_id": task_id,
        "snapshot_id": remote.current["snapshot_id"],
        "projection_id": projection["projection_id"],
        "authority": authority,
        "entry_id": entry_id,
        "topic": entry["topic"],
        "reference_count": len(references),
        "resolved_references": resolved,
    }
    encoded = json.dumps(
        result,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    if len(encoded) > MAX_CODEX_JSON_BYTES:
        raise VerificationError(
            "evidence trace is too large; retry with --reference-index"
        )
    assert_remote_safe(result)
    return result


RECONCILIATION_COLLECTIONS: Mapping[str, tuple[str, str]] = {
    "effective_claim": ("effective_claims", "claim_id"),
    "contested_claim": ("contested_claims", "claim_id"),
    "superseded_claim": ("superseded_claims", "claim_id"),
    "rejected_option": ("rejected_options", "option_id"),
    "artifact_authority": ("artifact_authorities", "artifact_id"),
    "completed_item": ("completed", "item_id"),
    "in_progress_item": ("in_progress", "item_id"),
    "next_action": ("next_actions", "action_id"),
    "open_question": ("open_questions", "question_id"),
    "risk": ("risks", "risk_id"),
    "blocking_conflict": ("blocking_conflicts", "conflict_id"),
    "nonblocking_contradiction": (
        "nonblocking_contradictions",
        "contradiction_id",
    ),
    "known_gap": ("known_gaps", "gap_id"),
    "evidence_index_entry": ("evidence_index", "entry_id"),
}
RECONCILIATION_OPERATION_KINDS = {
    "current_goal",
    "scope_boundary",
    *(kind for kind in RECONCILIATION_COLLECTIONS if kind != "evidence_index_entry"),
}


def _projection_record(
    projection: Mapping[str, Any],
    kind: str,
    record_id: str,
) -> Mapping[str, Any]:
    projection = _projection_with_runtime_completeness_basis(projection)
    if kind == "completeness":
        basis = projection["completeness_basis"]
        if record_id not in basis:
            raise VerificationError(
                "projection completeness dimension does not exist"
            )
        return basis[record_id]
    if kind == "current_goal":
        if record_id != "current_goal":
            raise VerificationError("current goal record ID must be current_goal")
        return projection["current_goal"]
    if kind == "scope_boundary":
        for direction in ("in_scope", "out_of_scope"):
            for boundary in projection["scope_boundaries"][direction]:
                if boundary["boundary_id"] == record_id:
                    return {"direction": direction, "boundary": boundary}
        raise VerificationError("projection record does not exist")
    metadata = RECONCILIATION_COLLECTIONS.get(kind)
    if metadata is None:
        raise VerificationError("projection record kind is invalid")
    collection_name, id_field = metadata
    for item in projection[collection_name]:
        if item[id_field] == record_id:
            return item
    raise VerificationError("projection record does not exist")


def _projection_record_summary(
    kind: str,
    record_id: str,
    value: Mapping[str, Any],
) -> Mapping[str, Any]:
    summary: dict[str, Any] = {
        "kind": kind,
        "id": record_id,
        "jcs_sha256": sha256_jcs(value),
    }
    source = (
        value.get("boundary")
        if kind == "scope_boundary" and isinstance(value.get("boundary"), Mapping)
        else value
    )
    if isinstance(source, Mapping):
        for field in (
            "status",
            "claim_key",
            "role",
            "authority_status",
            "severity",
            "blocking",
            "trace_status",
            "area",
        ):
            if field in source:
                summary[field] = source[field]
        if "kind" in source:
            summary["semantic_kind"] = source["kind"]
        evidence = source.get("evidence")
        if isinstance(evidence, list):
            summary["evidence_count"] = len(evidence)
    if kind == "scope_boundary":
        summary["direction"] = value["direction"]
    return summary


def _compact_projection_view(
    projection: Mapping[str, Any],
    *,
    cursor: int = 0,
) -> Mapping[str, Any]:
    if cursor < 0:
        raise VerificationError("compact projection cursor is invalid")
    projection = _projection_with_runtime_completeness_basis(projection)
    goal = projection["current_goal"]
    compact_goal: dict[str, Any] = {
        "status": goal["status"],
        "jcs_sha256": sha256_jcs(goal),
    }
    if goal.get("status") == "active":
        compact_goal["statement"] = goal["statement"]
    else:
        compact_goal["reason"] = goal["reason"]
    records: list[Mapping[str, Any]] = [
        _projection_record_summary(
            "current_goal",
            "current_goal",
            projection["current_goal"],
        )
    ]
    for dimension, basis in projection["completeness_basis"].items():
        records.append(
            _projection_record_summary(
                "completeness",
                str(dimension),
                basis,
            )
        )
    for direction in ("in_scope", "out_of_scope"):
        for boundary in projection["scope_boundaries"][direction]:
            records.append(
                _projection_record_summary(
                    "scope_boundary",
                    str(boundary["boundary_id"]),
                    {"direction": direction, "boundary": boundary},
                )
            )
    for kind, (collection_name, id_field) in RECONCILIATION_COLLECTIONS.items():
        for item in projection[collection_name]:
            records.append(
                _projection_record_summary(
                    kind,
                    str(item[id_field]),
                    item,
                )
            )
    record_priority = {
        "current_goal": 0,
        "completeness": 1,
        "effective_claim": 2,
        "contested_claim": 3,
        "scope_boundary": 4,
        "in_progress_item": 5,
        "next_action": 6,
        "open_question": 7,
        "blocking_conflict": 8,
        "risk": 9,
        "completed_item": 10,
        "superseded_claim": 11,
        "rejected_option": 12,
        "nonblocking_contradiction": 13,
        "known_gap": 14,
        "artifact_authority": 15,
        "evidence_index_entry": 16,
    }
    records.sort(
        key=lambda item: (
            record_priority.get(str(item["kind"]), 99),
            str(item["id"]),
        )
    )
    page_size = 32
    page = records[cursor : cursor + page_size]
    next_cursor = (
        cursor + len(page)
        if cursor + len(page) < len(records)
        else None
    )
    delta_index = [
        {
            "delta_id": delta["delta_id"],
            "evidence_entry_id": delta["evidence_entry_id"],
            "message_count": len(delta["message_evidence"]),
        }
        for delta in projection["unprojected_deltas"]
    ]
    current_authorities = [
        item
        for item in projection["artifact_authorities"]
        if item["authority_status"]
        in {"current_authoritative", "current_companion"}
    ]
    return {
        "projection_id": projection["projection_id"],
        "completeness": projection["completeness"],
        "current_goal": compact_goal,
        "unprojected_delta_index": delta_index,
        "record_index": [
            {
                "kind": item["kind"],
                "id": item["id"],
                "jcs_sha256": item["jcs_sha256"],
            }
            for item in page
        ],
        "record_page": {
            "legend": ["addressable_kind", "stable_id", "jcs_sha256"],
            "total": len(records),
            "returned": len(page),
            "cursor": cursor,
            "next_cursor": next_cursor,
            "complete": next_cursor is None,
        },
        "current_artifact_authorities": [
            {
                "artifact_id": item["artifact_id"],
                "sha256": item["sha256"],
                "authority_status": item["authority_status"],
                "jcs_sha256": sha256_jcs(item),
            }
            for item in current_authorities[:16]
        ],
        "current_artifact_authority_page": {
            "total": len(current_authorities),
            "returned": min(16, len(current_authorities)),
            "complete": len(current_authorities) <= 16,
            "remaining_records_are_in_paginated_record_index": (
                len(current_authorities) > 16
            ),
        },
        "artifact_authority_total": len(
            projection["artifact_authorities"]
        ),
        "usage": {
            "edit": (
                "Fetch only the exact record that must change with "
                "--kind KIND --id ID, then submit a typed v2 patch."
            ),
            "completeness_basis": (
                "Fetch one dimension with --kind completeness --id "
                "DIMENSION to recover its current reason and evidence."
            ),
            "delta_evidence": (
                "Fetch one delta with --delta-id DELTA_ID, then use "
                "trace-evidence with its entry ID/reference index for exact text."
            ),
            "diagnostic_full_view": (
                "Use --full only for exceptional diagnosis; normal "
                "reconciliation must not rewrite the whole projection."
            ),
        },
    }


def show_memory_projection_command(
    args: argparse.Namespace,
    engine: SyncEngine,
) -> Mapping[str, Any]:
    task_id = validate_identifier(args.task_id, "task_id")
    authority = "remote_verified"
    with FileLock(engine.lock_path):
        try:
            engine.git.ensure()
        except (OfflineError, ConflictError):
            if not engine.git.has_cache():
                raise
            authority = "cached_reference_only"
        remote = load_remote_task_by_id(engine.git, task_id)
    if not isinstance(remote.memory_projection, Mapping):
        raise VerificationError("task has no structured memory projection")
    projection = remote.memory_projection
    selected_modes = sum(
        (
            bool(args.full),
            args.kind is not None or args.record_id is not None,
            args.delta_id is not None,
        )
    )
    if selected_modes > 1:
        raise VerificationError(
            "--full, --kind/--id, and --delta-id are mutually exclusive"
        )
    if bool(args.full):
        body: Mapping[str, Any] = {
            "schema_version": "memory-vault-memory-projection-full-view/v1",
            "projection": dict(projection),
        }
    elif args.kind is not None or args.record_id is not None:
        if args.kind is None or args.record_id is None:
            raise VerificationError("--kind and --id must be supplied together")
        kind = str(args.kind)
        record_id = validate_identifier(args.record_id, "projection record ID")
        body = {
            "schema_version": "memory-vault-memory-projection-record-view/v1",
            "kind": kind,
            "id": record_id,
            "record": dict(_projection_record(projection, kind, record_id)),
        }
    elif args.delta_id is not None:
        delta_id = validate_identifier(args.delta_id, "projection delta ID")
        matches = [
            delta
            for delta in projection["unprojected_deltas"]
            if delta["delta_id"] == delta_id
        ]
        if len(matches) != 1:
            raise VerificationError("projection delta does not exist")
        delta = matches[0]
        body = {
            "schema_version": "memory-vault-memory-delta-view/v1",
            "delta": dict(delta),
            "trace_requests": [
                {
                    "entry_id": delta["evidence_entry_id"],
                    "reference_index": index,
                    "message_ordinal": reference["message_ordinal"],
                }
                for index, reference in enumerate(delta["message_evidence"])
            ],
        }
    else:
        body = {
            "schema_version": "memory-vault-memory-projection-compact-view/v1",
            **_compact_projection_view(
                projection,
                cursor=int(getattr(args, "cursor", 0)),
            ),
        }
    result = {
        **body,
        "task_id": task_id,
        "current_blob_sha": remote.current_blob_sha,
        "snapshot_id": remote.current["snapshot_id"],
        "authority": authority,
    }
    encoded = json.dumps(
        result,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    limit = (
        MAX_CODEX_JSON_BYTES
        if bool(args.full) or args.kind is not None or args.delta_id is not None
        else COMPACT_RECONCILIATION_VIEW_MAX_BYTES
    )
    if len(encoded) > limit:
        raise VerificationError(
            "compact memory projection view exceeds 12 KiB; fetch an exact "
            "record by stable kind and ID"
            if limit == COMPACT_RECONCILIATION_VIEW_MAX_BYTES
            else "memory projection view exceeds the safe limit"
        )
    assert_remote_safe(result)
    return result


def _load_reconciliation_proposal_v1(
    value: Mapping[str, Any],
) -> Mapping[str, Any]:
    fields = {
        "schema_version",
        "task_id",
        "source_projection_id",
        "resolved_delta_ids",
        "outcome",
        "outcome_rationale",
        "result_refs",
        "retired_refs",
        "retirement_message_evidence",
        "evidence_entry_ids",
        "projection",
    }
    _require_keys(
        value,
        required=fields,
        allowed=fields,
        label="memory reconciliation proposal",
    )
    if value.get("schema_version") != "memory-vault-reconciliation-proposal/v1":
        raise VerificationError("memory reconciliation proposal schema is invalid")
    validate_identifier(value.get("task_id"), "proposal.task_id")
    validate_identifier(
        value.get("source_projection_id"),
        "proposal.source_projection_id",
    )
    _projection_id_list(
        value.get("resolved_delta_ids"),
        "proposal.resolved_delta_ids",
        minimum=1,
        maximum=32,
    )
    if value.get("outcome") not in {
        "state_updated",
        "evidence_only_no_semantic_change",
    }:
        raise VerificationError("memory reconciliation outcome is invalid")
    _projection_text(
        value.get("outcome_rationale"),
        "proposal.outcome_rationale",
    )
    result_refs = _projection_unique_items(
        value.get("result_refs"),
        "proposal.result_refs",
        minimum=1,
        maximum=256,
    )
    for index, result in enumerate(result_refs):
        result = _projection_object(
            result,
            {"kind", "id"},
            f"proposal.result_refs[{index}]",
        )
        if result.get("kind") not in {
            "current_goal",
            "scope_boundary",
            "effective_claim",
            "contested_claim",
            "superseded_claim",
            "rejected_option",
            "artifact_authority",
            "completed_item",
            "in_progress_item",
            "next_action",
            "open_question",
            "risk",
            "blocking_conflict",
            "nonblocking_contradiction",
            "known_gap",
            "evidence_index_entry",
        }:
            raise VerificationError("memory reconciliation result kind is invalid")
        result_id = validate_identifier(result.get("id"), "proposal result ID")
        if result.get("kind") == "current_goal" and result_id != "current_goal":
            raise VerificationError(
                "proposal current_goal result ID must be current_goal"
            )
    retired_refs = _projection_unique_items(
        value.get("retired_refs"),
        "proposal.retired_refs",
        maximum=256,
    )
    for index, retired in enumerate(retired_refs):
        retired = _projection_object(
            retired,
            {"kind", "id"},
            f"proposal.retired_refs[{index}]",
        )
        if retired.get("kind") not in {
            "scope_boundary",
            "effective_claim",
            "contested_claim",
            "superseded_claim",
            "rejected_option",
            "artifact_authority",
            "completed_item",
            "in_progress_item",
            "next_action",
            "open_question",
            "risk",
            "blocking_conflict",
            "nonblocking_contradiction",
            "known_gap",
        }:
            raise VerificationError(
                "memory reconciliation retired result kind is invalid"
            )
        validate_identifier(retired.get("id"), "proposal retired result ID")
    retirement_evidence = _projection_unique_items(
        value.get("retirement_message_evidence"),
        "proposal.retirement_message_evidence",
        maximum=256,
    )
    for index, evidence in enumerate(retirement_evidence):
        verified = _validate_projection_evidence_ref(
            evidence,
            f"proposal.retirement_message_evidence[{index}]",
        )
        if verified.get("kind") != "source_message":
            raise VerificationError(
                "proposal retirement evidence must contain source messages"
            )
    _projection_id_list(
        value.get("evidence_entry_ids"),
        "proposal.evidence_entry_ids",
        minimum=1,
        maximum=128,
    )
    if not isinstance(value.get("projection"), Mapping):
        raise VerificationError("memory reconciliation projection is invalid")
    assert_remote_safe(value)
    return value


def _validate_reconciliation_completeness(
    value: Any,
) -> Mapping[str, Any]:
    fields = {
        "overall",
        "goal_and_scope",
        "decisions",
        "rationales",
        "progress",
        "artifacts",
        "conflicts",
        "evidence",
    }
    completeness = _projection_object(
        value,
        fields,
        "proposal.completeness",
    )
    if completeness.get("overall") not in {"complete", "partial"}:
        raise VerificationError("proposal completeness overall is invalid")
    for field in fields - {"overall"}:
        if completeness.get(field) not in {"complete", "partial", "unknown"}:
            raise VerificationError(
                f"proposal completeness {field} is invalid"
            )
    return completeness


def _validate_short_evidence_selectors(
    value: Any,
    label: str,
    *,
    required: bool,
) -> list[Mapping[str, Any]]:
    selectors = _projection_unique_items(
        value,
        label,
        minimum=1 if required else 0,
        maximum=256,
    )
    for index, selector in enumerate(selectors):
        item_label = f"{label}[{index}]"
        if not isinstance(selector, Mapping):
            raise VerificationError(f"{item_label} must be an object")
        if "delta_id" in selector:
            selector = _projection_object(
                selector,
                {"delta_id", "message_ordinals"},
                item_label,
            )
            validate_identifier(
                selector.get("delta_id"),
                f"{item_label}.delta_id",
            )
            ordinals = _projection_unique_items(
                selector.get("message_ordinals"),
                f"{item_label}.message_ordinals",
                minimum=1,
                maximum=64,
            )
        elif "entry_id" in selector:
            selector = _projection_object(
                selector,
                {"entry_id", "reference_indexes"},
                item_label,
            )
            validate_identifier(
                selector.get("entry_id"),
                f"{item_label}.entry_id",
            )
            ordinals = _projection_unique_items(
                selector.get("reference_indexes"),
                f"{item_label}.reference_indexes",
                minimum=1,
                maximum=256,
            )
        else:
            raise VerificationError(
                f"{item_label} is not a supported short evidence selector"
            )
        if any(
            not isinstance(number, int)
            or isinstance(number, bool)
            or number < 0
            for number in ordinals
        ):
            raise VerificationError(f"{item_label} index is invalid")
    return selectors


def _load_reconciliation_proposal_v2(
    value: Mapping[str, Any],
) -> Mapping[str, Any]:
    required = {
        "schema_version",
        "task_id",
        "source_projection_id",
        "resolved_delta_ids",
        "outcome_rationale",
        "operations",
        "message_dispositions",
        "completeness_assertions",
    }
    _require_keys(
        value,
        required=required,
        allowed=required,
        label="typed memory reconciliation proposal",
    )
    validate_identifier(value.get("task_id"), "proposal.task_id")
    validate_identifier(
        value.get("source_projection_id"),
        "proposal.source_projection_id",
    )
    resolved = set(
        _projection_id_list(
            value.get("resolved_delta_ids"),
            "proposal.resolved_delta_ids",
            minimum=1,
            maximum=32,
        )
    )
    _projection_text(
        value.get("outcome_rationale"),
        "proposal.outcome_rationale",
    )
    operations = _projection_unique_items(
        value.get("operations"),
        "proposal.operations",
        maximum=256,
    )
    operation_ids: set[str] = set()
    targets: set[tuple[str, str]] = set()
    for index, operation in enumerate(operations):
        label = f"proposal.operations[{index}]"
        if not isinstance(operation, Mapping):
            raise VerificationError(f"{label} must be an object")
        op = operation.get("op")
        fields = {
            "operation_id",
            "op",
            "kind",
            "id",
            "evidence",
        }
        if op == "upsert":
            fields.add("value")
        elif op != "retire":
            raise VerificationError(f"{label}.op is invalid")
        has_prior = "prior_jcs_sha256" in operation
        expects_absent = operation.get("expect_absent") is True
        if has_prior == expects_absent:
            raise VerificationError(
                f"{label} must declare exactly one record precondition"
            )
        if has_prior:
            fields.add("prior_jcs_sha256")
        else:
            fields.add("expect_absent")
        operation = _projection_object(operation, fields, label)
        operation_id = validate_identifier(
            operation.get("operation_id"),
            f"{label}.operation_id",
        )
        if operation_id in operation_ids:
            raise VerificationError(
                "typed reconciliation operation ID is duplicated"
            )
        operation_ids.add(operation_id)
        kind = operation.get("kind")
        if kind not in RECONCILIATION_OPERATION_KINDS:
            raise VerificationError(f"{label}.kind is invalid")
        record_id = validate_identifier(operation.get("id"), f"{label}.id")
        if kind == "current_goal" and record_id != "current_goal":
            raise VerificationError(
                "typed current_goal operation ID must be current_goal"
            )
        if kind == "current_goal" and op == "retire":
            raise VerificationError("current goal cannot be retired")
        if op == "retire" and kind in {
            "completed_item",
            "superseded_claim",
            "rejected_option",
            "artifact_authority",
        }:
            raise VerificationError(
                f"{label} must transition immutable history instead of retiring it"
            )
        if has_prior:
            validate_sha256(
                operation.get("prior_jcs_sha256"),
                f"{label}.prior_jcs_sha256",
            )
        elif op != "upsert":
            raise VerificationError(
                f"{label} cannot retire a record expected to be absent"
            )
        target = (str(kind), record_id)
        if target in targets:
            raise VerificationError(
                "typed reconciliation repeats one semantic target"
            )
        targets.add(target)
        _validate_short_evidence_selectors(
            operation.get("evidence"),
            f"{label}.evidence",
            required=True,
        )
        if op == "upsert" and not isinstance(
            operation.get("value"), Mapping
        ):
            raise VerificationError(f"{label}.value must be an object")
    dispositions = _projection_unique_items(
        value.get("message_dispositions"),
        "proposal.message_dispositions",
        minimum=1,
        maximum=1024,
    )
    disposition_keys: set[tuple[str, int]] = set()
    for index, disposition in enumerate(dispositions):
        label = f"proposal.message_dispositions[{index}]"
        if not isinstance(disposition, Mapping):
            raise VerificationError(f"{label} must be an object")
        mode = disposition.get("disposition")
        fields = {"delta_id", "message_ordinal", "disposition"}
        if mode == "applied":
            fields.add("operation_ids")
        elif mode == "evidence_only":
            fields.add("reason")
        else:
            raise VerificationError(f"{label}.disposition is invalid")
        disposition = _projection_object(disposition, fields, label)
        delta_id = validate_identifier(
            disposition.get("delta_id"),
            f"{label}.delta_id",
        )
        ordinal = disposition.get("message_ordinal")
        if (
            not isinstance(ordinal, int)
            or isinstance(ordinal, bool)
            or ordinal < 0
        ):
            raise VerificationError(f"{label}.message_ordinal is invalid")
        key = (delta_id, ordinal)
        if key in disposition_keys:
            raise VerificationError(
                "one resolved message has multiple disposition rows"
            )
        disposition_keys.add(key)
        if delta_id not in resolved:
            raise VerificationError(
                "message disposition cites an unresolved delta"
            )
        if mode == "applied":
            applied = set(
                _projection_id_list(
                    disposition.get("operation_ids"),
                    f"{label}.operation_ids",
                    minimum=1,
                    maximum=256,
                )
            )
            if not applied <= operation_ids:
                raise VerificationError(
                    "message disposition cites an unknown operation"
                )
        else:
            _projection_text(disposition.get("reason"), f"{label}.reason")
    assertions = _projection_unique_items(
        value.get("completeness_assertions"),
        "proposal.completeness_assertions",
        maximum=7,
    )
    dimensions = {
        "goal_and_scope",
        "decisions",
        "rationales",
        "progress",
        "artifacts",
        "conflicts",
        "evidence",
    }
    seen_dimensions: set[str] = set()
    for index, assertion in enumerate(assertions):
        label = f"proposal.completeness_assertions[{index}]"
        assertion = _projection_object(
            assertion,
            {"dimension", "status", "reason", "evidence"},
            label,
        )
        dimension = assertion.get("dimension")
        if dimension not in dimensions or dimension in seen_dimensions:
            raise VerificationError(
                "proposal completeness assertion dimension is invalid"
            )
        seen_dimensions.add(str(dimension))
        if assertion.get("status") not in {
            "complete",
            "partial",
            "unknown",
        }:
            raise VerificationError(
                "proposal completeness assertion status is invalid"
            )
        _projection_text(assertion.get("reason"), f"{label}.reason")
        _validate_short_evidence_selectors(
            assertion.get("evidence"),
            f"{label}.evidence",
            required=assertion.get("status") == "complete",
        )
    assert_remote_safe(value)
    return value


def _load_reconciliation_proposal(path: Path) -> Mapping[str, Any]:
    original = path.expanduser()
    if not original.is_absolute():
        original = Path.cwd() / original
    assert_plain_path(original, require_file=True)
    resolved = original.resolve(strict=True)
    assert_plain_path(resolved, require_file=True)
    proposal_size = resolved.stat().st_size
    if proposal_size > MAX_CODEX_JSON_BYTES:
        raise PrivacyError("memory reconciliation proposal exceeds the size limit")
    value = load_json(resolved)
    if not isinstance(value, Mapping):
        raise VerificationError("memory reconciliation proposal is not an object")
    schema_version = value.get("schema_version")
    if schema_version == "memory-vault-reconciliation-patch/v2":
        if proposal_size > RECONCILIATION_PATCH_MAX_BYTES:
            raise PrivacyError(
                "typed memory reconciliation patch exceeds 24 KiB"
            )
        return _load_reconciliation_proposal_v2(value)
    if schema_version == "memory-vault-reconciliation-proposal/v1":
        raise VerificationError(
            "full-projection reconciliation v1 is disabled; use the compact "
            "typed v2 patch"
        )
    raise VerificationError("memory reconciliation proposal schema is invalid")


def _store_pending_reconciliation(
    engine: SyncEngine,
    proposal: Mapping[str, Any],
    *,
    expected_current_blob_sha: str,
    observed_current_blob_sha: str | None,
    ticket_record: tuple[
        Path,
        dict[str, Any],
        dict[str, Any],
    ] | None = None,
) -> str:
    task_id = validate_identifier(proposal.get("task_id"), "pending task_id")
    source_projection_id = validate_identifier(
        proposal.get("source_projection_id"),
        "pending source projection ID",
    )
    expected_current_blob_sha = validate_git_sha(
        expected_current_blob_sha,
        "pending expected CURRENT blob",
    )
    if observed_current_blob_sha is not None:
        validate_git_sha(
            observed_current_blob_sha,
            "pending observed CURRENT blob",
        )
    proposal_digest, transaction_id = (
        _reconciliation_ticket_proposal_identity(
            task_id,
            expected_current_blob_sha,
            proposal,
        )
    )
    pending_id = validate_identifier(
        "reconcile-pending-"
        + proposal_digest[:32],
        "pending reconciliation ID",
    )
    pending_path = (
        engine.data_dir
        / "state"
        / "reconciliation-pending"
        / f"{pending_id}.json"
    )
    terminal_path = (
        engine.data_dir
        / "state"
        / "reconciliation-terminal"
        / f"{pending_id}.json"
    )
    if terminal_path.exists():
        return pending_id
    existing_pending: dict[str, Any] | None = None
    if pending_path.exists():
        (
            existing_pending,
            existing_proposal,
            existing_authorized,
        ) = _load_pending_reconciliation(engine, pending_path)
        if (
            sha256_jcs(existing_proposal) != sha256_jcs(proposal)
            or existing_pending.get("proposal_digest") != proposal_digest
            or existing_pending.get("transaction_id") != transaction_id
        ):
            raise IdentityError(
                "existing pending reconciliation identity changed"
            )
        if (
            existing_authorized
            or ticket_record is None
            or ticket_record[1].get("proposal_digest") is None
        ):
            return pending_id
    authorization: Mapping[str, Any] | None = None
    if (
        ticket_record is not None
        and ticket_record[1].get("proposal_digest") is not None
    ):
        _assert_reconciliation_ticket_proposal(
            ticket_record[1],
            task_id=task_id,
            expected_current_blob_sha=expected_current_blob_sha,
            proposal=proposal,
        )
        ticket = ticket_record[1]
        session = ticket_record[2]
        try:
            expires_at = dt.datetime.fromisoformat(
                str(ticket["expires_at"]).replace("Z", "+00:00")
            )
        except ValueError as exc:
            raise IdentityError(
                "pending authorization ticket expiry is invalid"
            ) from exc
        base = session.get("base")
        manifest = session.get("base_manifest")
        projection_reference = (
            manifest.get("memory_projection")
            if isinstance(manifest, Mapping)
            else None
        )
        if (
            ticket.get("state") != "issued"
            or expires_at <= dt.datetime.now(dt.timezone.utc)
            or ticket.get("proposal_digest") != proposal_digest
            or ticket.get("transaction_id") != transaction_id
            or not isinstance(ticket.get("proposal_bound_at"), str)
            or ticket.get("task_id") != task_id
            or ticket.get("source_projection_id")
            != source_projection_id
            or ticket.get("expected_current_blob_sha")
            != expected_current_blob_sha
            or session.get("schema_version") != SESSION_SCHEMA
            or session.get("session_key") not in {
                None,
                ticket.get("session_key"),
            }
            or session.get("task_id") != task_id
            or session.get("binding_id") != ticket.get("binding_id")
            or session.get("identity_kind")
            != ticket.get("identity_kind")
            or session.get("workspace_lineage_id")
            != ticket.get("workspace_lineage_id")
            or not isinstance(base, Mapping)
            or base.get("task_current_blob_sha")
            != expected_current_blob_sha
            or not isinstance(projection_reference, Mapping)
            or projection_reference.get("projection_id")
            != source_projection_id
        ):
            raise IdentityError(
                "pending reconciliation lacks an exact bound authorization"
            )
        authorization = {
            "schema_version": (
                "memory-vault-reconciliation-durable-authorization/v1"
            ),
            "ticket_token_sha256": ticket["token_sha256"],
            "session_key": ticket["session_key"],
            "turn_id": ticket["turn_id"],
            "turn_key": ticket["turn_key"],
            "binding_id": ticket["binding_id"],
            "identity_kind": ticket["identity_kind"],
            "workspace_lineage_id": ticket["workspace_lineage_id"],
            "task_id": task_id,
            "source_projection_id": source_projection_id,
            "expected_current_blob_sha": expected_current_blob_sha,
            "proposal_digest": proposal_digest,
            "transaction_id": transaction_id,
            "authorized_at": ticket["proposal_bound_at"],
            "ticket_expires_at": ticket["expires_at"],
        }
    record: dict[str, Any] = (
        dict(existing_pending)
        if existing_pending is not None
        else {
            "schema_version": "memory-vault-reconciliation-pending/v2",
            "pending_id": pending_id,
            "task_id": task_id,
            "source_projection_id": source_projection_id,
            "expected_current_blob_sha": expected_current_blob_sha,
            "observed_current_blob_sha": observed_current_blob_sha,
            "proposal_digest": proposal_digest,
            "transaction_id": transaction_id,
            "proposal": dict(proposal),
            "authorization": None,
            "created_at": utc_now(),
        }
    )
    if authorization is not None:
        record["authorization"] = dict(authorization)
    record.pop("integrity_hmac_sha256", None)
    device = _device_state(engine.data_dir)
    record["integrity_hmac_sha256"] = hmac.new(
        str(device["device_secret"]).encode("ascii"),
        jcs_json_bytes(record),
        hashlib.sha256,
    ).hexdigest()
    atomic_write_json(pending_path, record)
    return pending_id


def _typed_parent_records(
    projection: Mapping[str, Any],
) -> dict[tuple[str, str], Mapping[str, Any]]:
    result: dict[tuple[str, str], Mapping[str, Any]] = {
        ("current_goal", "current_goal"): projection["current_goal"]
    }
    for direction in ("in_scope", "out_of_scope"):
        for boundary in projection["scope_boundaries"][direction]:
            result[("scope_boundary", str(boundary["boundary_id"]))] = {
                "direction": direction,
                "boundary": boundary,
            }
    for kind, (collection_name, id_field) in RECONCILIATION_COLLECTIONS.items():
        if kind == "evidence_index_entry":
            continue
        for item in projection[collection_name]:
            result[(kind, str(item[id_field]))] = item
    return result


def _expand_short_evidence(
    selectors: Sequence[Mapping[str, Any]],
    parent_projection: Mapping[str, Any],
    *,
    resolved_delta_ids: set[str],
) -> tuple[list[Mapping[str, Any]], set[tuple[str, int]]]:
    deltas = {
        str(delta["delta_id"]): delta
        for delta in parent_projection["unprojected_deltas"]
    }
    entries = {
        str(entry["entry_id"]): entry
        for entry in parent_projection["evidence_index"]
    }
    resolved_messages: dict[
        bytes,
        tuple[str, int],
    ] = {}
    for delta_id in resolved_delta_ids:
        delta = deltas.get(delta_id)
        if delta is None:
            raise VerificationError(
                "short evidence selector cites an unknown resolved delta"
            )
        for reference in delta["message_evidence"]:
            resolved_messages[jcs_json_bytes(reference)] = (
                delta_id,
                int(reference["message_ordinal"]),
            )
    references: list[Mapping[str, Any]] = []
    message_keys: set[tuple[str, int]] = set()
    seen: set[bytes] = set()
    for selector in selectors:
        selected: list[Mapping[str, Any]]
        if "delta_id" in selector:
            delta_id = str(selector["delta_id"])
            if delta_id not in resolved_delta_ids:
                raise VerificationError(
                    "short evidence selector cites an unresolved delta"
                )
            delta = deltas[delta_id]
            by_ordinal = {
                int(reference["message_ordinal"]): reference
                for reference in delta["message_evidence"]
            }
            requested = [int(item) for item in selector["message_ordinals"]]
            if any(ordinal not in by_ordinal for ordinal in requested):
                raise VerificationError(
                    "short evidence selector cites an unknown message ordinal"
                )
            selected = [by_ordinal[ordinal] for ordinal in requested]
        else:
            entry_id = str(selector["entry_id"])
            entry = entries.get(entry_id)
            if entry is None:
                raise VerificationError(
                    "short evidence selector cites an unknown evidence entry"
                )
            entry_references = entry["references"]
            indexes = [int(item) for item in selector["reference_indexes"]]
            if any(index >= len(entry_references) for index in indexes):
                raise VerificationError(
                    "short evidence selector reference index is out of range"
                )
            selected = [entry_references[index] for index in indexes]
        for reference in selected:
            canonical = jcs_json_bytes(reference)
            if canonical not in seen:
                references.append(dict(reference))
                seen.add(canonical)
            resolved_key = resolved_messages.get(canonical)
            if resolved_key is not None:
                message_keys.add(resolved_key)
    return references, message_keys


def _inject_typed_operation_evidence(
    kind: str,
    raw_value: Mapping[str, Any],
    references: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    value = strict_json_loads(
        json.dumps(raw_value, ensure_ascii=False, allow_nan=False)
    )
    if not isinstance(value, dict):
        raise VerificationError("typed operation value is invalid")
    if "evidence" in value:
        raise VerificationError(
            "typed operation value must use short evidence selectors"
        )
    if kind not in {"artifact_authority", "scope_boundary"}:
        value["evidence"] = [dict(reference) for reference in references]
    rationale = value.get("rationale")
    if isinstance(rationale, dict):
        if "evidence" in rationale:
            raise VerificationError(
                "typed claim rationale must use short evidence selectors"
            )
        rationale["evidence"] = [
            dict(reference) for reference in references
        ]
    rejection = value.get("rejection_rationale")
    if isinstance(rejection, dict):
        if "evidence" in rejection:
            raise VerificationError(
                "typed rejection rationale must use short evidence selectors"
            )
        rejection["evidence"] = [
            dict(reference) for reference in references
        ]
    verification = value.get("verification")
    if isinstance(verification, dict):
        if "evidence" in verification:
            raise VerificationError(
                "typed artifact verification must use short evidence selectors"
            )
        verification["evidence"] = [
            dict(reference) for reference in references
        ]
        checks = verification.get("checks")
        if isinstance(checks, list):
            for check in checks:
                if not isinstance(check, dict):
                    raise VerificationError(
                        "typed artifact verification check is invalid"
                    )
                if "evidence" in check:
                    raise VerificationError(
                        "typed artifact check must use short evidence selectors"
                    )
                check["evidence"] = [
                    dict(reference) for reference in references
                ]
    return value


def _set_typed_projection_record(
    projection: MutableMapping[str, Any],
    kind: str,
    record_id: str,
    value: Mapping[str, Any] | None,
) -> None:
    if kind == "current_goal":
        if value is None:
            raise VerificationError("current goal cannot be retired")
        projection["current_goal"] = dict(value)
        return
    if kind == "scope_boundary":
        scope = projection["scope_boundaries"]
        for direction in ("in_scope", "out_of_scope"):
            scope[direction] = [
                item
                for item in scope[direction]
                if str(item["boundary_id"]) != record_id
            ]
        if value is not None:
            direction = value.get("direction")
            boundary = value.get("boundary")
            if (
                direction not in {"in_scope", "out_of_scope"}
                or not isinstance(boundary, Mapping)
                or boundary.get("boundary_id") != record_id
            ):
                raise VerificationError(
                    "typed scope value identity is inconsistent"
                )
            scope[str(direction)].append(dict(boundary))
            scope[str(direction)].sort(key=lambda item: str(item["boundary_id"]))
        return
    metadata = RECONCILIATION_COLLECTIONS.get(kind)
    if metadata is None or kind == "evidence_index_entry":
        raise VerificationError("typed projection record kind is invalid")
    collection_name, id_field = metadata
    collection = [
        item
        for item in projection[collection_name]
        if str(item[id_field]) != record_id
    ]
    if value is not None:
        if value.get(id_field) != record_id:
            raise VerificationError(
                "typed operation value identity is inconsistent"
            )
        collection.append(dict(value))
    collection.sort(key=lambda item: str(item[id_field]))
    projection[collection_name] = collection


def _projection_completeness_basis_for_reconciliation(
    projection: Mapping[str, Any],
) -> dict[str, Mapping[str, Any]]:
    dimensions = (
        "goal_and_scope",
        "decisions",
        "rationales",
        "progress",
        "artifacts",
        "conflicts",
        "evidence",
    )
    existing = projection.get("completeness_basis")
    if isinstance(existing, Mapping):
        copied = strict_json_loads(
            json.dumps(
                existing,
                ensure_ascii=False,
                allow_nan=False,
            )
        )
        if not isinstance(copied, dict):
            raise VerificationError(
                "parent completeness basis is invalid"
            )
        return copied
    return {
        dimension: {
            "status": "unknown",
            "reason": LEGACY_COMPLETENESS_BASIS_REASON,
            "evidence": [],
        }
        for dimension in dimensions
    }


def _apply_typed_reconciliation_patch(
    parent_projection: Mapping[str, Any],
    proposal: Mapping[str, Any],
    *,
    transaction_id: str,
) -> dict[str, Any]:
    runtime_parent = _projection_with_runtime_completeness_basis(
        parent_projection
    )
    projection = strict_json_loads(
        json.dumps(runtime_parent, ensure_ascii=False, allow_nan=False)
    )
    if not isinstance(projection, dict):
        raise VerificationError("parent projection cannot be patched")
    parent_records = _typed_parent_records(runtime_parent)
    parent_deltas = {
        str(delta["delta_id"]): delta
        for delta in runtime_parent["unprojected_deltas"]
    }
    resolved_delta_ids = set(proposal["resolved_delta_ids"])
    if not resolved_delta_ids <= set(parent_deltas):
        raise VerificationError(
            "typed reconciliation resolves an unknown parent delta"
        )
    resolved_message_refs: dict[
        tuple[str, int],
        Mapping[str, Any],
    ] = {}
    for delta_id in resolved_delta_ids:
        for reference in parent_deltas[delta_id]["message_evidence"]:
            key = (delta_id, int(reference["message_ordinal"]))
            if key in resolved_message_refs:
                raise VerificationError(
                    "resolved delta repeats one message ordinal"
                )
            resolved_message_refs[key] = reference

    dispositions: dict[tuple[str, int], Mapping[str, Any]] = {}
    for disposition in proposal["message_dispositions"]:
        key = (
            str(disposition["delta_id"]),
            int(disposition["message_ordinal"]),
        )
        dispositions[key] = disposition
    if set(dispositions) != set(resolved_message_refs):
        raise VerificationError(
            "typed reconciliation does not disposition every exact message"
        )

    operation_evidence: dict[
        str,
        tuple[list[Mapping[str, Any]], set[tuple[str, int]]],
    ] = {}
    for operation in proposal["operations"]:
        operation_id = str(operation["operation_id"])
        expanded = _expand_short_evidence(
            operation["evidence"],
            runtime_parent,
            resolved_delta_ids=resolved_delta_ids,
        )
        if not expanded[1]:
            raise VerificationError(
                "state-changing operation has no resolved message evidence"
            )
        operation_evidence[operation_id] = expanded
    for key, disposition in dispositions.items():
        if disposition["disposition"] == "evidence_only":
            if any(
                key in message_keys
                for _references, message_keys in operation_evidence.values()
            ):
                raise VerificationError(
                    "evidence-only message is also applied to an operation"
                )
            continue
        applied_ids = set(disposition["operation_ids"])
        for operation_id in applied_ids:
            if key not in operation_evidence[operation_id][1]:
                raise VerificationError(
                    "applied disposition is absent from operation evidence"
                )
    for operation_id, (_references, message_keys) in operation_evidence.items():
        for key in message_keys:
            disposition = dispositions[key]
            if (
                disposition["disposition"] != "applied"
                or operation_id not in disposition["operation_ids"]
            ):
                raise VerificationError(
                    "operation evidence has no matching applied disposition"
                )

    changed_refs: list[dict[str, str]] = []
    retired_refs: list[dict[str, str]] = []
    retirement_messages: dict[bytes, Mapping[str, Any]] = {}
    for operation in proposal["operations"]:
        kind = str(operation["kind"])
        record_id = str(operation["id"])
        key = (kind, record_id)
        before = parent_records.get(key)
        prior_hash = operation.get("prior_jcs_sha256")
        if prior_hash is not None:
            if before is None or sha256_jcs(before) != prior_hash:
                raise ConflictError(
                    "typed reconciliation record precondition changed"
                )
        elif before is not None or operation.get("expect_absent") is not True:
            raise ConflictError(
                "typed reconciliation expected an absent record"
            )
        references, _message_keys = operation_evidence[
            str(operation["operation_id"])
        ]
        if operation["op"] == "retire":
            if before is None:
                raise ConflictError(
                    "typed reconciliation cannot retire an absent record"
                )
            _set_typed_projection_record(
                projection,
                kind,
                record_id,
                None,
            )
            retired_refs.append({"kind": kind, "id": record_id})
            for message_key in _message_keys:
                reference = resolved_message_refs[message_key]
                retirement_messages[jcs_json_bytes(reference)] = reference
        else:
            value = _inject_typed_operation_evidence(
                kind,
                operation["value"],
                references,
            )
            if kind == "scope_boundary":
                boundary = value.get("boundary")
                if not isinstance(boundary, dict):
                    raise VerificationError(
                        "typed scope operation has no boundary value"
                    )
                if "evidence" in boundary:
                    raise VerificationError(
                        "typed scope boundary must use short evidence selectors"
                    )
                boundary["evidence"] = [
                    dict(reference) for reference in references
                ]
            _set_typed_projection_record(
                projection,
                kind,
                record_id,
                value,
            )
            after = _typed_parent_records(projection).get(key)
            if after is None or (
                before is not None
                and jcs_json_bytes(before) == jcs_json_bytes(after)
            ):
                raise VerificationError(
                    "typed upsert did not change its semantic record"
                )
            changed_refs.append({"kind": kind, "id": record_id})
    # Effective decisions are never silently deleted.  A retirement must move
    # the same stable identity into the contested or superseded collection in
    # this atomic patch.
    for retired in retired_refs:
        if retired["kind"] != "effective_claim":
            continue
        record_id = retired["id"]
        if not any(
            item["kind"] in {"contested_claim", "superseded_claim"}
            and item["id"] == record_id
            for item in changed_refs
        ):
            raise VerificationError(
                "effective claim retirement lacks an atomic claim transition"
            )

    projection["unprojected_deltas"] = [
        dict(delta)
        for delta in runtime_parent["unprojected_deltas"]
        if str(delta["delta_id"]) not in resolved_delta_ids
    ]
    completeness = dict(runtime_parent["completeness"])
    dimensions = (
        "goal_and_scope",
        "decisions",
        "rationales",
        "progress",
        "artifacts",
        "conflicts",
        "evidence",
    )
    completeness_basis = (
        _projection_completeness_basis_for_reconciliation(
            runtime_parent
        )
    )
    completeness_transitions: list[dict[str, Any]] = []
    for assertion in proposal["completeness_assertions"]:
        references, message_keys = _expand_short_evidence(
            assertion["evidence"],
            runtime_parent,
            resolved_delta_ids=resolved_delta_ids,
        )
        dimension = str(assertion["dimension"])
        before_status = str(completeness[dimension])
        after_status = str(assertion["status"])
        if not references or not message_keys:
            raise VerificationError(
                "completeness transition lacks resolved exact evidence"
            )
        before_basis = completeness_basis[dimension]
        after_basis = {
            "status": after_status,
            "reason": str(assertion["reason"]),
            "evidence": [dict(reference) for reference in references],
        }
        if jcs_json_bytes(before_basis) == jcs_json_bytes(after_basis):
            raise VerificationError(
                "completeness assertion does not change status or basis"
            )
        reason = str(assertion["reason"])
        transition = {
            "dimension": dimension,
            "before": before_status,
            "after": after_status,
            "change_kind": (
                "status_changed"
                if before_status != after_status
                else "basis_refreshed"
            ),
            "before_basis_sha256": sha256_jcs(before_basis),
            "after_basis_sha256": sha256_jcs(after_basis),
            "reason": reason,
            "evidence": [dict(reference) for reference in references],
        }
        completeness_transitions.append(transition)
        completeness[dimension] = after_status
        completeness_basis[dimension] = after_basis
    if projection["unprojected_deltas"]:
        if any(
            completeness[dimension] == "complete"
            for dimension in dimensions
        ):
            raise VerificationError(
                "projection with remaining deltas cannot claim completeness"
            )
        completeness["overall"] = "partial"
    else:
        completeness["overall"] = (
            "complete"
            if all(
                completeness[dimension] == "complete"
                for dimension in dimensions
            )
            else "partial"
        )
    projection["completeness"] = completeness
    projection["completeness_basis"] = completeness_basis

    evidence_entry_ids = sorted(
        {
            str(parent_deltas[delta_id]["evidence_entry_id"])
            for delta_id in resolved_delta_ids
        }
    )
    receipt_messages = [
        dict(reference)
        for delta in runtime_parent["unprojected_deltas"]
        if str(delta["delta_id"]) in resolved_delta_ids
        for reference in delta["message_evidence"]
    ]
    result_refs = [
        *changed_refs,
        *(
            {
                "kind": "completeness",
                "id": transition["dimension"],
            }
            for transition in completeness_transitions
        ),
        *(
            {"kind": "evidence_index_entry", "id": entry_id}
            for entry_id in evidence_entry_ids
        ),
    ]
    projection["reconciliation_receipts"] = [
        {
            "receipt_id": validate_identifier(
                f"receipt-{sha256_bytes(transaction_id.encode('ascii'))[:32]}",
                "reconciliation receipt ID",
            ),
            "source_projection_id": runtime_parent["projection_id"],
            "resolved_delta_ids": list(proposal["resolved_delta_ids"]),
            "message_evidence": receipt_messages,
            "outcome": (
                "state_updated"
                if proposal["operations"] or completeness_transitions
                else "evidence_only_no_semantic_change"
            ),
            "outcome_rationale": proposal["outcome_rationale"],
            "result_refs": result_refs,
            "retired_refs": retired_refs,
            "retirement_message_evidence": [
                dict(retirement_messages[key])
                for key in sorted(retirement_messages)
            ],
            "completeness_transitions": completeness_transitions,
            "evidence_entry_ids": evidence_entry_ids,
            "status": "semantically_reconciled",
        }
    ]

    # Evidence-index entries are a rebuildable index.  Retain only entries
    # required by the new state, current deltas, or this transition receipt.
    semantic_copy = dict(projection)
    semantic_copy["evidence_index"] = []
    semantic_copy["reconciliation_receipts"] = []
    semantic_copy["unprojected_deltas"] = []
    semantic_refs = {
        jcs_json_bytes(reference)
        for reference in _projection_evidence_refs(semantic_copy)
    }
    required_entry_ids = set(evidence_entry_ids) | {
        str(delta["evidence_entry_id"])
        for delta in projection["unprojected_deltas"]
    }
    projection["evidence_index"] = [
        dict(entry)
        for entry in runtime_parent["evidence_index"]
        if str(entry["entry_id"]) in required_entry_ids
        or any(
            jcs_json_bytes(reference) in semantic_refs
            for reference in entry["references"]
        )
    ]
    return projection


def _reconciliation_identity(
    task_id: str,
    expected_current_blob_sha: str,
    proposal: Mapping[str, Any],
) -> tuple[str, str, str, str]:
    """Return a retry-stable identity for a typed reconciliation.

    The compact typed patch is the externally supported reconciliation
    protocol.  Its immutable paths must therefore survive an ambiguous Git
    push result: retrying the same patch against the same parent CURRENT must
    address the same transaction, snapshot, and projection.  The disabled
    legacy full-projection protocol keeps its historical UUID behavior.
    """

    if (
        proposal.get("schema_version")
        == "memory-vault-reconciliation-patch/v2"
    ):
        digest = sha256_jcs(
            {
                "task_id": task_id,
                "expected_current_blob_sha": expected_current_blob_sha,
                "proposal": proposal,
            }
        )
        return (
            validate_identifier(
                f"memrec-{digest[:40]}",
                "memory reconciliation transaction ID",
            ),
            validate_identifier(
                f"snap-memrec-{digest[:32]}",
                "memory reconciliation snapshot ID",
            ),
            validate_identifier(
                f"proj-memrec-{digest[:32]}",
                "memory reconciliation projection ID",
            ),
            digest,
        )
    random_digest = uuid.uuid4().hex
    return (
        validate_identifier(
            f"memrec-{random_digest}",
            "memory reconciliation transaction ID",
        ),
        validate_identifier(
            f"snap-memrec-{uuid.uuid4().hex[:32]}",
            "memory reconciliation snapshot ID",
        ),
        validate_identifier(
            f"proj-memrec-{uuid.uuid4().hex[:32]}",
            "memory reconciliation projection ID",
        ),
        random_digest,
    )


def _reconciliation_parent_commit(
    git: GitVault,
    remote: RemoteTaskState,
) -> str:
    """Locate the stable atomic commit for the exact parent snapshot."""

    # Unit-level document tests intentionally use a minimal stand-in instead
    # of a repository.  Production always receives GitVault and resolves the
    # path history so unrelated later commits cannot perturb deterministic
    # reconciliation bytes.
    if not isinstance(git, GitVault):
        return validate_git_sha(
            remote.commit_sha,
            "memory reconciliation parent commit",
        )
    # CURRENT is mutable and the same bytes can legitimately recur after a
    # forward rollback/revert.  Its immutable manifest path is unique to the
    # snapshot, so the manifest's sole introduction commit is the canonical
    # parent forever.  Requiring the exact CURRENT in that same commit also
    # proves that the baseline pointer and version were atomically published.
    manifest_raw = git.show_bytes(remote.manifest_path)
    manifest_commits = git.path_commits(
        remote.manifest_path,
        maximum=2,
    )
    projection_path = remote.memory_projection_path
    projection_raw = (
        git.show_bytes(projection_path)
        if isinstance(projection_path, str)
        else None
    )
    projection_commits = (
        git.path_commits(projection_path, maximum=2)
        if isinstance(projection_path, str)
        else []
    )
    if (
        len(manifest_commits) != 1
        or len(projection_commits) != 1
        or projection_commits[0] != manifest_commits[0]
        or not {
            remote.current_path,
            remote.manifest_path,
            projection_path,
        }
        <= git.commit_changed_paths(manifest_commits[0])
        or git.show_bytes_at(
            manifest_commits[0],
            remote.manifest_path,
        )
        != manifest_raw
        or git_blob_sha(
            git.show_bytes_at(
                manifest_commits[0],
                remote.current_path,
            )
        )
        != remote.current_blob_sha
        or projection_raw is None
        or git.show_bytes_at(
            manifest_commits[0],
            projection_path,
        )
        != projection_raw
    ):
        raise VerificationError(
            "memory reconciliation parent manifest and CURRENT were not "
            "atomically introduced"
        )
    return manifest_commits[0]


def _reconciliation_documents(
    git: GitVault,
    remote: RemoteTaskState,
    proposal: Mapping[str, Any],
    *,
    candidate: bool = False,
    existing_recovery: bool = False,
) -> tuple[dict[str, bytes], str, str]:
    if (
        not existing_recovery
        and not candidate
        and (
            remote.current.get("state") not in {"active", "paused"}
            or remote.task.get("status")
            in {"archived", "split", "candidate"}
        )
    ):
        raise ConflictError(
            "memory reconciliation cannot activate a non-active task"
        )
    parent_projection = remote.memory_projection
    if not isinstance(parent_projection, Mapping):
        raise VerificationError(
            "memory reconciliation requires a projected parent task"
        )
    parent_projection = _projection_with_runtime_completeness_basis(
        parent_projection
    )
    if proposal.get("source_projection_id") != parent_projection.get(
        "projection_id"
    ):
        raise ConflictError(
            "memory reconciliation proposal targets a different projection"
        )
    parent_deltas = {
        str(delta["delta_id"]): delta
        for delta in parent_projection["unprojected_deltas"]
    }
    resolved_delta_ids = set(proposal["resolved_delta_ids"])
    if not resolved_delta_ids <= set(parent_deltas):
        raise VerificationError(
            "memory reconciliation resolves an unknown parent delta"
        )

    (
        transaction_id,
        snapshot_id,
        projection_id,
        _proposal_digest,
    ) = _reconciliation_identity(
        str(remote.current["task_id"]),
        remote.current_blob_sha,
        proposal,
    )
    task_id = str(remote.current["task_id"])
    manifest_path = f"tasks/{task_id}/versions/{snapshot_id}.json"
    projection_path = f"tasks/{task_id}/projections/{projection_id}.json"

    if (
        proposal.get("schema_version")
        == "memory-vault-reconciliation-patch/v2"
    ):
        proposed_projection = _apply_typed_reconciliation_patch(
            parent_projection,
            proposal,
            transaction_id=transaction_id,
        )
    else:
        proposed_projection = strict_json_loads(
            json.dumps(
                proposal["projection"],
                ensure_ascii=False,
                allow_nan=False,
            )
        )
        if not isinstance(proposed_projection, dict):
            raise VerificationError("memory reconciliation projection is invalid")
    proposed_projection["schema_version"] = "task-memory-projection/v1"
    proposed_projection["projection_id"] = projection_id
    proposed_projection["authority"] = "rebuildable_task_handoff_cache"
    proposed_projection["basis"] = {
        "task_id": task_id,
        "snapshot_id": snapshot_id,
        "generation": int(remote.current["generation"]) + 1,
        "transaction_id": transaction_id,
        "manifest_path": manifest_path,
        "source_current_precondition": {
            "current_blob_sha": remote.current_blob_sha,
            "snapshot_id": remote.current["snapshot_id"],
            "generation": remote.current["generation"],
            "transaction_id": remote.current["published_transaction_id"],
        },
    }
    if proposal.get("schema_version") != "memory-vault-reconciliation-patch/v2":
        proposed_projection["unprojected_deltas"] = [
            dict(delta)
            for delta_id, delta in parent_deltas.items()
            if delta_id not in resolved_delta_ids
        ]
    if (
        proposed_projection["unprojected_deltas"]
        and proposal.get("schema_version")
        != "memory-vault-reconciliation-patch/v2"
    ):
        proposed_projection["completeness"]["overall"] = "partial"
        for dimension in (
            "goal_and_scope",
            "decisions",
            "rationales",
            "progress",
            "artifacts",
            "conflicts",
            "evidence",
        ):
            proposed_projection["completeness"][dimension] = "partial"
    if proposal.get("schema_version") != "memory-vault-reconciliation-patch/v2":
        receipt_messages = [
            reference
            for delta_id in proposal["resolved_delta_ids"]
            for reference in parent_deltas[str(delta_id)]["message_evidence"]
        ]
        result_refs = [
            {"kind": result["kind"], "id": result["id"]}
            for result in proposal["result_refs"]
        ]
        proposed_projection["reconciliation_receipts"] = [
            {
                "receipt_id": validate_identifier(
                    f"receipt-{sha256_bytes(transaction_id.encode('ascii'))[:32]}",
                    "reconciliation receipt ID",
                ),
                "source_projection_id": parent_projection["projection_id"],
                "resolved_delta_ids": list(proposal["resolved_delta_ids"]),
                "message_evidence": receipt_messages,
                "outcome": proposal["outcome"],
                "outcome_rationale": proposal["outcome_rationale"],
                "result_refs": result_refs,
                "retired_refs": [
                    {"kind": retired["kind"], "id": retired["id"]}
                    for retired in proposal["retired_refs"]
                ],
                "retirement_message_evidence": [
                    dict(reference)
                    for reference in proposal["retirement_message_evidence"]
                ],
                "completeness_transitions": [],
                "evidence_entry_ids": list(proposal["evidence_entry_ids"]),
                "status": "semantically_reconciled",
            }
        ]
    if not isinstance(
        proposed_projection.get("completeness_basis"),
        Mapping,
    ):
        raise VerificationError(
            "new reconciliation projection lacks completeness bases"
        )
    _validate_task_memory_projection_structure(proposed_projection)

    required_source_keys: set[tuple[str, str]] = set()
    for reference in _projection_evidence_refs(proposed_projection):
        if reference.get("kind") == "source_message":
            required_source_keys.add(
                (
                    str(reference["source_id"]),
                    str(reference["revision_id"]),
                )
            )
        elif reference.get("kind") == "memory_event":
            event_id = validate_identifier(
                reference.get("memory_event_id"),
                "reconciliation memory event ID",
            )
            event = git.show_json(f"memory/events/{event_id}.json")
            _validate_memory_event_document(event, event_id=event_id)
            source = event["source"]
            required_source_keys.add(
                (str(source["source_id"]), str(source["revision_id"]))
            )
    parent_evidence = _task_version_source_evidence(remote.manifest)
    missing_source_keys = required_source_keys - set(parent_evidence)
    if missing_source_keys:
        raise VerificationError(
            "memory reconciliation references an unpinned source revision"
        )
    successor_evidence_sources = [
        dict(parent_evidence[key]) for key in sorted(required_source_keys)
    ]

    version: dict[str, Any] = {
        "schema_version": "task-version/v1",
        "task_id": task_id,
        "snapshot_id": snapshot_id,
        "generation": int(remote.current["generation"]) + 1,
        "state": "candidate" if candidate else "published",
        "transaction_id": transaction_id,
        "change_type": "content_revision",
        "continuation_readiness": (
            "blocked"
            if proposed_projection["blocking_conflicts"]
            else (
                "ready"
                if (
                    not proposed_projection["unprojected_deltas"]
                    and proposed_projection["completeness"]["overall"]
                    == "complete"
                )
                else "partial"
            )
        ),
        "parents": [
            {
                "kind": "version_snapshot",
                "snapshot_id": remote.current["snapshot_id"],
                "commit": _reconciliation_parent_commit(git, remote),
                "path": remote.manifest_path,
            }
        ],
        "artifacts": [
            dict(artifact) for artifact in remote.manifest["artifacts"]
        ],
    }
    for key in (
        "conversation_sources",
        "coverage",
        "verification",
        "observed_children",
    ):
        if key in remote.manifest:
            version[key] = strict_json_loads(
                json.dumps(
                    remote.manifest[key],
                    ensure_ascii=False,
                    allow_nan=False,
                )
            )
    if successor_evidence_sources:
        version["evidence_sources"] = successor_evidence_sources
    projection_bytes = pretty_json_bytes(proposed_projection)
    version["memory_projection"] = {
        "projection_id": projection_id,
        "path": projection_path,
        "content_sha256": sha256_bytes(projection_bytes),
    }
    current = {
        "schema_version": "task-current/v1",
        "task_id": task_id,
        "generation": version["generation"],
        "state": remote.current["state"],
        "snapshot_id": snapshot_id,
        "manifest_path": manifest_path,
        "continuation_readiness": version["continuation_readiness"],
        "published_transaction_id": transaction_id,
        "authority": {
            "strategy": "git-blob-sha-compare-and-swap",
            "timestamps_are_authoritative": False,
        },
    }
    _validate_task_version(version)
    _validate_task_current(current)
    _validate_projection_semantics(
        git,
        current,
        manifest_path,
        version,
        proposed_projection,
        strict_successor=True,
    )
    files = {
        projection_path: projection_bytes,
        manifest_path: pretty_json_bytes(version),
    }
    if not candidate:
        files[remote.current_path] = pretty_json_bytes(current)
    return files, transaction_id, snapshot_id


def _historical_task_state_by_current_blob(
    git: GitVault,
    latest: RemoteTaskState,
    expected_current_blob_sha: str,
) -> RemoteTaskState:
    try:
        current_raw = git.show_blob_bytes(expected_current_blob_sha)
    except VaultSyncError as exc:
        raise ConflictError(
            "expected reconciliation CURRENT blob is unavailable"
        ) from exc
    if git_blob_sha(current_raw) != expected_current_blob_sha:
        raise VerificationError(
            "historical reconciliation CURRENT blob identity is invalid"
        )
    try:
        current = strict_json_loads(current_raw.decode("utf-8"))
    except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
        raise VerificationError(
            "historical reconciliation CURRENT is invalid"
        ) from exc
    if not isinstance(current, Mapping):
        raise VerificationError(
            "historical reconciliation CURRENT is invalid"
        )
    _validate_task_current(current)
    if current.get("task_id") != latest.current.get("task_id"):
        raise VerificationError(
            "historical reconciliation task identity changed"
        )
    manifest_path = validate_repo_path(
        current.get("manifest_path"),
        "historical reconciliation manifest path",
    )
    manifest_raw = git.show_bytes(manifest_path)
    git.assert_immutable_path(manifest_path, manifest_raw)
    manifest_commits = git.path_commits(manifest_path, maximum=2)
    if len(manifest_commits) != 1:
        raise VerificationError(
            "historical reconciliation manifest is not immutable"
        )
    commit = manifest_commits[0]
    if (
        git.show_bytes_at(commit, manifest_path) != manifest_raw
        or git.show_bytes_at(commit, latest.current_path) != current_raw
    ):
        raise VerificationError(
            "historical reconciliation CURRENT and manifest were not "
            "atomically introduced"
        )
    try:
        manifest = strict_json_loads(manifest_raw.decode("utf-8"))
    except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
        raise VerificationError(
            "historical reconciliation manifest is invalid"
        ) from exc
    if not isinstance(manifest, Mapping):
        raise VerificationError(
            "historical reconciliation manifest is invalid"
        )
    _validate_task_version(manifest)
    if (
        manifest.get("task_id") != latest.current.get("task_id")
        or manifest.get("snapshot_id") != current.get("snapshot_id")
        or manifest.get("generation") != current.get("generation")
        or manifest.get("transaction_id")
        != current.get("published_transaction_id")
    ):
        raise VerificationError(
            "historical reconciliation baseline is inconsistent"
        )
    reference = manifest.get("memory_projection")
    if not isinstance(reference, Mapping):
        raise VerificationError(
            "historical reconciliation baseline has no projection"
        )
    projection_path = validate_repo_path(
        reference.get("path"),
        "historical reconciliation projection path",
    )
    projection_raw = git.show_bytes(projection_path)
    git.assert_immutable_path(projection_path, projection_raw)
    projection_commits = git.path_commits(
        projection_path,
        maximum=2,
    )
    if (
        len(projection_commits) != 1
        or projection_commits[0] != commit
        or not {
            latest.current_path,
            manifest_path,
            projection_path,
        }
        <= git.commit_changed_paths(commit)
        or git.show_bytes_at(commit, projection_path) != projection_raw
        or sha256_bytes(projection_raw)
        != reference.get("content_sha256")
    ):
        raise VerificationError(
            "historical reconciliation projection was not atomically "
            "introduced"
        )
    try:
        projection = strict_json_loads(projection_raw.decode("utf-8"))
    except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
        raise VerificationError(
            "historical reconciliation projection is invalid"
        ) from exc
    if not isinstance(projection, Mapping):
        raise VerificationError(
            "historical reconciliation projection is invalid"
        )
    projection = _projection_with_runtime_completeness_basis(projection)
    return RemoteTaskState(
        commit_sha=commit,
        task_path=latest.task_path,
        task=latest.task,
        current_path=latest.current_path,
        current_blob_sha=expected_current_blob_sha,
        current=current,
        manifest_path=manifest_path,
        manifest=manifest,
        memory_projection_path=projection_path,
        memory_projection=projection,
    )


def _existing_typed_reconciliation(
    git: GitVault,
    latest: RemoteTaskState,
    task_id: str,
    expected_current_blob_sha: str,
    proposal: Mapping[str, Any],
) -> Mapping[str, Any] | None:
    """Verify and classify a retry-stable typed reconciliation already remote."""

    if (
        proposal.get("schema_version")
        != "memory-vault-reconciliation-patch/v2"
    ):
        return None
    (
        transaction_id,
        snapshot_id,
        projection_id,
        _proposal_digest,
    ) = _reconciliation_identity(
        task_id,
        expected_current_blob_sha,
        proposal,
    )
    version_path = f"tasks/{task_id}/versions/{snapshot_id}.json"
    # `is True` deliberately prevents loose test doubles from being treated
    # as proof that an immutable remote path exists.
    file_exists = getattr(git, "file_exists", None)
    if not callable(file_exists) or file_exists(version_path) is not True:
        return None
    version_raw = git.show_bytes(version_path)
    try:
        version = strict_json_loads(version_raw.decode("utf-8"))
    except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
        raise ConflictError(
            "deterministic reconciliation version is invalid"
        ) from exc
    if not isinstance(version, Mapping):
        raise ConflictError(
            "deterministic reconciliation version is invalid"
        )
    _validate_task_version(version)
    projection_reference = version.get("memory_projection")
    expected_projection_path = (
        f"tasks/{task_id}/projections/{projection_id}.json"
    )
    if (
        version.get("task_id") != task_id
        or version.get("snapshot_id") != snapshot_id
        or version.get("transaction_id") != transaction_id
        or not isinstance(projection_reference, Mapping)
        or projection_reference.get("projection_id") != projection_id
        or projection_reference.get("path") != expected_projection_path
    ):
        raise ConflictError(
            "deterministic reconciliation path is occupied"
        )
    existing_state = version.get("state")
    if existing_state not in {"published", "candidate"}:
        raise ConflictError(
            "deterministic reconciliation transaction is inconsistent"
        )
    projection_raw = git.show_bytes(expected_projection_path)
    if (
        sha256_bytes(projection_raw)
        != projection_reference.get("content_sha256")
    ):
        raise ConflictError(
            "deterministic reconciliation projection hash is inconsistent"
        )
    try:
        projection = strict_json_loads(projection_raw.decode("utf-8"))
    except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
        raise ConflictError(
            "deterministic reconciliation projection is invalid"
        ) from exc
    if not isinstance(projection, Mapping):
        raise ConflictError(
            "deterministic reconciliation projection is invalid"
        )
    _validate_task_memory_projection_structure(projection)
    if projection.get("projection_id") != projection_id:
        raise ConflictError(
            "deterministic reconciliation projection identity is inconsistent"
        )

    base_state = (
        latest
        if latest.current_blob_sha == expected_current_blob_sha
        else _historical_task_state_by_current_blob(
            git,
            latest,
            expected_current_blob_sha,
        )
    )
    expected_files, regenerated_transaction, regenerated_snapshot = (
        _reconciliation_documents(
            git,
            base_state,
            proposal,
            candidate=existing_state == "candidate",
            existing_recovery=True,
        )
    )
    if (
        regenerated_transaction != transaction_id
        or regenerated_snapshot != snapshot_id
        or expected_files.get(version_path) != version_raw
        or expected_files.get(expected_projection_path) != projection_raw
    ):
        raise ConflictError(
            "deterministic reconciliation content or parent baseline "
            "is inconsistent"
        )
    git.assert_immutable_path(version_path, version_raw)
    git.assert_immutable_path(expected_projection_path, projection_raw)
    version_commits = git.path_commits(version_path, maximum=2)
    projection_commits = git.path_commits(
        expected_projection_path,
        maximum=2,
    )
    if (
        len(version_commits) != 1
        or len(projection_commits) != 1
        or projection_commits[0] != version_commits[0]
        or git.show_bytes_at(version_commits[0], version_path)
        != version_raw
        or git.show_bytes_at(
            version_commits[0],
            expected_projection_path,
        )
        != projection_raw
    ):
        raise ConflictError(
            "deterministic reconciliation version and projection were not "
            "atomically introduced"
        )
    transaction_commit = version_commits[0]
    expected_changed_paths = {
        version_path,
        expected_projection_path,
    }
    if existing_state == "published":
        expected_changed_paths.add(latest.current_path)
    changed_paths = getattr(git, "commit_changed_paths", None)
    if (
        not callable(changed_paths)
        or changed_paths(transaction_commit)
        != expected_changed_paths
    ):
        raise ConflictError(
            "deterministic reconciliation transaction changed an unexpected "
            "path"
        )

    relation = "candidate"
    if existing_state == "published":
        published_current = expected_files.get(latest.current_path)
        if published_current is None:
            raise ConflictError(
                "published deterministic reconciliation has no CURRENT"
            )
        if (
            git.show_bytes_at(
                transaction_commit,
                latest.current_path,
            )
            != published_current
        ):
            raise ConflictError(
                "published reconciliation version, projection, and CURRENT "
                "were not atomically introduced"
            )
        is_current = (
            latest.current.get("snapshot_id") == snapshot_id
            and latest.current.get("published_transaction_id")
            == transaction_id
            and git.show_bytes(latest.current_path) == published_current
        )
        if is_current:
            relation = "current"
        else:
            relation = "historical"
    else:
        try:
            current_at_transaction = git.show_bytes_at(
                transaction_commit,
                latest.current_path,
            )
        except (KeyError, OSError, VaultSyncError) as exc:
            raise ConflictError(
                "candidate reconciliation commit does not prove its remote "
                "basis"
            ) from exc
        remote_advanced_at_transaction = (
            git_blob_sha(current_at_transaction)
            != expected_current_blob_sha
        )
        frozen_at_transaction = False
        try:
            task_at_transaction = strict_json_loads(
                git.show_bytes_at(
                    transaction_commit,
                    latest.task_path,
                ).decode("utf-8")
            )
        except (
            KeyError,
            OSError,
            VaultSyncError,
            UnicodeDecodeError,
            ValueError,
            json.JSONDecodeError,
        ):
            task_at_transaction = None
        if isinstance(task_at_transaction, Mapping):
            frozen_at_transaction = (
                _historical_task_identity_supported(task_at_transaction)
                and task_at_transaction.get("task_id") == task_id
                and task_at_transaction.get("status")
                in {"archived", "split", "candidate"}
            )
        if not remote_advanced_at_transaction and not frozen_at_transaction:
            raise ConflictError(
                "candidate reconciliation commit does not prove a prior "
                "remote advance or frozen task"
            )
        if (
            latest.current.get("snapshot_id") == snapshot_id
            or latest.current.get("published_transaction_id")
            == transaction_id
        ):
            raise ConflictError(
                "candidate deterministic reconciliation became CURRENT"
            )

    return {
        "state": existing_state,
        "relation": relation,
        "transaction_id": transaction_id,
        "snapshot_id": snapshot_id,
        "projection_id": projection_id,
        "commit": version_commits[0],
    }


def _load_bootstrap_projection_proposal(
    path: Path,
) -> Mapping[str, Any]:
    original = path.expanduser()
    if not original.is_absolute():
        original = Path.cwd() / original
    assert_plain_path(original, require_file=True)
    resolved = original.resolve(strict=True)
    assert_plain_path(resolved, require_file=True)
    if resolved.stat().st_size > RECONCILIATION_PATCH_MAX_BYTES:
        raise PrivacyError("projection bootstrap patch exceeds 24 KiB")
    value = load_json(resolved)
    if not isinstance(value, Mapping):
        raise VerificationError(
            "projection bootstrap proposal is not an object"
        )
    fields = {
        "schema_version",
        "task_id",
        "operations",
        "completeness_assertions",
    }
    _require_keys(
        value,
        required=fields,
        allowed=fields,
        label="projection bootstrap proposal",
    )
    if (
        value.get("schema_version")
        != "memory-vault-projection-bootstrap-patch/v1"
    ):
        raise VerificationError(
            "projection bootstrap proposal schema is invalid"
        )
    validate_identifier(value.get("task_id"), "bootstrap task_id")
    operations = _projection_unique_items(
        value.get("operations"),
        "bootstrap operations",
        minimum=1,
        maximum=128,
    )
    targets: set[tuple[str, str]] = set()
    operation_ids: set[str] = set()
    for index, operation in enumerate(operations):
        label = f"bootstrap operations[{index}]"
        operation = _projection_object(
            operation,
            {
                "operation_id",
                "op",
                "kind",
                "id",
                "expect_absent",
                "value",
                "evidence",
            },
            label,
        )
        operation_id = validate_identifier(
            operation.get("operation_id"),
            f"{label}.operation_id",
        )
        if operation_id in operation_ids:
            raise VerificationError(
                "bootstrap operation ID is duplicated"
            )
        operation_ids.add(operation_id)
        if (
            operation.get("op") != "upsert"
            or operation.get("expect_absent") is not True
        ):
            raise VerificationError(
                "bootstrap may only upsert records expected to be absent"
            )
        kind = operation.get("kind")
        if (
            kind not in RECONCILIATION_OPERATION_KINDS
            or kind == "artifact_authority"
        ):
            raise VerificationError(
                "bootstrap operation kind is invalid or unsafe"
            )
        record_id = validate_identifier(
            operation.get("id"),
            f"{label}.id",
        )
        if kind == "current_goal" and record_id != "current_goal":
            raise VerificationError(
                "bootstrap current goal ID must be current_goal"
            )
        target = (str(kind), record_id)
        if target in targets:
            raise VerificationError(
                "bootstrap repeats one semantic target"
            )
        targets.add(target)
        if not isinstance(operation.get("value"), Mapping):
            raise VerificationError(
                "bootstrap operation value is invalid"
            )
        _validate_bootstrap_evidence_selectors(
            operation.get("evidence"),
            f"{label}.evidence",
            required=True,
        )
    if ("current_goal", "current_goal") not in targets:
        raise VerificationError(
            "projection bootstrap requires an explicit current goal"
        )
    assertions = _projection_unique_items(
        value.get("completeness_assertions"),
        "bootstrap completeness assertions",
        minimum=7,
        maximum=7,
    )
    dimensions = {
        "goal_and_scope",
        "decisions",
        "rationales",
        "progress",
        "artifacts",
        "conflicts",
        "evidence",
    }
    seen: set[str] = set()
    for index, assertion in enumerate(assertions):
        label = f"bootstrap completeness_assertions[{index}]"
        assertion = _projection_object(
            assertion,
            {"dimension", "status", "reason", "evidence"},
            label,
        )
        dimension = assertion.get("dimension")
        if dimension not in dimensions or dimension in seen:
            raise VerificationError(
                "bootstrap completeness dimension is invalid"
            )
        seen.add(str(dimension))
        if assertion.get("status") not in {
            "complete",
            "partial",
            "unknown",
        }:
            raise VerificationError(
                "bootstrap completeness status is invalid"
            )
        _projection_text(assertion.get("reason"), f"{label}.reason")
        _validate_bootstrap_evidence_selectors(
            assertion.get("evidence"),
            f"{label}.evidence",
            required=True,
        )
    if seen != dimensions:
        raise VerificationError(
            "bootstrap completeness assertions are incomplete"
        )
    assert_remote_safe(value)
    return value


def _validate_bootstrap_evidence_selectors(
    value: Any,
    label: str,
    *,
    required: bool,
) -> list[Mapping[str, Any]]:
    selectors = _projection_unique_items(
        value,
        label,
        minimum=1 if required else 0,
        maximum=128,
    )
    for index, selector in enumerate(selectors):
        item_label = f"{label}[{index}]"
        selector = _projection_object(
            selector,
            {"source_id", "revision_id", "message_ordinals"},
            item_label,
        )
        validate_identifier(
            selector.get("source_id"),
            f"{item_label}.source_id",
        )
        validate_identifier(
            selector.get("revision_id"),
            f"{item_label}.revision_id",
        )
        ordinals = _projection_unique_items(
            selector.get("message_ordinals"),
            f"{item_label}.message_ordinals",
            minimum=1,
            maximum=64,
        )
        if any(
            not isinstance(ordinal, int)
            or isinstance(ordinal, bool)
            or ordinal < 0
            for ordinal in ordinals
        ):
            raise VerificationError(
                "bootstrap evidence message ordinal is invalid"
            )
    return selectors


def _expand_bootstrap_evidence(
    git: GitVault,
    remote: RemoteTaskState,
    selectors: Sequence[Mapping[str, Any]],
) -> list[Mapping[str, Any]]:
    durable = _task_version_source_evidence(remote.manifest)
    references: list[Mapping[str, Any]] = []
    seen: set[bytes] = set()
    for selector in selectors:
        source_id = str(selector["source_id"])
        revision_id = str(selector["revision_id"])
        evidence_source = durable.get((source_id, revision_id))
        if evidence_source is None:
            raise VerificationError(
                "bootstrap evidence is not pinned by the CURRENT manifest"
            )
        _confirmed_source_binding(
            git,
            task_id=str(remote.current["task_id"]),
            source_id=source_id,
            source_sequence=int(evidence_source["source_sequence"]),
            expected_binding_id=str(evidence_source["binding_id"]),
        )
        content_path = validate_repo_path(
            evidence_source.get("content_path"),
            "bootstrap evidence content path",
        )
        if (
            content_path
            != f"sources/{source_id}/revisions/{revision_id}.json"
        ):
            raise VerificationError(
                "bootstrap evidence path is inconsistent"
            )
        raw = git.show_bytes(content_path)
        if (
            sha256_bytes(raw)
            != evidence_source.get("content_sha256")
        ):
            raise VerificationError(
                "bootstrap evidence content hash is invalid"
            )
        git.assert_immutable_path(content_path, raw)
        try:
            conversation = strict_json_loads(raw.decode("utf-8"))
        except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
            raise VerificationError(
                "bootstrap evidence conversation is invalid"
            ) from exc
        if not isinstance(conversation, Mapping):
            raise VerificationError(
                "bootstrap evidence conversation is invalid"
            )
        _validate_conversation_export(conversation)
        if conversation.get("source_id") != source_id:
            raise VerificationError(
                "bootstrap evidence source identity is invalid"
            )
        messages = {
            int(message["ordinal"]): message
            for message in conversation["messages"]
            if isinstance(message, Mapping)
        }
        for ordinal in selector["message_ordinals"]:
            message = messages.get(int(ordinal))
            if message is None or not isinstance(message.get("text"), str):
                raise VerificationError(
                    "bootstrap evidence message ordinal does not exist"
                )
            reference = {
                "kind": "source_message",
                "source_id": source_id,
                "revision_id": revision_id,
                "source_sequence": int(
                    evidence_source["source_sequence"]
                ),
                "revision_content_sha256": str(
                    evidence_source["content_sha256"]
                ),
                "message_ordinal": int(ordinal),
                "evidence_anchor_sha256": sha256_bytes(
                    message["text"].encode("utf-8")
                ),
            }
            _validate_projection_evidence_ref(
                reference,
                "expanded bootstrap evidence",
            )
            canonical = jcs_json_bytes(reference)
            if canonical not in seen:
                references.append(reference)
                seen.add(canonical)
    if not references:
        raise VerificationError(
            "projection bootstrap requires exact bound message evidence"
        )
    return references


def _bootstrap_projection_identity(
    task_id: str,
    expected_current_blob_sha: str,
    proposal: Mapping[str, Any],
) -> tuple[str, str, str, str]:
    digest = sha256_jcs(
        {
            "task_id": task_id,
            "expected_current_blob_sha": expected_current_blob_sha,
            "proposal": proposal,
        }
    )
    return (
        validate_identifier(
            f"bootstrap-{digest[:40]}",
            "bootstrap transaction ID",
        ),
        validate_identifier(
            f"snap-bootstrap-{digest[:32]}",
            "bootstrap snapshot ID",
        ),
        validate_identifier(
            f"proj-bootstrap-{digest[:32]}",
            "bootstrap projection ID",
        ),
        digest,
    )


def _bootstrap_projection_document(
    git: GitVault,
    remote: RemoteTaskState,
    proposal: Mapping[str, Any],
    *,
    projection_id: str,
    snapshot_id: str,
    transaction_id: str,
    manifest_path: str,
) -> dict[str, Any]:
    if remote.memory_projection is not None:
        raise ConflictError(
            "task already has a structured memory projection"
        )
    completeness = {
        "overall": "partial",
        "goal_and_scope": "unknown",
        "decisions": "unknown",
        "rationales": "unknown",
        "progress": "unknown",
        "artifacts": "unknown",
        "conflicts": "unknown",
        "evidence": "unknown",
    }
    projection: dict[str, Any] = {
        "schema_version": "task-memory-projection/v1",
        "projection_id": projection_id,
        "authority": "rebuildable_task_handoff_cache",
        "basis": {
            "task_id": remote.current["task_id"],
            "snapshot_id": snapshot_id,
            "generation": int(remote.current["generation"]) + 1,
            "transaction_id": transaction_id,
            "manifest_path": manifest_path,
            "source_current_precondition": {
                "current_blob_sha": remote.current_blob_sha,
                "snapshot_id": remote.current["snapshot_id"],
                "generation": remote.current["generation"],
                "transaction_id": remote.current[
                    "published_transaction_id"
                ],
            },
        },
        "completeness": completeness,
        "current_goal": {
            "status": "unknown",
            "reason": "No verified bootstrap goal was supplied.",
            "evidence": [],
        },
        "scope_boundaries": {"in_scope": [], "out_of_scope": []},
        "unprojected_deltas": [],
        "reconciliation_receipts": [],
        "effective_claims": [],
        "contested_claims": [],
        "superseded_claims": [],
        "rejected_options": [],
        "artifact_authorities": [],
        "unclassified_artifact_policy": (
            "reference_only_do_not_infer_from_filename_or_inventory"
        ),
        "completed": [],
        "in_progress": [],
        "next_actions": [],
        "open_questions": [],
        "risks": [],
        "blocking_conflicts": [],
        "nonblocking_contradictions": [],
        "known_gaps": [],
        "evidence_index": [],
        "trace_policy": {
            "mode": "on_demand_verified_evidence",
            "triggers": {
                "missing_rationale": True,
                "blocking_conflict": True,
                "multiple_same_role_current_authoritative_artifacts": True,
                "user_says_previously_explained": True,
                "projection_gap": True,
            },
            "action": (
                "trace_to_original_verified_evidence_before_asking_or_"
                "changing_state"
            ),
        },
    }
    evidence_groups: dict[
        bytes,
        list[Mapping[str, Any]],
    ] = {}
    completeness_basis: dict[str, Mapping[str, Any]] = {}
    for operation in proposal["operations"]:
        references = _expand_bootstrap_evidence(
            git,
            remote,
            operation["evidence"],
        )
        value = _inject_typed_operation_evidence(
            str(operation["kind"]),
            operation["value"],
            references,
        )
        if operation["kind"] == "scope_boundary":
            boundary = value.get("boundary")
            if not isinstance(boundary, dict):
                raise VerificationError(
                    "bootstrap scope operation is invalid"
                )
            if "evidence" in boundary:
                raise VerificationError(
                    "bootstrap scope value contains expanded evidence"
                )
            boundary["evidence"] = [
                dict(reference) for reference in references
            ]
        _set_typed_projection_record(
            projection,
            str(operation["kind"]),
            str(operation["id"]),
            value,
        )
        evidence_groups[jcs_json_bytes(references)] = references
    for assertion in proposal["completeness_assertions"]:
        references = _expand_bootstrap_evidence(
            git,
            remote,
            assertion["evidence"],
        )
        evidence_groups[jcs_json_bytes(references)] = references
        dimension = str(assertion["dimension"])
        completeness[dimension] = assertion["status"]
        completeness_basis[dimension] = {
            "status": assertion["status"],
            "reason": assertion["reason"],
            "evidence": [dict(reference) for reference in references],
        }
    completeness["overall"] = (
        "complete"
        if all(
            completeness[dimension] == "complete"
            for dimension in (
                "goal_and_scope",
                "decisions",
                "rationales",
                "progress",
                "artifacts",
                "conflicts",
                "evidence",
            )
        )
        else "partial"
    )
    projection["completeness_basis"] = completeness_basis

    artifact_refs: list[Mapping[str, Any]] = []
    for artifact in remote.manifest["artifacts"]:
        raw_role = artifact.get("role")
        authority_role = (
            str(raw_role)
            if isinstance(raw_role, str)
            and ID_RE.fullmatch(raw_role)
            and raw_role.lower() not in WINDOWS_RESERVED
            else "legacy-artifact"
        )
        reference = {
            "kind": "artifact",
            "artifact_id": artifact["artifact_id"],
            "sha256": artifact["sha256"],
        }
        artifact_refs.append(reference)
        projection["artifact_authorities"].append(
            {
                "artifact_id": artifact["artifact_id"],
                "sha256": artifact["sha256"],
                "purpose": (
                    "Inherited legacy artifact retained only as a reference "
                    "during first-projection bootstrap."
                ),
                "role": validate_identifier(
                    authority_role,
                    "legacy artifact role",
                ),
                "authority_status": "reference_only",
                "source_snapshot_id": remote.current["snapshot_id"],
                "dependencies": [],
                "verification": {
                    "status": "unverified",
                    "checks": [],
                    "evidence": [reference],
                },
                "relations": [],
            }
        )
    projection["artifact_authorities"].sort(
        key=lambda item: str(item["artifact_id"])
    )
    if artifact_refs:
        gap_id = validate_identifier(
            "gap-bootstrap-artifacts-"
            + sha256_jcs(artifact_refs)[:24],
            "bootstrap artifact gap ID",
        )
        if not any(
            gap["gap_id"] == gap_id
            for gap in projection["known_gaps"]
        ):
            projection["known_gaps"].append(
                {
                    "gap_id": gap_id,
                    "area": "artifact",
                    "statement": (
                        "Inherited artifacts are reference-only until their "
                        "purpose, authority, and verification are explicitly "
                        "reconciled."
                    ),
                    "trace_status": "not_attempted",
                    "evidence": artifact_refs,
                }
            )
        projection["completeness"]["artifacts"] = "partial"
        projection["completeness"]["overall"] = "partial"
        projection["completeness_basis"]["artifacts"] = {
            "status": "partial",
            "reason": (
                "Inherited artifacts remain reference-only until their "
                "authority and verification are explicitly reconciled."
            ),
            "evidence": [dict(reference) for reference in artifact_refs],
        }
    projection["known_gaps"].sort(
        key=lambda item: str(item["gap_id"])
    )
    projection["evidence_index"] = [
        {
            "entry_id": validate_identifier(
                "evidence-bootstrap-" + sha256_bytes(key)[:28],
                "bootstrap evidence entry ID",
            ),
            "topic": (
                "Exact task-bound source messages used to bootstrap the "
                "structured continuation state."
            ),
            "references": [dict(reference) for reference in references],
        }
        for key, references in sorted(
            evidence_groups.items(),
            key=lambda item: item[0],
        )
    ]
    _validate_task_memory_projection_structure(projection)
    return projection


def _bootstrap_projection_documents(
    git: GitVault,
    remote: RemoteTaskState,
    proposal: Mapping[str, Any],
    *,
    candidate: bool,
) -> tuple[dict[str, bytes], str, str, str]:
    if (
        remote.current.get("state") not in {"active", "paused"}
        or remote.task.get("status")
        in {"archived", "split", "candidate"}
    ):
        raise ConflictError(
            "projection bootstrap cannot activate a non-active task"
        )
    (
        transaction_id,
        snapshot_id,
        projection_id,
        _proposal_digest,
    ) = _bootstrap_projection_identity(
        str(remote.current["task_id"]),
        remote.current_blob_sha,
        proposal,
    )
    task_id = str(remote.current["task_id"])
    manifest_path = f"tasks/{task_id}/versions/{snapshot_id}.json"
    projection_path = (
        f"tasks/{task_id}/projections/{projection_id}.json"
    )
    projection = _bootstrap_projection_document(
        git,
        remote,
        proposal,
        projection_id=projection_id,
        snapshot_id=snapshot_id,
        transaction_id=transaction_id,
        manifest_path=manifest_path,
    )
    version: dict[str, Any] = {
        "schema_version": "task-version/v1",
        "task_id": task_id,
        "snapshot_id": snapshot_id,
        "generation": int(remote.current["generation"]) + 1,
        "state": "candidate" if candidate else "published",
        "transaction_id": transaction_id,
        "change_type": "metadata_import",
        "continuation_readiness": (
            "blocked"
            if projection["blocking_conflicts"]
            else (
                "ready"
                if projection["completeness"]["overall"] == "complete"
                else "partial"
            )
        ),
        "parents": [
            {
                "kind": "version_snapshot",
                "snapshot_id": remote.current["snapshot_id"],
                "commit": remote.commit_sha,
                "path": remote.manifest_path,
            }
        ],
        "artifacts": [
            dict(artifact) for artifact in remote.manifest["artifacts"]
        ],
    }
    for key in (
        "conversation_sources",
        "evidence_sources",
        "coverage",
        "verification",
        "observed_children",
        "remaining_work",
        "open_questions",
    ):
        if key in remote.manifest:
            version[key] = strict_json_loads(
                json.dumps(
                    remote.manifest[key],
                    ensure_ascii=False,
                    allow_nan=False,
                )
            )
    projection_bytes = pretty_json_bytes(projection)
    version["memory_projection"] = {
        "projection_id": projection_id,
        "path": projection_path,
        "content_sha256": sha256_bytes(projection_bytes),
    }
    current = {
        "schema_version": "task-current/v1",
        "task_id": task_id,
        "generation": version["generation"],
        "state": remote.current["state"],
        "snapshot_id": snapshot_id,
        "manifest_path": manifest_path,
        "continuation_readiness": version["continuation_readiness"],
        "published_transaction_id": transaction_id,
        "authority": {
            "strategy": "git-blob-sha-compare-and-swap",
            "timestamps_are_authoritative": False,
        },
    }
    _validate_task_version(version)
    _validate_task_current(current)
    _validate_projection_semantics(
        git,
        current,
        manifest_path,
        version,
        projection,
        strict_successor=True,
    )
    files = {
        projection_path: projection_bytes,
        manifest_path: pretty_json_bytes(version),
    }
    if not candidate:
        files[remote.current_path] = pretty_json_bytes(current)
    return files, transaction_id, snapshot_id, projection_id


def _historical_legacy_task_state_by_current_blob(
    git: GitVault,
    latest: RemoteTaskState,
    expected_current_blob_sha: str,
) -> RemoteTaskState:
    for commit in git.path_commits(latest.current_path, maximum=512):
        current_raw = git.show_bytes_at(commit, latest.current_path)
        if git_blob_sha(current_raw) != expected_current_blob_sha:
            continue
        try:
            current = strict_json_loads(current_raw.decode("utf-8"))
        except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
            raise VerificationError(
                "historical bootstrap CURRENT is invalid"
            ) from exc
        if not isinstance(current, Mapping):
            raise VerificationError(
                "historical bootstrap CURRENT is invalid"
            )
        _validate_task_current(current)
        manifest_path = validate_repo_path(
            current.get("manifest_path"),
            "historical bootstrap manifest path",
        )
        manifest_raw = git.show_bytes_at(commit, manifest_path)
        if git.show_bytes(manifest_path) != manifest_raw:
            raise VerificationError(
                "historical bootstrap manifest changed after its commit"
            )
        git.assert_immutable_path(manifest_path, manifest_raw)
        try:
            manifest = strict_json_loads(manifest_raw.decode("utf-8"))
        except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
            raise VerificationError(
                "historical bootstrap manifest is invalid"
            ) from exc
        if not isinstance(manifest, Mapping):
            raise VerificationError(
                "historical bootstrap manifest is invalid"
            )
        _validate_task_version(manifest)
        if (
            manifest.get("task_id") != latest.current.get("task_id")
            or manifest.get("snapshot_id") != current.get("snapshot_id")
            or manifest.get("generation") != current.get("generation")
            or manifest.get("transaction_id")
            != current.get("published_transaction_id")
            or manifest.get("memory_projection") is not None
        ):
            raise VerificationError(
                "historical bootstrap baseline is inconsistent"
            )
        return RemoteTaskState(
            commit_sha=commit,
            task_path=latest.task_path,
            task=latest.task,
            current_path=latest.current_path,
            current_blob_sha=expected_current_blob_sha,
            current=current,
            manifest_path=manifest_path,
            manifest=manifest,
            memory_projection_path=None,
            memory_projection=None,
        )
    raise ConflictError(
        "expected bootstrap CURRENT is not available in verified history"
    )


def bootstrap_memory_projection_command(
    args: argparse.Namespace,
    engine: SyncEngine,
) -> Mapping[str, Any]:
    task_id = validate_identifier(args.task_id, "task_id")
    expected = validate_git_sha(
        args.expected_current_blob_sha,
        "expected bootstrap CURRENT blob",
    )
    proposal = _load_bootstrap_projection_proposal(
        args.proposal_file
    )
    if proposal.get("task_id") != task_id:
        raise VerificationError(
            "projection bootstrap proposal targets a different task"
        )
    (
        expected_transaction_id,
        expected_snapshot_id,
        expected_projection_id,
        _digest,
    ) = _bootstrap_projection_identity(task_id, expected, proposal)
    expected_version_path = (
        f"tasks/{task_id}/versions/{expected_snapshot_id}.json"
    )
    with FileLock(engine.lock_path):
        engine.git.ensure()
        remote = load_remote_task_by_id(engine.git, task_id)
        if (
            remote.current.get("state") not in {"active", "paused"}
            or remote.task.get("status")
            in {"archived", "split", "candidate"}
        ):
            raise ConflictError(
                "projection bootstrap requires an active or paused task"
            )
        if engine.git.file_exists(expected_version_path):
            existing = engine.git.show_json(expected_version_path)
            if (
                existing.get("transaction_id")
                != expected_transaction_id
                or existing.get("memory_projection", {}).get(
                    "projection_id"
                )
                != expected_projection_id
            ):
                raise ConflictError(
                    "deterministic bootstrap path is occupied"
                )
            existing_state = existing.get("state")
            if existing_state not in {"published", "candidate"}:
                raise ConflictError(
                    "deterministic bootstrap transaction is inconsistent"
                )
            expected_base = (
                remote
                if remote.current_blob_sha == expected
                else _historical_legacy_task_state_by_current_blob(
                    engine.git,
                    remote,
                    expected,
                )
            )
            expected_files, _tx, _snapshot, _projection = (
                _bootstrap_projection_documents(
                    engine.git,
                    expected_base,
                    proposal,
                    candidate=existing_state == "candidate",
                )
            )
            projection_path = (
                f"tasks/{task_id}/projections/"
                f"{expected_projection_id}.json"
            )
            if (
                engine.git.show_bytes(expected_version_path)
                != expected_files[expected_version_path]
                or engine.git.show_bytes(projection_path)
                != expected_files[projection_path]
            ):
                raise ConflictError(
                    "deterministic bootstrap content is inconsistent"
                )
            if existing_state == "published":
                return {
                    "schema_version": (
                        "memory-vault-projection-bootstrap-result/v1"
                    ),
                    "status": "already_published",
                    "task_id": task_id,
                    "snapshot_id": expected_snapshot_id,
                    "projection_id": expected_projection_id,
                    "current_blob_sha": remote.current_blob_sha,
                    "historical": (
                        remote.current.get("published_transaction_id")
                        != expected_transaction_id
                    ),
                }
            if existing_state == "candidate":
                return {
                    "schema_version": (
                        "memory-vault-projection-bootstrap-result/v1"
                    ),
                    "status": "candidate_remote_advance",
                    "task_id": task_id,
                    "snapshot_id": expected_snapshot_id,
                    "projection_id": expected_projection_id,
                    "current_blob_sha": remote.current_blob_sha,
                }

        candidate = remote.current_blob_sha != expected
        observed_current_blob_sha = remote.current_blob_sha
        base_state = (
            _historical_legacy_task_state_by_current_blob(
                engine.git,
                remote,
                expected,
            )
            if candidate
            else remote
        )
        if base_state.memory_projection is not None:
            raise ConflictError(
                "projection bootstrap baseline already has a projection"
            )
        files, transaction_id, snapshot_id, projection_id = (
            _bootstrap_projection_documents(
                engine.git,
                base_state,
                proposal,
                candidate=candidate,
            )
        )
        try:
            with engine.git.create_worktree() as worktree:
                engine.git.write_generated_files(worktree, files)
                engine._validate_worktree(worktree, files)
                commit = engine.git.commit_and_push(
                    worktree,
                    files,
                    task_id,
                    transaction_id,
                )
        except ConflictError:
            if candidate:
                raise
            engine.git.fetch()
            latest = load_remote_task_by_id(engine.git, task_id)
            if latest.current_blob_sha == expected:
                raise
            observed_current_blob_sha = latest.current_blob_sha
            files, transaction_id, snapshot_id, projection_id = (
                _bootstrap_projection_documents(
                    engine.git,
                    base_state,
                    proposal,
                    candidate=True,
                )
            )
            with engine.git.create_worktree() as worktree:
                engine.git.write_generated_files(worktree, files)
                engine._validate_worktree(worktree, files)
                commit = engine.git.commit_and_push(
                    worktree,
                    files,
                    task_id,
                    transaction_id,
                )
            candidate = True
        engine.git.fetch()
        verified = load_remote_task_by_id(engine.git, task_id)
        if candidate:
            if verified.current_blob_sha != observed_current_blob_sha:
                raise VerificationError(
                    "bootstrap candidate changed CURRENT"
                )
            candidate_version = engine.git.show_json(
                f"tasks/{task_id}/versions/{snapshot_id}.json"
            )
            if candidate_version.get("state") != "candidate":
                raise VerificationError(
                    "bootstrap candidate was not preserved"
                )
            status = "candidate_remote_advance"
        else:
            if (
                verified.current.get("published_transaction_id")
                != transaction_id
                or not isinstance(
                    verified.memory_projection,
                    Mapping,
                )
                or verified.memory_projection.get("projection_id")
                != projection_id
            ):
                raise VerificationError(
                    "published bootstrap did not become CURRENT"
                )
            status = "published"
        return {
            "schema_version": (
                "memory-vault-projection-bootstrap-result/v1"
            ),
            "status": status,
            "task_id": task_id,
            "snapshot_id": snapshot_id,
            "projection_id": projection_id,
            "commit": commit,
            "current_blob_sha": verified.current_blob_sha,
        }


def _verified_reconciliation_ticket(
    engine: SyncEngine,
    *,
    token: str,
    task_id: str,
    expected_current_blob_sha: str,
    source_projection_id: str,
) -> tuple[Path, dict[str, Any], dict[str, Any]]:
    if not re.fullmatch(r"[A-Za-z0-9_-]{43}", token):
        raise IdentityError("memory reconciliation token is invalid")
    token_sha256 = sha256_bytes(token.encode("ascii"))
    path = _reconciliation_ticket_path(engine.data_dir, token_sha256)
    if not path.exists():
        raise IdentityError("memory reconciliation ticket does not exist")
    ticket = load_json(path)
    fields = {
        "schema_version",
        "token_sha256",
        "session_key",
        "task_id",
        "turn_id",
        "turn_key",
        "binding_id",
        "identity_kind",
        "workspace_lineage_id",
        "source_projection_id",
        "expected_current_blob_sha",
        "issued_at",
        "expires_at",
        "state",
    }
    proposal_binding_fields = {
        "proposal_digest",
        "transaction_id",
        "proposal_bound_at",
    }
    if not isinstance(ticket, dict):
        raise IdentityError("memory reconciliation ticket is invalid")
    _require_keys(
        ticket,
        required=fields,
        allowed=(
            fields
            | proposal_binding_fields
            | {"consumed_at", "invalidated_at"}
        ),
        label="memory reconciliation ticket",
    )
    if (
        ticket.get("schema_version")
        != "memory-vault-reconciliation-ticket/v1"
        or ticket.get("token_sha256") != token_sha256
        or ticket.get("state") != "issued"
        or ticket.get("task_id") != task_id
        or ticket.get("source_projection_id") != source_projection_id
        or ticket.get("expected_current_blob_sha")
        != expected_current_blob_sha
    ):
        raise IdentityError(
            "memory reconciliation ticket scope is invalid"
        )
    present_proposal_fields = proposal_binding_fields & set(ticket)
    if present_proposal_fields and present_proposal_fields != (
        proposal_binding_fields
    ):
        raise IdentityError(
            "memory reconciliation ticket proposal binding is incomplete"
        )
    if present_proposal_fields:
        validate_sha256(
            ticket.get("proposal_digest"),
            "memory reconciliation ticket proposal digest",
        )
        validate_identifier(
            ticket.get("transaction_id"),
            "memory reconciliation ticket transaction ID",
        )
        if not isinstance(ticket.get("proposal_bound_at"), str):
            raise IdentityError(
                "memory reconciliation ticket proposal binding time is invalid"
            )
    try:
        expires_at = dt.datetime.fromisoformat(
            str(ticket["expires_at"]).replace("Z", "+00:00")
        )
    except ValueError as exc:
        raise IdentityError(
            "memory reconciliation ticket expiry is invalid"
        ) from exc
    if expires_at <= dt.datetime.now(dt.timezone.utc):
        _finish_reconciliation_ticket(
            engine,
            path,
            ticket,
            state="invalidated",
        )
        raise IdentityError("memory reconciliation ticket expired")
    session_key = str(ticket["session_key"])
    session_path = _session_path(engine.data_dir, session_key)
    if not session_path.exists():
        raise IdentityError("memory reconciliation session is missing")
    session = load_json(session_path)
    if (
        not isinstance(session, dict)
        or session.get("schema_version") != SESSION_SCHEMA
        or session.get("task_id") != task_id
        or session.get("binding_id") != ticket.get("binding_id")
        or session.get("identity_kind") != ticket.get("identity_kind")
        or session.get("workspace_lineage_id")
        != ticket.get("workspace_lineage_id")
        or session.get("active_reconciliation_token_sha256")
        != token_sha256
    ):
        raise IdentityError(
            "memory reconciliation session identity changed"
        )
    base = session.get("base")
    manifest = session.get("base_manifest")
    projection_reference = (
        manifest.get("memory_projection")
        if isinstance(manifest, Mapping)
        else None
    )
    if (
        not isinstance(base, Mapping)
        or base.get("task_current_blob_sha")
        != expected_current_blob_sha
        or not isinstance(projection_reference, Mapping)
        or projection_reference.get("projection_id")
        != source_projection_id
    ):
        raise ConflictError(
            "memory reconciliation session baseline changed"
        )
    thread_id = os.environ.get("CODEX_THREAD_ID")
    if not isinstance(thread_id, str) or not thread_id:
        raise IdentityError(
            "memory reconciliation cannot locate the calling Codex task"
        )
    device = _device_state(engine.data_dir)
    if _session_key(device, thread_id) != session_key:
        raise IdentityError(
            "memory reconciliation token belongs to another Codex task"
        )
    prompt_path = _prompt_path(
        engine.data_dir,
        session_key,
        str(ticket["turn_key"]),
    )
    if not prompt_path.exists():
        raise IdentityError(
            "memory reconciliation ticket is outside its issuing turn"
        )
    return path, ticket, session


def _finish_reconciliation_ticket(
    engine: SyncEngine,
    path: Path,
    ticket: MutableMapping[str, Any],
    *,
    state: str,
) -> None:
    if state not in {"consumed", "invalidated"}:
        raise VerificationError(
            "memory reconciliation ticket final state is invalid"
        )
    if ticket.get("state") != "issued":
        raise IdentityError("memory reconciliation ticket was already used")
    ticket["state"] = state
    ticket[
        "consumed_at" if state == "consumed" else "invalidated_at"
    ] = utc_now()
    atomic_write_json(path, ticket)
    session_path = _session_path(
        engine.data_dir,
        str(ticket["session_key"]),
    )
    if session_path.exists():
        session = load_json(session_path)
        if (
            isinstance(session, dict)
            and session.get("active_reconciliation_token_sha256")
            == ticket.get("token_sha256")
        ):
            session.pop("active_reconciliation_token_sha256", None)
            if state == "invalidated":
                session["needs_remote_refresh"] = True
                session["pending_context_injection"] = True
            _save_session(
                engine.data_dir,
                str(ticket["session_key"]),
                session,
            )


def _reconciliation_ticket_proposal_identity(
    task_id: str,
    expected_current_blob_sha: str,
    proposal: Mapping[str, Any],
) -> tuple[str, str]:
    transaction_id, _snapshot_id, _projection_id, proposal_digest = (
        _reconciliation_identity(
            task_id,
            expected_current_blob_sha,
            proposal,
        )
    )
    return proposal_digest, transaction_id


def _assert_reconciliation_ticket_proposal(
    ticket: Mapping[str, Any],
    *,
    task_id: str,
    expected_current_blob_sha: str,
    proposal: Mapping[str, Any],
) -> None:
    proposal_digest, transaction_id = (
        _reconciliation_ticket_proposal_identity(
            task_id,
            expected_current_blob_sha,
            proposal,
        )
    )
    recorded_digest = ticket.get("proposal_digest")
    recorded_transaction = ticket.get("transaction_id")
    if (
        recorded_digest is not None
        and (
            recorded_digest != proposal_digest
            or recorded_transaction != transaction_id
        )
    ):
        raise IdentityError(
            "memory reconciliation ticket is already bound to a different "
            "typed patch"
        )


def _bind_reconciliation_ticket_proposal(
    engine: SyncEngine,
    ticket_record: tuple[
        Path,
        dict[str, Any],
        dict[str, Any],
    ] | None,
    *,
    task_id: str,
    expected_current_blob_sha: str,
    proposal: Mapping[str, Any],
) -> None:
    if ticket_record is None:
        return
    ticket = ticket_record[1]
    _assert_reconciliation_ticket_proposal(
        ticket,
        task_id=task_id,
        expected_current_blob_sha=expected_current_blob_sha,
        proposal=proposal,
    )
    if ticket.get("proposal_digest") is not None:
        return
    proposal_digest, transaction_id = (
        _reconciliation_ticket_proposal_identity(
            task_id,
            expected_current_blob_sha,
            proposal,
        )
    )
    ticket["proposal_digest"] = proposal_digest
    ticket["transaction_id"] = transaction_id
    ticket["proposal_bound_at"] = utc_now()
    atomic_write_json(ticket_record[0], ticket)


def _finish_existing_typed_reconciliation(
    engine: SyncEngine,
    remote: RemoteTaskState,
    existing: Mapping[str, Any],
    ticket_record: tuple[
        Path,
        dict[str, Any],
        dict[str, Any],
    ] | None,
) -> Mapping[str, Any]:
    relation = existing.get("relation")
    state = existing.get("state")
    if state == "published" and relation == "current":
        if (
            not isinstance(remote.memory_projection, Mapping)
            or remote.memory_projection.get("projection_id")
            != existing.get("projection_id")
        ):
            raise VerificationError(
                "already-published reconciliation projection is not CURRENT"
            )
        if ticket_record is not None:
            ticket = ticket_record[1]
            engine._refresh_session_after_publish(
                {
                    "session_key": ticket["session_key"],
                    "task_id": remote.current["task_id"],
                    "binding_id": ticket["binding_id"],
                },
                remote,
                pending_injection=False,
                remote_advance=False,
                invalidate_ticket=False,
            )
            _finish_reconciliation_ticket(
                engine,
                ticket_record[0],
                ticket,
                state="consumed",
            )
        status = "already_published"
    elif state == "published" and relation == "historical":
        if ticket_record is not None:
            _finish_reconciliation_ticket(
                engine,
                ticket_record[0],
                ticket_record[1],
                state="invalidated",
            )
        status = "published_then_advanced"
    elif state == "candidate" and relation == "candidate":
        if ticket_record is not None:
            _finish_reconciliation_ticket(
                engine,
                ticket_record[0],
                ticket_record[1],
                state="invalidated",
            )
        status = "candidate_remote_advance"
    else:
        raise VerificationError(
            "deterministic reconciliation recovery state is invalid"
        )
    return {
        "schema_version": "memory-vault-reconciliation-result/v1",
        "status": status,
        "task_id": remote.current["task_id"],
        "snapshot_id": existing["snapshot_id"],
        "projection_id": existing["projection_id"],
        "commit": existing["commit"],
        "current_blob_sha": remote.current_blob_sha,
    }


def _pending_reconciliation_signature(
    engine: SyncEngine,
    value: Mapping[str, Any],
) -> str:
    device = _device_state(engine.data_dir)
    return hmac.new(
        str(device["device_secret"]).encode("ascii"),
        jcs_json_bytes(value),
        hashlib.sha256,
    ).hexdigest()


RECONCILIATION_NEEDS_AUTHORIZATION_NEXT_STEP = (
    "Refresh and verify the exact parent history, then review and submit a "
    "newly authorized reconciliation. Preserved work in this queue is never "
    "published automatically."
)


def _reconciliation_needs_authorization_summary(
    data_dir: Path,
) -> Mapping[str, Any]:
    root = data_dir / "state" / "reconciliation-needs-authorization"
    paths = (
        sorted(
            path
            for path in root.glob("*.json")
            if path.is_file() and not path.name.endswith(".reason.json")
        )
        if root.exists()
        else []
    )
    return {
        "count": len(paths),
        "pending_ids": [path.stem for path in paths],
        "next_step": RECONCILIATION_NEEDS_AUTHORIZATION_NEXT_STEP,
    }


def _load_pending_reconciliation(
    engine: SyncEngine,
    path: Path,
) -> tuple[dict[str, Any], Mapping[str, Any], bool]:
    value = load_json(path)
    fields = {
        "schema_version",
        "pending_id",
        "task_id",
        "source_projection_id",
        "expected_current_blob_sha",
        "observed_current_blob_sha",
        "proposal_digest",
        "transaction_id",
        "proposal",
        "authorization",
        "created_at",
        "integrity_hmac_sha256",
    }
    if not isinstance(value, dict):
        raise IdentityError("pending reconciliation is invalid")
    _require_keys(
        value,
        required=fields,
        allowed=fields,
        label="pending reconciliation",
    )
    if value.get("schema_version") != (
        "memory-vault-reconciliation-pending/v2"
    ):
        raise IdentityError("pending reconciliation schema is invalid")
    signature = validate_sha256(
        value.get("integrity_hmac_sha256"),
        "pending reconciliation integrity signature",
    )
    unsigned = dict(value)
    unsigned.pop("integrity_hmac_sha256", None)
    if not hmac.compare_digest(
        signature,
        _pending_reconciliation_signature(engine, unsigned),
    ):
        raise IdentityError("pending reconciliation integrity check failed")
    task_id = validate_identifier(value.get("task_id"), "pending task_id")
    source_projection_id = validate_identifier(
        value.get("source_projection_id"),
        "pending source projection ID",
    )
    expected = validate_git_sha(
        value.get("expected_current_blob_sha"),
        "pending expected CURRENT blob",
    )
    observed = value.get("observed_current_blob_sha")
    if observed is not None:
        validate_git_sha(observed, "pending observed CURRENT blob")
    proposal_value = value.get("proposal")
    if not isinstance(proposal_value, Mapping):
        raise IdentityError("pending reconciliation proposal is invalid")
    proposal = _load_reconciliation_proposal_v2(proposal_value)
    if (
        proposal.get("task_id") != task_id
        or proposal.get("source_projection_id")
        != source_projection_id
    ):
        raise IdentityError(
            "pending reconciliation proposal identity changed"
        )
    proposal_digest, transaction_id = (
        _reconciliation_ticket_proposal_identity(
            task_id,
            expected,
            proposal,
        )
    )
    expected_pending_id = validate_identifier(
        f"reconcile-pending-{proposal_digest[:32]}",
        "pending reconciliation ID",
    )
    if (
        value.get("pending_id") != expected_pending_id
        or path.name != f"{expected_pending_id}.json"
        or value.get("proposal_digest") != proposal_digest
        or value.get("transaction_id") != transaction_id
    ):
        raise IdentityError(
            "pending reconciliation deterministic identity changed"
        )
    authorization = value.get("authorization")
    if authorization is None:
        return value, proposal, False
    authorization_fields = {
        "schema_version",
        "ticket_token_sha256",
        "session_key",
        "turn_id",
        "turn_key",
        "binding_id",
        "identity_kind",
        "workspace_lineage_id",
        "task_id",
        "source_projection_id",
        "expected_current_blob_sha",
        "proposal_digest",
        "transaction_id",
        "authorized_at",
        "ticket_expires_at",
    }
    authorization = _projection_object(
        authorization,
        authorization_fields,
        "pending durable authorization",
    )
    validate_sha256(
        authorization.get("ticket_token_sha256"),
        "pending ticket digest",
    )
    for key in (
        "session_key",
        "turn_id",
        "turn_key",
        "binding_id",
        "identity_kind",
    ):
        if not isinstance(authorization.get(key), str) or not str(
            authorization[key]
        ):
            raise IdentityError(
                f"pending durable authorization {key} is invalid"
            )
    if (
        authorization.get("schema_version")
        != "memory-vault-reconciliation-durable-authorization/v1"
        or authorization.get("task_id") != task_id
        or authorization.get("source_projection_id")
        != source_projection_id
        or authorization.get("expected_current_blob_sha") != expected
        or authorization.get("proposal_digest") != proposal_digest
        or authorization.get("transaction_id") != transaction_id
    ):
        raise IdentityError(
            "pending durable authorization scope changed"
        )
    try:
        authorized_at = dt.datetime.fromisoformat(
            str(authorization["authorized_at"]).replace("Z", "+00:00")
        )
        ticket_expires_at = dt.datetime.fromisoformat(
            str(authorization["ticket_expires_at"]).replace("Z", "+00:00")
        )
    except ValueError as exc:
        raise IdentityError(
            "pending durable authorization time is invalid"
        ) from exc
    if authorized_at > ticket_expires_at:
        raise IdentityError(
            "pending durable authorization postdates ticket expiry"
        )
    ticket_path = _reconciliation_ticket_path(
        engine.data_dir,
        str(authorization["ticket_token_sha256"]),
    )
    if not ticket_path.exists():
        return value, proposal, False
    ticket = load_json(ticket_path)
    ticket_pairs = {
        "token_sha256": "ticket_token_sha256",
        "session_key": "session_key",
        "turn_id": "turn_id",
        "turn_key": "turn_key",
        "binding_id": "binding_id",
        "identity_kind": "identity_kind",
        "workspace_lineage_id": "workspace_lineage_id",
        "task_id": "task_id",
        "source_projection_id": "source_projection_id",
        "expected_current_blob_sha": "expected_current_blob_sha",
        "proposal_digest": "proposal_digest",
        "transaction_id": "transaction_id",
        "proposal_bound_at": "authorized_at",
        "expires_at": "ticket_expires_at",
    }
    if (
        not isinstance(ticket, Mapping)
        or ticket.get("schema_version")
        != "memory-vault-reconciliation-ticket/v1"
        or ticket.get("state") not in {"issued", "invalidated"}
        or any(
            ticket.get(ticket_key) != authorization.get(auth_key)
            for ticket_key, auth_key in ticket_pairs.items()
        )
    ):
        return value, proposal, False
    return value, proposal, True


def _defer_pending_reconciliation_authorization(
    engine: SyncEngine,
    path: Path,
    *,
    reason: str,
) -> Mapping[str, Any]:
    pending, _proposal, authorized = _load_pending_reconciliation(
        engine,
        path,
    )
    if authorized or pending.get("authorization") is not None:
        raise IdentityError(
            "an authorized reconciliation cannot enter the authorization "
            "review queue"
        )
    pending_id = validate_identifier(
        pending.get("pending_id"),
        "pending reconciliation ID",
    )
    raw = path.read_bytes()
    review_root = (
        engine.data_dir
        / "state"
        / "reconciliation-needs-authorization"
    )
    ensure_private_dir(review_root)
    preserved_path = review_root / path.name
    if preserved_path.exists():
        if preserved_path.read_bytes() != raw:
            preserved_path = review_root / (
                f"{pending_id}-{sha256_bytes(raw)[:16]}.json"
            )
    if preserved_path.exists():
        if preserved_path.read_bytes() != raw:
            raise IdentityError(
                "authorization review path is occupied by different work"
            )
        with contextlib.suppress(FileNotFoundError):
            path.unlink()
    else:
        os.replace(path, preserved_path)
    review = {
        "schema_version": (
            "memory-vault-reconciliation-needs-authorization/v1"
        ),
        "pending_id": pending_id,
        "task_id": pending["task_id"],
        "source_projection_id": pending["source_projection_id"],
        "proposal_digest": pending["proposal_digest"],
        "transaction_id": pending["transaction_id"],
        "reason": reason,
        "content_preserved": True,
        "preserved_filename": preserved_path.name,
        "preserved_sha256": sha256_bytes(raw),
        "preserved_integrity_hmac_sha256": pending[
            "integrity_hmac_sha256"
        ],
        "next_step": RECONCILIATION_NEEDS_AUTHORIZATION_NEXT_STEP,
        "deferred_at": utc_now(),
    }
    review["integrity_hmac_sha256"] = (
        _pending_reconciliation_signature(engine, review)
    )
    atomic_write_json(
        review_root / f"{preserved_path.stem}.reason.json",
        review,
    )
    return {
        "schema_version": "memory-vault-reconciliation-recovery/v1",
        "status": "requires_new_authorization",
        "pending_id": pending_id,
        "reason": reason,
        "content_preserved": True,
        "preserved_sha256": review["preserved_sha256"],
        "remote_write_attempted": False,
        "needs_authorization": (
            _reconciliation_needs_authorization_summary(engine.data_dir)
        ),
    }


def _quarantine_pending_reconciliation(
    engine: SyncEngine,
    path: Path,
    *,
    reason: str,
) -> Mapping[str, Any]:
    pending_id = path.stem
    raw = path.read_bytes()
    quarantine_root = (
        engine.data_dir / "state" / "reconciliation-quarantine"
    )
    ensure_private_dir(quarantine_root)
    preserved_path = quarantine_root / path.name
    if preserved_path.exists():
        if preserved_path.read_bytes() != raw:
            preserved_path = quarantine_root / (
                f"{pending_id}-{sha256_bytes(raw)[:16]}.json"
            )
    if preserved_path.exists():
        if preserved_path.read_bytes() != raw:
            raise IdentityError(
                "pending reconciliation quarantine path is occupied"
            )
        with contextlib.suppress(FileNotFoundError):
            path.unlink()
    else:
        os.replace(path, preserved_path)
    quarantine = {
        "schema_version": "memory-vault-reconciliation-quarantine/v1",
        "pending_id": pending_id,
        "reason": reason,
        "content_preserved": True,
        "preserved_filename": preserved_path.name,
        "preserved_sha256": sha256_bytes(raw),
        "quarantined_at": utc_now(),
    }
    quarantine["integrity_hmac_sha256"] = (
        _pending_reconciliation_signature(engine, quarantine)
    )
    atomic_write_json(
        quarantine_root / f"{preserved_path.stem}.reason.json",
        quarantine,
    )
    return {
        "schema_version": "memory-vault-reconciliation-recovery/v1",
        "status": "quarantined",
        "pending_id": pending_id,
        "remote_write_attempted": False,
    }


def _terminalize_pending_reconciliation(
    engine: SyncEngine,
    path: Path,
    pending: Mapping[str, Any],
    result: Mapping[str, Any],
) -> Mapping[str, Any]:
    terminal = {
        "schema_version": "memory-vault-reconciliation-terminal/v1",
        "pending_id": pending["pending_id"],
        "task_id": pending["task_id"],
        "proposal_digest": pending["proposal_digest"],
        "transaction_id": pending["transaction_id"],
        "result": dict(result),
        "finished_at": utc_now(),
    }
    terminal["integrity_hmac_sha256"] = (
        _pending_reconciliation_signature(engine, terminal)
    )
    atomic_write_json(
        engine.data_dir
        / "state"
        / "reconciliation-terminal"
        / path.name,
        terminal,
    )
    with contextlib.suppress(FileNotFoundError):
        path.unlink()
    return {
        "schema_version": "memory-vault-reconciliation-recovery/v1",
        "status": str(result["status"]),
        "pending_id": pending["pending_id"],
        "task_id": pending["task_id"],
        "transaction_id": pending["transaction_id"],
        "terminal": True,
    }


def _refresh_pending_reconciliation_session(
    engine: SyncEngine,
    pending: Mapping[str, Any],
    remote: RemoteTaskState,
    result: Mapping[str, Any],
) -> None:
    authorization = pending.get("authorization")
    if not isinstance(authorization, Mapping):
        return
    status = str(result.get("status"))
    if status in {"published", "already_published"}:
        try:
            engine._refresh_session_after_publish(
                {
                    "session_key": authorization["session_key"],
                    "task_id": pending["task_id"],
                    "binding_id": authorization["binding_id"],
                },
                remote,
                pending_injection=True,
                remote_advance=False,
                invalidate_ticket=True,
            )
        except VaultSyncError:
            # The deterministic remote transaction is still terminal.  A
            # changed or missing local session must not make it replayable,
            # and its new identity is never guessed here.
            return
        return
    session_key = str(authorization["session_key"])
    session_path = _session_path(engine.data_dir, session_key)
    if not session_path.exists():
        return
    try:
        session = load_json(session_path)
        if (
            not isinstance(session, dict)
            or session.get("schema_version") != SESSION_SCHEMA
            or session.get("task_id") != pending.get("task_id")
            or session.get("binding_id")
            != authorization.get("binding_id")
        ):
            return
        _invalidate_session_reconciliation_ticket(
            engine.data_dir,
            session,
        )
        session["needs_remote_refresh"] = True
        session["pending_context_injection"] = True
        _save_session(engine.data_dir, session_key, session)
    except (VaultSyncError, OSError, ValueError):
        # The remote candidate/historical result is already deterministic and
        # terminal.  Corrupt local session state is isolated from remote
        # liveness and must never make that transaction replayable.
        return


def _recover_pending_reconciliations(
    engine: SyncEngine,
    *,
    session_key: str | None = None,
    already_locked: bool = False,
) -> Mapping[str, Any]:
    """Recover at most one signed, previously authorized typed transaction."""

    def execute() -> Mapping[str, Any]:
        deferred_ids: list[str] = []

        def report(value: Mapping[str, Any]) -> Mapping[str, Any]:
            result = dict(value)
            result["needs_authorization"] = (
                _reconciliation_needs_authorization_summary(engine.data_dir)
            )
            if deferred_ids:
                result["deferred_needs_authorization_ids"] = list(
                    deferred_ids
                )
            return result

        pending_root = (
            engine.data_dir / "state" / "reconciliation-pending"
        )
        if not pending_root.exists():
            needs_authorization = (
                _reconciliation_needs_authorization_summary(engine.data_dir)
            )
            return report({
                "schema_version": (
                    "memory-vault-reconciliation-recovery/v1"
                ),
                "status": (
                    "requires_new_authorization"
                    if needs_authorization["count"]
                    else "noop"
                ),
                "remote_write_attempted": False,
            })
        candidates = sorted(
            (
                path
                for path in pending_root.iterdir()
                if path.is_file() and path.suffix == ".json"
            ),
            key=lambda item: (item.stat().st_mtime_ns, item.name),
        )
        selected: tuple[
            Path,
            dict[str, Any],
            Mapping[str, Any],
            bool,
        ] | None = None
        for path in candidates:
            try:
                pending, proposal, authorized = (
                    _load_pending_reconciliation(engine, path)
                )
            except VaultSyncError as exc:
                return report(_quarantine_pending_reconciliation(
                    engine,
                    path,
                    reason=exc.code,
                ))
            if not authorized:
                try:
                    engine.git.ensure()
                    latest_unsigned = load_remote_task_by_id(
                        engine.git,
                        str(pending["task_id"]),
                    )
                except OfflineError:
                    return report({
                        "schema_version": (
                            "memory-vault-reconciliation-recovery/v1"
                        ),
                        "status": "retained_offline",
                        "pending_id": pending["pending_id"],
                        "remote_write_attempted": False,
                    })
                existing_unsigned = _existing_typed_reconciliation(
                    engine.git,
                    latest_unsigned,
                    str(pending["task_id"]),
                    str(pending["expected_current_blob_sha"]),
                    proposal,
                )
                if existing_unsigned is not None:
                    result_unsigned = (
                        _finish_existing_typed_reconciliation(
                            engine,
                            latest_unsigned,
                            existing_unsigned,
                            None,
                        )
                    )
                    return report(
                        _terminalize_pending_reconciliation(
                            engine,
                            path,
                            pending,
                            result_unsigned,
                        )
                    )
                deferred = _defer_pending_reconciliation_authorization(
                    engine,
                    path,
                    reason="missing_exact_bound_authorization",
                )
                deferred_ids.append(str(deferred["pending_id"]))
                continue
            authorization = pending.get("authorization")
            if (
                session_key is not None
                and (
                    not isinstance(authorization, Mapping)
                    or authorization.get("session_key") != session_key
                )
            ):
                continue
            selected = path, pending, proposal, authorized
            break
        if selected is None:
            needs_authorization = (
                _reconciliation_needs_authorization_summary(engine.data_dir)
            )
            return report({
                "schema_version": (
                    "memory-vault-reconciliation-recovery/v1"
                ),
                "status": (
                    "requires_new_authorization"
                    if needs_authorization["count"]
                    else "noop"
                ),
                "remote_write_attempted": False,
            })
        path, pending, proposal, authorized = selected
        task_id = str(pending["task_id"])
        expected = str(pending["expected_current_blob_sha"])
        try:
            engine.git.ensure()
            latest = load_remote_task_by_id(engine.git, task_id)
        except OfflineError:
            return report({
                "schema_version": (
                    "memory-vault-reconciliation-recovery/v1"
                ),
                "status": "retained_offline",
                "pending_id": pending["pending_id"],
                "remote_write_attempted": False,
            })
        existing = _existing_typed_reconciliation(
            engine.git,
            latest,
            task_id,
            expected,
            proposal,
        )
        if existing is not None:
            result = _finish_existing_typed_reconciliation(
                engine,
                latest,
                existing,
                None,
            )
            _refresh_pending_reconciliation_session(
                engine,
                pending,
                latest,
                result,
            )
            return report(_terminalize_pending_reconciliation(
                engine,
                path,
                pending,
                result,
            ))
        publish_allowed = (
            latest.current.get("state") in {"active", "paused"}
            and latest.task.get("status")
            not in {"archived", "split", "candidate"}
        )
        candidate = (
            latest.current_blob_sha != expected or not publish_allowed
        )
        try:
            base_state = (
                _historical_task_state_by_current_blob(
                    engine.git,
                    latest,
                    expected,
                )
                if candidate
                else latest
            )
            files, transaction_id, _snapshot_id = (
                _reconciliation_documents(
                    engine.git,
                    base_state,
                    proposal,
                    candidate=candidate,
                )
            )
            if transaction_id != pending["transaction_id"]:
                raise IdentityError(
                    "pending reconciliation transaction changed"
                )
            with engine.git.create_worktree() as worktree:
                engine.git.write_generated_files(worktree, files)
                engine._validate_worktree(worktree, files)
                engine.git.commit_and_push(
                    worktree,
                    files,
                    task_id,
                    transaction_id,
                )
        except (
            AuthenticationError,
            PrivacyError,
            VerificationError,
            IdentityError,
        ) as exc:
            return report(_quarantine_pending_reconciliation(
                engine,
                path,
                reason=exc.code,
            ))
        except VaultSyncError:
            try:
                engine.git.fetch()
                latest = load_remote_task_by_id(engine.git, task_id)
            except OfflineError:
                return report({
                    "schema_version": (
                        "memory-vault-reconciliation-recovery/v1"
                    ),
                    "status": "retained_push_verification",
                    "pending_id": pending["pending_id"],
                    "remote_write_attempted": True,
                })
            existing = _existing_typed_reconciliation(
                engine.git,
                latest,
                task_id,
                expected,
                proposal,
            )
            if existing is None:
                return report({
                    "schema_version": (
                        "memory-vault-reconciliation-recovery/v1"
                    ),
                    "status": "retained_retry",
                    "pending_id": pending["pending_id"],
                    "remote_write_attempted": True,
                })
            result = _finish_existing_typed_reconciliation(
                engine,
                latest,
                existing,
                None,
            )
            _refresh_pending_reconciliation_session(
                engine,
                pending,
                latest,
                result,
            )
            return report(_terminalize_pending_reconciliation(
                engine,
                path,
                pending,
                result,
            ))
        try:
            engine.git.fetch()
            latest = load_remote_task_by_id(engine.git, task_id)
        except OfflineError:
            return report({
                "schema_version": (
                    "memory-vault-reconciliation-recovery/v1"
                ),
                "status": "retained_push_verification",
                "pending_id": pending["pending_id"],
                "remote_write_attempted": True,
            })
        existing = _existing_typed_reconciliation(
            engine.git,
            latest,
            task_id,
            expected,
            proposal,
        )
        if existing is None:
            return report(_quarantine_pending_reconciliation(
                engine,
                path,
                reason="remote_verification",
            ))
        result = dict(
            _finish_existing_typed_reconciliation(
                engine,
                latest,
                existing,
                None,
            )
        )
        if result.get("status") == "already_published":
            result["status"] = "published"
        _refresh_pending_reconciliation_session(
            engine,
            pending,
            latest,
            result,
        )
        return report(_terminalize_pending_reconciliation(
            engine,
            path,
            pending,
            result,
        ))

    if already_locked:
        return execute()
    with FileLock(engine.lock_path):
        return execute()


def _publish_reconciliation_candidate_after_advance(
    engine: SyncEngine,
    *,
    proposal: Mapping[str, Any],
    task_id: str,
    expected_current_blob_sha: str,
    latest: RemoteTaskState,
    ticket_record: tuple[
        Path,
        dict[str, Any],
        dict[str, Any],
    ] | None,
) -> Mapping[str, Any]:
    """Persist a stale exact-parent patch as an immutable remote candidate."""

    base_state = _historical_task_state_by_current_blob(
        engine.git,
        latest,
        expected_current_blob_sha,
    )
    files, transaction_id, _snapshot_id = _reconciliation_documents(
        engine.git,
        base_state,
        proposal,
        candidate=True,
    )
    observed = latest
    for _attempt in range(3):
        existing = _existing_typed_reconciliation(
            engine.git,
            observed,
            task_id,
            expected_current_blob_sha,
            proposal,
        )
        if existing is not None:
            return _finish_existing_typed_reconciliation(
                engine,
                observed,
                existing,
                ticket_record,
            )
        try:
            with engine.git.create_worktree() as worktree:
                engine.git.write_generated_files(worktree, files)
                engine._validate_worktree(worktree, files)
                engine.git.commit_and_push(
                    worktree,
                    files,
                    task_id,
                    transaction_id,
                )
        except VaultSyncError as push_error:
            if isinstance(
                push_error,
                (
                    AuthenticationError,
                    PrivacyError,
                    VerificationError,
                    IdentityError,
                ),
            ):
                raise
            try:
                engine.git.fetch()
            except OfflineError:
                pending_id = _store_pending_reconciliation(
                    engine,
                    proposal,
                    expected_current_blob_sha=expected_current_blob_sha,
                    observed_current_blob_sha=observed.current_blob_sha,
                    ticket_record=ticket_record,
                )
                return {
                    "schema_version": (
                        "memory-vault-reconciliation-result/v1"
                    ),
                    "status": "pending_push_verification",
                    "task_id": task_id,
                    "pending_id": pending_id,
                    "expected_current_blob_sha": (
                        expected_current_blob_sha
                    ),
                    "observed_current_blob_sha": (
                        observed.current_blob_sha
                    ),
                }
            observed = load_remote_task_by_id(engine.git, task_id)
            existing = _existing_typed_reconciliation(
                engine.git,
                observed,
                task_id,
                expected_current_blob_sha,
                proposal,
            )
            if existing is not None:
                return _finish_existing_typed_reconciliation(
                    engine,
                    observed,
                    existing,
                    ticket_record,
                )
            continue
        try:
            engine.git.fetch()
        except OfflineError as fetch_error:
            return _recover_ambiguous_reconciliation_push(
                engine,
                proposal=proposal,
                task_id=task_id,
                expected_current_blob_sha=expected_current_blob_sha,
                push_error=fetch_error,
                ticket_record=ticket_record,
            )
        observed = load_remote_task_by_id(engine.git, task_id)
        existing = _existing_typed_reconciliation(
            engine.git,
            observed,
            task_id,
            expected_current_blob_sha,
            proposal,
        )
        if existing is None:
            raise VerificationError(
                "pushed reconciliation candidate is absent from remote"
            )
        return _finish_existing_typed_reconciliation(
            engine,
            observed,
            existing,
            ticket_record,
        )
    pending_id = _store_pending_reconciliation(
        engine,
        proposal,
        expected_current_blob_sha=expected_current_blob_sha,
        observed_current_blob_sha=observed.current_blob_sha,
        ticket_record=ticket_record,
    )
    return {
        "schema_version": "memory-vault-reconciliation-result/v1",
        "status": "pending_candidate_retry",
        "task_id": task_id,
        "pending_id": pending_id,
        "expected_current_blob_sha": expected_current_blob_sha,
        "observed_current_blob_sha": observed.current_blob_sha,
    }


def _recover_ambiguous_reconciliation_push(
    engine: SyncEngine,
    *,
    proposal: Mapping[str, Any],
    task_id: str,
    expected_current_blob_sha: str,
    push_error: VaultSyncError,
    ticket_record: tuple[
        Path,
        dict[str, Any],
        dict[str, Any],
    ] | None,
) -> Mapping[str, Any]:
    """Resolve a failed push response without duplicating an accepted write."""

    if isinstance(
        push_error,
        (
            AuthenticationError,
            PrivacyError,
            VerificationError,
            IdentityError,
        ),
    ):
        raise push_error
    try:
        engine.git.fetch()
    except OfflineError:
        pending_id = _store_pending_reconciliation(
            engine,
            proposal,
            expected_current_blob_sha=expected_current_blob_sha,
            observed_current_blob_sha=None,
            ticket_record=ticket_record,
        )
        # The remote acceptance result is unknown.  Keep the exact ticket
        # issued so the same task and turn can retry the deterministic patch.
        return {
            "schema_version": "memory-vault-reconciliation-result/v1",
            "status": "pending_push_verification",
            "task_id": task_id,
            "pending_id": pending_id,
            "expected_current_blob_sha": expected_current_blob_sha,
        }
    latest = load_remote_task_by_id(engine.git, task_id)
    existing = _existing_typed_reconciliation(
        engine.git,
        latest,
        task_id,
        expected_current_blob_sha,
        proposal,
    )
    if existing is not None:
        return _finish_existing_typed_reconciliation(
            engine,
            latest,
            existing,
            ticket_record,
        )
    if latest.current_blob_sha != expected_current_blob_sha:
        return _publish_reconciliation_candidate_after_advance(
            engine,
            proposal=proposal,
            task_id=task_id,
            expected_current_blob_sha=expected_current_blob_sha,
            latest=latest,
            ticket_record=ticket_record,
        )
    pending_id = _store_pending_reconciliation(
        engine,
        proposal,
        expected_current_blob_sha=expected_current_blob_sha,
        observed_current_blob_sha=latest.current_blob_sha,
        ticket_record=ticket_record,
    )
    if latest.current_blob_sha == expected_current_blob_sha:
        # Fetch proved that the write was not accepted and that the session
        # baseline is still exact.  Preserve the ticket for a byte-identical
        # retry.
        return {
            "schema_version": "memory-vault-reconciliation-result/v1",
            "status": "pending_push_race",
            "task_id": task_id,
            "pending_id": pending_id,
            "expected_current_blob_sha": expected_current_blob_sha,
            "observed_current_blob_sha": latest.current_blob_sha,
        }
    raise AssertionError("unreachable reconciliation recovery state")


def reconcile_memory_command(
    args: argparse.Namespace,
    engine: SyncEngine,
) -> Mapping[str, Any]:
    task_id = validate_identifier(args.task_id, "task_id")
    expected = validate_git_sha(
        args.expected_current_blob_sha,
        "expected CURRENT blob",
    )
    proposal = _load_reconciliation_proposal(args.proposal_file)
    if proposal.get("task_id") != task_id:
        raise VerificationError(
            "memory reconciliation proposal targets a different task"
        )
    with FileLock(engine.lock_path):
        ticket_record: tuple[
            Path,
            dict[str, Any],
            dict[str, Any],
        ] | None = None
        if (
            proposal.get("schema_version")
            == "memory-vault-reconciliation-patch/v2"
        ):
            session_token = getattr(args, "session_token", None)
            if not isinstance(session_token, str) or not session_token:
                raise IdentityError(
                    "typed memory reconciliation requires its one-time "
                    "session token"
                )
            ticket_record = _verified_reconciliation_ticket(
                engine,
                token=session_token,
                task_id=task_id,
                expected_current_blob_sha=expected,
                source_projection_id=str(
                    proposal["source_projection_id"]
                ),
            )
            _assert_reconciliation_ticket_proposal(
                ticket_record[1],
                task_id=task_id,
                expected_current_blob_sha=expected,
                proposal=proposal,
            )
        engine.git.ensure()
        remote = load_remote_task_by_id(engine.git, task_id)
        existing = _existing_typed_reconciliation(
            engine.git,
            remote,
            task_id,
            expected,
            proposal,
        )
        if existing is not None:
            _bind_reconciliation_ticket_proposal(
                engine,
                ticket_record,
                task_id=task_id,
                expected_current_blob_sha=expected,
                proposal=proposal,
            )
            return _finish_existing_typed_reconciliation(
                engine,
                remote,
                existing,
                ticket_record,
            )
        publish_allowed = (
            remote.current.get("state") in {"active", "paused"}
            and remote.task.get("status")
            not in {"archived", "split", "candidate"}
        )
        if (
            remote.current_blob_sha != expected
            or not publish_allowed
        ):
            try:
                base_state = _historical_task_state_by_current_blob(
                    engine.git,
                    remote,
                    expected,
                )
            except ConflictError:
                pending_id = _store_pending_reconciliation(
                    engine,
                    proposal,
                    expected_current_blob_sha=expected,
                    observed_current_blob_sha=remote.current_blob_sha,
                    ticket_record=ticket_record,
                )
                pending_path = (
                    engine.data_dir
                    / "state"
                    / "reconciliation-pending"
                    / f"{pending_id}.json"
                )
                deferred = (
                    _defer_pending_reconciliation_authorization(
                        engine,
                        pending_path,
                        reason="exact_parent_history_unavailable",
                    )
                )
                if ticket_record is not None:
                    _finish_reconciliation_ticket(
                        engine,
                        ticket_record[0],
                        ticket_record[1],
                        state="invalidated",
                    )
                return {
                    "schema_version": (
                        "memory-vault-reconciliation-result/v1"
                    ),
                    "status": "requires_new_authorization",
                    "task_id": task_id,
                    "pending_id": pending_id,
                    "expected_current_blob_sha": expected,
                    "observed_current_blob_sha": remote.current_blob_sha,
                    "reason": "exact_parent_history_unavailable",
                    "content_preserved": deferred["content_preserved"],
                    "preserved_sha256": deferred["preserved_sha256"],
                    "remote_write_attempted": False,
                    "needs_authorization": deferred[
                        "needs_authorization"
                    ],
                }
            files, transaction_id, snapshot_id = (
                _reconciliation_documents(
                    engine.git,
                    base_state,
                    proposal,
                    candidate=True,
                )
            )
            _bind_reconciliation_ticket_proposal(
                engine,
                ticket_record,
                task_id=task_id,
                expected_current_blob_sha=expected,
                proposal=proposal,
            )
            try:
                with engine.git.create_worktree() as worktree:
                    engine.git.write_generated_files(worktree, files)
                    engine._validate_worktree(worktree, files)
                    commit = engine.git.commit_and_push(
                        worktree,
                        files,
                        task_id,
                        transaction_id,
                    )
            except VaultSyncError as push_error:
                return _recover_ambiguous_reconciliation_push(
                    engine,
                    proposal=proposal,
                    task_id=task_id,
                    expected_current_blob_sha=expected,
                    push_error=push_error,
                    ticket_record=ticket_record,
                )
            try:
                engine.git.fetch()
            except OfflineError as fetch_error:
                return _recover_ambiguous_reconciliation_push(
                    engine,
                    proposal=proposal,
                    task_id=task_id,
                    expected_current_blob_sha=expected,
                    push_error=fetch_error,
                    ticket_record=ticket_record,
                )
            unchanged = load_remote_task_by_id(engine.git, task_id)
            existing = _existing_typed_reconciliation(
                engine.git,
                unchanged,
                task_id,
                expected,
                proposal,
            )
            if existing is None:
                raise VerificationError(
                    "pushed reconciliation candidate is absent from remote"
                )
            return _finish_existing_typed_reconciliation(
                engine,
                unchanged,
                existing,
                ticket_record,
            )
        files, transaction_id, snapshot_id = _reconciliation_documents(
            engine.git,
            remote,
            proposal,
        )
        _bind_reconciliation_ticket_proposal(
            engine,
            ticket_record,
            task_id=task_id,
            expected_current_blob_sha=expected,
            proposal=proposal,
        )
        try:
            with engine.git.create_worktree() as worktree:
                engine.git.write_generated_files(worktree, files)
                engine._validate_worktree(worktree, files)
                commit = engine.git.commit_and_push(
                    worktree,
                    files,
                    task_id,
                    transaction_id,
                )
        except VaultSyncError as push_error:
            return _recover_ambiguous_reconciliation_push(
                engine,
                proposal=proposal,
                task_id=task_id,
                expected_current_blob_sha=expected,
                push_error=push_error,
                ticket_record=ticket_record,
            )
        try:
            engine.git.fetch()
        except OfflineError as fetch_error:
            return _recover_ambiguous_reconciliation_push(
                engine,
                proposal=proposal,
                task_id=task_id,
                expected_current_blob_sha=expected,
                push_error=fetch_error,
                ticket_record=ticket_record,
            )
        verified = load_remote_task_by_id(engine.git, task_id)
        existing = _existing_typed_reconciliation(
            engine.git,
            verified,
            task_id,
            expected,
            proposal,
        )
        if existing is None:
            raise VerificationError(
                "pushed memory reconciliation is absent from remote"
            )
        result = dict(
            _finish_existing_typed_reconciliation(
                engine,
                verified,
                existing,
                ticket_record,
            )
        )
        if result.get("status") == "already_published":
            result["status"] = "published"
            result["commit"] = commit
        return result


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Private cross-device associative Memory Network"
    )
    parser.add_argument(
        "--data-dir",
        type=Path,
        help="override PLUGIN_DATA for diagnostics or isolated tests",
    )
    parser.add_argument("--version", action="version", version=VERSION)
    subparsers = parser.add_subparsers(dest="command", required=True)

    configure = subparsers.add_parser("configure")
    configure.add_argument("--repo-url")
    configure.add_argument("--branch")
    configure.add_argument("--expected-repository")
    configure.add_argument(
        "--control-privacy-verifier",
        choices=("github-private-v1", "gitlab-private-v1"),
    )
    configure.add_argument("--control-credential-host")
    configure.add_argument("--drive-root-folder-id")
    configure.add_argument("--drive-oauth-client-id")
    configure.add_argument("--allow-root", action="append")
    update_mode = configure.add_mutually_exclusive_group()
    update_mode.add_argument(
        "--auto-update",
        dest="auto_update",
        action="store_true",
    )
    update_mode.add_argument(
        "--disable-auto-update",
        dest="auto_update",
        action="store_false",
    )
    configure.set_defaults(auto_update=None)
    configure.add_argument(
        "--update-check-hours",
        type=int,
        choices=range(1, 169),
        metavar="1-168",
    )
    configure.add_argument("--codex-executable")
    configure.add_argument(
        "--artifact-mode", choices=("declared-only", "none")
    )
    configure.add_argument(
        "--max-stop-upload-bytes",
        type=int,
        help=(
            "upload at Stop only when pending artifact bytes are at or below "
            "this limit; larger artifacts wait for `flush`"
        ),
    )
    configure.add_argument(
        "--max-parallel-artifact-uploads",
        type=int,
        choices=range(1, MAX_PARALLEL_ARTIFACT_UPLOADS + 1),
        metavar=f"1-{MAX_PARALLEL_ARTIFACT_UPLOADS}",
        help=(
            "maximum distinct content-addressed artifact uploads in flight "
            "during one bounded flush"
        ),
    )
    configure.add_argument("--disable", action="store_true")

    configure_rclone = subparsers.add_parser(
        "configure-rclone-store",
        help=(
            "verify and activate an encrypted provider-neutral rclone "
            "object store"
        ),
    )
    configure_rclone.add_argument(
        "--rclone-executable",
        required=True,
    )
    configure_rclone.add_argument(
        "--rclone-config",
        required=True,
    )
    configure_rclone.add_argument(
        "--rclone-remote",
        required=True,
    )
    configure_rclone.add_argument(
        "--config-password-stdin",
        action="store_true",
        help="read the encrypted rclone config password from bounded stdin",
    )
    configure_rclone.add_argument(
        "--no-initialize-root",
        action="store_true",
        help="verify configuration without creating the encrypted root marker",
    )

    github_auth = subparsers.add_parser("auth-github")
    github_auth.add_argument("--username")
    control_auth = subparsers.add_parser("auth-control")
    control_auth.add_argument("--username")

    drive_auth = subparsers.add_parser("auth-drive")
    drive_auth.add_argument("--client-id")
    drive_auth.add_argument("--no-client-secret", action="store_true")

    rclone_auth = subparsers.add_parser("auth-rclone")
    rclone_auth.add_argument(
        "--config-password-stdin",
        action="store_true",
        help="read the encrypted rclone config password from bounded stdin",
    )
    subparsers.add_parser("init-object-store")
    configure_chunking = subparsers.add_parser(
        "configure-chunking",
        help=(
            "opt in or out of encrypted fixed-size delta chunks without "
            "deleting historical remote objects"
        ),
    )
    chunking_mode = configure_chunking.add_mutually_exclusive_group(
        required=True
    )
    chunking_mode.add_argument("--enable", action="store_true")
    chunking_mode.add_argument("--disable", action="store_true")
    configure_chunking.add_argument(
        "--minimum-bytes",
        type=int,
        help=(
            "minimum artifact size for new chunked uploads; must be at least "
            "one 16-MiB chunk"
        ),
    )

    subparsers.add_parser(
        "flush",
        help="publish queued memory episodes and receive remote additions",
    )
    recall = subparsers.add_parser(
        "recall",
        help="query the private local associative index without network access",
    )
    recall.add_argument(
        "--query-stdin",
        action="store_true",
        required=True,
        help="read a bounded private UTF-8 query from standard input",
    )
    recall.add_argument(
        "--limit",
        type=int,
        choices=range(1, memory_network.MAX_RECALL_LIMIT + 1),
        default=DEFAULT_MEMORY_RECALL_LIMIT,
    )
    views = subparsers.add_parser(
        "views",
        help=(
            "show bounded taskless claim timelines and current graph views "
            "without changing memory"
        ),
    )
    views.add_argument("--claim-key")
    views.add_argument(
        "--limit",
        type=int,
        choices=range(1, 257),
        default=256,
    )
    views.add_argument(
        "--no-proposals",
        action="store_true",
        help="omit non-mutating consolidation proposals",
    )
    pack_network = subparsers.add_parser(
        "pack-network",
        help="stream a verified network export into a bounded memory pack",
    )
    pack_network.add_argument("--output", type=Path, required=True)
    import_pack = subparsers.add_parser(
        "import-pack",
        help="verify and import a bounded memory pack",
    )
    import_pack.add_argument("--pack", type=Path, required=True)
    copy_pack = subparsers.add_parser(
        "copy-pack",
        help="resume a bounded memory-pack copy with a private journal",
    )
    copy_pack.add_argument("--pack", type=Path, required=True)
    copy_pack.add_argument("--output", type=Path, required=True)
    copy_pack.add_argument("--journal", type=Path, required=True)
    checkpoint_pack = subparsers.add_parser(
        "checkpoint-pack",
        help="write a hash checkpoint for a verified memory pack",
    )
    checkpoint_pack.add_argument("--pack", type=Path, required=True)
    checkpoint_pack.add_argument("--output", type=Path, required=True)
    checkpoint_pack.add_argument("--generation", type=int, required=True)
    checkpoint_pack.add_argument("--previous-checkpoint-sha256")
    verify_checkpoint = subparsers.add_parser(
        "verify-checkpoint",
        help="verify a taskless hash checkpoint",
    )
    verify_checkpoint.add_argument("--checkpoint", type=Path, required=True)
    verify_checkpoint.add_argument("--trusted-sha256")
    share_network = subparsers.add_parser(
        "share-network",
        help="select a closed taskless subgraph for an external crypto provider",
    )
    share_network.add_argument("--selector-stdin", action="store_true", required=True)
    share_network.add_argument("--output", type=Path, required=True)
    share_network.add_argument("--recipient-fingerprint", required=True)
    share_network.add_argument("--key-epoch", type=int, required=True)
    verify_share = subparsers.add_parser(
        "verify-share-envelope",
        help="verify opaque encrypted-share metadata without decrypting",
    )
    verify_share.add_argument("--envelope", type=Path, required=True)
    trust_init = subparsers.add_parser(
        "trust-init",
        help=(
            "bootstrap opaque local device-trust metadata; external keys "
            "and authority remain required for changes"
        ),
    )
    trust_init.add_argument("--state", type=Path)
    trust_init.add_argument("--installation-fingerprint", required=True)
    trust_init.add_argument("--device-fingerprint", required=True)
    trust_init.add_argument("--public-key-fingerprint", required=True)
    trust_init.add_argument("--key-epoch", type=int, default=1)
    trust_status = subparsers.add_parser(
        "trust-status",
        help="validate and summarize opaque local device-trust metadata",
    )
    trust_status.add_argument("--state", type=Path)
    export_network = subparsers.add_parser(
        "export-network",
        help="export the complete taskless memory graph as a verified bundle",
    )
    export_network.add_argument("--output", type=Path, required=True)
    import_network = subparsers.add_parser(
        "import-network",
        help="import only missing immutable memory nodes and edges",
    )
    import_network.add_argument("--bundle", type=Path, required=True)
    remember = subparsers.add_parser(
        "remember",
        help="append one AI-inferred semantic relation anchored to an episode",
    )
    remember.add_argument(
        "--proposal-stdin",
        action="store_true",
        required=True,
        help="read a bounded taskless semantic proposal from standard input",
    )
    subparsers.add_parser("status")
    diagnostics = subparsers.add_parser(
        "diagnostics",
        help="list bounded content-free private diagnostic metadata",
    )
    diagnostics.add_argument("--limit", type=int, default=10)
    configure_update_trust = subparsers.add_parser(
        "configure-update-trust",
        help=(
            "explicitly import one offline-verified signed-update root; "
            "this cannot overwrite existing trust"
        ),
    )
    configure_update_trust.add_argument(
        "--root-file",
        type=Path,
        required=True,
    )
    subparsers.add_parser(
        "update-trust-status",
        help="show whether signed metadata is required for plugin updates",
    )
    update = subparsers.add_parser("update")
    update.add_argument("--check-only", action="store_true")
    doctor = subparsers.add_parser("doctor")
    doctor.add_argument("--online", action="store_true")

    hook = subparsers.add_parser("hook")
    hook.add_argument(
        "event", choices=("session-start", "user-prompt-submit", "stop")
    )
    # Task ownership, binding, routing, projection and CURRENT commands are
    # intentionally absent. Legacy bytes are migration evidence, not a CLI.
    return parser


def _print_json(value: Any) -> None:
    payload = (
        json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        + "\n"
    ).encode("utf-8")
    sys.stdout.buffer.write(payload)
    sys.stdout.buffer.flush()


def _diagnostic_lock_path(data_dir: Path) -> Path:
    return data_dir / "locks" / "private-diagnostics.lock"


def _record_unexpected_diagnostic(
    data_dir: Path,
    *,
    operation: str,
) -> str | None:
    """Best-effort record of reviewed metadata, never exception content."""

    correlation_id = new_diagnostic_correlation_id()
    try:
        with FileLock(_diagnostic_lock_path(data_dir)):
            record_private_diagnostic(
                data_dir,
                correlation_id=correlation_id,
                occurred_at=utc_now(),
                operation=operation,
                runtime_version=VERSION,
                error_category="unexpected-internal",
            )
    except Exception:
        # Diagnostics must never turn an already safe generic hook response
        # into a traceback or a second lifecycle failure.
        return None
    return correlation_id


def diagnostics_command(
    data_dir: Path,
    *,
    limit: int,
) -> Mapping[str, Any]:
    try:
        with FileLock(_diagnostic_lock_path(data_dir)):
            return diagnostics_summary(data_dir, limit=limit)
    except DiagnosticError as exc:
        raise VerificationError("private diagnostic store is invalid") from exc


def _hook_dispatch(
    event: str,
    config: Mapping[str, Any] | None,
    data_dir: Path,
) -> int:
    hook_name = {
        "session-start": "SessionStart",
        "user-prompt-submit": "UserPromptSubmit",
        "stop": "Stop",
    }[event]
    update_result: Mapping[str, Any] | None = None
    try:
        if event == "session-start":
            _refresh_stable_runtime(data_dir)
        hook_input = read_hook_input()
        if config is None:
            _print_json(
                hook_json(
                    hook_name,
                    warning=(
                        "Private Memory Network is installed, but this client has "
                        "not completed its local setup or legacy-data migration."
                    ),
                )
            )
            return 0
        if (
            event == "session-start"
            and hook_input.get("source") in {"startup", "resume", "clear"}
        ):
            try:
                update_result = PluginUpdater(config, data_dir).check()
            except VaultSyncError:
                update_result = {
                    "schema_version": UPDATE_STATE_SCHEMA,
                    "status": "check_failed",
                    "running_version": VERSION,
                }
            except Exception:
                _record_unexpected_diagnostic(
                    data_dir,
                    operation="hook.session-start.update-check",
                )
                update_result = {
                    "schema_version": UPDATE_STATE_SCHEMA,
                    "status": "check_failed",
                    "running_version": VERSION,
                }
        engine = SyncEngine(config, data_dir)
        if event == "session-start":
            output = engine.session_start(hook_input)
        elif event == "user-prompt-submit":
            output = engine.user_prompt_submit(hook_input)
        else:
            output = engine.stop(hook_input)
    except VaultSyncError as exc:
        warning = (
            "Private Memory Network is temporarily unavailable; queued memory "
            "remains local and nothing was published."
            if exc.retryable
            else "Private Memory Network refused an unsafe or invalid memory packet."
        )
        output = hook_json(hook_name, warning=warning)
    except Exception:
        correlation_id = _record_unexpected_diagnostic(
            data_dir,
            operation=f"hook.{event}",
        )
        reference = (
            f" Diagnostic reference: {correlation_id}."
            if correlation_id is not None
            else ""
        )
        output = hook_json(
            hook_name,
            warning=(
                "Private Memory Network encountered an internal error; no "
                f"memory was published.{reference}"
            ),
        )
    output = _decorate_update_result(output, update_result)
    _print_json(output)
    return 0


def main(argv: Sequence[str] | None = None) -> int:
    args = build_parser().parse_args(argv)
    data_dir: Path | None = None
    try:
        data_dir = (
            args.data_dir.expanduser().resolve()
            if args.data_dir is not None
            else default_data_dir()
        )
        ensure_private_dir(data_dir)
        if args.data_dir is None:
            migrate_legacy_plugin_data(data_dir)
        config = load_config(data_dir)
    except (VaultSyncError, OSError, ValueError) as failure:
        exc = (
            failure
            if isinstance(failure, VaultSyncError)
            else ConfigurationError(
                "local plugin data could not be validated safely"
            )
        )
        if args.command == "hook":
            with contextlib.suppress(Exception):
                read_hook_input()
            hook_name = {
                "session-start": "SessionStart",
                "user-prompt-submit": "UserPromptSubmit",
                "stop": "Stop",
            }[args.event]
            _print_json(
                hook_json(
                    hook_name,
                    warning=(
                        "Private Memory Network found conflicting or incomplete "
                        "local upgrade data. It did not guess, merge, or publish."
                    ),
                )
            )
            return 0
        _print_json(
            {
                "schema_version": "memory-vault-sync-error/v1",
                "ok": False,
                "code": exc.code,
                "retryable": exc.retryable,
                "message": str(exc),
            }
        )
        return 2
    except Exception:
        if args.command != "hook":
            raise
        with contextlib.suppress(Exception):
            read_hook_input()
        hook_name = {
            "session-start": "SessionStart",
            "user-prompt-submit": "UserPromptSubmit",
            "stop": "Stop",
        }[args.event]
        if data_dir is None:
            with contextlib.suppress(Exception):
                data_dir = default_data_dir()
        correlation_id = (
            _record_unexpected_diagnostic(
                data_dir,
                operation=f"hook.{args.event}.setup",
            )
            if data_dir is not None
            else None
        )
        reference = (
            f" Diagnostic reference: {correlation_id}."
            if correlation_id is not None
            else ""
        )
        _print_json(
            hook_json(
                hook_name,
                warning=(
                    "Private Memory Network encountered an internal setup "
                    f"error; no memory was published.{reference}"
                ),
            )
        )
        return 0
    if data_dir is None:
        raise ConfigurationError("local plugin data directory is unavailable")
    if args.command == "hook":
        return _hook_dispatch(args.event, config, data_dir)
    try:
        if args.command == "configure":
            result = configure_command(args, data_dir)
        elif args.command == "configure-rclone-store":
            result = configure_rclone_store_command(args, data_dir)
        elif args.command == "diagnostics":
            result = diagnostics_command(
                data_dir,
                limit=args.limit,
            )
        elif args.command == "configure-update-trust":
            result = configure_update_trust_command(args, data_dir)
        elif args.command == "update-trust-status":
            result = update_trust_status_command(data_dir)
        else:
            if config is None:
                raise ConfigurationError("run configure first")
            engine = SyncEngine(config, data_dir)
            if args.command in {"auth-github", "auth-control"}:
                result = github_auth_command(args, config, data_dir)
            elif args.command == "auth-drive":
                result = drive_auth_command(args, config, data_dir)
            elif args.command == "auth-rclone":
                result = rclone_auth_command(args, config)
            elif args.command == "init-object-store":
                result = initialize_object_store_command(engine)
            elif args.command == "configure-chunking":
                result = configure_chunking_command(args, engine)
            elif args.command == "flush":
                with FileLock(engine.lock_path):
                    engine.git.ensure()
                    publication = engine._publish_memory_network_batch(
                        remote_ready=True
                    )
                    if publication.get("state") == "idle":
                        receive = engine._receive_memory_network()
                    else:
                        receive = publication.get("receive")
                result = {
                    "schema_version": "memory-network-flush/v1",
                    "publication": publication,
                    "receive": receive,
                }
            elif args.command == "recall":
                result = engine.recall_memory(
                    read_private_memory_query(),
                    limit=args.limit,
                )
            elif args.command == "views":
                result = engine.memory_network_views(
                    claim_key=args.claim_key,
                    limit=args.limit,
                    include_proposals=not args.no_proposals,
                )
            elif args.command == "pack-network":
                result = engine.pack_memory_network(args.output)
            elif args.command == "import-pack":
                result = engine.import_memory_pack(args.pack)
            elif args.command == "copy-pack":
                result = engine.copy_memory_pack(
                    args.pack,
                    args.output,
                    args.journal,
                )
            elif args.command == "checkpoint-pack":
                result = engine.checkpoint_memory_pack(
                    args.pack,
                    args.output,
                    generation=args.generation,
                    previous_checkpoint_sha256=args.previous_checkpoint_sha256,
                )
            elif args.command == "verify-checkpoint":
                result = engine.verify_network_checkpoint(
                    args.checkpoint,
                    trusted_checkpoint_sha256=args.trusted_sha256,
                )
            elif args.command == "share-network":
                result = engine.share_memory_network(
                    read_private_share_selector(),
                    args.output,
                    recipient_fingerprint=args.recipient_fingerprint,
                    key_epoch=args.key_epoch,
                )
            elif args.command == "verify-share-envelope":
                result = engine.verify_memory_share_envelope(args.envelope)
            elif args.command == "trust-init":
                result = engine.initialize_device_trust_state(
                    installation_fingerprint=args.installation_fingerprint,
                    device_fingerprint=args.device_fingerprint,
                    public_key_fingerprint=args.public_key_fingerprint,
                    key_epoch=args.key_epoch,
                    state_path=args.state,
                )
            elif args.command == "trust-status":
                result = engine.device_trust_status(args.state)
            elif args.command == "export-network":
                result = engine.export_memory_network(args.output)
            elif args.command == "import-network":
                result = engine.import_memory_network(args.bundle)
            elif args.command == "remember":
                result = engine.record_semantic_memory(
                    read_private_memory_proposal()
                )
            elif args.command == "status":
                result = engine.status()
            elif args.command == "update":
                result = PluginUpdater(config, data_dir).check(
                    force=True,
                    check_only=args.check_only,
                )
            elif args.command == "doctor":
                result = engine.doctor(online=args.online)
            else:
                raise ConfigurationError("unsupported command")
    except VaultSyncError as exc:
        _print_json(
            {
                "schema_version": "memory-vault-sync-error/v1",
                "ok": False,
                "code": exc.code,
                "retryable": exc.retryable,
                "message": str(exc),
            }
        )
        return 2
    _print_json(result)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
